CREATE OR REPLACE FUNCTION "analytics"."aggregate_daily_stats"("p_location_id" "uuid", "p_business_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'analytics'
    AS $$
DECLARE
    v_merchant_id UUID;
    v_peak_hour RECORD;
    v_slowest_hour RECORD;
    v_labor_stats RECORD;
    v_customer_stats RECORD;
    v_hourly_totals RECORD;
    v_top_items JSONB;
    v_top_categories JSONB;
BEGIN
    -- Get merchant_id
    SELECT merchant_id INTO v_merchant_id
    FROM public.locations WHERE id = p_location_id;
    
    IF v_merchant_id IS NULL THEN
        RAISE EXCEPTION 'Location not found: %', p_location_id;
    END IF;
    
    -- Find peak hour
    SELECT hour_of_day, gross_sales INTO v_peak_hour
    FROM analytics.location_hourly_stats
    WHERE location_id = p_location_id AND business_date = p_business_date
    ORDER BY gross_sales DESC
    LIMIT 1;
    
    -- Find slowest hour (with some sales)
    SELECT hour_of_day, gross_sales INTO v_slowest_hour
    FROM analytics.location_hourly_stats
    WHERE location_id = p_location_id 
      AND business_date = p_business_date
      AND gross_sales > 0
    ORDER BY gross_sales ASC
    LIMIT 1;
    
    -- Get labor stats from staff_shifts (actual clock in/out)
    SELECT 
        COALESCE(SUM(
            EXTRACT(EPOCH FROM (
                COALESCE(ss.clock_out_time, NOW()) - ss.clock_in_time
            )) / 3600
        ), 0) AS labor_hours,
        COALESCE(SUM(
            (EXTRACT(EPOCH FROM (
                COALESCE(ss.clock_out_time, NOW()) - ss.clock_in_time
            )) / 3600) * COALESCE(ss.hourly_rate_snapshot, 0)
        ), 0) AS labor_cost
    INTO v_labor_stats
    FROM public.staff_shifts ss
    WHERE ss.location_id = p_location_id
      AND ss.clock_in_time::DATE = p_business_date;
    
    -- Get customer stats
    SELECT 
        COUNT(DISTINCT o.customer_id)::INTEGER AS unique_customers,
        COUNT(DISTINCT o.customer_id) FILTER (
            WHERE c.created_at::DATE = p_business_date
        )::INTEGER AS new_customers
    INTO v_customer_stats
    FROM public.orders o
    LEFT JOIN public.customers c ON c.id = o.customer_id
    WHERE o.location_id = p_location_id
      AND o.created_at::DATE = p_business_date
      AND o.status = 'completed'
      AND o.customer_id IS NOT NULL;
    
    -- Sum up hourly totals
    SELECT 
        COALESCE(SUM(lhs.gross_sales), 0) AS gross_sales,
        COALESCE(SUM(lhs.net_sales), 0) AS net_sales,
        COALESCE(SUM(lhs.discounts_total), 0) AS discounts_total,
        COALESCE(SUM(lhs.tips_total), 0) AS tips_total,
        COALESCE(SUM(lhs.service_charges_total), 0) AS service_charges_total,
        COALESCE(SUM(lhs.tax_collected), 0) AS tax_collected,
        COALESCE(SUM(lhs.total_collected), 0) AS total_collected,
        COALESCE(SUM(lhs.order_count), 0)::INTEGER AS order_count,
        COALESCE(SUM(lhs.items_sold), 0)::INTEGER AS items_sold,
        COALESCE(SUM(lhs.void_count), 0)::INTEGER AS void_count,
        COALESCE(SUM(lhs.void_amount), 0) AS void_amount
    INTO v_hourly_totals
    FROM analytics.location_hourly_stats lhs
    WHERE lhs.location_id = p_location_id
      AND lhs.business_date = p_business_date;
    
    -- Get top 10 items
    SELECT COALESCE(jsonb_agg(item_data ORDER BY revenue DESC), '[]'::JSONB)
    INTO v_top_items
    FROM (
        SELECT jsonb_build_object(
            'item_id', oi.menu_item_id,
            'name', oi.item_name,
            'qty', SUM(oi.quantity),
            'revenue', SUM(oi.subtotal)
        ) AS item_data,
        SUM(oi.subtotal) AS revenue
        FROM public.order_items oi
        JOIN public.orders o ON o.id = oi.order_id
        WHERE o.location_id = p_location_id
          AND o.created_at::DATE = p_business_date
          AND o.status = 'completed'
          AND oi.is_voided = FALSE
          AND oi.menu_item_id IS NOT NULL
        GROUP BY oi.menu_item_id, oi.item_name
        ORDER BY SUM(oi.subtotal) DESC
        LIMIT 10
    ) top;
    
    -- Get top 5 categories
    SELECT COALESCE(jsonb_agg(cat_data ORDER BY revenue DESC), '[]'::JSONB)
    INTO v_top_categories
    FROM (
        SELECT jsonb_build_object(
            'category', oi.category_name,
            'qty', SUM(oi.quantity),
            'revenue', SUM(oi.subtotal)
        ) AS cat_data,
        SUM(oi.subtotal) AS revenue
        FROM public.order_items oi
        JOIN public.orders o ON o.id = oi.order_id
        WHERE o.location_id = p_location_id
          AND o.created_at::DATE = p_business_date
          AND o.status = 'completed'
          AND oi.is_voided = FALSE
          AND oi.category_name IS NOT NULL
        GROUP BY oi.category_name
        ORDER BY SUM(oi.subtotal) DESC
        LIMIT 5
    ) top;
    
    -- Get refunds total
    -- Note: Refunds come from order_payments.refunded_amount
    
    -- Upsert daily stats
    INSERT INTO analytics.location_daily_stats (
        merchant_id,
        location_id,
        business_date,
        day_of_week,
        gross_sales,
        net_sales,
        discounts_total,
        refunds_total,
        tips_total,
        service_charges_total,
        tax_collected,
        total_collected,
        order_count,
        avg_ticket,
        items_sold,
        void_count,
        void_amount,
        unique_customers,
        new_customers,
        returning_customers,
        labor_hours,
        labor_cost,
        sales_per_labor_hour,
        labor_cost_percentage,
        peak_hour,
        peak_hour_revenue,
        slowest_hour,
        slowest_hour_revenue,
        top_items,
        top_categories,
        payment_method_breakdown,
        order_type_breakdown
    )
    SELECT
        v_merchant_id,
        p_location_id,
        p_business_date,
        EXTRACT(DOW FROM p_business_date)::INTEGER,
        v_hourly_totals.gross_sales,
        v_hourly_totals.net_sales,
        v_hourly_totals.discounts_total,
        -- Get refunds from order_payments
        COALESCE((
            SELECT SUM(op.refunded_amount)
            FROM public.order_payments op
            JOIN public.orders o ON o.id = op.order_id
            WHERE o.location_id = p_location_id
              AND o.created_at::DATE = p_business_date
              AND op.refunded_amount > 0
        ), 0),
        v_hourly_totals.tips_total,
        v_hourly_totals.service_charges_total,
        v_hourly_totals.tax_collected,
        v_hourly_totals.total_collected,
        v_hourly_totals.order_count,
        CASE WHEN v_hourly_totals.order_count > 0 
             THEN v_hourly_totals.gross_sales / v_hourly_totals.order_count
             ELSE 0 
        END,
        v_hourly_totals.items_sold,
        v_hourly_totals.void_count,
        v_hourly_totals.void_amount,
        COALESCE(v_customer_stats.unique_customers, 0),
        COALESCE(v_customer_stats.new_customers, 0),
        COALESCE(v_customer_stats.unique_customers, 0) - COALESCE(v_customer_stats.new_customers, 0),
        ROUND(v_labor_stats.labor_hours::DECIMAL, 2),
        ROUND(v_labor_stats.labor_cost::DECIMAL, 2),
        CASE WHEN v_labor_stats.labor_hours > 0 
             THEN ROUND((v_hourly_totals.net_sales / v_labor_stats.labor_hours)::DECIMAL, 2)
             ELSE 0 
        END,
        CASE WHEN v_hourly_totals.net_sales > 0 
             THEN ROUND((v_labor_stats.labor_cost / v_hourly_totals.net_sales * 100)::DECIMAL, 2)
             ELSE 0 
        END,
        v_peak_hour.hour_of_day,
        COALESCE(v_peak_hour.gross_sales, 0),
        v_slowest_hour.hour_of_day,
        COALESCE(v_slowest_hour.gross_sales, 0),
        v_top_items,
        v_top_categories,
        -- Merge payment breakdowns from all hours
        COALESCE(
            (SELECT jsonb_object_agg(key, value) 
             FROM (
                SELECT key, jsonb_build_object(
                    'count', SUM((value->>'count')::INTEGER),
                    'amount', SUM((value->>'amount')::DECIMAL)
                ) AS value
                FROM analytics.location_hourly_stats lhs2,
                     jsonb_each(lhs2.payment_method_breakdown)
                WHERE lhs2.location_id = p_location_id 
                  AND lhs2.business_date = p_business_date
                GROUP BY key
             ) merged
            ), '{}'::JSONB
        ),
        -- Merge order type breakdowns
        COALESCE(
            (SELECT jsonb_object_agg(key, value)
             FROM (
                SELECT key, jsonb_build_object(
                    'count', SUM((value->>'count')::INTEGER),
                    'amount', SUM((value->>'amount')::DECIMAL)
                ) AS value
                FROM analytics.location_hourly_stats lhs3,
                     jsonb_each(lhs3.order_type_breakdown)
                WHERE lhs3.location_id = p_location_id 
                  AND lhs3.business_date = p_business_date
                GROUP BY key
             ) merged
            ), '{}'::JSONB
        )
    ON CONFLICT (location_id, business_date)
    DO UPDATE SET
        gross_sales = EXCLUDED.gross_sales,
        net_sales = EXCLUDED.net_sales,
        discounts_total = EXCLUDED.discounts_total,
        refunds_total = EXCLUDED.refunds_total,
        tips_total = EXCLUDED.tips_total,
        service_charges_total = EXCLUDED.service_charges_total,
        tax_collected = EXCLUDED.tax_collected,
        total_collected = EXCLUDED.total_collected,
        order_count = EXCLUDED.order_count,
        avg_ticket = EXCLUDED.avg_ticket,
        items_sold = EXCLUDED.items_sold,
        void_count = EXCLUDED.void_count,
        void_amount = EXCLUDED.void_amount,
        unique_customers = EXCLUDED.unique_customers,
        new_customers = EXCLUDED.new_customers,
        returning_customers = EXCLUDED.returning_customers,
        labor_hours = EXCLUDED.labor_hours,
        labor_cost = EXCLUDED.labor_cost,
        sales_per_labor_hour = EXCLUDED.sales_per_labor_hour,
        labor_cost_percentage = EXCLUDED.labor_cost_percentage,
        peak_hour = EXCLUDED.peak_hour,
        peak_hour_revenue = EXCLUDED.peak_hour_revenue,
        slowest_hour = EXCLUDED.slowest_hour,
        slowest_hour_revenue = EXCLUDED.slowest_hour_revenue,
        top_items = EXCLUDED.top_items,
        top_categories = EXCLUDED.top_categories,
        payment_method_breakdown = EXCLUDED.payment_method_breakdown,
        order_type_breakdown = EXCLUDED.order_type_breakdown,
        updated_at = NOW();
END;
$$;


ALTER FUNCTION "analytics"."aggregate_daily_stats"("p_location_id" "uuid", "p_business_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics"."aggregate_hourly_stats"("p_location_id" "uuid", "p_hour_start" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'analytics'
    AS $$
DECLARE
    v_merchant_id UUID;
    v_hour_end TIMESTAMPTZ;
    v_business_date DATE;
    v_stats RECORD;
    v_payment_breakdown JSONB;
    v_order_type_breakdown JSONB;
BEGIN
    -- Get merchant_id
    SELECT merchant_id INTO v_merchant_id
    FROM public.locations WHERE id = p_location_id;
    
    IF v_merchant_id IS NULL THEN
        RAISE EXCEPTION 'Location not found: %', p_location_id;
    END IF;
    
    v_hour_end := p_hour_start + INTERVAL '1 hour';
    v_business_date := p_hour_start::DATE;
    
    -- Get order stats for the hour
    SELECT 
        COALESCE(SUM(o.total_amount), 0) AS gross_sales,
        COALESCE(SUM(o.total_amount - o.discount_amount), 0) AS net_sales,
        COALESCE(SUM(o.discount_amount), 0) AS discounts_total,
        COALESCE(SUM(o.tip_amount), 0) AS tips_total,
        COALESCE(SUM(o.service_charge), 0) AS service_charges_total,
        COALESCE(SUM(o.tax_amount), 0) AS tax_collected,
        COALESCE(SUM(o.amount_paid), 0) AS total_collected,
        COUNT(*)::INTEGER AS order_count,
        COUNT(*) FILTER (WHERE o.voided_at IS NOT NULL OR o.status = 'void')::INTEGER AS void_count,
        COALESCE(SUM(o.total_amount) FILTER (WHERE o.voided_at IS NOT NULL OR o.status = 'void'), 0) AS void_amount
    INTO v_stats
    FROM public.orders o
    WHERE o.location_id = p_location_id
      AND o.created_at >= p_hour_start
      AND o.created_at < v_hour_end
      AND o.status = 'completed';
    
    -- Get payment method breakdown
    SELECT COALESCE(
        jsonb_object_agg(
            payment_method::TEXT,
            jsonb_build_object('count', pay_count, 'amount', pay_amount)
        ),
        '{}'::JSONB
    ) INTO v_payment_breakdown
    FROM (
        SELECT 
            op.payment_method,
            COUNT(*) AS pay_count,
            SUM(op.total_amount) AS pay_amount
        FROM public.order_payments op
        JOIN public.orders o ON o.id = op.order_id
        WHERE o.location_id = p_location_id
          AND o.created_at >= p_hour_start
          AND o.created_at < v_hour_end
          AND o.status = 'completed'
          AND op.status = 'captured'
          AND op.is_voided = FALSE
        GROUP BY op.payment_method
    ) pm;
    
    -- Get order type breakdown
    SELECT jsonb_build_object(
        'dine_in', jsonb_build_object(
            'count', COUNT(*) FILTER (WHERE o.order_type = 'dine_in'),
            'amount', COALESCE(SUM(o.total_amount) FILTER (WHERE o.order_type = 'dine_in'), 0)
        ),
        'takeout', jsonb_build_object(
            'count', COUNT(*) FILTER (WHERE o.order_type = 'takeout'),
            'amount', COALESCE(SUM(o.total_amount) FILTER (WHERE o.order_type = 'takeout'), 0)
        ),
        'delivery', jsonb_build_object(
            'count', COUNT(*) FILTER (WHERE o.order_type = 'delivery'),
            'amount', COALESCE(SUM(o.total_amount) FILTER (WHERE o.order_type = 'delivery'), 0)
        ),
        'online', jsonb_build_object(
            'count', COUNT(*) FILTER (WHERE o.order_type = 'online'),
            'amount', COALESCE(SUM(o.total_amount) FILTER (WHERE o.order_type = 'online'), 0)
        ),
        'catering', jsonb_build_object(
            'count', COUNT(*) FILTER (WHERE o.order_type = 'catering'),
            'amount', COALESCE(SUM(o.total_amount) FILTER (WHERE o.order_type = 'catering'), 0)
        )
    ) INTO v_order_type_breakdown
    FROM public.orders o
    WHERE o.location_id = p_location_id
      AND o.created_at >= p_hour_start
      AND o.created_at < v_hour_end
      AND o.status = 'completed';
    
    -- Upsert hourly stats
    INSERT INTO analytics.location_hourly_stats (
        merchant_id,
        location_id,
        hour_start,
        business_date,
        hour_of_day,
        day_of_week,
        gross_sales,
        net_sales,
        discounts_total,
        tips_total,
        service_charges_total,
        tax_collected,
        total_collected,
        order_count,
        avg_ticket,
        void_count,
        void_amount,
        payment_method_breakdown,
        order_type_breakdown
    ) VALUES (
        v_merchant_id,
        p_location_id,
        p_hour_start,
        v_business_date,
        EXTRACT(HOUR FROM p_hour_start)::INTEGER,
        EXTRACT(DOW FROM p_hour_start)::INTEGER,
        v_stats.gross_sales,
        v_stats.net_sales,
        v_stats.discounts_total,
        v_stats.tips_total,
        v_stats.service_charges_total,
        v_stats.tax_collected,
        v_stats.total_collected,
        v_stats.order_count,
        CASE WHEN v_stats.order_count > 0 
             THEN v_stats.gross_sales / v_stats.order_count 
             ELSE 0 
        END,
        v_stats.void_count,
        v_stats.void_amount,
        v_payment_breakdown,
        v_order_type_breakdown
    )
    ON CONFLICT (location_id, hour_start) 
    DO UPDATE SET
        gross_sales = EXCLUDED.gross_sales,
        net_sales = EXCLUDED.net_sales,
        discounts_total = EXCLUDED.discounts_total,
        tips_total = EXCLUDED.tips_total,
        service_charges_total = EXCLUDED.service_charges_total,
        tax_collected = EXCLUDED.tax_collected,
        total_collected = EXCLUDED.total_collected,
        order_count = EXCLUDED.order_count,
        avg_ticket = EXCLUDED.avg_ticket,
        void_count = EXCLUDED.void_count,
        void_amount = EXCLUDED.void_amount,
        payment_method_breakdown = EXCLUDED.payment_method_breakdown,
        order_type_breakdown = EXCLUDED.order_type_breakdown,
        updated_at = NOW();
        
    -- Also update items_sold from order_items
    UPDATE analytics.location_hourly_stats lhs
    SET items_sold = (
        SELECT COALESCE(SUM(oi.quantity), 0)::INTEGER
        FROM public.order_items oi
        JOIN public.orders o ON o.id = oi.order_id
        WHERE o.location_id = p_location_id
          AND o.created_at >= p_hour_start
          AND o.created_at < v_hour_end
          AND o.status = 'completed'
          AND oi.is_voided = FALSE
    )
    WHERE lhs.location_id = p_location_id AND lhs.hour_start = p_hour_start;
END;
$$;


ALTER FUNCTION "analytics"."aggregate_hourly_stats"("p_location_id" "uuid", "p_hour_start" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics"."backfill_stats"("p_merchant_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("location_id" "uuid", "days_processed" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'analytics'
    AS $$
DECLARE
    v_location RECORD;
    v_current_date DATE;
    v_current_hour TIMESTAMPTZ;
    v_days_processed INTEGER;
BEGIN
    FOR v_location IN 
        SELECT id FROM public.locations WHERE merchant_id = p_merchant_id AND is_active = TRUE
    LOOP
        v_days_processed := 0;
        v_current_date := p_start_date;
        
        WHILE v_current_date <= p_end_date LOOP
            -- Process each hour of the day
            FOR h IN 0..23 LOOP
                v_current_hour := v_current_date + (h || ' hours')::INTERVAL;
                PERFORM analytics.aggregate_hourly_stats(v_location.id, v_current_hour);
            END LOOP;
            
            -- Aggregate daily
            PERFORM analytics.aggregate_daily_stats(v_location.id, v_current_date);
            
            v_days_processed := v_days_processed + 1;
            v_current_date := v_current_date + 1;
        END LOOP;
        
        location_id := v_location.id;
        days_processed := v_days_processed;
        RETURN NEXT;
    END LOOP;
END;
$$;


ALTER FUNCTION "analytics"."backfill_stats"("p_merchant_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics"."get_comparison_summary"("p_merchant_id" "uuid", "p_location_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("location_id" "uuid", "location_name" "text", "total_gross_sales" numeric, "total_net_sales" numeric, "total_orders" integer, "avg_daily_sales" numeric, "avg_ticket" numeric, "total_tips" numeric, "labor_cost_pct" numeric, "best_day" "date", "best_day_sales" numeric, "worst_day" "date", "worst_day_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'analytics'
    AS $$
BEGIN
    RETURN QUERY
    WITH aggregated AS (
        SELECT 
            lds.location_id,
            l.name AS location_name,
            SUM(lds.gross_sales) AS total_gross_sales,
            SUM(lds.net_sales) AS total_net_sales,
            SUM(lds.order_count) AS total_orders,
            AVG(lds.gross_sales) AS avg_daily_sales,
            CASE WHEN SUM(lds.order_count) > 0 
                 THEN SUM(lds.gross_sales) / SUM(lds.order_count)
                 ELSE 0 
            END AS avg_ticket,
            SUM(lds.tips_total) AS total_tips,
            CASE WHEN SUM(lds.net_sales) > 0
                 THEN SUM(lds.labor_cost) / SUM(lds.net_sales) * 100
                 ELSE 0
            END AS labor_cost_pct
        FROM analytics.location_daily_stats lds
        JOIN public.locations l ON l.id = lds.location_id
        WHERE lds.merchant_id = p_merchant_id
          AND lds.location_id = ANY(p_location_ids)
          AND lds.business_date BETWEEN p_start_date AND p_end_date
        GROUP BY lds.location_id, l.name
    ),
    best_days AS (
        SELECT DISTINCT ON (lds.location_id)
            lds.location_id,
            lds.business_date AS best_day,
            lds.gross_sales AS best_day_sales
        FROM analytics.location_daily_stats lds
        WHERE lds.merchant_id = p_merchant_id
          AND lds.location_id = ANY(p_location_ids)
          AND lds.business_date BETWEEN p_start_date AND p_end_date
        ORDER BY lds.location_id, lds.gross_sales DESC
    ),
    worst_days AS (
        SELECT DISTINCT ON (lds.location_id)
            lds.location_id,
            lds.business_date AS worst_day,
            lds.gross_sales AS worst_day_sales
        FROM analytics.location_daily_stats lds
        WHERE lds.merchant_id = p_merchant_id
          AND lds.location_id = ANY(p_location_ids)
          AND lds.business_date BETWEEN p_start_date AND p_end_date
          AND lds.gross_sales > 0 -- Exclude days with no sales
        ORDER BY lds.location_id, lds.gross_sales ASC
    )
    SELECT 
        a.location_id,
        a.location_name::TEXT,
        a.total_gross_sales,
        a.total_net_sales,
        a.total_orders::INTEGER,
        ROUND(a.avg_daily_sales::DECIMAL, 2),
        ROUND(a.avg_ticket::DECIMAL, 2),
        a.total_tips,
        ROUND(a.labor_cost_pct::DECIMAL, 2),
        bd.best_day,
        bd.best_day_sales,
        wd.worst_day,
        wd.worst_day_sales
    FROM aggregated a
    LEFT JOIN best_days bd ON bd.location_id = a.location_id
    LEFT JOIN worst_days wd ON wd.location_id = a.location_id
    ORDER BY a.total_gross_sales DESC;
END;
$$;


ALTER FUNCTION "analytics"."get_comparison_summary"("p_merchant_id" "uuid", "p_location_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics"."get_daypart_comparison"("p_merchant_id" "uuid", "p_location_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date") RETURNS TABLE("location_id" "uuid", "location_name" "text", "daypart" "text", "total_sales" numeric, "order_count" integer, "pct_of_daily_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'analytics'
    AS $$
BEGIN
    RETURN QUERY
    WITH hourly_data AS (
        SELECT 
            lhs.location_id,
            l.name AS location_name,
            CASE 
                WHEN lhs.hour_of_day BETWEEN 5 AND 10 THEN 'breakfast'
                WHEN lhs.hour_of_day BETWEEN 11 AND 14 THEN 'lunch'
                WHEN lhs.hour_of_day BETWEEN 15 AND 17 THEN 'afternoon'
                WHEN lhs.hour_of_day BETWEEN 18 AND 21 THEN 'dinner'
                ELSE 'late_night'
            END AS daypart,
            lhs.gross_sales,
            lhs.order_count
        FROM analytics.location_hourly_stats lhs
        JOIN public.locations l ON l.id = lhs.location_id
        WHERE lhs.merchant_id = p_merchant_id
          AND lhs.location_id = ANY(p_location_ids)
          AND lhs.business_date BETWEEN p_start_date AND p_end_date
    ),
    location_totals AS (
        SELECT 
            hd.location_id,
            SUM(hd.gross_sales) AS total_location_sales
        FROM hourly_data hd
        GROUP BY hd.location_id
    )
    SELECT 
        hd.location_id,
        hd.location_name::TEXT,
        hd.daypart,
        SUM(hd.gross_sales) AS total_sales,
        SUM(hd.order_count)::INTEGER AS order_count,
        CASE WHEN lt.total_location_sales > 0
             THEN ROUND((SUM(hd.gross_sales) / lt.total_location_sales * 100)::DECIMAL, 1)
             ELSE 0
        END AS pct_of_daily_sales
    FROM hourly_data hd
    JOIN location_totals lt ON lt.location_id = hd.location_id
    GROUP BY hd.location_id, hd.location_name, hd.daypart, lt.total_location_sales
    ORDER BY hd.location_name, hd.daypart;
END;
$$;


ALTER FUNCTION "analytics"."get_daypart_comparison"("p_merchant_id" "uuid", "p_location_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics"."get_hourly_comparison"("p_merchant_id" "uuid", "p_location_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS TABLE("location_id" "uuid", "location_name" "text", "business_date" "date", "hour_of_day" integer, "gross_sales" numeric, "order_count" integer, "avg_ticket" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'analytics'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        lhs.location_id,
        l.name::TEXT AS location_name,
        lhs.business_date,
        lhs.hour_of_day,
        lhs.gross_sales,
        lhs.order_count,
        lhs.avg_ticket
    FROM analytics.location_hourly_stats lhs
    JOIN public.locations l ON l.id = lhs.location_id
    WHERE lhs.merchant_id = p_merchant_id
      AND lhs.location_id = ANY(p_location_ids)
      AND lhs.business_date BETWEEN p_start_date AND COALESCE(p_end_date, p_start_date)
    ORDER BY lhs.business_date, lhs.hour_of_day, l.name;
END;
$$;


ALTER FUNCTION "analytics"."get_hourly_comparison"("p_merchant_id" "uuid", "p_location_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics"."get_location_comparison"("p_merchant_id" "uuid", "p_location_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date", "p_metrics" "text"[] DEFAULT ARRAY['gross_sales'::"text", 'net_sales'::"text", 'order_count'::"text", 'avg_ticket'::"text"]) RETURNS TABLE("location_id" "uuid", "location_name" "text", "business_date" "date", "gross_sales" numeric, "net_sales" numeric, "order_count" integer, "avg_ticket" numeric, "tips_total" numeric, "discounts_total" numeric, "labor_cost_percentage" numeric, "items_sold" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'analytics'
    AS $$
BEGIN
    -- Validate merchant owns these locations
    IF EXISTS (
        SELECT 1 FROM unnest(p_location_ids) AS lid
        WHERE NOT EXISTS (
            SELECT 1 FROM public.locations l 
            WHERE l.id = lid AND l.merchant_id = p_merchant_id
        )
    ) THEN
        RAISE EXCEPTION 'Invalid location_id for this merchant';
    END IF;

    RETURN QUERY
    SELECT 
        lds.location_id,
        l.name::TEXT AS location_name,
        lds.business_date,
        lds.gross_sales,
        lds.net_sales,
        lds.order_count,
        lds.avg_ticket,
        lds.tips_total,
        lds.discounts_total,
        lds.labor_cost_percentage,
        lds.items_sold
    FROM analytics.location_daily_stats lds
    JOIN public.locations l ON l.id = lds.location_id
    WHERE lds.merchant_id = p_merchant_id
      AND lds.location_id = ANY(p_location_ids)
      AND lds.business_date BETWEEN p_start_date AND p_end_date
    ORDER BY lds.business_date, l.name;
END;
$$;


ALTER FUNCTION "analytics"."get_location_comparison"("p_merchant_id" "uuid", "p_location_ids" "uuid"[], "p_start_date" "date", "p_end_date" "date", "p_metrics" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics"."get_location_rankings"("p_merchant_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_metric" "text" DEFAULT 'gross_sales'::"text", "p_limit" integer DEFAULT 10) RETURNS TABLE("rank" integer, "location_id" "uuid", "location_name" "text", "metric_value" numeric, "metric_vs_avg_pct" numeric, "trend_pct" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'analytics'
    AS $$
DECLARE
    v_period_days INTEGER;
    v_prev_start DATE;
    v_prev_end DATE;
    v_avg_value DECIMAL;
BEGIN
    -- Calculate previous period for trend
    v_period_days := p_end_date - p_start_date + 1;
    v_prev_end := p_start_date - 1;
    v_prev_start := v_prev_end - v_period_days + 1;
    
    -- Calculate merchant average
    SELECT AVG(
        CASE p_metric
            WHEN 'gross_sales' THEN lds.gross_sales
            WHEN 'net_sales' THEN lds.net_sales
            WHEN 'order_count' THEN lds.order_count::DECIMAL
            WHEN 'avg_ticket' THEN lds.avg_ticket
            WHEN 'labor_cost_percentage' THEN lds.labor_cost_percentage
            ELSE lds.gross_sales
        END
    ) INTO v_avg_value
    FROM analytics.location_daily_stats lds
    WHERE lds.merchant_id = p_merchant_id
      AND lds.business_date BETWEEN p_start_date AND p_end_date;

    RETURN QUERY
    WITH current_period AS (
        SELECT 
            lds.location_id,
            l.name AS location_name,
            SUM(
                CASE p_metric
                    WHEN 'gross_sales' THEN lds.gross_sales
                    WHEN 'net_sales' THEN lds.net_sales
                    WHEN 'order_count' THEN lds.order_count::DECIMAL
                    WHEN 'avg_ticket' THEN lds.avg_ticket
                    WHEN 'labor_cost_percentage' THEN lds.labor_cost_percentage
                    ELSE lds.gross_sales
                END
            ) AS metric_value
        FROM analytics.location_daily_stats lds
        JOIN public.locations l ON l.id = lds.location_id
        WHERE lds.merchant_id = p_merchant_id
          AND lds.business_date BETWEEN p_start_date AND p_end_date
        GROUP BY lds.location_id, l.name
    ),
    previous_period AS (
        SELECT 
            lds.location_id,
            SUM(
                CASE p_metric
                    WHEN 'gross_sales' THEN lds.gross_sales
                    WHEN 'net_sales' THEN lds.net_sales
                    WHEN 'order_count' THEN lds.order_count::DECIMAL
                    WHEN 'avg_ticket' THEN lds.avg_ticket
                    WHEN 'labor_cost_percentage' THEN lds.labor_cost_percentage
                    ELSE lds.gross_sales
                END
            ) AS prev_value
        FROM analytics.location_daily_stats lds
        WHERE lds.merchant_id = p_merchant_id
          AND lds.business_date BETWEEN v_prev_start AND v_prev_end
        GROUP BY lds.location_id
    )
    SELECT 
        ROW_NUMBER() OVER (ORDER BY cp.metric_value DESC)::INTEGER AS rank,
        cp.location_id,
        cp.location_name::TEXT,
        cp.metric_value,
        CASE WHEN v_avg_value > 0 
             THEN ROUND(((cp.metric_value - v_avg_value) / v_avg_value * 100)::DECIMAL, 1)
             ELSE 0 
        END AS metric_vs_avg_pct,
        CASE WHEN pp.prev_value > 0 
             THEN ROUND(((cp.metric_value - pp.prev_value) / pp.prev_value * 100)::DECIMAL, 1)
             ELSE 0 
        END AS trend_pct
    FROM current_period cp
    LEFT JOIN previous_period pp ON pp.location_id = cp.location_id
    ORDER BY cp.metric_value DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION "analytics"."get_location_rankings"("p_merchant_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_metric" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "analytics"."trigger_update_hourly_stats"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Only process completed orders
    IF NEW.status = 'completed' AND 
       (OLD IS NULL OR OLD.status != 'completed') THEN
        PERFORM analytics.aggregate_hourly_stats(
            NEW.location_id,
            date_trunc('hour', NEW.created_at)
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "analytics"."trigger_update_hourly_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_online_order"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order       RECORD;
  v_now         TIMESTAMPTZ := NOW();
BEGIN
  -- Lock the row to prevent race conditions
  SELECT id, status, location_id, merchant_id
    INTO v_order
    FROM public.orders
   WHERE id = p_order_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.status <> 'pending' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error',   'Order is not in pending status (current: ' || v_order.status || ')'
    );
  END IF;

  -- Transition: pending → accepted → sent_to_kitchen
  UPDATE public.orders
     SET status              = 'accepted',
         accepted_at         = v_now,
         sent_to_kitchen_at  = v_now,
         updated_at          = v_now
   WHERE id = p_order_id;

  -- Fire all items to kitchen
  UPDATE public.order_items
     SET kitchen_status     = 'sent',
         sent_to_kitchen_at = v_now
   WHERE order_id = p_order_id
     AND (kitchen_status IS NULL OR kitchen_status = 'pending');

  -- Audit trail
  INSERT INTO public.order_status_history
    (order_id, from_status, to_status, changed_at, notes)
  VALUES
    (p_order_id, 'pending', 'accepted', v_now, 'Accepted by merchant');

  RETURN jsonb_build_object(
    'success',    true,
    'order_id',   p_order_id,
    'accepted_at', v_now
  );
END;
$$;


ALTER FUNCTION "public"."accept_online_order"("p_order_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_online_order"("p_order_id" "uuid") IS 'Merchant accepts a pending online order. Transitions to accepted and fires to kitchen.';



CREATE OR REPLACE FUNCTION "public"."add_category_to_menu"("p_menu_id" "uuid", "p_category_id" "uuid", "p_display_order" integer DEFAULT 0, "p_custom_title" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    INSERT INTO menu_categories (
        menu_id, category_id, display_order, 
        custom_title, is_active,
        created_at, updated_at
    ) VALUES (
        p_menu_id, p_category_id, p_display_order,
        p_custom_title, true,
        NOW(), NOW()
    )
    ON CONFLICT (menu_id, category_id) 
    DO UPDATE SET
        display_order = EXCLUDED.display_order,
        custom_title = COALESCE(EXCLUDED.custom_title, menu_categories.custom_title),
        is_active = true,
        updated_at = NOW();
    
    RETURN json_build_object(
        'success', true,
        'menu_id', p_menu_id,
        'category_id', p_category_id
    );
END;
$$;


