CREATE OR REPLACE FUNCTION "public"."add_open_item_v2"("p_order_id" "uuid", "p_item_name" "text", "p_unit_price" numeric, "p_quantity" integer DEFAULT 1, "p_special_instructions" "text" DEFAULT NULL::"text", "p_is_tax_exempt" boolean DEFAULT false, "p_seat_number" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_location_id uuid;
    v_merchant_id uuid;
    v_tax_rate numeric := 8.0;
    v_item_id uuid;
    
    -- Pricing calculations
    v_cash_price numeric;
    v_subtotal numeric;
    v_cash_subtotal numeric;
    v_tax_amount numeric;
    v_cash_tax_amount numeric;
    
    v_cash_discount_rate numeric := 0.04;
BEGIN
    -- ============================================
    -- 1. Validate & Get Order Context
    -- ============================================
    SELECT o.location_id, o.merchant_id 
    INTO v_location_id, v_merchant_id
    FROM public.orders o
    WHERE o.id = p_order_id
      AND o.status NOT IN ('completed', 'cancelled', 'void')
      AND o.merchant_id = user_merchant_id()
      AND o.location_id = ANY(user_location_ids())
    FOR UPDATE;
    
    IF v_location_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or access denied: %', p_order_id;
    END IF;
    
    -- ============================================
    -- 2. Get Tax Rate (unless exempt)
    -- ============================================
    IF NOT p_is_tax_exempt THEN
        SELECT COALESCE(tr.percentage, 8.0)
        INTO v_tax_rate
        FROM public.tax_rates tr
        WHERE tr.location_id = v_location_id 
          AND tr.tax_category = 'standard' 
          AND tr.is_active = true
        LIMIT 1;
        
        v_tax_rate := COALESCE(v_tax_rate, 8.0);
    ELSE
        v_tax_rate := 0;
    END IF;
    
    -- ============================================
    -- 3. Calculate Pricing (simplified - no modifiers/sizes)
    -- ============================================
    -- Cash price = card price * (1 - cash_discount_rate)
    v_cash_price := p_unit_price * (1 - v_cash_discount_rate);
    
    -- Subtotals
    v_subtotal := p_unit_price * p_quantity;
    v_cash_subtotal := v_cash_price * p_quantity;
    
    -- Tax
    v_tax_amount := ROUND(v_subtotal * v_tax_rate / 100, 2);
    v_cash_tax_amount := ROUND(v_cash_subtotal * v_tax_rate / 100, 2);
    
    -- ============================================
    -- 4. Insert Order Item
    -- ============================================
    INSERT INTO public.order_items (
        order_id,
        
        -- Open item flags
        is_open_item,
        open_item_name,
        open_item_price,
        
        -- Standard fields (for compatibility)
        menu_item_id,
        item_name,
        category_name,
        quantity,
        
        -- Card pricing
        unit_price,
        subtotal,
        tax_rate,
        tax_amount,
        
        -- Cash pricing
        cash_price,
        cash_subtotal,
        cash_tax_amount,
        
        -- Kitchen
        special_instructions,
        seat_number,
        item_status,

        -- Payment tracking
        paid_quantity,
        
        -- Timestamps
        created_at,
        updated_at
    ) VALUES (
        p_order_id,
        
        -- Open item
        TRUE,  -- is_open_item
        p_item_name,  -- open_item_name
        p_unit_price,  -- open_item_price
        
        -- Standard fields
        NULL,  -- menu_item_id
        p_item_name,  -- item_name (for reporting)
        'Open Items',  -- category_name
        p_quantity,
        
        -- Card pricing
        p_unit_price,  -- unit_price
        v_subtotal,
        v_tax_rate,
        v_tax_amount,
        
        -- Cash pricing
        v_cash_price,
        v_cash_subtotal,
        v_cash_tax_amount,
        
        -- Kitchen
        p_special_instructions,
        p_seat_number,
        'pending',
        
        -- Payment
        0,  -- paid_quantity
        
        -- Timestamps
        now(),
        now()
    )
    RETURNING id INTO v_item_id;
    
    -- ============================================
    -- 5. Recalculate Order Totals
    -- ============================================
    -- Your existing function works perfectly!
    PERFORM calculate_order_totals_fast(p_order_id);
    
    -- ============================================
    -- 6. Return Result
    -- ============================================
    RETURN jsonb_build_object(
        'success', true,
        'order_item_id', v_item_id,
        'item_name', p_item_name,
        'quantity', p_quantity,
        'unit_price', p_unit_price,
        'cash_price', v_cash_price,
        'subtotal', v_subtotal,
        'cash_subtotal', v_cash_subtotal,
        'tax_rate', v_tax_rate,
        'tax_amount', v_tax_amount,
        'cash_tax_amount', v_cash_tax_amount
    );
END;
$$;


ALTER FUNCTION "public"."add_open_item_v2"("p_order_id" "uuid", "p_item_name" "text", "p_unit_price" numeric, "p_quantity" integer, "p_special_instructions" "text", "p_is_tax_exempt" boolean, "p_seat_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_open_item_v2_dep"("p_order_id" "uuid", "p_item_name" "text", "p_unit_price" numeric, "p_quantity" integer DEFAULT 1, "p_special_instructions" "text" DEFAULT NULL::"text", "p_is_tax_exempt" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$DECLARE
    v_location_id uuid;
    v_merchant_id uuid;
    v_tax_rate numeric := 8.0;
    v_item_id uuid;
    
    v_cash_price numeric;
    v_subtotal numeric;
    v_cash_subtotal numeric;
    v_tax_amount numeric;
    v_cash_tax_amount numeric;
    
    v_cash_discount_rate numeric := 0.04;
    v_has_active_discount boolean := false;
BEGIN
    -- 1. Validate & Get Order Context
    SELECT o.location_id, o.merchant_id 
    INTO v_location_id, v_merchant_id
    FROM public.orders o
    WHERE o.id = p_order_id
      AND o.status NOT IN ('completed', 'cancelled', 'void')
      AND o.merchant_id = user_merchant_id()
      AND o.location_id = ANY(user_location_ids())
    FOR UPDATE;
    
    IF v_location_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or access denied: %', p_order_id;
    END IF;
    
    -- 2. Get Tax Rate
    IF NOT p_is_tax_exempt THEN
        SELECT COALESCE(tr.percentage, 8.0)
        INTO v_tax_rate
        FROM public.tax_rates tr
        WHERE tr.location_id = v_location_id 
          AND tr.tax_category = 'standard' 
          AND tr.is_active = true
        LIMIT 1;
        
        v_tax_rate := COALESCE(v_tax_rate, 8.0);
    ELSE
        v_tax_rate := 0;
    END IF;
    
    -- 3. Calculate base pricing (pre-discount)
    v_cash_price := p_unit_price * (1 - v_cash_discount_rate);
    v_subtotal := p_unit_price * p_quantity;
    v_cash_subtotal := v_cash_price * p_quantity;
    v_tax_amount := ROUND(v_subtotal * v_tax_rate / 100, 2);
    v_cash_tax_amount := ROUND(v_cash_subtotal * v_tax_rate / 100, 2);
    
    -- 4. Insert Order Item
    INSERT INTO public.order_items (
        order_id,
        is_open_item,
        open_item_name,
        open_item_price,
        menu_item_id,
        item_name,
        category_name,
        quantity,
        unit_price,
        subtotal,
        tax_rate,
        tax_amount,
        cash_price,
        cash_subtotal,
        cash_tax_amount,
        special_instructions,
        item_status,
        paid_quantity,
        discount_amount,
        created_at,
        updated_at
    ) VALUES (
        p_order_id,
        TRUE,
        p_item_name,
        p_unit_price,
        NULL,
        p_item_name,
        'Open Items',
        p_quantity,
        p_unit_price,
        v_subtotal,
        v_tax_rate,
        v_tax_amount,
        v_cash_price,
        v_cash_subtotal,
        v_cash_tax_amount,
        p_special_instructions,
        'pending',
        0,
        0,
        now(),
        now()
    )
    RETURNING id INTO v_item_id;
    
    -- 5. Check for active discount and redistribute
    SELECT EXISTS(
        SELECT 1 FROM public.order_discounts
        WHERE order_id = p_order_id
          AND voided_at IS NULL
          AND calculated_amount > 0
    ) INTO v_has_active_discount;
    
    IF v_has_active_discount THEN
        PERFORM redistribute_order_discount(p_order_id);
        
        SELECT subtotal, tax_amount, cash_subtotal, cash_tax_amount
        INTO v_subtotal, v_tax_amount, v_cash_subtotal, v_cash_tax_amount
        FROM public.order_items
        WHERE id = v_item_id;
    END IF;
    
    -- 6. Recalculate Order Totals
    -- PERFORM calculate_order_totals_fast(p_order_id);
    PERFORM recalculate_order_discount(p_order_id);

    RETURN jsonb_build_object(
        'success', true,
        'order_item_id', v_item_id,
        'item_name', p_item_name,
        'quantity', p_quantity,
        'unit_price', p_unit_price,
        'cash_price', v_cash_price,
        'subtotal', v_subtotal,
        'cash_subtotal', v_cash_subtotal,
        'tax_rate', v_tax_rate,
        'tax_amount', v_tax_amount,
        'cash_tax_amount', v_cash_tax_amount,
        'discount_applied', v_has_active_discount
    );
END;$$;


ALTER FUNCTION "public"."add_open_item_v2_dep"("p_order_id" "uuid", "p_item_name" "text", "p_unit_price" numeric, "p_quantity" integer, "p_special_instructions" "text", "p_is_tax_exempt" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_order_item"("p_order_id" "uuid", "p_item_name" "text", "p_unit_price" numeric, "p_menu_item_id" "uuid" DEFAULT NULL::"uuid", "p_location_exclusive_item_id" "uuid" DEFAULT NULL::"uuid", "p_item_description" "text" DEFAULT NULL::"text", "p_category_name" "text" DEFAULT NULL::"text", "p_cash_price" numeric DEFAULT NULL::numeric, "p_use_cash_price" boolean DEFAULT true, "p_quantity" integer DEFAULT 1, "p_selected_size_id" "uuid" DEFAULT NULL::"uuid", "p_selected_size_name" "text" DEFAULT NULL::"text", "p_size_price_modifier" numeric DEFAULT 0, "p_special_instructions" "text" DEFAULT NULL::"text", "p_modifiers" "jsonb" DEFAULT '[]'::"jsonb", "p_prep_station" "text" DEFAULT NULL::"text", "p_course_number" integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_item_id UUID;
  v_price_paid NUMERIC(10, 2);
  v_modifier JSONB;
  v_modifier_total NUMERIC(10, 2) := 0;
  v_item_subtotal NUMERIC(10, 2);
  v_merchant_id UUID;
  v_result JSON;
BEGIN
  -- Verify order exists and user has access
  SELECT merchant_id INTO v_merchant_id
  FROM public.orders
  WHERE id = p_order_id
    AND status NOT IN ('completed', 'cancelled', 'void')
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found or cannot be modified';
  END IF;
  
  -- -- Verify user has permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied: location.orders.manage required';
  -- END IF;
  
  -- Validate required fields
  IF p_item_name IS NULL THEN
    RAISE EXCEPTION 'Item name is required';
  END IF;
  
  IF p_unit_price IS NULL THEN
    RAISE EXCEPTION 'Unit price is required';
  END IF;
  
  -- Determine price to use (cash or card)
  -- POS sends both effective_price and effective_cash_price
  v_price_paid := CASE 
    WHEN p_use_cash_price AND p_cash_price IS NOT NULL THEN p_cash_price
    ELSE p_unit_price
  END;
  
  -- Add size modifier to price
  v_price_paid := v_price_paid + COALESCE(p_size_price_modifier, 0);
  
  -- Calculate modifier total from pre-calculated modifier prices
  IF jsonb_array_length(p_modifiers) > 0 THEN
    SELECT COALESCE(SUM(
      (mod->>'price_modifier')::NUMERIC * COALESCE((mod->>'quantity')::INTEGER, 1)
    ), 0)
    INTO v_modifier_total
    FROM jsonb_array_elements(p_modifiers) AS mod;
  END IF;
  
  -- Calculate item subtotal
  v_item_subtotal := (p_quantity * v_price_paid) + (p_quantity * v_modifier_total);
  
  -- Insert order item with all denormalized data
  INSERT INTO public.order_items (
    order_id,
    -- Item references (for audit/reporting)
    menu_item_id,
    location_exclusive_item_id,
    -- Denormalized item details (snapshot at time of order)
    item_name,
    item_description,
    category_name,
    -- Quantities
    quantity,
    -- Price snapshot (all from POS)
    unit_price,              -- effective_price
    cash_price,              -- effective_cash_price
    price_paid,              -- Actual price used (cash or card)
    subtotal,                -- Total for this line item
    -- Size details
    selected_size_id,
    selected_size_name,
    size_price_modifier,
    -- Instructions
    special_instructions,
    -- Status
    item_status,
    -- Prep info
    prep_station,
    course_number,
    -- Timestamps
    created_at,
    updated_at
  ) VALUES (
    p_order_id,
    p_menu_item_id,
    p_location_exclusive_item_id,
    p_item_name,
    p_item_description,
    p_category_name,
    p_quantity,
    p_unit_price,
    p_cash_price,
    v_price_paid,
    v_item_subtotal,
    p_selected_size_id,
    p_selected_size_name,
    COALESCE(p_size_price_modifier, 0),
    p_special_instructions,
    'pending',
    p_prep_station,
    p_course_number,
    NOW(),
    NOW()
  )
  RETURNING id INTO v_item_id;
  
  -- Add modifiers (pre-calculated prices from POS)
  IF jsonb_array_length(p_modifiers) > 0 THEN
    INSERT INTO public.order_item_modifiers (
      order_item_id,
      modifier_group_id,
      modifier_item_id,
      modifier_group_name,
      modifier_name,
      price_modifier,
      quantity,
      total_price
    )
    SELECT
      v_item_id,
      (mod->>'modifier_group_id')::UUID,
      (mod->>'modifier_item_id')::UUID,
      mod->>'modifier_group_name',
      mod->>'modifier_name',
      (mod->>'price_modifier')::NUMERIC,           -- Pre-calculated from POS
      COALESCE((mod->>'quantity')::INTEGER, 1),
      (mod->>'price_modifier')::NUMERIC * COALESCE((mod->>'quantity')::INTEGER, 1)
    FROM jsonb_array_elements(p_modifiers) AS mod;
  END IF;
  
  -- Return result
  SELECT json_build_object(
    'success', true,
    'order_item_id', v_item_id,
    'item_name', p_item_name,
    'quantity', p_quantity,
    'unit_price', p_unit_price,
    'cash_price', p_cash_price,
    'price_paid', v_price_paid,
    'modifier_total', v_modifier_total,
    'subtotal', v_item_subtotal
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."add_order_item"("p_order_id" "uuid", "p_item_name" "text", "p_unit_price" numeric, "p_menu_item_id" "uuid", "p_location_exclusive_item_id" "uuid", "p_item_description" "text", "p_category_name" "text", "p_cash_price" numeric, "p_use_cash_price" boolean, "p_quantity" integer, "p_selected_size_id" "uuid", "p_selected_size_name" "text", "p_size_price_modifier" numeric, "p_special_instructions" "text", "p_modifiers" "jsonb", "p_prep_station" "text", "p_course_number" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_order_item"("p_order_id" "uuid", "p_item_name" "text", "p_unit_price" numeric, "p_menu_item_id" "uuid", "p_location_exclusive_item_id" "uuid", "p_item_description" "text", "p_category_name" "text", "p_cash_price" numeric, "p_use_cash_price" boolean, "p_quantity" integer, "p_selected_size_id" "uuid", "p_selected_size_name" "text", "p_size_price_modifier" numeric, "p_special_instructions" "text", "p_modifiers" "jsonb", "p_prep_station" "text", "p_course_number" integer) IS 'Adds an item to an order using pre-calculated prices from POS. Accepts effective_price and effective_cash_price from get_menu_with_categories.';



CREATE OR REPLACE FUNCTION "public"."add_order_item_modifier"("p_order_item_id" "uuid", "p_modifier_group_id" "uuid", "p_modifier_item_id" "uuid", "p_modifier_group_name" "text", "p_modifier_name" "text", "p_price_modifier" numeric, "p_quantity" integer DEFAULT 1) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_id UUID;
  v_item_quantity INTEGER;
  v_price_paid NUMERIC(10, 2);
  v_modifier_id UUID;
  v_new_modifier_total NUMERIC(10, 2);
  v_new_subtotal NUMERIC(10, 2);
  v_result JSON;
BEGIN
  -- Get item details and verify access
  SELECT 
    oi.order_id,
    oi.quantity,
    oi.price_paid
  INTO v_order_id, v_item_quantity, v_price_paid
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
    AND oi.is_voided = FALSE
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids())
    AND o.status NOT IN ('completed', 'cancelled', 'void');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found or cannot be modified';
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Insert modifier
  INSERT INTO public.order_item_modifiers (
    order_item_id,
    modifier_group_id,
    modifier_item_id,
    modifier_group_name,
    modifier_name,
    price_modifier,
    quantity,
    total_price
  ) VALUES (
    p_order_item_id,
    p_modifier_group_id,
    p_modifier_item_id,
    p_modifier_group_name,
    p_modifier_name,
    p_price_modifier,
    p_quantity,
    p_price_modifier * p_quantity
  )
  RETURNING id INTO v_modifier_id;

  -- Calculate new totals
  SELECT COALESCE(SUM(total_price), 0)
  INTO v_new_modifier_total
  FROM public.order_item_modifiers
  WHERE order_item_id = p_order_item_id;

  v_new_subtotal := (v_item_quantity * v_price_paid) + (v_item_quantity * v_new_modifier_total);

  -- Update item subtotal
  UPDATE public.order_items
  SET 
    subtotal = v_new_subtotal,
    updated_at = NOW()
  WHERE id = p_order_item_id;

  SELECT json_build_object(
    'success', true,
    'modifier_id', v_modifier_id,
    'order_item_id', p_order_item_id,
    'modifier_name', p_modifier_name,
    'modifier_total', v_new_modifier_total,
    'new_subtotal', v_new_subtotal
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."add_order_item_modifier"("p_order_item_id" "uuid", "p_modifier_group_id" "uuid", "p_modifier_item_id" "uuid", "p_modifier_group_name" "text", "p_modifier_name" "text", "p_price_modifier" numeric, "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_order_item_v2"("p_order_id" "uuid", "p_menu_item_id" "uuid" DEFAULT NULL::"uuid", "p_quantity" integer DEFAULT 1, "p_unit_price" numeric DEFAULT 0, "p_cash_unit_price" numeric DEFAULT NULL::numeric, "p_item_name" "text" DEFAULT NULL::"text", "p_category_name" "text" DEFAULT NULL::"text", "p_location_exclusive_item_id" "uuid" DEFAULT NULL::"uuid", "p_selected_size_id" "uuid" DEFAULT NULL::"uuid", "p_selected_size_name" "text" DEFAULT NULL::"text", "p_size_price_modifier" numeric DEFAULT 0, "p_modifiers" "jsonb" DEFAULT NULL::"jsonb", "p_special_instructions" "text" DEFAULT NULL::"text", "p_course_number" integer DEFAULT 1, "p_seat_number" integer DEFAULT NULL::integer, "p_menu_id" "uuid" DEFAULT NULL::"uuid", "p_menu_name" "text" DEFAULT NULL::"text", "p_category_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
    v_location_id uuid;
    v_merchant_id uuid;
    v_tax_rate numeric := 0;  -- Default fallback
    v_is_tax_exempt boolean := false;
    v_item_id uuid;
    
    -- Pricing calculations
    v_modifier_total numeric := 0;
    v_size_mod numeric;
    v_effective_card_price numeric;
    v_effective_cash_price numeric;
    v_subtotal numeric;
    v_cash_subtotal numeric;
    v_tax_amount numeric;
    v_cash_tax_amount numeric;
    
    v_cash_discount_rate numeric := 0.04;
    v_has_active_discount boolean := false;
    v_new_sync_version integer;
BEGIN
     -- ============================================
    -- 1. Validate & Get Order Context (with RLS)
    -- ============================================
    -- FOR UPDATE: Acquires exclusive row lock to prevent race conditions
    -- when multiple items are added concurrently. Second transaction waits
    -- until first completes, ensuring calculate_order_totals_fast sees all items.
    SELECT o.location_id, o.merchant_id 
    INTO v_location_id, v_merchant_id
    FROM public.orders o
    WHERE o.id = p_order_id
      AND o.status NOT IN ('completed', 'cancelled', 'void')
      AND o.merchant_id = user_merchant_id()
      AND o.location_id = ANY(user_location_ids())
    FOR UPDATE;
    
    IF v_location_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or access denied: %', p_order_id;
    END IF;
    
    
    -- ============================================
    -- 2. Get Tax Rate
    -- ============================================
    IF p_menu_item_id IS NOT NULL THEN
        -- Get tax rate and exemption status in one query
        SELECT 
            COALESCE(tr.percentage, 0),
            COALESCE(lio.is_tax_exempt, mi.is_tax_exempt, false)
        INTO v_tax_rate, v_is_tax_exempt
        FROM public.menu_items mi
        LEFT JOIN public.location_item_overrides lio 
            ON lio.menu_item_id = mi.id 
            AND lio.location_id = v_location_id
        LEFT JOIN public.tax_rates tr 
            ON tr.location_id = v_location_id 
            AND tr.tax_category::text = COALESCE(lio.tax_category, mi.tax_category, 'standard')::text
            AND tr.is_active = true
        WHERE mi.id = p_menu_item_id;
        
        -- Override rate to 0 if exempt
        IF v_is_tax_exempt THEN
            v_tax_rate := 0;
        END IF;
    ELSE
        -- Open item - get default rate
        SELECT COALESCE(tr.percentage, 0)
        INTO v_tax_rate
        FROM public.tax_rates tr
        WHERE tr.location_id = v_location_id 
          AND tr.tax_category = 'standard' 
          AND tr.is_active = true
        LIMIT 1;
    END IF;
    
    -- Ensure we have a rate
    v_tax_rate := COALESCE(v_tax_rate, 0);

    -- ============================================
    -- 3. Calculate Modifier Total
    -- ============================================
    IF p_modifiers IS NOT NULL AND jsonb_array_length(p_modifiers) > 0 THEN
        SELECT COALESCE(SUM(
            COALESCE((mod->>'price_modifier')::numeric, 0) * 
            COALESCE((mod->>'quantity')::integer, 1)
        ), 0)
        INTO v_modifier_total
        FROM jsonb_array_elements(p_modifiers) AS mod;
    END IF;
    
    -- ============================================
    -- 4. Calculate Pricing
    -- ============================================
    v_size_mod := COALESCE(p_size_price_modifier, 0);
    
    -- Effective prices = base + size + modifiers
    v_effective_card_price := p_unit_price + v_size_mod + v_modifier_total;
    v_effective_cash_price := COALESCE(p_cash_unit_price, p_unit_price * (1 - v_cash_discount_rate)) 
                              + v_size_mod + v_modifier_total;
    
    -- Subtotals = effective price × quantity
    v_subtotal := v_effective_card_price * p_quantity;
    v_cash_subtotal := v_effective_cash_price * p_quantity;
    
    -- Tax on subtotals
    v_tax_amount := ROUND(v_subtotal * v_tax_rate / 100, 2);
    v_cash_tax_amount := ROUND(v_cash_subtotal * v_tax_rate / 100, 2);
    
    -- ============================================
    -- 5. Insert Order Item
    -- ============================================
    INSERT INTO public.order_items (
        order_id,
        menu_item_id,
        location_exclusive_item_id,
        item_name,
        category_name,
        quantity,
        -- Card pricing
        unit_price,
        subtotal,
        tax_rate,
        tax_amount,
        -- Cash pricing
        cash_price,
        cash_subtotal,
        cash_tax_amount,
        -- Size
        selected_size_id,
        selected_size_name,
        size_price_modifier,
        -- Kitchen
        special_instructions,
        item_status,
        course_number,
        seat_number,
        -- Payment tracking
        paid_quantity,
        -- Timestamps
        created_at,
        updated_at,
        -- Base Prices With no Modifiers
        base_card_price,
        base_cash_price,
        -- Menu/Category context
        menu_id,
        menu_name,
        category_id
    ) VALUES (
        p_order_id,
        p_menu_item_id,
        p_location_exclusive_item_id,
        p_item_name,
        COALESCE(p_category_name, 'Uncategorized'),
        p_quantity,
        -- Card pricing
        v_effective_card_price,
        v_subtotal,
        v_tax_rate,
        v_tax_amount,
        -- Cash pricing
        v_effective_cash_price,
        v_cash_subtotal,
        v_cash_tax_amount,
        -- Size
        p_selected_size_id,
        p_selected_size_name,
        v_size_mod,
        -- Kitchen
        p_special_instructions,
        'pending',
        COALESCE(p_course_number, 1),
        p_seat_number,
        -- Payment
        0,
        -- Timestamps
        now(),
        now(),
       -- Base Price with No Modifiers,
        p_unit_price,
        p_cash_unit_price,
        -- Menu/Category context
        p_menu_id,
        p_menu_name,
        p_category_id
    )
    RETURNING id INTO v_item_id;

    -- ============================================
    -- 6. Insert Modifiers
    -- ============================================
    IF p_modifiers IS NOT NULL AND jsonb_array_length(p_modifiers) > 0 THEN
        INSERT INTO public.order_item_modifiers (
            order_item_id,
            modifier_group_id,
            modifier_item_id,
            modifier_group_name,
            modifier_name,
            price_modifier,
            quantity,
            total_price,
            is_no
        )
        SELECT
            v_item_id,
            (mod->>'modifier_group_id')::uuid,
            (mod->>'modifier_item_id')::uuid,
            mod->>'modifier_group_name',
            mod->>'modifier_name',
            COALESCE((mod->>'price_modifier')::numeric, 0),
            COALESCE((mod->>'quantity')::integer, 1),
            COALESCE((mod->>'price_modifier')::numeric, 0) * COALESCE((mod->>'quantity')::integer, 1),
            COALESCE((mod->>'is_no')::boolean, false)
        FROM jsonb_array_elements(p_modifiers) AS mod;
    END IF;

    -- 7. Check if there's an active order discount
    SELECT EXISTS(
        SELECT 1 FROM public.order_discounts
        WHERE order_id = p_order_id
          AND voided_at IS NULL
          AND calculated_amount > 0
    ) INTO v_has_active_discount;
    
    -- 8. If discount exists, redistribute across all items (including new one)
    IF v_has_active_discount THEN
        PERFORM redistribute_order_discount(p_order_id);
        
        -- Get the updated values for the new item
        SELECT subtotal, tax_amount, cash_subtotal, cash_tax_amount
        INTO v_subtotal, v_tax_amount, v_cash_subtotal, v_cash_tax_amount
        FROM public.order_items
        WHERE id = v_item_id;
    END IF;
    
       -- ============================================
    -- 7. RECALCULATE DISCOUNT (updates order_discounts + all items)
    -- ============================================
    PERFORM recalculate_order_discount(p_order_id);
    -- ============================================
    -- 7. Recalculate Order Totals
    -- ============================================
    -- PERFORM calculate_order_totals_fast(p_order_id);
    v_new_sync_version := increment_order_sync_version(p_order_id);

    -- ============================================
    -- 8. Return Result
    -- ============================================
    RETURN jsonb_build_object(
        'success', true,
        'order_item_id', v_item_id,
        'item_name', p_item_name,
        'quantity', p_quantity,
        'unit_price', v_effective_card_price,
        'cash_price', v_effective_cash_price,
        'modifier_total', v_modifier_total,
        'subtotal', v_subtotal,
        'cash_subtotal', v_cash_subtotal,
        'tax_rate', v_tax_rate,
        'tax_amount', v_tax_amount,
        'cash_tax_amount', v_cash_tax_amount,
        'sync_version', v_new_sync_version
    );
END$$;


ALTER FUNCTION "public"."add_order_item_v2"("p_order_id" "uuid", "p_menu_item_id" "uuid", "p_quantity" integer, "p_unit_price" numeric, "p_cash_unit_price" numeric, "p_item_name" "text", "p_category_name" "text", "p_location_exclusive_item_id" "uuid", "p_selected_size_id" "uuid", "p_selected_size_name" "text", "p_size_price_modifier" numeric, "p_modifiers" "jsonb", "p_special_instructions" "text", "p_course_number" integer, "p_seat_number" integer, "p_menu_id" "uuid", "p_menu_name" "text", "p_category_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_order_item_v2_dep"("p_order_id" "uuid", "p_item_name" "text", "p_unit_price" numeric, "p_quantity" integer DEFAULT 1, "p_cash_unit_price" numeric DEFAULT NULL::numeric, "p_menu_item_id" "uuid" DEFAULT NULL::"uuid", "p_location_exclusive_item_id" "uuid" DEFAULT NULL::"uuid", "p_category_name" "text" DEFAULT 'Uncategorized'::"text", "p_selected_size_id" "uuid" DEFAULT NULL::"uuid", "p_selected_size_name" "text" DEFAULT NULL::"text", "p_size_price_modifier" numeric DEFAULT 0, "p_modifiers" "jsonb" DEFAULT '[]'::"jsonb", "p_special_instructions" "text" DEFAULT NULL::"text", "p_course_number" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
    v_location_id uuid;
    v_merchant_id uuid;
    v_tax_rate numeric := 0;  -- Default fallback
    v_is_tax_exempt boolean := false;
    v_item_id uuid;
    
    -- Pricing calculations
    v_modifier_total numeric := 0;
    v_size_mod numeric;
    v_effective_card_price numeric;
    v_effective_cash_price numeric;
    v_subtotal numeric;
    v_cash_subtotal numeric;
    v_tax_amount numeric;
    v_cash_tax_amount numeric;
    
    v_cash_discount_rate numeric := 0.04;
    v_has_active_discount boolean := false;
    v_new_sync_version integer;
BEGIN
     -- ============================================
    -- 1. Validate & Get Order Context (with RLS)
    -- ============================================
    -- FOR UPDATE: Acquires exclusive row lock to prevent race conditions
    -- when multiple items are added concurrently. Second transaction waits
    -- until first completes, ensuring calculate_order_totals_fast sees all items.
    SELECT o.location_id, o.merchant_id 
    INTO v_location_id, v_merchant_id
    FROM public.orders o
    WHERE o.id = p_order_id
      AND o.status NOT IN ('completed', 'cancelled', 'void')
      AND o.merchant_id = user_merchant_id()
      AND o.location_id = ANY(user_location_ids())
    FOR UPDATE;
    
    IF v_location_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or access denied: %', p_order_id;
    END IF;
    
    
    -- ============================================
    -- 2. Get Tax Rate
    -- ============================================
    IF p_menu_item_id IS NOT NULL THEN
        -- Get tax rate and exemption status in one query
        SELECT 
            COALESCE(tr.percentage, 0),
            COALESCE(lio.is_tax_exempt, mi.is_tax_exempt, false)
        INTO v_tax_rate, v_is_tax_exempt
        FROM public.menu_items mi
        LEFT JOIN public.location_item_overrides lio 
            ON lio.menu_item_id = mi.id 
            AND lio.location_id = v_location_id
        LEFT JOIN public.tax_rates tr 
            ON tr.location_id = v_location_id 
            AND tr.tax_category::text = COALESCE(lio.tax_category, mi.tax_category, 'standard')::text
            AND tr.is_active = true
        WHERE mi.id = p_menu_item_id;
        
        -- Override rate to 0 if exempt
        IF v_is_tax_exempt THEN
            v_tax_rate := 0;
        END IF;
    ELSE
        -- Open item - get default rate
        SELECT COALESCE(tr.percentage, 0)
        INTO v_tax_rate
        FROM public.tax_rates tr
        WHERE tr.location_id = v_location_id 
          AND tr.tax_category = 'standard' 
          AND tr.is_active = true
        LIMIT 1;
    END IF;
    
    -- Ensure we have a rate
    v_tax_rate := COALESCE(v_tax_rate, 0);

    -- ============================================
    -- 3. Calculate Modifier Total
    -- ============================================
    IF p_modifiers IS NOT NULL AND jsonb_array_length(p_modifiers) > 0 THEN
        SELECT COALESCE(SUM(
            COALESCE((mod->>'price_modifier')::numeric, 0) * 
            COALESCE((mod->>'quantity')::integer, 1)
        ), 0)
        INTO v_modifier_total
        FROM jsonb_array_elements(p_modifiers) AS mod;
    END IF;
    
    -- ============================================
    -- 4. Calculate Pricing
    -- ============================================
    v_size_mod := COALESCE(p_size_price_modifier, 0);
    
    -- Effective prices = base + size + modifiers
    v_effective_card_price := p_unit_price + v_size_mod + v_modifier_total;
    v_effective_cash_price := COALESCE(p_cash_unit_price, p_unit_price * (1 - v_cash_discount_rate)) 
                              + v_size_mod + v_modifier_total;
    
    -- Subtotals = effective price × quantity
    v_subtotal := v_effective_card_price * p_quantity;
    v_cash_subtotal := v_effective_cash_price * p_quantity;
    
    -- Tax on subtotals
    v_tax_amount := ROUND(v_subtotal * v_tax_rate / 100, 2);
    v_cash_tax_amount := ROUND(v_cash_subtotal * v_tax_rate / 100, 2);
    
    -- ============================================
    -- 5. Insert Order Item
    -- ============================================
    INSERT INTO public.order_items (
        order_id,
        menu_item_id,
        location_exclusive_item_id,
        item_name,
        category_name,
        quantity,
        -- Card pricing
        unit_price,
        subtotal,
        tax_rate,
        tax_amount,
        -- Cash pricing
        cash_price,
        cash_subtotal,
        cash_tax_amount,
        -- Size
        selected_size_id,
        selected_size_name,
        size_price_modifier,
        -- Kitchen
        special_instructions,
        item_status,
        course_number,
        -- Payment tracking
        paid_quantity,
        -- Timestamps
        created_at,
        updated_at,
        -- Base Prices With no Modifiers
        base_card_price,
        base_cash_price
    ) VALUES (
        p_order_id,
        p_menu_item_id,
        p_location_exclusive_item_id,
        p_item_name,
        COALESCE(p_category_name, 'Uncategorized'),
        p_quantity,
        -- Card pricing
        v_effective_card_price,
        v_subtotal,
        v_tax_rate,
        v_tax_amount,
        -- Cash pricing
        v_effective_cash_price,
        v_cash_subtotal,
        v_cash_tax_amount,
        -- Size
        p_selected_size_id,
        p_selected_size_name,
        v_size_mod,
        -- Kitchen
        p_special_instructions,
        'pending',
        COALESCE(p_course_number, 1),
        -- Payment
        0,
        -- Timestamps
        now(),
        now(),
       -- Base Price with No Modifiers,
        p_unit_price,
        p_cash_unit_price
    )
    RETURNING id INTO v_item_id;

    -- ============================================
    -- 6. Insert Modifiers
    -- ============================================
    IF p_modifiers IS NOT NULL AND jsonb_array_length(p_modifiers) > 0 THEN
        INSERT INTO public.order_item_modifiers (
            order_item_id,
            modifier_group_id,
            modifier_item_id,
            modifier_group_name,
            modifier_name,
            price_modifier,
            quantity,
            total_price
        )
        SELECT
            v_item_id,
            (mod->>'modifier_group_id')::uuid,
            (mod->>'modifier_item_id')::uuid,
            mod->>'modifier_group_name',
            mod->>'modifier_name',
            COALESCE((mod->>'price_modifier')::numeric, 0),
            COALESCE((mod->>'quantity')::integer, 1),
            COALESCE((mod->>'price_modifier')::numeric, 0) * COALESCE((mod->>'quantity')::integer, 1)
        FROM jsonb_array_elements(p_modifiers) AS mod;
    END IF;

    -- 7. Check if there's an active order discount
    SELECT EXISTS(
        SELECT 1 FROM public.order_discounts
        WHERE order_id = p_order_id
          AND voided_at IS NULL
          AND calculated_amount > 0
    ) INTO v_has_active_discount;
    
    -- 8. If discount exists, redistribute across all items (including new one)
    IF v_has_active_discount THEN
        PERFORM redistribute_order_discount(p_order_id);
        
        -- Get the updated values for the new item
        SELECT subtotal, tax_amount, cash_subtotal, cash_tax_amount
        INTO v_subtotal, v_tax_amount, v_cash_subtotal, v_cash_tax_amount
        FROM public.order_items
        WHERE id = v_item_id;
    END IF;
    
       -- ============================================
    -- 7. RECALCULATE DISCOUNT (updates order_discounts + all items)
    -- ============================================
    PERFORM recalculate_order_discount(p_order_id);
    -- ============================================
    -- 7. Recalculate Order Totals
    -- ============================================
    -- PERFORM calculate_order_totals_fast(p_order_id);
    v_new_sync_version := increment_order_sync_version(p_order_id);

    -- ============================================
    -- 8. Return Result
    -- ============================================
    RETURN jsonb_build_object(
        'success', true,
        'order_item_id', v_item_id,
        'item_name', p_item_name,
        'quantity', p_quantity,
        'unit_price', v_effective_card_price,
        'cash_price', v_effective_cash_price,
        'modifier_total', v_modifier_total,
        'subtotal', v_subtotal,
        'cash_subtotal', v_cash_subtotal,
        'tax_rate', v_tax_rate,
        'tax_amount', v_tax_amount,
        'cash_tax_amount', v_cash_tax_amount,
        'sync_version', v_new_sync_version
    );
END;$$;


ALTER FUNCTION "public"."add_order_item_v2_dep"("p_order_id" "uuid", "p_item_name" "text", "p_unit_price" numeric, "p_quantity" integer, "p_cash_unit_price" numeric, "p_menu_item_id" "uuid", "p_location_exclusive_item_id" "uuid", "p_category_name" "text", "p_selected_size_id" "uuid", "p_selected_size_name" "text", "p_size_price_modifier" numeric, "p_modifiers" "jsonb", "p_special_instructions" "text", "p_course_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_order_item_v3"("p_order_id" "uuid", "p_menu_item_id" "uuid", "p_location_exclusive_item_id" "uuid", "p_item_name" "text", "p_category_name" "text", "p_quantity" integer, "p_unit_price" numeric, "p_cash_unit_price" numeric DEFAULT NULL::numeric, "p_selected_size_id" "uuid" DEFAULT NULL::"uuid", "p_selected_size_name" "text" DEFAULT NULL::"text", "p_size_price_modifier" numeric DEFAULT 0, "p_modifiers" "jsonb" DEFAULT NULL::"jsonb", "p_special_instructions" "text" DEFAULT NULL::"text", "p_course_number" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$DECLARE
    v_location_id uuid;
    v_merchant_id uuid;
    v_tax_rate numeric := 8.0;
    v_is_tax_exempt boolean := false;
    v_item_id uuid;
    
    -- Pricing
    v_modifier_total numeric := 0;
    v_size_mod numeric;
    v_effective_card_price numeric;
    v_effective_cash_price numeric;
    v_subtotal numeric;
    v_cash_subtotal numeric;
    v_tax_amount numeric;
    v_cash_tax_amount numeric;
    
    v_cash_discount_rate numeric := 0.04;
    v_discount_result JSONB;
BEGIN
    -- ============================================
    -- 1. Validate & Get Order Context
    -- ============================================
    SELECT o.location_id, o.merchant_id 
    INTO v_location_id, v_merchant_id
    FROM public.orders o
    WHERE o.id = p_order_id
      AND o.status NOT IN ('completed', 'cancelled', 'void')
      AND o.merchant_id = user_merchant_id()
      AND o.location_id = ANY(user_location_ids())
    FOR UPDATE;
    
    IF v_location_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or access denied: %', p_order_id;
    END IF;
    
    -- ============================================
    -- 2. Get Tax Rate
    -- ============================================
    IF p_menu_item_id IS NOT NULL THEN
        SELECT 
            COALESCE(tr.percentage, 8.0),
            COALESCE(lio.is_tax_exempt, mi.is_tax_exempt, false)
        INTO v_tax_rate, v_is_tax_exempt
        FROM public.menu_items mi
        LEFT JOIN public.location_item_overrides lio 
            ON lio.menu_item_id = mi.id AND lio.location_id = v_location_id
        LEFT JOIN public.tax_rates tr 
            ON tr.location_id = v_location_id 
            AND tr.tax_category::text = COALESCE(lio.tax_category, mi.tax_category, 'standard')::text
            AND tr.is_active = true
        WHERE mi.id = p_menu_item_id;
        
        IF v_is_tax_exempt THEN v_tax_rate := 0; END IF;
    ELSE
        SELECT COALESCE(tr.percentage, 8.0) INTO v_tax_rate
        FROM public.tax_rates tr
        WHERE tr.location_id = v_location_id 
          AND tr.tax_category = 'standard' AND tr.is_active = true
        LIMIT 1;
    END IF;
    
    v_tax_rate := COALESCE(v_tax_rate, 8.0);

    -- ============================================
    -- 3. Calculate Modifier Total
    -- ============================================
    IF p_modifiers IS NOT NULL AND jsonb_array_length(p_modifiers) > 0 THEN
        SELECT COALESCE(SUM(
            COALESCE((mod->>'price_modifier')::numeric, 0) * 
            COALESCE((mod->>'quantity')::integer, 1)
        ), 0)
        INTO v_modifier_total
        FROM jsonb_array_elements(p_modifiers) AS mod;
    END IF;
    
    -- ============================================
    -- 4. Calculate Pricing (WITHOUT discount - will be applied by recalculate)
    -- ============================================
    v_size_mod := COALESCE(p_size_price_modifier, 0);
    v_effective_card_price := p_unit_price + v_size_mod + v_modifier_total;
    v_effective_cash_price := COALESCE(p_cash_unit_price, p_unit_price * (1 - v_cash_discount_rate)) 
                              + v_size_mod + v_modifier_total;
    
    -- Initial values (no discount yet)
    v_subtotal := v_effective_card_price * p_quantity;
    v_cash_subtotal := v_effective_cash_price * p_quantity;
    v_tax_amount := ROUND(v_subtotal * v_tax_rate / 100, 2);
    v_cash_tax_amount := ROUND(v_cash_subtotal * v_tax_rate / 100, 2);
    
    -- ============================================
    -- 5. Insert Order Item (without discount - will be set by recalculate)
    -- ============================================
    INSERT INTO public.order_items (
        order_id, menu_item_id, location_exclusive_item_id,
        item_name, category_name, quantity,
        unit_price, subtotal, tax_rate, tax_amount,
        cash_price, cash_subtotal, cash_tax_amount,
        selected_size_id, selected_size_name, size_price_modifier,
        special_instructions, item_status, course_number,
        paid_quantity, created_at, updated_at
    ) VALUES (
        p_order_id, p_menu_item_id, p_location_exclusive_item_id,
        p_item_name, COALESCE(p_category_name, 'Uncategorized'), p_quantity,
        v_effective_card_price, v_subtotal, v_tax_rate, v_tax_amount,
        v_effective_cash_price, v_cash_subtotal, v_cash_tax_amount,
        p_selected_size_id, p_selected_size_name, v_size_mod,
        p_special_instructions, 'pending', COALESCE(p_course_number, 1),
        0, now(), now()
    )
    RETURNING id INTO v_item_id;

    -- ============================================
    -- 6. Insert Modifiers
    -- ============================================
    IF p_modifiers IS NOT NULL AND jsonb_array_length(p_modifiers) > 0 THEN
        INSERT INTO public.order_item_modifiers (
            order_item_id, modifier_group_id, modifier_item_id,
            modifier_group_name, modifier_name, price_modifier, quantity, total_price
        )
        SELECT
            v_item_id,
            (mod->>'modifier_group_id')::uuid,
            (mod->>'modifier_item_id')::uuid,
            mod->>'modifier_group_name',
            mod->>'modifier_name',
            COALESCE((mod->>'price_modifier')::numeric, 0),
            COALESCE((mod->>'quantity')::integer, 1),
            COALESCE((mod->>'price_modifier')::numeric, 0) * COALESCE((mod->>'quantity')::integer, 1)
        FROM jsonb_array_elements(p_modifiers) AS mod;
    END IF;
    
    -- ============================================
    -- 7. RECALCULATE DISCOUNT (updates order_discounts + all items)
    -- ============================================
    v_discount_result := recalculate_order_discount(p_order_id);
    
    -- ============================================
    -- 8. Return Result
    -- ============================================
    RETURN jsonb_build_object(
        'success', true,
        'order_item_id', v_item_id,
        'item_name', p_item_name,
        'quantity', p_quantity,
        'unit_price', v_effective_card_price,
        'cash_price', v_effective_cash_price,
        'modifier_total', v_modifier_total,
        'tax_rate', v_tax_rate,
        'discount_applied', (v_discount_result->>'has_discount')::boolean,
        'discount_recalculated', v_discount_result
    );
END;$$;


ALTER FUNCTION "public"."add_order_item_v3"("p_order_id" "uuid", "p_menu_item_id" "uuid", "p_location_exclusive_item_id" "uuid", "p_item_name" "text", "p_category_name" "text", "p_quantity" integer, "p_unit_price" numeric, "p_cash_unit_price" numeric, "p_selected_size_id" "uuid", "p_selected_size_name" "text", "p_size_price_modifier" numeric, "p_modifiers" "jsonb", "p_special_instructions" "text", "p_course_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_order_item_with_course"("p_order_id" "uuid", "p_item_name" "text", "p_unit_price" numeric, "p_quantity" integer DEFAULT 1, "p_course_number" integer DEFAULT NULL::integer, "p_menu_item_id" "uuid" DEFAULT NULL::"uuid", "p_location_exclusive_item_id" "uuid" DEFAULT NULL::"uuid", "p_item_description" "text" DEFAULT NULL::"text", "p_category_name" "text" DEFAULT NULL::"text", "p_cash_price" numeric DEFAULT NULL::numeric, "p_use_cash_price" boolean DEFAULT false, "p_selected_size_id" "uuid" DEFAULT NULL::"uuid", "p_selected_size_name" "text" DEFAULT NULL::"text", "p_size_price_modifier" numeric DEFAULT 0, "p_special_instructions" "text" DEFAULT NULL::"text", "p_modifiers" "jsonb" DEFAULT '[]'::"jsonb", "p_prep_station" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order RECORD;
  v_course INTEGER;
  v_course_status TEXT;
  v_order_item_id UUID;
  v_effective_price NUMERIC;
  v_modifier_total NUMERIC := 0;
  v_subtotal NUMERIC;
  v_mod JSONB;
BEGIN
  -- Get order and validate
  SELECT o.*, ts.working_course
  INTO v_order
  FROM public.orders o
  LEFT JOIN public.table_sessions ts ON ts.order_id = o.id AND ts.is_active = TRUE
  WHERE o.id = p_order_id
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  -- Determine course number
  v_course := COALESCE(p_course_number, v_order.working_course, 1);

  -- Check if course is still open
  SELECT status INTO v_course_status
  FROM public.order_courses
  WHERE order_id = p_order_id AND course_number = v_course;

  IF v_course_status IS NOT NULL AND v_course_status != 'open' THEN
    RAISE EXCEPTION 'Cannot add items to course % - it has already been fired', v_course;
  END IF;

  -- Ensure course exists
  PERFORM public.ensure_course_exists(p_order_id, v_course);

  -- Calculate effective price
  v_effective_price := CASE 
    WHEN p_use_cash_price AND p_cash_price IS NOT NULL THEN p_cash_price
    ELSE p_unit_price
  END + COALESCE(p_size_price_modifier, 0);

  -- Calculate modifier total
  FOR v_mod IN SELECT * FROM jsonb_array_elements(p_modifiers)
  LOOP
    v_modifier_total := v_modifier_total + 
      COALESCE((v_mod->>'price_modifier')::NUMERIC, 0) * 
      COALESCE((v_mod->>'quantity')::INTEGER, 1);
  END LOOP;

  -- Calculate subtotal
  v_subtotal := (v_effective_price + v_modifier_total) * p_quantity;

  -- Insert item
  INSERT INTO public.order_items (
    order_id, menu_item_id, location_exclusive_item_id,
    item_name, item_description, category_name,
    unit_price, cash_price,
    selected_size_id, selected_size_name, size_price_modifier,
    quantity, subtotal,
    special_instructions, prep_station,
    course_number
  ) VALUES (
    p_order_id, p_menu_item_id, p_location_exclusive_item_id,
    p_item_name, p_item_description, p_category_name,
    p_unit_price, p_cash_price,
    p_selected_size_id, p_selected_size_name, p_size_price_modifier,
    p_quantity, v_subtotal,
    p_special_instructions, p_prep_station,
    v_course
  )
  RETURNING id INTO v_order_item_id;

  -- Insert modifiers
  FOR v_mod IN SELECT * FROM jsonb_array_elements(p_modifiers)
  LOOP
    INSERT INTO public.order_item_modifiers (
      order_item_id,
      modifier_group_id,
      modifier_item_id,
      modifier_group_name,
      modifier_name,
      price_modifier,
      quantity
    ) VALUES (
      v_order_item_id,
      (v_mod->>'modifier_group_id')::UUID,
      (v_mod->>'modifier_item_id')::UUID,
      v_mod->>'modifier_group_name',
      v_mod->>'modifier_name',
      COALESCE((v_mod->>'price_modifier')::NUMERIC, 0),
      COALESCE((v_mod->>'quantity')::INTEGER, 1)
    );
  END LOOP;

  RETURN json_build_object(
    'success', true,
    'order_item_id', v_order_item_id,
    'course_number', v_course,
    'subtotal', v_subtotal
  );
END;
$$;


ALTER FUNCTION "public"."add_order_item_with_course"("p_order_id" "uuid", "p_item_name" "text", "p_unit_price" numeric, "p_quantity" integer, "p_course_number" integer, "p_menu_item_id" "uuid", "p_location_exclusive_item_id" "uuid", "p_item_description" "text", "p_category_name" "text", "p_cash_price" numeric, "p_use_cash_price" boolean, "p_selected_size_id" "uuid", "p_selected_size_name" "text", "p_size_price_modifier" numeric, "p_special_instructions" "text", "p_modifiers" "jsonb", "p_prep_station" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_order_items_batch"("p_order_id" "uuid", "p_items" "jsonb") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_item JSONB;
  v_item_id UUID;
  v_price_paid NUMERIC(10, 2);
  v_modifier_total NUMERIC(10, 2);
  v_item_subtotal NUMERIC(10, 2);
  v_merchant_id UUID;
  v_inserted_items UUID[] := ARRAY[]::UUID[];
  v_total_items INTEGER := 0;
  v_total_amount NUMERIC(10, 2) := 0;
  v_result JSON;
BEGIN
  -- Verify order exists and user has access
  SELECT merchant_id INTO v_merchant_id
  FROM public.orders
  WHERE id = p_order_id
    AND status NOT IN ('completed', 'cancelled', 'void')
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found or cannot be modified';
  END IF;
  
  -- -- Verify user has permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied: location.orders.manage required';
  -- END IF;
  
  -- Process each item
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    -- Calculate price to use
    v_price_paid := CASE 
      WHEN (v_item->>'use_cash_price')::BOOLEAN AND (v_item->>'cash_price') IS NOT NULL 
        THEN (v_item->>'cash_price')::NUMERIC
      ELSE (v_item->>'unit_price')::NUMERIC
    END;
    
    -- Add size modifier
    v_price_paid := v_price_paid + COALESCE((v_item->>'size_price_modifier')::NUMERIC, 0);
    
    -- Calculate modifier total
    SELECT COALESCE(SUM(
      (mod->>'price_modifier')::NUMERIC * COALESCE((mod->>'quantity')::INTEGER, 1)
    ), 0)
    INTO v_modifier_total
    FROM jsonb_array_elements(COALESCE(v_item->'modifiers', '[]'::jsonb)) AS mod;
    
    -- Calculate subtotal
    v_item_subtotal := (COALESCE((v_item->>'quantity')::INTEGER, 1) * v_price_paid) + 
                       (COALESCE((v_item->>'quantity')::INTEGER, 1) * v_modifier_total);
    
    -- Insert item
    INSERT INTO public.order_items (
      order_id,
      menu_item_id,
      location_exclusive_item_id,
      item_name,
      item_description,
      category_name,
      quantity,
      unit_price,
      cash_price,
      price_paid,
      subtotal,
      selected_size_id,
      selected_size_name,
      size_price_modifier,
      special_instructions,
      item_status,
      prep_station,
      course_number,
      created_at,
      updated_at
    ) VALUES (
      p_order_id,
      (v_item->>'menu_item_id')::UUID,
      (v_item->>'location_exclusive_item_id')::UUID,
      v_item->>'item_name',
      v_item->>'item_description',
      v_item->>'category_name',
      COALESCE((v_item->>'quantity')::INTEGER, 1),
      (v_item->>'unit_price')::NUMERIC,
      (v_item->>'cash_price')::NUMERIC,
      v_price_paid,
      v_item_subtotal,
      (v_item->>'selected_size_id')::UUID,
      v_item->>'selected_size_name',
      COALESCE((v_item->>'size_price_modifier')::NUMERIC, 0),
      v_item->>'special_instructions',
      'pending',
      v_item->>'prep_station',
      (v_item->>'course_number')::INTEGER,
      NOW(),
      NOW()
    )
    RETURNING id INTO v_item_id;
    
    -- Add modifiers for this item
    IF jsonb_array_length(COALESCE(v_item->'modifiers', '[]'::jsonb)) > 0 THEN
      INSERT INTO public.order_item_modifiers (
        order_item_id,
        modifier_group_id,
        modifier_item_id,
        modifier_group_name,
        modifier_name,
        price_modifier,
        quantity,
        total_price
      )
      SELECT
        v_item_id,
        (mod->>'modifier_group_id')::UUID,
        (mod->>'modifier_item_id')::UUID,
        mod->>'modifier_group_name',
        mod->>'modifier_name',
        (mod->>'price_modifier')::NUMERIC,
        COALESCE((mod->>'quantity')::INTEGER, 1),
        (mod->>'price_modifier')::NUMERIC * COALESCE((mod->>'quantity')::INTEGER, 1)
      FROM jsonb_array_elements(v_item->'modifiers') AS mod;
    END IF;
    
    v_inserted_items := array_append(v_inserted_items, v_item_id);
    v_total_items := v_total_items + 1;
    v_total_amount := v_total_amount + v_item_subtotal;
  END LOOP;
  
  -- Return result
  SELECT json_build_object(
    'success', true,
    'order_id', p_order_id,
    'items_added', v_total_items,
    'item_ids', v_inserted_items,
    'batch_total', v_total_amount
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."add_order_items_batch"("p_order_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_order_items_batch"("p_order_id" "uuid", "p_items" "jsonb") IS 'Adds multiple items to an order in a single call for better performance';



CREATE OR REPLACE FUNCTION "public"."add_ticket_message"("p_ticket_id" "uuid", "p_sender_id" "text", "p_sender_name" "text", "p_sender_role" "text", "p_message" "text", "p_is_internal" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_message_id UUID;
  v_ticket     RECORD;
BEGIN
  SELECT * INTO v_ticket FROM public.support_tickets WHERE id = p_ticket_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;

  INSERT INTO public.support_ticket_messages (
    ticket_id, sender_id, sender_name, sender_role, message, is_internal,
    read_by_merchant, read_by_admin
  ) VALUES (
    p_ticket_id, p_sender_id, p_sender_name, p_sender_role, p_message, p_is_internal,
    CASE WHEN p_sender_role = 'admin' THEN false ELSE true END,
    CASE WHEN p_sender_role = 'admin' THEN true ELSE false END
  )
  RETURNING id INTO v_message_id;

  -- Update ticket timestamps and status
  UPDATE public.support_tickets
  SET
    last_message_at = now(),
    updated_at = now(),
    -- First admin response sets first_response_at
    first_response_at = CASE
      WHEN p_sender_role = 'admin' AND first_response_at IS NULL THEN now()
      ELSE first_response_at
    END,
    -- Admin reply moves ticket to in_progress if it was open
    status = CASE
      WHEN p_sender_role = 'admin' AND status = 'open' THEN 'in_progress'
      WHEN p_sender_role = 'merchant' AND status = 'waiting_on_merchant' THEN 'in_progress'
      ELSE status
    END
  WHERE id = p_ticket_id;

  RETURN jsonb_build_object('message_id', v_message_id);
END;
$$;


ALTER FUNCTION "public"."add_ticket_message"("p_ticket_id" "uuid", "p_sender_id" "text", "p_sender_name" "text", "p_sender_role" "text", "p_message" "text", "p_is_internal" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_ticket_message_with_attachments"("p_ticket_id" "uuid", "p_sender_id" "text", "p_sender_name" "text", "p_sender_role" "text", "p_message" "text", "p_is_internal" boolean DEFAULT false, "p_attachments" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_message_id UUID;
  v_ticket     RECORD;
  v_att        JSONB;
BEGIN
  SELECT * INTO v_ticket FROM public.support_tickets WHERE id = p_ticket_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;

  -- Insert message
  INSERT INTO public.support_ticket_messages (
    ticket_id, sender_id, sender_name, sender_role, message, is_internal,
    read_by_merchant, read_by_admin
  ) VALUES (
    p_ticket_id, p_sender_id, p_sender_name, p_sender_role, p_message, p_is_internal,
    CASE WHEN p_sender_role = 'admin' THEN false ELSE true END,
    CASE WHEN p_sender_role = 'admin' THEN true  ELSE false END
  )
  RETURNING id INTO v_message_id;

  -- Insert attachments linked to this message
  FOR v_att IN SELECT * FROM jsonb_array_elements(COALESCE(p_attachments, '[]'::jsonb))
  LOOP
    INSERT INTO public.support_ticket_attachments (
      ticket_id, message_id, uploaded_by,
      file_name, file_path, file_size, file_type
    ) VALUES (
      p_ticket_id, v_message_id, p_sender_id,
      v_att->>'file_name',
      v_att->>'file_path',
      (v_att->>'file_size')::integer,
      v_att->>'file_type'
    );
  END LOOP;

  -- Update ticket timestamps and auto-advance status
  UPDATE public.support_tickets
  SET
    last_message_at   = now(),
    updated_at        = now(),
    first_response_at = CASE
      WHEN p_sender_role = 'admin' AND first_response_at IS NULL THEN now()
      ELSE first_response_at
    END,
    status = CASE
      WHEN p_sender_role = 'admin'    AND status = 'open'                  THEN 'in_progress'
      WHEN p_sender_role = 'merchant' AND status = 'waiting_on_merchant'   THEN 'in_progress'
      ELSE status
    END
  WHERE id = p_ticket_id;

  RETURN jsonb_build_object('message_id', v_message_id);
END;
$$;


ALTER FUNCTION "public"."add_ticket_message_with_attachments"("p_ticket_id" "uuid", "p_sender_id" "text", "p_sender_name" "text", "p_sender_role" "text", "p_message" "text", "p_is_internal" boolean, "p_attachments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_to_waitlist"("p_location_id" "uuid", "p_party_name" "text", "p_party_size" integer, "p_phone" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_preferred_section" "text" DEFAULT NULL::"text", "p_seating_preference" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_quoted_wait_minutes" integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_merchant_id UUID;
  v_waitlist_id UUID;
  v_position INTEGER;
  v_calculated_wait INTEGER;
BEGIN
  -- Verify permission
  -- IF NOT has_any_permission(ARRAY['location.waitlist.manage', 'location.tables.manage']) THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Get merchant ID
  v_merchant_id := user_merchant_id();
  
  -- -- Verify location access
  -- IF NOT p_location_id = ANY(user_location_ids()) THEN
  --   RAISE EXCEPTION 'Location access denied';
  -- END IF;

  -- Get current position in queue
  SELECT COUNT(*) + 1 INTO v_position
  FROM public.waitlist
  WHERE location_id = p_location_id AND status = 'waiting';

  -- Calculate estimated wait if not provided
  IF p_quoted_wait_minutes IS NULL THEN
    v_calculated_wait := public.estimate_wait_time(p_location_id, p_party_size);
  ELSE
    v_calculated_wait := p_quoted_wait_minutes;
  END IF;

  -- Create waitlist entry
  INSERT INTO public.waitlist (
    merchant_id, location_id,
    party_name, party_size, phone, email,
    preferred_section, seating_preference, notes,
    quoted_wait_minutes, estimated_ready_at,
    position_in_queue,
    created_by_staff_id
  ) VALUES (
    v_merchant_id, p_location_id,
    p_party_name, p_party_size, p_phone, p_email,
    p_preferred_section, p_seating_preference, p_notes,
    v_calculated_wait, NOW() + (v_calculated_wait || ' minutes')::INTERVAL,
    v_position,
    user_staff_profile_id()
  )
  RETURNING id INTO v_waitlist_id;

  RETURN json_build_object(
    'success', true,
    'waitlist_id', v_waitlist_id,
    'position', v_position,
    'quoted_wait_minutes', v_calculated_wait,
    'estimated_ready_at', NOW() + (v_calculated_wait || ' minutes')::INTERVAL,
    'party_name', p_party_name
  );
END;$$;


