CREATE OR REPLACE FUNCTION "public"."adjust_tips"("p_order_id" "uuid", "p_adjustments" "jsonb", "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_order RECORD;
    v_payment RECORD;
    v_adj RECORD;
    v_payment_id UUID;
    v_new_tip NUMERIC;
    v_old_tip NUMERIC;
    v_adjusted_count INTEGER := 0;
    v_new_order_tip_total NUMERIC;
    v_new_sync_version INTEGER;
BEGIN
    -- ============================================
    -- 1. Validate Order Exists with RLS
    -- ============================================
    SELECT * INTO v_order
    FROM public.orders
    WHERE id = p_order_id
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids())
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found or access denied';
    END IF;

    -- ============================================
    -- 2. Loop Over Adjustments
    -- ============================================
    FOR v_adj IN SELECT * FROM jsonb_array_elements(p_adjustments)
    LOOP
        v_payment_id := (v_adj.value->>'payment_id')::UUID;
        v_new_tip := (v_adj.value->>'new_tip_amount')::NUMERIC;

        -- Fetch payment row with lock
        SELECT * INTO v_payment
        FROM public.order_payments
        WHERE id = v_payment_id
          AND order_id = p_order_id
          AND status = 'captured'
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Payment % not found or not in captured status', v_payment_id;
        END IF;

        -- Capture old tip before update
        v_old_tip := COALESCE(v_payment.tip_amount, 0);

        -- Update payment with new tip
        UPDATE public.order_payments
        SET
            tip_amount = v_new_tip,
            total_amount = amount + v_new_tip,
            original_tip_amount = COALESCE(original_tip_amount, v_old_tip),
            tip_adjusted_at = NOW(),
            tip_adjusted_by = p_staff_id
        WHERE id = v_payment_id;

        -- Log the tip adjustment event
        PERFORM log_payment_event(
            p_payment_id := v_payment_id,
            p_order_id := p_order_id,
            p_location_id := v_order.location_id,
            p_event_type := 'tip_adjusted',
            p_amount := v_payment.amount,
            p_tip_amount := v_new_tip,
            p_previous_status := 'captured',
            p_new_status := 'captured',
            p_psp_reference := v_payment.reference_number,
            p_auth_code := v_payment.authorization_code,
            p_staff_id := p_staff_id,
            p_terminal_id := NULL,
            p_result_code := '00',
            p_response_message := 'Tip adjusted from ' || v_old_tip::TEXT || ' to ' || v_new_tip::TEXT,
            p_raw_response := jsonb_build_object(
                'old_tip_amount', v_old_tip,
                'new_tip_amount', v_new_tip,
                'adjustment_delta', v_new_tip - v_old_tip
            ),
            p_reason := NULL
        );

        v_adjusted_count := v_adjusted_count + 1;
    END LOOP;

    -- ============================================
    -- 3. Recalculate Order Tip Total
    -- ============================================
    SELECT COALESCE(SUM(tip_amount), 0)
    INTO v_new_order_tip_total
    FROM public.order_payments
    WHERE order_id = p_order_id
      AND status != 'void';

    -- ============================================
    -- 4. Update Order
    -- ============================================
    UPDATE public.orders
    SET
        tip_amount = v_new_order_tip_total,
        amount_paid = amount_paid + v_new_order_tip_total,
        updated_at = NOW()
    WHERE id = p_order_id;

    -- ============================================
    -- 5. Increment Sync Version
    -- ============================================
    v_new_sync_version := increment_order_sync_version(p_order_id);

    -- ============================================
    -- 6. Return Result
    -- ============================================
    RETURN jsonb_build_object(
        'success', true,
        'order_id', p_order_id,
        'adjusted_count', v_adjusted_count,
        'new_order_tip_total', v_new_order_tip_total,
        'sync_version', v_new_sync_version
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$$;


ALTER FUNCTION "public"."adjust_tips"("p_order_id" "uuid", "p_adjustments" "jsonb", "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_bulk_reset_pins"("p_merchant_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("staff_profile_id" "uuid", "staff_name" "text", "new_pin" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_admin_user_id text;
  v_staff record;
  v_pin text;
  v_reset_count int := 0;
BEGIN
  IF NOT is_dexapos_admin() THEN
    RAISE EXCEPTION 'Unauthorized: Admin access required';
  END IF;

  v_admin_user_id := current_user_id();

  FOR v_staff IN
    SELECT
      sp.id AS profile_id,
      sp.user_id AS profile_user_id,
      sp.first_name || ' ' || sp.last_name AS full_name,
      lm.location_id AS loc_id
    FROM staff_profiles sp
    JOIN location_members lm ON lm.staff_profile_id = sp.id
    JOIN locations l ON l.id = lm.location_id
    WHERE sp.merchant_id = p_merchant_id
      AND sp.is_active = true
      AND lm.is_active = true
      AND (p_location_id IS NULL OR lm.location_id = p_location_id)
    UNION
    SELECT
      sp.id AS profile_id,
      sp.user_id AS profile_user_id,
      sp.first_name || ' ' || sp.last_name AS full_name,
      lm.location_id AS loc_id
    FROM staff_profiles sp
    JOIN location_members lm ON lm.user_id = sp.user_id
    JOIN locations l ON l.id = lm.location_id
    WHERE sp.merchant_id = p_merchant_id
      AND sp.user_id IS NOT NULL
      AND sp.is_active = true
      AND lm.staff_profile_id IS NULL
      AND lm.is_active = true
      AND (p_location_id IS NULL OR lm.location_id = p_location_id)
  LOOP
    v_pin := lpad(floor(random() * 9000 + 1000)::text, 4, '0');

    UPDATE location_members
    SET
      pin_plain = v_pin,
      pin_hashed = NULL,
      pin_code = v_pin,
      updated_at = NOW()
    WHERE (
        staff_profile_id = v_staff.profile_id
        OR (v_staff.profile_user_id IS NOT NULL AND user_id = v_staff.profile_user_id)
      )
      AND location_id = v_staff.loc_id;

    staff_profile_id := v_staff.profile_id;
    staff_name := v_staff.full_name;
    new_pin := v_pin;
    RETURN NEXT;

    v_reset_count := v_reset_count + 1;
  END LOOP;

  INSERT INTO audit_logs (
    actor_user_id,
    actor_role,
    action,
    action_category,
    severity,
    resource_type,
    resource_id,
    merchant_id,
    location_id,
    metadata
  ) VALUES (
    v_admin_user_id,
    'hq.admin',
    'ADMIN_BULK_RESET_PINS',
    'staff_management',
    'warning',
    'merchant',
    p_merchant_id,
    p_merchant_id,
    p_location_id,
    jsonb_build_object(
      'bulk_reset', true,
      'staff_count', v_reset_count
    )
  );
END;
$$;


ALTER FUNCTION "public"."admin_bulk_reset_pins"("p_merchant_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_unified_staff_view"("p_merchant_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("member_id" "text", "staff_profile_id" "uuid", "user_id" "text", "clerk_user_id" "text", "email" "text", "first_name" "text", "last_name" "text", "display_name" "text", "avatar_url" "text", "phone" "text", "account_type" "text", "is_clerk_user" boolean, "location_assignments" "jsonb", "total_locations" bigint, "primary_location_id" "uuid", "primary_location_name" "text", "overall_is_active" boolean, "member_created_at" timestamp with time zone, "last_updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF NOT is_dexapos_admin() THEN
    RAISE EXCEPTION 'Unauthorized: Admin access required';
  END IF;

  RETURN QUERY
  WITH staff_data AS (
    SELECT
      sp.id AS profile_id,
      sp.user_id,
      u.id AS clerk_user_id,
      sp.email,
      sp.first_name,
      sp.last_name,
      sp.display_name,
      COALESCE(u.avatar_url, sp.avatar_url) AS avatar_url,
      sp.phone,
      sp.account_type,
      sp.is_active AS profile_active,
      sp.created_at,
      sp.updated_at
    FROM staff_profiles sp
    LEFT JOIN users u ON u.id = sp.user_id
    WHERE sp.merchant_id = p_merchant_id
  ),
  location_data AS (
    SELECT
      COALESCE(lm.staff_profile_id, sp_map.id) AS profile_id,
      jsonb_agg(
        jsonb_build_object(
          'location_id', l.id,
          'location_name', l.name,
          'role_code', lm.role_code,
          'role_name', r.name,
          'is_primary', lm.is_primary_location,
          'is_active', lm.is_active,
          'has_pin', (lm.pin_plain IS NOT NULL OR lm.pin_hashed IS NOT NULL OR lm.pin_code IS NOT NULL),
          'pin_code', COALESCE(lm.pin_plain, lm.pin_hashed, lm.pin_code),
          'hourly_rate', lm.hourly_rate,
          'employment_type', lm.employment_type,
          'assigned_at', lm.assigned_at
        ) ORDER BY lm.is_primary_location DESC, l.name
      ) AS assignments,
      COUNT(*)::bigint AS location_count,
      (array_agg(l.id) FILTER (WHERE lm.is_primary_location = true))[1] AS primary_loc_id,
      (array_agg(l.name) FILTER (WHERE lm.is_primary_location = true))[1] AS primary_loc_name,
      BOOL_OR(lm.is_active) AS any_active
    FROM location_members lm
    INNER JOIN locations l ON l.id = lm.location_id
    LEFT JOIN roles r ON r.code = lm.role_code
    LEFT JOIN staff_profiles sp_map
      ON sp_map.user_id = lm.user_id
     AND sp_map.merchant_id = p_merchant_id
    WHERE l.merchant_id = p_merchant_id
      AND (p_location_id IS NULL OR lm.location_id = p_location_id)
      AND COALESCE(lm.staff_profile_id, sp_map.id) IS NOT NULL
    GROUP BY COALESCE(lm.staff_profile_id, sp_map.id)
  )
  SELECT
    m.id::text AS member_id,
    sd.profile_id AS staff_profile_id,
    sd.user_id AS user_id,
    sd.clerk_user_id,
    sd.email,
    sd.first_name,
    sd.last_name,
    sd.display_name,
    sd.avatar_url,
    sd.phone,
    sd.account_type,
    (sd.account_type = 'clerk') AS is_clerk_user,
    COALESCE(ld.assignments, '[]'::jsonb) AS location_assignments,
    COALESCE(ld.location_count, 0) AS total_locations,
    ld.primary_loc_id AS primary_location_id,
    ld.primary_loc_name AS primary_location_name,
    COALESCE(ld.any_active, false) AND sd.profile_active AS overall_is_active,
    m.created_at AS member_created_at,
    m.updated_at AS last_updated_at
  FROM staff_data sd
  LEFT JOIN members m ON m.staff_profile_id = sd.profile_id OR m.user_id = sd.user_id
  LEFT JOIN location_data ld ON ld.profile_id = sd.profile_id
  ORDER BY sd.last_name, sd.first_name;
END;
$$;


ALTER FUNCTION "public"."admin_get_unified_staff_view"("p_merchant_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reset_staff_pin"("p_staff_profile_id" "uuid", "p_location_id" "uuid", "p_custom_pin" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "new_pin" "text", "error_message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
  v_pin text;
  v_staff_name text;
  v_merchant_id uuid;
  v_admin_user_id text;
  v_staff_user_id text;
BEGIN
  IF NOT is_dexapos_admin() THEN
    RETURN QUERY SELECT false, NULL::text, 'Unauthorized: Admin access required'::text;
    RETURN;
  END IF;

  v_admin_user_id := current_user_id();

  SELECT
    sp.first_name || ' ' || sp.last_name,
    sp.merchant_id,
    sp.user_id
  INTO v_staff_name, v_merchant_id, v_staff_user_id
  FROM staff_profiles sp
  JOIN location_members lm
    ON (
      lm.staff_profile_id = sp.id
      OR (sp.user_id IS NOT NULL AND lm.user_id = sp.user_id)
    )
  WHERE sp.id = p_staff_profile_id
    AND lm.location_id = p_location_id;

  IF v_staff_name IS NULL THEN
    RETURN QUERY SELECT false, NULL::text, 'Staff member not found at this location'::text;
    RETURN;
  END IF;

  IF p_custom_pin IS NOT NULL THEN
    IF NOT p_custom_pin ~ '^\d{4,6}$' THEN
      RETURN QUERY SELECT false, NULL::text, 'PIN must be 4-6 digits'::text;
      RETURN;
    END IF;
    v_pin := p_custom_pin;
  ELSE
    v_pin := lpad(floor(random() * 9000 + 1000)::text, 4, '0');
  END IF;

  UPDATE location_members
  SET
    pin_plain = v_pin,
    pin_hashed = NULL,
    pin_code = v_pin,
    updated_at = NOW()
  WHERE (
      staff_profile_id = p_staff_profile_id
      OR (v_staff_user_id IS NOT NULL AND user_id = v_staff_user_id)
    )
    AND location_id = p_location_id;

  INSERT INTO audit_logs (
    actor_user_id,
    actor_role,
    action,
    action_category,
    severity,
    resource_type,
    resource_id,
    resource_name,
    merchant_id,
    location_id,
    metadata
  ) VALUES (
    v_admin_user_id,
    'hq.admin',
    'ADMIN_RESET_PIN',
    'staff_management',
    'warning',
    'staff_profile',
    p_staff_profile_id,
    v_staff_name,
    v_merchant_id,
    p_location_id,
    jsonb_build_object('admin_reset', true)
  );

  RETURN QUERY SELECT true, v_pin, NULL::text;
END;
$_$;


ALTER FUNCTION "public"."admin_reset_staff_pin"("p_staff_profile_id" "uuid", "p_location_id" "uuid", "p_custom_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_toggle_staff_status"("p_staff_profile_id" "uuid", "p_location_id" "uuid", "p_new_status" boolean) RETURNS TABLE("success" boolean, "staff_name" "text", "error_message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_staff_name text;
  v_merchant_id uuid;
BEGIN
  -- Only allow DexaPOS admins
  IF NOT is_dexapos_admin() THEN
    RETURN QUERY SELECT false, NULL::text, 'Unauthorized: Admin access required'::text;
    RETURN;
  END IF;

  -- Get staff info
  SELECT
    sp.first_name || ' ' || sp.last_name,
    sp.merchant_id
  INTO v_staff_name, v_merchant_id
  FROM staff_profiles sp
  JOIN location_members lm ON lm.staff_profile_id = sp.id
  WHERE sp.id = p_staff_profile_id
    AND lm.location_id = p_location_id;

  IF v_staff_name IS NULL THEN
    RETURN QUERY SELECT false, NULL::text, 'Staff member not found at this location'::text;
    RETURN;
  END IF;

  -- Update status
  UPDATE location_members
  SET
    is_active = p_new_status,
    updated_at = NOW()
  WHERE staff_profile_id = p_staff_profile_id
    AND location_id = p_location_id;

  -- Removed internal logging.

  RETURN QUERY SELECT true, v_staff_name, NULL::text;
END;
$$;


ALTER FUNCTION "public"."admin_toggle_staff_status"("p_staff_profile_id" "uuid", "p_location_id" "uuid", "p_new_status" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_course"("p_session_id" "uuid", "p_fire_course" boolean DEFAULT true, "p_notes" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_current_course INTEGER;
  v_total_courses INTEGER;
  v_event_type session_event_type;
BEGIN
  -- Get current course info
  SELECT current_course, total_courses
  INTO v_current_course, v_total_courses
  FROM public.table_sessions
  WHERE id = p_session_id
    AND is_active = TRUE
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found';
  END IF;

  -- Advance course
  v_current_course := v_current_course + 1;

  UPDATE public.table_sessions
  SET current_course = v_current_course, updated_at = NOW()
  WHERE id = p_session_id;

  -- Record event
  v_event_type := CASE v_current_course
    WHEN 1 THEN 'appetizers_fired'::session_event_type
    WHEN 2 THEN 'mains_fired'::session_event_type
    WHEN 3 THEN 'desserts_fired'::session_event_type
    ELSE 'custom'::session_event_type
  END;

  IF p_fire_course THEN
    INSERT INTO public.table_session_events (
      session_id, event_type, notes,
      event_data, triggered_by_staff_id, triggered_by_user_id
    ) VALUES (
      p_session_id, v_event_type, p_notes,
      jsonb_build_object('course_number', v_current_course),
      user_staff_profile_id(), get_my_claim('sub')
    );
  END IF;

  RETURN json_build_object(
    'success', true,
    'session_id', p_session_id,
    'current_course', v_current_course,
    'total_courses', v_total_courses,
    'is_final_course', v_current_course >= v_total_courses
  );
END;
$$;


