CREATE OR REPLACE FUNCTION "public"."app_set_location_price"("p_location_id" "uuid", "p_vendor_id" "uuid", "p_inventory_item_id" "uuid", "p_price" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Ensure link exists
    INSERT INTO location_vendors (location_id, vendor_id)
    VALUES (p_location_id, p_vendor_id)
    ON CONFLICT (location_id, vendor_id) DO NOTHING;

    -- Upsert pricing
    INSERT INTO location_vendor_pricing (location_id, vendor_id, inventory_item_id, unit_cost)
    VALUES (p_location_id, p_vendor_id, p_inventory_item_id, p_price)
    ON CONFLICT (location_id, vendor_id, inventory_item_id)
    DO UPDATE SET unit_cost = EXCLUDED.unit_cost, last_updated = NOW();
END;
$$;


