CREATE OR REPLACE FUNCTION "public"."app_upsert_inventory_item"("p_location_id" "uuid", "p_item_id" "uuid", "p_name" "text", "p_sku" "text", "p_category" "text", "p_unit_type" "text", "p_cost" numeric, "p_is_global" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_merchant_id UUID;
    v_new_item_id UUID;
    v_target_location_id UUID;
BEGIN
    SELECT merchant_id INTO v_merchant_id FROM locations WHERE id = p_location_id;
    
    -- Determine location scope
    IF p_is_global THEN
        v_target_location_id := NULL;
    ELSE
        v_target_location_id := p_location_id;
    END IF;

    IF p_item_id IS NULL THEN
        -- INSERT
        INSERT INTO inventory_items (
            merchant_id, location_id, name, sku, category, unit_type, cost_per_unit
        ) VALUES (
            v_merchant_id, v_target_location_id, p_name, p_sku, p_category, p_unit_type, p_cost
        ) RETURNING id INTO v_new_item_id;
    ELSE
        -- UPDATE
        UPDATE inventory_items SET
            name = p_name,
            sku = p_sku,
            category = p_category,
            unit_type = p_unit_type,
            cost_per_unit = p_cost
        WHERE id = p_item_id;
        v_new_item_id := p_item_id;
    END IF;

    RETURN jsonb_build_object('id', v_new_item_id, 'success', true);
END;
$$;


ALTER FUNCTION "public"."app_upsert_inventory_item"("p_location_id" "uuid", "p_item_id" "uuid", "p_name" "text", "p_sku" "text", "p_category" "text", "p_unit_type" "text", "p_cost" numeric, "p_is_global" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_upsert_vendor"("p_location_id" "uuid", "p_vendor_id" "uuid", "p_name" "text", "p_phone" "text", "p_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_merchant_id UUID;
    v_new_vendor_id UUID;
BEGIN
    SELECT merchant_id INTO v_merchant_id FROM locations WHERE id = p_location_id;

    IF p_vendor_id IS NULL THEN
        -- INSERT
        INSERT INTO vendors (merchant_id, name, phone, email)
        VALUES (v_merchant_id, p_name, p_phone, p_email)
        RETURNING id INTO v_new_vendor_id;
        
        -- Auto-link to creating location? Optional but helpful
        INSERT INTO location_vendors (location_id, vendor_id)
        VALUES (p_location_id, v_new_vendor_id);
    ELSE
        -- UPDATE
        UPDATE vendors SET
            name = p_name,
            phone = p_phone,
            email = p_email
        WHERE id = p_vendor_id;
        v_new_vendor_id := p_vendor_id;
    END IF;

    RETURN jsonb_build_object('id', v_new_vendor_id, 'success', true);
END;
$$;


ALTER FUNCTION "public"."app_upsert_vendor"("p_location_id" "uuid", "p_vendor_id" "uuid", "p_name" "text", "p_phone" "text", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_order_discount_to_item"("p_order_id" "uuid", "p_order_item_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_item RECORD;
    v_total_discount NUMERIC := 0;
    v_total_discount_type TEXT;
    v_total_discount_value NUMERIC;
    v_order_subtotal NUMERIC;
    v_item_proportion NUMERIC;
    v_item_discount_amount NUMERIC;
    v_discounted_subtotal NUMERIC;
    v_discounted_cash_subtotal NUMERIC;
    v_new_tax_amount NUMERIC;
    v_new_cash_tax_amount NUMERIC;
BEGIN
    -- Get all active (non-voided) order discounts
    SELECT 
        SUM(od.calculated_amount)
    INTO v_total_discount
    FROM public.order_discounts od
    WHERE od.order_id = p_order_id
      AND od.voided_at IS NULL;
    
    -- If no discount, nothing to do
    IF v_total_discount IS NULL OR v_total_discount <= 0 THEN
        RETURN;
    END IF;
    
    -- Get the item details
    SELECT 
        oi.id,
        oi.quantity,
        oi.unit_price,
        oi.cash_price,
        oi.tax_rate,
        (oi.quantity * oi.unit_price) as item_subtotal,
        (oi.quantity * COALESCE(oi.cash_price, oi.unit_price)) as item_cash_subtotal
    INTO v_item
    FROM public.order_items oi
    WHERE oi.id = p_order_item_id
      AND oi.is_voided = false;
    
    IF v_item IS NULL THEN
        RETURN;
    END IF;
    
    -- Get total order subtotal (sum of all non-voided items, pre-discount)
    SELECT COALESCE(SUM(quantity * unit_price), 0)
    INTO v_order_subtotal
    FROM public.order_items
    WHERE order_id = p_order_id
      AND is_voided = false;
    
    IF v_order_subtotal <= 0 THEN
        RETURN;
    END IF;
    
    -- Calculate this item's proportion of the order
    v_item_proportion := v_item.item_subtotal / v_order_subtotal;
    
    -- Calculate this item's share of the discount
    v_item_discount_amount := ROUND(v_total_discount * v_item_proportion, 2);
    
    -- Calculate discounted subtotals
    v_discounted_subtotal := v_item.item_subtotal - v_item_discount_amount;
    v_discounted_cash_subtotal := v_item.item_cash_subtotal - 
        ROUND(v_item_discount_amount * v_item.item_cash_subtotal / NULLIF(v_item.item_subtotal, 0), 2);
    
    -- Recalculate tax on discounted amounts
    v_new_tax_amount := ROUND(v_discounted_subtotal * COALESCE(v_item.tax_rate, 0) / 100, 2);
    v_new_cash_tax_amount := ROUND(v_discounted_cash_subtotal * COALESCE(v_item.tax_rate, 0) / 100, 2);
    
    -- Update the item with discount-adjusted values
    UPDATE public.order_items
    SET
        discount_amount = v_item_discount_amount,
        subtotal = v_discounted_subtotal,
        cash_subtotal = v_discounted_cash_subtotal,
        tax_amount = v_new_tax_amount,
        cash_tax_amount = v_new_cash_tax_amount,
        updated_at = now()
    WHERE id = p_order_item_id;
    
END;
$$;


ALTER FUNCTION "public"."apply_order_discount_to_item"("p_order_id" "uuid", "p_order_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_refund_to_payment"("p_payment_id" "uuid", "p_refund_amount" numeric, "p_reversal_type" "public"."reversal_type", "p_return_rrn" "text" DEFAULT NULL::"text", "p_return_auth_code" "text" DEFAULT NULL::"text", "p_return_reference_id" "text" DEFAULT NULL::"text", "p_return_number" "text" DEFAULT NULL::"text", "p_return_reason" "text" DEFAULT NULL::"text", "p_initiated_by" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_payment record;
  v_new_refunded numeric;
  v_new_status payment_status;
BEGIN
  SELECT * INTO v_payment
  FROM order_payments op
  JOIN orders o ON o.id = op.order_id
  WHERE op.id = p_payment_id
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment not found or access denied';
  END IF;

  v_new_refunded := COALESCE(v_payment.refunded_amount, 0) + p_refund_amount;

  IF p_reversal_type = 'void' THEN
    v_new_status := 'void'::payment_status;
  ELSIF v_new_refunded + 0.0001 >= v_payment.amount THEN
    v_new_status := 'refunded'::payment_status;
  ELSE
    v_new_status := 'partially_refunded'::payment_status;
  END IF;

  UPDATE order_payments
  SET refunded_amount = v_new_refunded,
      refunded_at = now(),
      status = v_new_status,
      is_voided = (p_reversal_type = 'void'),
      -- Return/refund tracking fields
      is_returned = true,
      returned_at = now(),
      returned_by = COALESCE(p_initiated_by, returned_by),
      return_amount = v_new_refunded,
      return_rrn = COALESCE(p_return_rrn, return_rrn),
      return_auth_code = COALESCE(p_return_auth_code, return_auth_code),
      return_reference_id = COALESCE(p_return_reference_id, return_reference_id),
      return_number = COALESCE(p_return_number, return_number),
      return_reason = COALESCE(p_return_reason, return_reason)
  WHERE id = p_payment_id;
END;
$$;


ALTER FUNCTION "public"."apply_refund_to_payment"("p_payment_id" "uuid", "p_refund_amount" numeric, "p_reversal_type" "public"."reversal_type", "p_return_rrn" "text", "p_return_auth_code" "text", "p_return_reference_id" "text", "p_return_number" "text", "p_return_reason" "text", "p_initiated_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_shift_swap"("p_request_id" "uuid", "p_manager_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_req record;
BEGIN
    -- 1. Get request details
    SELECT * INTO v_req FROM shift_trade_requests WHERE id = p_request_id;
    
    IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF;
    IF v_req.status != 'pending_manager' THEN RAISE EXCEPTION 'Request is not pending approval'; END IF;

    -- 2. Swap the employees on the actual shifts
    -- Assign Requester's Shift -> Recipient
    UPDATE shifts 
    SET employee_id = v_req.recipient_id, status = 'published'
    WHERE id = v_req.offered_shift_id;

    -- Assign Recipient's Shift -> Requester
    UPDATE shifts 
    SET employee_id = v_req.requester_id, status = 'published'
    WHERE id = v_req.requested_shift_id;

    -- 3. Mark Request as Approved
    UPDATE shift_trade_requests 
    SET status = 'approved', reviewed_by = p_manager_id 
    WHERE id = p_request_id;

    RETURN true;
END;
$$;


ALTER FUNCTION "public"."approve_shift_swap"("p_request_id" "uuid", "p_manager_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_tip_distribution"("p_session_id" "uuid", "p_approved_by" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN

UPDATE tip_distribution_sessions
SET
status='approved',
approved_at=now(),
approved_by=p_approved_by
WHERE id=p_session_id
AND status='calculated';

IF NOT FOUND THEN

RETURN json_build_object(
'success',false,
'error','Session not found or not in calculated status'
);

END IF;

RETURN json_build_object(
'success',true,
'session_id',p_session_id
);

END;
$$;


ALTER FUNCTION "public"."approve_tip_distribution"("p_session_id" "uuid", "p_approved_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_device"("p_device_id" "uuid", "p_new_status" "public"."device_lifecycle_status", "p_to_merchant_id" "uuid" DEFAULT NULL::"uuid", "p_to_location_id" "uuid" DEFAULT NULL::"uuid", "p_tracking_number" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_device                    public.device_inventory%ROWTYPE;
  v_performer_id              text;
  v_assignment_id             uuid;
  v_allowed_transitions       public.device_lifecycle_status[];
  v_target_location_merchant  uuid;
  v_target_merchant_id        uuid;
BEGIN
  IF NOT public.is_dexapos_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only DEXA HQ can assign devices');
  END IF;

  v_performer_id := public.current_user_id();
  IF v_performer_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authenticated user not found');
  END IF;

  SELECT *
  INTO v_device
  FROM public.device_inventory
  WHERE id = p_device_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Device not found');
  END IF;

  IF v_device.status = p_new_status THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format('Device is already in status %s', p_new_status)
    );
  END IF;

  v_allowed_transitions := CASE v_device.status
    WHEN 'in_warehouse'::public.device_lifecycle_status THEN ARRAY['allocated', 'decommissioned', 'lost']::public.device_lifecycle_status[]
    WHEN 'allocated'::public.device_lifecycle_status THEN ARRAY['shipped', 'in_warehouse']::public.device_lifecycle_status[]
    WHEN 'shipped'::public.device_lifecycle_status THEN ARRAY['provisioning', 'in_warehouse', 'lost']::public.device_lifecycle_status[]
    WHEN 'provisioning'::public.device_lifecycle_status THEN ARRAY['deployed', 'in_warehouse', 'in_repair']::public.device_lifecycle_status[]
    WHEN 'deployed'::public.device_lifecycle_status THEN ARRAY['in_repair', 'decommissioned', 'in_warehouse', 'lost']::public.device_lifecycle_status[]
    WHEN 'in_repair'::public.device_lifecycle_status THEN ARRAY['provisioning', 'deployed', 'decommissioned', 'rma', 'in_warehouse']::public.device_lifecycle_status[]
    WHEN 'decommissioned'::public.device_lifecycle_status THEN ARRAY[]::public.device_lifecycle_status[]
    WHEN 'lost'::public.device_lifecycle_status THEN ARRAY['in_warehouse']::public.device_lifecycle_status[]
    WHEN 'rma'::public.device_lifecycle_status THEN ARRAY[]::public.device_lifecycle_status[]
  END;

  IF NOT (p_new_status = ANY (COALESCE(v_allowed_transitions, ARRAY[]::public.device_lifecycle_status[]))) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format('Invalid transition: %s -> %s', v_device.status, p_new_status)
    );
  END IF;

  IF p_to_location_id IS NOT NULL THEN
    SELECT merchant_id
    INTO v_target_location_merchant
    FROM public.locations
    WHERE id = p_to_location_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'Target location not found');
    END IF;
  END IF;

  IF p_to_merchant_id IS NOT NULL
     AND v_target_location_merchant IS NOT NULL
     AND p_to_merchant_id <> v_target_location_merchant THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Target location does not belong to target merchant'
    );
  END IF;

  v_target_merchant_id := COALESCE(p_to_merchant_id, v_target_location_merchant);

  IF p_new_status = 'in_warehouse'::public.device_lifecycle_status
     AND (p_to_merchant_id IS NOT NULL OR p_to_location_id IS NOT NULL) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Warehouse status cannot carry a target merchant or location'
    );
  END IF;

  IF p_new_status IN ('allocated'::public.device_lifecycle_status, 'shipped'::public.device_lifecycle_status)
     AND v_target_merchant_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format('Status %s requires a target merchant', p_new_status)
    );
  END IF;

  IF p_new_status IN ('provisioning'::public.device_lifecycle_status, 'deployed'::public.device_lifecycle_status)
     AND (v_target_merchant_id IS NULL OR p_to_location_id IS NULL) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format('Status %s requires both a target merchant and location', p_new_status)
    );
  END IF;

  INSERT INTO public.device_assignments (
    device_id,
    previous_status,
    new_status,
    from_merchant_id,
    to_merchant_id,
    from_location_id,
    to_location_id,
    performed_by,
    tracking_number,
    reason,
    notes
  )
  VALUES (
    p_device_id,
    v_device.status,
    p_new_status,
    v_device.merchant_id,
    CASE
      WHEN p_new_status = 'in_warehouse'::public.device_lifecycle_status THEN NULL
      ELSE COALESCE(v_target_merchant_id, v_device.merchant_id)
    END,
    v_device.location_id,
    CASE
      WHEN p_new_status = 'in_warehouse'::public.device_lifecycle_status THEN NULL
      ELSE COALESCE(p_to_location_id, v_device.location_id)
    END,
    v_performer_id,
    p_tracking_number,
    p_reason,
    p_notes
  )
  RETURNING id INTO v_assignment_id;

  UPDATE public.device_inventory
  SET
    status = p_new_status,
    merchant_id = CASE
      WHEN p_new_status = 'in_warehouse'::public.device_lifecycle_status THEN NULL
      ELSE COALESCE(v_target_merchant_id, merchant_id)
    END,
    location_id = CASE
      WHEN p_new_status = 'in_warehouse'::public.device_lifecycle_status THEN NULL
      ELSE COALESCE(p_to_location_id, location_id)
    END,
    linked_station_id = CASE
      WHEN p_new_status IN (
        'in_warehouse'::public.device_lifecycle_status,
        'in_repair'::public.device_lifecycle_status,
        'decommissioned'::public.device_lifecycle_status,
        'lost'::public.device_lifecycle_status,
        'rma'::public.device_lifecycle_status
      ) THEN NULL
      ELSE linked_station_id
    END,
    linked_payment_terminal_id = CASE
      WHEN p_new_status IN (
        'in_warehouse'::public.device_lifecycle_status,
        'in_repair'::public.device_lifecycle_status,
        'decommissioned'::public.device_lifecycle_status,
        'lost'::public.device_lifecycle_status,
        'rma'::public.device_lifecycle_status
      ) THEN NULL
      ELSE linked_payment_terminal_id
    END,
    linked_printer_id = CASE
      WHEN p_new_status IN (
        'in_warehouse'::public.device_lifecycle_status,
        'in_repair'::public.device_lifecycle_status,
        'decommissioned'::public.device_lifecycle_status,
        'lost'::public.device_lifecycle_status,
        'rma'::public.device_lifecycle_status
      ) THEN NULL
      ELSE linked_printer_id
    END
  WHERE id = p_device_id;

  RETURN jsonb_build_object(
    'success', true,
    'assignment_id', v_assignment_id,
    'device_id', p_device_id,
    'previous_status', v_device.status,
    'new_status', p_new_status,
    'merchant_id', (
      SELECT merchant_id
      FROM public.device_inventory
      WHERE id = p_device_id
    ),
    'location_id', (
      SELECT location_id
      FROM public.device_inventory
      WHERE id = p_device_id
    )
  );
END;
$$;


ALTER FUNCTION "public"."assign_device"("p_device_id" "uuid", "p_new_status" "public"."device_lifecycle_status", "p_to_merchant_id" "uuid", "p_to_location_id" "uuid", "p_tracking_number" "text", "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_device"("p_device_id" "uuid", "p_new_status" "public"."device_lifecycle_status", "p_to_merchant_id" "uuid", "p_to_location_id" "uuid", "p_tracking_number" "text", "p_reason" "text", "p_notes" "text") IS 'Primary state-transition RPC for the device registry. Validates lifecycle moves, logs the assignment, and updates current ownership atomically.';



CREATE OR REPLACE FUNCTION "public"."assign_reservation_tables"("p_reservation_id" "uuid", "p_table_ids" "uuid"[]) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$BEGIN
  UPDATE public.reservations
  SET assigned_table_ids = p_table_ids, updated_at = NOW()
  WHERE id = p_reservation_id
    AND merchant_id = user_merchant_id();
    -- AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Reservation not found';
  END IF;

  RETURN json_build_object(
    'success', true,
    'reservation_id', p_reservation_id,
    'assigned_table_ids', p_table_ids
  );
END;$$;


ALTER FUNCTION "public"."assign_reservation_tables"("p_reservation_id" "uuid", "p_table_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_activate_merchant_on_first_successful_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$declare
  v_previous_status text;
begin
  if new.merchant_id is null then
    return new;
  end if;

  if coalesce(new.status::text, '') not in ('captured', 'succeeded') then
    return new;
  end if;

  select onboarding_status
  into v_previous_status
  from public.merchants
  where id = new.merchant_id;

  if v_previous_status is null or v_previous_status not in ('created', 'onboarding') then
    return new;
  end if;

  update public.merchants
  set
    onboarding_status = 'active',
    activated_at = coalesce(activated_at, now()),
    onboarding_completed_at = coalesce(onboarding_completed_at, now()),
    updated_at = now()
  where id = new.merchant_id
    and onboarding_status in ('created', 'onboarding');

  if found then
    insert into public.audit_logs (
      action, action_category, severity, status, actor_name, actor_role,
      resource_type, merchant_id, changes, metadata
    )
    values (
      'merchant.status_auto_activated',
      'merchant',
      'info',
      'success',
      'System',
      'system',
      'merchant',
      new.merchant_id,
      jsonb_build_object(
        'before', jsonb_build_object('onboarding_status', v_previous_status),
        'after', jsonb_build_object('onboarding_status', 'active')
      ),
      jsonb_build_object(
        'source', 'order_payments_trigger',
        'auto_activation', true,
        'payment_id', new.id
      )
    );
  end if;

  return new;
end;$$;


ALTER FUNCTION "public"."auto_activate_merchant_on_first_successful_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_create_kds_display"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  has_active_items boolean;
BEGIN
  -- Station becoming KDS → create display
  IF NEW.station_type = 'kds' AND (OLD IS NULL OR OLD.station_type != 'kds') THEN
    -- Reactivate if soft-deleted record exists
    UPDATE kds_displays 
      SET is_active = true, updated_at = now()
      WHERE station_id = NEW.id
      RETURNING true INTO has_active_items;
    
    -- Otherwise create fresh
    IF NOT FOUND THEN
      INSERT INTO kds_displays (station_id, merchant_id, location_id, display_name)
      VALUES (NEW.id, NEW.merchant_id, NEW.location_id, NEW.station_name || ' KDS');
    END IF;
  END IF;

  -- Station leaving KDS → soft-disable, don't delete
  IF OLD IS NOT NULL AND OLD.station_type = 'kds' AND NEW.station_type != 'kds' THEN
    -- Check for pending items
    SELECT EXISTS (
      SELECT 1 FROM kds_item_status kis
      JOIN kds_displays kd ON kd.id = kis.kds_display_id
      WHERE kd.station_id = NEW.id
        AND kis.status IN ('new', 'in_progress')
    ) INTO has_active_items;

    -- Soft-disable the display
    UPDATE kds_displays 
      SET is_active = false, updated_at = now()
      WHERE station_id = NEW.id;

    -- If active items exist, redistribute them
    IF has_active_items THEN
      PERFORM redistribute_kds_items(NEW.id);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_create_kds_display"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."broadcast_order_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$DECLARE
  payload jsonb;
  order_data jsonb;
  order_items_data jsonb;
  order_payments_data jsonb;
  order_refund_items_data jsonb;
  reversals_data jsonb;
  payment_items_data jsonb;


  v_topic text;
  v_location_id uuid;
  v_station_name text;
BEGIN
  -- Get location_id (handle DELETE case)
  v_location_id := COALESCE(NEW.location_id, OLD.location_id);

  IF v_location_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Build topic
  v_topic := 'location:' || v_location_id::text || ':orders';

  -- Build payload based on operation
  IF TG_OP = 'DELETE' THEN
    -- DELETE: Minimal payload (no need to fetch items)
    payload := jsonb_build_object(
      'operation', TG_OP,
      'timestamp', now(),
      'data', jsonb_build_object(
        'order', jsonb_build_object(
          'id', OLD.id,
          'order_number', OLD.order_number,
          'location_id', OLD.location_id,
          'station_id', OLD.station_id
        )
      )
    );
  ELSE
    -- INSERT/UPDATE: Full payload with order_items and modifiers
    -- 1. FETCH STATION NAME ----------------------------------------
    -- We need to look up the name based on the station_id
    SELECT station_name INTO v_station_name
    FROM stations
    WHERE id = NEW.station_id;
    -----------------------------------------------------------------
    -- Fetch order items WITH their modifiers for this order
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        --TODO: Might need to fetch menu_item base price 
        -- THIS LOGIC does not work for the current modifiers calculation locally
        'id', oi.id,
        'menu_item_id', oi.menu_item_id,
        'item_name', oi.item_name,
        'quantity', oi.quantity,
        'unit_price', oi.unit_price,
        'cash_price', oi.cash_price,
        'subtotal', oi.subtotal,
        'cash_subtotal', oi.cash_subtotal,
        'base_card_price', oi.base_card_price,
        'base_cash_price', oi.base_cash_price,
        'tax_amount', oi.tax_amount,
        'cash_tax_amount', oi.cash_tax_amount,
        'discount_amount', COALESCE(oi.discount_amount, 0),
        'item_status', oi.item_status,
        'kitchen_status', oi.kitchen_status,
        'paid_quantity', COALESCE(oi.paid_quantity, 0),
        'refunded_quantity', COALESCE(oi.refunded_quantity, 0),
        'refunded_amount', COALESCE(oi.refunded_amount, 0),
        'course_number', oi.course_number,
        'seat_number', oi.seat_number,
        'is_voided', COALESCE(oi.is_voided, false),
        'is_open_item', COALESCE(oi.is_open_item, false),
        'open_item_name', oi.open_item_name,
        'open_item_price', oi.open_item_price,
        'special_instructions', oi.special_instructions,
        'category_name', oi.category_name,
        'category_id', oi.category_id,
        'prep_station', oi.prep_station,
        'rush', COALESCE(oi.rush, false),
        'is_prioritized', COALESCE(oi.is_prioritized, false),
        'fire_time', oi.fire_time::timestamptz,
        -- Phase 2.5: Include modifiers for this item
        'modifiers', (
          SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
              'modifier_group_id', oim.modifier_group_id,
              'modifier_item_id', oim.modifier_item_id,
              'modifier_group_name', oim.modifier_group_name,
              'modifier_name', oim.modifier_name,
              'price_modifier', oim.price_modifier,
              'quantity', oim.quantity,
              'is_no', COALESCE(oim.is_no, false)
            )
          ), '[]'::jsonb)
          FROM order_item_modifiers oim
          WHERE oim.order_item_id = oi.id
        )
      )
      ORDER BY oi.display_order ASC NULLS LAST, oi.created_at ASC
    ), '[]'::jsonb) INTO order_items_data
    FROM order_items oi
    WHERE oi.order_id = NEW.id
      AND COALESCE(oi.is_voided, false) = false;

     
    -- Fetch order payments for this order
    -- Split into two jsonb_build_object calls to stay under 100-arg limit
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', op.id,
        'order_id', op.order_id,
        'payment_method', op.payment_method,
        'amount', op.amount,
        'tip_amount', COALESCE(op.tip_amount, 0),
        'total_amount', op.total_amount,
        'status', op.status,
        'subtotal_portion', op.subtotal_portion,
        'tax_portion', op.tax_portion,
        'discount_portion', op.discount_portion,
        'amount_tendered', op.amount_tendered,
        'change_given', COALESCE(op.change_given, 0),
        'is_cash_priced', COALESCE(op.is_cash_priced, false),
        'original_amount', op.original_amount,
        'split_portion_index', op.split_portion_index,
        'split_count', op.split_count,
        'covers_items', COALESCE(op.covers_items, ARRAY[]::uuid[]),
        'card_type', op.card_type,
        'card_last_four', op.card_last_four,
        'transaction_id', op.transaction_id,
        'terminal_type', op.terminal_type,
        'is_voided', COALESCE(op.is_voided, false),
        'void_reason', op.void_reason,
        'refunded_amount', COALESCE(op.refunded_amount, 0),
        'refunded_at', op.refunded_at
      ) || jsonb_build_object(
        'captured_at', op.captured_at,
        'authorization_code', op.authorization_code,
        'auth_code', op.auth_code,
        'rrn', op.rrn,
        'batch_number', op.batch_number,
        'dejavoo_batch_number', op.dejavoo_batch_number,
        'dejavoo_invoice_number', op.dejavoo_invoice_number,
        'result_code', op.result_code,
        'entry_mode', op.processor_response->'dejavoo_transaction'->>'entryMode',
        'reference_number', op.reference_number,
        'reference_id', op.reference_number,
        'created_at', op.initiated_at,
        -- Return/refund tracking fields
        'is_returned', COALESCE(op.is_returned, false),
        'returned_at', op.returned_at,
        'returned_by', op.returned_by,
        'return_amount', COALESCE(op.return_amount, 0),
        'return_rrn', op.return_rrn,
        'return_auth_code', op.return_auth_code,
        'return_reference_id', op.return_reference_id,
        'return_number', op.return_number,
        'return_reason', op.return_reason
      )
    ), '[]'::jsonb) INTO order_payments_data
    FROM order_payments op
    WHERE op.order_id = NEW.id
      AND op.status IN ('captured', 'refunded', 'partially_refunded', 'void');
    -- Include refunded/voided payments for history display

    -- Fetch reversals for this order (via payment linkage)
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', r.id,
        'original_payment_id', r.original_payment_id,
        'original_psp_reference', r.original_psp_reference,
        'reversal_reference_id', r.reversal_reference_id,
        'reversal_psp_reference', r.reversal_psp_reference,
        'merchant_id', r.merchant_id,
        'location_id', r.location_id,
        'reversal_type', r.reversal_type,
        'amount', r.amount,
        'reason_code', r.reason_code,
        'reason_description', r.reason_description,
        'status', r.status,
        'result_code', r.result_code,
        'response_message', r.response_message,
        'initiated_by', r.initiated_by,
        'approved_by', r.approved_by,
        'requested_at', r.requested_at,
        'processed_at', r.processed_at,
        'completed_at', r.completed_at,
        'failed_at', r.failed_at,
        'terminal_response', r.terminal_response,
        'emv_data', r.emv_data
      )
    ), '[]'::jsonb) INTO reversals_data
    FROM reversals r
    JOIN order_payments op ON op.id = r.original_payment_id
    WHERE op.order_id = NEW.id;

    -- Fetch refund line items for this order
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', ori.id,
        'reversal_id', ori.reversal_id,
        'order_item_id', ori.order_item_id,
        'order_payment_item_id', ori.order_payment_item_id,
        'quantity_refunded', ori.quantity_refunded,
        'unit_price_refunded', ori.unit_price_refunded,
        'subtotal_refunded', ori.subtotal_refunded,
        'tax_refunded', ori.tax_refunded,
        'total_refunded', ori.total_refunded,
        'refund_reason', ori.refund_reason,
        'refund_reason_detail', ori.refund_reason_detail,
        'return_to_inventory', ori.return_to_inventory,
        'inventory_updated', ori.inventory_updated,
        'created_at', ori.created_at
      )
    ), '[]'::jsonb) INTO order_refund_items_data
    FROM order_refund_items ori
    JOIN order_items oi ON oi.id = ori.order_item_id
    WHERE oi.order_id = NEW.id;


    -- Fetch per-payment item coverage from junction table
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', opi.id,
        'order_payment_id', opi.order_payment_id,
        'order_item_id', opi.order_item_id,
        'quantity_paid', opi.quantity_paid,
        'unit_price_paid', opi.unit_price_paid,
        'subtotal_paid', opi.subtotal_paid,
        'tax_paid', opi.tax_paid
      )
    ), '[]'::jsonb) INTO payment_items_data
    FROM order_payment_items opi
    JOIN order_payments op ON op.id = opi.order_payment_id
    WHERE op.order_id = NEW.id;


    -- Build order_data in parts to avoid 100 argument limit
    -- Part 1: Identifiers and relationships
    order_data := jsonb_build_object(
      'id', NEW.id,
      'order_number', NEW.order_number,
      'display_number', NEW.display_number,
      'external_id', NEW.external_id,
      'merchant_id', NEW.merchant_id,
      'location_id', NEW.location_id,
      'customer_id', NEW.customer_id,
      'created_by_staff_id', NEW.created_by_staff_id,
      'created_by_user_id', NEW.created_by_user_id,
      'assigned_server_id', NEW.assigned_server_id,
      'station_id', NEW.station_id,
      'station_name', v_station_name,
      'order_type', NEW.order_type,
      'order_source', NEW.order_source,
      'split_payment_path', NEW.split_payment_path,
      'status', NEW.status,
      'table_number', NEW.table_number,
      'seat_number', NEW.seat_number,
      'check_status', NEW.check_status
    );

    -- Part 2: Financial totals
    order_data := order_data || jsonb_build_object(
      'subtotal', NEW.subtotal,
      'tax_amount', NEW.tax_amount,
      'tip_amount', NEW.tip_amount,
      'discount_amount', NEW.discount_amount,
      'service_charge', NEW.service_charge,
      'total_amount', NEW.total_amount,
      'card_subtotal', NEW.card_subtotal,
      'card_tax_amount', NEW.card_tax_amount,
      'card_total', NEW.card_total,
      'cash_subtotal', NEW.cash_subtotal,
      'cash_tax_amount', NEW.cash_tax_amount,
      'cash_total', NEW.cash_total,
      'cash_discount_applied', NEW.cash_discount_applied,
      'cash_discount_amount', NEW.cash_discount_amount
    );

    -- Part 3: Effective pricing and payment status
    order_data := order_data || jsonb_build_object(
      'effective_subtotal', NEW.effective_subtotal,
      'effective_tax_amount', NEW.effective_tax_amount,
      'effective_total', NEW.effective_total,
      'payment_pricing_mode', NEW.payment_pricing_mode,
      'payment_status', NEW.payment_status,
      'amount_paid', NEW.amount_paid,
      'amount_due', NEW.amount_due,
      'cash_amount_due', NEW.cash_amount_due
    );

    -- Part 4: Timestamps
    order_data := order_data || jsonb_build_object(
      'created_at', NEW.created_at,
      'updated_at', NEW.updated_at,
      'sent_to_kitchen_at', NEW.sent_to_kitchen_at,
      'started_preparing_at', NEW.started_preparing_at,
      'ready_at', NEW.ready_at,
      'completed_at', NEW.completed_at,
      'cancelled_at', NEW.cancelled_at,
      'voided_at', NEW.voided_at
    );

    -- Part 5: Void info, sync info, order items, and payments
    order_data := order_data || jsonb_build_object(
      'voided_by', NEW.voided_by,
      'void_reason', NEW.void_reason,
      'cancellation_reason', NEW.cancellation_reason,
      'sync_version', NEW.sync_version,
      'is_offline', NEW.is_offline,
      'order_items', order_items_data,
      'order_payments', order_payments_data,
      'reversals', reversals_data,
      'order_refund_items', order_refund_items_data,
      'payment_items', payment_items_data
    );

    -- Build final payload
    payload := jsonb_build_object(
      'operation', TG_OP,
      'timestamp', now(),
      'data', jsonb_build_object(
        'order', order_data
      )
    );
  END IF;

  -- RAISE LOG 'Active Order %', payload; 
  RAISE LOG 'Broadcasting order for location %', v_topic;
  RAISE LOG 'Broadcasting order for location %', payload;

  -- Broadcast using Supabase Realtime
  PERFORM realtime.send(
    payload,
    TG_OP,
    v_topic,
    true
  );

  RETURN NULL;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'broadcast_order_changes failed: %', SQLERRM;
  RETURN NULL;
END;$$;


ALTER FUNCTION "public"."broadcast_order_changes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."broadcast_order_changes"() IS 'Broadcasts order changes to Supabase Realtime with station_id, order_items, and modifiers for remote order management.';



CREATE OR REPLACE FUNCTION "public"."broadcast_order_item_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_order_id UUID;
BEGIN
  -- Get the order ID from the changed item
  v_order_id := COALESCE(NEW.order_id, OLD.order_id);

  IF v_order_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Touch the parent order to trigger its broadcast
  -- This causes broadcast_order_changes() to fire with fresh item data
  
  UPDATE orders
  SET updated_at = NOW()
  WHERE id = v_order_id;

  RETURN COALESCE(NEW, OLD);

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'broadcast_order_item_changes failed: %', SQLERRM;
  RETURN COALESCE(NEW, OLD);
END;$$;


ALTER FUNCTION "public"."broadcast_order_item_changes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."broadcast_order_item_changes"() IS 'Cascades order_item changes to parent order for broadcast. Implements order-level refresh strategy.';



CREATE OR REPLACE FUNCTION "public"."broadcast_order_item_modifier_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_id UUID;
BEGIN
  -- Get order_id via the parent order_item
  SELECT oi.order_id INTO v_order_id
  FROM order_items oi
  WHERE oi.id = COALESCE(NEW.order_item_id, OLD.order_item_id);

  -- Touch the parent order to trigger its broadcast
  IF v_order_id IS NOT NULL THEN
    UPDATE orders
    SET updated_at = NOW()
    WHERE id = v_order_id;
  END IF;

  RETURN COALESCE(NEW, OLD);

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'broadcast_order_item_modifier_changes failed: %', SQLERRM;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."broadcast_order_item_modifier_changes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."broadcast_order_item_modifier_changes"() IS 'Cascades order_item_modifier changes to parent order for broadcast. Ensures modifiers sync to all devices.';



CREATE OR REPLACE FUNCTION "public"."broadcast_session_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  session_record RECORD;
  payload jsonb;
BEGIN
  -- Get session details
  SELECT ts.location_id, ts.id as session_id
  INTO session_record
  FROM public.table_sessions ts
  WHERE ts.id = NEW.session_id;

  IF session_record IS NULL THEN
    RETURN NULL;
  END IF;

  payload := jsonb_build_object(
    'id', NEW.id,
    'session_id', NEW.session_id,
    'event_type', NEW.event_type,
    'event_data', NEW.event_data,
    'triggered_by_user_id', NEW.triggered_by_user_id,
    'triggered_by_system', NEW.triggered_by_system,
    'occurred_at', NEW.occurred_at,
    'minutes_since_previous', NEW.minutes_since_previous,
    'notes', NEW.notes
  );

  -- Broadcast to location channel (all staff see events)
  PERFORM realtime.send(
      payload,
      'SESSION_EVENT'
      'location:' || session_record.location_id::text || ':tables',
      'private', true
  );

  -- Also broadcast to session-specific channel for detail views
  PERFORM realtime.send(
     payload,
     NEW.event_type::text,
     'session:' || session_record.session_id::text || ':events', true
  );

  -- PERFORM realtime.send(
  --   payload,           -- payload (jsonb)
  --   TG_OP,             -- event (text) 
  --   v_topic,           -- topic (text)
  --   true               -- private (boolean)
  -- );


  RETURN NULL;
END;$$;


