CREATE OR REPLACE FUNCTION "public"."bulk_update_order_item_status"("p_order_item_ids" "uuid"[], "p_status" "text", "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_affected_order_ids UUID[];
  v_result JSONB;
BEGIN
  -- Update order items with appropriate timestamps
  UPDATE order_items
  SET
    kitchen_status = p_status,
    updated_at = NOW(),
    -- Set fire_time when status is 'sent', or when 'preparing' and not yet set (2-step mode)
    fire_time = CASE
      WHEN p_status = 'sent' THEN NOW()
      WHEN p_status = 'preparing' AND fire_time IS NULL THEN NOW()
      ELSE fire_time
    END,
    -- Set sent_to_kitchen_at for 'sent' or 'preparing' (COALESCE preserves existing)
    sent_to_kitchen_at = CASE
      WHEN p_status IN ('sent', 'preparing')
        THEN COALESCE(sent_to_kitchen_at, NOW())
      ELSE sent_to_kitchen_at
    END,
    -- Set started_preparing_at when status is 'preparing'
    started_preparing_at = CASE
      WHEN p_status = 'preparing'
        THEN COALESCE(started_preparing_at, NOW())
      ELSE started_preparing_at
    END,
    -- Set completed_at when status is 'ready' or 'served'
    completed_at = CASE
      WHEN p_status IN ('ready', 'served')
        THEN COALESCE(completed_at, NOW())
      ELSE completed_at
    END
  WHERE id = ANY(p_order_item_ids);

  -- Sync kds_item_status when items progress
  IF p_status = 'preparing' THEN
    UPDATE kds_item_status
    SET started_at = COALESCE(started_at, NOW())
    WHERE order_item_id = ANY(p_order_item_ids)
      AND status = 'pending';
  END IF;

  -- IF p_status IN ('ready', 'served') THEN
  --   UPDATE kds_item_status
  --   SET status = 'completed',
  --       completed_at = COALESCE(completed_at, NOW()),
  --       bumped_at = NOW(),
  --       bumped_by = p_staff_id
  --   WHERE order_item_id = ANY(p_order_item_ids)
  --     AND status NOT IN ('cancelled', 'completed');
  -- END IF;


  -- 'ready' = done cooking, keep visible on KDS displays
  IF p_status = 'ready' THEN
    UPDATE kds_item_status
    SET completed_at = COALESCE(completed_at, NOW())
    WHERE order_item_id = ANY(p_order_item_ids)
      AND status NOT IN ('cancelled', 'completed');
  END IF;

  -- 'served' = picked up, remove from KDS displays
  IF p_status = 'served' THEN
    UPDATE kds_item_status
    SET status = 'completed',
        completed_at = COALESCE(completed_at, NOW()),
        bumped_at = NOW(),
        bumped_by = p_staff_id
    WHERE order_item_id = ANY(p_order_item_ids)
      AND status NOT IN ('cancelled', 'completed');
  END IF;


  -- Get affected order IDs
  SELECT ARRAY_AGG(DISTINCT order_id) INTO v_affected_order_ids
  FROM order_items
  WHERE id = ANY(p_order_item_ids);

  -- Single atomic UPDATE: timestamps + status derivation + sync_version
  -- Only auto-transition orders in kitchen-related statuses (sent_to_kitchen, preparing).
  -- Never auto-set 'completed' (payment-gated).
  IF v_affected_order_ids IS NOT NULL THEN
    UPDATE orders o
    SET
      -- Timestamps: also set sent_to_kitchen_at for 'preparing' (2-step mode)
      sent_to_kitchen_at = CASE
        WHEN p_status IN ('sent', 'preparing') THEN COALESCE(o.sent_to_kitchen_at, NOW())
        ELSE o.sent_to_kitchen_at
      END,
      started_preparing_at = CASE
        WHEN p_status = 'preparing' THEN COALESCE(o.started_preparing_at, NOW())
        ELSE o.started_preparing_at
      END,
      ready_at = CASE
        WHEN agg.all_ready_or_served AND o.status::text IN ('sent_to_kitchen', 'preparing')
          THEN COALESCE(o.ready_at, NOW())
        ELSE o.ready_at
      END,
      -- Status derivation (only for kitchen-related statuses, skip when just sending items)
      status = CASE
        WHEN p_status = 'sent' THEN o.status
        WHEN o.status::text NOT IN ('sent_to_kitchen', 'preparing') THEN o.status
        WHEN agg.all_ready_or_served THEN 'ready'::order_status
        WHEN agg.any_beyond_sent THEN 'preparing'::order_status
        ELSE o.status
      END,
      -- Bump sync_version for optimistic locking
      sync_version = COALESCE(o.sync_version, 0) + 1,
      updated_at = NOW()
    FROM (
      SELECT
        oi.order_id,
        bool_and(oi.kitchen_status IN ('ready', 'served')) AS all_ready_or_served,
        bool_or(oi.kitchen_status IN ('preparing', 'ready', 'served')) AS any_beyond_sent
      FROM order_items oi
      WHERE oi.order_id = ANY(v_affected_order_ids)
        AND COALESCE(oi.is_voided, false) = false
        AND oi.kitchen_status IS NOT NULL
      GROUP BY oi.order_id
    ) agg
    WHERE o.id = agg.order_id;
  END IF;

  v_result := jsonb_build_object(
    'updated_count', array_length(p_order_item_ids, 1),
    'affected_order_ids', to_jsonb(v_affected_order_ids)
  );

  RETURN v_result;
END;$$;


ALTER FUNCTION "public"."bulk_update_order_item_status"("p_order_item_ids" "uuid"[], "p_status" "text", "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_event_timing"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  last_event_time TIMESTAMPTZ;
BEGIN
  SELECT occurred_at INTO last_event_time
  FROM public.table_session_events
  WHERE session_id = NEW.session_id
    AND occurred_at < NEW.occurred_at
  ORDER BY occurred_at DESC
  LIMIT 1;
  
  IF last_event_time IS NOT NULL THEN
    NEW.minutes_since_previous := EXTRACT(EPOCH FROM (NEW.occurred_at - last_event_time)) / 60;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_event_timing"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_item_totals"("p_quantity" integer, "p_unit_price" numeric, "p_cash_price" numeric, "p_tax_rate" numeric, "p_discount_amount" numeric DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
DECLARE
    v_gross_subtotal NUMERIC;
    v_gross_cash_subtotal NUMERIC;
    v_net_subtotal NUMERIC;
    v_net_cash_subtotal NUMERIC;
    v_cash_discount_amount NUMERIC;
    v_tax_amount NUMERIC;
    v_cash_tax_amount NUMERIC;
BEGIN
    -- Gross subtotals (before discount)
    v_gross_subtotal := p_quantity * p_unit_price;
    v_gross_cash_subtotal := p_quantity * COALESCE(p_cash_price, p_unit_price);
    
    -- Calculate proportional cash discount
    -- If card gets $X discount, cash gets $X × (cash_price / card_price)
    IF p_unit_price > 0 AND p_discount_amount > 0 THEN
        v_cash_discount_amount := ROUND(
            p_discount_amount * COALESCE(p_cash_price, p_unit_price) / p_unit_price, 
            2
        );
    ELSE
        v_cash_discount_amount := p_discount_amount;
    END IF;
    
    -- Net subtotals (after discount)
    v_net_subtotal := GREATEST(v_gross_subtotal - COALESCE(p_discount_amount, 0), 0);
    v_net_cash_subtotal := GREATEST(v_gross_cash_subtotal - COALESCE(v_cash_discount_amount, 0), 0);
    
    -- Tax on DISCOUNTED amounts (this is the key fix!)
    v_tax_amount := ROUND(v_net_subtotal * COALESCE(p_tax_rate, 0) / 100, 2);
    v_cash_tax_amount := ROUND(v_net_cash_subtotal * COALESCE(p_tax_rate, 0) / 100, 2);
    
    RETURN jsonb_build_object(
        'gross_subtotal', v_gross_subtotal,
        'gross_cash_subtotal', v_gross_cash_subtotal,
        'discount_amount', COALESCE(p_discount_amount, 0),
        'cash_discount_amount', COALESCE(v_cash_discount_amount, 0),
        'subtotal', v_net_subtotal,
        'cash_subtotal', v_net_cash_subtotal,
        'tax_amount', v_tax_amount,
        'cash_tax_amount', v_cash_tax_amount,
        'total', v_net_subtotal + v_tax_amount,
        'cash_total', v_net_cash_subtotal + v_cash_tax_amount
    );
END;
$_$;


ALTER FUNCTION "public"."calculate_item_totals"("p_quantity" integer, "p_unit_price" numeric, "p_cash_price" numeric, "p_tax_rate" numeric, "p_discount_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_order_dual_totals"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_location_id uuid;
    v_merchant_id uuid;
    v_card_subtotal numeric := 0;
    v_cash_subtotal numeric := 0;
    v_card_tax numeric := 0;
    v_cash_tax numeric := 0;
    v_item_discount_total numeric := 0;
    v_service_charge numeric := 0;
    v_tax_rate numeric := 0.08;  -- Default 8% tax rate
    v_cash_discount_rate numeric := 0.04;  -- Default 4% cash discount
BEGIN
    -- Get order context
    SELECT location_id, merchant_id, COALESCE(service_charge, 0)
    INTO v_location_id, v_merchant_id, v_service_charge
    FROM public.orders 
    WHERE id = p_order_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found: %', p_order_id;
    END IF;

    -- ============================================
    -- Calculate subtotals from order items
    -- ============================================
    SELECT 
        -- Card subtotal: unit_price * quantity - discounts
        COALESCE(SUM(
            (oi.unit_price * oi.quantity) - COALESCE(oi.discount_amount, 0)
        ), 0),
        -- Cash subtotal: use cash_price if available, otherwise apply discount rate
        COALESCE(SUM(
            (COALESCE(oi.cash_price, oi.unit_price * (1 - v_cash_discount_rate)) * oi.quantity) 
            - COALESCE(oi.discount_amount, 0)
        ), 0),
        -- Total item-level discounts
        COALESCE(SUM(oi.discount_amount), 0)
    INTO v_card_subtotal, v_cash_subtotal, v_item_discount_total
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id 
      AND oi.is_voided = false;

    -- ============================================
    -- Calculate taxes using default rate
    -- ============================================
    v_card_tax := ROUND(v_card_subtotal * v_tax_rate, 2);
    v_cash_tax := ROUND(v_cash_subtotal * v_tax_rate, 2);

    -- ============================================
    -- Update order with calculated values
    -- ============================================
    UPDATE public.orders SET
        -- Standard columns (already exist)
        subtotal = v_card_subtotal,
        tax_amount = v_card_tax,
        total_amount = v_card_subtotal + v_card_tax + v_service_charge,
        discount_amount = v_item_discount_total,
        amount_due = (v_card_subtotal + v_card_tax + v_service_charge) - COALESCE(amount_paid, 0),
        updated_at = now()
    WHERE id = p_order_id;
    
    -- Return result with dual pricing info
    RETURN jsonb_build_object(
        'success', true,
        'card', jsonb_build_object(
            'subtotal', v_card_subtotal,
            'tax', v_card_tax,
            'service_charge', v_service_charge,
            'total', v_card_subtotal + v_card_tax + v_service_charge
        ),
        'cash', jsonb_build_object(
            'subtotal', v_cash_subtotal,
            'tax', v_cash_tax,
            'service_charge', v_service_charge,
            'total', v_cash_subtotal + v_cash_tax + v_service_charge
        ),
        'discounts', jsonb_build_object(
            'item_level', v_item_discount_total,
            'order_level', 0,
            'total', v_item_discount_total
        ),
        'savings', (v_card_subtotal + v_card_tax) - (v_cash_subtotal + v_cash_tax)
    );
END;
$$;


ALTER FUNCTION "public"."calculate_order_dual_totals"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_order_tax"("p_order_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_location_id uuid;
  v_subtotal NUMERIC(10, 2);
  v_calculated_tax NUMERIC(10, 2);
  v_result JSON;
BEGIN
  -- Verify context
  SELECT location_id, subtotal INTO v_location_id, v_subtotal
  FROM public.orders
  WHERE id = p_order_id AND merchant_id = user_merchant_id() AND location_id = ANY(user_location_ids());
  
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;

  -- Smart Calculation
  SELECT COALESCE(SUM(
    CASE 
        -- 1. Exemption Check (L2 Override -> L1 Global)
        WHEN COALESCE(lio.is_tax_exempt, mi.is_tax_exempt, false) = true THEN 0
        -- 2. Rate Lookup (Location Rate matching Item Category)
        ELSE ROUND(oi.subtotal * (COALESCE(tr.percentage, 0) / 100), 2)
    END
  ), 0) INTO v_calculated_tax
  FROM order_items oi
  JOIN menu_items mi ON mi.id = oi.menu_item_id
  LEFT JOIN location_item_overrides lio ON lio.menu_item_id = mi.id AND lio.location_id = v_location_id
  LEFT JOIN tax_rates tr ON tr.location_id = v_location_id 
      AND tr.tax_category = COALESCE(lio.tax_category, mi.tax_category, 'standard') 
      AND tr.is_active = true
  WHERE oi.order_id = p_order_id AND oi.is_voided != TRUE;

  -- Update Order
  UPDATE public.orders
  SET tax_amount = v_calculated_tax,
      total_amount = subtotal + v_calculated_tax + COALESCE(service_charge, 0) - COALESCE(discount_amount, 0),
      amount_due = (subtotal + v_calculated_tax + COALESCE(service_charge, 0) - COALESCE(discount_amount, 0)) - COALESCE(amount_paid, 0),
      updated_at = NOW()
  WHERE id = p_order_id;
  
  SELECT json_build_object('success', true, 'tax_amount', v_calculated_tax) INTO v_result;
  RETURN v_result;
END;$$;


ALTER FUNCTION "public"."calculate_order_tax"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_order_totals_fast"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$DECLARE
v_card_subtotal numeric;
v_cash_subtotal numeric;
v_card_tax numeric;
v_cash_tax numeric;
v_discount numeric;
v_service_charge numeric;
v_amount_paid numeric;
v_original_card_subtotal numeric;
v_original_cash_subtotal numeric;
v_unpaid_card_total numeric;
v_unpaid_cash_total numeric;
v_effective_paid numeric;
v_payment_refunded numeric;
v_card_total_calc numeric;
v_payment_voided numeric;
v_payment_based_due numeric;
v_custom_refund_balance numeric;
v_order record;
BEGIN
SELECT 
    COALESCE(SUM(quantity * unit_price), 0),
    COALESCE(SUM(quantity * COALESCE(cash_price, unit_price)), 0),
    COALESCE(SUM(discount_amount), 0)
INTO v_original_card_subtotal, v_original_cash_subtotal, v_discount
FROM public.order_items
WHERE order_id = p_order_id AND is_voided = false;

SELECT 
    COALESCE(SUM(subtotal), 0),
    COALESCE(SUM(cash_subtotal), 0),
    COALESCE(SUM(tax_amount), 0),
    COALESCE(SUM(cash_tax_amount), 0)
INTO v_card_subtotal, v_cash_subtotal, v_card_tax, v_cash_tax
FROM public.order_items
WHERE order_id = p_order_id AND is_voided = false;

SELECT *
INTO v_order
FROM public.orders WHERE id = p_order_id;

v_service_charge := COALESCE(v_order.service_charge, 0);
v_amount_paid := COALESCE(v_order.amount_paid, 0);

SELECT
    COALESCE(SUM(
        ROUND(subtotal * (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0))::NUMERIC / NULLIF(quantity, 0), 2) +
        ROUND(tax_amount * (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0))::NUMERIC / NULLIF(quantity, 0), 2)
    ), 0),
    COALESCE(SUM(
        ROUND(cash_subtotal * (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0))::NUMERIC / NULLIF(quantity, 0), 2) +
        ROUND(cash_tax_amount * (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0))::NUMERIC / NULLIF(quantity, 0), 2)
    ), 0)
INTO v_unpaid_card_total, v_unpaid_cash_total
FROM public.order_items
WHERE order_id = p_order_id
    AND is_voided = false
    AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

SELECT
    COALESCE(SUM(
        COALESCE(original_amount, amount)
        - COALESCE(refunded_amount, 0) * COALESCE(original_amount, amount) / NULLIF(amount, 0)
    ), 0),
    COALESCE(SUM(COALESCE(refunded_amount, 0)), 0)
INTO v_effective_paid, v_payment_refunded
FROM public.order_payments
WHERE order_id = p_order_id
    AND status IN ('captured', 'partially_refunded', 'refunded')
    AND is_voided = false;

SELECT COALESCE(SUM(COALESCE(original_amount, amount)), 0)
INTO v_payment_voided
FROM public.order_payments
WHERE order_id = p_order_id
  AND (status = 'void' OR is_voided = true);


v_card_total_calc := v_card_subtotal + v_card_tax + v_service_charge;

v_payment_based_due := GREATEST(v_card_total_calc - v_effective_paid, 0);

v_custom_refund_balance := GREATEST(v_payment_based_due - v_unpaid_card_total, 0);

IF v_order.payment_status = 'paid' AND v_payment_refunded = 0 AND v_payment_voided = 0 THEN
    v_unpaid_card_total := 0;
    v_unpaid_cash_total := 0;
ELSE
    v_unpaid_card_total := v_unpaid_card_total + v_custom_refund_balance;
    v_unpaid_cash_total := v_unpaid_cash_total + v_custom_refund_balance;
END IF;

UPDATE public.orders SET
    -- Original subtotals (pre-discount) for reference
    card_subtotal = v_original_card_subtotal,
    cash_subtotal = v_original_cash_subtotal,
    
    -- Discount amount
    discount_amount = v_discount,
    
    -- Effective values (after discount)
    effective_subtotal = v_card_subtotal,
    effective_tax_amount = v_card_tax,
    effective_total = v_card_subtotal + v_card_tax + v_service_charge,
    
    -- Tax amounts (on discounted subtotals)
    card_tax_amount = v_card_tax,
    cash_tax_amount = v_cash_tax,
    
    -- Totals (discounted subtotal + tax + service)
    card_total = v_card_subtotal + v_card_tax + v_service_charge,
    cash_total = v_cash_subtotal + v_cash_tax + v_service_charge,
    
    -- Legacy fields
    subtotal = v_card_subtotal,
    tax_amount = v_card_tax,
    total_amount = v_card_subtotal + v_card_tax + v_service_charge,
    
    -- Amount due (calculated from UNPAID items, not total - paid)
    amount_due = v_unpaid_card_total,
    cash_amount_due = v_unpaid_cash_total,
    
    updated_at = now()
WHERE id = p_order_id;

RETURN jsonb_build_object(
    'success', true,
    'card_subtotal', v_original_card_subtotal,
    'effective_subtotal', v_card_subtotal,
    'discount_amount', v_discount,
    'card_tax', v_card_tax,
    'card_total', v_card_subtotal + v_card_tax + v_service_charge,
    'cash_total', v_cash_subtotal + v_cash_tax + v_service_charge,
    'amount_due', v_unpaid_card_total,
    'cash_amount_due', v_unpaid_cash_total
);
END;$$;


ALTER FUNCTION "public"."calculate_order_totals_fast"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_tip_distribution"("p_location_id" "uuid", "p_merchant_id" "uuid", "p_session_date" "date", "p_shift_period" "text" DEFAULT 'full_day'::"text", "p_calculated_by" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_session_id       UUID;
  v_total_collected   NUMERIC;
  v_total_distributed NUMERIC;
  v_total_pooled      NUMERIC;
  v_total_tipouts     NUMERIC;
  v_pool              RECORD;
  v_rule              RECORD;
  v_role_share        RECORD;
  v_pool_total        NUMERIC;
  v_role_count        INTEGER;
  v_total_hours       NUMERIC;
  v_total_points      NUMERIC;
  v_tipout_total      NUMERIC;
  v_giver_count       INTEGER;
  v_receiver_count    INTEGER;
BEGIN

  -- Advisory lock to prevent concurrent runs for same location/date
  PERFORM pg_advisory_xact_lock(
    hashtext(p_location_id::text || p_session_date::text)
  );

  -- =========================================================
  -- STEP 1: CREATE OR RESET SESSION
  -- =========================================================
  INSERT INTO tip_distribution_sessions(
    merchant_id, location_id, session_date, shift_period
  )
  VALUES(p_merchant_id, p_location_id, p_session_date, p_shift_period)
  ON CONFLICT(location_id, session_date, shift_period)
  DO UPDATE SET updated_at = now(), status = 'draft'
  RETURNING id INTO v_session_id;

  DELETE FROM tip_distribution_details WHERE session_id = v_session_id;

  -- =========================================================
  -- STEP 2: POPULATE EMPLOYEE DATA FROM DAILY TIPS
  -- =========================================================
  INSERT INTO tip_distribution_details(
    session_id, staff_profile_id, role_code,
    hours_worked, gross_sales,
    charged_tips, cash_tips, individual_tips_earned
  )
  SELECT
    v_session_id,
    edt.staff_profile_id,
    lm.role_code,
    COALESCE(edt.hours_worked, 0),
    COALESCE(edt.gross_sales, 0),
    COALESCE(edt.charged_tips, 0),
    COALESCE(edt.cash_tips_declared, 0),
    COALESCE(edt.charged_tips, 0) + COALESCE(edt.cash_tips_declared, 0)
  FROM employee_daily_tips edt
  JOIN location_members lm
    ON lm.staff_profile_id = edt.staff_profile_id
    AND lm.location_id = edt.location_id
  WHERE edt.location_id = p_location_id
    AND edt.shift_date = p_session_date;

  -- =========================================================
  -- STEP 3: CALCULATE TOTAL COLLECTED
  -- =========================================================
  SELECT COALESCE(SUM(individual_tips_earned), 0)
  INTO v_total_collected
  FROM tip_distribution_details
  WHERE session_id = v_session_id;

  -- =========================================================
  -- STEP 4: CREATE TEMP TABLE FOR PER‑POOL CONTRIBUTIONS
  -- =========================================================
  CREATE TEMP TABLE temp_pool_contrib (
    pool_id UUID,
    staff_profile_id UUID,
    amount NUMERIC
  ) ON COMMIT DROP;

  -- =========================================================
  -- STEP 5: PROCESS EACH ACTIVE TIP POOL – CONTRIBUTIONS
  -- =========================================================
  FOR v_pool IN
    SELECT * FROM tip_pool_configs
    WHERE location_id = p_location_id
      AND is_active = true
      AND effective_date <= p_session_date
      AND (end_date IS NULL OR end_date >= p_session_date)
  LOOP
    -- Insert contributions into temp table (per pool)
    IF v_pool.tip_source = 'charged_tips' THEN
      INSERT INTO temp_pool_contrib (pool_id, staff_profile_id, amount)
      SELECT v_pool.id, dd.staff_profile_id,
             ROUND(dd.charged_tips * (v_pool.source_percentage / 100.0), 2)
      FROM tip_distribution_details dd
      WHERE dd.session_id = v_session_id
        AND dd.role_code = ANY(v_pool.contributing_role_codes);

    ELSIF v_pool.tip_source = 'all_tips' THEN
      INSERT INTO temp_pool_contrib (pool_id, staff_profile_id, amount)
      SELECT v_pool.id, dd.staff_profile_id,
             ROUND(dd.individual_tips_earned * (v_pool.source_percentage / 100.0), 2)
      FROM tip_distribution_details dd
      WHERE dd.session_id = v_session_id
        AND dd.role_code = ANY(v_pool.contributing_role_codes);

    ELSIF v_pool.tip_source = 'cash_only' THEN
      INSERT INTO temp_pool_contrib (pool_id, staff_profile_id, amount)
      SELECT v_pool.id, dd.staff_profile_id,
             ROUND(dd.cash_tips * (v_pool.source_percentage / 100.0), 2)
      FROM tip_distribution_details dd
      WHERE dd.session_id = v_session_id
        AND dd.role_code = ANY(v_pool.contributing_role_codes);
    END IF;
  END LOOP;

  -- =========================================================
  -- STEP 6: UPDATE tip_pool_contributed FROM TEMP TABLE
  -- =========================================================
  UPDATE tip_distribution_details dd
  SET tip_pool_contributed = COALESCE((
    SELECT SUM(amount) FROM temp_pool_contrib t
    WHERE t.staff_profile_id = dd.staff_profile_id
  ), 0)
  WHERE session_id = v_session_id;

  -- =========================================================
  -- STEP 7: REDISTRIBUTE EACH POOL (accumulate receipts)
  -- =========================================================
  FOR v_pool IN
    SELECT * FROM tip_pool_configs
    WHERE location_id = p_location_id
      AND is_active = true
      AND effective_date <= p_session_date
      AND (end_date IS NULL OR end_date >= p_session_date)
  LOOP
    -- Get total contributed to this pool from the temp table
    SELECT COALESCE(SUM(amount), 0) INTO v_pool_total
    FROM temp_pool_contrib
    WHERE pool_id = v_pool.id;

    -- Skip if nothing to distribute
    IF v_pool_total = 0 THEN
      CONTINUE;
    END IF;

    -- ----- DISTRIBUTION BY METHOD -----
    IF v_pool.distribution_method = 'percentage' THEN
      -- Percentage split by role, equally among employees of that role
      FOR v_role_share IN
        SELECT prs.role_code, prs.share_percentage
        FROM tip_pool_role_shares prs
        WHERE prs.tip_pool_config_id = v_pool.id
          AND prs.is_eligible = true
          AND prs.share_percentage IS NOT NULL
          AND prs.share_percentage > 0
      LOOP
        SELECT COUNT(*) INTO v_role_count
        FROM tip_distribution_details
        WHERE session_id = v_session_id
          AND role_code = v_role_share.role_code;

        IF v_role_count > 0 THEN
          UPDATE tip_distribution_details
          SET tip_pool_received = tip_pool_received +
            ROUND((v_pool_total * (v_role_share.share_percentage / 100.0)) / v_role_count, 2)
          WHERE session_id = v_session_id
            AND role_code = v_role_share.role_code;
        END IF;
      END LOOP;

    ELSIF v_pool.distribution_method = 'equal_split' THEN
      -- Equal split only among employees whose roles are eligible for this pool
      SELECT COUNT(*) INTO v_role_count
      FROM tip_distribution_details dd
      WHERE dd.session_id = v_session_id
        AND EXISTS (
          SELECT 1 FROM tip_pool_role_shares prs
          WHERE prs.tip_pool_config_id = v_pool.id
            AND prs.role_code = dd.role_code
            AND prs.is_eligible = true
        );

      IF v_role_count > 0 THEN
        UPDATE tip_distribution_details dd
        SET tip_pool_received = tip_pool_received +
          ROUND(v_pool_total / v_role_count, 2)
        WHERE dd.session_id = v_session_id
          AND EXISTS (
            SELECT 1 FROM tip_pool_role_shares prs
            WHERE prs.tip_pool_config_id = v_pool.id
              AND prs.role_code = dd.role_code
              AND prs.is_eligible = true
          );
      END IF;

    ELSIF v_pool.distribution_method = 'hours_weighted' THEN
      -- Hours‑weighted only for eligible roles
      SELECT COALESCE(SUM(dd.hours_worked), 0) INTO v_total_hours
      FROM tip_distribution_details dd
      WHERE dd.session_id = v_session_id
        AND EXISTS (
          SELECT 1 FROM tip_pool_role_shares prs
          WHERE prs.tip_pool_config_id = v_pool.id
            AND prs.role_code = dd.role_code
            AND prs.is_eligible = true
        );

      IF v_total_hours > 0 THEN
        UPDATE tip_distribution_details dd
        SET tip_pool_received = tip_pool_received +
          ROUND(v_pool_total * (dd.hours_worked / v_total_hours), 2)
        WHERE dd.session_id = v_session_id
          AND EXISTS (
            SELECT 1 FROM tip_pool_role_shares prs
            WHERE prs.tip_pool_config_id = v_pool.id
              AND prs.role_code = dd.role_code
              AND prs.is_eligible = true
          );
      END IF;

    ELSIF v_pool.distribution_method = 'points' THEN
      -- Points‑based: role's points_per_hour * employee's hours
      SELECT COALESCE(SUM(prs.points_per_hour * dd.hours_worked), 0) INTO v_total_points
      FROM tip_distribution_details dd
      JOIN tip_pool_role_shares prs
        ON prs.tip_pool_config_id = v_pool.id
        AND prs.role_code = dd.role_code
        AND prs.is_eligible = true
      WHERE dd.session_id = v_session_id;

      IF v_total_points > 0 THEN
        UPDATE tip_distribution_details dd
        SET tip_pool_received = tip_pool_received +
          ROUND(v_pool_total * ((prs_sub.points_per_hour * dd.hours_worked) / v_total_points), 2)
        FROM tip_pool_role_shares prs_sub
        WHERE dd.session_id = v_session_id
          AND prs_sub.tip_pool_config_id = v_pool.id
          AND prs_sub.role_code = dd.role_code
          AND prs_sub.is_eligible = true;
      END IF;
    END IF;
  END LOOP;

  -- =========================================================
  -- STEP 8: TIP‑OUT RULES (all three types)
  -- =========================================================
  FOR v_rule IN
    SELECT * FROM tip_out_rules
    WHERE location_id = p_location_id
      AND is_active = true
      AND effective_date <= p_session_date
      AND (end_date IS NULL OR end_date >= p_session_date)
  LOOP
    -- How many receivers for this rule?
    SELECT COUNT(*) INTO v_receiver_count
    FROM tip_distribution_details
    WHERE session_id = v_session_id
      AND role_code = v_rule.to_role_code;

    IF v_rule.tip_out_type = 'percentage_of_sales' THEN
      -- Deduct from givers
      UPDATE tip_distribution_details dd
      SET tip_out_given = tip_out_given +
        ROUND(dd.gross_sales * (v_rule.tip_out_value / 100.0), 2)
      WHERE dd.session_id = v_session_id
        AND dd.role_code = v_rule.from_role_code;

      -- Total given (for crediting receivers)
      SELECT COALESCE(SUM(ROUND(dd.gross_sales * (v_rule.tip_out_value / 100.0), 2)), 0)
      INTO v_tipout_total
      FROM tip_distribution_details dd
      WHERE dd.session_id = v_session_id
        AND dd.role_code = v_rule.from_role_code;

      -- Credit receivers equally
      IF v_receiver_count > 0 THEN
        UPDATE tip_distribution_details
        SET tip_out_received = tip_out_received +
          ROUND(v_tipout_total / v_receiver_count, 2)
        WHERE session_id = v_session_id
          AND role_code = v_rule.to_role_code;
      END IF;

    ELSIF v_rule.tip_out_type = 'percentage_of_tips' THEN
      UPDATE tip_distribution_details dd
      SET tip_out_given = tip_out_given +
        ROUND(dd.individual_tips_earned * (v_rule.tip_out_value / 100.0), 2)
      WHERE dd.session_id = v_session_id
        AND dd.role_code = v_rule.from_role_code;

      SELECT COALESCE(SUM(ROUND(dd.individual_tips_earned * (v_rule.tip_out_value / 100.0), 2)), 0)
      INTO v_tipout_total
      FROM tip_distribution_details dd
      WHERE dd.session_id = v_session_id
        AND dd.role_code = v_rule.from_role_code;

      IF v_receiver_count > 0 THEN
        UPDATE tip_distribution_details
        SET tip_out_received = tip_out_received +
          ROUND(v_tipout_total / v_receiver_count, 2)
        WHERE session_id = v_session_id
          AND role_code = v_rule.to_role_code;
      END IF;

    ELSIF v_rule.tip_out_type = 'flat_amount' THEN
      UPDATE tip_distribution_details dd
      SET tip_out_given = tip_out_given + v_rule.tip_out_value
      WHERE dd.session_id = v_session_id
        AND dd.role_code = v_rule.from_role_code;

      SELECT COUNT(*) INTO v_giver_count
      FROM tip_distribution_details
      WHERE session_id = v_session_id
        AND role_code = v_rule.from_role_code;

      v_tipout_total := v_giver_count * v_rule.tip_out_value;

      IF v_receiver_count > 0 THEN
        UPDATE tip_distribution_details
        SET tip_out_received = tip_out_received +
          ROUND(v_tipout_total / v_receiver_count, 2)
        WHERE session_id = v_session_id
          AND role_code = v_rule.to_role_code;
      END IF;
    END IF;
  END LOOP;

  -- =========================================================
  -- STEP 9: CALCULATE NET TIPS FOR EACH EMPLOYEE
  -- =========================================================
  UPDATE tip_distribution_details
  SET net_tips =
    individual_tips_earned
    - tip_pool_contributed
    + tip_pool_received
    - tip_out_given
    + tip_out_received
    + manual_adjustment
  WHERE session_id = v_session_id;

  -- =========================================================
  -- STEP 10: AGGREGATE SESSION TOTALS
  -- =========================================================
  SELECT
    COALESCE(SUM(net_tips), 0),
    COALESCE(SUM(tip_pool_contributed), 0),
    COALESCE(SUM(tip_out_given), 0)
  INTO v_total_distributed, v_total_pooled, v_total_tipouts
  FROM tip_distribution_details
  WHERE session_id = v_session_id;

  UPDATE tip_distribution_sessions
  SET
    status = 'calculated',
    total_tips_collected = v_total_collected,
    total_tips_pooled = v_total_pooled,
    total_tip_outs = v_total_tipouts,
    total_distributed = v_total_distributed,
    rounding_adjustment = v_total_collected - v_total_distributed,
    calculated_at = now(),
    calculated_by = p_calculated_by
  WHERE id = v_session_id;

  RETURN json_build_object(
    'success', true,
    'session_id', v_session_id,
    'total_collected', v_total_collected,
    'total_distributed', v_total_distributed
  );

END;
$$;


ALTER FUNCTION "public"."calculate_tip_distribution"("p_location_id" "uuid", "p_merchant_id" "uuid", "p_session_date" "date", "p_shift_period" "text", "p_calculated_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_modify_item"("p_order_item_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_id UUID;
  v_course_number INTEGER;
  v_course_status TEXT;
BEGIN
  -- Get item's order and course
  SELECT order_id, course_number INTO v_order_id, v_course_number
  FROM public.order_items
  WHERE id = p_order_item_id;

  IF v_order_id IS NULL THEN
    RETURN FALSE;
  END IF;

  -- Check course status
  SELECT status INTO v_course_status
  FROM public.order_courses
  WHERE order_id = v_order_id AND course_number = v_course_number;

  -- Can modify if course doesn't exist yet or is still open
  RETURN v_course_status IS NULL OR v_course_status = 'open';
END;
$$;


ALTER FUNCTION "public"."can_modify_item"("p_order_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_online_order_by_customer"("p_order_id" "uuid", "p_session_token" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_session RECORD;
  v_order   RECORD;
  v_now     TIMESTAMPTZ := NOW();
BEGIN
  -- Validate session token and ownership
  SELECT s.id, s.order_id, s.expires_at
    INTO v_session
    FROM public.online_order_sessions s
   WHERE s.session_token = p_session_token
     AND s.expires_at > v_now;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid or expired session');
  END IF;

  IF v_session.order_id <> p_order_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order does not belong to this session');
  END IF;

  -- Lock and check order
  SELECT id, status
    INTO v_order
    FROM public.orders
   WHERE id = p_order_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.status <> 'pending' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error',   'Order can only be cancelled while pending (current: ' || v_order.status || ')'
    );
  END IF;

  UPDATE public.orders
     SET status               = 'cancelled',
         cancelled_at         = v_now,
         cancelled_by         = 'customer',
         cancellation_reason  = p_reason,
         updated_at           = v_now
   WHERE id = p_order_id;

  INSERT INTO public.order_status_history
    (order_id, from_status, to_status, changed_at, notes)
  VALUES
    (p_order_id, 'pending', 'cancelled', v_now,
     COALESCE('Cancelled by customer: ' || p_reason, 'Cancelled by customer'));

  RETURN jsonb_build_object(
    'success',      true,
    'order_id',     p_order_id,
    'cancelled_at', v_now
  );
END;
$$;


ALTER FUNCTION "public"."cancel_online_order_by_customer"("p_order_id" "uuid", "p_session_token" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_online_order_by_customer"("p_order_id" "uuid", "p_session_token" "text", "p_reason" "text") IS 'Customer cancels their own online order while it is still pending. Validates session ownership.';



CREATE OR REPLACE FUNCTION "public"."cancel_order"("p_order_id" "uuid", "p_cancel_reason" "text" DEFAULT 'Customer cancelled'::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_status TEXT;
  v_result JSON;
BEGIN
  -- Get order status
  SELECT status INTO v_order_status
  FROM public.orders
  WHERE id = p_order_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  -- For draft/pending orders, we can cancel with lower permission
  IF v_order_status IN ('draft', 'pending') THEN
    -- Just need regular order manage permission
    -- IF NOT has_permission('location.orders.manage') THEN
    --   RAISE EXCEPTION 'Permission denied';
    -- END IF;

    -- Delete items (hard delete for draft)
    DELETE FROM public.order_item_modifiers oim
    USING public.order_items oi
    WHERE oim.order_item_id = oi.id AND oi.order_id = p_order_id;

    DELETE FROM public.order_items WHERE order_id = p_order_id;

    -- Update order to cancelled
    UPDATE public.orders
    SET 
      status = 'cancelled',
      void_reason = p_cancel_reason,
      updated_at = NOW()
    WHERE id = p_order_id;

    -- Close table session if linked
    UPDATE public.table_sessions
    SET 
      is_active = FALSE,
      status = 'available',
      closed_at = NOW()
    WHERE order_id = p_order_id AND is_active = TRUE;

    SELECT json_build_object(
      'success', true,
      'order_id', p_order_id,
      'action', 'cancelled',
      'reason', p_cancel_reason
    ) INTO v_result;

    RETURN v_result;
  ELSE
    -- For confirmed orders, use void_order
    RETURN public.void_order(p_order_id, p_cancel_reason);
  END IF;
END;
$$;


ALTER FUNCTION "public"."cancel_order"("p_order_id" "uuid", "p_cancel_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cancel_order"("p_order_id" "uuid", "p_cancel_reason" "text") IS 'Cancels an order - hard delete for draft/pending, void for confirmed orders';



CREATE OR REPLACE FUNCTION "public"."capture_preauth_v1"("p_payment_id" "uuid", "p_capture_amount" numeric, "p_tip_amount" numeric DEFAULT 0, "p_terminal_response" "jsonb" DEFAULT NULL::"jsonb", "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_payment RECORD;
  v_order RECORD;
  v_total_collected NUMERIC;
  v_new_amount_paid NUMERIC;
  v_new_amount_due NUMERIC;
  v_order_fully_paid BOOLEAN;
  v_new_paid_status TEXT;
  v_subtotal_portion NUMERIC := 0;
  v_tax_portion NUMERIC := 0;
  v_covered_items UUID[] := '{}';
  v_result_code TEXT;
  v_result_message TEXT;
BEGIN
  -- Validate payment exists and is authorized
  SELECT id, order_id, amount, status
  INTO v_payment
  FROM order_payments
  WHERE id = p_payment_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment not found');
  END IF;

  IF v_payment.status <> 'authorized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment is not in authorized status');
  END IF;

  -- Get order for totals update (expanded for enrichment fields)
  SELECT id, total_amount, amount_paid, amount_due,
         card_total, card_subtotal, cash_total, cash_subtotal,
         merchant_id, location_id
  INTO v_order
  FROM orders
  WHERE id = v_payment.order_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  v_total_collected := p_capture_amount + COALESCE(p_tip_amount, 0);

  -- NOW update order totals (capture = real payment) — compute first for v_order_fully_paid
  v_new_amount_paid := COALESCE(v_order.amount_paid, 0) + p_capture_amount;
  v_new_amount_due := GREATEST(COALESCE(v_order.total_amount, 0) - v_new_amount_paid, 0);
  v_order_fully_paid := v_new_amount_due <= 0;

  -- Calculate subtotal/tax portion (same formula as process_payment_v7 full-remaining path)
  IF COALESCE(v_order.card_total, 0) > 0 THEN
    v_subtotal_portion := ROUND(p_capture_amount * (COALESCE(v_order.card_subtotal, 0) / v_order.card_total), 2);
  END IF;
  v_tax_portion := p_capture_amount - v_subtotal_portion;

  -- Collect covered items (if fully paid, all unpaid non-voided items)
  IF v_order_fully_paid THEN
    SELECT COALESCE(array_agg(id), '{}')
    INTO v_covered_items
    FROM order_items
    WHERE order_id = v_payment.order_id
      AND (is_voided IS NULL OR is_voided = false)
      AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;
  END IF;

  -- Extract result code/message from terminal response
  IF p_terminal_response IS NOT NULL THEN
    v_result_code := COALESCE(
      p_terminal_response->'castles_transaction'->>'resultCode',
      p_terminal_response->'dejavoo_transaction'->>'resultCode'
    );
    v_result_message := COALESCE(
      p_terminal_response->'castles_transaction'->>'statusMessage',
      p_terminal_response->'dejavoo_transaction'->>'resultMessage'
    );
  END IF;

  -- Update payment to captured (enriched with all fields)
  UPDATE order_payments
  SET
    status = 'captured',
    amount = p_capture_amount,
    tip_amount = COALESCE(p_tip_amount, 0),
    total_amount = v_total_collected,
    captured_at = NOW(),
    terminal_response = COALESCE(p_terminal_response, terminal_response),
    processor_response = COALESCE(p_terminal_response, terminal_response),
    subtotal_portion = v_subtotal_portion,
    tax_portion = v_tax_portion,
    covers_items = CASE WHEN array_length(v_covered_items, 1) > 0 THEN v_covered_items ELSE NULL END,
    merchant_id = COALESCE(merchant_id, v_order.merchant_id),
    location_id = COALESCE(location_id, v_order.location_id),
    result_code = COALESCE(v_result_code, result_code),
    result_message = COALESCE(v_result_message, result_message),
    processed_by_staff_id = COALESCE(p_staff_id, processed_by_staff_id)
  WHERE id = p_payment_id;

  -- Determine paid_status
  IF v_order_fully_paid THEN
    v_new_paid_status := 'paid';
  ELSIF v_new_amount_paid > 0 THEN
    v_new_paid_status := 'partial';
  ELSE
    v_new_paid_status := 'pending';
  END IF;

  UPDATE orders
  SET
    amount_paid = v_new_amount_paid,
    amount_due = v_new_amount_due,
    payment_status = v_new_paid_status::payment_status,
    check_status = CASE WHEN v_order_fully_paid THEN 'Closed' ELSE check_status END,
    sync_version = sync_version + 1
  WHERE id = v_payment.order_id;

  -- Mark all items as paid if order is fully covered
  IF v_order_fully_paid THEN
    UPDATE order_items
    SET paid_quantity = quantity,
        payment_id = p_payment_id
    WHERE order_id = v_payment.order_id
      AND (paid_quantity IS NULL OR paid_quantity < quantity)
      AND (is_voided IS NULL OR is_voided = false);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', p_payment_id,
    'captured_amount', p_capture_amount,
    'tip_amount', COALESCE(p_tip_amount, 0),
    'order_fully_paid', v_order_fully_paid,
    'order_amount_due', v_new_amount_due
  );
END;
$$;


ALTER FUNCTION "public"."capture_preauth_v1"("p_payment_id" "uuid", "p_capture_amount" numeric, "p_tip_amount" numeric, "p_terminal_response" "jsonb", "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_device_session_status"("p_device_id" "text", "p_session_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_session RECORD;
BEGIN
  SELECT 
    ss.id,
    ss.session_status,
    ss.kicked_by_staff_name,
    ss.kick_reason,
    ss.ended_at
  INTO v_session
  FROM station_sessions ss
  WHERE ss.id = p_session_id
    AND ss.device_id = p_device_id;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'is_valid', false,
      'status', 'not_found',
      'error', 'Session not found'
    );
  END IF;

  IF v_session.session_status = 'active' THEN
    RETURN json_build_object(
      'is_valid', true,
      'status', v_session.session_status
    );
  END IF;

  -- Session is no longer active (kicked, ended, or expired)
  RETURN json_build_object(
    'is_valid', false,
    'status', v_session.session_status,
    'kicked_by', v_session.kicked_by_staff_name,
    'kick_reason', v_session.kick_reason,
    'ended_at', v_session.ended_at
  );
END;
$$;


ALTER FUNCTION "public"."check_device_session_status"("p_device_id" "text", "p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_merchant_access"("target_merchant_id" "uuid", "required_permission" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_clerk_user_id TEXT;
    merchant_clerk_org_id TEXT;
    carrier_id_lookup UUID;
    user_role_code TEXT;
BEGIN
    -- 1. Get Current User
    current_clerk_user_id := get_my_claim('sub')::text; -- Or use your request_user_id() helper
    IF current_clerk_user_id IS NULL THEN RETURN FALSE; END IF;

    -- 2. DEXA HQ OVERRIDE (Manage Everything)
    -- Replace with your actual HQ Org ID check or is_dexa_admin() function
    IF is_dexapos_admin()
    THEN
        RETURN TRUE;
    END IF;

    -- 3. Get Merchant Context (Clerk Org ID & Carrier ID)
    SELECT clerk_org_id, carrier_id INTO merchant_clerk_org_id, carrier_id_lookup
    FROM merchants
    WHERE id = target_merchant_id;

    -- 4. CARRIER OVERRIDE (Manage their merchants)
    IF EXISTS (
        SELECT 1 FROM members m
        JOIN carriers c ON c.clerk_org_id = m.organization_id
        WHERE m.user_id = current_clerk_user_id
        AND c.id = carrier_id_lookup
        -- Optional: Check if carrier member has specific carrier permissions here
    ) THEN
        RETURN TRUE;
    END IF;

    -- 5. MERCHANT ACCESS CHECK
    -- Get the user's role within this specific merchant
    SELECT role INTO user_role_code
    FROM members
    WHERE user_id = current_clerk_user_id
    AND organization_id = merchant_clerk_org_id;

    IF user_role_code IS NULL THEN
        RETURN FALSE; -- Not a member of this merchant
    END IF;

    -- If no specific permission is required (Read-Only access), basic membership is enough
    IF required_permission IS NULL THEN
        RETURN TRUE;
    END IF;

    -- 6. PERMISSION CHECK (Dynamic)
    -- specific override for your requirement: Owner/Admin always allow
    IF user_role_code IN ('merchant.owner', 'merchant.admin') THEN
        RETURN TRUE;
    END IF;

    -- Check if the user's role maps to the required permission code
    RETURN EXISTS (
        SELECT 1 FROM role_permissions
        WHERE role_code = user_role_code
        AND permission_code = required_permission
    );
END;
$$;


ALTER FUNCTION "public"."check_merchant_access"("target_merchant_id" "uuid", "required_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_modifier_group_usage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_usage_count INTEGER;
    v_is_location_specific BOOLEAN;
BEGIN
    -- Check if this is a location-specific group
    SELECT (location_id IS NOT NULL) INTO v_is_location_specific
    FROM modifier_groups WHERE id = OLD.id;

    -- Only check usage for location-specific groups
    -- Global groups can always be deleted (they cascade to overrides)
    IF v_is_location_specific THEN
        -- Count how many menu items use this modifier group
        SELECT COUNT(*) INTO v_usage_count
        FROM menu_item_modifier_groups
        WHERE modifier_group_id = OLD.id;

        IF v_usage_count > 0 THEN
            RAISE EXCEPTION
                'Cannot delete location-specific modifier group: assigned to % menu item(s). Please unassign it from all menu items first.',
                v_usage_count;
        END IF;
    END IF;

    RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."check_modifier_group_usage"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_modifier_group_usage"() IS 'Prevents deletion of location-specific modifier groups that are assigned to menu items. Global groups can always be deleted.';



CREATE OR REPLACE FUNCTION "public"."check_schedule_usage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_usage_count INTEGER;
    v_is_location_specific BOOLEAN;
BEGIN
    -- Check if this is a location-specific schedule
    SELECT (location_id IS NOT NULL) INTO v_is_location_specific
    FROM schedules WHERE id = OLD.id;

    -- Only check usage for location-specific schedules
    -- Global schedules can always be deleted (they cascade to overrides)
    IF v_is_location_specific THEN
        -- Count how many categories/menus use this schedule
        SELECT
            (SELECT COUNT(*) FROM category_schedules WHERE schedule_id = OLD.id) +
            (SELECT COUNT(*) FROM menu_schedules WHERE schedule_id = OLD.id)
        INTO v_usage_count;

        IF v_usage_count > 0 THEN
            RAISE EXCEPTION
                'Cannot delete location-specific schedule: assigned to % menu(s) or category(ies). Please unassign it first.',
                v_usage_count;
        END IF;
    END IF;

    RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."check_schedule_usage"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_schedule_usage"() IS 'Prevents deletion of location-specific schedules that are assigned to categories/menus. Global schedules can always be deleted.';



CREATE OR REPLACE FUNCTION "public"."check_table_availability"("p_location_id" "uuid", "p_date" "date", "p_time" time without time zone, "p_party_size" integer, "p_duration_minutes" integer DEFAULT 90) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_start_time TIMESTAMP;
  v_end_time TIMESTAMP;
BEGIN
  v_start_time := p_date + p_time;
  v_end_time := v_start_time + (p_duration_minutes || ' minutes')::INTERVAL;

  RETURN (
    SELECT json_build_object(
      'available_tables', COALESCE(json_agg(
        json_build_object(
          'id', fpo.id,
          'name', fpo.name,
          'shape_id', fpo.shape_id,
          'capacity', fpo.capacity,
          'zone_name', fpo.zone_name
        )
      ), '[]'::json),
      'total_available', COUNT(*)
    )
    FROM public.floor_plan_objects fpo
    WHERE fpo.location_id = p_location_id
      AND fpo.category IN ('table', 'booth')
      AND fpo.is_active = TRUE
      AND fpo.is_reservable = TRUE
      AND fpo.capacity >= p_party_size
      -- Not reserved during the requested window
      AND NOT EXISTS (
        SELECT 1 FROM public.reservations r
        WHERE r.assigned_table_ids @> ARRAY[fpo.id]
          AND r.status NOT IN ('cancelled', 'no_show', 'completed')
          AND r.reservation_date = p_date
          AND (
            -- Existing reservation overlaps with requested time
            (r.reservation_time, r.reservation_time + (r.duration_minutes || ' minutes')::INTERVAL)
            OVERLAPS
            (p_time, p_time + (p_duration_minutes || ' minutes')::INTERVAL)
          )
      )
  );
END;
$$;


ALTER FUNCTION "public"."check_table_availability"("p_location_id" "uuid", "p_date" "date", "p_time" time without time zone, "p_party_size" integer, "p_duration_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_station"("p_station_id" "uuid", "p_device_id" "uuid", "p_device_name" "text" DEFAULT NULL::"text", "p_staff_profile_id" "uuid" DEFAULT NULL::"uuid", "p_staff_name" "text" DEFAULT NULL::"text", "p_force_takeover" boolean DEFAULT false) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_station RECORD;
  v_existing_session RECORD;
  v_new_session_id UUID;
  v_was_kicked BOOLEAN := FALSE;
BEGIN
  -- Get station info
  SELECT s.*, l.merchant_id 
  INTO v_station
  FROM stations s
  JOIN locations l ON l.id = s.location_id
  WHERE s.id = p_station_id AND s.is_active = TRUE;
  
  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Station not found',
      'error_code', 'STATION_NOT_FOUND'
    );
  END IF;
  
  -- End any session this device has at OTHER stations
  UPDATE station_sessions
  SET session_status = 'ended', ended_at = NOW(), updated_at = NOW()
  WHERE device_id = p_device_id
    AND session_status = 'active'
    AND station_id != p_station_id;
  
  -- Check for existing session at THIS station
  SELECT * INTO v_existing_session
  FROM station_sessions
  WHERE station_id = p_station_id
    AND session_status = 'active'
  FOR UPDATE;
  
  IF FOUND THEN
    -- Same device reconnecting
    IF v_existing_session.device_id = p_device_id THEN
      UPDATE station_sessions
      SET 
        staff_profile_id = COALESCE(p_staff_profile_id, staff_profile_id),
        staff_name = COALESCE(p_staff_name, staff_name),
        updated_at = NOW()
      WHERE id = v_existing_session.id;
      
      RETURN json_build_object(
        'success', true,
        'session_id', v_existing_session.id,
        'station_name', v_station.station_name,
        'is_reconnect', true
      );
    END IF;
    
    -- Different device - need takeover permission
    IF NOT p_force_takeover THEN
      RETURN json_build_object(
        'success', false,
        'error', 'Station in use',
        'error_code', 'STATION_IN_USE',
        'current_session', json_build_object(
          'device_name', v_existing_session.device_name,
          'staff_name', v_existing_session.staff_name,
          'started_at', v_existing_session.started_at
        )
      );
    END IF;
    
    -- Force takeover - kick existing session
    UPDATE station_sessions
    SET 
      session_status = 'kicked',
      ended_at = NOW(),
      kicked_by_device_id = p_device_id,
      kicked_by_staff_name = p_staff_name,
      kick_reason = 'Taken over',
      updated_at = NOW()
    WHERE id = v_existing_session.id;
    
    -- Notify kicked device via Realtime
    INSERT INTO session_kick_notifications (session_id, device_id, kicked_by_staff_name, kick_reason)
    VALUES (v_existing_session.id, v_existing_session.device_id, p_staff_name, 'Taken over');
    
    v_was_kicked := TRUE;
  END IF;
  
  -- Create new session
  INSERT INTO station_sessions (
    station_id, merchant_id, location_id,
    device_id, device_name,
    staff_profile_id, staff_name,
    session_status
  ) VALUES (
    p_station_id, v_station.merchant_id, v_station.location_id,
    p_device_id, p_device_name,
    p_staff_profile_id, p_staff_name,
    'active'
  )
  RETURNING id INTO v_new_session_id;
  
  -- Update station
  UPDATE stations 
  SET device_id = p_device_id, device_name = p_device_name, is_online = TRUE
  WHERE id = p_station_id;
  
  RETURN json_build_object(
    'success', true,
    'session_id', v_new_session_id,
    'station_id', p_station_id,
    'station_name', v_station.station_name,
    'kicked_previous', v_was_kicked
  );
END;
$$;


ALTER FUNCTION "public"."claim_station"("p_station_id" "uuid", "p_device_id" "uuid", "p_device_name" "text", "p_staff_profile_id" "uuid", "p_staff_name" "text", "p_force_takeover" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_station"("p_station_id" "uuid", "p_device_id" "text", "p_device_name" "text" DEFAULT NULL::"text", "p_device_model" "text" DEFAULT NULL::"text", "p_staff_profile_id" "uuid" DEFAULT NULL::"uuid", "p_staff_name" "text" DEFAULT NULL::"text", "p_force_takeover" boolean DEFAULT false) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_station RECORD;
  v_existing_session RECORD;
  v_new_session_id UUID;
  v_was_kicked BOOLEAN := FALSE;
BEGIN
  -- Get station info
  SELECT s.*, l.merchant_id 
  INTO v_station
  FROM stations s
  JOIN locations l ON l.id = s.location_id
  WHERE s.id = p_station_id AND s.is_active = TRUE;
  
  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Station not found or inactive',
      'error_code', 'STATION_NOT_FOUND'
    );
  END IF;
  
  -- End any existing session for THIS device at a DIFFERENT station
  UPDATE station_sessions
  SET 
    session_status = 'ended',
    ended_at = NOW()
  WHERE device_id = p_device_id
    AND session_status = 'active'
    AND station_id != p_station_id;
  
  -- Check for existing active session at THIS station
  SELECT * INTO v_existing_session
  FROM station_sessions
  WHERE station_id = p_station_id
    AND session_status = 'active'
  FOR UPDATE;  -- Lock row to prevent race conditions
  
  IF FOUND THEN
    -- Same device reconnecting? Just update and return existing session
    IF v_existing_session.device_id = p_device_id THEN
      UPDATE station_sessions
      SET 
        last_activity_at = NOW(),
        staff_profile_id = COALESCE(p_staff_profile_id, staff_profile_id),
        staff_name = COALESCE(p_staff_name, staff_name),
        device_name = COALESCE(p_device_name, device_name)
      WHERE id = v_existing_session.id;
      
      RETURN json_build_object(
        'success', true,
        'session_id', v_existing_session.id,
        'is_reconnect', true,
        'message', 'Reconnected to existing session'
      );
    END IF;
    
    -- Different device - need to takeover
    IF NOT p_force_takeover THEN
      RETURN json_build_object(
        'success', false,
        'error', 'Station is in use by another device',
        'error_code', 'STATION_IN_USE',
        'current_session', json_build_object(
          'device_name', v_existing_session.device_name,
          'staff_name', v_existing_session.staff_name,
          'started_at', v_existing_session.started_at
        )
      );
    END IF;
    
    -- Force takeover - kick the existing session
    UPDATE station_sessions
    SET 
      session_status = 'kicked',
      ended_at = NOW(),
      kicked_by_device_id = p_device_id,
      kicked_by_staff_name = p_staff_name,
      kick_reason = 'Taken over by another device'
    WHERE id = v_existing_session.id;
    
    v_was_kicked := TRUE;
    
    -- Insert kick notification for Realtime
    INSERT INTO session_kick_notifications (
      session_id, device_id, kicked_by_staff_name, kick_reason
    ) VALUES (
      v_existing_session.id, 
      v_existing_session.device_id, 
      p_staff_name, 
      'Taken over by another device'
    );
  END IF;
  
  -- Create new session
  INSERT INTO station_sessions (
    station_id,
    merchant_id,
    location_id,
    device_id,
    device_name,
    device_model,
    staff_profile_id,
    staff_name,
    session_status,
    started_at
  ) VALUES (
    p_station_id,
    v_station.merchant_id,
    v_station.location_id,
    p_device_id,
    p_device_name,
    p_device_model,
    p_staff_profile_id,
    p_staff_name,
    'active',
    NOW()
  )
  RETURNING id INTO v_new_session_id;
  
  -- Update station with device info
  UPDATE stations
  SET 
    device_id = p_device_id,
    device_name = p_device_name,
    is_online = TRUE,
    last_heartbeat_at = NOW()
  WHERE id = p_station_id;
  
  RETURN json_build_object(
    'success', true,
    'session_id', v_new_session_id,
    'station_id', p_station_id,
    'station_name', v_station.station_name,
    'kicked_previous', v_was_kicked,
    'message', CASE 
      WHEN v_was_kicked THEN 'Station claimed, previous device was kicked'
      ELSE 'Station claimed successfully'
    END
  );
END;
$$;


ALTER FUNCTION "public"."claim_station"("p_station_id" "uuid", "p_device_id" "text", "p_device_name" "text", "p_device_model" "text", "p_staff_profile_id" "uuid", "p_staff_name" "text", "p_force_takeover" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clear_order_item_instructions"("p_order_item_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_id UUID;
  v_result JSON;
BEGIN
  -- Verify access
  SELECT oi.order_id INTO v_order_id
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
    AND oi.is_voided = FALSE
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids())
    AND o.status NOT IN ('completed', 'cancelled', 'void');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found or cannot be modified';
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Clear instructions
  UPDATE public.order_items
  SET 
    special_instructions = NULL,
    updated_at = NOW()
  WHERE id = p_order_item_id;

  SELECT json_build_object(
    'success', true,
    'order_item_id', p_order_item_id,
    'special_instructions', NULL
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."clear_order_item_instructions"("p_order_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clear_order_items"("p_order_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_status TEXT;
  v_removed_count INTEGER;
  v_result JSON;
BEGIN
  -- Verify order and status
  SELECT status INTO v_order_status
  FROM public.orders
  WHERE id = p_order_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  IF v_order_status NOT IN ('draft', 'pending') THEN
    RAISE EXCEPTION 'Cannot clear items from % orders', v_order_status;
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Delete all modifiers
  DELETE FROM public.order_item_modifiers oim
  USING public.order_items oi
  WHERE oim.order_item_id = oi.id AND oi.order_id = p_order_id;

  -- Delete all items
  DELETE FROM public.order_items WHERE order_id = p_order_id;
  
  GET DIAGNOSTICS v_removed_count = ROW_COUNT;

  -- Reset order totals
  UPDATE public.orders
  SET 
    subtotal = 0,
    tax_amount = 0,
    total_amount = 0,
    updated_at = NOW()
  WHERE id = p_order_id;

  SELECT json_build_object(
    'success', true,
    'order_id', p_order_id,
    'removed_count', v_removed_count
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."clear_order_items"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_cash_drawer_session"("p_session_id" "uuid", "p_cash_drawer_id" "uuid", "p_closed_by" "uuid", "p_closing_amount" numeric, "p_closing_count_details" "jsonb" DEFAULT NULL::"jsonb", "p_variance_notes" "text" DEFAULT NULL::"text", "p_is_blind_count" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_session RECORD;
  v_expected_cash NUMERIC;
  v_variance NUMERIC;
BEGIN
  -- Get session and verify it's open
  SELECT * INTO v_session
  FROM cash_drawer_sessions
  WHERE id = p_session_id AND status = 'open';

  IF v_session IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Session not found or not open'
    );
  END IF;

  -- Calculate expected_cash from operations (source of truth)
  -- Formula: opening + cash_sales + pay_ins - cash_refunds - pay_outs - cash_drops - tip_outs
  SELECT v_session.opening_amount + COALESCE(SUM(
    CASE
      WHEN operation_type IN ('cash_sale', 'pay_in') THEN amount
      WHEN operation_type IN ('cash_refund', 'pay_out', 'cash_drop', 'tip_out') THEN -amount
      ELSE 0
    END
  ), 0)
  INTO v_expected_cash
  FROM cash_drawer_operations
  WHERE session_id = p_session_id;

  v_variance := p_closing_amount - v_expected_cash;

  -- Record closing_count operation
  INSERT INTO cash_drawer_operations (
    cash_drawer_id, session_id, operation_type,
    amount, performed_by, performed_at,
    balance_after
  ) VALUES (
    p_cash_drawer_id, p_session_id, 'closing_count',
    p_closing_amount, p_closed_by, NOW(),
    v_expected_cash
  );

  -- Update session
  UPDATE cash_drawer_sessions
  SET
    closed_by = p_closed_by,
    closed_at = NOW(),
    closing_amount = p_closing_amount,
    closing_count_details = p_closing_count_details,
    closing_count_verified = (p_closing_count_details IS NOT NULL),
    expected_cash = v_expected_cash,
    variance = v_variance,
    variance_notes = p_variance_notes,
    status = 'closed'
  WHERE id = p_session_id;

  -- Update drawer status
  UPDATE cash_drawers
  SET is_open = false, current_session_id = NULL
  WHERE id = p_cash_drawer_id;

  RETURN jsonb_build_object(
    'success', true,
    'expected_cash', v_expected_cash,
    'closing_amount', p_closing_amount,
    'variance', v_variance
  );
END;
$$;


ALTER FUNCTION "public"."close_cash_drawer_session"("p_session_id" "uuid", "p_cash_drawer_id" "uuid", "p_closed_by" "uuid", "p_closing_amount" numeric, "p_closing_count_details" "jsonb", "p_variance_notes" "text", "p_is_blind_count" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_check"("p_order_id" "uuid", "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_order RECORD;
  v_result JSONB;
BEGIN
  -- Lock and fetch order
  SELECT * INTO v_order
  FROM orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Order not found'
    );
  END IF;

  -- We can close checks thats still have money due
  -- Validate order is fully paid
  -- IF v_order.amount_due > 0.01 THEN
  --   RETURN jsonb_build_object(
  --     'success', false,
  --     'error', 'Cannot close check with outstanding balance',
  --     'amount_due', v_order.amount_due
  --   );
  -- END IF;

  -- Validate check is not already closed
  IF v_order.check_status = 'Closed' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Check is already closed'
    );
  END IF;

  -- Close the check
  UPDATE orders
  SET check_status = 'Closed',
      updated_at = NOW(),
      sync_version = sync_version + 1
  WHERE id = p_order_id;

  -- Log the action (audit_logs table expected to exist)
  INSERT INTO audit_logs (
    action,
    resource_type,
    resource_id,
    staff_profile_id,
    changes,
    created_at
  ) VALUES (
    'close_check',
    'orders',
    p_order_id,
    p_staff_id,
    jsonb_build_object('check_status', 'Closed'),
    NOW()
  );

  -- Return success
  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'check_status', 'Closed'
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM
  );
END;$$;


ALTER FUNCTION "public"."close_check"("p_order_id" "uuid", "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."copy_schedule_shifts"("p_source_schedule_id" "uuid", "p_target_schedule_id" "uuid", "p_include_employees" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_source_start date;
    v_target_start date;
    v_days_diff integer;
BEGIN
    -- 1. Get date difference to shift the timestamps
    SELECT start_date INTO v_source_start FROM schedules WHERE id = p_source_schedule_id;
    SELECT start_date INTO v_target_start FROM schedules WHERE id = p_target_schedule_id;
    
    v_days_diff := v_target_start - v_source_start;

    -- 2. Clone Shifts
    INSERT INTO shifts (
        merchant_id, location_id, schedule_id, 
        employee_id, role_name, 
        start_time, end_time, 
        color, notes, status
    )
    SELECT 
        merchant_id, location_id, p_target_schedule_id,
        CASE WHEN p_include_employees THEN employee_id ELSE NULL END, -- Option to copy structure only
        role_name,
        start_time + (v_days_diff || ' days')::interval, -- Shift the dates
        end_time + (v_days_diff || ' days')::interval,
        color, notes,
        'draft' -- Always copy as draft first!
    FROM shifts 
    WHERE schedule_id = p_source_schedule_id;
END;
$$;


ALTER FUNCTION "public"."copy_schedule_shifts"("p_source_schedule_id" "uuid", "p_target_schedule_id" "uuid", "p_include_employees" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_adhoc_expense"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_expense_vendor_name" "text", "p_expense_category" "text", "p_expense_notes" "text", "p_payment_method" "text", "p_card_last_four" "text", "p_total_amount" numeric, "p_user_id" "text", "p_user_name" "text", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_po_id     UUID;
    v_po_number TEXT;
    v_item      JSONB;
BEGIN
    v_po_number := 'EXP-' || to_char(now(), 'YYYYMMDD') || '-' ||
                   UPPER(SUBSTRING(gen_random_uuid()::TEXT, 1, 6));

    INSERT INTO purchase_orders (
        merchant_id, location_id, po_number, status, total_amount,
        is_adhoc_expense, expense_vendor_name, expense_category, expense_notes,
        payment_method, card_last_four, paid_at, created_by
    ) VALUES (
        p_merchant_id, p_location_id, v_po_number, 'paid', p_total_amount,
        true, p_expense_vendor_name, p_expense_category, p_expense_notes,
        p_payment_method, p_card_last_four, now(),
        CASE WHEN p_user_id ~ '^[0-9a-f-]{36}$' THEN p_user_id::UUID ELSE NULL END
    )
    RETURNING id INTO v_po_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        INSERT INTO purchase_order_items (
            purchase_order_id, item_name,
            quantity_ordered, unit_cost, line_total
        ) VALUES (
            v_po_id,
            v_item->>'name',
            COALESCE((v_item->>'quantity')::NUMERIC, 1),
            COALESCE((v_item->>'unit_cost')::NUMERIC, 0),
            COALESCE((v_item->>'line_total')::NUMERIC, 0)
        );
    END LOOP;

    RETURN jsonb_build_object(
        'success',           true,
        'purchase_order_id', v_po_id,
        'po_number',         v_po_number
    );
END;
$_$;


ALTER FUNCTION "public"."create_adhoc_expense"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_expense_vendor_name" "text", "p_expense_category" "text", "p_expense_notes" "text", "p_payment_method" "text", "p_card_last_four" "text", "p_total_amount" numeric, "p_user_id" "text", "p_user_name" "text", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_floor_plan"("p_location_id" "uuid", "p_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_canvas_width" integer DEFAULT 1200, "p_canvas_height" integer DEFAULT 800, "p_is_default" boolean DEFAULT false) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_merchant_id UUID;
  v_floor_plan_id UUID;
BEGIN
  -- Verify permission
  -- IF NOT has_any_permission(ARRAY['location.floor_plan.manage', 'merchant.settings.manage']) THEN
  --   RAISE EXCEPTION 'Permission denied: location.floor_plan.manage required';
  -- END IF;

  -- Get merchant ID
  v_merchant_id := user_merchant_id();
  
  -- Verify location access
  IF NOT p_location_id = ANY(user_location_ids()) THEN
    RAISE EXCEPTION 'Location access denied';
  END IF;

  -- If setting as default, unset others
  IF p_is_default THEN
    UPDATE public.floor_plans 
    SET is_default = FALSE 
    WHERE location_id = p_location_id;
  END IF;

  -- Create floor plan
  INSERT INTO public.floor_plans (
    merchant_id, location_id, name, description,
    canvas_width, canvas_height, is_default,
    created_by
  ) VALUES (
    v_merchant_id, p_location_id, p_name, p_description,
    p_canvas_width, p_canvas_height, p_is_default,
    user_staff_profile_id()
  )
  RETURNING id INTO v_floor_plan_id;

  RETURN json_build_object(
    'success', true,
    'floor_plan_id', v_floor_plan_id,
    'name', p_name
  );
END;
$$;


ALTER FUNCTION "public"."create_floor_plan"("p_location_id" "uuid", "p_name" "text", "p_description" "text", "p_canvas_width" integer, "p_canvas_height" integer, "p_is_default" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_inventory_count"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_count_name" "text", "p_assigned_to_user_id" "text" DEFAULT NULL::"text", "p_assigned_to_name" "text" DEFAULT NULL::"text", "p_item_ids" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count_id      UUID;
    v_items_count   INTEGER;
BEGIN
    -- Create count session
    INSERT INTO inventory_counts (
        merchant_id, location_id,
        count_name, status,
        assigned_to_user_id, assigned_to_name
    ) VALUES (
        p_merchant_id, p_location_id,
        p_count_name, 'draft',
        p_assigned_to_user_id, p_assigned_to_name
    )
    RETURNING id INTO v_count_id;

    -- Snapshot current stock for each item in scope
    -- Scope: active items belonging to this merchant (global OR location-specific)
    -- Stock snapshot: use location_inventory_stock if a row exists, else 0
    INSERT INTO inventory_count_items (count_id, inventory_item_id, expected_quantity)
    SELECT
        v_count_id,
        ii.id,
        COALESCE(lis.stock_quantity, 0)
    FROM inventory_items ii
    LEFT JOIN location_inventory_stock lis
        ON  lis.inventory_item_id = ii.id
        AND lis.location_id       = p_location_id
    WHERE ii.merchant_id  = p_merchant_id
      AND ii.is_active    = true
      AND (
            -- global items (shared across all locations)
            ii.location_id IS NULL
            OR
            -- items specific to this location
            ii.location_id = p_location_id
          )
      AND (
            -- no filter → include all in-scope items
            p_item_ids IS NULL
            OR
            -- filter to requested item UUIDs
            ii.id = ANY(
                SELECT elem::UUID
                FROM jsonb_array_elements_text(p_item_ids) AS elem
            )
          );

    GET DIAGNOSTICS v_items_count = ROW_COUNT;

    RETURN jsonb_build_object(
        'success',      true,
        'count_id',     v_count_id,
        'items_count',  v_items_count
    );
END;
$$;


ALTER FUNCTION "public"."create_inventory_count"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_count_name" "text", "p_assigned_to_user_id" "text", "p_assigned_to_name" "text", "p_item_ids" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_next_course"("p_order_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_next_course INTEGER;
  v_course_id UUID;
BEGIN
  -- Get next course number
  SELECT COALESCE(MAX(course_number), 0) + 1 INTO v_next_course
  FROM public.order_courses
  WHERE order_id = p_order_id;

  -- Also check items in case courses aren't in order_courses yet
  SELECT GREATEST(v_next_course, COALESCE(MAX(course_number), 0) + 1) INTO v_next_course
  FROM public.order_items
  WHERE order_id = p_order_id AND is_voided = FALSE;

  -- Create the course
  INSERT INTO public.order_courses (order_id, course_number, status)
  VALUES (p_order_id, v_next_course, 'open')
  RETURNING id INTO v_course_id;

  -- Update working course
  UPDATE public.table_sessions
  SET working_course = v_next_course, updated_at = NOW()
  WHERE order_id = p_order_id AND is_active = TRUE;

  RETURN json_build_object(
    'success', true,
    'course_number', v_next_course,
    'course_id', v_course_id
  );
END;
$$;


ALTER FUNCTION "public"."create_next_course"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_order"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_order_type" "public"."order_type" DEFAULT 'dine_in'::"public"."order_type", "p_table_number" "text" DEFAULT NULL::"text", "p_customer_name" "text" DEFAULT NULL::"text", "p_customer_phone" "text" DEFAULT NULL::"text", "p_special_instructions" "text" DEFAULT NULL::"text", "p_device_id" "text" DEFAULT NULL::"text", "p_created_by_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_id UUID;
  v_order_number TEXT;
  v_display_number TEXT;
  v_user_id TEXT;
  v_verified_staff_id UUID; -- Variable to hold the safe staff ID
  v_result JSON;
BEGIN
  -- Get current user ID from Clerk JWT
  v_user_id := get_my_claim('sub');
  
  -- Verify user has access to this location
  IF NOT (p_location_id = ANY(user_location_ids())) THEN
    RAISE EXCEPTION 'Access denied: User does not have access to location';
  END IF;
  
  -- Verify merchant_id matches user's merchant
  IF p_merchant_id != user_merchant_id() THEN
    RAISE EXCEPTION 'Access denied: Invalid merchant_id';
  END IF;

  -- Safe Staff ID Validation
  -- ---------------------------------------------------------
  -- Initialize with the passed value
  v_verified_staff_id := p_created_by_staff_id;

  -- If a staff ID was provided, verify it exists
  IF v_verified_staff_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.staff_profiles WHERE id = v_verified_staff_id) THEN
       v_verified_staff_id := NULL;
    END IF;
  END IF;
  
  -- Generate order number
  v_order_number := public.generate_order_number(p_location_id);
  
  -- Generate display number (just the sequence part)
  v_display_number := '#' || SPLIT_PART(v_order_number, '-', 3);
  
  -- Create the order
  -- This INSERT will fire the `tr_log_orders` trigger which handles the Audit Log entry
  INSERT INTO public.orders (
    merchant_id,
    location_id,
    order_number,
    display_number,
    order_type,
    status,
    table_number,
    customer_name,
    customer_phone,
    special_instructions,
    device_id,
    created_by_staff_id,
    created_by_user_id,
    created_at,
    updated_at
  ) VALUES (
    p_merchant_id,
    p_location_id,
    v_order_number,
    v_display_number,
    p_order_type,
    'draft',
    p_table_number,
    p_customer_name,
    p_customer_phone,
    p_special_instructions,
    p_device_id,
    v_verified_staff_id,
    v_user_id,
    NOW(),
    NOW()
  )
  RETURNING id INTO v_order_id;
  
  -- Return order details
  SELECT json_build_object(
    'success', true,
    'order_id', v_order_id,
    'order_number', v_order_number,
    'display_number', v_display_number,
    'status', 'draft'
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."create_order"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_order_type" "public"."order_type", "p_table_number" "text", "p_customer_name" "text", "p_customer_phone" "text", "p_special_instructions" "text", "p_device_id" "text", "p_created_by_staff_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_order"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_order_type" "public"."order_type", "p_table_number" "text", "p_customer_name" "text", "p_customer_phone" "text", "p_special_instructions" "text", "p_device_id" "text", "p_created_by_staff_id" "uuid") IS 'Creates a new order in draft status - requires location.orders.manage permission';



CREATE OR REPLACE FUNCTION "public"."create_order_v2"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_order_type" "public"."order_type", "p_table_number" "text", "p_customer_name" "text", "p_customer_phone" "text", "p_special_instructions" "text", "p_device_id" "text", "p_created_by_staff_id" "uuid", "p_station_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_order_id UUID;
  v_order_number TEXT;
  v_display_number TEXT;
  v_user_id TEXT;
  v_result JSON;
  v_verified_staff_id UUID; -- Variable to hold the safe staff ID
BEGIN
  -- Get current user ID from Clerk JWT
  v_user_id := get_my_claim('sub');
  
  -- Verify user has access to this location
  IF NOT (p_location_id = ANY(user_location_ids())) THEN
    RAISE EXCEPTION 'Access denied: User does not have access to location';
  END IF;
  
  -- Verify user has permission to manage orders
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied: location.orders.manage required';
  -- END IF;
  
  -- Verify merchant_id matches user's merchant
  IF p_merchant_id != user_merchant_id() THEN
    RAISE EXCEPTION 'Access denied: Invalid merchant_id';
  END IF;

  -- Safe Staff ID Validation
  -- ---------------------------------------------------------
  -- Initialize with the passed value
  v_verified_staff_id := p_created_by_staff_id;

  -- If a staff ID was provided, verify it exists in the database
  IF v_verified_staff_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.staff_profiles WHERE id = v_verified_staff_id) THEN
      -- If not found, set to NULL to prevent FK violation error
      v_verified_staff_id := NULL;
    END IF;
  END IF;


  
  -- Generate order number (per-station when station_id provided)
  v_order_number := public.generate_order_number(p_location_id, p_station_id);

  -- Generate display number (handles both 3-segment and 4-segment formats)
  v_display_number := CASE
    WHEN SPLIT_PART(v_order_number, '-', 4) <> ''
    THEN '#' || SPLIT_PART(v_order_number, '-', 3) || '-' || SPLIT_PART(v_order_number, '-', 4)
    ELSE '#' || SPLIT_PART(v_order_number, '-', 3)
  END;
  
  -- Create the order
  INSERT INTO public.orders (
    merchant_id,
    location_id,
    order_number,
    display_number,
    order_type,
    status,
    table_number,
    customer_name,
    customer_phone,
    special_instructions,
    device_id,
    created_by_staff_id,
    created_by_user_id,
    station_id,
    created_at,
    updated_at
  ) VALUES (
    p_merchant_id,
    p_location_id,
    v_order_number,
    v_display_number,
    p_order_type,
    'draft',
    p_table_number,
    p_customer_name,
    p_customer_phone,
    p_special_instructions,
    p_device_id,
    v_verified_staff_id,
    v_user_id,
    p_station_id,
    NOW(),
    NOW()
  )
  RETURNING id INTO v_order_id;
  
  -- Log to audit
  INSERT INTO public.audit_logs (
    actor_user_id,
    organization_id,
    action,
    action_category,
    resource_type,
    resource_name,
    metadata,
    status
  ) VALUES (
    v_user_id,
    (SELECT clerk_org_id FROM public.merchants WHERE id = p_merchant_id),
    'order_created',
    'order_management',
    'order',
    v_order_number,
    jsonb_build_object(
      'order_id', v_order_id,
      'order_type', p_order_type,
      'table_number', p_table_number,
      'location_id', p_location_id,
      'station_id', p_station_id
    ),
    'success'
  );
  
  -- Return order details
  SELECT json_build_object(
    'success', true,
    'order_id', v_order_id,
    'order_number', v_order_number,
    'display_number', v_display_number,
    'status', 'draft'
  ) INTO v_result;
  
  RETURN v_result;
END;$$;


