CREATE OR REPLACE FUNCTION "public"."create_reservation"("p_location_id" "uuid", "p_party_name" "text", "p_party_size" integer, "p_phone" "text", "p_reservation_date" "date", "p_reservation_time" time without time zone, "p_email" "text" DEFAULT NULL::"text", "p_duration_minutes" integer DEFAULT 90, "p_preferred_section" "text" DEFAULT NULL::"text", "p_seating_preference" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_special_requests" "text" DEFAULT NULL::"text", "p_is_vip" boolean DEFAULT false, "p_source" "text" DEFAULT 'direct'::"text", "p_assigned_table_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_merchant_id UUID;
  v_reservation_id UUID;
  v_confirmation_number TEXT;
BEGIN
  -- Verify permission
  -- IF NOT has_any_permission(ARRAY['location.reservations.manage', 'location.tables.manage']) THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Get merchant ID
  v_merchant_id := user_merchant_id();
  
  -- Verify location access
  IF NOT p_location_id = ANY(user_location_ids()) THEN
    RAISE EXCEPTION 'Location access denied';
  END IF;

  -- Validate date/time is in future
  IF p_reservation_date < CURRENT_DATE OR 
     (p_reservation_date = CURRENT_DATE AND p_reservation_time < CURRENT_TIME) THEN
    RAISE EXCEPTION 'Reservation must be in the future';
  END IF;

  -- Create reservation
  INSERT INTO public.reservations (
    merchant_id, location_id,
    party_name, party_size, phone, email,
    reservation_date, reservation_time, duration_minutes,
    preferred_section, seating_preference,
    notes, special_requests, is_vip, source,
    assigned_table_ids,
    created_by_staff_id
  ) VALUES (
    v_merchant_id, p_location_id,
    p_party_name, p_party_size, p_phone, p_email,
    p_reservation_date, p_reservation_time, p_duration_minutes,
    p_preferred_section, p_seating_preference,
    p_notes, p_special_requests, p_is_vip, p_source,
    p_assigned_table_ids,
    user_staff_profile_id()
  )
  RETURNING id, confirmation_number INTO v_reservation_id, v_confirmation_number;

  RETURN json_build_object(
    'success', true,
    'reservation_id', v_reservation_id,
    'confirmation_number', v_confirmation_number,
    'party_name', p_party_name,
    'reservation_date', p_reservation_date,
    'reservation_time', p_reservation_time
  );
END;
$$;


