CREATE OR REPLACE FUNCTION "public"."create_reversal"("p_original_payment_id" "uuid", "p_original_psp_reference" "text", "p_reversal_reference_id" "text", "p_reversal_type" "public"."reversal_type", "p_amount" numeric, "p_reason_code" "public"."refund_reason_type", "p_reason_description" "text", "p_initiated_by" "uuid", "p_approved_by" "uuid") RETURNS "public"."reversals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_payment record;
  v_reversal reversals;
BEGIN
  SELECT op.*, o.merchant_id, o.location_id
  INTO v_payment
  FROM order_payments op
  JOIN orders o ON o.id = op.order_id
  WHERE op.id = p_original_payment_id
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment not found or access denied';
  END IF;

  INSERT INTO reversals (
    original_payment_id,
    original_psp_reference,
    reversal_reference_id,
    merchant_id,
    location_id,
    reversal_type,
    amount,
    reason_code,
    reason_description,
    status,
    initiated_by,
    approved_by
  )
  VALUES (
    p_original_payment_id,
    p_original_psp_reference,
    p_reversal_reference_id,
    v_payment.merchant_id,
    v_payment.location_id,
    p_reversal_type,
    p_amount,
    p_reason_code,
    p_reason_description,
    'pending',
    p_initiated_by,
    p_approved_by
  )
  RETURNING * INTO v_reversal;

  RETURN v_reversal;
END;
$$;


