CREATE OR REPLACE FUNCTION "public"."create_support_ticket"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_subject" "text", "p_description" "text", "p_category" "text", "p_submitted_by" "text", "p_submitted_by_name" "text", "p_submitted_by_email" "text" DEFAULT NULL::"text", "p_carrier_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_ticket_id     UUID;
  v_ticket_number TEXT;
  v_carrier_id    UUID;
BEGIN
  -- Auto-resolve carrier from merchant if not provided
  IF p_carrier_id IS NULL THEN
    SELECT carrier_id INTO v_carrier_id FROM public.merchants WHERE id = p_merchant_id;
  ELSE
    v_carrier_id := p_carrier_id;
  END IF;

  -- Generate ticket number
  v_ticket_number := 'DEXA-' || lpad(nextval('support_ticket_seq')::text, 5, '0');

  INSERT INTO public.support_tickets (
    ticket_number, merchant_id, location_id,
    submitted_by, submitted_by_name, submitted_by_email,
    carrier_id, subject, description, category, metadata
  ) VALUES (
    v_ticket_number, p_merchant_id, p_location_id,
    p_submitted_by, p_submitted_by_name, p_submitted_by_email,
    v_carrier_id, p_subject, p_description, p_category, COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_ticket_id;

  -- Insert initial description as first message
  INSERT INTO public.support_ticket_messages (
    ticket_id, sender_id, sender_name, sender_role, message, read_by_admin
  ) VALUES (
    v_ticket_id, p_submitted_by, p_submitted_by_name, 'merchant', p_description, false
  );

  RETURN jsonb_build_object('ticket_id', v_ticket_id, 'ticket_number', v_ticket_number);
END;
$$;


ALTER FUNCTION "public"."create_support_ticket"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_subject" "text", "p_description" "text", "p_category" "text", "p_submitted_by" "text", "p_submitted_by_name" "text", "p_submitted_by_email" "text", "p_carrier_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_support_ticket"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_subject" "text", "p_description" "text", "p_category" "text", "p_submitted_by" "text", "p_submitted_by_name" "text", "p_submitted_by_email" "text" DEFAULT NULL::"text", "p_carrier_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_attachments" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_ticket_id     UUID;
  v_ticket_number TEXT;
  v_carrier_id    UUID;
  v_message_id    UUID;
  v_att           JSONB;
BEGIN
  -- Auto-resolve carrier from merchant if not provided
  IF p_carrier_id IS NULL THEN
    SELECT carrier_id INTO v_carrier_id FROM public.merchants WHERE id = p_merchant_id;
  ELSE
    v_carrier_id := p_carrier_id;
  END IF;

  -- Generate ticket number
  v_ticket_number := 'DEXA-' || lpad(nextval('support_ticket_seq')::text, 5, '0');

  INSERT INTO public.support_tickets (
    ticket_number, merchant_id, location_id,
    submitted_by, submitted_by_name, submitted_by_email,
    carrier_id, subject, description, category, metadata
  ) VALUES (
    v_ticket_number, p_merchant_id, p_location_id,
    p_submitted_by, p_submitted_by_name, p_submitted_by_email,
    v_carrier_id, p_subject, p_description, p_category, COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_ticket_id;

  -- Insert initial description as first message
  INSERT INTO public.support_ticket_messages (
    ticket_id, sender_id, sender_name, sender_role, message, read_by_admin
  ) VALUES (
    v_ticket_id, p_submitted_by, p_submitted_by_name, 'merchant', p_description, false
  ) RETURNING id INTO v_message_id;

  -- Insert attachments linked to the first message
  FOR v_att IN SELECT * FROM jsonb_array_elements(COALESCE(p_attachments, '[]'::jsonb))
  LOOP
    INSERT INTO public.support_ticket_attachments (
      ticket_id, message_id, uploaded_by,
      file_name, file_path, file_size, file_type
    ) VALUES (
      v_ticket_id, v_message_id, p_submitted_by,
      v_att->>'file_name',
      v_att->>'file_path',
      (v_att->>'file_size')::integer,
      v_att->>'file_type'
    );
  END LOOP;

  RETURN jsonb_build_object('ticket_id', v_ticket_id, 'ticket_number', v_ticket_number);
END;
$$;


ALTER FUNCTION "public"."create_support_ticket"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_subject" "text", "p_description" "text", "p_category" "text", "p_submitted_by" "text", "p_submitted_by_name" "text", "p_submitted_by_email" "text", "p_carrier_id" "uuid", "p_metadata" "jsonb", "p_attachments" "jsonb") OWNER TO "postgres";


