CREATE OR REPLACE FUNCTION "public"."get_active_organization_count"("p_days" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN (
    SELECT count(DISTINCT merchant_id)
    FROM orders
    WHERE created_at >= (now() - (p_days || ' days')::interval)
    AND status NOT IN ('draft', 'cancelled', 'void')
  );
END;
$$;


ALTER FUNCTION "public"."get_active_organization_count"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_merchant_breakdown"("p_merchant_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_payment_status" "text"[] DEFAULT NULL::"text"[], "p_date_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_date_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("merchant_id" "uuid", "merchant_name" "text", "total_locations" bigint, "active_locations" bigint, "order_count" bigint, "transaction_count" bigint, "card_revenue" numeric, "cash_revenue" numeric, "total_revenue" numeric, "avg_ticket" numeric, "tip_total" numeric, "total_fees" numeric, "void_count" bigint, "refund_count" bigint, "void_refund_amount" numeric, "void_rate_pct" numeric, "unsettled_amount" numeric, "cash_discount_count" bigint, "last_transaction_at" timestamp with time zone, "prior_total_revenue" numeric, "revenue_change_pct" numeric, "payment_method_breakdown" "jsonb", "daily_revenue_trend" "jsonb")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_allowed_merchants uuid[];
  v_filter_merchants  uuid[];
  v_from              timestamptz;
  v_to                timestamptz;
  v_period_days       int;
  v_prior_from        timestamptz;
  v_prior_to          timestamptz;
BEGIN
  IF NOT public.is_dexapos_admin() THEN
    RETURN;
  END IF;

  v_from := COALESCE(p_date_from, date_trunc('day', now()) - interval '29 days');
  v_to := COALESCE(p_date_to, now());

  IF p_date_from IS NULL AND p_date_to IS NOT NULL THEN
    v_from := p_date_to - interval '29 days';
  END IF;

  IF p_date_from IS NOT NULL AND p_date_to IS NULL THEN
    v_to := now();
  END IF;

  IF v_to <= v_from THEN
    v_to := v_from + interval '1 second';
  END IF;

  v_period_days := GREATEST(EXTRACT(DAY FROM v_to - v_from)::int, 1);
  v_prior_from := v_from - (v_period_days || ' days')::interval;
  v_prior_to := v_from;

  SELECT COALESCE(array_agg(mid), ARRAY[]::uuid[])
    INTO v_allowed_merchants
  FROM public.get_admin_merchant_ids() AS mid;

  IF COALESCE(array_length(v_allowed_merchants, 1), 0) = 0 THEN
    RETURN;
  END IF;

  IF p_merchant_ids IS NULL OR array_length(p_merchant_ids, 1) IS NULL THEN
    v_filter_merchants := v_allowed_merchants;
  ELSE
    SELECT COALESCE(array_agg(mid), ARRAY[]::uuid[])
      INTO v_filter_merchants
    FROM unnest(p_merchant_ids) AS mid
    WHERE mid = ANY (v_allowed_merchants);

    IF COALESCE(array_length(v_filter_merchants, 1), 0) = 0 THEN
      RETURN;
    END IF;
  END IF;

  RETURN QUERY
  WITH
  base AS (
    SELECT
      op.merchant_id,
      op.location_id,
      op.order_id,
      op.id AS payment_id,
      COALESCE(op.captured_at, op.initiated_at) AS event_ts,
      op.payment_method::text AS payment_method,
      op.status::text AS payment_status,
      COALESCE(op.total_amount, 0)::numeric AS total_amount,
      COALESCE(op.tip_amount, 0)::numeric AS tip_amount,
      COALESCE(op.gateway_fee, 0)::numeric AS gateway_fee,
      COALESCE(op.refunded_amount, 0)::numeric AS refunded_amount,
      COALESCE(op.return_amount, 0)::numeric AS return_amount,
      COALESCE(op.is_voided, false) AS is_voided,
      COALESCE(op.is_returned, false) AS is_returned,
      COALESCE(op.is_settled, false) AS is_settled,
      COALESCE(op.cash_discount_applied, false) AS cash_discount_applied
    FROM public.order_payments op
    WHERE op.merchant_id = ANY (v_filter_merchants)
      AND (p_location_ids IS NULL OR op.location_id = ANY (p_location_ids))
      AND COALESCE(op.captured_at, op.initiated_at) >= v_from
      AND COALESCE(op.captured_at, op.initiated_at) <= v_to
      AND (
        (p_payment_status IS NULL AND op.status::text NOT IN ('pending', 'failed'))
        OR (p_payment_status IS NOT NULL AND op.status::text = ANY (p_payment_status))
      )
  ),

  prior_period AS (
    SELECT
      op.merchant_id,
      COALESCE(
        SUM(
          CASE
            WHEN op.status::text = 'captured' THEN COALESCE(op.total_amount, 0)
            ELSE 0
          END
        ),
        0
      )::numeric AS prior_revenue
    FROM public.order_payments op
    WHERE op.merchant_id = ANY (v_filter_merchants)
      AND (p_location_ids IS NULL OR op.location_id = ANY (p_location_ids))
      AND COALESCE(op.captured_at, op.initiated_at) >= v_prior_from
      AND COALESCE(op.captured_at, op.initiated_at) < v_prior_to
      AND op.status::text NOT IN ('pending', 'failed')
    GROUP BY op.merchant_id
  ),

  all_locations AS (
    SELECT
      l.merchant_id,
      COUNT(*)::bigint AS total_locations
    FROM public.locations l
    WHERE l.merchant_id = ANY (v_filter_merchants)
      AND l.is_active = true
    GROUP BY l.merchant_id
  ),

  merchant_rollup AS (
    SELECT
      b.merchant_id,
      COUNT(DISTINCT b.location_id)::bigint AS active_locations,
      COUNT(DISTINCT b.order_id)::bigint AS order_count,
      COUNT(*)::bigint AS transaction_count,

      ROUND(
        COALESCE(
          SUM(
            CASE
              WHEN b.payment_status = 'captured' AND b.payment_method = 'card'
              THEN b.total_amount
              ELSE 0
            END
          ),
          0
        ),
        2
      ) AS card_revenue,

      ROUND(
        COALESCE(
          SUM(
            CASE
              WHEN b.payment_status = 'captured' AND b.payment_method = 'cash'
              THEN b.total_amount
              ELSE 0
            END
          ),
          0
        ),
        2
      ) AS cash_revenue,

      ROUND(
        COALESCE(
          SUM(
            CASE
              WHEN b.payment_status = 'captured' THEN b.total_amount
              ELSE 0
            END
          ),
          0
        ),
        2
      ) AS total_revenue,

      ROUND(
        COALESCE(
          AVG(
            CASE
              WHEN b.payment_status = 'captured' THEN b.total_amount
              ELSE NULL
            END
          ),
          0
        ),
        2
      ) AS avg_ticket,

      ROUND(
        COALESCE(
          SUM(
            CASE
              WHEN b.payment_status = 'captured' THEN b.tip_amount
              ELSE 0
            END
          ),
          0
        ),
        2
      ) AS tip_total,

      ROUND(COALESCE(SUM(b.gateway_fee), 0), 2) AS total_fees,

      COUNT(*) FILTER (WHERE b.is_voided)::bigint AS void_count,
      COUNT(*) FILTER (WHERE b.payment_status IN ('refunded', 'partially_refunded'))::bigint AS refund_count,

      ROUND(
        COALESCE(
          SUM(CASE WHEN b.is_voided THEN b.total_amount ELSE 0 END) +
          SUM(b.refunded_amount) +
          SUM(b.return_amount),
          0
        ),
        2
      ) AS void_refund_amount,

      ROUND(
        COALESCE(
          SUM(
            CASE
              WHEN b.payment_status = 'captured' AND NOT b.is_settled
              THEN b.total_amount
              ELSE 0
            END
          ),
          0
        ),
        2
      ) AS unsettled_amount,

      COUNT(*) FILTER (WHERE b.cash_discount_applied)::bigint AS cash_discount_count,
      MAX(b.event_ts) AS last_transaction_at
    FROM base b
    GROUP BY b.merchant_id
  ),

  method_breakdown AS (
    SELECT
      b.merchant_id,
      jsonb_agg(
        jsonb_build_object(
          'method', b.payment_method,
          'count', b.cnt,
          'amount', b.amt
        ) ORDER BY b.amt DESC
      ) AS payment_method_breakdown
    FROM (
      SELECT
        base_tx.merchant_id,
        base_tx.payment_method,
        COUNT(*)::bigint AS cnt,
        ROUND(
          COALESCE(
            SUM(CASE WHEN base_tx.payment_status = 'captured' THEN base_tx.total_amount ELSE 0 END),
            0
          ),
          2
        ) AS amt
      FROM base AS base_tx
      GROUP BY base_tx.merchant_id, base_tx.payment_method
    ) b
    GROUP BY b.merchant_id
  ),

  date_series AS (
    SELECT d::date AS day
    FROM generate_series(
      date_trunc('day', v_from)::date,
      date_trunc('day', v_to)::date,
      '1 day'::interval
    ) AS d
  ),

  merchant_ids_cte AS (
    SELECT DISTINCT base_ids.merchant_id
    FROM base AS base_ids
  ),

  daily_filled AS (
    SELECT
      mi.merchant_id,
      ds.day,
      COALESCE(
        SUM(CASE WHEN b.payment_status = 'captured' THEN b.total_amount ELSE 0 END),
        0
      )::numeric AS daily_revenue
    FROM merchant_ids_cte mi
    CROSS JOIN date_series ds
    LEFT JOIN base b
      ON b.merchant_id = mi.merchant_id
      AND date_trunc('day', b.event_ts)::date = ds.day
    GROUP BY mi.merchant_id, ds.day
  ),

  trend AS (
    SELECT
      df.merchant_id,
      jsonb_agg(
        jsonb_build_object(
          'date', to_char(df.day, 'YYYY-MM-DD'),
          'revenue', ROUND(df.daily_revenue, 2)
        ) ORDER BY df.day
      ) AS daily_revenue_trend
    FROM daily_filled df
    GROUP BY df.merchant_id
  )

  SELECT
    mr.merchant_id,
    m.name::text AS merchant_name,
    COALESCE(al.total_locations, 0)::bigint AS total_locations,
    mr.active_locations,
    mr.order_count,
    mr.transaction_count,
    mr.card_revenue,
    mr.cash_revenue,
    mr.total_revenue,
    mr.avg_ticket,
    mr.tip_total,
    mr.total_fees,
    mr.void_count,
    mr.refund_count,
    mr.void_refund_amount,
    CASE
      WHEN mr.transaction_count > 0
      THEN ROUND((mr.void_count::numeric / mr.transaction_count) * 100, 2)
      ELSE 0
    END::numeric AS void_rate_pct,
    mr.unsettled_amount,
    mr.cash_discount_count,
    mr.last_transaction_at,
    COALESCE(pp.prior_revenue, 0)::numeric AS prior_total_revenue,
    CASE
      WHEN COALESCE(pp.prior_revenue, 0) > 0
      THEN ROUND(((mr.total_revenue - pp.prior_revenue) / pp.prior_revenue) * 100, 1)
      WHEN mr.total_revenue > 0 THEN 100.0
      ELSE 0
    END::numeric AS revenue_change_pct,
    COALESCE(mb.payment_method_breakdown, '[]'::jsonb) AS payment_method_breakdown,
    COALESCE(t.daily_revenue_trend, '[]'::jsonb) AS daily_revenue_trend
  FROM merchant_rollup mr
  JOIN public.merchants m ON m.id = mr.merchant_id
  LEFT JOIN all_locations al ON al.merchant_id = mr.merchant_id
  LEFT JOIN prior_period pp ON pp.merchant_id = mr.merchant_id
  LEFT JOIN method_breakdown mb ON mb.merchant_id = mr.merchant_id
  LEFT JOIN trend t ON t.merchant_id = mr.merchant_id
  ORDER BY mr.total_revenue DESC, mr.transaction_count DESC;
END;
$$;


ALTER FUNCTION "public"."get_admin_merchant_breakdown"("p_merchant_ids" "uuid"[], "p_location_ids" "uuid"[], "p_payment_status" "text"[], "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admin_merchant_breakdown"("p_merchant_ids" "uuid"[], "p_location_ids" "uuid"[], "p_payment_status" "text"[], "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone) IS 'v2 HQ admin merchant breakdown: revenue, voids, refunds, tips, fees, settlement, dual-pricing, prior-period comparison, gap-filled daily trend, and payment-method breakdown.';



CREATE OR REPLACE FUNCTION "public"."get_admin_merchant_ids"() RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH admin_ctx AS (
    SELECT
      public.current_user_id() AS user_id,
      public.is_dexapos_admin() AS is_admin,
      EXISTS (
        SELECT 1
        FROM public.get_my_hq_role() r
        WHERE r.role_code = 'hq.super_admin'
      ) AS is_super_admin
  )
  SELECT m.id
  FROM public.merchants m
  CROSS JOIN admin_ctx c
  WHERE c.is_admin = true
    AND c.is_super_admin = true

  UNION

  SELECT ama.merchant_id
  FROM public.admin_merchant_access ama
  CROSS JOIN admin_ctx c
  WHERE c.is_admin = true
    AND c.is_super_admin = false
    AND ama.admin_user_id = c.user_id
    AND ama.is_active = true;
$$;


ALTER FUNCTION "public"."get_admin_merchant_ids"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admin_merchant_ids"() IS 'Returns merchant IDs the current HQ admin can access; hq.super_admin gets all merchants.';



CREATE OR REPLACE FUNCTION "public"."get_admin_settlement_batch_payments"("p_batch_id" "text", "p_merchant_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("payment_id" "uuid", "order_id" "uuid", "order_number" "text", "merchant_id" "uuid", "merchant_name" "text", "location_id" "uuid", "location_name" "text", "payment_method" "text", "payment_status" "text", "total_amount" numeric, "tip_amount" numeric, "refund_amount" numeric, "is_voided" boolean, "is_returned" boolean, "initiated_at" timestamp with time zone, "captured_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_allowed_merchants uuid[];
  v_filter_merchants uuid[];
  v_batch_id text := NULLIF(trim(p_batch_id), '');
BEGIN
  IF NOT public.is_dexapos_admin() THEN
    RETURN;
  END IF;

  IF v_batch_id IS NULL THEN
    RETURN;
  END IF;

  SELECT COALESCE(array_agg(mid), ARRAY[]::uuid[])
  INTO v_allowed_merchants
  FROM public.get_admin_merchant_ids() AS mid;

  IF COALESCE(array_length(v_allowed_merchants, 1), 0) = 0 THEN
    RETURN;
  END IF;

  IF p_merchant_id IS NOT NULL THEN
    IF NOT (p_merchant_id = ANY (v_allowed_merchants)) THEN
      RETURN;
    END IF;
    v_filter_merchants := ARRAY[p_merchant_id];
  ELSE
    v_filter_merchants := v_allowed_merchants;
  END IF;

  RETURN QUERY
  SELECT
    op.id AS payment_id,
    op.order_id,
    COALESCE(o.order_number, o.display_number)::text AS order_number,
    o.merchant_id,
    m.name::text AS merchant_name,
    o.location_id,
    l.name::text AS location_name,
    op.payment_method::text AS payment_method,
    op.status::text AS payment_status,
    COALESCE(op.total_amount, 0)::numeric AS total_amount,
    COALESCE(op.tip_amount, 0)::numeric AS tip_amount,
    COALESCE(op.return_amount, 0)::numeric AS refund_amount,
    COALESCE(op.is_voided, false) AS is_voided,
    COALESCE(op.is_returned, false) AS is_returned,
    op.initiated_at,
    op.captured_at
  FROM public.order_payments op
  JOIN public.orders o
    ON o.id = op.order_id
  JOIN public.merchants m
    ON m.id = o.merchant_id
  LEFT JOIN public.locations l
    ON l.id = o.location_id
  WHERE o.merchant_id = ANY (v_filter_merchants)
    AND COALESCE(op.batch_number, op.dejavoo_batch_number) = v_batch_id
  ORDER BY COALESCE(op.captured_at, op.initiated_at, o.created_at) DESC;
END;
$$;


ALTER FUNCTION "public"."get_admin_settlement_batch_payments"("p_batch_id" "text", "p_merchant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admin_settlement_batch_payments"("p_batch_id" "text", "p_merchant_id" "uuid") IS 'HQ admin settlement batch payment details scoped by assigned merchants.';



CREATE OR REPLACE FUNCTION "public"."get_admin_settlement_batches"("p_merchant_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_status" "text"[] DEFAULT NULL::"text"[], "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "batch_id" "text", "merchant_id" "uuid", "merchant_name" "text", "location_id" "uuid", "location_name" "text", "business_date" "date", "opened_at" timestamp with time zone, "closed_at" timestamp with time zone, "settlement_date" "date", "funded_date" "date", "transaction_count" integer, "sales_count" integer, "refund_count" integer, "void_count" integer, "gross_amount" numeric, "tip_amount" numeric, "refund_amount" numeric, "net_deposit" numeric, "status" "text", "linked_payment_count" bigint, "linked_payment_amount" numeric, "discrepancy_amount" numeric, "has_discrepancy" boolean)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_allowed_merchants uuid[];
  v_filter_merchants uuid[];
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 200), 1), 500);
BEGIN
  IF NOT public.is_dexapos_admin() THEN
    RETURN;
  END IF;

  SELECT COALESCE(array_agg(mid), ARRAY[]::uuid[])
  INTO v_allowed_merchants
  FROM public.get_admin_merchant_ids() AS mid;

  IF COALESCE(array_length(v_allowed_merchants, 1), 0) = 0 THEN
    RETURN;
  END IF;

  IF p_merchant_ids IS NULL OR array_length(p_merchant_ids, 1) IS NULL THEN
    v_filter_merchants := v_allowed_merchants;
  ELSE
    SELECT COALESCE(array_agg(mid), ARRAY[]::uuid[])
    INTO v_filter_merchants
    FROM unnest(p_merchant_ids) AS mid
    WHERE mid = ANY (v_allowed_merchants);

    IF COALESCE(array_length(v_filter_merchants, 1), 0) = 0 THEN
      RETURN;
    END IF;
  END IF;

  RETURN QUERY
  WITH scoped_batches AS (
    SELECT
      sb.id,
      sb.batch_id,
      sb.merchant_id,
      m.name AS merchant_name,
      sb.location_id,
      l.name AS location_name,
      sb.business_date,
      sb.opened_at,
      sb.closed_at,
      sb.settlement_date,
      sb.funded_date,
      COALESCE(sb.transaction_count, 0) AS transaction_count,
      COALESCE(sb.sales_count, 0) AS sales_count,
      COALESCE(sb.refund_count, 0) AS refund_count,
      COALESCE(sb.void_count, 0) AS void_count,
      COALESCE(sb.gross_amount, 0) AS gross_amount_cents,
      COALESCE(sb.tip_amount, 0) AS tip_amount_cents,
      COALESCE(sb.refund_amount, 0) AS refund_amount_cents,
      COALESCE(sb.net_deposit, 0) AS net_deposit_cents,
      sb.status::text AS status
    FROM public.settlement_batches sb
    JOIN public.merchants m
      ON m.id = sb.merchant_id
    LEFT JOIN public.locations l
      ON l.id = sb.location_id
    WHERE sb.merchant_id = ANY (v_filter_merchants)
      AND (p_status IS NULL OR sb.status::text = ANY (p_status))
      AND (p_date_from IS NULL OR sb.business_date >= p_date_from)
      AND (p_date_to IS NULL OR sb.business_date <= p_date_to)
    ORDER BY sb.business_date DESC, sb.closed_at DESC NULLS LAST, sb.opened_at DESC
    LIMIT v_limit
  )
  SELECT
    b.id,
    b.batch_id::text,
    b.merchant_id,
    b.merchant_name::text,
    b.location_id,
    b.location_name::text,
    b.business_date,
    b.opened_at,
    b.closed_at,
    b.settlement_date,
    b.funded_date,
    b.transaction_count,
    b.sales_count,
    b.refund_count,
    b.void_count,
    (b.gross_amount_cents::numeric / 100.0)::numeric AS gross_amount,
    (b.tip_amount_cents::numeric / 100.0)::numeric AS tip_amount,
    (b.refund_amount_cents::numeric / 100.0)::numeric AS refund_amount,
    (b.net_deposit_cents::numeric / 100.0)::numeric AS net_deposit,
    b.status,
    COALESCE(lp.linked_payment_count, 0)::bigint AS linked_payment_count,
    COALESCE(lp.linked_payment_amount, 0)::numeric AS linked_payment_amount,
    ROUND(
      (b.gross_amount_cents::numeric / 100.0) - COALESCE(lp.linked_payment_amount, 0),
      2
    )::numeric AS discrepancy_amount,
    ABS(
      ROUND(
        (b.gross_amount_cents::numeric / 100.0) - COALESCE(lp.linked_payment_amount, 0),
        2
      )
    ) >= 0.01 AS has_discrepancy
  FROM scoped_batches b
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*)::bigint AS linked_payment_count,
      COALESCE(
        SUM(
          CASE
            WHEN COALESCE(op.is_voided, false) THEN 0
            WHEN op.status::text = ANY (ARRAY['failed', 'pending']) THEN 0
            ELSE COALESCE(op.total_amount, 0)::numeric
          END
        ),
        0
      )::numeric AS linked_payment_amount
    FROM public.order_payments op
    LEFT JOIN public.orders o
      ON o.id = op.order_id
    WHERE COALESCE(op.merchant_id, o.merchant_id) = b.merchant_id
      AND COALESCE(op.batch_number, op.dejavoo_batch_number) = b.batch_id
  ) lp ON true
  ORDER BY b.business_date DESC, b.closed_at DESC NULLS LAST, b.opened_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_admin_settlement_batches"("p_merchant_ids" "uuid"[], "p_status" "text"[], "p_date_from" "date", "p_date_to" "date", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admin_settlement_batches"("p_merchant_ids" "uuid"[], "p_status" "text"[], "p_date_from" "date", "p_date_to" "date", "p_limit" integer) IS 'HQ admin settlement batch reconciliation list with assignment-scoped merchant intersection and discrepancy calculation.';



CREATE OR REPLACE FUNCTION "public"."get_admin_transaction_detail"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order public.orders%ROWTYPE;
  v_order_enriched jsonb;
  v_payments jsonb;
  v_order_items jsonb;
  v_order_discounts jsonb;
BEGIN
  IF p_order_id IS NULL THEN
    RETURN NULL;
  END IF;

  IF NOT public.is_dexapos_admin() THEN
    RETURN NULL;
  END IF;

  SELECT o.*
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF v_order.merchant_id NOT IN (SELECT public.get_admin_merchant_ids()) THEN
    RETURN NULL;
  END IF;

  SELECT
    to_jsonb(v_order)
    || jsonb_build_object(
      'merchant_name', m.name,
      'location_name', l.name,
      'staff_name', NULLIF(trim(concat_ws(' ', sp.first_name, sp.last_name)), '')
    )
  INTO v_order_enriched
  FROM public.merchants m
  LEFT JOIN public.locations l
    ON l.id = v_order.location_id
  LEFT JOIN public.staff_profiles sp
    ON sp.id = v_order.created_by_staff_id
  WHERE m.id = v_order.merchant_id;

  SELECT COALESCE(
    jsonb_agg(
      (
        to_jsonb(op)
        || jsonb_build_object(
          'staff_name', NULLIF(trim(concat_ws(' ', psp.first_name, psp.last_name)), ''),
          'terminal_info',
            CASE
              WHEN pt.id IS NULL THEN NULL
              ELSE jsonb_build_object(
                'terminal_id', pt.id,
                'terminal_name', pt.terminal_name,
                'terminal_model', pt.terminal_model,
                'serial_number', pt.serial_number,
                'tpn', pt.tpn,
                'connection_type', pt.connection_type,
                'api_environment', pt.api_environment
              )
            END,
          'settlement',
            CASE
              WHEN sb.id IS NULL THEN NULL
              ELSE jsonb_build_object(
                'settlement_batch_id', sb.id,
                'batch_id', sb.batch_id,
                'status', sb.status,
                'opened_at', sb.opened_at,
                'closed_at', sb.closed_at,
                'settlement_date', sb.settlement_date,
                'funded_date', sb.funded_date,
                'is_settled', COALESCE(op.is_settled, false),
                'settled_at', op.settled_at
              )
            END,
          'items_paid', COALESCE(
            (
              SELECT jsonb_agg(
                to_jsonb(opi)
                || jsonb_build_object(
                  'item', to_jsonb(oi)
                )
                ORDER BY opi.created_at
              )
              FROM public.order_payment_items opi
              JOIN public.order_items oi
                ON oi.id = opi.order_item_id
              WHERE opi.order_payment_id = op.id
            ),
            '[]'::jsonb
          ),
          'payment_events', COALESCE(
            (
              SELECT jsonb_agg(to_jsonb(pe) ORDER BY pe.event_timestamp)
              FROM public.payment_events pe
              WHERE pe.payment_id = op.id
            ),
            '[]'::jsonb
          )
        )
      )
      ORDER BY COALESCE(op.initiated_at, op.captured_at)
    ),
    '[]'::jsonb
  )
  INTO v_payments
  FROM public.order_payments op
  LEFT JOIN public.staff_profiles psp
    ON psp.id = COALESCE(op.processed_by_staff_id, op.tip_adjusted_by, op.returned_by)
  LEFT JOIN LATERAL (
    SELECT pt_inner.*
    FROM public.payment_terminals pt_inner
    WHERE pt_inner.location_id = COALESCE(op.location_id, v_order.location_id)
      AND (
        op.terminal_id IS NULL
        OR pt_inner.serial_number = op.terminal_id
        OR pt_inner.tpn = op.terminal_id
        OR pt_inner.id::text = op.terminal_id
      )
    ORDER BY
      CASE
        WHEN op.terminal_id IS NOT NULL AND pt_inner.serial_number = op.terminal_id THEN 0
        WHEN op.terminal_id IS NOT NULL AND pt_inner.tpn = op.terminal_id THEN 1
        WHEN op.terminal_id IS NOT NULL AND pt_inner.id::text = op.terminal_id THEN 2
        ELSE 3
      END,
      pt_inner.updated_at DESC
    LIMIT 1
  ) pt ON true
  LEFT JOIN LATERAL (
    SELECT sb_inner.*
    FROM public.settlement_batches sb_inner
    WHERE sb_inner.merchant_id = COALESCE(op.merchant_id, v_order.merchant_id)
      AND sb_inner.location_id = COALESCE(op.location_id, v_order.location_id)
      AND COALESCE(op.batch_number, op.dejavoo_batch_number) IS NOT NULL
      AND sb_inner.batch_id = COALESCE(op.batch_number, op.dejavoo_batch_number)
    ORDER BY sb_inner.closed_at DESC NULLS LAST, sb_inner.created_at DESC
    LIMIT 1
  ) sb ON true
  WHERE op.order_id = p_order_id;

  SELECT COALESCE(
    jsonb_agg(
      (
        to_jsonb(oi)
        || jsonb_build_object(
          'modifiers', COALESCE(
            (
              SELECT jsonb_agg(to_jsonb(oim) ORDER BY oim.created_at)
              FROM public.order_item_modifiers oim
              WHERE oim.order_item_id = oi.id
            ),
            '[]'::jsonb
          )
        )
      )
      ORDER BY oi.created_at, oi.display_order
    ),
    '[]'::jsonb
  )
  INTO v_order_items
  FROM public.order_items oi
  WHERE oi.order_id = p_order_id;

  SELECT COALESCE(
    jsonb_agg(to_jsonb(od) ORDER BY od.applied_at, od.created_at),
    '[]'::jsonb
  )
  INTO v_order_discounts
  FROM public.order_discounts od
  WHERE od.order_id = p_order_id;

  RETURN jsonb_build_object(
    'order', v_order_enriched,
    'payments', v_payments,
    'order_items', v_order_items,
    'order_discounts', v_order_discounts
  );
END;
$$;


ALTER FUNCTION "public"."get_admin_transaction_detail"("p_order_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admin_transaction_detail"("p_order_id" "uuid") IS 'Returns HQ admin-scoped transaction details for one order, including payments, payment events, items paid, settlement, and full order breakdown.';



CREATE OR REPLACE FUNCTION "public"."get_admin_transaction_summary"("p_merchant_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_status" "text"[] DEFAULT NULL::"text"[], "p_payment_status" "text"[] DEFAULT NULL::"text"[], "p_payment_method" "text"[] DEFAULT NULL::"text"[], "p_date_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_date_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_min_amount" numeric DEFAULT NULL::numeric, "p_max_amount" numeric DEFAULT NULL::numeric, "p_search" "text" DEFAULT NULL::"text", "p_card_type" "text" DEFAULT NULL::"text", "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_sort_by" "text" DEFAULT 'initiated_at'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text") RETURNS TABLE("current_period_from" timestamp with time zone, "current_period_to" timestamp with time zone, "previous_period_from" timestamp with time zone, "previous_period_to" timestamp with time zone, "current_total_transactions" bigint, "previous_total_transactions" bigint, "current_card_revenue" numeric, "previous_card_revenue" numeric, "current_card_count" bigint, "previous_card_count" bigint, "current_cash_revenue" numeric, "previous_cash_revenue" numeric, "current_cash_count" bigint, "previous_cash_count" bigint, "current_total_revenue" numeric, "previous_total_revenue" numeric, "current_avg_tip" numeric, "previous_avg_tip" numeric, "current_avg_tip_pct" numeric, "previous_avg_tip_pct" numeric, "current_void_return_count" bigint, "previous_void_return_count" bigint, "current_void_return_amount" numeric, "previous_void_return_amount" numeric, "current_void_rate_pct" numeric, "previous_void_rate_pct" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_search text := NULLIF(trim(p_search), '');
  v_allowed_merchants uuid[];
  v_filter_merchants uuid[];
  v_card_tokens text[];
  v_current_from timestamptz;
  v_current_to timestamptz;
  v_previous_from timestamptz;
  v_previous_to timestamptz;
  v_window interval;
BEGIN
  IF NOT public.is_dexapos_admin() THEN
    RETURN;
  END IF;

  -- Keep signature parity with list RPC (sorting is ignored for aggregates).
  PERFORM p_sort_by, p_sort_dir;

  v_current_from := COALESCE(p_date_from, date_trunc('day', now()) - interval '29 days');
  v_current_to := COALESCE(p_date_to, now());

  IF p_date_from IS NULL AND p_date_to IS NOT NULL THEN
    v_current_from := p_date_to - interval '29 days';
  END IF;

  IF p_date_from IS NOT NULL AND p_date_to IS NULL THEN
    v_current_to := now();
  END IF;

  IF v_current_to <= v_current_from THEN
    v_current_to := v_current_from + interval '1 second';
  END IF;

  v_window := v_current_to - v_current_from;
  IF v_window < interval '1 second' THEN
    v_window := interval '1 day';
  END IF;

  v_previous_to := v_current_from;
  v_previous_from := v_current_from - v_window;

  SELECT COALESCE(array_agg(mid), ARRAY[]::uuid[])
  INTO v_allowed_merchants
  FROM public.get_admin_merchant_ids() AS mid;

  IF p_merchant_ids IS NULL OR array_length(p_merchant_ids, 1) IS NULL THEN
    v_filter_merchants := v_allowed_merchants;
  ELSE
    SELECT COALESCE(array_agg(mid), ARRAY[]::uuid[])
    INTO v_filter_merchants
    FROM unnest(p_merchant_ids) AS mid
    WHERE mid = ANY (v_allowed_merchants);
  END IF;

  IF NULLIF(trim(COALESCE(p_card_type, '')), '') IS NOT NULL THEN
    v_card_tokens := ARRAY(
      SELECT trim(token)
      FROM unnest(string_to_array(lower(p_card_type), ',')) AS token
      WHERE trim(token) <> ''
    );
  ELSE
    v_card_tokens := ARRAY[]::text[];
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT
      op.id AS payment_id,
      COALESCE(op.captured_at, op.initiated_at, o.created_at) AS event_ts,
      op.payment_method::text AS payment_method,
      op.status::text AS payment_status,
      op.total_amount::numeric AS total_amount,
      op.tip_amount::numeric AS tip_amount,
      op.amount::numeric AS amount,
      COALESCE(op.is_voided, false) AS is_voided,
      COALESCE(op.is_returned, false) AS is_returned,
      op.return_amount::numeric AS return_amount
    FROM public.order_payments op
    JOIN public.orders o
      ON o.id = op.order_id
    WHERE o.merchant_id = ANY (v_filter_merchants)
      AND (p_location_ids IS NULL OR o.location_id = ANY (p_location_ids))
      AND (p_status IS NULL OR o.status::text = ANY (p_status))
      AND (
        (p_payment_status IS NULL AND op.status::text <> ALL (ARRAY['pending', 'failed']))
        OR (p_payment_status IS NOT NULL AND op.status::text = ANY (p_payment_status))
      )
      AND (p_payment_method IS NULL OR op.payment_method::text = ANY (p_payment_method))
      AND (p_min_amount IS NULL OR op.total_amount >= p_min_amount)
      AND (p_max_amount IS NULL OR op.total_amount <= p_max_amount)
      AND (
        p_staff_id IS NULL
        OR op.processed_by_staff_id = p_staff_id
        OR o.created_by_staff_id = p_staff_id
      )
      AND (
        COALESCE(array_length(v_card_tokens, 1), 0) = 0
        OR EXISTS (
          SELECT 1
          FROM unnest(v_card_tokens) AS token
          WHERE lower(COALESCE(op.card_type, '')) LIKE '%' || token || '%'
        )
      )
      AND (
        v_search IS NULL
        OR COALESCE(o.order_number, '') ILIKE '%' || v_search || '%'
        OR COALESCE(o.display_number, '') ILIKE '%' || v_search || '%'
        OR COALESCE(o.customer_name, '') ILIKE '%' || v_search || '%'
        OR COALESCE(op.card_last_four, '') ILIKE '%' || v_search || '%'
        OR COALESCE(op.authorization_code, '') ILIKE '%' || v_search || '%'
        OR COALESCE(op.reference_number, '') ILIKE '%' || v_search || '%'
      )
  ),
  current_scope AS (
    SELECT *
    FROM base
    WHERE event_ts >= v_current_from
      AND event_ts <= v_current_to
  ),
  previous_scope AS (
    SELECT *
    FROM base
    WHERE event_ts >= v_previous_from
      AND event_ts < v_previous_to
  ),
  current_metrics AS (
    SELECT
      COUNT(*)::bigint AS total_transactions,
      COALESCE(
        SUM(
          CASE
            WHEN payment_status = 'captured'
              AND payment_method IN ('card', 'card_spinapi', 'card_dvpaylite')
            THEN total_amount
            ELSE 0
          END
        ),
        0
      )::numeric AS card_revenue,
      COUNT(*) FILTER (
        WHERE payment_status = 'captured'
          AND payment_method IN ('card', 'card_spinapi', 'card_dvpaylite')
      )::bigint AS card_count,
      COALESCE(
        SUM(
          CASE
            WHEN payment_status = 'captured' AND payment_method = 'cash'
            THEN total_amount
            ELSE 0
          END
        ),
        0
      )::numeric AS cash_revenue,
      COUNT(*) FILTER (
        WHERE payment_status = 'captured' AND payment_method = 'cash'
      )::bigint AS cash_count,
      COALESCE(
        AVG(
          CASE
            WHEN payment_status = 'captured'
              AND payment_method IN ('card', 'card_spinapi', 'card_dvpaylite')
            THEN tip_amount
            ELSE NULL
          END
        ),
        0
      )::numeric AS avg_tip,
      COALESCE(
        AVG(
          CASE
            WHEN payment_status = 'captured'
              AND payment_method IN ('card', 'card_spinapi', 'card_dvpaylite')
              AND amount > 0
            THEN (tip_amount / amount) * 100
            ELSE NULL
          END
        ),
        0
      )::numeric AS avg_tip_pct,
      COUNT(*) FILTER (
        WHERE is_voided OR is_returned
      )::bigint AS void_return_count,
      COALESCE(
        SUM(
          CASE
            WHEN is_returned THEN COALESCE(return_amount, 0)
            WHEN is_voided THEN COALESCE(total_amount, 0)
            ELSE 0
          END
        ),
        0
      )::numeric AS void_return_amount,
      CASE
        WHEN COUNT(*) > 0 THEN
          (
            COUNT(*) FILTER (WHERE is_voided OR is_returned)::numeric
            / COUNT(*)::numeric
          ) * 100
        ELSE 0
      END::numeric AS void_rate_pct
    FROM current_scope
  ),
  previous_metrics AS (
    SELECT
      COUNT(*)::bigint AS total_transactions,
      COALESCE(
        SUM(
          CASE
            WHEN payment_status = 'captured'
              AND payment_method IN ('card', 'card_spinapi', 'card_dvpaylite')
            THEN total_amount
            ELSE 0
          END
        ),
        0
      )::numeric AS card_revenue,
      COUNT(*) FILTER (
        WHERE payment_status = 'captured'
          AND payment_method IN ('card', 'card_spinapi', 'card_dvpaylite')
      )::bigint AS card_count,
      COALESCE(
        SUM(
          CASE
            WHEN payment_status = 'captured' AND payment_method = 'cash'
            THEN total_amount
            ELSE 0
          END
        ),
        0
      )::numeric AS cash_revenue,
      COUNT(*) FILTER (
        WHERE payment_status = 'captured' AND payment_method = 'cash'
      )::bigint AS cash_count,
      COALESCE(
        AVG(
          CASE
            WHEN payment_status = 'captured'
              AND payment_method IN ('card', 'card_spinapi', 'card_dvpaylite')
            THEN tip_amount
            ELSE NULL
          END
        ),
        0
      )::numeric AS avg_tip,
      COALESCE(
        AVG(
          CASE
            WHEN payment_status = 'captured'
              AND payment_method IN ('card', 'card_spinapi', 'card_dvpaylite')
              AND amount > 0
            THEN (tip_amount / amount) * 100
            ELSE NULL
          END
        ),
        0
      )::numeric AS avg_tip_pct,
      COUNT(*) FILTER (
        WHERE is_voided OR is_returned
      )::bigint AS void_return_count,
      COALESCE(
        SUM(
          CASE
            WHEN is_returned THEN COALESCE(return_amount, 0)
            WHEN is_voided THEN COALESCE(total_amount, 0)
            ELSE 0
          END
        ),
        0
      )::numeric AS void_return_amount,
      CASE
        WHEN COUNT(*) > 0 THEN
          (
            COUNT(*) FILTER (WHERE is_voided OR is_returned)::numeric
            / COUNT(*)::numeric
          ) * 100
        ELSE 0
      END::numeric AS void_rate_pct
    FROM previous_scope
  )
  SELECT
    v_current_from,
    v_current_to,
    v_previous_from,
    v_previous_to,
    cm.total_transactions,
    pm.total_transactions,
    cm.card_revenue,
    pm.card_revenue,
    cm.card_count,
    pm.card_count,
    cm.cash_revenue,
    pm.cash_revenue,
    cm.cash_count,
    pm.cash_count,
    (cm.card_revenue + cm.cash_revenue)::numeric AS current_total_revenue,
    (pm.card_revenue + pm.cash_revenue)::numeric AS previous_total_revenue,
    cm.avg_tip,
    pm.avg_tip,
    cm.avg_tip_pct,
    pm.avg_tip_pct,
    cm.void_return_count,
    pm.void_return_count,
    cm.void_return_amount,
    pm.void_return_amount,
    cm.void_rate_pct,
    pm.void_rate_pct
  FROM current_metrics cm
  CROSS JOIN previous_metrics pm;
END;
$$;


ALTER FUNCTION "public"."get_admin_transaction_summary"("p_merchant_ids" "uuid"[], "p_location_ids" "uuid"[], "p_status" "text"[], "p_payment_status" "text"[], "p_payment_method" "text"[], "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_min_amount" numeric, "p_max_amount" numeric, "p_search" "text", "p_card_type" "text", "p_staff_id" "uuid", "p_sort_by" "text", "p_sort_dir" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admin_transaction_summary"("p_merchant_ids" "uuid"[], "p_location_ids" "uuid"[], "p_status" "text"[], "p_payment_status" "text"[], "p_payment_method" "text"[], "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_min_amount" numeric, "p_max_amount" numeric, "p_search" "text", "p_card_type" "text", "p_staff_id" "uuid", "p_sort_by" "text", "p_sort_dir" "text") IS 'HQ admin summary aggregates with assignment-scoped merchant intersection and prior-equivalent-period comparison.';



CREATE OR REPLACE FUNCTION "public"."get_admin_transactions"("p_merchant_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_status" "text"[] DEFAULT NULL::"text"[], "p_payment_status" "text"[] DEFAULT NULL::"text"[], "p_payment_method" "text"[] DEFAULT NULL::"text"[], "p_date_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_date_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_min_amount" numeric DEFAULT NULL::numeric, "p_max_amount" numeric DEFAULT NULL::numeric, "p_search" "text" DEFAULT NULL::"text", "p_card_type" "text" DEFAULT NULL::"text", "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_sort_by" "text" DEFAULT 'initiated_at'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 25) RETURNS TABLE("id" "uuid", "order_id" "uuid", "order_number" "text", "display_number" "text", "merchant_id" "uuid", "merchant_name" "text", "location_id" "uuid", "location_name" "text", "customer_name" "text", "payment_method" "text", "card_type" "text", "card_last_four" "text", "authorization_code" "text", "reference_number" "text", "amount" numeric, "tip_amount" numeric, "total_amount" numeric, "subtotal_amount" numeric, "tax_amount" numeric, "discount_amount" numeric, "status" "text", "order_status" "text", "payment_status" "text", "staff_id" "uuid", "staff_name" "text", "entry_mode" "text", "created_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_page integer := GREATEST(COALESCE(p_page, 1), 1);
  v_page_size integer := LEAST(GREATEST(COALESCE(p_page_size, 25), 1), 200);
  v_offset integer := (v_page - 1) * v_page_size;
  v_sort_by text;
  v_sort_dir text;
  v_search text := NULLIF(trim(p_search), '');
  v_allowed_merchants uuid[];
  v_filter_merchants uuid[];
  v_card_tokens text[];
BEGIN
  IF NOT public.is_dexapos_admin() THEN
    RETURN;
  END IF;

  SELECT COALESCE(array_agg(mid), ARRAY[]::uuid[])
  INTO v_allowed_merchants
  FROM public.get_admin_merchant_ids() AS mid;

  IF COALESCE(array_length(v_allowed_merchants, 1), 0) = 0 THEN
    RETURN;
  END IF;

  IF p_merchant_ids IS NULL OR array_length(p_merchant_ids, 1) IS NULL THEN
    v_filter_merchants := v_allowed_merchants;
  ELSE
    SELECT COALESCE(array_agg(mid), ARRAY[]::uuid[])
    INTO v_filter_merchants
    FROM unnest(p_merchant_ids) AS mid
    WHERE mid = ANY (v_allowed_merchants);

    IF COALESCE(array_length(v_filter_merchants, 1), 0) = 0 THEN
      RETURN;
    END IF;
  END IF;

  v_sort_by := lower(COALESCE(p_sort_by, 'initiated_at'));
  IF v_sort_by NOT IN (
    'initiated_at',
    'created_at',
    'order_number',
    'total_amount',
    'amount',
    'tip_amount',
    'merchant_name',
    'location_name',
    'customer_name',
    'status',
    'payment_method'
  ) THEN
    v_sort_by := 'initiated_at';
  END IF;

  v_sort_dir := lower(COALESCE(p_sort_dir, 'desc'));
  IF v_sort_dir NOT IN ('asc', 'desc') THEN
    v_sort_dir := 'desc';
  END IF;

  IF NULLIF(trim(COALESCE(p_card_type, '')), '') IS NOT NULL THEN
    v_card_tokens := ARRAY(
      SELECT trim(token)
      FROM unnest(string_to_array(lower(p_card_type), ',')) AS token
      WHERE trim(token) <> ''
    );
  ELSE
    v_card_tokens := ARRAY[]::text[];
  END IF;

  RETURN QUERY
  WITH filtered AS (
    SELECT
      op.id,
      op.order_id,
      o.order_number,
      o.display_number,
      o.merchant_id AS merchant_id,
      m.name AS merchant_name,
      o.location_id AS location_id,
      l.name AS location_name,
      o.customer_name,
      op.payment_method::text AS payment_method,
      op.card_type,
      op.card_last_four,
      op.authorization_code,
      op.reference_number,
      op.amount::numeric AS amount,
      op.tip_amount::numeric AS tip_amount,
      op.total_amount::numeric AS total_amount,
      o.subtotal::numeric AS subtotal_amount,
      o.tax_amount::numeric AS tax_amount,
      o.discount_amount::numeric AS discount_amount,
      op.status::text AS status,
      o.status::text AS order_status,
      o.payment_status::text AS payment_status,
      COALESCE(op.processed_by_staff_id, o.created_by_staff_id) AS staff_id,
      trim(concat_ws(' ', sp.first_name, sp.last_name)) AS staff_name,
      COALESCE(
        NULLIF(op.processor_response->>'entry_type', ''),
        NULLIF(op.processor_response->>'entryType', ''),
        NULLIF(op.processor_response->>'entry_mode', ''),
        NULLIF(op.processor_response->>'entryMode', '')
      ) AS entry_mode,
      COALESCE(op.captured_at, op.initiated_at, o.created_at) AS created_at
    FROM public.order_payments op
    JOIN public.orders o
      ON o.id = op.order_id
    JOIN public.merchants m
      ON m.id = o.merchant_id
    LEFT JOIN public.locations l
      ON l.id = o.location_id
    LEFT JOIN public.staff_profiles sp
      ON sp.id = COALESCE(op.processed_by_staff_id, o.created_by_staff_id)
    WHERE o.merchant_id = ANY (v_filter_merchants)
      AND (p_location_ids IS NULL OR o.location_id = ANY (p_location_ids))
      AND (p_status IS NULL OR o.status::text = ANY (p_status))
      AND (
        (p_payment_status IS NULL AND op.status::text <> ALL (ARRAY['pending', 'failed']))
        OR (p_payment_status IS NOT NULL AND op.status::text = ANY (p_payment_status))
      )
      AND (p_payment_method IS NULL OR op.payment_method::text = ANY (p_payment_method))
      AND (p_date_from IS NULL OR COALESCE(op.captured_at, op.initiated_at, o.created_at) >= p_date_from)
      AND (p_date_to IS NULL OR COALESCE(op.captured_at, op.initiated_at, o.created_at) <= p_date_to)
      AND (p_min_amount IS NULL OR op.total_amount >= p_min_amount)
      AND (p_max_amount IS NULL OR op.total_amount <= p_max_amount)
      AND (
        p_staff_id IS NULL
        OR op.processed_by_staff_id = p_staff_id
        OR o.created_by_staff_id = p_staff_id
      )
      AND (
        COALESCE(array_length(v_card_tokens, 1), 0) = 0
        OR EXISTS (
          SELECT 1
          FROM unnest(v_card_tokens) AS token
          WHERE lower(COALESCE(op.card_type, '')) LIKE '%' || token || '%'
        )
      )
      AND (
        v_search IS NULL
        OR COALESCE(o.order_number, '') ILIKE '%' || v_search || '%'
        OR COALESCE(o.display_number, '') ILIKE '%' || v_search || '%'
        OR COALESCE(o.customer_name, '') ILIKE '%' || v_search || '%'
        OR COALESCE(op.card_last_four, '') ILIKE '%' || v_search || '%'
        OR COALESCE(op.authorization_code, '') ILIKE '%' || v_search || '%'
        OR COALESCE(op.reference_number, '') ILIKE '%' || v_search || '%'
      )
  ),
  counted AS (
    SELECT f.*, COUNT(*) OVER() AS total_count
    FROM filtered f
  )
  SELECT
    c.id,
    c.order_id,
    c.order_number,
    c.display_number,
    c.merchant_id,
    c.merchant_name,
    c.location_id,
    c.location_name,
    c.customer_name,
    c.payment_method,
    c.card_type,
    c.card_last_four,
    c.authorization_code,
    c.reference_number,
    c.amount,
    c.tip_amount,
    c.total_amount,
    c.subtotal_amount,
    c.tax_amount,
    c.discount_amount,
    c.status,
    c.order_status,
    c.payment_status,
    c.staff_id,
    NULLIF(c.staff_name, ''),
    c.entry_mode,
    c.created_at,
    c.total_count
  FROM counted c
  ORDER BY
    CASE WHEN v_sort_by = 'order_number'   AND v_sort_dir = 'asc'  THEN c.order_number END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'order_number'   AND v_sort_dir = 'desc' THEN c.order_number END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'total_amount'   AND v_sort_dir = 'asc'  THEN c.total_amount END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'total_amount'   AND v_sort_dir = 'desc' THEN c.total_amount END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'amount'         AND v_sort_dir = 'asc'  THEN c.amount END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'amount'         AND v_sort_dir = 'desc' THEN c.amount END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'tip_amount'     AND v_sort_dir = 'asc'  THEN c.tip_amount END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'tip_amount'     AND v_sort_dir = 'desc' THEN c.tip_amount END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'merchant_name'  AND v_sort_dir = 'asc'  THEN c.merchant_name END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'merchant_name'  AND v_sort_dir = 'desc' THEN c.merchant_name END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'location_name'  AND v_sort_dir = 'asc'  THEN c.location_name END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'location_name'  AND v_sort_dir = 'desc' THEN c.location_name END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'customer_name'  AND v_sort_dir = 'asc'  THEN c.customer_name END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'customer_name'  AND v_sort_dir = 'desc' THEN c.customer_name END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'status'         AND v_sort_dir = 'asc'  THEN c.status END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'status'         AND v_sort_dir = 'desc' THEN c.status END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'payment_method' AND v_sort_dir = 'asc'  THEN c.payment_method END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'payment_method' AND v_sort_dir = 'desc' THEN c.payment_method END DESC NULLS LAST,
    CASE WHEN v_sort_by IN ('initiated_at', 'created_at') AND v_sort_dir = 'asc'  THEN c.created_at END ASC NULLS LAST,
    CASE WHEN v_sort_by IN ('initiated_at', 'created_at') AND v_sort_dir = 'desc' THEN c.created_at END DESC NULLS LAST,
    c.created_at DESC
  LIMIT v_page_size
  OFFSET v_offset;
END;
$$;


ALTER FUNCTION "public"."get_admin_transactions"("p_merchant_ids" "uuid"[], "p_location_ids" "uuid"[], "p_status" "text"[], "p_payment_status" "text"[], "p_payment_method" "text"[], "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_min_amount" numeric, "p_max_amount" numeric, "p_search" "text", "p_card_type" "text", "p_staff_id" "uuid", "p_sort_by" "text", "p_sort_dir" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admin_transactions"("p_merchant_ids" "uuid"[], "p_location_ids" "uuid"[], "p_status" "text"[], "p_payment_status" "text"[], "p_payment_method" "text"[], "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_min_amount" numeric, "p_max_amount" numeric, "p_search" "text", "p_card_type" "text", "p_staff_id" "uuid", "p_sort_by" "text", "p_sort_dir" "text", "p_page" integer, "p_page_size" integer) IS 'HQ admin transactions query with assignment-scoped merchant intersection, filters, sorting, and pagination.';



CREATE OR REPLACE FUNCTION "public"."get_admin_transactions_export"("p_merchant_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_status" "text"[] DEFAULT NULL::"text"[], "p_payment_status" "text"[] DEFAULT NULL::"text"[], "p_payment_method" "text"[] DEFAULT NULL::"text"[], "p_date_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_date_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_min_amount" numeric DEFAULT NULL::numeric, "p_max_amount" numeric DEFAULT NULL::numeric, "p_search" "text" DEFAULT NULL::"text", "p_card_type" "text" DEFAULT NULL::"text", "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_sort_by" "text" DEFAULT 'initiated_at'::"text", "p_sort_dir" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 10000) RETURNS TABLE("payment_id" "uuid", "order_id" "uuid", "order_number" "text", "display_number" "text", "created_at" timestamp with time zone, "merchant_id" "uuid", "merchant_name" "text", "location_id" "uuid", "location_name" "text", "customer_name" "text", "order_type" "text", "order_status" "text", "payment_method" "text", "card_type" "text", "card_last_four" "text", "entry_mode" "text", "authorization_code" "text", "reference_number" "text", "batch_number" "text", "subtotal_amount" numeric, "tax_amount" numeric, "tip_amount" numeric, "discount_amount" numeric, "service_charge_amount" numeric, "total_amount" numeric, "amount_tendered" numeric, "change_given" numeric, "payment_status" "text", "is_voided" boolean, "void_reason" "text", "is_returned" boolean, "return_amount" numeric, "return_reason" "text", "staff_name" "text", "terminal_serial" "text", "device_id" "text", "total_count" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sort_by text;
  v_sort_dir text;
  v_search text := NULLIF(trim(p_search), '');
  v_allowed_merchants uuid[];
  v_filter_merchants uuid[];
  v_card_tokens text[];
  v_export_limit integer := LEAST(GREATEST(COALESCE(p_limit, 10000), 1), 10000);
BEGIN
  IF NOT public.is_dexapos_admin() THEN
    RETURN;
  END IF;

  SELECT COALESCE(array_agg(mid), ARRAY[]::uuid[])
  INTO v_allowed_merchants
  FROM public.get_admin_merchant_ids() AS mid;

  IF COALESCE(array_length(v_allowed_merchants, 1), 0) = 0 THEN
    RETURN;
  END IF;

  IF p_merchant_ids IS NULL OR array_length(p_merchant_ids, 1) IS NULL THEN
    v_filter_merchants := v_allowed_merchants;
  ELSE
    SELECT COALESCE(array_agg(mid), ARRAY[]::uuid[])
    INTO v_filter_merchants
    FROM unnest(p_merchant_ids) AS mid
    WHERE mid = ANY (v_allowed_merchants);

    IF COALESCE(array_length(v_filter_merchants, 1), 0) = 0 THEN
      RETURN;
    END IF;
  END IF;

  v_sort_by := lower(COALESCE(p_sort_by, 'initiated_at'));
  IF v_sort_by NOT IN (
    'initiated_at',
    'created_at',
    'order_number',
    'total_amount',
    'merchant_name',
    'location_name',
    'customer_name',
    'payment_method',
    'payment_status'
  ) THEN
    v_sort_by := 'initiated_at';
  END IF;

  v_sort_dir := lower(COALESCE(p_sort_dir, 'desc'));
  IF v_sort_dir NOT IN ('asc', 'desc') THEN
    v_sort_dir := 'desc';
  END IF;

  IF NULLIF(trim(COALESCE(p_card_type, '')), '') IS NOT NULL THEN
    v_card_tokens := ARRAY(
      SELECT trim(token)
      FROM unnest(string_to_array(lower(p_card_type), ',')) AS token
      WHERE trim(token) <> ''
    );
  ELSE
    v_card_tokens := ARRAY[]::text[];
  END IF;

  RETURN QUERY
  WITH filtered AS (
    SELECT
      op.id AS payment_id,
      op.order_id,
      o.order_number,
      o.display_number,
      COALESCE(op.captured_at, op.initiated_at, o.created_at) AS created_at,
      o.merchant_id,
      m.name AS merchant_name,
      o.location_id,
      l.name AS location_name,
      COALESCE(NULLIF(o.customer_name, ''), 'Walk-in') AS customer_name,
      o.order_type::text AS order_type,
      o.status::text AS order_status,
      op.payment_method::text AS payment_method,
      op.card_type,
      op.card_last_four,
      COALESCE(
        NULLIF(op.processor_response->>'entry_type', ''),
        NULLIF(op.processor_response->>'entryType', ''),
        NULLIF(op.processor_response->>'entry_mode', ''),
        NULLIF(op.processor_response->>'entryMode', ''),
        NULLIF(op.terminal_response->>'entry_type', ''),
        NULLIF(op.terminal_response->>'entryType', ''),
        NULLIF(op.terminal_response->>'entry_mode', ''),
        NULLIF(op.terminal_response->>'entryMode', '')
      ) AS entry_mode,
      op.authorization_code,
      op.reference_number,
      COALESCE(op.batch_number::text, op.dejavoo_batch_number)::text AS batch_number,
      o.subtotal::numeric AS subtotal_amount,
      o.tax_amount::numeric AS tax_amount,
      op.tip_amount::numeric AS tip_amount,
      o.discount_amount::numeric AS discount_amount,
      o.service_charge::numeric AS service_charge_amount,
      op.total_amount::numeric AS total_amount,
      op.amount_tendered::numeric AS amount_tendered,
      op.change_given::numeric AS change_given,
      op.status::text AS payment_status,
      COALESCE(op.is_voided, false) AS is_voided,
      op.void_reason,
      COALESCE(op.is_returned, false) AS is_returned,
      op.return_amount::numeric AS return_amount,
      op.return_reason::text AS return_reason,
      NULLIF(trim(concat_ws(' ', sp.first_name, sp.last_name)), '') AS staff_name,
      COALESCE(pt.serial_number, NULLIF(op.terminal_id, '')) AS terminal_serial,
      COALESCE(NULLIF(op.device_id, ''), NULLIF(o.device_id, '')) AS device_id
    FROM public.order_payments op
    JOIN public.orders o
      ON o.id = op.order_id
    JOIN public.merchants m
      ON m.id = o.merchant_id
    LEFT JOIN public.locations l
      ON l.id = o.location_id
    LEFT JOIN public.staff_profiles sp
      ON sp.id = COALESCE(op.processed_by_staff_id, o.created_by_staff_id)
    LEFT JOIN LATERAL (
      SELECT pt_inner.*
      FROM public.payment_terminals pt_inner
      WHERE pt_inner.location_id = COALESCE(op.location_id, o.location_id)
        AND (
          op.terminal_id IS NULL
          OR pt_inner.serial_number = op.terminal_id
          OR pt_inner.tpn = op.terminal_id
          OR pt_inner.id::text = op.terminal_id
        )
      ORDER BY
        CASE
          WHEN op.terminal_id IS NOT NULL AND pt_inner.serial_number = op.terminal_id THEN 0
          WHEN op.terminal_id IS NOT NULL AND pt_inner.tpn = op.terminal_id THEN 1
          WHEN op.terminal_id IS NOT NULL AND pt_inner.id::text = op.terminal_id THEN 2
          ELSE 3
        END,
        pt_inner.updated_at DESC
      LIMIT 1
    ) pt ON true
    WHERE o.merchant_id = ANY (v_filter_merchants)
      AND (p_location_ids IS NULL OR o.location_id = ANY (p_location_ids))
      AND (p_status IS NULL OR o.status::text = ANY (p_status))
      AND (
        (p_payment_status IS NULL AND op.status::text <> ALL (ARRAY['pending', 'failed']))
        OR (p_payment_status IS NOT NULL AND op.status::text = ANY (p_payment_status))
      )
      AND (p_payment_method IS NULL OR op.payment_method::text = ANY (p_payment_method))
      AND (p_date_from IS NULL OR COALESCE(op.captured_at, op.initiated_at, o.created_at) >= p_date_from)
      AND (p_date_to IS NULL OR COALESCE(op.captured_at, op.initiated_at, o.created_at) <= p_date_to)
      AND (p_min_amount IS NULL OR op.total_amount >= p_min_amount)
      AND (p_max_amount IS NULL OR op.total_amount <= p_max_amount)
      AND (
        p_staff_id IS NULL
        OR op.processed_by_staff_id = p_staff_id
        OR o.created_by_staff_id = p_staff_id
      )
      AND (
        COALESCE(array_length(v_card_tokens, 1), 0) = 0
        OR EXISTS (
          SELECT 1
          FROM unnest(v_card_tokens) AS token
          WHERE lower(COALESCE(op.card_type, '')) LIKE '%' || token || '%'
        )
      )
      AND (
        v_search IS NULL
        OR COALESCE(o.order_number, '') ILIKE '%' || v_search || '%'
        OR COALESCE(o.display_number, '') ILIKE '%' || v_search || '%'
        OR COALESCE(o.customer_name, '') ILIKE '%' || v_search || '%'
        OR COALESCE(op.card_last_four, '') ILIKE '%' || v_search || '%'
        OR COALESCE(op.authorization_code, '') ILIKE '%' || v_search || '%'
        OR COALESCE(op.reference_number, '') ILIKE '%' || v_search || '%'
      )
  ),
  counted AS (
    SELECT f.*, COUNT(*) OVER() AS total_count
    FROM filtered f
  )
  SELECT
    c.payment_id,
    c.order_id,
    c.order_number,
    c.display_number,
    c.created_at,
    c.merchant_id,
    c.merchant_name,
    c.location_id,
    c.location_name,
    c.customer_name,
    c.order_type,
    c.order_status,
    c.payment_method,
    c.card_type,
    c.card_last_four,
    c.entry_mode,
    c.authorization_code,
    c.reference_number,
    c.batch_number,
    c.subtotal_amount,
    c.tax_amount,
    c.tip_amount,
    c.discount_amount,
    c.service_charge_amount,
    c.total_amount,
    c.amount_tendered,
    c.change_given,
    c.payment_status,
    c.is_voided,
    c.void_reason,
    c.is_returned,
    c.return_amount,
    c.return_reason,
    c.staff_name,
    c.terminal_serial,
    c.device_id,
    c.total_count
  FROM counted c
  ORDER BY
    CASE WHEN v_sort_by = 'order_number'   AND v_sort_dir = 'asc'  THEN c.order_number END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'order_number'   AND v_sort_dir = 'desc' THEN c.order_number END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'total_amount'   AND v_sort_dir = 'asc'  THEN c.total_amount END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'total_amount'   AND v_sort_dir = 'desc' THEN c.total_amount END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'merchant_name'  AND v_sort_dir = 'asc'  THEN c.merchant_name END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'merchant_name'  AND v_sort_dir = 'desc' THEN c.merchant_name END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'location_name'  AND v_sort_dir = 'asc'  THEN c.location_name END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'location_name'  AND v_sort_dir = 'desc' THEN c.location_name END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'customer_name'  AND v_sort_dir = 'asc'  THEN c.customer_name END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'customer_name'  AND v_sort_dir = 'desc' THEN c.customer_name END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'payment_method' AND v_sort_dir = 'asc'  THEN c.payment_method END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'payment_method' AND v_sort_dir = 'desc' THEN c.payment_method END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'payment_status' AND v_sort_dir = 'asc'  THEN c.payment_status END ASC NULLS LAST,
    CASE WHEN v_sort_by = 'payment_status' AND v_sort_dir = 'desc' THEN c.payment_status END DESC NULLS LAST,
    CASE WHEN v_sort_by IN ('initiated_at', 'created_at') AND v_sort_dir = 'asc'  THEN c.created_at END ASC NULLS LAST,
    CASE WHEN v_sort_by IN ('initiated_at', 'created_at') AND v_sort_dir = 'desc' THEN c.created_at END DESC NULLS LAST,
    c.created_at DESC
  LIMIT v_export_limit;
END;
$$;


ALTER FUNCTION "public"."get_admin_transactions_export"("p_merchant_ids" "uuid"[], "p_location_ids" "uuid"[], "p_status" "text"[], "p_payment_status" "text"[], "p_payment_method" "text"[], "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_min_amount" numeric, "p_max_amount" numeric, "p_search" "text", "p_card_type" "text", "p_staff_id" "uuid", "p_sort_by" "text", "p_sort_dir" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admin_transactions_export"("p_merchant_ids" "uuid"[], "p_location_ids" "uuid"[], "p_status" "text"[], "p_payment_status" "text"[], "p_payment_method" "text"[], "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_min_amount" numeric, "p_max_amount" numeric, "p_search" "text", "p_card_type" "text", "p_staff_id" "uuid", "p_sort_by" "text", "p_sort_dir" "text", "p_limit" integer) IS 'HQ admin export query for transactions with assignment-scoped merchant intersection and a hard 10,000-row cap.';



CREATE OR REPLACE FUNCTION "public"."get_aggregate_stock"("p_inventory_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'total_stock', COALESCE(SUM(stock_quantity), 0),
        'location_count', COUNT(DISTINCT location_id),
        'low_stock_count', COUNT(*) FILTER (
            WHERE stock_quantity <= COALESCE(reorder_threshold, 
                (SELECT reorder_threshold FROM inventory_items WHERE id = p_inventory_item_id))
            AND stock_quantity > 0
        ),
        'out_of_stock_count', COUNT(*) FILTER (WHERE stock_quantity <= 0)
    ) INTO v_result
    FROM public.location_inventory_stock
    WHERE inventory_item_id = p_inventory_item_id;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_aggregate_stock"("p_inventory_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_avg_kitchen_time"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("date" "date", "avg_minutes" numeric, "overall_avg" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  WITH daily_avg AS (
    SELECT
      DATE(kis.created_at) AS kitchen_date,
      AVG(EXTRACT(EPOCH FROM (kis.bumped_at - kis.created_at)) / 60)::NUMERIC(10,2) AS avg_min
    FROM kds_item_status kis
    WHERE kis.created_at >= p_from
      AND kis.created_at < p_to
      AND kis.bumped_at IS NOT NULL
    GROUP BY DATE(kis.created_at)
  )
  SELECT
    d.kitchen_date AS date,
    d.avg_min AS avg_minutes,
    (
      SELECT AVG(EXTRACT(EPOCH FROM (kis.bumped_at - kis.created_at)) / 60)::NUMERIC(10,2)
      FROM kds_item_status kis
      WHERE kis.created_at >= p_from
        AND kis.created_at < p_to
        AND kis.bumped_at IS NOT NULL
    ) AS overall_avg
  FROM daily_avg d
  ORDER BY d.kitchen_date;
END;
$$;


ALTER FUNCTION "public"."get_avg_kitchen_time"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_avg_table_turn_time"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("date" "date", "avg_minutes" numeric, "overall_avg" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  WITH daily_avg AS (
    SELECT
      DATE(ts.seated_at) AS session_date,
      ROUND(
        AVG(
          COALESCE(
            ts.actual_duration,
            EXTRACT(EPOCH FROM (ts.closed_at - ts.seated_at)) / 60
          )
        ),
        2
      ) AS avg_min
    FROM table_sessions ts
    WHERE ts.seated_at >= p_from
      AND ts.seated_at < p_to
      AND ts.closed_at IS NOT NULL
    GROUP BY DATE(ts.seated_at)
  )
  SELECT
    d.session_date,
    d.avg_min,
    (
      SELECT ROUND(
        AVG(
          COALESCE(
            ts.actual_duration,
            EXTRACT(EPOCH FROM (ts.closed_at - ts.seated_at)) / 60
          )
        ),
        2
      )
      FROM table_sessions ts
      WHERE ts.seated_at >= p_from
        AND ts.seated_at < p_to
        AND ts.closed_at IS NOT NULL
    ) AS overall_avg
  FROM daily_avg d
  ORDER BY d.session_date;
END;
$$;


ALTER FUNCTION "public"."get_avg_table_turn_time"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_avg_ticket_by_day"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("date" "date", "avg_ticket" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    DATE(o.created_at) as date,
    AVG(o.total_amount)::NUMERIC(8,2) as avg_ticket
  FROM orders o
  WHERE o.created_at >= p_from AND o.created_at < p_to
    AND o.status NOT IN ('draft', 'cancelled', 'void')
  GROUP BY DATE(o.created_at)
  ORDER BY date;
END;
$$;


ALTER FUNCTION "public"."get_avg_ticket_by_day"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_avg_time_to_first_order"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("avg_days" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    AVG(EXTRACT(EPOCH FROM (o.created_at - m.created_at)) / 86400)::NUMERIC(5,2) as avg_days
  FROM merchants m
  JOIN LATERAL (
    SELECT created_at FROM orders WHERE merchant_id = m.id ORDER BY created_at LIMIT 1
  ) o ON TRUE
  WHERE m.created_at >= p_from AND m.created_at < p_to
    AND o.created_at >= p_from AND o.created_at < p_to;
END;
$$;


ALTER FUNCTION "public"."get_avg_time_to_first_order"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_busiest_locations"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("location_id" "uuid", "location_name" "text", "merchant_name" "text", "order_count" bigint)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    l.id,
    l.name,
    m.name,
    COUNT(*)::BIGINT as order_count
  FROM orders o
  JOIN locations l ON o.location_id = l.id
  JOIN merchants m ON o.merchant_id = m.id
  WHERE o.created_at >= p_from AND o.created_at < p_to
  GROUP BY l.id, l.name, m.name
  ORDER BY order_count DESC
  LIMIT 10;
END;
$$;


ALTER FUNCTION "public"."get_busiest_locations"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cash_flow_report"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN (
        SELECT COALESCE(json_agg(
            json_build_object(
                'order_number', o.order_number,
                'amount_collected', op.amount,
                'tip_amount', op.tip_amount,
                'total_amount', op.total_amount,
                'created_at', op.initiated_at,
                'staff_name', sp.first_name || ' ' || sp.last_name
            ) ORDER BY op.initiated_at DESC
        ), '[]'::json)
        FROM order_payments op
        JOIN orders o ON o.id = op.order_id
        LEFT JOIN staff_profiles sp ON sp.id = op.processed_by_staff_id
        WHERE o.merchant_id = p_merchant_id
          AND (p_location_id IS NULL OR o.location_id = p_location_id)
          AND op.payment_method = 'cash'
          AND op.status IN ('captured', 'authorized')
          AND op.initiated_at BETWEEN p_start_date AND p_end_date
    );
END;
$$;


ALTER FUNCTION "public"."get_cash_flow_report"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cash_vs_card_split"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("pricing_mode" "text", "order_count" bigint, "revenue" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(o.payment_pricing_mode::TEXT, 'unknown') as pricing_mode,
    COUNT(*)::BIGINT as order_count,
    COALESCE(SUM(o.total_amount), 0)::NUMERIC as revenue
  FROM orders o
  WHERE o.created_at >= p_from AND o.created_at < p_to
    AND o.status NOT IN ('draft', 'cancelled', 'void')
  GROUP BY o.payment_pricing_mode
  ORDER BY order_count DESC;
END;
$$;


ALTER FUNCTION "public"."get_cash_vs_card_split"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_categories_for_location"("p_merchant_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$BEGIN
    RETURN (
        SELECT COALESCE(json_agg(
            json_build_object(
                'id', c.id,
                'name', c.name,
                'description', c.description,
                'image', c.image,
                'display_order', c.display_order,
                
                -- Ownership info
                'location_id', c.location_id,
                'is_global', COALESCE(c.is_global, c.location_id IS NULL),
                'is_location_specific', (c.location_id IS NOT NULL),
                'location_name', (
                    SELECT l.name FROM locations l WHERE l.id = c.location_id
                ),
                'created_by', c.created_by,
                
                -- Global availability
                'is_active', c.is_active,
                
                -- Location override (only applies to global categories)
                'location_override', CASE 
                    WHEN c.location_id IS NULL AND lco.id IS NOT NULL THEN json_build_object(
                        'id', lco.id,
                        'is_active', lco.is_active,
                        'display_order', lco.display_order,
                        'custom_title', lco.custom_title
                    )
                    ELSE NULL
                END,
                
                -- Effective values
                'effective_is_active', CASE
                    -- Location-specific category: use its own is_active
                    WHEN c.location_id IS NOT NULL THEN c.is_active
                    -- Global category: check for location override
                    ELSE COALESCE(lco.is_active, c.is_active)
                END,
                'effective_display_order', CASE
                    WHEN c.location_id IS NOT NULL THEN c.display_order
                    ELSE COALESCE(lco.display_order, c.display_order)
                END,
                'effective_name', CASE
                    WHEN c.location_id IS NOT NULL THEN c.name
                    ELSE COALESCE(lco.custom_title, c.name)
                END,
                
                -- Items in this category
                'items', (
                    SELECT COALESCE(json_agg(
                        json_build_object(
                            'id', ci.id,
                            'menu_item_id', mi.id,
                            'display_order', ci.display_order,
                            'is_featured', ci.is_featured,
                            
                            -- Category-level price
                            'category_price', ci.custom_price,
                            'category_cash_price', ci.custom_cash_price,
                            'category_delivery_price', ci.custom_delivery_price,
                            'category_is_available', ci.is_available,
                            
                            'menu_item', json_build_object(
                                'id', mi.id,
                                'name', mi.name,
                                'description', mi.description,
                                'image', mi.image,
                                'allergens', mi.allergens,
                                'meal_types', mi.meal_types,
                                'card_bg_color', mi.card_bg_color,
                                'location_id', mi.location_id,
                                -- Level 1: Base price
                                'base_price', mi.price,
                                'base_cash_price', mi.cash_price,
                                'base_delivery_price', mi.delivery_price,
                                'base_availability', mi.availability,
                                
                                -- Level 2: Location item override
                                'location_item_override', CASE 
                                    WHEN lio.id IS NOT NULL THEN json_build_object(
                                        'id', lio.id,
                                        'custom_price', lio.custom_price,
                                        'custom_cash_price', lio.custom_cash_price,
                                        'custom_delivery_price', lio.custom_delivery_price,
                                        'price_modifier', lio.price_modifier,
                                        'price_modifier_type', lio.price_modifier_type,
                                        'is_available', lio.is_available,
                                        'stock_tracking_mode', lio.stock_tracking_mode,
                                        'current_stock', lio.current_stock
                                    )
                                    ELSE NULL
                                END,
                                
                                -- Level 4: Location + Category override
                                'location_category_override', CASE 
                                    WHEN lcio.id IS NOT NULL THEN json_build_object(
                                        'id', lcio.id,
                                        'custom_price', lcio.custom_price,
                                        'custom_cash_price', lcio.custom_cash_price,
                                        'custom_delivery_price', lcio.custom_delivery_price,
                                        'is_available', lcio.is_available
                                    )
                                    ELSE NULL
                                END,
                                
                                -- Effective price (full cascade)
                                'effective_price', COALESCE(
                                    lcio.custom_price,           -- L4: Location + Category
                                    ci.custom_price,             -- L3: Category
                                    lio.custom_price,            -- L2: Location item
                                    mi.price                     -- L1: Base
                                ),
                                
                                'effective_cash_price', COALESCE(
                                    lcio.custom_cash_price,
                                    ci.custom_cash_price,
                                    lio.custom_cash_price,
                                    mi.cash_price
                                ),

                                'effective_delivery_price', COALESCE(
                                    lcio.custom_delivery_price,
                                    ci.custom_delivery_price,
                                    lio.custom_delivery_price,
                                    mi.delivery_price
                                ),

                                -- Availability (AND logic)
                                'effective_availability', (
                                    mi.availability = true
                                    AND COALESCE(lio.is_available, true) = true
                                    AND COALESCE(ci.is_available, true) = true
                                    AND COALESCE(lcio.is_available, true) = true
                                ),

                                -- Item badges (location-specific)
                                -- is_new: stored per-branch in location_item_overrides
                                'is_new', COALESCE(lio.is_new, false),
                                'is_popular', (
                                    COALESCE(lio.is_popular, false)
                                    OR (
                                        p_location_id IS NOT NULL
                                        AND (
                                            SELECT COUNT(*) >= 10
                                            FROM order_items oi
                                            JOIN orders o ON o.id = oi.order_id
                                            WHERE oi.menu_item_id = mi.id
                                              AND o.location_id = p_location_id
                                              AND o.status = 'completed'
                                              AND o.completed_at > NOW() - INTERVAL '30 days'
                                              AND oi.is_voided = false
                                        )
                                    )
                                ),

                                -- Price source
                                'price_source', CASE
                                    WHEN lcio.custom_price IS NOT NULL THEN 'location_category'
                                    WHEN ci.custom_price IS NOT NULL THEN 'category'
                                    WHEN lio.custom_price IS NOT NULL THEN 'location_item'
                                    ELSE 'base'
                                END,

                                -- Override flags
                                'has_location_item_override', (lio.id IS NOT NULL),
                                'has_category_price', (ci.custom_price IS NOT NULL),
                                'has_location_category_override', (lcio.id IS NOT NULL)
                            )
                        ) ORDER BY COALESCE(lcio.display_order, ci.display_order)
                    ), '[]'::json)
                    FROM category_items ci
                    JOIN menu_items mi ON mi.id = ci.menu_item_id
                    LEFT JOIN location_item_overrides lio 
                        ON lio.menu_item_id = mi.id 
                        AND lio.location_id = p_location_id
                    LEFT JOIN location_category_item_overrides lcio 
                        ON lcio.menu_item_id = mi.id 
                        AND lcio.category_id = c.id
                        AND lcio.location_id = p_location_id
                    WHERE ci.category_id = c.id
                ),
                
                -- Item count
                'item_count', (
                    SELECT COUNT(*) FROM category_items ci WHERE ci.category_id = c.id
                ),

                -- Menu count (how many menus use this category)
                'menu_count', (
                    SELECT COUNT(*) FROM menu_categories mc WHERE mc.category_id = c.id
                ),
                
                -- Has location override
                'has_location_override', (lco.id IS NOT NULL),
                
                'created_at', c.created_at,
                'updated_at', c.updated_at
            ) ORDER BY 
                -- Sort: Global categories first, then location-specific
                CASE WHEN c.location_id IS NULL THEN 0 ELSE 1 END,
                COALESCE(lco.display_order, c.display_order) NULLS LAST,
                c.name
        ), '[]'::json)
        FROM categories c
        -- Only join location overrides if we have a location context
        LEFT JOIN location_category_overrides lco 
            ON lco.category_id = c.id 
            AND lco.location_id = p_location_id
            AND c.location_id IS NULL  -- Only global categories can have overrides
        WHERE c.merchant_id = p_merchant_id
          AND (
              -- If no location specified: return ALL categories (admin view)
              p_location_id IS NULL
              OR
              -- If location specified: return global + this location's categories
              (
                  c.location_id IS NULL  -- Global categories
                  OR 
                  c.location_id = p_location_id  -- This location's specific categories
              )
          )
    );
END;$$;


ALTER FUNCTION "public"."get_categories_for_location"("p_merchant_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_chargeback_volume_by_month"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("month" "text", "chargeback_count" bigint, "total_amount" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    TO_CHAR(DATE_TRUNC('month', cb.received_at)::DATE, 'YYYY-MM') as month,
    COUNT(*)::BIGINT as chargeback_count,
    SUM(cb.amount)::NUMERIC as total_amount
  FROM chargebacks cb
  WHERE cb.received_at >= p_from AND cb.received_at < p_to
  GROUP BY DATE_TRUNC('month', cb.received_at)
  ORDER BY month;
END;
$$;


ALTER FUNCTION "public"."get_chargeback_volume_by_month"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_churn_risk_merchants"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("merchant_id" "uuid", "merchant_name" "text", "last_period_revenue" numeric, "current_revenue" numeric, "change_pct" numeric)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_window_days INT;
  v_prev_start  TIMESTAMPTZ;
  v_prev_end    TIMESTAMPTZ;
BEGIN
  -- Calculate window size correctly
  v_window_days := EXTRACT(DAY FROM (p_to - p_from));
  v_prev_start  := p_from - (v_window_days || ' days')::INTERVAL;
  v_prev_end    := p_from;

  RETURN QUERY
  WITH current_rev AS (
    SELECT 
      o.merchant_id,
      COALESCE(SUM(o.total_amount), 0) AS revenue
    FROM orders o
    WHERE o.created_at >= p_from
      AND o.created_at < p_to
      AND o.status NOT IN ('draft', 'cancelled', 'void')
    GROUP BY o.merchant_id
  ),
  previous_rev AS (
    SELECT 
      o.merchant_id,
      COALESCE(SUM(o.total_amount), 0) AS revenue
    FROM orders o
    WHERE o.created_at >= v_prev_start
      AND o.created_at < v_prev_end
      AND o.status NOT IN ('draft', 'cancelled', 'void')
    GROUP BY o.merchant_id
  )

  SELECT
    cr.merchant_id,
    m.name::TEXT,
    pr.revenue::NUMERIC AS last_period_revenue,
    cr.revenue::NUMERIC AS current_revenue,
    CASE
      WHEN pr.revenue > 0
      THEN ((cr.revenue - pr.revenue) / pr.revenue * 100)::NUMERIC(5,2)
      ELSE 0::NUMERIC
    END AS change_pct

  FROM current_rev cr
  JOIN previous_rev pr
    ON cr.merchant_id = pr.merchant_id
  JOIN merchants m
    ON cr.merchant_id = m.id

  WHERE pr.revenue > 0
    AND ((cr.revenue - pr.revenue) / pr.revenue) < -0.5

  ORDER BY change_pct;

END;
$$;


ALTER FUNCTION "public"."get_churn_risk_merchants"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_course_status"("p_order_id" "uuid", "p_course_number" integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_result JSON;
BEGIN
  SELECT json_build_object(
    'course_number', oc.course_number,
    'status', oc.status,
    'is_locked', oc.status != 'open',
    'fired_at', oc.fired_at,
    'served_at', oc.served_at,
    'item_count', (
      SELECT COUNT(*) FROM public.order_items oi
      WHERE oi.order_id = p_order_id 
        AND oi.course_number = p_course_number
        AND oi.is_voided = FALSE
    )
  )
  INTO v_result
  FROM public.order_courses oc
  WHERE oc.order_id = p_order_id AND oc.course_number = p_course_number;

  -- If course doesn't exist yet, return open status
  IF v_result IS NULL THEN
    v_result := json_build_object(
      'course_number', p_course_number,
      'status', 'open',
      'is_locked', false,
      'fired_at', null,
      'served_at', null,
      'item_count', (
        SELECT COUNT(*) FROM public.order_items oi
        WHERE oi.order_id = p_order_id 
          AND oi.course_number = p_course_number
          AND oi.is_voided = FALSE
      )
    );
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_course_status"("p_order_id" "uuid", "p_course_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_activity_timeline"("p_customer_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("activity_id" "text", "activity_type" "text", "activity_label" "text", "description" "text", "amount_value" numeric, "currency" "text", "created_at" timestamp with time zone, "is_clickable" boolean, "related_entity_id" "uuid", "related_entity_type" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  -- Orders
  SELECT
    'order_' || o.id::text AS activity_id,
    'order'::text AS activity_type,
    'Order Completed'::text AS activity_label,
    'Order #' || o.order_number || ' — ' || item_counts.cnt || ' item' ||
      CASE WHEN item_counts.cnt > 1 THEN 's' ELSE '' END AS description,
    o.total_amount AS amount_value,
    'USD'::text AS currency,
    o.created_at,
    true::boolean AS is_clickable,
    o.id AS related_entity_id,
    'order'::text AS related_entity_type
  FROM orders o
  JOIN LATERAL (
    SELECT COUNT(*)::integer AS cnt
    FROM order_items oi
    WHERE oi.order_id = o.id AND oi.is_voided = false
  ) item_counts ON true
  WHERE o.customer_id = p_customer_id
    AND o.status NOT IN ('cancelled', 'void')

  UNION ALL

  -- Customer Activities (tags, notes, etc.)
  SELECT
    'activity_' || ca.id::text AS activity_id,
    ca.activity_type::text AS activity_type,
    CASE
      WHEN ca.activity_type = 'tag_added' THEN 'Tag Added'
      WHEN ca.activity_type = 'tag_removed' THEN 'Tag Removed'
      WHEN ca.activity_type = 'note_added' THEN 'Note Added'
      ELSE ca.activity_type::text
    END AS activity_label,
    CASE
      WHEN ca.activity_type = 'tag_added' THEN 'Tagged as ' || COALESCE((ca.metadata->>'tag'), 'unknown')
      WHEN ca.activity_type = 'tag_removed' THEN 'Removed tag: ' || COALESCE((ca.metadata->>'tag'), 'unknown')
      WHEN ca.activity_type = 'note_added' THEN 'Note: ' || COALESCE((ca.metadata->>'note'), '')
      ELSE COALESCE(ca.metadata::text, '')
    END AS description,
    NULL::numeric AS amount_value,
    NULL::text AS currency,
    ca.created_at,
    false::boolean AS is_clickable,
    NULL::uuid AS related_entity_id,
    NULL::text AS related_entity_type
  FROM customer_activities ca
  WHERE ca.customer_id = p_customer_id

  ORDER BY created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_customer_activity_timeline"("p_customer_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_channel_trend"("p_customer_id" "uuid", "p_days" integer DEFAULT 90) RETURNS TABLE("channel" "text", "count_recent" bigint, "count_previous" bigint, "percentage_recent" numeric, "percentage_previous" numeric, "trend_label" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  WITH recent_period AS (
      SELECT
          o.order_type::text AS channel,
          COUNT(*)::bigint AS count_recent
      FROM orders o
      WHERE o.customer_id = p_customer_id
        AND o.created_at >= NOW() - (p_days || ' days')::interval
        AND o.status NOT IN ('cancelled', 'void')
      GROUP BY o.order_type
  ),
  previous_period AS (
      SELECT
          o.order_type::text AS channel,
          COUNT(*)::bigint AS count_previous
      FROM orders o
      WHERE o.customer_id = p_customer_id
        AND o.created_at >= NOW() - ((p_days * 2) || ' days')::interval
        AND o.created_at < NOW() - (p_days || ' days')::interval
        AND o.status NOT IN ('cancelled', 'void')
      GROUP BY o.order_type
  ),
  totals AS (
      SELECT
          NULLIF((SELECT SUM(r.count_recent) FROM recent_period r), 0) AS total_recent,
          NULLIF((SELECT SUM(p.count_previous) FROM previous_period p), 0) AS total_previous
  )
  SELECT
      COALESCE(rp.channel, pp.channel) AS channel,
      COALESCE(rp.count_recent, 0) AS count_recent,
      COALESCE(pp.count_previous, 0) AS count_previous,
      ROUND(
          COALESCE(rp.count_recent, 0)::numeric
          / NULLIF(t.total_recent, 0) * 100,
          1
      ) AS percentage_recent,
      ROUND(
          COALESCE(pp.count_previous, 0)::numeric
          / NULLIF(t.total_previous, 0) * 100,
          1
      ) AS percentage_previous,
      CASE
          WHEN COALESCE(rp.count_recent, 0) > COALESCE(pp.count_previous, 0)
              THEN '↑ Increasing'
          WHEN COALESCE(rp.count_recent, 0) < COALESCE(pp.count_previous, 0)
              THEN '↓ Decreasing'
          ELSE '→ Stable'
      END AS trend_label
  FROM recent_period rp
  FULL OUTER JOIN previous_period pp
      ON rp.channel = pp.channel
  CROSS JOIN totals t
  ORDER BY COALESCE(rp.count_recent, 0) DESC;

END;
$$;


ALTER FUNCTION "public"."get_customer_channel_trend"("p_customer_id" "uuid", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_most_ordered_items"("p_customer_id" "uuid", "p_limit" integer DEFAULT 5) RETURNS TABLE("item_id" "uuid", "item_name" "text", "order_count" integer, "total_quantity" integer)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT 
    oi.menu_item_id as item_id,
    mi.name as item_name,
    COUNT(DISTINCT oi.order_id)::INTEGER as order_count,
    SUM(oi.quantity)::INTEGER as total_quantity
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  JOIN public.menu_items mi ON mi.id = oi.menu_item_id
  WHERE 
    o.customer_id = p_customer_id
    AND o.status IN ('ready', 'completed')
  GROUP BY oi.menu_item_id, mi.name
  ORDER BY total_quantity DESC
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."get_customer_most_ordered_items"("p_customer_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_order_channels"("p_customer_id" "uuid") RETURNS TABLE("channel" "text", "order_count" integer, "percentage" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  WITH channel_counts AS (
    SELECT 
      o.order_type::TEXT,
      COUNT(*) as count
    FROM public.orders o
    WHERE 
      o.customer_id = p_customer_id
      AND o.status IN ('ready', 'completed')
    GROUP BY o.order_type
  ),
  total_orders AS (
    SELECT SUM(count) as total FROM channel_counts
  )
  SELECT 
    cc.order_type,
    cc.count::INTEGER,
    ROUND((cc.count::NUMERIC / NULLIF(t.total, 0) * 100), 2) as percentage
  FROM channel_counts cc
  CROSS JOIN total_orders t
  ORDER BY cc.count DESC;
$$;


ALTER FUNCTION "public"."get_customer_order_channels"("p_customer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_percentile"("p_customer_id" "uuid", "p_merchant_id" "uuid") RETURNS TABLE("percentile" numeric, "rank_position" bigint, "total_customers" bigint, "is_top_tier" boolean)
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  WITH customer_rank AS (
    SELECT
      c.id,
      c.lifetime_spend,
      ROW_NUMBER() OVER (ORDER BY c.lifetime_spend DESC) AS rank,
      COUNT(*) OVER () AS total
    FROM customers c
    WHERE c.merchant_id = p_merchant_id
  )
  SELECT
    ROUND(((total - rank + 1)::numeric / NULLIF(total, 0) * 100), 1) AS percentile,
    rank::bigint AS rank_position,
    total::bigint AS total_customers,
    (rank <= CEIL(total::numeric * 0.2)::bigint)::boolean AS is_top_tier
  FROM customer_rank
  WHERE id = p_customer_id;
END;
$$;


ALTER FUNCTION "public"."get_customer_percentile"("p_customer_id" "uuid", "p_merchant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_profile"("p_customer_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_result JSON;
BEGIN
  SELECT json_build_object(
    'customer', (
      SELECT row_to_json(c) 
      FROM public.customers c 
      WHERE c.id = p_customer_id
    ),
    'order_channels', (
      SELECT json_agg(row_to_json(ch))
      FROM get_customer_order_channels(p_customer_id) ch
    ),
    'most_ordered_items', (
      SELECT json_agg(row_to_json(items))
      FROM get_customer_most_ordered_items(p_customer_id, 5) items
    ),
    'recent_activity', (
      SELECT json_agg(row_to_json(act))
      FROM (
        SELECT * FROM public.customer_activities
        WHERE customer_id = p_customer_id
        ORDER BY created_at DESC
        LIMIT 10
      ) act
    )
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


