CREATE OR REPLACE FUNCTION "public"."get_customer_spend_trend"("p_customer_id" "uuid", "p_months" integer DEFAULT 6) RETURNS TABLE("month" "text", "month_date" "date", "total_spend" numeric, "order_count" bigint)
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    to_char(DATE_TRUNC('month', o.created_at), 'Mon') AS month,
    DATE_TRUNC('month', o.created_at)::date AS month_date,
    COALESCE(SUM(o.total_amount), 0::numeric) AS total_spend,
    COUNT(*)::bigint AS order_count
  FROM orders o
  WHERE o.customer_id = p_customer_id
    AND o.created_at >= NOW() - (p_months || ' months')::interval
    AND o.status NOT IN ('cancelled', 'void')
  GROUP BY DATE_TRUNC('month', o.created_at)
  ORDER BY month_date ASC;
END;
$$;


ALTER FUNCTION "public"."get_customer_spend_trend"("p_customer_id" "uuid", "p_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_top_items"("p_customer_id" "uuid", "p_days" integer DEFAULT 90, "p_limit" integer DEFAULT 10) RETURNS TABLE("item_id" "uuid", "item_name" "text", "order_count" bigint, "total_spent" numeric, "last_ordered_at" timestamp with time zone, "is_new_favorite" boolean, "frequency_label" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  WITH item_orders AS (
    SELECT
      COALESCE(oi.menu_item_id, '00000000-0000-0000-0000-000000000000'::uuid) AS item_id,
      oi.item_name,
      COUNT(*)::bigint AS order_count,
      COALESCE(SUM(oi.unit_price * oi.quantity), 0::numeric) AS total_spent,
      MAX(o.created_at) AS last_ordered_at,
      -- Check if first ordered in last 30 days (new favorite)
      (MIN(o.created_at) >= NOW() - '30 days'::interval)::boolean AS is_new_favorite
    FROM order_items oi
    JOIN orders o ON oi.order_id = o.id
    WHERE o.customer_id = p_customer_id
      AND o.created_at >= NOW() - (p_days || ' days')::interval
      AND o.status NOT IN ('cancelled', 'void')
      AND oi.is_voided = false
    GROUP BY oi.menu_item_id, oi.item_name
  ),
  total_orders AS (
    SELECT COUNT(DISTINCT o.id)::bigint AS order_count
    FROM orders o
    WHERE o.customer_id = p_customer_id
      AND o.created_at >= NOW() - (p_days || ' days')::interval
      AND o.status NOT IN ('cancelled', 'void')
  )
  SELECT
    io.item_id,
    io.item_name,
    io.order_count,
    io.total_spent,
    io.last_ordered_at,
    io.is_new_favorite,
    CASE
      WHEN io.order_count >= tot.order_count THEN 'Every visit'
      WHEN io.order_count >= (tot.order_count * 0.5) THEN 'Regularly'
      WHEN io.order_count >= (tot.order_count * 0.25) THEN 'Often'
      ELSE 'Occasionally'
    END AS frequency_label
  FROM item_orders io
  CROSS JOIN total_orders tot
  ORDER BY io.order_count DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_customer_top_items"("p_customer_id" "uuid", "p_days" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_visit_pattern"("p_customer_id" "uuid", "p_days" integer DEFAULT 90) RETURNS TABLE("day_of_week" "text", "hour_of_day" integer, "visit_count" bigint, "is_peak" boolean)
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  WITH visit_stats AS (
    SELECT
      TO_CHAR(o.created_at, 'Day') AS day_of_week,
      EXTRACT(HOUR FROM o.created_at)::integer AS hour_of_day,
      COUNT(*)::bigint AS visit_count,
      ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) AS rank
    FROM orders o
    WHERE o.customer_id = p_customer_id
      AND o.created_at >= NOW() - (p_days || ' days')::interval
      AND o.status NOT IN ('cancelled', 'void')
    GROUP BY TO_CHAR(o.created_at, 'Day'), EXTRACT(HOUR FROM o.created_at)
  )
  SELECT
    TRIM(visit_stats.day_of_week) AS day_of_week,
    visit_stats.hour_of_day,
    visit_stats.visit_count,
    (visit_stats.rank <= 3)::boolean AS is_peak
  FROM visit_stats
  ORDER BY visit_stats.visit_count DESC;
END;
$$;


ALTER FUNCTION "public"."get_customer_visit_pattern"("p_customer_id" "uuid", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_visit_trend"("p_customer_id" "uuid", "p_recent_days" integer DEFAULT 90, "p_compare_days" integer DEFAULT 90) RETURNS TABLE("recent_visits" bigint, "previous_visits" bigint, "trend_direction" "text", "trend_percentage" numeric)
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  WITH recent AS (
    SELECT COUNT(DISTINCT DATE(o.created_at))::bigint AS visit_days
    FROM orders o
    WHERE o.customer_id = p_customer_id
      AND o.created_at >= NOW() - (p_recent_days || ' days')::interval
      AND o.status NOT IN ('cancelled', 'void')
  ),
  previous AS (
    SELECT COUNT(DISTINCT DATE(o.created_at))::bigint AS visit_days
    FROM orders o
    WHERE o.customer_id = p_customer_id
      AND o.created_at >= NOW() - ((p_recent_days + p_compare_days) || ' days')::interval
      AND o.created_at < NOW() - (p_recent_days || ' days')::interval
      AND o.status NOT IN ('cancelled', 'void')
  )
  SELECT
    r.visit_days AS recent_visits,
    p.visit_days AS previous_visits,
    CASE
      WHEN r.visit_days > p.visit_days THEN '↑'
      WHEN r.visit_days < p.visit_days THEN '↓'
      ELSE '→'
    END AS trend_direction,
    CASE
      WHEN p.visit_days = 0 THEN NULL
      ELSE ROUND(((r.visit_days - p.visit_days)::numeric / p.visit_days * 100), 1)
    END AS trend_percentage
  FROM recent r, previous p;
END;
$$;


ALTER FUNCTION "public"."get_customer_visit_trend"("p_customer_id" "uuid", "p_recent_days" integer, "p_compare_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_device_active_session"("p_device_id" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_session RECORD;
BEGIN
  SELECT 
    ss.*,
    s.station_name,
    s.station_type,
    s.station_number
  INTO v_session
  FROM station_sessions ss
  JOIN stations s ON s.id = ss.station_id
  WHERE ss.device_id = p_device_id
    AND ss.session_status = 'active';
  
  IF NOT FOUND THEN
    RETURN json_build_object('has_session', false);
  END IF;
  
  RETURN json_build_object(
    'has_session', true,
    'session_id', v_session.id,
    'station_id', v_session.station_id,
    'station_name', v_session.station_name,
    'station_type', v_session.station_type,
    'staff_profile_id', v_session.staff_profile_id,
    'staff_name', v_session.staff_name,
    'started_at', v_session.started_at
  );
END;
$$;


ALTER FUNCTION "public"."get_device_active_session"("p_device_id" "text") OWNER TO "postgres";


