CREATE OR REPLACE FUNCTION "public"."get_discrepancy_report"("p_purchase_order_id" "uuid") RETURNS TABLE("item_id" "uuid", "inventory_item_id" "uuid", "item_name" "text", "item_sku" "text", "item_unit_type" "text", "quantity_ordered" numeric, "quantity_received" numeric, "unit_cost" numeric, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    poi.id as item_id,
    poi.inventory_item_id,
    poi.item_name::TEXT,
    poi.item_sku::TEXT,
    poi.item_unit_type::TEXT,
    poi.quantity_ordered,
    COALESCE(poi.quantity_received, 0) as quantity_received,
    poi.unit_cost,
    CASE 
      WHEN COALESCE(poi.quantity_received, 0) = 0 THEN 'missing'
      WHEN COALESCE(poi.quantity_received, 0) < poi.quantity_ordered THEN 'shorted'
      ELSE 'received'
    END as status
  FROM public.purchase_order_items poi
  WHERE poi.purchase_order_id = p_purchase_order_id
  ORDER BY poi.created_at;
END;
$$;


ALTER FUNCTION "public"."get_discrepancy_report"("p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dual_pricing_adoption"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("adopted_merchants" bigint, "total_merchants" bigint, "adoption_pct" numeric)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_total_merchants BIGINT;
  v_adopted BIGINT;
BEGIN
  SELECT COUNT(DISTINCT id)::BIGINT INTO v_total_merchants FROM merchants;

  SELECT COUNT(DISTINCT merchant_id)::BIGINT INTO v_adopted
  FROM orders
  WHERE created_at >= p_from AND created_at < p_to
    AND cash_discount_applied = true;

  RETURN QUERY
  SELECT
    COALESCE(v_adopted, 0)::BIGINT,
    v_total_merchants,
    CASE
      WHEN v_total_merchants > 0
      THEN (COALESCE(v_adopted, 0)::NUMERIC / v_total_merchants * 100)::NUMERIC(5,2)
      ELSE 0::NUMERIC
    END;
END;
$$;


ALTER FUNCTION "public"."get_dual_pricing_adoption"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_item_cost"("p_location_id" "uuid", "p_inventory_item_id" "uuid", "p_vendor_id" "uuid" DEFAULT NULL::"uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    v_cost NUMERIC;
BEGIN
    -- Priority 1: Direct location override (no vendor required)
    SELECT custom_cost INTO v_cost
    FROM public.location_inventory_overrides
    WHERE location_id = p_location_id
      AND inventory_item_id = p_inventory_item_id
      AND custom_cost IS NOT NULL;
    
    IF v_cost IS NOT NULL THEN
        RETURN v_cost;
    END IF;

    -- Priority 2: Location-specific vendor pricing
    IF p_vendor_id IS NOT NULL THEN
        SELECT unit_cost INTO v_cost
        FROM public.location_vendor_pricing
        WHERE location_id = p_location_id
          AND vendor_id = p_vendor_id
          AND inventory_item_id = p_inventory_item_id;
        
        IF v_cost IS NOT NULL THEN
            RETURN v_cost;
        END IF;
    END IF;
    
    -- Priority 3: Preferred vendor's default cost
    SELECT vi.default_cost INTO v_cost
    FROM public.vendor_items vi
    WHERE vi.inventory_item_id = p_inventory_item_id
      AND vi.is_preferred = true
    LIMIT 1;
    
    IF v_cost IS NOT NULL AND v_cost > 0 THEN
        RETURN v_cost;
    END IF;
    
    -- Priority 4: Item's base cost_per_unit
    SELECT cost_per_unit INTO v_cost
    FROM public.inventory_items
    WHERE id = p_inventory_item_id;
    
    RETURN COALESCE(v_cost, 0);
END;
$$;


ALTER FUNCTION "public"."get_effective_item_cost"("p_location_id" "uuid", "p_inventory_item_id" "uuid", "p_vendor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_pricing"("p_location_id" "uuid") RETURNS TABLE("pricing_strategy" "text", "dual_pricing_percentage" numeric, "source" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_location RECORD;
  v_merchant RECORD;
BEGIN
  -- Get location
  SELECT l.merchant_id, l.use_merchant_pricing_defaults,
         l.pricing_strategy AS loc_strategy, l.dual_pricing_percentage AS loc_percentage
  INTO v_location
  FROM locations l
  WHERE l.id = p_location_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- If location uses merchant defaults, return merchant values
  IF v_location.use_merchant_pricing_defaults THEN
    SELECT m.pricing_strategy, m.dual_pricing_percentage
    INTO v_merchant
    FROM merchants m
    WHERE m.id = v_location.merchant_id;

    pricing_strategy := v_merchant.pricing_strategy;
    dual_pricing_percentage := v_merchant.dual_pricing_percentage;
    source := 'merchant';
    RETURN NEXT;
  ELSE
    pricing_strategy := v_location.loc_strategy;
    dual_pricing_percentage := v_location.loc_percentage;
    source := 'location';
    RETURN NEXT;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_effective_pricing"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_reorder_threshold"("p_location_id" "uuid", "p_inventory_item_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    v_threshold NUMERIC;
BEGIN
    -- Priority 1: Location stock table override
    SELECT reorder_threshold INTO v_threshold
    FROM public.location_inventory_stock
    WHERE location_id = p_location_id
      AND inventory_item_id = p_inventory_item_id
      AND reorder_threshold IS NOT NULL;
    
    IF v_threshold IS NOT NULL THEN
        RETURN v_threshold;
    END IF;
    
    -- Priority 2: Location inventory overrides table
    SELECT custom_reorder_threshold INTO v_threshold
    FROM public.location_inventory_overrides
    WHERE location_id = p_location_id
      AND inventory_item_id = p_inventory_item_id
      AND custom_reorder_threshold IS NOT NULL;
    
    IF v_threshold IS NOT NULL THEN
        RETURN v_threshold;
    END IF;
    
    -- Priority 3: Global default from inventory_items
    -- FIX: Use reorder_point column (not reorder_threshold)
    SELECT reorder_point INTO v_threshold
    FROM public.inventory_items
    WHERE id = p_inventory_item_id;
    
    RETURN COALESCE(v_threshold, 0);
END;
$$;


ALTER FUNCTION "public"."get_effective_reorder_threshold"("p_location_id" "uuid", "p_inventory_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_eligible_promotions"("p_customer_id" "uuid", "p_merchant_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_order_total" numeric DEFAULT NULL::numeric, "p_order_items" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    v_promo RECORD;
    v_result JSONB := '[]'::JSONB;
    v_customer RECORD;
    v_visit_count INTEGER;
    v_last_visit DATE;
    v_today DATE := CURRENT_DATE;
    v_now_time TIME := LOCALTIME;
    v_qualifying BOOLEAN;
    v_discount_amount NUMERIC;
    v_bogo_qty INTEGER;
    v_bundle_match BOOLEAN;
BEGIN
    -- Fetch customer info if available
    IF p_customer_id IS NOT NULL THEN
        SELECT * INTO v_customer FROM customers WHERE id = p_customer_id;
        SELECT COUNT(*) INTO v_visit_count FROM orders WHERE customer_id = p_customer_id AND status = 'completed';
        SELECT MAX(created_at)::DATE INTO v_last_visit FROM orders WHERE customer_id = p_customer_id AND status = 'completed';
    END IF;

    FOR v_promo IN
        SELECT *
        FROM promotions
        WHERE merchant_id = p_merchant_id
          AND is_active = true
          AND (starts_at IS NULL OR starts_at <= now())
          AND (ends_at IS NULL OR ends_at >= now())
          AND (location_ids IS NULL OR p_location_id IS NULL OR p_location_id = ANY(location_ids))
    LOOP
        -- Time-of-day filter
        IF v_promo.active_days IS NOT NULL AND NOT (EXTRACT(DOW FROM now())::INTEGER = ANY(v_promo.active_days)) THEN
            CONTINUE;
        END IF;
        IF v_promo.active_time_start IS NOT NULL AND v_promo.active_time_end IS NOT NULL THEN
            IF NOT (v_now_time BETWEEN v_promo.active_time_start AND v_promo.active_time_end) THEN
                CONTINUE;
            END IF;
        END IF;

        v_qualifying := true;

        -- Type-specific qualification
        CASE v_promo.promo_type
            WHEN 'happy_hour' THEN
                -- Already handled by time filters above
                NULL;

            WHEN 'birthday' THEN
                IF v_customer IS NULL OR v_customer.birthday IS NULL THEN
                    v_qualifying := false;
                ELSE
                    -- Respect birthday_window: day, week, or month
                    CASE COALESCE(v_promo.birthday_window, 'week')
                        WHEN 'day' THEN
                            IF EXTRACT(MONTH FROM v_customer.birthday) != EXTRACT(MONTH FROM v_today)
                               OR EXTRACT(DAY FROM v_customer.birthday) != EXTRACT(DAY FROM v_today) THEN
                                v_qualifying := false;
                            END IF;
                        WHEN 'week' THEN
                            -- Check if birthday falls within 7 days (before or after today)
                            IF ABS(
                                EXTRACT(DOY FROM MAKE_DATE(EXTRACT(YEAR FROM v_today)::INT, EXTRACT(MONTH FROM v_customer.birthday)::INT, EXTRACT(DAY FROM v_customer.birthday)::INT))
                                - EXTRACT(DOY FROM v_today)
                            ) > 3 THEN
                                v_qualifying := false;
                            END IF;
                        WHEN 'month' THEN
                            IF EXTRACT(MONTH FROM v_customer.birthday) != EXTRACT(MONTH FROM v_today) THEN
                                v_qualifying := false;
                            END IF;
                        ELSE
                            v_qualifying := false;
                    END CASE;
                END IF;

            WHEN 'first_visit' THEN
                -- Qualifies if customer is anonymous OR has 0 completed orders
                IF p_customer_id IS NOT NULL AND v_visit_count > 0 THEN
                    v_qualifying := false;
                END IF;

            WHEN 'comeback' THEN
                IF v_last_visit IS NULL OR v_last_visit > v_today - COALESCE(v_promo.comeback_days, 30) THEN
                    v_qualifying := false;
                END IF;

            WHEN 'threshold' THEN
                IF p_order_total IS NULL OR p_order_total < COALESCE(v_promo.threshold_amount, 0) THEN
                    v_qualifying := false;
                END IF;

            WHEN 'bogo' THEN
                -- Check if order contains at least bogo_buy_quantity of qualifying items
                IF p_order_items IS NULL THEN
                    v_qualifying := false;
                ELSE
                    SELECT COALESCE(SUM((item->>'quantity')::INTEGER), 0) INTO v_bogo_qty
                    FROM jsonb_array_elements(p_order_items) AS item
                    WHERE (v_promo.target_item_ids IS NULL OR (item->>'menu_item_id')::UUID = ANY(v_promo.target_item_ids))
                      AND (v_promo.target_categories IS NULL OR (item->>'category_id')::UUID = ANY(v_promo.target_categories));

                    IF v_bogo_qty < COALESCE(v_promo.bogo_buy_quantity, 1) THEN
                        v_qualifying := false;
                    END IF;
                END IF;

            WHEN 'bundle' THEN
                -- Check all target items/categories present in order
                IF p_order_items IS NULL THEN
                    v_qualifying := false;
                ELSE
                    -- All target_item_ids must appear in the order
                    IF v_promo.target_item_ids IS NOT NULL THEN
                        SELECT bool_and(EXISTS(
                            SELECT 1 FROM jsonb_array_elements(p_order_items) AS item
                            WHERE (item->>'menu_item_id')::UUID = tid
                        )) INTO v_bundle_match
                        FROM unnest(v_promo.target_item_ids) AS tid;

                        IF NOT COALESCE(v_bundle_match, false) THEN
                            v_qualifying := false;
                        END IF;
                    END IF;
                END IF;

            WHEN 'seasonal' THEN
                -- Already handled by date range filters above
                NULL;

            WHEN 'referral' THEN
                IF v_customer IS NULL OR v_customer.referred_by_customer_id IS NULL THEN
                    v_qualifying := false;
                ELSE
                    -- Check if referral promo already used by this customer
                    PERFORM 1 FROM promotion_usage WHERE promotion_id = v_promo.id AND customer_id = p_customer_id;
                    IF FOUND THEN
                        v_qualifying := false;
                    END IF;
                END IF;

            ELSE
                -- Unknown promo type, skip
                v_qualifying := false;
        END CASE;

        -- Check per-customer usage limits
        IF v_qualifying AND p_customer_id IS NOT NULL AND v_promo.max_uses_per_customer IS NOT NULL THEN
            PERFORM 1 FROM promotion_usage
            WHERE promotion_id = v_promo.id AND customer_id = p_customer_id
            HAVING COUNT(*) >= v_promo.max_uses_per_customer;
            IF FOUND THEN
                v_qualifying := false;
            END IF;
        END IF;

        -- Check total usage limits
        IF v_qualifying AND v_promo.max_uses_total IS NOT NULL THEN
            IF v_promo.current_uses >= v_promo.max_uses_total THEN
                v_qualifying := false;
            END IF;
        END IF;

        IF v_qualifying THEN
            -- Calculate discount amount if order total is known
            IF p_order_total IS NOT NULL THEN
                IF v_promo.discount_type = 'percentage' THEN
                    v_discount_amount := LEAST(
                        p_order_total * v_promo.discount_value / 100,
                        COALESCE(v_promo.discount_max, p_order_total)
                    );
                ELSIF v_promo.discount_type = 'fixed_amount' THEN
                    v_discount_amount := v_promo.discount_value;
                ELSE
                    v_discount_amount := v_promo.discount_value;
                END IF;
            ELSE
                v_discount_amount := NULL;
            END IF;

            v_result := v_result || jsonb_build_object(
                'promo_id', v_promo.id,
                'name', v_promo.name,
                'promo_type', v_promo.promo_type,
                'discount_type', v_promo.discount_type,
                'discount_value', v_promo.discount_value,
                'discount_max', v_promo.discount_max,
                'discount_amount', v_discount_amount,
                'auto_apply', COALESCE(v_promo.auto_apply, false)
            );
        END IF;
    END LOOP;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_eligible_promotions"("p_customer_id" "uuid", "p_merchant_id" "uuid", "p_location_id" "uuid", "p_order_total" numeric, "p_order_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_eod_cash_summary"("p_location_id" "uuid", "p_business_date" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_drawers JSONB := '[]'::JSONB;
  v_grand_totals JSONB;
  v_drawer RECORD;
  v_ops RECORD;
  v_no_sale_audit JSONB;
BEGIN
  -- Per-drawer breakdown
  FOR v_drawer IN
    SELECT
      s.id AS session_id,
      d.id AS drawer_id,
      d.name AS drawer_name,
      s.opened_by,
      s.closed_by,
      s.opened_at,
      s.closed_at,
      s.opening_amount,
      s.closing_amount,
      s.expected_cash,
      s.variance,
      s.status
    FROM cash_drawer_sessions s
    JOIN cash_drawers d ON d.id = s.cash_drawer_id
    WHERE s.location_id = p_location_id
      AND s.business_date = p_business_date
    ORDER BY s.opened_at
  LOOP
    -- Get operation breakdown for this session
    SELECT
      COALESCE(SUM(CASE WHEN operation_type = 'cash_sale' THEN amount ELSE 0 END), 0) AS cash_sales,
      COALESCE(SUM(CASE WHEN operation_type = 'cash_refund' THEN amount ELSE 0 END), 0) AS cash_refunds,
      COALESCE(SUM(CASE WHEN operation_type = 'pay_in' THEN amount ELSE 0 END), 0) AS pay_ins,
      COALESCE(SUM(CASE WHEN operation_type = 'pay_out' THEN amount ELSE 0 END), 0) AS pay_outs,
      COALESCE(SUM(CASE WHEN operation_type = 'cash_drop' THEN amount ELSE 0 END), 0) AS cash_drops,
      COALESCE(SUM(CASE WHEN operation_type = 'tip_out' THEN amount ELSE 0 END), 0) AS tip_outs,
      COUNT(CASE WHEN operation_type = 'no_sale' THEN 1 END) AS no_sale_count
    INTO v_ops
    FROM cash_drawer_operations
    WHERE session_id = v_drawer.session_id;

    v_drawers := v_drawers || jsonb_build_object(
      'session_id', v_drawer.session_id,
      'drawer_id', v_drawer.drawer_id,
      'drawer_name', v_drawer.drawer_name,
      'opened_at', v_drawer.opened_at,
      'closed_at', v_drawer.closed_at,
      'opening_amount', v_drawer.opening_amount,
      'closing_amount', v_drawer.closing_amount,
      'expected_cash', v_drawer.expected_cash,
      'variance', v_drawer.variance,
      'status', v_drawer.status,
      'cash_sales', v_ops.cash_sales,
      'cash_refunds', v_ops.cash_refunds,
      'pay_ins', v_ops.pay_ins,
      'pay_outs', v_ops.pay_outs,
      'cash_drops', v_ops.cash_drops,
      'tip_outs', v_ops.tip_outs,
      'no_sale_count', v_ops.no_sale_count
    );
  END LOOP;

  -- Grand totals across all drawers
  SELECT jsonb_build_object(
    'total_opening', COALESCE(SUM(s.opening_amount), 0),
    'total_closing', COALESCE(SUM(s.closing_amount), 0),
    'total_expected', COALESCE(SUM(s.expected_cash), 0),
    'total_variance', COALESCE(SUM(s.variance), 0),
    'sessions_count', COUNT(*),
    'sessions_still_open', COUNT(CASE WHEN s.status = 'open' THEN 1 END)
  )
  INTO v_grand_totals
  FROM cash_drawer_sessions s
  WHERE s.location_id = p_location_id
    AND s.business_date = p_business_date;

  -- No Sale audit by employee
  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::JSONB)
  INTO v_no_sale_audit
  FROM (
    SELECT
      o.performed_by,
      COUNT(*) AS no_sale_count
    FROM cash_drawer_operations o
    JOIN cash_drawer_sessions s ON s.id = o.session_id
    WHERE s.location_id = p_location_id
      AND s.business_date = p_business_date
      AND o.operation_type = 'no_sale'
    GROUP BY o.performed_by
    ORDER BY no_sale_count DESC
  ) t;

  RETURN jsonb_build_object(
    'drawers', v_drawers,
    'grand_totals', v_grand_totals,
    'no_sale_audit', v_no_sale_audit,
    'business_date', p_business_date
  );
END;
$$;


ALTER FUNCTION "public"."get_eod_cash_summary"("p_location_id" "uuid", "p_business_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_feature_adoption_rates"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("feature" "text", "adopted_count" bigint, "total_merchants" bigint, "adoption_pct" numeric)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_total_merchants BIGINT;
BEGIN
  SELECT COUNT(DISTINCT id)::BIGINT INTO v_total_merchants FROM merchants;

  RETURN QUERY
  SELECT
    'kds'::TEXT as feature,
    COUNT(DISTINCT kd.merchant_id)::BIGINT,
    v_total_merchants,
    (COUNT(DISTINCT kd.merchant_id)::NUMERIC / NULLIF(v_total_merchants, 0) * 100)::NUMERIC(5,2)
  FROM kds_displays kd
  WHERE kd.is_active = true
    AND kd.created_at >= p_from AND kd.created_at < p_to

  UNION ALL

  SELECT
    'table_management'::TEXT,
    COUNT(DISTINCT ts.merchant_id)::BIGINT,
    v_total_merchants,
    (COUNT(DISTINCT ts.merchant_id)::NUMERIC / NULLIF(v_total_merchants, 0) * 100)::NUMERIC(5,2)
  FROM table_sessions ts
  WHERE ts.seated_at >= p_from AND ts.seated_at < p_to

  UNION ALL

  SELECT
    'online_ordering'::TEXT,
    COUNT(DISTINCT o.merchant_id)::BIGINT,
    v_total_merchants,
    (COUNT(DISTINCT o.merchant_id)::NUMERIC / NULLIF(v_total_merchants, 0) * 100)::NUMERIC(5,2)
  FROM orders o
  WHERE o.created_at >= p_from AND o.created_at < p_to
    AND o.order_type = 'online';
END;
$$;


ALTER FUNCTION "public"."get_feature_adoption_rates"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_financial_kpis"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_summary JSON;
    v_payment_methods JSON;
    v_daily_stats JSON;
    v_best_sellers JSON;
    v_order_types JSON;
BEGIN
    -- 1. Summary Metrics
    SELECT json_build_object(
        'gross_sales', COALESCE(SUM(subtotal), 0),
        'net_sales', COALESCE(SUM(subtotal - discount_amount), 0),
        'discounts_total', COALESCE(SUM(discount_amount), 0),
        'refunds_total', (
            SELECT COALESCE(SUM(refunded_amount), 0)
            FROM order_payments op
            JOIN orders o2 ON o2.id = op.order_id
            WHERE o2.merchant_id = p_merchant_id
              AND (p_location_id IS NULL OR o2.location_id = p_location_id)
              AND op.status IN ('captured', 'authorized', 'refunded', 'partially_refunded')
              AND op.initiated_at BETWEEN p_start_date AND p_end_date
        ),
        'tax_total', COALESCE(SUM(tax_amount), 0),
        'tip_total', COALESCE(SUM(tip_amount), 0),
        'order_count', COUNT(*),
        'avg_order_value', CASE WHEN COUNT(*) > 0 THEN SUM(total_amount) / COUNT(*) ELSE 0 END,
        'paid_in_total', COALESCE(SUM(amount_paid), 0)
    ) INTO v_summary
    FROM orders
    WHERE merchant_id = p_merchant_id
      AND (p_location_id IS NULL OR location_id = p_location_id)
      AND status NOT IN ('draft', 'cancelled', 'void')
      AND created_at BETWEEN p_start_date AND p_end_date;

    -- 2. Payment Methods Breakdown
    SELECT COALESCE(json_agg(pm), '[]'::json) INTO v_payment_methods
    FROM (
        SELECT 
            payment_method as method,
            SUM(amount) as amount,
            COUNT(*) as count
        FROM order_payments op
        JOIN orders o ON o.id = op.order_id
        WHERE o.merchant_id = p_merchant_id
          AND (p_location_id IS NULL OR o.location_id = p_location_id)
          AND op.status IN ('captured', 'authorized')
          AND op.initiated_at BETWEEN p_start_date AND p_end_date
        GROUP BY payment_method
    ) pm;

    -- 3. Daily Stats for Charts
    SELECT COALESCE(json_agg(ds), '[]'::json) INTO v_daily_stats
    FROM (
        SELECT 
            date_trunc('day', created_at AT TIME ZONE 'UTC') as date,
            SUM(subtotal - discount_amount) as net_sales,
            COUNT(*) as order_count,
            COUNT(*) as guest_count
        FROM orders
        WHERE merchant_id = p_merchant_id
          AND (p_location_id IS NULL OR location_id = p_location_id)
          AND status NOT IN ('draft', 'cancelled', 'void')
          AND created_at BETWEEN p_start_date AND p_end_date
        GROUP BY 1
        ORDER BY 1 ASC
    ) ds;

    -- 4. Best Selling Items
    SELECT COALESCE(json_agg(bs), '[]'::json) INTO v_best_sellers
    FROM (
        SELECT 
            oi.item_name,
            SUM(oi.quantity) as quantity,
            SUM(oi.subtotal) as revenue
        FROM order_items oi
        JOIN orders o ON o.id = oi.order_id
        WHERE o.merchant_id = p_merchant_id
          AND (p_location_id IS NULL OR o.location_id = p_location_id)
          AND o.status NOT IN ('draft', 'cancelled', 'void')
          AND oi.is_voided = false
          AND o.created_at BETWEEN p_start_date AND p_end_date
        GROUP BY oi.item_name
        ORDER BY revenue DESC
        LIMIT 10
    ) bs;

    -- 5. Order Type Breakdown (ADDED)
    SELECT COALESCE(json_agg(ot), '[]'::json) INTO v_order_types
    FROM (
        SELECT 
            order_type as type,
            COUNT(*) as count,
            SUM(total_amount) as revenue
        FROM orders
        WHERE merchant_id = p_merchant_id
          AND (p_location_id IS NULL OR location_id = p_location_id)
          AND status NOT IN ('draft', 'cancelled', 'void')
          AND created_at BETWEEN p_start_date AND p_end_date
        GROUP BY order_type
    ) ot;

    RETURN json_build_object(
        'summary', v_summary,
        'payment_methods', v_payment_methods,
        'daily_stats', v_daily_stats,
        'best_sellers', v_best_sellers,
        'order_types', v_order_types
    );
END;
$$;


ALTER FUNCTION "public"."get_financial_kpis"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_floor_plan"("p_floor_plan_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_result JSON;
BEGIN
  SELECT json_build_object(
    'floor_plan', json_build_object(
      'id', fp.id,
      'name', fp.name,
      'description', fp.description,
      'canvas_width', fp.canvas_width,
      'canvas_height', fp.canvas_height,
      'grid_size', fp.grid_size,
      'background_color', fp.background_color,
      'is_active', fp.is_active,
      'is_default', fp.is_default
    ),
    'objects', (
      SELECT COALESCE(json_agg(
        json_build_object(
          'id', fpo.id,
          'name', fpo.name,
          'shape_id', fpo.shape_id,
          'category', fpo.category,
          'x', fpo.x,
          'y', fpo.y,
          'rotation', fpo.rotation,
          'width', fpo.width,
          'height', fpo.height,
          'capacity', fpo.capacity,
          'min_capacity', fpo.min_capacity,
          'is_reservable', fpo.is_reservable,
          'is_combinable', fpo.is_combinable,
          'default_turn_time', fpo.default_turn_time,
          'section_id', fpo.section_id,
          'zone_name', fpo.zone_name,
          'label_override', fpo.label_override,
          'color_override', fpo.color_override,
          'z_index', fpo.z_index,
          'is_visible', fpo.is_visible,
          'is_active', fpo.is_active
        ) ORDER BY fpo.z_index, fpo.created_at
      ), '[]'::json)
      FROM public.floor_plan_objects fpo
      WHERE fpo.floor_plan_id = fp.id
    ),
    'sections', (
      SELECT COALESCE(json_agg(
        json_build_object(
          'id', ss.id,
          'name', ss.name,
          'color', ss.color,
          'assigned_staff_id', ss.assigned_staff_id,
          'is_active', ss.is_active
        )
      ), '[]'::json)
      FROM public.server_sections ss
      WHERE ss.floor_plan_id = fp.id AND ss.is_active = TRUE
    )
  )
  INTO v_result
  FROM public.floor_plans fp
  WHERE fp.id = p_floor_plan_id
    AND fp.merchant_id = user_merchant_id()
    AND fp.location_id = ANY(user_location_ids());

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Floor plan not found or access denied';
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_floor_plan"("p_floor_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_floor_plan_objects_with_sessions"("p_floor_plan_id" "uuid") RETURNS TABLE("id" "uuid", "floor_plan_id" "uuid", "location_id" "uuid", "merchant_id" "uuid", "name" "text", "shape_id" "text", "category" "text", "x" numeric, "y" numeric, "rotation" numeric, "z_index" integer, "width" numeric, "height" numeric, "capacity" integer, "min_capacity" integer, "is_reservable" boolean, "is_combinable" boolean, "is_visible" boolean, "is_active" boolean, "section_id" "uuid", "zone_name" "text", "default_turn_time" integer, "label_override" "text", "color_override" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "session_id" "uuid", "session_status" "text", "session_number" "text", "party_size" integer, "guest_name" "text", "order_id" "uuid", "server_staff_id" "uuid", "is_vip" boolean, "needs_attention" boolean, "current_course" integer, "seated_at" timestamp with time zone, "reservation_id" "uuid", "waitlist_id" "uuid", "merged_tables" "uuid"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    fpo.id,
    fpo.floor_plan_id,
    fpo.location_id,
    fpo.merchant_id,
    fpo.name,
    fpo.shape_id,
    fpo.category::TEXT,
    fpo.x,
    fpo.y,
    fpo.rotation,
    fpo.z_index,
    fpo.width,
    fpo.height,
    fpo.capacity,
    fpo.min_capacity,
    fpo.is_reservable,
    fpo.is_combinable,
    fpo.is_visible,
    fpo.is_active,
    fpo.section_id,
    fpo.zone_name,
    fpo.default_turn_time,
    fpo.label_override,
    fpo.color_override,
    fpo.created_at,
    fpo.updated_at,
    ts.id AS session_id,
    COALESCE(ts.status::TEXT, 'available') AS session_status,
    ts.session_number,
    ts.party_size,
    ts.guest_name,
    ts.order_id,
    ts.server_staff_id,
    COALESCE(ts.is_vip, false) AS is_vip,
    COALESCE(ts.needs_attention, false) AS needs_attention,
    COALESCE(ts.current_course, 1) AS current_course,
    ts.seated_at,
    ts.reservation_id,
    ts.waitlist_id,
    (
      SELECT ARRAY_AGG(tst2.table_id ORDER BY tst2.seated_position)
      FROM table_session_tables tst2
      WHERE tst2.session_id = ts.id
      AND tst2.is_active = true
    ) AS merged_tables
  FROM floor_plan_objects fpo
  LEFT JOIN table_session_tables tst
    ON tst.table_id = fpo.id
    AND tst.is_active = true
  LEFT JOIN table_sessions ts
    ON ts.id = tst.session_id
    AND ts.is_active = true
    AND ts.status NOT IN ('cleaning')
  WHERE fpo.floor_plan_id = p_floor_plan_id
    AND fpo.is_active = true
  ORDER BY fpo.z_index, fpo.name;
END;
$$;


ALTER FUNCTION "public"."get_floor_plan_objects_with_sessions"("p_floor_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_floor_plan_status"("p_floor_plan_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$BEGIN
  RETURN (
    SELECT json_build_object(
      'floor_plan_id', p_floor_plan_id,
      'timestamp', NOW(),
      'tables', (
        SELECT COALESCE(json_agg(
          json_build_object(
            'id', fpo.id,
            'name', fpo.name,
            'shape_id', fpo.shape_id,
            'category', fpo.category,
            'x', fpo.x,
            'y', fpo.y,
            'rotation', fpo.rotation,
            'capacity', fpo.capacity,
            'is_active', fpo.is_active,
            -- Active session info (if any)
            'session', (
              SELECT json_build_object(
                'id', ts.id,
                'session_number', ts.session_number,
                'status', ts.status,
                'party_size', ts.party_size,
                'guest_name', ts.guest_name,
                'server_staff_id', ts.server_staff_id,
                'order_id', ts.order_id,
                'seated_at', ts.seated_at,
                'current_course', ts.current_course,
                'needs_attention', ts.needs_attention,
                'is_vip', ts.is_vip,
                'minutes_seated', EXTRACT(EPOCH FROM (NOW() - ts.seated_at)) / 60,
                'merged_tables', (
                  SELECT json_agg(tst2.table_id)
                  FROM public.table_session_tables tst2
                  WHERE tst2.session_id = ts.id AND tst2.table_id != fpo.id
                )
              )
              FROM public.table_sessions ts
              JOIN public.table_session_tables tst ON tst.session_id = ts.id
              WHERE tst.table_id = fpo.id AND ts.is_active = TRUE
            ),
            -- Upcoming reservation
            'next_reservation', (
              SELECT json_build_object(
                'id', r.id,
                'party_name', r.party_name,
                'party_size', r.party_size,
                'time', r.reservation_time,
                'status', r.status
              )
              FROM public.reservations r
              WHERE r.assigned_table_ids @> ARRAY[fpo.id]
                AND r.reservation_date = CURRENT_DATE
                AND r.status IN ('pending', 'confirmed', 'reminded')
              ORDER BY r.reservation_time
              LIMIT 1
            )
          )
        ), '[]'::json)
        FROM public.floor_plan_objects fpo
        WHERE fpo.floor_plan_id = p_floor_plan_id
          AND fpo.category IN ('table', 'booth')
          AND fpo.is_active = TRUE
      ),
      'summary', (
        SELECT json_build_object(
          'total_tables', COUNT(*),
          'available', COUNT(*) FILTER (WHERE session_id IS NULL),
          'occupied', COUNT(*) FILTER (WHERE session_id IS NOT NULL),
          'total_capacity', SUM(capacity),
          'current_covers', SUM(COALESCE(party_size, 0))
        )
        FROM (
          SELECT 
            fpo.id,
            fpo.capacity,
            ts.id as session_id,
            ts.party_size
          FROM public.floor_plan_objects fpo
          LEFT JOIN public.table_session_tables tst ON tst.table_id = fpo.id
          LEFT JOIN public.table_sessions ts ON ts.id = tst.session_id AND ts.is_active = TRUE
          WHERE fpo.floor_plan_id = p_floor_plan_id
            AND fpo.category IN ('table', 'booth')
            AND fpo.is_active = TRUE
        ) sub
      )
    )
    FROM public.floor_plans fp
    WHERE fp.id = p_floor_plan_id
      AND fp.merchant_id = user_merchant_id()
      -- AND fp.location_id = ANY(user_location_ids())
  );
END;$$;


ALTER FUNCTION "public"."get_floor_plan_status"("p_floor_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_items_for_location"("p_merchant_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN (
        SELECT COALESCE(json_agg(
            json_build_object(
                'id', mi.id,
                'name', mi.name,
                'description', mi.description,
                'image', mi.image,
                'meal_types', mi.meal_types,
                'allergens', mi.allergens,
                'card_bg_color', mi.card_bg_color,
                'stock_tracking_mode', mi.stock_tracking_mode,
                
                -- Base prices (Level 1)
                'base_price', mi.price,
                'base_cash_price', mi.cash_price,
                'base_delivery_price', mi.delivery_price,
                'base_availability', mi.availability,

                -- Location override (Level 2)
                'location_override', CASE
                    WHEN lio.id IS NOT NULL THEN json_build_object(
                        'id', lio.id,
                        'custom_price', lio.custom_price,
                        'custom_cash_price', lio.custom_cash_price,
                        'custom_delivery_price', lio.custom_delivery_price,
                        'price_modifier', lio.price_modifier,
                        'price_modifier_type', lio.price_modifier_type,
                        'is_available', lio.is_available,
                        'stock_tracking_mode', lio.stock_tracking_mode,
                        'current_stock', lio.current_stock,
                        'low_stock_threshold', lio.low_stock_threshold
                    )
                    ELSE NULL
                END,

                -- Effective values
                'effective_price', COALESCE(lio.custom_price, mi.price),
                'effective_cash_price', COALESCE(lio.custom_cash_price, mi.cash_price),
                'effective_delivery_price', COALESCE(lio.custom_delivery_price, mi.delivery_price),
                'effective_availability', COALESCE(lio.is_available, mi.availability),
                
                -- UI flags
                'has_location_override', (lio.id IS NOT NULL),
                'price_source', CASE
                    WHEN lio.custom_price IS NOT NULL THEN 'location_override'
                    ELSE 'base'
                END,
                'modifier_groups', (
                    SELECT COALESCE(json_agg(
                        json_build_object(
                            'id', mg.id,
                            'name', mg.name,
                            'description', mg.description,
                            'min_selections', mg.min_selections,
                            'max_selections', mg.max_selections,
                            'is_required', mg.is_required,
                            
                            -- Group Availability: Location Override > Global Default
                            'is_active', COALESCE(lmgo.is_active, true),
                            
                            'items', (
                                SELECT COALESCE(json_agg(
                                    json_build_object(
                                        'id', mgi.id,
                                        'name', mgi.name,
                                        'description', mgi.description,
                                        
                                        -- Price: Location Override > Global Base
                                        'price_modifier', COALESCE(lmio_mod.price_modifier, mgi.price_modifier),
                                        
                                        -- Availability: Location Override > Global Base
                                        'is_active', (
                                            mgi.is_active = true 
                                            AND COALESCE(lmio_mod.is_active, true) = true
                                        ),
                                        
                                        -- Stock: Location Specific
                                        'stock_tracking_mode', COALESCE(lmio_mod.stock_tracking_mode, 'in_stock'),
                                        'current_stock', lmio_mod.current_stock
                                    ) ORDER BY mgi.name ASC
                                ), '[]'::json)
                                FROM modifier_group_items mgi
                                -- JOIN: Location Item Overrides
                                LEFT JOIN location_modifier_item_overrides lmio_mod
                                    ON lmio_mod.modifier_group_item_id = mgi.id 
                                    AND lmio_mod.location_id = p_location_id
                                WHERE mgi.modifier_group_id = mg.id
                                -- We usually show even inactive items in the "Library" view so managers can enable them
                                -- But for simplicity, let's filter out globally deleted ones
                            )
                        ) ORDER BY mg.name ASC
                    ), '[]'::json)
                    FROM menu_item_modifier_groups mimg
                    JOIN modifier_groups mg ON mg.id = mimg.modifier_group_id
                    -- JOIN: Location Group Overrides
                    LEFT JOIN location_modifier_group_overrides lmgo
                        ON lmgo.modifier_group_id = mg.id 
                        AND lmgo.location_id = p_location_id
                    WHERE mimg.menu_item_id = mi.id
                ),
                
                -- Categories
                'categories', (
                    SELECT COALESCE(json_agg(
                        json_build_object(
                            'id', c.id,
                            'name', c.name
                        )
                    ), '[]'::json)
                    FROM menu_item_categories mic
                    JOIN categories c ON c.id = mic.category_id
                    WHERE mic.menu_item_id = mi.id
                ),
                
                -- Menu Count
                'menu_count', (
                    SELECT COUNT(*) 
                    FROM menu_item_menus mim 
                    WHERE mim.menu_item_id = mi.id
                ),
                
                'created_at', mi.created_at,
                'updated_at', mi.updated_at
            )
            -- FIX: ORDER BY moved inside the aggregation
            ORDER BY mi.name ASC
        ), '[]'::json)
        FROM menu_items mi
        LEFT JOIN location_item_overrides lio 
            ON lio.menu_item_id = mi.id 
            AND lio.location_id = p_location_id
        WHERE mi.merchant_id = p_merchant_id
    );
END;
$$;


ALTER FUNCTION "public"."get_items_for_location"("p_merchant_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_items_for_location_library"("p_merchant_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN (
        SELECT COALESCE(json_agg(
            json_build_object(
                'id', mi.id,
                'name', mi.name,
                'description', mi.description,
                'image', mi.image,
                'allergens', mi.allergens,
                'meal_types', mi.meal_types,
                'card_bg_color', mi.card_bg_color,

                -- Stock info
                'stock_tracking_mode', mi.stock_tracking_mode,

                -- Tax & Inventory Control (L1 - Base)
                'tax_category', mi.tax_category,
                'is_tax_exempt', mi.is_tax_exempt,
                'available_channels', mi.available_channels,

                -- Level 1: Base price
                'base_price', mi.price,
                'base_cash_price', mi.cash_price,
                'base_delivery_price', mi.delivery_price,
                'base_availability', mi.availability,

                -- Level 2: Location item override (if exists)
                'location_override', CASE
                    WHEN lio.id IS NOT NULL THEN json_build_object(
                        'id', lio.id,
                        'custom_price', lio.custom_price,
                        'custom_cash_price', lio.custom_cash_price,
                        'price_modifier', lio.price_modifier,
                        'price_modifier_type', lio.price_modifier_type,
                        'is_available', lio.is_available,
                        'stock_tracking_mode', lio.stock_tracking_mode,
                        'current_stock', lio.current_stock,
                        'tax_category', lio.tax_category,
                        'is_tax_exempt', lio.is_tax_exempt,
                        'available_channels', lio.available_channels,
                        'custom_delivery_price', lio.custom_delivery_price
                    )
                    ELSE NULL
                END,

                -- ============================================================
                -- EFFECTIVE PRICE: L2 > L1 ONLY (NO CATEGORY PRICES!)
                -- ============================================================
                'effective_price', COALESCE(
                    lio.custom_price,            -- L2: Location item override
                    mi.price                     -- L1: Base
                ),

                'effective_cash_price', COALESCE(
                    lio.custom_cash_price,
                    mi.cash_price
                ),

                'effective_delivery_price', COALESCE(
                    lio.custom_delivery_price,       -- L2: Location item override
                    mi.delivery_price                -- L1: Base
                ),

                'effective_availability', COALESCE(
                    lio.is_available,
                    mi.availability
                ),

                -- Effective Tax & Inventory (L2 > L1)
                'effective_tax_category', COALESCE(
                    lio.tax_category,
                    mi.tax_category
                ),
                'effective_is_tax_exempt', COALESCE(
                    lio.is_tax_exempt,
                    mi.is_tax_exempt
                ),
                'effective_available_channels', COALESCE(
                    lio.available_channels,
                    mi.available_channels
                ),

                -- Price source indicator
                'price_source', CASE
                    WHEN lio.custom_price IS NOT NULL THEN 'location_item'
                    ELSE 'base'
                END,

                -- Override flags
                'has_location_override', (lio.id IS NOT NULL),

                -- Categories this item belongs to (for UI filtering/display)
                -- NOTE: We show categories but don't use their prices!
                'categories', COALESCE(
                    (
                        SELECT json_agg(
                            json_build_object(
                                'id', c.id,
                                'name', c.name,
                                'location_id', c.location_id,
                                'location_name', (SELECT l.name FROM locations l WHERE l.id = c.location_id),
                                'is_global', COALESCE(c.is_global, c.location_id IS NULL)
                            ) ORDER BY c.name
                        )
                        FROM category_items ci
                        JOIN categories c ON c.id = ci.category_id
                        WHERE ci.menu_item_id = mi.id
                          AND c.merchant_id = p_merchant_id
                          AND (
                              -- All categories if no location specified
                              p_location_id IS NULL
                              OR
                              -- Global + location-specific categories
                              c.location_id IS NULL
                              OR
                              c.location_id = p_location_id
                          )
                    ),
                    '[]'::json
                ),

                'created_at', mi.created_at,
                'updated_at', mi.updated_at
            )
            ORDER BY mi.name
        ), '[]'::json)
        FROM menu_items mi
        LEFT JOIN location_item_overrides lio
            ON lio.menu_item_id = mi.id
            AND lio.location_id = p_location_id
        WHERE mi.merchant_id = p_merchant_id
    );
END;
$$;


ALTER FUNCTION "public"."get_items_for_location_library"("p_merchant_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_items_for_location_library"("p_merchant_id" "uuid", "p_location_id" "uuid") IS 'Get items for Items Library view with L2 (location override) + L1 (base) pricing only. Category prices are excluded from effective_price calculation.';



CREATE OR REPLACE FUNCTION "public"."get_kds_tickets"("p_location_id" "uuid", "p_statuses" "text"[] DEFAULT ARRAY['sent'::"text", 'preparing'::"text", 'ready'::"text"]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(ticket ORDER BY ticket->>'start_time' ASC NULLS LAST), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'ticket_id', o.id::text || '_c' || COALESCE(oi_grouped.course_number, 1)::text,
      'order_id', o.id,
      'db_order_id', o.id,
      'order_number', o.order_number,
      'display_number', o.display_number,
      'course_number', COALESCE(oi_grouped.course_number, 1),
      'status', CASE
        WHEN oi_grouped.all_ready THEN 'ready'
        WHEN oi_grouped.any_sent THEN 'pending'
        ELSE 'cooking'
      END,
      'order_type', o.order_type,
      'table_name', o.table_number,
      'customer_name', o.customer_name,
      'start_time', COALESCE(o.sent_to_kitchen_at, o.created_at),
      'item_count', oi_grouped.item_count,
      'items', oi_grouped.items_json
    ) AS ticket
    FROM orders o
    -- Join aggregated items grouped by course
    INNER JOIN (
      SELECT
        oi.order_id,
        COALESCE(oi.course_number, 1) AS course_number,
        -- Status aggregation
        bool_and(oi.kitchen_status = 'ready') AS all_ready,
        bool_or(oi.kitchen_status = 'sent' OR oi.kitchen_status IS NULL) AS any_sent,
        -- Item count (sum of quantities)
        SUM(oi.quantity)::int AS item_count,
        -- Items array with nested modifiers
        jsonb_agg(
          jsonb_build_object(
            'id', oi.id,
            'name', COALESCE(oi.open_item_name, oi.item_name),
            'quantity', oi.quantity,
            'kitchen_status', COALESCE(oi.kitchen_status, 'sent'),
            'special_instructions', oi.special_instructions,
            'category_name', oi.category_name,
            'category_id', oi.category_id,
            'menu_name', oi.menu_name,
            'menu_id', oi.menu_id,
            'modifiers', (
              SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                  'modifier_name', oim.modifier_name,
                  'modifier_group_name', oim.modifier_group_name,
                  'price_modifier', oim.price_modifier
                )
              ), '[]'::jsonb)
              FROM order_item_modifiers oim
              WHERE oim.order_item_id = oi.id
            )
          )
        ) AS items_json
      FROM order_items oi
      WHERE COALESCE(oi.is_voided, false) = false
        AND (oi.kitchen_status = ANY(p_statuses) OR oi.kitchen_status IS NULL)
      GROUP BY oi.order_id, COALESCE(oi.course_number, 1)
    ) oi_grouped ON oi_grouped.order_id = o.id
    WHERE o.location_id = p_location_id
      AND o.status NOT IN ('completed', 'cancelled', 'void', 'refunded')
  ) sub;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_kds_tickets"("p_location_id" "uuid", "p_statuses" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_kds_tickets_v2"("p_location_id" "uuid", "p_statuses" "text"[] DEFAULT ARRAY['sent'::"text", 'preparing'::"text", 'ready'::"text"], "p_kds_display_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$DECLARE
  v_result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(ticket ORDER BY ticket->>'start_time' ASC NULLS LAST), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'ticket_id', o.id::text || '_c' || COALESCE(oi_grouped.course_number, 1)::text  || '_f' || COALESCE(EXTRACT(EPOCH FROM oi_grouped.fire_time::timestamptz)::bigint::text, '0'),
      'order_id', o.id,
      'db_order_id', o.id,
      'order_number', o.order_number,
      'display_number', o.display_number,
      'course_number', COALESCE(oi_grouped.course_number, 1),
      'status', CASE
        WHEN oi_grouped.all_ready THEN 'ready'
        WHEN oi_grouped.any_sent THEN 'pending'
        ELSE 'cooking'
      END,
      'order_type', o.order_type,
      'order_source', o.order_source,
      'table_name', o.table_number,
      'customer_name', o.customer_name,
      'start_time', COALESCE(oi_grouped.fire_time::timestamptz, o.sent_to_kitchen_at, o.created_at),
      'item_count', oi_grouped.item_count,
      'prioritized', oi_grouped.any_prioritized,
      'items', oi_grouped.items_json
    ) AS ticket
    FROM orders o
    -- Join aggregated items grouped by course
    INNER JOIN (
      SELECT
        oi.order_id,
        COALESCE(oi.course_number, 1) AS course_number,
        -- Status aggregation
        bool_and(oi.kitchen_status = 'ready') AS all_ready,
        bool_or(oi.kitchen_status = 'sent' OR oi.kitchen_status IS NULL) AS any_sent,
        -- Item count (sum of quantities)
        SUM(oi.quantity)::int AS item_count,
        oi.fire_time,
        -- Ticket-level priority flag (true if any item is prioritized)
        bool_or(COALESCE(oi.is_prioritized, false)) AS any_prioritized,
        -- Items array with nested modifiers (stable ordering)
        jsonb_agg(
          jsonb_build_object(
            'id', oi.id,
            'name', COALESCE(oi.open_item_name, oi.item_name),
            'quantity', oi.quantity,
            'kitchen_status', COALESCE(oi.kitchen_status, 'sent'),
            'special_instructions', oi.special_instructions,
            'category_name', oi.category_name,
            'category_id', oi.category_id,
            'menu_name', oi.menu_name,
            'menu_id', oi.menu_id,
            'prep_station', oi.prep_station,
            'rush', COALESCE(oi.rush, false),
            'is_prioritized', COALESCE(oi.is_prioritized, false),
            'fire_time', oi.fire_time::timestamptz,
            'modifiers', (
              SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                  'modifier_name', oim.modifier_name,
                  'modifier_group_name', oim.modifier_group_name,
                  'price_modifier', oim.price_modifier,
                  'is_no', COALESCE(oim.is_no, false)

                )
              ), '[]'::jsonb)
              FROM order_item_modifiers oim
              WHERE oim.order_item_id = oi.id
            )
          )
          ORDER BY oi.id ASC
        ) AS items_json
      FROM order_items oi
      -- When p_kds_display_id is provided, only include items routed to that display
      LEFT JOIN kds_item_status kis
        ON kis.order_item_id = oi.id
        AND kis.kds_display_id = p_kds_display_id
        AND kis.status NOT IN ('cancelled', 'completed')
      WHERE COALESCE(oi.is_voided, false) = false
        AND (oi.kitchen_status = ANY(p_statuses) OR oi.kitchen_status IS NULL)
        -- Filter: if display ID provided, only show routed items; otherwise show all
        AND (p_kds_display_id IS NULL OR kis.id IS NOT NULL)
      GROUP BY oi.order_id, COALESCE(oi.course_number, 1), oi.fire_time
    ) oi_grouped ON oi_grouped.order_id = o.id
    WHERE o.location_id = p_location_id
      AND o.status NOT IN ('completed', 'cancelled', 'void', 'refunded')
  ) sub;

  RETURN v_result;
END;$$;


ALTER FUNCTION "public"."get_kds_tickets_v2"("p_location_id" "uuid", "p_statuses" "text"[], "p_kds_display_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_kitchen_performance_stats"("p_merchant_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_start_date" timestamp with time zone DEFAULT ("now"() - '7 days'::interval), "p_end_date" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  -- Main stats aggregation using order_items and orders
  WITH item_data AS (
    SELECT
      oi.id,
      oi.order_id,
      oi.prep_station,
      oi.rush,
      oi.created_at,
      oi.item_status,
      o.created_at as order_created_at,
      o.updated_at as order_updated_at,
      -- Time from item creation to order update (proxy for prep time)
      EXTRACT(EPOCH FROM (o.updated_at - oi.created_at)) as item_to_order_update_seconds,
      -- Time from order creation to order update (full ticket time)
      EXTRACT(EPOCH FROM (o.updated_at - o.created_at)) as ticket_time_seconds
    FROM order_items oi
    JOIN orders o ON oi.order_id = o.id
    WHERE o.merchant_id = p_merchant_id
      AND (p_location_id IS NULL OR o.location_id = p_location_id)
      AND oi.created_at >= p_start_date
      AND oi.created_at <= p_end_date
      AND oi.item_status NOT IN ('cancelled', 'voided')
  ),
  ticket_summary AS (
    -- Overall ticket times per order
    SELECT
      order_id,
      MAX(ticket_time_seconds) as ticket_time_seconds
    FROM item_data
    GROUP BY order_id
  ),
  station_stats AS (
    -- Per-station statistics
    SELECT
      COALESCE(id.prep_station, 'Unassigned') as station_name,
      COUNT(*) as total_items,
      AVG(id.item_to_order_update_seconds) as avg_prep_seconds,
      COUNT(CASE WHEN id.item_status IN ('served', 'ready') THEN 1 END) as completed_items,
      COUNT(CASE WHEN id.item_status IN ('pending', 'preparing') THEN 1 END) as pending_items
    FROM item_data id
    GROUP BY id.prep_station
  ),
  hourly_day_stats AS (
    -- Heatmap data: hour and day of week
    SELECT
      EXTRACT(HOUR FROM id.created_at AT TIME ZONE 'UTC')::int as hour_of_day,
      EXTRACT(DOW FROM id.created_at AT TIME ZONE 'UTC')::int as day_of_week,
      AVG(id.item_to_order_update_seconds) as avg_prep_seconds,
      COUNT(*) as item_count
    FROM item_data id
    GROUP BY
      EXTRACT(HOUR FROM id.created_at AT TIME ZONE 'UTC'),
      EXTRACT(DOW FROM id.created_at AT TIME ZONE 'UTC')
  ),
  rush_analysis AS (
    -- Rush vs normal orders
    SELECT
      COUNT(CASE WHEN id.rush = true THEN 1 END) as rush_items,
      COUNT(*) as total_items,
      AVG(id.item_to_order_update_seconds) FILTER (WHERE id.rush = true) as avg_rush_seconds,
      AVG(id.item_to_order_update_seconds) FILTER (WHERE id.rush = false OR id.rush IS NULL) as avg_normal_seconds
    FROM item_data id
  ),
  completion_analysis AS (
    -- Item status breakdown
    SELECT
      COUNT(CASE WHEN id.item_status IN ('served', 'ready') THEN 1 END) as completed_items,
      COUNT(CASE WHEN id.item_status IN ('pending', 'preparing') THEN 1 END) as pending_items,
      COUNT(*) as total_items
    FROM item_data id
  ),
  daily_trend_data AS (
    -- Daily average prep times
    SELECT
      DATE(id.created_at AT TIME ZONE 'UTC') as trend_date,
      AVG(id.item_to_order_update_seconds) as avg_prep_seconds
    FROM item_data id
    GROUP BY DATE(id.created_at AT TIME ZONE 'UTC')
  )
  SELECT jsonb_build_object(
    'avg_ticket_time_minutes',
    ROUND(COALESCE((SELECT AVG(ticket_time_seconds) FROM ticket_summary) / 60.0, 0)::numeric, 2),
    'total_items_processed',
    (SELECT COUNT(*) FROM item_data),
    'by_station',
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'station_id', ss.station_name,
        'display_name', ss.station_name,
        'total_items', ss.total_items,
        'avg_prep_minutes', ROUND(COALESCE(ss.avg_prep_seconds / 60.0, 0)::numeric, 2),
        'auto_bumped', ss.pending_items,
        'manual_completed', ss.completed_items,
        'alert_threshold_minutes', 10,
        'auto_bump_threshold_minutes', 20
      ) ORDER BY ss.station_name)
      FROM station_stats ss
    ), '[]'::jsonb),
    'by_hour_and_day',
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'hour_of_day', hds.hour_of_day,
        'day_of_week', hds.day_of_week,
        'avg_ticket_minutes', ROUND(COALESCE(hds.avg_prep_seconds / 60.0, 0)::numeric, 2)
      ) ORDER BY hds.hour_of_day, hds.day_of_week)
      FROM hourly_day_stats hds
      WHERE hds.item_count > 0
    ), '[]'::jsonb),
    'rush_stats',
    (
      SELECT jsonb_build_object(
        'rush_items', COALESCE(ra.rush_items, 0),
        'total_items', COALESCE(ra.total_items, 0),
        'rush_percentage', COALESCE(ROUND(((ra.rush_items::float / NULLIF(ra.total_items, 0)) * 100)::numeric, 2), 0),
        'avg_rush_time_minutes', COALESCE(ROUND((ra.avg_rush_seconds / 60.0)::numeric, 2), 0),
        'avg_normal_time_minutes', COALESCE(ROUND((ra.avg_normal_seconds / 60.0)::numeric, 2), 0)
      )
      FROM rush_analysis ra
    ),
    'auto_bump_stats',
    (
      SELECT jsonb_build_object(
        'auto_bumped', COALESCE(ca.pending_items, 0),
        'manual_completed', COALESCE(ca.completed_items, 0),
        'total_items', COALESCE(ca.total_items, 0),
        'auto_bump_rate', COALESCE(ROUND(((ca.pending_items::float / NULLIF(ca.total_items, 0)) * 100)::numeric, 2), 0)
      )
      FROM completion_analysis ca
    ),
    'daily_trend',
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'date', dtd.trend_date,
        'avg_ticket_minutes', ROUND(COALESCE(dtd.avg_prep_seconds / 60.0, 0)::numeric, 2)
      ) ORDER BY dtd.trend_date)
      FROM daily_trend_data dtd
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_kitchen_performance_stats"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_location_floor_plans"("p_location_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$BEGIN
  RETURN (
    SELECT COALESCE(json_agg(
      json_build_object(
        'id', fp.id,
        'name', fp.name,
        'description', fp.description,
        'is_active', fp.is_active,
        'is_default', fp.is_default,
        'display_order', fp.display_order,
        'table_count', (
          SELECT COUNT(*) FROM public.floor_plan_objects fpo
          WHERE fpo.floor_plan_id = fp.id AND fpo.category IN ('table', 'booth')
        ),
        'total_capacity', (
          SELECT COALESCE(SUM(fpo.capacity), 0) FROM public.floor_plan_objects fpo
          WHERE fpo.floor_plan_id = fp.id AND fpo.category IN ('table', 'booth')
        ),
        -- New nested objects array
        'objects', (
          SELECT COALESCE(json_agg(
            json_build_object(
              'id', fpo.id,
              'name', fpo.name,
              'shape_id', fpo.shape_id,
              'category', fpo.category,
              'x', fpo.x,
              'y', fpo.y,
              'rotation', fpo.rotation,
              'width', fpo.width,
              'height', fpo.height,
              'capacity', fpo.capacity,
              'min_capacity', fpo.min_capacity,
              'is_reservable', fpo.is_reservable,
              'is_combinable', fpo.is_combinable,
              'default_turn_time', fpo.default_turn_time,
              'section_id', fpo.section_id,
              'zone_name', fpo.zone_name,
              'label_override', fpo.label_override,
              'color_override', fpo.color_override,
              'z_index', fpo.z_index,
              'is_visible', fpo.is_visible,
              'is_active', fpo.is_active
            ) ORDER BY fpo.z_index ASC, fpo.created_at ASC
          ), '[]'::json)
          FROM public.floor_plan_objects fpo
          WHERE fpo.floor_plan_id = fp.id
        )
      ) ORDER BY fp.display_order, fp.name
    ), '[]'::json)
    FROM public.floor_plans fp
    WHERE fp.location_id = p_location_id
      AND fp.merchant_id = user_merchant_id()
  );
END;$$;


ALTER FUNCTION "public"."get_location_floor_plans"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_location_item_price"("p_location_id" "uuid", "p_menu_item_id" "uuid", "p_is_cash" boolean DEFAULT false) RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    v_price DECIMAL(10, 2);
BEGIN
    -- First check for location override
    IF p_is_cash THEN
        SELECT COALESCE(o.custom_cash_price, mi.cash_price, mi.price)
        INTO v_price
        FROM menu_items mi
        LEFT JOIN location_menu_item_overrides o 
            ON o.menu_item_id = mi.id AND o.location_id = p_location_id
        WHERE mi.id = p_menu_item_id;
    ELSE
        SELECT COALESCE(o.custom_price, mi.price)
        INTO v_price
        FROM menu_items mi
        LEFT JOIN location_menu_item_overrides o 
            ON o.menu_item_id = mi.id AND o.location_id = p_location_id
        WHERE mi.id = p_menu_item_id;
    END IF;
    
    RETURN v_price;
END;
$$;


ALTER FUNCTION "public"."get_location_item_price"("p_location_id" "uuid", "p_menu_item_id" "uuid", "p_is_cash" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_location_role"("p_location_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
    SELECT role_code FROM location_members
    WHERE user_id = current_user_id()
      AND location_id = p_location_id
      AND is_active = true
    LIMIT 1;
$$;


ALTER FUNCTION "public"."get_location_role"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_location_stations_with_status"("p_location_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN (
    SELECT COALESCE(json_agg(station_data ORDER BY station_number, station_name), '[]'::json)
    FROM (
      SELECT
        s.id,
        s.station_name,
        s.station_type,
        s.station_number,
        s.is_active,
        ss.id IS NULL as is_available,
        CASE WHEN ss.id IS NOT NULL THEN json_build_object(
          'session_id', ss.id,
          'device_name', ss.device_name,
          'staff_name', ss.staff_name,
          'started_at', ss.started_at
        ) ELSE null END as current_session,
        -- Station capabilities and view scope (Phase 1 Foundation)
        s.view_scope,
        s.can_create_orders,
        s.can_process_payments,
        s.can_void_orders,
        s.can_apply_discounts,
        s.can_update_kitchen_status,
        s.is_online,
        s.last_heartbeat_at,
        -- Device hardware fields
        s.hardware_model,
        s.device_manufacturer,
        s.device_model,
        s.network_type,
        s.battery_level,
        s.has_builtin_printer,
        s.has_builtin_cfd,
        s.has_cash_drawer_port,
        s.has_nfc,
        s.app_version,
        s.os_version,
        -- Payment terminal data (non-sensitive metadata only)
        CASE WHEN pt.id IS NOT NULL THEN json_build_object(
          'id', pt.id,
          'terminal_name', pt.terminal_name,
          'tpn', pt.tpn,
          'register_id', pt.register_id,
          'terminal_type', pt.terminal_type,
          'terminal_model', pt.terminal_model,
          'is_connected', pt.is_connected,
          'last_connection_status', pt.last_connection_status,
          'last_connection_test_at', pt.last_connection_test_at,
          'ip_address', pt.local_ip_address,
          'port', pt.local_port,
          'connection_type', pt.connection_type
        ) ELSE null END as payment_terminal
      FROM stations s
      LEFT JOIN station_sessions ss
        ON s.id = ss.station_id
        AND ss.session_status = 'active'
      LEFT JOIN station_devices sd
        ON s.id = sd.station_id
        AND sd.device_type = 'payment_terminal'
        AND sd.is_active = TRUE
      LEFT JOIN payment_terminals pt
        ON sd.payment_terminal_id = pt.id
        AND pt.is_active = TRUE
      WHERE s.location_id = p_location_id
        AND s.is_active = TRUE
    ) station_data
  );
END;
$$;


ALTER FUNCTION "public"."get_location_stations_with_status"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_location_table_status_v2"("p_location_id" "uuid") RETURNS TABLE("table_id" "uuid", "table_name" "text", "table_capacity" integer, "table_category" "text", "section_id" "uuid", "session_id" "uuid", "session_status" "text", "order_id" "uuid", "party_size" integer, "server_staff_id" "uuid", "guest_name" "text", "guest_phone" "text", "reservation_id" "uuid", "waitlist_id" "uuid", "session_number" "text", "seated_at" timestamp with time zone, "is_vip" boolean, "needs_attention" boolean, "current_course" integer, "first_order_at" timestamp with time zone, "food_served_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    fpo.id                      AS table_id,
    fpo.name                    AS table_name,
    fpo.capacity                AS table_capacity,
    fpo.category::TEXT          AS table_category,
    fpo.section_id              AS section_id,
    ts.id                       AS session_id,
    COALESCE(ts.status::TEXT, 'available') AS session_status,
    ts.order_id                 AS order_id,
    COALESCE(ts.party_size, 0)  AS party_size,
    ts.server_staff_id          AS server_staff_id,
    ts.guest_name               AS guest_name,
    ts.guest_phone              AS guest_phone,
    ts.reservation_id           AS reservation_id,
    ts.waitlist_id              AS waitlist_id,
    ts.session_number           AS session_number,
    ts.seated_at                AS seated_at,
    COALESCE(ts.is_vip, false)  AS is_vip,
    COALESCE(ts.needs_attention, false) AS needs_attention,
    COALESCE(ts.current_course, 1) AS current_course,
    ts.first_order_at           AS first_order_at,
    ts.food_served_at           AS food_served_at
  FROM floor_plan_objects fpo
  LEFT JOIN table_session_tables tst
    ON tst.table_id = fpo.id
    AND tst.is_active = true
  LEFT JOIN table_sessions ts
    ON ts.id = tst.session_id
    AND ts.is_active = true
    AND ts.status NOT IN ('cleaning')  -- cleaning sessions are "almost done"
  WHERE fpo.location_id = p_location_id
    AND fpo.is_active = true
    AND fpo.category IN ('table', 'booth')
  ORDER BY fpo.name;
END;
$$;


ALTER FUNCTION "public"."get_location_table_status_v2"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_menu_for_location"("p_menu_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    result JSON;
BEGIN
    SELECT json_build_object(
        'id', m.id,
        'merchant_id', m.merchant_id,
        'location_id', m.location_id,
        'name', m.name,
        'description', m.description,
        'is_active', m.is_active,
        'is_global', (m.location_id IS NULL),
        'is_location_owned', (m.location_id IS NOT NULL),
        'created_at', m.created_at,
        'updated_at', m.updated_at,
        
        'menu_categories', (
            SELECT COALESCE(json_agg(
                json_build_object(
                    'id', mc.id,
                    'category', json_build_object(
                        'id', c.id,
                        'name', c.name,
                        'description', c.description,
                        'image', c.image,
                        'is_active', COALESCE(lco.is_active, c.is_active),
                        'has_override', (lco.id IS NOT NULL)
                    )
                ) 
            ), '[]'::json)
            FROM menu_categories mc
            JOIN categories c ON c.id = mc.category_id
            LEFT JOIN location_category_overrides lco 
                ON lco.category_id = c.id AND lco.location_id = p_location_id
            WHERE mc.menu_id = m.id
        ),
        
        'menu_item_menus', (
            SELECT COALESCE(json_agg(
                json_build_object(
                    'id', mim.id,
                    
                    -- Level 3: Menu-level pricing
                    'custom_price', mim.custom_price,
                    'custom_cash_price', mim.custom_cash_price,
                    'custom_delivery_price', mim.custom_delivery_price,
                    'is_available', mim.is_available,

                    -- Level 4: Location + Menu override
                    'location_menu_override', CASE
                        WHEN lmio.id IS NOT NULL THEN json_build_object(
                            'id', lmio.id,
                            'custom_price', lmio.custom_price,
                            'custom_cash_price', lmio.custom_cash_price,
                            'custom_delivery_price', lmio.custom_delivery_price,
                            'is_available', lmio.is_available
                        )
                        ELSE NULL
                    END,

                    'menu_item', json_build_object(
                        'id', mi.id,
                        'name', mi.name,
                        'description', mi.description,
                        'image', mi.image,
                        'meal_types', mi.meal_types,
                        'allergens', mi.allergens,
                        'card_bg_color', mi.card_bg_color,

                        -- Level 1: Global base
                        'price', mi.price,
                        'cash_price', mi.cash_price,
                        'delivery_price', mi.delivery_price,
                        'availability', mi.availability,

                        -- Level 2: Location item base override
                        'location_item_override', CASE
                            WHEN lio.id IS NOT NULL THEN json_build_object(
                                'id', lio.id,
                                'custom_price', lio.custom_price,
                                'custom_cash_price', lio.custom_cash_price,
                                'custom_delivery_price', lio.custom_delivery_price,
                                'price_modifier', lio.price_modifier,
                                'price_modifier_type', lio.price_modifier_type,
                                'is_available', lio.is_available,
                                'current_stock', lio.current_stock
                            )
                            ELSE NULL
                        END,
                        
                        -- ================================================
                        -- EFFECTIVE PRICE CALCULATION
                        -- Full cascade: Level 4 > Level 2 > Level 3 > Level 1
                        -- ================================================
                        'effective_price', CASE
                            -- Location-owned menu: just use menu price
                            WHEN m.location_id IS NOT NULL THEN 
                                COALESCE(mim.custom_price, mi.price)
                            -- Global menu with location context
                            ELSE COALESCE(
                                lmio.custom_price,                              -- Level 4
                                -- Level 2 with modifier logic
                                CASE 
                                    WHEN lio.price_modifier_type = 'add' AND lio.price_modifier IS NOT NULL THEN
                                        COALESCE(mim.custom_price, mi.price) + lio.price_modifier
                                    WHEN lio.price_modifier_type = 'percent' AND lio.price_modifier IS NOT NULL THEN
                                        COALESCE(mim.custom_price, mi.price) * (1 + lio.price_modifier / 100)
                                    WHEN lio.custom_price IS NOT NULL THEN
                                        lio.custom_price
                                    ELSE NULL
                                END,
                                mim.custom_price,                               -- Level 3
                                mi.price                                        -- Level 1
                            )
                        END,
                        
                        'effective_cash_price', CASE
                            WHEN m.location_id IS NOT NULL THEN 
                                COALESCE(mim.custom_cash_price, mi.cash_price)
                            ELSE COALESCE(
                                lmio.custom_cash_price,
                                CASE 
                                    WHEN lio.price_modifier_type = 'add' AND lio.price_modifier IS NOT NULL THEN
                                        COALESCE(mim.custom_cash_price, mi.cash_price) + lio.price_modifier
                                    WHEN lio.price_modifier_type = 'percent' AND lio.price_modifier IS NOT NULL THEN
                                        COALESCE(mim.custom_cash_price, mi.cash_price) * (1 + lio.price_modifier / 100)
                                    WHEN lio.custom_cash_price IS NOT NULL THEN
                                        lio.custom_cash_price
                                    ELSE NULL
                                END,
                                mim.custom_cash_price,
                                mi.cash_price
                            )
                        END,
                        
                        'effective_delivery_price', CASE
                            WHEN m.location_id IS NOT NULL THEN
                                COALESCE(mim.custom_delivery_price, mi.delivery_price)
                            ELSE COALESCE(
                                lmio.custom_delivery_price,
                                lio.custom_delivery_price,
                                mim.custom_delivery_price,
                                mi.delivery_price
                            )
                        END,

                        -- Availability: AND logic
                        'effective_availability', (
                            mi.availability = true
                            AND COALESCE(lio.is_available, true) = true
                            AND mim.is_available = true
                            AND COALESCE(lmio.is_available, true) = true
                        ),

                        -- UI helper flags
                        'has_location_item_override', (lio.id IS NOT NULL),
                        'has_menu_override', (mim.custom_price IS NOT NULL),
                        'has_location_menu_override', (lmio.id IS NOT NULL),
                        
                        'price_source', CASE
                            WHEN m.location_id IS NOT NULL AND mim.custom_price IS NOT NULL 
                                THEN 'location_menu'
                            WHEN lmio.custom_price IS NOT NULL 
                                THEN 'location_menu_override'
                            WHEN lio.custom_price IS NOT NULL OR lio.price_modifier IS NOT NULL 
                                THEN 'location_item_override'
                            WHEN mim.custom_price IS NOT NULL 
                                THEN 'menu_override'
                            ELSE 'base'
                        END,
                        
                        -- Price breakdown for admin UI
                        'price_breakdown', json_build_object(
                            'level_1_base', mi.price,
                            'level_1_delivery', mi.delivery_price,
                            'level_2_location_item', lio.custom_price,
                            'level_2_location_item_delivery', lio.custom_delivery_price,
                            'level_2_modifier', lio.price_modifier,
                            'level_2_modifier_type', lio.price_modifier_type,
                            'level_3_menu', mim.custom_price,
                            'level_3_menu_delivery', mim.custom_delivery_price,
                            'level_4_location_menu', lmio.custom_price,
                            'level_4_location_menu_delivery', lmio.custom_delivery_price
                        ),
                        
                        'stock_tracking_mode', COALESCE(
                            NULLIF(lio.stock_tracking_mode, 'use_default'),
                            mi.stock_tracking_mode
                        ),
                        'current_stock', lio.current_stock,
                        'modifier_groups', (
                            SELECT COALESCE(json_agg(
                                json_build_object(
                                    'id', mg.id,
                                    'name', mg.name,
                                    'min_selections', mg.min_selections,
                                    'max_selections', mg.max_selections,
                                    'is_required', mg.is_required,
                                    
                                    -- Group Availability Override
                                    'is_active', COALESCE(lmgo.is_active, true),
                                    
                                    'items', (
                                        SELECT COALESCE(json_agg(
                                            json_build_object(
                                                'id', mgi.id,
                                                'name', mgi.name,
                                                
                                                -- Modifier Price: Location Override > Global Base
                                                'price_modifier', COALESCE(lmio_mod.price_modifier, mgi.price_modifier),
                                                
                                                -- Modifier Availability: Location Override > Global Base
                                                'is_active', (
                                                    mgi.is_active = true 
                                                    AND COALESCE(lmio_mod.is_active, true) = true
                                                ),

                                                -- Stock Status (Location Specific)
                                                'stock_tracking_mode', COALESCE(lmio_mod.stock_tracking_mode, 'in_stock'),
                                                'current_stock', lmio_mod.current_stock
                                            ) ORDER BY mgi.name
                                        ), '[]'::json)
                                        FROM modifier_group_items mgi
                                        -- LEFT JOIN: Check for Item Override
                                        LEFT JOIN location_modifier_item_overrides lmio_mod
                                            ON lmio_mod.modifier_group_item_id = mgi.id 
                                            AND lmio_mod.location_id = p_location_id
                                        WHERE mgi.modifier_group_id = mg.id
                                    )
                                ) ORDER BY mg.name
                            ), '[]'::json)
                            FROM menu_item_modifier_groups mimg
                            JOIN modifier_groups mg ON mg.id = mimg.modifier_group_id
                            -- LEFT JOIN: Check for Group Override
                            LEFT JOIN location_modifier_group_overrides lmgo
                                ON lmgo.modifier_group_id = mg.id 
                                AND lmgo.location_id = p_location_id
                            WHERE mimg.menu_item_id = mi.id
                        )
                    )
                )
            ), '[]'::json)
            FROM menu_item_menus mim
            JOIN menu_items mi ON mi.id = mim.menu_item_id
            -- Level 2: Location item base
            LEFT JOIN location_item_overrides lio 
                ON lio.menu_item_id = mi.id AND lio.location_id = p_location_id
            -- Level 4: Location + Menu override
            LEFT JOIN location_menu_item_overrides lmio 
                ON lmio.menu_item_id = mi.id 
                AND lmio.menu_id = p_menu_id 
                AND lmio.location_id = p_location_id
            WHERE mim.menu_id = m.id
        ),
        
        'menu_schedules', (
            SELECT COALESCE(json_agg(
                json_build_object(
                    'id', ms.id,
                    'schedule', json_build_object(
                        'id', s.id,
                        'name', s.name,
                        'description', s.description,
                        'is_active', s.is_active,
                        'schedule_time_slots', (
                            SELECT COALESCE(json_agg(
                                json_build_object(
                                    'id', sts.id,
                                    'day_of_week', sts.day_of_week,
                                    'start_time', sts.start_time,
                                    'end_time', sts.end_time
                                )
                            ), '[]'::json)
                            FROM schedule_time_slots sts
                            WHERE sts.schedule_id = s.id
                        )
                    )
                )
            ), '[]'::json)
            FROM menu_schedules ms
            JOIN schedules s ON s.id = ms.schedule_id
            WHERE ms.menu_id = m.id
        )
    ) INTO result
    FROM menus m
    WHERE m.id = p_menu_id;
    
    RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_menu_for_location"("p_menu_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_menu_item_details"("p_item_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN (
        SELECT json_build_object(
            'id', mi.id,
            'name', mi.name,
            'description', mi.description,
            'image', mi.image,
            'meal_types', mi.meal_types,
            'allergens', mi.allergens,
            'card_bg_color', mi.card_bg_color,
            'stock_tracking_mode', mi.stock_tracking_mode,

            -- Level 1: Global Base
            'base_price', mi.price,
            'base_cash_price', mi.cash_price,
            'base_delivery_price', mi.delivery_price,
            'base_availability', mi.availability,

            -- Level 2: Location Override
            'location_override', CASE
                WHEN lio.id IS NOT NULL THEN json_build_object(
                    'id', lio.id,
                    'custom_price', lio.custom_price,
                    'custom_cash_price', lio.custom_cash_price,
                    'custom_delivery_price', lio.custom_delivery_price,
                    'price_modifier', lio.price_modifier,
                    'price_modifier_type', lio.price_modifier_type,
                    'is_available', lio.is_available,
                    'stock_tracking_mode', lio.stock_tracking_mode,
                    'current_stock', lio.current_stock,
                    'is_popular', lio.is_popular
                )
                ELSE NULL
            END,

            -- Effective Values (Computed)
            'effective_price', COALESCE(lio.custom_price, mi.price),
            'effective_cash_price', COALESCE(lio.custom_cash_price, mi.cash_price),
            'effective_delivery_price', COALESCE(lio.custom_delivery_price, mi.delivery_price),
            'effective_availability', COALESCE(lio.is_available, mi.availability),

            -- UI Flags
            'has_location_override', (lio.id IS NOT NULL),
            'price_source', CASE
                WHEN lio.custom_price IS NOT NULL THEN 'location_override'
                ELSE 'base'
            END,

            -- Modifiers
            'modifier_groups', (
                SELECT COALESCE(json_agg(
                    json_build_object(
                        'id', mg.id,
                        'name', mg.name,
                        'description', mg.description,
                        'min_selections', mg.min_selections,
                        'max_selections', mg.max_selections,
                        'is_required', mg.is_required,
                        'is_active', COALESCE(lmgo.is_active, true),
                        'items', (
                            SELECT COALESCE(json_agg(
                                json_build_object(
                                    'id', mgi.id,
                                    'name', mgi.name,
                                    'description', mgi.description,
                                    'price_modifier', COALESCE(lmio_mod.price_modifier, mgi.price_modifier),
                                    'is_active', (mgi.is_active = true AND COALESCE(lmio_mod.is_active, true) = true),
                                    'stock_tracking_mode', COALESCE(lmio_mod.stock_tracking_mode, 'in_stock'),
                                    'current_stock', lmio_mod.current_stock
                                ) ORDER BY mgi.name ASC
                            ), '[]'::json)
                            FROM modifier_group_items mgi
                            LEFT JOIN location_modifier_item_overrides lmio_mod
                                ON lmio_mod.modifier_group_item_id = mgi.id
                                AND lmio_mod.location_id = p_location_id
                            WHERE mgi.modifier_group_id = mg.id
                        )
                    ) ORDER BY mg.name ASC
                ), '[]'::json)
                FROM menu_item_modifier_groups mimg
                JOIN modifier_groups mg ON mg.id = mimg.modifier_group_id
                LEFT JOIN location_modifier_group_overrides lmgo
                    ON lmgo.modifier_group_id = mg.id
                    AND lmgo.location_id = p_location_id
                WHERE mimg.menu_item_id = mi.id
            ),

            -- Categories (fixed: was menu_item_categories, now category_items)
            'categories', (
                SELECT COALESCE(json_agg(
                    json_build_object('id', c.id, 'name', c.name)
                ), '[]'::json)
                FROM category_items ci
                JOIN categories c ON c.id = ci.category_id
                WHERE ci.menu_item_id = mi.id
            ),

            -- Menus
            'menus', (
                SELECT COALESCE(json_agg(
                    json_build_object(
                        'id', m.id,
                        'name', m.name,
                        'is_active', m.is_active,
                        'is_global', (m.location_id IS NULL),
                        'location_id', m.location_id
                    ) ORDER BY m.name ASC
                ), '[]'::json)
                FROM menu_item_menus mim
                JOIN menus m ON m.id = mim.menu_id
                WHERE mim.menu_item_id = mi.id
            ),

            'menu_count', (
                SELECT COUNT(*)
                FROM menu_item_menus mim
                WHERE mim.menu_item_id = mi.id
            )
        )
        FROM menu_items mi
        LEFT JOIN location_item_overrides lio
            ON lio.menu_item_id = mi.id AND lio.location_id = p_location_id
        WHERE mi.id = p_item_id
    );
END;
$$;


ALTER FUNCTION "public"."get_menu_item_details"("p_item_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_menu_with_categories"("p_menu_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    result JSON;
BEGIN
    SELECT json_build_object(
        'id', m.id,
        'merchant_id', m.merchant_id,
        'location_id', m.location_id,
        'name', m.name,
        'description', m.description,
        'is_active', m.is_active,
        'is_global', (m.location_id IS NULL),
        'is_location_owned', (m.location_id IS NOT NULL),
        'created_at', m.created_at,
        'updated_at', m.updated_at,

        -- Categories with items (Uber Eats / DoorDash style)
        'categories', (
            SELECT COALESCE(json_agg(
                json_build_object(
                    'id', mc.id,
                    'category_id', c.id,
                    'display_order', COALESCE(
                        lmco.display_order,
                        lco.display_order,
                        mc.display_order
                    ),
                    'is_active', COALESCE(
                        lmco.is_active,
                        lco.is_active,
                        mc.is_active,
                        true
                    ),

                    'category', json_build_object(
                        'id', c.id,
                        'name', COALESCE(lmco.custom_title, mc.custom_title, c.name),
                        'description', c.description,
                        'image', COALESCE(mc.custom_image, c.image),
                        'has_location_override', (lco.id IS NOT NULL),
                        'has_menu_category_override', (lmco.id IS NOT NULL),
                        'location_id', c.location_id
                    ),

                    -- Items in this category on this menu
                    'items', (
                        SELECT COALESCE(json_agg(
                            json_build_object(
                                'id', ci.id,
                                'menu_item_id', mi.id,
                                'category_id', c.id,
                                'display_order', COALESCE(lcio.display_order, ci.display_order),
                                'is_featured', COALESCE(lcio.is_featured, ci.is_featured),

                                'menu_item', json_build_object(
                                    'id', mi.id,
                                    'name', mi.name,
                                    'description', mi.description,
                                    'image', mi.image,
                                    'allergens', mi.allergens,
                                    'meal_types', mi.meal_types,
                                    'card_bg_color', mi.card_bg_color,

                                    -- ============================================
                                    -- PRICE BREAKDOWN (All Levels)
                                    -- ============================================
                                    'price_levels', json_build_object(
                                        'level_1_base', mi.price,
                                        'level_2_location_item', lio.custom_price,
                                        'level_2_modifier', lio.price_modifier,
                                        'level_2_modifier_type', lio.price_modifier_type,
                                        'level_3_category', ci.custom_price,
                                        'level_4_location_category', lcio.custom_price,
                                        'level_5_location_menu', lmio.custom_price,
                                        'level_1_delivery', mi.delivery_price,
                                        'level_2_location_item_delivery', lio.custom_delivery_price,
                                        'level_3_category_delivery', ci.custom_delivery_price,
                                        'level_4_location_category_delivery', lcio.custom_delivery_price,
                                        'level_5_location_menu_delivery', lmio.custom_delivery_price
                                    ),

                                    -- ============================================
                                    -- EFFECTIVE PRICE (Full Cascade)
                                    -- L5 > L4 > L3 > L2 > L1
                                    -- ============================================
                                    'effective_price', CASE
                                        -- Location-owned menu: simplified cascade
                                        WHEN m.location_id IS NOT NULL THEN
                                            COALESCE(
                                                ci.custom_price,
                                                mi.price
                                            )
                                        -- Global menu with location context
                                        ELSE COALESCE(
                                            lmio.custom_price,                    -- L5: Location + Menu
                                            lcio.custom_price,                    -- L4: Location + Category
                                            ci.custom_price,                      -- L3: Category
                                            -- L2 with modifier logic
                                            CASE
                                                WHEN lio.price_modifier_type = 'add'
                                                     AND lio.price_modifier IS NOT NULL
                                                THEN mi.price + lio.price_modifier
                                                WHEN lio.price_modifier_type = 'percent'
                                                     AND lio.price_modifier IS NOT NULL
                                                THEN mi.price * (1 + lio.price_modifier / 100)
                                                WHEN lio.custom_price IS NOT NULL
                                                THEN lio.custom_price
                                                ELSE NULL
                                            END,
                                            mi.price                              -- L1: Base
                                        )
                                    END,

                                    'effective_cash_price', CASE
                                        WHEN m.location_id IS NOT NULL THEN
                                            COALESCE(ci.custom_cash_price, mi.cash_price)
                                        ELSE COALESCE(
                                            lmio.custom_cash_price,
                                            lcio.custom_cash_price,
                                            ci.custom_cash_price,
                                            lio.custom_cash_price,
                                            mi.cash_price
                                        )
                                    END,

                                    'effective_delivery_price', CASE
                                        WHEN m.location_id IS NOT NULL THEN
                                            COALESCE(ci.custom_delivery_price, mi.delivery_price)
                                        ELSE COALESCE(
                                            lmio.custom_delivery_price,
                                            lcio.custom_delivery_price,
                                            ci.custom_delivery_price,
                                            lio.custom_delivery_price,
                                            mi.delivery_price
                                        )
                                    END,

                                    -- ============================================
                                    -- AVAILABILITY (AND Logic through all levels)
                                    -- ============================================
                                    'effective_availability', (
                                        mi.availability = true                           -- L1
                                        AND COALESCE(lio.is_available, true) = true      -- L2
                                        AND COALESCE(ci.is_available, true) = true       -- L3
                                        AND COALESCE(lcio.is_available, true) = true     -- L4
                                        AND COALESCE(lmio.is_available, true) = true     -- L5
                                    ),

                                    -- Item badges (location-specific)
                                    -- is_new: stored per-branch in location_item_overrides
                                    'is_new', COALESCE(lio.is_new, false),
                                    'is_popular', (
                                    COALESCE(lio.is_popular, false)
                                    OR (
                                        p_location_id IS NOT NULL
                                        AND (
                                            SELECT COUNT(*) >= 10
                                            FROM order_items oi
                                            JOIN orders o ON o.id = oi.order_id
                                            WHERE oi.menu_item_id = mi.id
                                              AND o.location_id = p_location_id
                                              AND o.status = 'completed'
                                              AND o.completed_at > NOW() - INTERVAL '30 days'
                                              AND oi.is_voided = false
                                        )
                                    )
                                ),

                                    -- Price source indicator for UI
                                    'price_source', CASE
                                        WHEN lmio.custom_price IS NOT NULL THEN 'location_menu'
                                        WHEN lcio.custom_price IS NOT NULL THEN 'location_category'
                                        WHEN ci.custom_price IS NOT NULL THEN 'category'
                                        WHEN lio.custom_price IS NOT NULL OR lio.price_modifier IS NOT NULL
                                            THEN 'location_item'
                                        ELSE 'base'
                                    END,

                                    -- Override flags for UI
                                    'has_location_item_override', (lio.id IS NOT NULL),
                                    'has_category_override', (ci.custom_price IS NOT NULL),
                                    'has_location_category_override', (lcio.id IS NOT NULL),
                                    'has_location_menu_override', (lmio.id IS NOT NULL),

                                    -- Stock info
                                    'stock_tracking_mode', COALESCE(
                                        NULLIF(lio.stock_tracking_mode, 'use_default'),
                                        mi.stock_tracking_mode
                                    ),
                                    'current_stock', lio.current_stock,

                                    -- Modifiers (with location overrides)
                                    'modifier_groups', (
                                        SELECT COALESCE(json_agg(
                                            json_build_object(
                                                'id', mg.id,
                                                'name', mg.name,
                                                'min_selections', mg.min_selections,
                                                'max_selections', mg.max_selections,
                                                'is_required', mg.is_required,
                                                'is_active', COALESCE(lmgo.is_active, true),

                                                'items', (
                                                    SELECT COALESCE(json_agg(
                                                        json_build_object(
                                                            'id', mgi.id,
                                                            'name', mgi.name,
                                                            'price_modifier', COALESCE(
                                                                lmio_mod.price_modifier,
                                                                mgi.price_modifier
                                                            ),
                                                            'is_active', (
                                                                mgi.is_active = true
                                                                AND COALESCE(lmio_mod.is_active, true) = true
                                                            ),
                                                            'stock_tracking_mode', COALESCE(
                                                                lmio_mod.stock_tracking_mode,
                                                                'in_stock'
                                                            ),
                                                            'current_stock', lmio_mod.current_stock
                                                        ) ORDER BY mgi.display_order, mgi.name
                                                    ), '[]'::json)
                                                    FROM modifier_group_items mgi
                                                    LEFT JOIN location_modifier_item_overrides lmio_mod
                                                        ON lmio_mod.modifier_group_item_id = mgi.id
                                                        AND lmio_mod.location_id = p_location_id
                                                    WHERE mgi.modifier_group_id = mg.id
                                                )
                                            ) ORDER BY mg.display_order, mg.name
                                        ), '[]'::json)
                                        FROM menu_item_modifier_groups mimg
                                        JOIN modifier_groups mg ON mg.id = mimg.modifier_group_id
                                        LEFT JOIN location_modifier_group_overrides lmgo
                                            ON lmgo.modifier_group_id = mg.id
                                            AND lmgo.location_id = p_location_id
                                        WHERE mimg.menu_item_id = mi.id
                                    )
                                )
                            ) ORDER BY COALESCE(lcio.display_order, ci.display_order)
                        ), '[]'::json)
                        FROM category_items ci
                        JOIN menu_items mi ON mi.id = ci.menu_item_id
                        -- L2: Location item override
                        LEFT JOIN location_item_overrides lio
                            ON lio.menu_item_id = mi.id
                            AND lio.location_id = p_location_id
                        -- L4: Location + Category override
                        LEFT JOIN location_category_item_overrides lcio
                            ON lcio.menu_item_id = mi.id
                            AND lcio.category_id = c.id
                            AND lcio.location_id = p_location_id
                        -- L5: Location + Menu override
                        LEFT JOIN location_menu_item_overrides lmio
                            ON lmio.menu_item_id = mi.id
                            AND lmio.menu_id = m.id
                            AND lmio.category_id = c.id
                            AND lmio.location_id = p_location_id
                        WHERE ci.category_id = c.id
                        -- Removed: AND COALESCE(ci.is_available, true) = true
                        -- Sold-out items now pass through with effective_availability = false
                        -- so the storefront can render them grayed out with a "Sold Out" label.
                    )
                ) ORDER BY COALESCE(lmco.display_order, lco.display_order, mc.display_order)
            ), '[]'::json)
            FROM menu_categories mc
            JOIN categories c ON c.id = mc.category_id
            LEFT JOIN location_category_overrides lco
                ON lco.category_id = c.id
                AND lco.location_id = p_location_id
            LEFT JOIN location_menu_category_overrides lmco
                ON lmco.category_id = c.id
                AND lmco.menu_id = m.id
                AND lmco.location_id = p_location_id
            WHERE mc.menu_id = m.id
              AND COALESCE(lmco.is_active, lco.is_active, mc.is_active, true) = true
        ),

        -- Schedules
        'schedules', (
            SELECT COALESCE(json_agg(
                json_build_object(
                    'id', ms.id,
                    'schedule', json_build_object(
                        'id', s.id,
                        'name', s.name,
                        'description', s.description,
                        'is_active', s.is_active,
                        'time_slots', (
                            SELECT COALESCE(json_agg(
                                json_build_object(
                                    'id', sts.id,
                                    'day_of_week', sts.day_of_week,
                                    'start_time', sts.start_time,
                                    'end_time', sts.end_time
                                )
                            ), '[]'::json)
                            FROM schedule_time_slots sts
                            WHERE sts.schedule_id = s.id
                        )
                    )
                )
            ), '[]'::json)
            FROM menu_schedules ms
            JOIN schedules s ON s.id = ms.schedule_id
            WHERE ms.menu_id = m.id
        )
    ) INTO result
    FROM menus m
    WHERE m.id = p_menu_id;

    RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_menu_with_categories"("p_menu_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_merchant_acquisition"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("period" "text", "new_merchants" bigint, "new_locations" bigint)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    TO_CHAR(DATE_TRUNC('week', m.created_at)::DATE, 'YYYY-MM-DD') as period,
    COUNT(DISTINCT m.id)::BIGINT as new_merchants,
    COUNT(DISTINCT l.id)::BIGINT as new_locations
  FROM merchants m
  LEFT JOIN locations l ON l.merchant_id = m.id AND l.created_at >= p_from AND l.created_at < p_to
  WHERE m.created_at >= p_from AND m.created_at < p_to
  GROUP BY DATE_TRUNC('week', m.created_at)
  ORDER BY period;
END;
$$;


ALTER FUNCTION "public"."get_merchant_acquisition"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_merchant_retention"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("retained" bigint, "churned" bigint, "new_merchants" bigint, "retention_rate" numeric)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_window_days INT;
  v_prev_start  TIMESTAMPTZ;
  v_prev_end    TIMESTAMPTZ;
BEGIN
  -- Calculate window size
  v_window_days := EXTRACT(DAY FROM (p_to - p_from));
  v_prev_start  := p_from - (v_window_days || ' days')::INTERVAL;
  v_prev_end    := p_from;

  RETURN QUERY
  WITH current_active AS (
    SELECT DISTINCT merchant_id
    FROM orders
    WHERE created_at >= p_from
      AND created_at < p_to
  ),
  previous_active AS (
    SELECT DISTINCT merchant_id
    FROM orders
    WHERE created_at >= v_prev_start
      AND created_at < v_prev_end
  ),
  new_merchants_cte AS (
    SELECT COUNT(*)::BIGINT AS cnt
    FROM merchants
    WHERE created_at >= p_from
      AND created_at < p_to
  )

  SELECT
    -- Retained = active in both periods
    COUNT(DISTINCT pa.merchant_id)
      FILTER (WHERE ca.merchant_id IS NOT NULL)::BIGINT AS retained,

    -- Churned = active before but not now
    COUNT(DISTINCT pa.merchant_id)
      FILTER (WHERE ca.merchant_id IS NULL)::BIGINT AS churned,

    -- Newly created merchants in current window
    (SELECT cnt FROM new_merchants_cte) AS new_merchants,

    -- Retention %
    CASE
      WHEN COUNT(DISTINCT pa.merchant_id) > 0 THEN
        (
          COUNT(DISTINCT pa.merchant_id)
          FILTER (WHERE ca.merchant_id IS NOT NULL)::NUMERIC
          / COUNT(DISTINCT pa.merchant_id)
        * 100
        )::NUMERIC(5,2)
      ELSE 0::NUMERIC
    END AS retention_rate

  FROM previous_active pa
  LEFT JOIN current_active ca
    ON pa.merchant_id = ca.merchant_id;

END;
$$;


ALTER FUNCTION "public"."get_merchant_retention"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_carrier_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT id FROM public.carriers WHERE clerk_org_id = get_my_claim('org_id');
$$;


