CREATE OR REPLACE FUNCTION "public"."get_my_hq_role"() RETURNS TABLE("role_code" "text", "role_name" "text", "level" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$DECLARE
  v_user_id text;
BEGIN
  v_user_id := current_user_id();
  IF v_user_id IS NULL OR NOT is_dexapos_admin() THEN
    RETURN;
  END IF;

  -- RETURN QUERY
  -- SELECT r.code, r.name, r.level
  -- FROM user_roles ur
  -- JOIN roles r ON r.code = ur.role_code
  -- WHERE ur.user_id = v_user_id
  -- AND r.organization_type = 'hq'
  -- ORDER BY r.level DESC
  -- LIMIT 1;
   -- Query from members table joined with roles
  RETURN QUERY
  SELECT r.code, r.name, r.level
  FROM members m
  JOIN roles r ON r.code = m.role
  WHERE m.user_id = v_user_id
    AND r.organization_type = 'hq'
  ORDER BY r.level DESC
  LIMIT 1;
END;$$;


