CREATE OR REPLACE FUNCTION "public"."get_onboarding_funnel"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("stage" "text", "merchant_count" bigint)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  WITH created_merchants AS (
    SELECT COUNT(DISTINCT id)::BIGINT as cnt FROM merchants WHERE created_at >= p_from AND created_at < p_to
  ),
  with_menu AS (
    SELECT COUNT(DISTINCT m.id)::BIGINT as cnt
    FROM merchants m
    WHERE m.created_at >= p_from AND m.created_at < p_to
      AND EXISTS (SELECT 1 FROM menu_items mi WHERE mi.merchant_id = m.id LIMIT 1)
  ),
  with_staff AS (
    SELECT COUNT(DISTINCT m.id)::BIGINT as cnt
    FROM merchants m
    WHERE m.created_at >= p_from AND m.created_at < p_to
      AND EXISTS (SELECT 1 FROM staff_profiles sp WHERE sp.merchant_id = m.id LIMIT 1)
  ),
  with_first_order AS (
    SELECT COUNT(DISTINCT m.id)::BIGINT as cnt
    FROM merchants m
    WHERE m.created_at >= p_from AND m.created_at < p_to
      AND EXISTS (SELECT 1 FROM orders o WHERE o.merchant_id = m.id LIMIT 1)
  ),
  steady_state AS (
    SELECT COUNT(DISTINCT merchant_id)::BIGINT as cnt
    FROM (
      SELECT o.merchant_id
      FROM orders o
      WHERE o.created_at >= p_from AND o.created_at < p_to
      GROUP BY o.merchant_id
      HAVING COUNT(*) >= 5
    ) subq
  )
  SELECT 'Merchant Created' as stage, (SELECT cnt FROM created_merchants) as merchant_count
  UNION ALL
  SELECT 'Menu Setup', (SELECT cnt FROM with_menu)
  UNION ALL
  SELECT 'Staff Added', (SELECT cnt FROM with_staff)
  UNION ALL
  SELECT 'First Order', (SELECT cnt FROM with_first_order)
  UNION ALL
  SELECT 'Steady State (5+ orders)', (SELECT cnt FROM steady_state);
END;
$$;


ALTER FUNCTION "public"."get_onboarding_funnel"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_order_courses"("p_order_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN (
    SELECT json_build_object(
      'order_id', p_order_id,
      'courses', COALESCE(
        (
          SELECT json_agg(
            json_build_object(
              'course_number', oc.course_number,
              'status', oc.status,
              'created_at', oc.created_at,
              'fired_at', oc.fired_at,
              'served_at', oc.served_at,
              'item_count', (
                SELECT COUNT(*) FROM public.order_items oi
                WHERE oi.order_id = p_order_id 
                  AND oi.course_number = oc.course_number
                  AND oi.is_voided = FALSE
              ),
              'items', (
                SELECT json_agg(
                  json_build_object(
                    'id', oi.id,
                    'item_name', oi.item_name,
                    'quantity', oi.quantity,
                    'subtotal', oi.subtotal
                  )
                )
                FROM public.order_items oi
                WHERE oi.order_id = p_order_id 
                  AND oi.course_number = oc.course_number
                  AND oi.is_voided = FALSE
              )
            ) ORDER BY oc.course_number
          )
          FROM public.order_courses oc
          WHERE oc.order_id = p_order_id
        ),
        '[]'::json
      ),
      'working_course', (
        SELECT ts.working_course 
        FROM public.table_sessions ts 
        WHERE ts.order_id = p_order_id AND ts.is_active = TRUE
      ),
      'highest_course', (
        SELECT COALESCE(MAX(course_number), 0)
        FROM public.order_items
        WHERE order_id = p_order_id AND is_voided = FALSE
      )
    )
    FROM public.orders o
    WHERE o.id = p_order_id
      AND o.merchant_id = user_merchant_id()
      AND o.location_id = ANY(user_location_ids())
  );
END;
$$;


ALTER FUNCTION "public"."get_order_courses"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_order_details"("p_order_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_result JSON;
  v_station_name TEXT;
BEGIN
  -- Verify user has access
  IF NOT EXISTS (
    SELECT 1 FROM public.orders
    WHERE id = p_order_id
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids())
  ) THEN
    RAISE EXCEPTION 'Order not found or access denied';
  END IF;
  
  -- Get station name for this order
  SELECT s.station_name INTO v_station_name
  FROM public.orders o
  LEFT JOIN public.stations s ON s.id = o.station_id
  WHERE o.id = p_order_id;

  SELECT json_build_object(
    'order', row_to_json(o.*),
    'station_name', v_station_name,
    'items', (
      SELECT COALESCE(json_agg(
        json_build_object(
          'item', row_to_json(oi.*),
          'modifiers', (
            SELECT COALESCE(json_agg(row_to_json(oim.*)), '[]'::json)
            FROM public.order_item_modifiers oim
            WHERE oim.order_item_id = oi.id
          )
        )
        ORDER BY oi.display_order ASC NULLS LAST, oi.created_at ASC
      ), '[]'::json)
      FROM public.order_items oi
      WHERE oi.order_id = o.id
        AND oi.is_voided = FALSE
    ),
    'payments', (
      SELECT COALESCE(json_agg(row_to_json(op.*)), '[]'::json)
      FROM public.order_payments op
      WHERE op.order_id = o.id
    ),
     'payment_items', (
      SELECT COALESCE(json_agg(row_to_json(opi.*)), '[]'::json)
      FROM public.order_payment_items opi
      JOIN public.order_payments op ON op.id = opi.order_payment_id
      WHERE op.order_id = o.id
    ),
    'reversals', (
      SELECT COALESCE(json_agg(row_to_json(r.*)), '[]'::json)
      FROM public.reversals r
      JOIN public.order_payments op ON op.id = r.original_payment_id
      WHERE op.order_id = o.id
    ),
    'order_refund_items', (
      SELECT COALESCE(json_agg(row_to_json(ori.*)), '[]'::json)
      FROM public.order_refund_items ori
      JOIN public.order_items oi ON oi.id = ori.order_item_id
      WHERE oi.order_id = o.id
    ),
    'status_history', (
      SELECT COALESCE(json_agg(row_to_json(osh.*) ORDER BY osh.changed_at), '[]'::json)
      FROM public.order_status_history osh
      WHERE osh.order_id = o.id
    ),
    'order_discounts', (
      SELECT COALESCE(json_agg(row_to_json(od.*) ORDER BY od.applied_at), '[]'::json)
      FROM public.order_discounts od
      WHERE od.order_id = o.id
        AND od.voided_at IS NULL
    )
  )
  INTO v_result
  FROM public.orders o
  WHERE o.id = p_order_id;
  
  RETURN v_result;
END;$$;


ALTER FUNCTION "public"."get_order_details"("p_order_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_order_details"("p_order_id" "uuid") IS 'Returns complete order details - requires location.orders.view or merchant.orders.view permission';



CREATE OR REPLACE FUNCTION "public"."get_order_flow_stats"("p_merchant_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_start_date" timestamp with time zone DEFAULT ("now"() - '7 days'::interval), "p_end_date" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  -- Base: all orders in the date range
  WITH all_orders AS (
    SELECT
      o.id,
      o.status::text as status,
      o.total_amount,
      o.created_at,
      o.completed_at,
      o.order_type,
      o.voided_by,
      o.void_reason,
      sp_voided.first_name || ' ' || sp_voided.last_name as voided_by_staff
    FROM orders o
    LEFT JOIN staff_profiles sp_voided ON o.voided_by = sp_voided.id
    WHERE o.merchant_id = p_merchant_id
      AND (p_location_id IS NULL OR o.location_id = p_location_id)
      AND o.created_at >= p_start_date
      AND o.created_at <= p_end_date
  ),

  -- Funnel stages: count orders at each status
  funnel_counts AS (
    SELECT
      status,
      CASE
        WHEN status = 'pending' THEN 'Pending'
        WHEN status = 'sent_to_kitchen' THEN 'Sent to Kitchen'
        WHEN status = 'preparing' THEN 'Preparing'
        WHEN status = 'ready' THEN 'Ready'
        WHEN status = 'completed' THEN 'Completed'
        WHEN status = 'cancelled' THEN 'Cancelled'
        WHEN status = 'refunded' THEN 'Refunded'
        WHEN status = 'void' THEN 'Void'
        WHEN status = 'draft' THEN 'Draft'
        ELSE status
      END as label,
      CASE
        WHEN status = 'draft' THEN 0
        WHEN status = 'pending' THEN 1
        WHEN status = 'sent_to_kitchen' THEN 2
        WHEN status = 'preparing' THEN 3
        WHEN status = 'ready' THEN 4
        WHEN status = 'completed' THEN 5
        WHEN status = 'cancelled' THEN 6
        WHEN status = 'refunded' THEN 7
        WHEN status = 'void' THEN 8
        ELSE 99
      END as sort_order,
      COUNT(*) as count_val
    FROM all_orders
    GROUP BY status
  ),

  -- Top voided items
  top_voided_items_calc AS (
    SELECT
      mi.name as item_name,
      COUNT(*) as void_count,
      COALESCE(SUM(oi.unit_price * oi.quantity), 0) as void_amount
    FROM all_orders ao
    LEFT JOIN order_items oi ON ao.id = oi.order_id
    LEFT JOIN menu_items mi ON oi.menu_item_id = mi.id
    WHERE ao.status = 'void'
      AND oi.id IS NOT NULL
    GROUP BY mi.name
    ORDER BY void_count DESC
    LIMIT 10
  ),

  -- Staff void stats
  staff_void_stats_calc AS (
    SELECT
      COALESCE(ao.voided_by_staff, 'Unknown') as staff_name,
      COUNT(*) as void_count,
      COALESCE(SUM(ao.total_amount), 0) as void_amount
    FROM all_orders ao
    WHERE ao.status = 'void'
      AND ao.voided_by IS NOT NULL
    GROUP BY ao.voided_by_staff
    ORDER BY void_count DESC
  ),

  -- Refund reason breakdown
  refund_reason_calc AS (
    SELECT
      COALESCE(op.refund_reason, 'No reason provided') as reason,
      COUNT(*) as count_val,
      COALESCE(SUM(op.refunded_amount), 0) as total_amount
    FROM all_orders ao
    LEFT JOIN order_payments op ON ao.id = op.order_id
    WHERE ao.status = 'refunded'
      AND op.is_returned = true
    GROUP BY op.refund_reason
    ORDER BY count_val DESC
  ),

  -- Order type breakdown
  order_type_stats_calc AS (
    SELECT
      ao.order_type as order_type_val,
      COUNT(*) as count_val,
      COALESCE(SUM(ao.total_amount), 0) as total_rev,
      COALESCE(AVG(ao.total_amount), 0) as avg_val
    FROM all_orders ao
    WHERE ao.order_type IS NOT NULL
    GROUP BY ao.order_type
  ),

  -- Completion time per order type
  completion_time_calc AS (
    SELECT
      ao.order_type as order_type_val,
      AVG(EXTRACT(EPOCH FROM (ao.completed_at - ao.created_at)) / 60) as avg_min,
      MIN(EXTRACT(EPOCH FROM (ao.completed_at - ao.created_at)) / 60) as min_min,
      MAX(EXTRACT(EPOCH FROM (ao.completed_at - ao.created_at)) / 60) as max_min,
      COUNT(*) as count_val
    FROM all_orders ao
    WHERE ao.completed_at IS NOT NULL
      AND ao.order_type IS NOT NULL
    GROUP BY ao.order_type
  ),

  -- Aggregates
  order_totals AS (
    SELECT
      COUNT(*) as total_orders,
      COUNT(CASE WHEN status = 'completed' THEN 1 END) as completed_count,
      COUNT(CASE WHEN status = 'cancelled' THEN 1 END) as cancelled_count,
      COUNT(CASE WHEN status = 'void' THEN 1 END) as void_count
    FROM all_orders
  )

  SELECT jsonb_build_object(
    'total_orders', (SELECT total_orders FROM order_totals),

    'completion_rate',
    CASE
      WHEN (SELECT total_orders FROM order_totals) > 0
      THEN ROUND(((SELECT completed_count FROM order_totals)::numeric / (SELECT total_orders FROM order_totals) * 100)::numeric, 2)
      ELSE 0
    END,

    'cancellation_rate',
    CASE
      WHEN (SELECT total_orders FROM order_totals) > 0
      THEN ROUND(((SELECT cancelled_count FROM order_totals)::numeric / (SELECT total_orders FROM order_totals) * 100)::numeric, 2)
      ELSE 0
    END,

    'void_rate',
    CASE
      WHEN (SELECT total_orders FROM order_totals) > 0
      THEN ROUND(((SELECT void_count FROM order_totals)::numeric / (SELECT total_orders FROM order_totals) * 100)::numeric, 2)
      ELSE 0
    END,

    'funnel',
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'status', fc.status,
        'label', fc.label,
        'count', fc.count_val,
        'pct_of_total', ROUND((fc.count_val::numeric / (SELECT total_orders FROM order_totals) * 100)::numeric, 2)
      ) ORDER BY fc.sort_order)
      FROM funnel_counts fc
    ), '[]'::jsonb),

    'void_refund',
    jsonb_build_object(
      'total_voids', (SELECT COUNT(*) FROM all_orders WHERE status = 'void'),
      'void_amount', (SELECT COALESCE(SUM(total_amount), 0) FROM all_orders WHERE status = 'void'),
      'total_refunds', (SELECT COUNT(*) FROM all_orders WHERE status = 'refunded'),
      'refund_amount', (SELECT COALESCE(SUM(total_amount), 0) FROM all_orders WHERE status = 'refunded'),
      'by_reason', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'reason', frc.reason,
          'count', frc.count_val,
          'total_amount', ROUND(COALESCE(frc.total_amount, 0)::numeric, 2)
        ))
        FROM refund_reason_calc frc
      ), '[]'::jsonb),
      'top_voided_items', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'item_name', tvi.item_name,
          'void_count', tvi.void_count,
          'void_amount', ROUND(COALESCE(tvi.void_amount, 0)::numeric, 2)
        ))
        FROM top_voided_items_calc tvi
      ), '[]'::jsonb),
      'staff_voids', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'staff_id', ''::text,
          'staff_name', svs.staff_name,
          'void_count', svs.void_count,
          'void_amount', ROUND(COALESCE(svs.void_amount, 0)::numeric, 2)
        ))
        FROM staff_void_stats_calc svs
      ), '[]'::jsonb)
    ),

    'order_types',
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'order_type', ots.order_type_val,
        'count', ots.count_val,
        'total_revenue', ROUND(COALESCE(ots.total_rev, 0)::numeric, 2),
        'avg_order_value', ROUND(COALESCE(ots.avg_val, 0)::numeric, 2),
        'pct_of_total', ROUND((ots.count_val::numeric / (SELECT total_orders FROM order_totals) * 100)::numeric, 2)
      ))
      FROM order_type_stats_calc ots
    ), '[]'::jsonb),

    'completion_times',
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'order_type', ctc.order_type_val,
        'avg_minutes', ROUND(COALESCE(ctc.avg_min, 0)::numeric, 2),
        'order_count', ctc.count_val,
        'min_minutes', ROUND(COALESCE(ctc.min_min, 0)::numeric, 2),
        'max_minutes', ROUND(COALESCE(ctc.max_min, 0)::numeric, 2)
      ))
      FROM completion_time_calc ctc
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_order_flow_stats"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_order_flow_stats"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) IS 'Comprehensive order flow analytics for a merchant/location over date range. Returns: funnel progression, void/refund analysis, order type breakdown, completion times. Aggregates from orders, order_items, menu_items, order_payments, staff_profiles.';



CREATE OR REPLACE FUNCTION "public"."get_order_item"("p_order_item_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_result JSON;
BEGIN
  SELECT json_build_object(
    'item', json_build_object(
      'id', oi.id,
      'order_id', oi.order_id,
      'menu_item_id', oi.menu_item_id,
      'location_exclusive_item_id', oi.location_exclusive_item_id,
      'item_name', oi.item_name,
      'item_description', oi.item_description,
      'category_name', oi.category_name,
      'quantity', oi.quantity,
      'unit_price', oi.unit_price,
      'cash_price', oi.cash_price,
      'price_paid', oi.price_paid,
      'subtotal', oi.subtotal,
      'selected_size_id', oi.selected_size_id,
      'selected_size_name', oi.selected_size_name,
      'size_price_modifier', oi.size_price_modifier,
      'special_instructions', oi.special_instructions,
      'item_status', oi.item_status,
      'prep_station', oi.prep_station,
      'course_number', oi.course_number,
      'is_voided', oi.is_voided,
      'created_at', oi.created_at,
      'updated_at', oi.updated_at
    ),
    'modifiers', (
      SELECT COALESCE(json_agg(
        json_build_object(
          'id', oim.id,
          'modifier_group_id', oim.modifier_group_id,
          'modifier_item_id', oim.modifier_item_id,
          'modifier_group_name', oim.modifier_group_name,
          'modifier_name', oim.modifier_name,
          'price_modifier', oim.price_modifier,
          'quantity', oim.quantity,
          'total_price', oim.total_price
        )
      ), '[]'::json)
      FROM public.order_item_modifiers oim
      WHERE oim.order_item_id = oi.id
    ),
    'modifier_total', (
      SELECT COALESCE(SUM(total_price), 0)
      FROM public.order_item_modifiers
      WHERE order_item_id = oi.id
    )
  )
  INTO v_result
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids());

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Order item not found';
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_order_item"("p_order_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organization_info"("p_organization_id" "text") RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_result json;
  v_org json;
  v_members json;
  v_pending_invites json;
  v_carriers json;
BEGIN
  -- Get organization details
  SELECT to_json(o.*)
  INTO v_org
  FROM organizations o
  WHERE o.id = p_organization_id;

  IF v_org IS NULL THEN
    RETURN json_build_object('error', 'Organization not found');
  END IF;

  -- Get members with user details
  SELECT COALESCE(json_agg(
    json_build_object(
      'id', m.id,
      'user_id', m.user_id,
      'organization_id', m.organization_id,
      'role', m.role,
      'staff_profile_id', m.staff_profile_id,
      'created_at', m.created_at,
      'updated_at', m.updated_at,
      'user', json_build_object(
        'id', u.id,
        'first_name', u.first_name,
        'last_name', u.last_name,
        'email', u.email,
        'avatar_url', u.avatar_url,
        'created_at', u.created_at
      )
    )
  ), '[]'::json)
  INTO v_members
  FROM members m
  LEFT JOIN users u ON u.id = m.user_id
  WHERE m.organization_id = p_organization_id;

  -- Get pending admin invites with both user references
  SELECT COALESCE(json_agg(
    json_build_object(
      'id', pai.id,
      'organization_id', pai.organization_id,
      'email', pai.email,
      'role', pai.role,
      'status', pai.status,
      'clerk_invite_id', pai.clerk_invite_id,
      'clerk_user_id', pai.clerk_user_id,
      'invited_by', pai.invited_by,
      'merchant_access', pai.merchant_access,
      'accepted_at', pai.accepted_at,
      'created_at', pai.created_at,
      'updated_at', pai.updated_at,
      'clerk_user', CASE 
        WHEN cu.id IS NOT NULL THEN json_build_object(
          'id', cu.id,
          'first_name', cu.first_name,
          'last_name', cu.last_name,
          'email', cu.email
        )
        ELSE NULL
      END,
      'invited_by_user', CASE 
        WHEN iu.id IS NOT NULL THEN json_build_object(
          'id', iu.id,
          'first_name', iu.first_name,
          'last_name', iu.last_name,
          'email', iu.email
        )
        ELSE NULL
      END
    )
  ), '[]'::json)
  INTO v_pending_invites
  FROM pending_org_admin_invites pai
  LEFT JOIN users cu ON cu.id = pai.clerk_user_id
  LEFT JOIN users iu ON iu.id = pai.invited_by
  WHERE pai.organization_id = p_organization_id;

  -- Get carriers with merchants (if applicable)
  -- SELECT COALESCE(json_agg(
  --   json_build_object(
  --     'id', c.id,
  --     'merchants', (
  --       SELECT COALESCE(json_agg(to_json(mer.*)), '[]'::json)
  --       FROM merchants mer
  --       WHERE mer.carrier_id = c.id
  --     )
  --   )
  -- ), '[]'::json)
  -- INTO v_carriers
  -- FROM carriers c
  -- WHERE c.organization_id = p_organization_id;

  -- Build final result
  v_result := v_org::jsonb || jsonb_build_object(
    'members', v_members,
    'pending_org_admin_invites', v_pending_invites,
    'carriers', v_carriers
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_organization_info"("p_organization_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_failure_rate_by_day"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("date" "date", "total_txns" bigint, "failed_txns" bigint, "failure_rate_pct" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    DATE(op.initiated_at) AS date,
    COUNT(*)::BIGINT AS total_txns,
    COUNT(*) FILTER (WHERE op.status IN ('failed', 'declined'))::BIGINT AS failed_txns,
    CASE
      WHEN COUNT(*) > 0
      THEN (
        COUNT(*) FILTER (WHERE op.status IN ('failed', 'declined'))::NUMERIC
        / COUNT(*) * 100
      )::NUMERIC(5,2)
      ELSE 0::NUMERIC
    END AS failure_rate_pct
  FROM order_payments op
  WHERE op.initiated_at >= p_from
    AND op.initiated_at < p_to
  GROUP BY DATE(op.initiated_at)
  ORDER BY date;
END;
$$;


