CREATE OR REPLACE FUNCTION "public"."get_payment_method_mix"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("payment_method" "text", "txn_count" bigint, "total_amount" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    op.payment_method::TEXT,
    COUNT(*)::BIGINT AS txn_count,
    COALESCE(SUM(op.total_amount), 0)::NUMERIC AS total_amount
  FROM order_payments op
  WHERE op.initiated_at >= p_from
    AND op.initiated_at < p_to
  GROUP BY op.payment_method
  ORDER BY txn_count DESC;
END;
$$;


