CREATE OR REPLACE FUNCTION "public"."get_payment_summary_stats"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("total_transactions" bigint, "total_failed" bigint, "overall_failure_rate" numeric, "total_chargebacks" bigint, "total_chargeback_amount" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::BIGINT AS total_transactions,

    COUNT(
      CASE WHEN op.status IN ('failed', 'declined') THEN 1 END
    )::BIGINT AS total_failed,

    CASE
      WHEN COUNT(*) > 0
      THEN ROUND(
        COUNT(CASE WHEN op.status IN ('failed', 'declined') THEN 1 END)::NUMERIC
        / COUNT(*) * 100,
        2
      )
      ELSE 0
    END AS overall_failure_rate,

    (
      SELECT COUNT(*)::BIGINT
      FROM chargebacks cb
      WHERE cb.received_at >= p_from
        AND cb.received_at < p_to
    ) AS total_chargebacks,

    (
      SELECT COALESCE(SUM(cb.amount), 0)
      FROM chargebacks cb
      WHERE cb.received_at >= p_from
        AND cb.received_at < p_to
    ) AS total_chargeback_amount

  FROM order_payments op
  WHERE op.initiated_at >= p_from
    AND op.initiated_at < p_to;

END;
$$;


ALTER FUNCTION "public"."get_payment_summary_stats"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_peak_hours_heatmap"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("day_of_week" integer, "hour" integer, "order_count" bigint)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    EXTRACT(DOW FROM o.created_at)::INT as day_of_week,
    EXTRACT(HOUR FROM o.created_at)::INT as hour,
    COUNT(*)::BIGINT as order_count
  FROM orders o
  WHERE o.created_at >= p_from AND o.created_at < p_to
  GROUP BY EXTRACT(DOW FROM o.created_at), EXTRACT(HOUR FROM o.created_at)
  ORDER BY day_of_week, hour;
END;
$$;


