CREATE OR REPLACE FUNCTION "public"."get_pos_full_sync"("p_location_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    result JSON;
BEGIN
    SELECT json_build_object(
        -- 1. Metadata about the sync
        'synced_at', NOW(),
        'location_id', p_location_id,
        
        -- 2. The Full Menu List (Deeply Resolved)
        'menus', (
            SELECT COALESCE(json_agg(
                -- We call the detailed function for each valid menu
                get_menu_with_categories(m.id, p_location_id)
                ORDER BY m.display_order NULLS LAST, m.name
            ), '[]'::json)
            FROM menus m
            WHERE m.merchant_id = (SELECT merchant_id FROM locations WHERE id = p_location_id)
            AND m.is_active = true
            -- LOGIC: Get Global Menus + Location Specific Menus
            AND (
                (m.location_id IS NULL) -- Global menus
                OR 
                (m.location_id = p_location_id) -- Menus specific to this location
            )
            -- Optional: Add logic here if you have a way to 'hide' global menus from specific locations
        )
    ) INTO result;

    RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_pos_full_sync"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pos_inventory_sync"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_merchant_id UUID;
    v_result JSONB;
BEGIN
    -- 1. Get Merchant ID from Location
    SELECT merchant_id INTO v_merchant_id
    FROM locations
    WHERE id = p_location_id;

    -- 2. Construct the JSON response
    SELECT jsonb_build_object(
        'vendors', (
            SELECT COALESCE(jsonb_agg(v.*), '[]'::jsonb)
            FROM (
                SELECT 
                    id, 
                    name, 
                    phone, 
                    email, 
                    EXISTS(SELECT 1 FROM location_vendors lv WHERE lv.vendor_id = vendors.id AND lv.location_id = p_location_id) as is_linked
                FROM vendors
                WHERE merchant_id = v_merchant_id
                AND (is_active = true OR is_active IS NULL)
                ORDER BY name
            ) v
        ),
        'menu_recipes', (
            SELECT COALESCE(jsonb_agg(mr.*), '[]'::jsonb)
            FROM (
                SELECT 
                    mir.menu_item_id,
                    mir.inventory_item_id,
                    mir.quantity_used
                FROM menu_item_recipes mir
                JOIN menu_items mi ON mir.menu_item_id = mi.id
                WHERE mi.merchant_id = v_merchant_id
                AND mi.availability = true
                -- Include Global Items OR Local Items for this location
                AND (mi.location_id IS NULL OR mi.location_id = p_location_id)
            ) mr
        ),
        'modifier_recipes', (
            SELECT COALESCE(jsonb_agg(modr.*), '[]'::jsonb)
            FROM (
                SELECT 
                    mgir.modifier_group_item_id,
                    mgir.inventory_item_id,
                    mgir.quantity_used
                FROM modifier_group_item_recipes mgir
                JOIN modifier_group_items mgi ON mgir.modifier_group_item_id = mgi.id
                JOIN modifier_groups mg ON mgi.modifier_group_id = mg.id
                WHERE mg.merchant_id = v_merchant_id
                -- mg.is_active does not exist on modifier_groups (only on items)
                AND mgi.is_active = true
                -- Include Global Groups OR Local Groups for this location
                AND (mg.location_id IS NULL OR mg.location_id = p_location_id)
            ) modr
        ),
        'inventory_items', (
            SELECT COALESCE(jsonb_agg(i.*), '[]'::jsonb)
            FROM (
                SELECT 
                    ii.id,
                    ii.name,
                    ii.sku,
                    ii.unit_type,
                    ii.category,
                    
                    -- Cost and Threshold calculations
                    get_effective_item_cost(p_location_id, ii.id, NULL) as cost,
                    get_effective_reorder_threshold(p_location_id, ii.id) as reorder_threshold,
                    
                    -- Metadata for UI Editing
                    ii.location_id,
                    (ii.location_id IS NULL) as is_global,
                    
                    -- Check for Overrides (Matches web logic: Override Table OR Location Vendor Pricing)
                    (
                        EXISTS (
                            SELECT 1 FROM location_inventory_overrides lio
                            WHERE lio.location_id = p_location_id
                            AND lio.inventory_item_id = ii.id
                            AND lio.custom_cost IS NOT NULL
                        ) OR 
                        EXISTS (
                            SELECT 1 FROM location_vendor_pricing lvp
                            WHERE lvp.location_id = p_location_id
                            AND lvp.inventory_item_id = ii.id
                        )
                    ) as has_cost_override,
                    
                    -- Real-time Stock Quantity
                    COALESCE(lis.stock_quantity, 0) as stock_quantity,
                    
                    ii.vendor_id,
                    ii.is_active
                FROM inventory_items ii
                LEFT JOIN location_inventory_stock lis 
                    ON ii.id = lis.inventory_item_id 
                    AND lis.location_id = p_location_id
                WHERE ii.merchant_id = v_merchant_id
                AND (ii.is_active = true OR ii.is_active IS NULL)
                AND (ii.location_id IS NULL OR ii.location_id = p_location_id) -- Global items + Local items
                ORDER BY ii.name
            ) i
        )
    ) INTO v_result;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_pos_inventory_sync"("p_location_id" "uuid") OWNER TO "postgres";


