CREATE OR REPLACE FUNCTION "public"."get_reservations"("p_location_id" "uuid", "p_date" "date" DEFAULT CURRENT_DATE, "p_include_cancelled" boolean DEFAULT false) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN (
    SELECT json_build_object(
      'date', p_date,
      'reservations', COALESCE(json_agg(
        json_build_object(
          'id', r.id,
          'confirmation_number', r.confirmation_number,
          'party_name', r.party_name,
          'party_size', r.party_size,
          'phone', r.phone,
          'email', r.email,
          'reservation_time', r.reservation_time,
          'duration_minutes', r.duration_minutes,
          'end_time', r.reservation_time + (r.duration_minutes || ' minutes')::INTERVAL,
          'status', r.status,
          'assigned_table_ids', r.assigned_table_ids,
          'assigned_tables', (
            SELECT json_agg(fpo.name)
            FROM public.floor_plan_objects fpo
            WHERE fpo.id = ANY(r.assigned_table_ids)
          ),
          'preferred_section', r.preferred_section,
          'seating_preference', r.seating_preference,
          'notes', r.notes,
          'special_requests', r.special_requests,
          'is_vip', r.is_vip,
          'source', r.source
        ) ORDER BY r.reservation_time
      ), '[]'::json),
      'summary', json_build_object(
        'total', COUNT(*),
        'confirmed', COUNT(*) FILTER (WHERE r.status = 'confirmed'),
        'pending', COUNT(*) FILTER (WHERE r.status = 'pending'),
        'total_covers', SUM(r.party_size)
      )
    )
    FROM public.reservations r
    WHERE r.location_id = p_location_id
      AND r.merchant_id = user_merchant_id()
      AND p_location_id = ANY(user_location_ids())
      AND r.reservation_date = p_date
      AND (p_include_cancelled OR r.status NOT IN ('cancelled', 'no_show'))
  );
END;
$$;


