CREATE OR REPLACE FUNCTION "public"."get_revenue_by_merchant"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("merchant_id" "uuid", "merchant_name" "text", "revenue" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    m.id,
    m.name,
    COALESCE(SUM(o.total_amount), 0)::NUMERIC as revenue
  FROM merchants m
  LEFT JOIN orders o ON o.merchant_id = m.id
    AND o.created_at >= p_from AND o.created_at < p_to
    AND o.status NOT IN ('draft', 'cancelled', 'void')
  GROUP BY m.id, m.name
  ORDER BY revenue DESC
  LIMIT 20;
END;
$$;


