CREATE OR REPLACE FUNCTION "public"."handle_shift_update_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_schedule_status text;
BEGIN
    -- Check if parent schedule is active
    SELECT status INTO v_schedule_status FROM schedules WHERE id = NEW.schedule_id;
    
    -- If schedule is draft, do nothing
    IF v_schedule_status != 'active' THEN RETURN NEW; END IF;

    -- CASE 1: Shift Assigned (Null -> User)
    IF OLD.employee_id IS NULL AND NEW.employee_id IS NOT NULL THEN
        INSERT INTO notifications (merchant_id, recipient_id, type, title, body, data)
        VALUES (NEW.merchant_id, NEW.employee_id, 'schedule_update', 
                'New Shift Assigned', 
                'You have been assigned a shift on ' || to_char(NEW.start_time, 'Mon DD') || ' at ' || to_char(NEW.start_time, 'HH:MI AM'),
                jsonb_build_object('shift_id', NEW.id));

    -- CASE 2: Shift Removed (User -> Null)
    ELSIF OLD.employee_id IS NOT NULL AND NEW.employee_id IS NULL THEN
        INSERT INTO notifications (merchant_id, recipient_id, type, title, body, data)
        VALUES (OLD.merchant_id, OLD.employee_id, 'schedule_update', 
                'Shift Removed', 
                'Your shift on ' || to_char(OLD.start_time, 'Mon DD') || ' has been removed.',
                jsonb_build_object('shift_id', OLD.id));

    -- CASE 3: Shift Reassigned (User A -> User B)
    ELSIF OLD.employee_id IS NOT NULL AND NEW.employee_id IS NOT NULL AND OLD.employee_id != NEW.employee_id THEN
        -- Notify Old User
        INSERT INTO notifications (merchant_id, recipient_id, type, title, body, data)
        VALUES (OLD.merchant_id, OLD.employee_id, 'schedule_update', 'Shift Removed', 'Your shift on ' || to_char(OLD.start_time, 'Mon DD') || ' has been removed.', jsonb_build_object('shift_id', OLD.id));
        -- Notify New User
        INSERT INTO notifications (merchant_id, recipient_id, type, title, body, data)
        VALUES (NEW.merchant_id, NEW.employee_id, 'schedule_update', 'New Shift Assigned', 'You have been assigned a shift on ' || to_char(NEW.start_time, 'Mon DD') || '.', jsonb_build_object('shift_id', NEW.id));

    -- CASE 4: Time Change (Same User)
    ELSIF OLD.employee_id = NEW.employee_id AND (OLD.start_time != NEW.start_time OR OLD.end_time != NEW.end_time) THEN
        INSERT INTO notifications (merchant_id, recipient_id, type, title, body, data)
        VALUES (NEW.merchant_id, NEW.employee_id, 'schedule_update', 
                'Shift Updated', 
                'Your shift on ' || to_char(NEW.start_time, 'Mon DD') || ' changed: ' || to_char(NEW.start_time, 'HH:MI AM') || ' - ' || to_char(NEW.end_time, 'HH:MI AM'),
                jsonb_build_object('shift_id', NEW.id));
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_shift_update_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_time_clock"("p_pin_code" "text", "p_location_id" "uuid", "p_action_type" "text", "p_device_id" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$DECLARE
    v_staff_id uuid;
    v_rate numeric;
    v_merchant_id uuid;
    v_current_shift_id uuid;
    v_current_status text;
    v_result json;
BEGIN
    -- 1. Validate PIN & Get Staff Context
    -- We perform the bcrypt hash comparison here.
    SELECT 
        sm.staff_profile_id, 
        sm.hourly_rate, 
        sm.merchant_id
    INTO 
        v_staff_id, 
        v_rate, 
        v_merchant_id
    FROM location_members sm
    WHERE sm.location_id = p_location_id 
      AND sm.is_active = true
      -- Validate provided PIN against stored hash (handling 2a/2b prefix differences)
      AND sm.pin_code IS NOT NULL
      AND (
          replace(sm.pin_code, '$2b$', '$2a$') = crypt(p_pin_code, replace(sm.pin_code, '$2b$', '$2a$'))
      );

    IF NOT FOUND THEN
        -- Standardized error for UI to catch
        RAISE EXCEPTION 'INVALID_PIN';
    END IF;

    -- 2. Find Active Shift (if any)
    -- We look for any shift that is not completed
    SELECT id, status INTO v_current_shift_id, v_current_status
    FROM staff_shifts
    WHERE staff_profile_id = v_staff_id
      AND status != 'completed'
    ORDER BY created_at DESC
    LIMIT 1;

    -- 3. Handle Actions
    
    ----------------------------------------------------------------
    -- ACTION: SIGN IN (Unlock + Auto Clock In)
    ----------------------------------------------------------------
    IF p_action_type = 'sign_in' THEN
        -- If NO active shift exists, automatically clock them in
        IF v_current_shift_id IS NULL THEN
            INSERT INTO staff_shifts (
                merchant_id, 
                location_id, 
                staff_profile_id, 
                status, 
                hourly_rate_snapshot, 
                device_id
            ) VALUES (
                v_merchant_id, 
                p_location_id, 
                v_staff_id, 
                'active', 
                COALESCE(v_rate, 0), 
                p_device_id
            ) RETURNING id INTO v_current_shift_id;
            
            v_current_status := 'active';
        END IF;
        -- If shift exists, we just fall through to return success/status
    
    ----------------------------------------------------------------
    -- ACTION: CLOCK IN (Explicit)
    ----------------------------------------------------------------
    ELSIF p_action_type = 'clock_in' THEN
        IF v_current_shift_id IS NOT NULL THEN
            RAISE EXCEPTION 'ALREADY_CLOCKED_IN';
        END IF;

        INSERT INTO staff_shifts (
            merchant_id, 
            location_id, 
            staff_profile_id, 
            status, 
            hourly_rate_snapshot, 
            device_id
        ) VALUES (
            v_merchant_id, 
            p_location_id, 
            v_staff_id, 
            'active', 
            COALESCE(v_rate, 0), 
            p_device_id
        ) RETURNING id INTO v_current_shift_id;
        
        v_current_status := 'active';

    ----------------------------------------------------------------
    -- ACTION: CLOCK OUT
    ----------------------------------------------------------------
    ELSIF p_action_type = 'clock_out' THEN
        IF v_current_shift_id IS NULL THEN
            RAISE EXCEPTION 'NO_ACTIVE_SHIFT';
        END IF;

        IF v_current_status = 'on_break' THEN
             RAISE EXCEPTION 'END_BREAK_FIRST';
        END IF;

        UPDATE staff_shifts
        SET status = 'completed',
            clock_out_time = now(),
            updated_at = now()
        WHERE id = v_current_shift_id;
        
        v_current_status := 'completed';

    ----------------------------------------------------------------
    -- ACTION: START BREAK
    ----------------------------------------------------------------
    ELSIF p_action_type = 'break_start' THEN
        IF v_current_status != 'active' THEN
             RAISE EXCEPTION 'MUST_BE_ACTIVE_TO_BREAK';
        END IF;

        UPDATE staff_shifts
        SET status = 'on_break',
            break_logs = COALESCE(break_logs, '[]'::jsonb) || jsonb_build_array(
                jsonb_build_object(
                    'start', now(), 
                    'end', null, 
                    'type', 'unpaid'
                )
            ),
            updated_at = now()
        WHERE id = v_current_shift_id;
        
        v_current_status := 'on_break';

    ----------------------------------------------------------------
    -- ACTION: END BREAK
    ----------------------------------------------------------------
    ELSIF p_action_type = 'break_end' THEN
        IF v_current_status != 'on_break' THEN
             RAISE EXCEPTION 'NOT_ON_BREAK';
        END IF;

        UPDATE staff_shifts
        SET status = 'active',
            -- Update the 'end' timestamp of the last break entry
            break_logs = jsonb_set(
                break_logs,
                ARRAY[(jsonb_array_length(break_logs) - 1)::text, 'end'],
                to_jsonb(now())
            ),
            updated_at = now()
        WHERE id = v_current_shift_id;
        
        v_current_status := 'active';
    END IF;

    -- 4. Return Status for UI
    SELECT json_build_object(
        'success', true,
        'action', p_action_type,
        'status', v_current_status,
        'staff_id', v_staff_id,
        'shift_id', v_current_shift_id
    ) INTO v_result;

    RETURN v_result;
END;$_$;


ALTER FUNCTION "public"."handle_time_clock"("p_pin_code" "text", "p_location_id" "uuid", "p_action_type" "text", "p_device_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_time_clock_v2"("p_location_id" "uuid", "p_pin_code" "text", "p_action_type" "text", "p_device_id" "text", "p_station_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$DECLARE
    v_staff_id uuid;
    v_rate numeric;
    v_merchant_id uuid;
    v_current_shift_id uuid;
    v_current_status text;
    v_result json;
    v_session_id uuid;
    v_member_id uuid;
    v_pin_plain text;
BEGIN
    -- 1. Validate PIN & Get Staff Context
        SELECT
        sm.staff_profile_id,
        sm.hourly_rate,
        sm.merchant_id,
        sm.id,
        sm.pin_plain
    INTO
        v_staff_id,
        v_rate,
        v_merchant_id,
        v_member_id,
        v_pin_plain
    FROM location_members sm
    WHERE sm.location_id = p_location_id
      AND sm.is_active = true
      AND (
          -- Fast path: plain-text PIN match
          (sm.pin_plain IS NOT NULL AND sm.pin_plain = p_pin_code)
          OR
          -- Bcrypt fallback: un-migrated employees only
          (sm.pin_plain IS NULL AND sm.pin_code IS NOT NULL
           AND replace(sm.pin_code, '$2b$', '$2a$') = crypt(p_pin_code, replace(sm.pin_code, '$2b$', '$2a$')))
      );

    IF NOT FOUND THEN
        RAISE EXCEPTION 'INVALID_PIN';
    END IF;

    -- Auto-migrate: populate pin_plain on first successful bcrypt login
    IF v_pin_plain IS NULL THEN
        UPDATE location_members SET pin_plain = p_pin_code WHERE id = v_member_id;
    END IF;


    -- Get active station session for this device (if any)
    SELECT id INTO v_session_id
    FROM station_sessions
    WHERE device_id = p_device_id AND session_status = 'active';

    -- 2. Find Active Shift (if any)
    SELECT id, status INTO v_current_shift_id, v_current_status
    FROM staff_shifts
    WHERE staff_profile_id = v_staff_id
      AND status != 'completed'
    ORDER BY created_at DESC
    LIMIT 1;

    -- 3. Handle Actions
    
    ----------------------------------------------------------------
    -- ACTION: SIGN IN (Unlock + Auto Clock In)
    ----------------------------------------------------------------
    IF p_action_type = 'sign_in' THEN
        IF v_current_shift_id IS NULL THEN
            INSERT INTO staff_shifts (
                merchant_id, 
                location_id, 
                staff_profile_id, 
                status, 
                hourly_rate_snapshot, 
                device_id,
                station_id,              -- NEW
                station_session_id       -- NEW
            ) VALUES (
                v_merchant_id, 
                p_location_id, 
                v_staff_id, 
                'active', 
                COALESCE(v_rate, 0), 
                p_device_id,
                p_station_id,            -- NEW
                v_session_id             -- NEW
            ) RETURNING id INTO v_current_shift_id;
            
            v_current_status := 'active';
        END IF;
    
    ----------------------------------------------------------------
    -- ACTION: CLOCK IN (Explicit)
    ----------------------------------------------------------------
    ELSIF p_action_type = 'clock_in' THEN
        IF v_current_shift_id IS NOT NULL THEN
            RAISE EXCEPTION 'ALREADY_CLOCKED_IN';
        END IF;

        INSERT INTO staff_shifts (
            merchant_id, 
            location_id, 
            staff_profile_id, 
            status, 
            hourly_rate_snapshot, 
            device_id,
            station_id,              -- NEW
            station_session_id       -- NEW
        ) VALUES (
            v_merchant_id, 
            p_location_id, 
            v_staff_id, 
            'active', 
            COALESCE(v_rate, 0), 
            p_device_id,
            p_station_id,            -- NEW
            v_session_id             -- NEW
        ) RETURNING id INTO v_current_shift_id;
        
        v_current_status := 'active';

    ----------------------------------------------------------------
    -- ACTION: CLOCK OUT
    ----------------------------------------------------------------
    ELSIF p_action_type = 'clock_out' THEN
        IF v_current_shift_id IS NULL THEN
            RAISE EXCEPTION 'NO_ACTIVE_SHIFT';
        END IF;

        IF v_current_status = 'on_break' THEN
             RAISE EXCEPTION 'END_BREAK_FIRST';
        END IF;

        UPDATE staff_shifts
        SET status = 'completed',
            clock_out_time = now(),
            updated_at = now()
        WHERE id = v_current_shift_id;
        
        v_current_status := 'completed';

    ----------------------------------------------------------------
    -- ACTION: START BREAK
    ----------------------------------------------------------------
    ELSIF p_action_type = 'break_start' THEN
        IF v_current_status != 'active' THEN
             RAISE EXCEPTION 'MUST_BE_ACTIVE_TO_BREAK';
        END IF;

        UPDATE staff_shifts
        SET status = 'on_break',
            break_logs = COALESCE(break_logs, '[]'::jsonb) || jsonb_build_array(
                jsonb_build_object(
                    'start', now(), 
                    'end', null, 
                    'type', 'unpaid'
                )
            ),
            updated_at = now()
        WHERE id = v_current_shift_id;
        
        v_current_status := 'on_break';

    ----------------------------------------------------------------
    -- ACTION: END BREAK
    ----------------------------------------------------------------
    ELSIF p_action_type = 'break_end' THEN
        IF v_current_status != 'on_break' THEN
             RAISE EXCEPTION 'NOT_ON_BREAK';
        END IF;

        UPDATE staff_shifts
        SET status = 'active',
            break_logs = jsonb_set(
                break_logs,
                ARRAY[(jsonb_array_length(break_logs) - 1)::text, 'end'],
                to_jsonb(now())
            ),
            updated_at = now()
        WHERE id = v_current_shift_id;
        
        v_current_status := 'active';
    END IF;

    -- 4. Return Status for UI
    SELECT json_build_object(
        'success', true,
        'action', p_action_type,
        'status', v_current_status,
        'staff_id', v_staff_id,
        'shift_id', v_current_shift_id,
        'station_id', p_station_id      -- NEW
    ) INTO v_result;

    RETURN v_result;
END;$_$;


ALTER FUNCTION "public"."handle_time_clock_v2"("p_location_id" "uuid", "p_pin_code" "text", "p_action_type" "text", "p_device_id" "text", "p_station_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hq_has_permission"("p_permission_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_user_id text;
  v_has_permission boolean;
BEGIN
  v_user_id := current_user_id();
  IF v_user_id IS NULL THEN
    RETURN false;
  END IF;

  IF NOT is_dexapos_admin() THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM members m
    JOIN roles r ON r.code = m.role
    JOIN role_permissions rp ON rp.role_code = m.role
    WHERE m.user_id = v_user_id
      AND r.organization_type = 'hq'
      AND rp.permission_code = p_permission_code
  )
  INTO v_has_permission;

  RETURN COALESCE(v_has_permission, false);
END;
$$;


ALTER FUNCTION "public"."hq_has_permission"("p_permission_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hq_has_permission"("p_permission_code" "text") IS 'Checks HQ permission using members.role + role_permissions (aligned with members-based HQ roles).';



CREATE OR REPLACE FUNCTION "public"."increment_castles_txn_counter"("p_terminal_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_next INTEGER;
BEGIN
  UPDATE payment_terminals
  SET
    castles_txn_counter = CASE
      WHEN castles_txn_counter >= 999999 THEN 1  -- wrap around
      ELSE castles_txn_counter + 1
    END,
    castles_counter_updated_at = now()
  WHERE id = p_terminal_id
  RETURNING castles_txn_counter INTO v_next;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Terminal not found: %', p_terminal_id;
  END IF;

  RETURN v_next;
END;
$$;


ALTER FUNCTION "public"."increment_castles_txn_counter"("p_terminal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_location_stock"("p_inventory_item_id" "uuid", "p_location_id" "uuid", "p_quantity" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    INSERT INTO location_inventory_stock (location_id, inventory_item_id, stock_quantity, updated_at)
    VALUES (p_location_id, p_inventory_item_id, GREATEST(0, p_quantity), now())
    ON CONFLICT (location_id, inventory_item_id)
    DO UPDATE SET
        stock_quantity = location_inventory_stock.stock_quantity + p_quantity,
        updated_at     = now();

    -- Sync legacy aggregate
    UPDATE inventory_items
    SET
        current_stock = (
            SELECT COALESCE(SUM(stock_quantity), 0)
            FROM location_inventory_stock
            WHERE inventory_item_id = p_inventory_item_id
        ),
        updated_at = now()
    WHERE id = p_inventory_item_id;
END;
$$;


ALTER FUNCTION "public"."increment_location_stock"("p_inventory_item_id" "uuid", "p_location_id" "uuid", "p_quantity" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_order_sync_version"("p_order_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_new_version integer;
BEGIN
    UPDATE orders
    SET sync_version = COALESCE(sync_version, 0) + 1,
        updated_at = NOW()
    WHERE id = p_order_id
    RETURNING sync_version INTO v_new_version;

    RETURN COALESCE(v_new_version, 1);
END;
$$;


ALTER FUNCTION "public"."increment_order_sync_version"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initialize_location_stock"("p_location_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    INSERT INTO location_inventory_stock (location_id, inventory_item_id, stock_quantity)
    SELECT p_location_id, ii.id, 0
    FROM inventory_items ii
    JOIN locations l ON l.merchant_id = ii.merchant_id
    WHERE l.id      = p_location_id
      AND ii.location_id IS NULL   -- global items only
      AND ii.is_active = true
      AND NOT EXISTS (
          SELECT 1 FROM location_inventory_stock lis
          WHERE lis.location_id      = p_location_id
            AND lis.inventory_item_id = ii.id
      );

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."initialize_location_stock"("p_location_id" "uuid") OWNER TO "postgres";


