CREATE OR REPLACE FUNCTION "public"."is_location_member"("p_location_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM location_members
        WHERE user_id = current_user_id()
          AND location_id = p_location_id
          AND is_active = true
    );
$$;


ALTER FUNCTION "public"."is_location_member"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_merchant_admin"("p_merchant_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$SELECT (
    -- 1. Check if the user is a global admin (Short-circuit logic)
    is_dexapos_admin() 
    OR 
    -- 2. If not admin, check specific merchant membership and roles
    EXISTS (
        SELECT 1 
        FROM members m
        JOIN merchants mer ON mer.clerk_org_id = m.organization_id
        WHERE m.user_id = current_user_id()
          AND mer.id = p_merchant_id
          AND m.role IN ('merchant.owner', 'merchant.admin', 'merchant.manager') 
    )
);$$;


ALTER FUNCTION "public"."is_merchant_admin"("p_merchant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_merchant_owner"("p_merchant_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$-- Single table lookup, context secure
SELECT EXISTS (
    SELECT 1 
    FROM members m
    JOIN merchants mer ON mer.clerk_org_id = m.organization_id
    WHERE m.user_id = current_user_id()
      AND mer.id = p_merchant_id
      -- The role is directly checked against the membership for THIS merchant
      AND m.role IN ('merchant.owner', 'merchant.admin') 
);$$;


ALTER FUNCTION "public"."is_merchant_owner"("p_merchant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_order_to_session"("p_session_id" "uuid", "p_order_id" "uuid", "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$BEGIN
  -- =========================================
  -- Validation
  -- =========================================
  IF p_order_id IS NULL OR p_session_id IS NULL THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Both order_id and session_id are required'
    );
  END IF;

  -- Verify session
  IF NOT EXISTS (
    SELECT 1 FROM public.table_sessions
    WHERE id = p_session_id AND is_active = TRUE
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids())
  ) THEN
    RAISE EXCEPTION 'Session not found';
  END IF;

  -- Verify order
  IF NOT EXISTS (
    SELECT 1 FROM public.orders
    WHERE id = p_order_id
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids())
  ) THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  -- -- Check if session exists
  -- SELECT EXISTS(SELECT 1 FROM table_sessions WHERE id = p_session_id)
  -- INTO v_session_exists;

  -- IF NOT v_session_exists THEN
  --   RETURN json_build_object(
  --     'success', false,
  --     'error', 'Session not found'
  --   );
  -- END IF;

  -- =========================================
  -- Bidirectional Update (Atomic)
  -- =========================================

  -- Update order to point to session
  UPDATE orders
  SET
    session_id = p_session_id,
    updated_at = NOW()
  WHERE id = p_order_id;

  -- Update session to point to order
  UPDATE table_sessions
  SET
    order_id = p_order_id,
    updated_at = NOW()
  WHERE id = p_session_id;

  -- Record event if first order
  INSERT INTO public.table_session_events (
    session_id, event_type, event_data,
    triggered_by_staff_id, triggered_by_user_id
  ) VALUES (
    p_session_id, 'order_placed', 
    jsonb_build_object('order_id', p_order_id),
    COALESCE(p_staff_id, user_staff_profile_id()), get_my_claim('sub')
  );

  return json_build_object(
    'success', true,
    'order_id', p_order_id,
    'session_id', p_session_id,
    'linked_at', NOW(),
    'message', 'Order and session linked successfully'
  );

EXCEPTION WHEN OTHERS THEN
  -- Handle any unexpected errors
  RETURN json_build_object(
    'success', false,
    'error', SQLERRM,
    'error_code', SQLSTATE
  );
END;$$;


ALTER FUNCTION "public"."link_order_to_session"("p_session_id" "uuid", "p_order_id" "uuid", "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_admin_payment_audit_event"("p_action" "text", "p_resource_type" "text" DEFAULT 'payment_data'::"text", "p_resource_id" "text" DEFAULT NULL::"text", "p_merchant_id" "text" DEFAULT NULL::"text", "p_location_id" "text" DEFAULT NULL::"text", "p_fields_accessed" "text"[] DEFAULT NULL::"text"[], "p_success" boolean DEFAULT true, "p_error_message" "text" DEFAULT NULL::"text", "p_request_path" "text" DEFAULT '/manage/transactions'::"text", "p_ip_address" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id text := auth.jwt()->>'sub';
  v_user_email text := NULLIF(auth.jwt()->>'email', '');
  v_user_role text := NULL;
  v_resource_id uuid := NULL;
  v_merchant_id uuid := NULL;
  v_location_id uuid := NULL;
  v_ip_address inet := NULL;
BEGIN
  IF NOT public.is_dexapos_admin() THEN
    RETURN;
  END IF;

  IF NULLIF(trim(COALESCE(p_resource_id, '')), '') IS NOT NULL THEN
    BEGIN
      v_resource_id := trim(p_resource_id)::uuid;
    EXCEPTION
      WHEN others THEN
        v_resource_id := NULL;
    END;
  END IF;

  IF NULLIF(trim(COALESCE(p_merchant_id, '')), '') IS NOT NULL THEN
    BEGIN
      v_merchant_id := trim(p_merchant_id)::uuid;
    EXCEPTION
      WHEN others THEN
        v_merchant_id := NULL;
    END;
  END IF;

  IF NULLIF(trim(COALESCE(p_location_id, '')), '') IS NOT NULL THEN
    BEGIN
      v_location_id := trim(p_location_id)::uuid;
    EXCEPTION
      WHEN others THEN
        v_location_id := NULL;
    END;
  END IF;

  IF NULLIF(trim(COALESCE(p_ip_address, '')), '') IS NOT NULL THEN
    BEGIN
      v_ip_address := trim(p_ip_address)::inet;
    EXCEPTION
      WHEN others THEN
        v_ip_address := NULL;
    END;
  END IF;

  BEGIN
    SELECT role_code::text
    INTO v_user_role
    FROM public.get_my_hq_role()
    LIMIT 1;
  EXCEPTION
    WHEN others THEN
      v_user_role := NULL;
  END;

  INSERT INTO public.payment_audit_log (
    resource_type,
    resource_id,
    action,
    user_id,
    user_email,
    user_role,
    merchant_id,
    location_id,
    ip_address,
    user_agent,
    request_path,
    success,
    error_message,
    fields_accessed,
    event_timestamp
  )
  VALUES (
    COALESCE(NULLIF(trim(COALESCE(p_resource_type, '')), ''), 'payment_data'),
    v_resource_id,
    COALESCE(NULLIF(trim(COALESCE(p_action, '')), ''), 'unknown_action'),
    v_user_id,
    v_user_email,
    v_user_role,
    v_merchant_id,
    v_location_id,
    v_ip_address,
    NULLIF(trim(COALESCE(p_user_agent, '')), ''),
    COALESCE(NULLIF(trim(COALESCE(p_request_path, '')), ''), '/manage/transactions'),
    COALESCE(p_success, true),
    NULLIF(trim(COALESCE(p_error_message, '')), ''),
    COALESCE(p_fields_accessed, ARRAY[]::text[]),
    now()
  );
EXCEPTION
  WHEN others THEN
    RETURN;
END;
$$;


ALTER FUNCTION "public"."log_admin_payment_audit_event"("p_action" "text", "p_resource_type" "text", "p_resource_id" "text", "p_merchant_id" "text", "p_location_id" "text", "p_fields_accessed" "text"[], "p_success" boolean, "p_error_message" "text", "p_request_path" "text", "p_ip_address" "text", "p_user_agent" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_admin_payment_audit_event"("p_action" "text", "p_resource_type" "text", "p_resource_id" "text", "p_merchant_id" "text", "p_location_id" "text", "p_fields_accessed" "text"[], "p_success" boolean, "p_error_message" "text", "p_request_path" "text", "p_ip_address" "text", "p_user_agent" "text") IS 'Logs HQ admin payment-data access actions (list/detail/export/search) to payment_audit_log. Retained long-term; no automatic pruning configured.';



CREATE OR REPLACE FUNCTION "public"."log_audit_event"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_actor_user_id" "text", "p_actor_name" "text", "p_actor_role" "text", "p_action" "text", "p_action_category" "text", "p_severity" "text" DEFAULT 'info'::"text", "p_resource_type" "text" DEFAULT NULL::"text", "p_resource_id" "uuid" DEFAULT NULL::"uuid", "p_resource_name" "text" DEFAULT NULL::"text", "p_changes" "jsonb" DEFAULT NULL::"jsonb", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_log_id UUID;
BEGIN
  INSERT INTO public.audit_logs (
    merchant_id,
    location_id,
    actor_user_id,
    actor_name,
    actor_role,
    action,
    action_category,
    severity,
    resource_type,
    resource_id,
    resource_name,
    changes,
    metadata
  ) VALUES (
    p_merchant_id,
    p_location_id,
    p_actor_user_id,
    p_actor_name,
    p_actor_role,
    p_action,
    p_action_category,
    p_severity,
    p_resource_type,
    p_resource_id,
    p_resource_name,
    p_changes,
    p_metadata
  )
  RETURNING id INTO v_log_id;
  
  RETURN v_log_id;
END;
$$;


