CREATE OR REPLACE FUNCTION "public"."log_payment_event"("p_payment_id" "uuid", "p_order_id" "uuid", "p_location_id" "uuid", "p_event_type" "text", "p_amount" numeric DEFAULT NULL::numeric, "p_tip_amount" numeric DEFAULT NULL::numeric, "p_previous_status" "text" DEFAULT NULL::"text", "p_new_status" "text" DEFAULT NULL::"text", "p_psp_reference" "text" DEFAULT NULL::"text", "p_auth_code" "text" DEFAULT NULL::"text", "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_terminal_id" "text" DEFAULT NULL::"text", "p_result_code" "text" DEFAULT NULL::"text", "p_response_message" "text" DEFAULT NULL::"text", "p_raw_response" "jsonb" DEFAULT NULL::"jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_event_id uuid;
BEGIN
    INSERT INTO public.payment_events (
        id,
        payment_id,
        order_id,
        location_id,
        event_type,
        amount,
        tip_amount,
        previous_status,
        new_status,
        psp_reference,
        auth_code,
        staff_id,
        terminal_id,
        result_code,
        response_message,
        raw_response,
        reason,
        event_timestamp
    ) VALUES (
        gen_random_uuid(),
        p_payment_id,
        p_order_id,
        p_location_id,
        p_event_type,
        p_amount,
        p_tip_amount,
        p_previous_status,
        p_new_status,
        p_psp_reference,
        p_auth_code,
        p_staff_id,
        p_terminal_id,
        p_result_code,
        p_response_message,
        p_raw_response,
        p_reason,
        now()
    )
    RETURNING id INTO v_event_id;
    
    RETURN v_event_id;
    
EXCEPTION WHEN OTHERS THEN
    -- Fire and forget - don't fail the main transaction for audit logging
    RAISE WARNING 'Failed to log payment event: %', SQLERRM;
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."log_payment_event"("p_payment_id" "uuid", "p_order_id" "uuid", "p_location_id" "uuid", "p_event_type" "text", "p_amount" numeric, "p_tip_amount" numeric, "p_previous_status" "text", "p_new_status" "text", "p_psp_reference" "text", "p_auth_code" "text", "p_staff_id" "uuid", "p_terminal_id" "text", "p_result_code" "text", "p_response_message" "text", "p_raw_response" "jsonb", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_payment_event"("p_payment_id" "uuid", "p_order_id" "uuid", "p_location_id" "uuid", "p_event_type" "text", "p_amount" numeric, "p_tip_amount" numeric, "p_previous_status" "text", "p_new_status" "text", "p_psp_reference" "text", "p_auth_code" "text", "p_staff_id" "uuid", "p_terminal_id" "text", "p_result_code" "text", "p_response_message" "text", "p_raw_response" "jsonb", "p_reason" "text") IS 'Append-only audit log for payment lifecycle events. Fire-and-forget design - 
failures are logged as warnings but do not block the main transaction.';



CREATE OR REPLACE FUNCTION "public"."log_purchase_order_delivery"("p_purchase_order_id" "uuid", "p_delivered_by" "text", "p_delivery_notes" "text", "p_logged_by_user_id" "text", "p_logged_by_name" "text", "p_received_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_location_id       UUID;
    v_merchant_id       UUID;
    v_item              JSONB;
    v_inventory_item_id UUID;
    v_qty_received      NUMERIC;
    v_qty_ordered       NUMERIC;
    v_prev_stock        NUMERIC;
    v_new_stock         NUMERIC;
    v_items_processed   INTEGER  := 0;
    v_discrepancies     JSONB    := '[]'::jsonb;
BEGIN
    SELECT po.location_id, po.merchant_id
    INTO   v_location_id, v_merchant_id
    FROM   purchase_orders po
    WHERE  po.id = p_purchase_order_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_received_items)
    LOOP
        v_inventory_item_id := (v_item->>'inventory_item_id')::UUID;
        v_qty_received      := (v_item->>'quantity_received')::NUMERIC;

        -- Capture pre-receive stock for audit log
        SELECT COALESCE(stock_quantity, 0)
        INTO   v_prev_stock
        FROM   location_inventory_stock
        WHERE  location_id       = v_location_id
        AND  inventory_item_id = v_inventory_item_id;

        -- Get ordered quantity to detect discrepancy
        SELECT quantity_ordered
        INTO   v_qty_ordered
        FROM   purchase_order_items
        WHERE  purchase_order_id = p_purchase_order_id
        AND  inventory_item_id = v_inventory_item_id;

        -- Update received qty on PO line
        UPDATE purchase_order_items
        SET    quantity_received = v_qty_received
        WHERE  purchase_order_id = p_purchase_order_id
          AND  inventory_item_id = v_inventory_item_id;

        -- Increment stock
        PERFORM public.increment_location_stock(v_inventory_item_id, v_location_id, v_qty_received);

        -- Capture post-receive stock
        SELECT COALESCE(stock_quantity, 0)
        INTO   v_new_stock
        FROM   location_inventory_stock
        WHERE  location_id       = v_location_id
          AND  inventory_item_id = v_inventory_item_id;

        -- Audit log entry
        INSERT INTO stock_update_log (
            merchant_id, location_id, inventory_item_id,
            previous_stock, new_stock, change_amount,
            update_reason, update_source,
            updated_by_user_id, updated_by_name,
            purchase_order_id
        ) VALUES (
            v_merchant_id, v_location_id, v_inventory_item_id,
            v_prev_stock, v_new_stock, v_qty_received,
            'received_delivery', 'delivery',
            p_logged_by_user_id, p_logged_by_name,
            p_purchase_order_id
        );

        -- Record discrepancy if received != ordered
        IF v_qty_ordered IS NOT NULL AND v_qty_received <> v_qty_ordered THEN
            v_discrepancies := v_discrepancies || jsonb_build_object(
                'inventory_item_id', v_inventory_item_id,
                'quantity_ordered',  v_qty_ordered,
                'quantity_received', v_qty_received,
                'difference',        v_qty_received - v_qty_ordered
            );
        END IF;

        v_items_processed := v_items_processed + 1;
    END LOOP;

    -- Mark PO as received
    UPDATE purchase_orders
    SET
        status                    = 'received',
        received_at               = now(),
        delivered_by              = p_delivered_by,
        delivered_at              = now(),
        delivery_notes            = p_delivery_notes,
        delivery_logged_by_user_id = p_logged_by_user_id,
        delivery_logged_by_name   = p_logged_by_name,
        updated_at                = now()
    WHERE id = p_purchase_order_id;

    RETURN jsonb_build_object(
        'success',         true,
        'items_processed', v_items_processed,
        'discrepancies',   v_discrepancies
    );
END;
$$;


ALTER FUNCTION "public"."log_purchase_order_delivery"("p_purchase_order_id" "uuid", "p_delivered_by" "text", "p_delivery_notes" "text", "p_logged_by_user_id" "text", "p_logged_by_name" "text", "p_received_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_purchase_order_payment"("p_purchase_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric, "p_paid_by_user_id" "text", "p_paid_by_name" "text", "p_paid_to" "text", "p_card_last_four" "text", "p_notes" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_payment_id  UUID;
    v_vendor_id   UUID;
    v_vendor_name TEXT;
BEGIN
    SELECT po.vendor_id, v.name
    INTO   v_vendor_id, v_vendor_name
    FROM   purchase_orders po
    LEFT JOIN vendors v ON v.id = po.vendor_id
    WHERE  po.id = p_purchase_order_id;

    INSERT INTO purchase_order_payments (
        purchase_order_id, payment_method, card_last_four, amount,
        vendor_id, vendor_name, paid_to,
        paid_by_user_id, paid_by_name, notes
    ) VALUES (
        p_purchase_order_id, p_payment_method, p_card_last_four, p_amount,
        v_vendor_id, v_vendor_name, p_paid_to,
        p_paid_by_user_id, p_paid_by_name, p_notes
    )
    RETURNING id INTO v_payment_id;

    UPDATE purchase_orders
    SET
        status        = 'paid',
        paid_at       = now(),
        payment_method = p_payment_method,
        card_last_four = p_card_last_four,
        updated_at    = now()
    WHERE id = p_purchase_order_id;

    RETURN jsonb_build_object('success', true, 'payment_id', v_payment_id);
END;
$$;


ALTER FUNCTION "public"."log_purchase_order_payment"("p_purchase_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric, "p_paid_by_user_id" "text", "p_paid_by_name" "text", "p_paid_to" "text", "p_card_last_four" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_purchase_order_payment"("p_purchase_order_id" "uuid", "p_payment_method" "text", "p_card_last_four" "text", "p_amount" numeric, "p_paid_to" "text", "p_paid_by_user_id" "text", "p_paid_by_name" "text", "p_notes" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_po_merchant_id UUID;
  v_po_location_id UUID;
  v_po_number TEXT;
  v_po_vendor_id UUID;
  v_expense_vendor_name TEXT;
  v_vendor_name TEXT;
  v_payment_id UUID;
BEGIN
  -- Get the purchase order with vendor info
  SELECT 
    po.merchant_id, 
    po.location_id, 
    po.po_number, 
    po.vendor_id,
    po.expense_vendor_name,
    v.name
  INTO 
    v_po_merchant_id, 
    v_po_location_id, 
    v_po_number, 
    v_po_vendor_id,
    v_expense_vendor_name,
    v_vendor_name
  FROM public.purchase_orders po
  LEFT JOIN public.vendors v ON po.vendor_id = v.id
  WHERE po.id = p_purchase_order_id;
  
  IF v_po_number IS NULL THEN
    RAISE EXCEPTION 'Purchase order not found';
  END IF;
  
  -- Create payment record
  INSERT INTO public.purchase_order_payments (
    purchase_order_id,
    payment_method,
    card_last_four,
    amount,
    vendor_id,
    vendor_name,
    paid_to,
    paid_by_user_id,
    paid_by_name,
    notes
  ) VALUES (
    p_purchase_order_id,
    p_payment_method,
    CASE WHEN p_payment_method = 'card' THEN p_card_last_four ELSE NULL END,
    p_amount,
    v_po_vendor_id,
    v_vendor_name,
    p_paid_to,
    p_paid_by_user_id,
    p_paid_by_name,
    p_notes
  )
  RETURNING id INTO v_payment_id;
  
  -- Update PO status to paid
  UPDATE public.purchase_orders
  SET 
    status = 'paid',
    paid_at = NOW(),
    updated_at = NOW()
  WHERE id = p_purchase_order_id;
  
  -- Log to audit_logs
  INSERT INTO public.audit_logs (
    merchant_id,
    location_id,
    actor_user_id,
    actor_name,
    action,
    action_category,
    severity,
    resource_type,
    resource_id,
    resource_name,
    changes,
    metadata
  ) VALUES (
    v_po_merchant_id,
    v_po_location_id,
    p_paid_by_user_id,
    p_paid_by_name,
    'purchase_order.paid',
    'purchase_order',
    'info',
    'purchase_order',
    p_purchase_order_id,
    v_po_number,
    jsonb_build_object(
      'after', jsonb_build_object('status', 'paid', 'amount', p_amount, 'payment_method', p_payment_method)
    ),
    jsonb_build_object(
      'payment_id', v_payment_id,
      'paid_to', p_paid_to,
      'vendor_name', COALESCE(v_vendor_name, v_expense_vendor_name),
      'notes', p_notes
    )
  );
  
  RETURN v_payment_id;
END;
$$;


ALTER FUNCTION "public"."log_purchase_order_payment"("p_purchase_order_id" "uuid", "p_payment_method" "text", "p_card_last_four" "text", "p_amount" numeric, "p_paid_to" "text", "p_paid_by_user_id" "text", "p_paid_by_name" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_stock_update_with_audit"("p_location_id" "uuid", "p_inventory_item_id" "uuid", "p_new_stock" numeric, "p_update_reason" "text", "p_update_source" "text", "p_user_id" "text", "p_user_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_item_name TEXT;
  v_unit_type TEXT;
  v_previous_stock NUMERIC;
  v_merchant_id UUID;
  v_change_amount NUMERIC;
  v_stock_log_id UUID;
  v_audit_log_id UUID;
BEGIN
  -- Get the inventory item details
  SELECT ii.name, ii.unit_type, ii.merchant_id 
  INTO v_item_name, v_unit_type, v_merchant_id
  FROM public.inventory_items ii
  WHERE ii.id = p_inventory_item_id;
  
  IF v_item_name IS NULL THEN
    RAISE EXCEPTION 'Inventory item not found';
  END IF;
  
  -- Get current stock for this location
  SELECT lis.stock_quantity INTO v_previous_stock
  FROM public.location_inventory_stock lis
  WHERE lis.location_id = p_location_id AND lis.inventory_item_id = p_inventory_item_id;
  
  v_previous_stock := COALESCE(v_previous_stock, 0);
  v_change_amount := p_new_stock - v_previous_stock;
  
  -- Upsert the location stock
  INSERT INTO public.location_inventory_stock (location_id, inventory_item_id, stock_quantity, updated_at)
  VALUES (p_location_id, p_inventory_item_id, p_new_stock, NOW())
  ON CONFLICT (location_id, inventory_item_id)
  DO UPDATE SET 
    stock_quantity = EXCLUDED.stock_quantity,
    updated_at = NOW();
  
  -- Log to stock_update_log
  INSERT INTO public.stock_update_log (
    merchant_id,
    location_id,
    inventory_item_id,
    previous_stock,
    new_stock,
    change_amount,
    update_reason,
    update_source,
    updated_by_user_id,
    updated_by_name
  ) VALUES (
    v_merchant_id,
    p_location_id,
    p_inventory_item_id,
    v_previous_stock,
    p_new_stock,
    v_change_amount,
    p_update_reason,
    p_update_source,
    p_user_id,
    p_user_name
  )
  RETURNING id INTO v_stock_log_id;
  
  -- Log to audit_logs
  INSERT INTO public.audit_logs (
    merchant_id,
    location_id,
    actor_user_id,
    actor_name,
    action,
    action_category,
    severity,
    resource_type,
    resource_id,
    resource_name,
    changes,
    metadata
  ) VALUES (
    v_merchant_id,
    p_location_id,
    p_user_id,
    p_user_name,
    'inventory.stock_updated',
    'inventory',
    CASE WHEN ABS(v_change_amount) > 100 THEN 'warning' ELSE 'info' END,
    'inventory_item',
    p_inventory_item_id,
    v_item_name,
    jsonb_build_object(
      'before', jsonb_build_object('stock', v_previous_stock),
      'after', jsonb_build_object('stock', p_new_stock),
      'reason', p_update_reason
    ),
    jsonb_build_object(
      'change_amount', v_change_amount,
      'update_source', p_update_source,
      'unit_type', v_unit_type
    )
  )
  RETURNING id INTO v_audit_log_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'stock_log_id', v_stock_log_id,
    'audit_log_id', v_audit_log_id,
    'previous_stock', v_previous_stock,
    'new_stock', p_new_stock,
    'change_amount', v_change_amount
  );
END;
$$;


ALTER FUNCTION "public"."log_stock_update_with_audit"("p_location_id" "uuid", "p_inventory_item_id" "uuid", "p_new_stock" numeric, "p_update_reason" "text", "p_update_source" "text", "p_user_id" "text", "p_user_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_waste"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_inventory_item_id" "uuid", "p_quantity" numeric, "p_reason" "text", "p_notes" "text", "p_logged_by_user_id" "text", "p_logged_by_name" "text", "p_waste_date" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_waste_log_id      UUID;
    v_cost_per_unit     NUMERIC;
    v_estimated_cost    NUMERIC;
    v_prev_stock        NUMERIC;
    v_new_stock         NUMERIC;
BEGIN
    -- Validate quantity
    IF p_quantity <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'quantity must be greater than zero');
    END IF;

    -- Fetch cost_per_unit for estimated_cost calculation
    SELECT COALESCE(cost_per_unit, 0)
    INTO   v_cost_per_unit
    FROM   inventory_items
    WHERE  id = p_inventory_item_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'inventory item not found');
    END IF;

    v_estimated_cost := ROUND(v_cost_per_unit * p_quantity, 4);

    -- Capture pre-waste stock
    SELECT COALESCE(stock_quantity, 0)
    INTO   v_prev_stock
    FROM   location_inventory_stock
    WHERE  location_id       = p_location_id
      AND  inventory_item_id = p_inventory_item_id;

    -- Insert waste record
    INSERT INTO waste_logs (
        merchant_id, location_id, inventory_item_id,
        quantity, reason, notes,
        waste_date, estimated_cost,
        logged_by_user_id, logged_by_name
    ) VALUES (
        p_merchant_id, p_location_id, p_inventory_item_id,
        p_quantity, p_reason, p_notes,
        p_waste_date, v_estimated_cost,
        p_logged_by_user_id, p_logged_by_name
    )
    RETURNING id INTO v_waste_log_id;

    -- Decrement stock (floored at 0)
    PERFORM public.decrement_location_stock(p_inventory_item_id, p_location_id, p_quantity);

    -- Capture post-waste stock
    SELECT COALESCE(stock_quantity, 0)
    INTO   v_new_stock
    FROM   location_inventory_stock
    WHERE  location_id       = p_location_id
      AND  inventory_item_id = p_inventory_item_id;

    -- Audit log
    INSERT INTO stock_update_log (
        merchant_id, location_id, inventory_item_id,
        previous_stock, new_stock, change_amount,
        update_reason, update_source,
        updated_by_user_id, updated_by_name
    ) VALUES (
        p_merchant_id, p_location_id, p_inventory_item_id,
        v_prev_stock, v_new_stock, -p_quantity,
        'waste_spoilage', 'waste',
        p_logged_by_user_id, p_logged_by_name
    );

    RETURN jsonb_build_object(
        'success',        true,
        'waste_log_id',   v_waste_log_id,
        'estimated_cost', v_estimated_cost,
        'new_stock',      v_new_stock
    );
END;
$$;


ALTER FUNCTION "public"."log_waste"("p_merchant_id" "uuid", "p_location_id" "uuid", "p_inventory_item_id" "uuid", "p_quantity" numeric, "p_reason" "text", "p_notes" "text", "p_logged_by_user_id" "text", "p_logged_by_name" "text", "p_waste_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."loyalty_earn_on_order"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_customer_id UUID;
    v_merchant_id UUID;
    v_location_id UUID;
    v_total NUMERIC;
    v_discount NUMERIC;
    v_status TEXT;
    v_program RECORD;
    v_enrollment RECORD;
    v_points_earned INTEGER;
    v_qualifying_amount NUMERIC;
    v_item RECORD;
    v_punch_earned INTEGER;
    v_reward_id UUID;
    v_result JSONB := '[]'::JSONB;
BEGIN
    SELECT customer_id, merchant_id, location_id, total_amount, discount_amount, status
    INTO v_customer_id, v_merchant_id, v_location_id, v_total, v_discount, v_status
    FROM orders
    WHERE id = p_order_id;

    IF v_status IS NULL THEN
        RETURN jsonb_build_object('error', 'Order not found', 'order_id', p_order_id);
    END IF;

    IF v_customer_id IS NULL THEN
        RETURN jsonb_build_object('error', 'Order has no customer', 'order_id', p_order_id);
    END IF;

    FOR v_program IN
        SELECT *
        FROM loyalty_programs
        WHERE merchant_id = v_merchant_id
          AND is_active = true
          AND (starts_at IS NULL OR starts_at <= now())
          AND (ends_at IS NULL OR ends_at >= now())
          AND (location_ids IS NULL OR v_location_id = ANY(location_ids))
    LOOP
        v_reward_id := NULL;
        v_points_earned := 0;
        v_punch_earned := 0;

        SELECT * INTO v_enrollment
        FROM loyalty_enrollments
        WHERE program_id = v_program.id AND customer_id = v_customer_id;

        IF v_enrollment IS NULL THEN
            IF v_program.auto_enroll THEN
                INSERT INTO loyalty_enrollments (
                    program_id, customer_id, merchant_id,
                    current_points, lifetime_points,
                    current_visits, lifetime_visits,
                    current_punches, lifetime_punches,
                    total_rewards_earned, total_rewards_redeemed, total_reward_value
                ) VALUES (
                    v_program.id, v_customer_id, v_merchant_id,
                    0, 0, 0, 0, 0, 0, 0, 0, 0
                )
                RETURNING * INTO v_enrollment;
            ELSE
                CONTINUE;
            END IF;
        END IF;

        IF v_program.cooldown_minutes IS NOT NULL AND v_program.cooldown_minutes > 0
           AND v_enrollment.last_earn_at IS NOT NULL THEN
            IF v_enrollment.last_earn_at + (v_program.cooldown_minutes * interval '1 minute') > now() THEN
                CONTINUE;
            END IF;
        END IF;

        IF v_program.min_order_amount IS NOT NULL AND v_total < v_program.min_order_amount THEN
            CONTINUE;
        END IF;

        IF v_program.program_type = 'points' THEN
            SELECT COALESCE(SUM(
                (oi.unit_price * oi.quantity) -
                CASE WHEN NOT v_program.earn_on_discounted THEN COALESCE(oi.discount_amount, 0) ELSE 0 END
            ), 0)
            INTO v_qualifying_amount
            FROM order_items oi
            WHERE oi.order_id = p_order_id
              AND (v_program.excluded_categories IS NULL OR oi.category_id != ALL(v_program.excluded_categories))
              AND (v_program.excluded_item_ids IS NULL OR oi.menu_item_id != ALL(v_program.excluded_item_ids));

            v_points_earned := FLOOR(v_qualifying_amount * v_program.points_per_dollar);

            IF v_points_earned > 0 THEN
                UPDATE loyalty_enrollments
                SET
                    current_points = current_points + v_points_earned,
                    lifetime_points = lifetime_points + v_points_earned,
                    last_earn_at = now(),
                    updated_at = now()
                WHERE id = v_enrollment.id
                RETURNING * INTO v_enrollment;

                INSERT INTO loyalty_transactions (
                    enrollment_id, customer_id, program_id, merchant_id,
                    order_id, transaction_type,
                    points_delta, balance_points,
                    description
                ) VALUES (
                    v_enrollment.id, v_customer_id, v_program.id, v_merchant_id,
                    p_order_id, 'earn_points',
                    v_points_earned, v_enrollment.current_points,
                    'Earned ' || v_points_earned || ' points'
                );

                IF v_program.points_redemption_threshold IS NOT NULL
                   AND v_enrollment.current_points >= v_program.points_redemption_threshold
                THEN
                    INSERT INTO loyalty_rewards (
                        customer_id, enrollment_id, program_id, merchant_id,
                        reward_description, reward_type, reward_value,
                        reward_max_value, reward_category_id, reward_menu_item_id,
                        expires_at, status
                    ) VALUES (
                        v_customer_id, v_enrollment.id, v_program.id, v_merchant_id,
                        v_program.reward_description, v_program.reward_type, v_program.reward_value,
                        v_program.reward_max_value, v_program.reward_category_id, v_program.reward_menu_item_id,
                        CASE WHEN v_program.reward_expiry_days IS NOT NULL
                             THEN now() + (v_program.reward_expiry_days * interval '1 day')
                             ELSE NULL END,
                        'available'
                    ) RETURNING id INTO v_reward_id;

                    UPDATE loyalty_enrollments
                    SET
                        current_points = current_points - v_program.points_redemption_threshold,
                        total_rewards_earned = total_rewards_earned + 1
                    WHERE id = v_enrollment.id
                    RETURNING current_points INTO v_enrollment.current_points;

                    INSERT INTO loyalty_transactions (
                        enrollment_id, customer_id, program_id, merchant_id,
                        order_id, transaction_type,
                        points_delta, balance_points,
                        description, reward_id
                    ) VALUES (
                        v_enrollment.id, v_customer_id, v_program.id, v_merchant_id,
                        p_order_id, 'threshold_crossed',
                        -v_program.points_redemption_threshold, v_enrollment.current_points,
                        'Reward unlocked: ' || v_program.reward_description,
                        v_reward_id
                    );
                END IF;
            END IF;

        ELSIF v_program.program_type = 'visits' THEN
            UPDATE loyalty_enrollments
            SET
                current_visits = current_visits + 1,
                lifetime_visits = lifetime_visits + 1,
                last_earn_at = now(),
                updated_at = now()
            WHERE id = v_enrollment.id
            RETURNING * INTO v_enrollment;

            INSERT INTO loyalty_transactions (
                enrollment_id, customer_id, program_id, merchant_id,
                order_id, transaction_type,
                visits_delta, balance_visits,
                description
            ) VALUES (
                v_enrollment.id, v_customer_id, v_program.id, v_merchant_id,
                p_order_id, 'earn_visit',
                1, v_enrollment.current_visits,
                'Earned a visit'
            );

            IF v_program.visits_required IS NOT NULL
               AND v_enrollment.current_visits >= v_program.visits_required
            THEN
                INSERT INTO loyalty_rewards (
                    customer_id, enrollment_id, program_id, merchant_id,
                    reward_description, reward_type, reward_value,
                    reward_max_value, reward_category_id, reward_menu_item_id,
                    expires_at, status
                ) VALUES (
                    v_customer_id, v_enrollment.id, v_program.id, v_merchant_id,
                    v_program.reward_description, v_program.reward_type, v_program.reward_value,
                    v_program.reward_max_value, v_program.reward_category_id, v_program.reward_menu_item_id,
                    CASE WHEN v_program.reward_expiry_days IS NOT NULL
                         THEN now() + (v_program.reward_expiry_days * interval '1 day')
                         ELSE NULL END,
                    'available'
                ) RETURNING id INTO v_reward_id;

                UPDATE loyalty_enrollments
                SET
                    current_visits = 0,
                    total_rewards_earned = total_rewards_earned + 1
                WHERE id = v_enrollment.id
                RETURNING current_visits INTO v_enrollment.current_visits;

                INSERT INTO loyalty_transactions (
                    enrollment_id, customer_id, program_id, merchant_id,
                    order_id, transaction_type,
                    visits_delta, balance_visits,
                    description, reward_id
                ) VALUES (
                    v_enrollment.id, v_customer_id, v_program.id, v_merchant_id,
                    p_order_id, 'threshold_crossed',
                    -v_program.visits_required, v_enrollment.current_visits,
                    'Reward unlocked: ' || v_program.reward_description,
                    v_reward_id
                );
            END IF;

        ELSIF v_program.program_type = 'punch_card' THEN
            v_punch_earned := 0;
            FOR v_item IN
                SELECT oi.menu_item_id, oi.quantity, mi.category_id
                FROM order_items oi
                LEFT JOIN menu_items mi ON oi.menu_item_id = mi.id
                WHERE oi.order_id = p_order_id
            LOOP
                IF v_program.punch_target_type = 'item' AND v_item.menu_item_id = v_program.punch_menu_item_id THEN
                    v_punch_earned := v_punch_earned + v_item.quantity;
                ELSIF v_program.punch_target_type = 'category' AND v_item.category_id = v_program.punch_category_id THEN
                    v_punch_earned := v_punch_earned + v_item.quantity;
                END IF;
            END LOOP;

            IF v_punch_earned > 0 THEN
                UPDATE loyalty_enrollments
                SET
                    current_punches = current_punches + v_punch_earned,
                    lifetime_punches = lifetime_punches + v_punch_earned,
                    last_earn_at = now(),
                    updated_at = now()
                WHERE id = v_enrollment.id
                RETURNING * INTO v_enrollment;

                INSERT INTO loyalty_transactions (
                    enrollment_id, customer_id, program_id, merchant_id,
                    order_id, transaction_type,
                    punches_delta, balance_punches,
                    description
                ) VALUES (
                    v_enrollment.id, v_customer_id, v_program.id, v_merchant_id,
                    p_order_id, 'earn_punch',
                    v_punch_earned, v_enrollment.current_punches,
                    'Earned ' || v_punch_earned || ' punches'
                );

                IF v_program.punches_required IS NOT NULL
                   AND v_enrollment.current_punches >= v_program.punches_required
                THEN
                    INSERT INTO loyalty_rewards (
                        customer_id, enrollment_id, program_id, merchant_id,
                        reward_description, reward_type, reward_value,
                        reward_max_value, reward_category_id, reward_menu_item_id,
                        expires_at, status
                    ) VALUES (
                        v_customer_id, v_enrollment.id, v_program.id, v_merchant_id,
                        v_program.reward_description, v_program.reward_type, v_program.reward_value,
                        v_program.reward_max_value, v_program.reward_category_id, v_program.reward_menu_item_id,
                        CASE WHEN v_program.reward_expiry_days IS NOT NULL
                             THEN now() + (v_program.reward_expiry_days * interval '1 day')
                             ELSE NULL END,
                        'available'
                    ) RETURNING id INTO v_reward_id;

                    UPDATE loyalty_enrollments
                    SET
                        current_punches = current_punches - v_program.punches_required,
                        total_rewards_earned = total_rewards_earned + 1
                    WHERE id = v_enrollment.id
                    RETURNING current_punches INTO v_enrollment.current_punches;

                    INSERT INTO loyalty_transactions (
                        enrollment_id, customer_id, program_id, merchant_id,
                        order_id, transaction_type,
                        punches_delta, balance_punches,
                        description, reward_id
                    ) VALUES (
                        v_enrollment.id, v_customer_id, v_program.id, v_merchant_id,
                        p_order_id, 'threshold_crossed',
                        -v_program.punches_required, v_enrollment.current_punches,
                        'Reward unlocked: ' || v_program.reward_description,
                        v_reward_id
                    );
                END IF;
            END IF;
        END IF;

        v_result := v_result || jsonb_build_object(
            'program_name', v_program.name,
            'program_type', v_program.program_type,
            'earned', CASE v_program.program_type
                WHEN 'points' THEN v_points_earned
                WHEN 'visits' THEN 1
                WHEN 'punch_card' THEN v_punch_earned
            END,
            'new_balance', CASE v_program.program_type
                WHEN 'points' THEN v_enrollment.current_points
                WHEN 'visits' THEN v_enrollment.current_visits
                WHEN 'punch_card' THEN v_enrollment.current_punches
            END,
            'reward_unlocked', v_reward_id IS NOT NULL
        );
    END LOOP;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."loyalty_earn_on_order"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."loyalty_expire_rewards"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_reward RECORD;
BEGIN
    FOR v_reward IN
        SELECT *
        FROM loyalty_rewards
        WHERE status = 'available' AND expires_at < now()
    LOOP
        UPDATE loyalty_rewards
        SET status = 'expired'
        WHERE id = v_reward.id;

        INSERT INTO loyalty_transactions (
            enrollment_id, customer_id, program_id, merchant_id,
            transaction_type,
            description, reward_id
        ) VALUES (
            v_reward.enrollment_id, v_reward.customer_id, v_reward.program_id, v_reward.merchant_id,
            'expire',
            'Reward expired: ' || v_reward.reward_description,
            v_reward.id
        );
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."loyalty_expire_rewards"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."loyalty_get_customer_status"("p_customer_id" "uuid", "p_merchant_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    v_customer JSONB;
    v_enrollments JSONB := '[]'::JSONB;
    v_available_rewards JSONB := '[]'::JSONB;
    v_eligible_promos JSONB;
    v_record RECORD;
    v_progress NUMERIC;
BEGIN
    -- Basic customer info
    SELECT jsonb_build_object(
        'id', id,
        'name', name,
        'phone', phone,
        'tags', tags
    ) INTO v_customer
    FROM customers
    WHERE id = p_customer_id;

    -- Enrollments with progress
    FOR v_record IN
        SELECT
            e.*,
            p.name as program_name,
            p.program_type,
            p.points_redemption_threshold,
            p.visits_required,
            p.punches_required,
            p.reward_description
        FROM loyalty_enrollments e
        JOIN loyalty_programs p ON e.program_id = p.id
        WHERE e.customer_id = p_customer_id AND e.merchant_id = p_merchant_id
          AND e.is_active = true
    LOOP
        IF v_record.program_type = 'points' AND COALESCE(v_record.points_redemption_threshold, 0) > 0 THEN
            v_progress := (v_record.current_points::NUMERIC / v_record.points_redemption_threshold) * 100;
        ELSIF v_record.program_type = 'visits' AND COALESCE(v_record.visits_required, 0) > 0 THEN
            v_progress := (v_record.current_visits::NUMERIC / v_record.visits_required) * 100;
        ELSIF v_record.program_type = 'punch_card' AND COALESCE(v_record.punches_required, 0) > 0 THEN
            v_progress := (v_record.current_punches::NUMERIC / v_record.punches_required) * 100;
        ELSE
            v_progress := 0;
        END IF;

        v_enrollments := v_enrollments || jsonb_build_object(
            'program_id', v_record.program_id,
            'program_name', v_record.program_name,
            'program_type', v_record.program_type,
            'current_points', v_record.current_points,
            'points_threshold', v_record.points_redemption_threshold,
            'current_visits', v_record.current_visits,
            'visits_required', v_record.visits_required,
            'current_punches', v_record.current_punches,
            'punches_required', v_record.punches_required,
            'progress_percent', ROUND(v_progress::NUMERIC, 1),
            'next_reward', v_record.reward_description
        );
    END LOOP;

    -- Available (non-expired) rewards
    FOR v_record IN
        SELECT r.*, p.name as program_name
        FROM loyalty_rewards r
        JOIN loyalty_programs p ON r.program_id = p.id
        WHERE r.customer_id = p_customer_id
          AND r.merchant_id = p_merchant_id
          AND r.status = 'available'
          AND (r.expires_at IS NULL OR r.expires_at > now())
    LOOP
        v_available_rewards := v_available_rewards || jsonb_build_object(
            'reward_id', v_record.id,
            'description', v_record.reward_description,
            'reward_type', v_record.reward_type,
            'expires_at', v_record.expires_at,
            'program_name', v_record.program_name
        );
    END LOOP;

    -- Eligible promotions (delegate to separate function)
    SELECT get_eligible_promotions(p_customer_id, p_merchant_id, NULL, NULL, NULL)
    INTO v_eligible_promos;

    -- Assemble result matching spec shape
    RETURN jsonb_build_object(
        'customer', v_customer,
        'enrollments', v_enrollments,
        'available_rewards', v_available_rewards,
        'eligible_promotions', COALESCE(v_eligible_promos, '[]'::JSONB)
    );
END;
$$;


ALTER FUNCTION "public"."loyalty_get_customer_status"("p_customer_id" "uuid", "p_merchant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."loyalty_manual_adjust"("p_enrollment_id" "uuid", "p_adjustment_type" "text", "p_amount" integer, "p_reason" "text", "p_staff_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_enrollment RECORD;
    v_new_balance INTEGER;
BEGIN
    SELECT * INTO v_enrollment FROM loyalty_enrollments WHERE id = p_enrollment_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'Enrollment not found');
    END IF;

    CASE p_adjustment_type
        WHEN 'points' THEN
            UPDATE loyalty_enrollments
            SET
                current_points = current_points + p_amount,
                lifetime_points = lifetime_points + GREATEST(p_amount, 0),
                updated_at = now()
            WHERE id = p_enrollment_id
            RETURNING current_points INTO v_new_balance;

            INSERT INTO loyalty_transactions (
                enrollment_id, customer_id, program_id, merchant_id,
                transaction_type,
                points_delta, balance_points,
                description, staff_id
            ) VALUES (
                p_enrollment_id, v_enrollment.customer_id, v_enrollment.program_id, v_enrollment.merchant_id,
                'adjust',
                p_amount, v_new_balance,
                'Manual adjustment: ' || p_reason,
                p_staff_id
            );

        WHEN 'visits' THEN
            UPDATE loyalty_enrollments
            SET
                current_visits = current_visits + p_amount,
                lifetime_visits = lifetime_visits + GREATEST(p_amount, 0),
                updated_at = now()
            WHERE id = p_enrollment_id
            RETURNING current_visits INTO v_new_balance;

            INSERT INTO loyalty_transactions (
                enrollment_id, customer_id, program_id, merchant_id,
                transaction_type,
                visits_delta, balance_visits,
                description, staff_id
            ) VALUES (
                p_enrollment_id, v_enrollment.customer_id, v_enrollment.program_id, v_enrollment.merchant_id,
                'adjust',
                p_amount, v_new_balance,
                'Manual adjustment: ' || p_reason,
                p_staff_id
            );

        WHEN 'punches' THEN
            UPDATE loyalty_enrollments
            SET
                current_punches = current_punches + p_amount,
                lifetime_punches = lifetime_punches + GREATEST(p_amount, 0),
                updated_at = now()
            WHERE id = p_enrollment_id
            RETURNING current_punches INTO v_new_balance;

            INSERT INTO loyalty_transactions (
                enrollment_id, customer_id, program_id, merchant_id,
                transaction_type,
                punches_delta, balance_punches,
                description, staff_id
            ) VALUES (
                p_enrollment_id, v_enrollment.customer_id, v_enrollment.program_id, v_enrollment.merchant_id,
                'adjust',
                p_amount, v_new_balance,
                'Manual adjustment: ' || p_reason,
                p_staff_id
            );

        ELSE
            RETURN jsonb_build_object('error', 'Invalid adjustment type. Must be: points, visits, or punches');
    END CASE;

    RETURN jsonb_build_object('success', true, 'new_balance', v_new_balance);
END;
$$;


ALTER FUNCTION "public"."loyalty_manual_adjust"("p_enrollment_id" "uuid", "p_adjustment_type" "text", "p_amount" integer, "p_reason" "text", "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."loyalty_redeem_reward"("p_reward_id" "uuid", "p_order_id" "uuid", "p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_reward RECORD;
    v_customer_id UUID;
    v_order_total NUMERIC;
    v_enrollment RECORD;
    v_discount_amount NUMERIC;
    v_free_item_id UUID;
    v_item_price NUMERIC;
    v_discount JSONB;
BEGIN
    -- Fetch reward and validate
    SELECT r.*, p.merchant_id AS program_merchant_id
    INTO v_reward
    FROM loyalty_rewards r
    JOIN loyalty_programs p ON r.program_id = p.id
    WHERE r.id = p_reward_id AND r.status = 'available';

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'Reward not available');
    END IF;

    -- Check expiry
    IF v_reward.expires_at IS NOT NULL AND v_reward.expires_at < now() THEN
        UPDATE loyalty_rewards SET status = 'expired' WHERE id = p_reward_id;
        RETURN jsonb_build_object('error', 'Reward expired');
    END IF;

    -- Validate customer matches order
    SELECT customer_id, total_amount INTO v_customer_id, v_order_total FROM orders WHERE id = p_order_id;
    IF v_customer_id IS NULL OR v_customer_id != v_reward.customer_id THEN
        RETURN jsonb_build_object('error', 'Reward does not belong to this customer');
    END IF;

    -- Get enrollment for balance updates
    SELECT * INTO v_enrollment FROM loyalty_enrollments WHERE id = v_reward.enrollment_id;

    -- Compute discount based on reward_type
    CASE v_reward.reward_type
        WHEN 'discount_fixed' THEN
            v_discount_amount := v_reward.reward_value;

        WHEN 'discount_percent' THEN
            v_discount_amount := LEAST(
                (v_order_total * v_reward.reward_value / 100),
                COALESCE(v_reward.reward_max_value, v_order_total)
            );

        WHEN 'free_item' THEN
            v_free_item_id := v_reward.reward_menu_item_id;
            IF v_free_item_id IS NULL THEN
                RETURN jsonb_build_object('error', 'Free item reward missing menu item reference');
            END IF;
            -- Look up the item price from the order
            SELECT oi.unit_price INTO v_item_price
            FROM order_items oi
            WHERE oi.order_id = p_order_id AND oi.menu_item_id = v_free_item_id
            LIMIT 1;
            v_discount_amount := COALESCE(v_item_price, 0);

        WHEN 'free_category_item' THEN
            -- Find the cheapest qualifying category item on the order
            SELECT oi.unit_price, oi.menu_item_id INTO v_item_price, v_free_item_id
            FROM order_items oi
            LEFT JOIN menu_items mi ON oi.menu_item_id = mi.id
            WHERE oi.order_id = p_order_id
              AND mi.category_id = v_reward.reward_category_id
            ORDER BY oi.unit_price ASC
            LIMIT 1;
            v_discount_amount := COALESCE(v_item_price, 0);

        ELSE
            RETURN jsonb_build_object('error', 'Unsupported reward type');
    END CASE;

    -- Mark reward as redeemed
    UPDATE loyalty_rewards
    SET
        status = 'redeemed',
        redeemed_at = now(),
        redeemed_order_id = p_order_id,
        redeemed_location_id = p_location_id
    WHERE id = p_reward_id;

    -- Update enrollment totals
    UPDATE loyalty_enrollments
    SET
        total_rewards_redeemed = total_rewards_redeemed + 1,
        total_reward_value = total_reward_value + v_discount_amount,
        last_redeem_at = now(),
        updated_at = now()
    WHERE id = v_reward.enrollment_id;

    -- Log transaction
    INSERT INTO loyalty_transactions (
        enrollment_id, customer_id, program_id, merchant_id,
        order_id, location_id, transaction_type,
        points_delta, balance_points, punches_delta, balance_punches,
        visits_delta, balance_visits, description, reward_id
    ) VALUES (
        v_reward.enrollment_id, v_reward.customer_id, v_reward.program_id, v_reward.merchant_id,
        p_order_id, p_location_id, 'redeem',
        0, v_enrollment.current_points,
        0, v_enrollment.current_punches,
        0, v_enrollment.current_visits,
        'Redeemed: ' || v_reward.reward_description,
        p_reward_id
    );

    -- Return discount details → feeds into order_discounts with source = 'loyalty'
    v_discount := jsonb_build_object(
        'discount_type', CASE v_reward.reward_type
            WHEN 'discount_fixed' THEN 'fixed_amount'
            WHEN 'discount_percent' THEN 'percentage'
            WHEN 'free_item' THEN 'free_item'
            WHEN 'free_category_item' THEN 'free_item'
        END,
        'discount_amount', v_discount_amount,
        'discount_name', v_reward.reward_description,
        'source', 'loyalty',
        'free_item_id', v_free_item_id
    );

    RETURN v_discount;
END;
$$;


ALTER FUNCTION "public"."loyalty_redeem_reward"("p_reward_id" "uuid", "p_order_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."loyalty_void_order_earnings"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_tx RECORD;
    v_enrollment RECORD;
    v_reward RECORD;
    v_threshold_tx RECORD;
BEGIN
    FOR v_tx IN
        SELECT *
        FROM loyalty_transactions
        WHERE order_id = p_order_id
          AND transaction_type IN ('earn_points', 'earn_visit', 'earn_punch')
    LOOP
        -- Fetch current enrollment state
        SELECT * INTO v_enrollment FROM loyalty_enrollments WHERE id = v_tx.enrollment_id;

        -- Reverse balances
        UPDATE loyalty_enrollments
        SET
            current_points = current_points - COALESCE(v_tx.points_delta, 0),
            lifetime_points = lifetime_points - COALESCE(v_tx.points_delta, 0),
            current_visits = current_visits - COALESCE(v_tx.visits_delta, 0),
            lifetime_visits = lifetime_visits - COALESCE(v_tx.visits_delta, 0),
            current_punches = current_punches - COALESCE(v_tx.punches_delta, 0),
            lifetime_punches = lifetime_punches - COALESCE(v_tx.punches_delta, 0),
            updated_at = now()
        WHERE id = v_tx.enrollment_id;

        -- Log void transaction
        INSERT INTO loyalty_transactions (
            enrollment_id, customer_id, program_id, merchant_id,
            order_id, transaction_type,
            points_delta, punches_delta, visits_delta,
            balance_points, balance_punches, balance_visits,
            description
        ) VALUES (
            v_tx.enrollment_id, v_tx.customer_id, v_tx.program_id, v_tx.merchant_id,
            p_order_id, 'void',
            -COALESCE(v_tx.points_delta, 0),
            -COALESCE(v_tx.punches_delta, 0),
            -COALESCE(v_tx.visits_delta, 0),
            v_enrollment.current_points - COALESCE(v_tx.points_delta, 0),
            v_enrollment.current_punches - COALESCE(v_tx.punches_delta, 0),
            v_enrollment.current_visits - COALESCE(v_tx.visits_delta, 0),
            'Voided earnings from order ' || p_order_id
        );

        -- Void any unredeemed rewards linked via threshold_crossed transactions for this order
        FOR v_threshold_tx IN
            SELECT *
            FROM loyalty_transactions
            WHERE order_id = p_order_id
              AND enrollment_id = v_tx.enrollment_id
              AND transaction_type = 'threshold_crossed'
              AND reward_id IS NOT NULL
        LOOP
            -- Check reward status before voiding
            SELECT * INTO v_reward FROM loyalty_rewards WHERE id = v_threshold_tx.reward_id;

            IF v_reward.status = 'available' THEN
                -- Safe to void — not yet redeemed
                UPDATE loyalty_rewards
                SET status = 'voided', voided_at = now(), voided_reason = 'Order voided'
                WHERE id = v_reward.id;

                -- Decrement total_rewards_earned
                UPDATE loyalty_enrollments
                SET total_rewards_earned = GREATEST(total_rewards_earned - 1, 0)
                WHERE id = v_tx.enrollment_id;
            ELSIF v_reward.status = 'redeemed' THEN
                -- Already redeemed → flag for manager review, do NOT auto-claw-back
                UPDATE loyalty_rewards
                SET voided_reason = 'REVIEW: Order voided but reward was already redeemed'
                WHERE id = v_reward.id;
            END IF;
        END LOOP;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."loyalty_void_order_earnings"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manage_order_discount"("p_action" "text", "p_order_id" "uuid", "p_staff_id" "uuid", "p_discount_id" "uuid" DEFAULT NULL::"uuid", "p_discount_name" "text" DEFAULT NULL::"text", "p_discount_type" "text" DEFAULT NULL::"text", "p_discount_value" numeric DEFAULT NULL::numeric, "p_source" "text" DEFAULT 'preset'::"text", "p_reason" "text" DEFAULT NULL::"text", "p_applied_to_item_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_approved_by_staff_id" "uuid" DEFAULT NULL::"uuid", "p_order_discount_id" "uuid" DEFAULT NULL::"uuid", "p_void_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$DECLARE
    v_order RECORD;
    v_discount RECORD;
    v_is_preset_discount BOOLEAN := false;
    v_order_discount_id UUID;
    v_calculated_amount NUMERIC := 0;
    v_pre_discount_subtotal NUMERIC;
    v_applicable_subtotal NUMERIC;
    v_calculated_cash_amount NUMERIC := 0;
    v_pre_discount_cash_subtotal NUMERIC;
    v_applicable_cash_subtotal NUMERIC;
    v_discount_type TEXT;
    v_discount_value NUMERIC;
    v_discount_name TEXT;
    v_requires_approval BOOLEAN := false;
    v_max_discount_amount NUMERIC;
    v_is_stackable BOOLEAN := true;
    v_has_non_stackable BOOLEAN := false;
    
    v_item RECORD;
    v_item_discount_amount NUMERIC;
    v_item_proportion NUMERIC;
    v_distributed_total NUMERIC := 0;
    v_last_item_id UUID;
    v_affected_item_ids UUID[] := '{}';
    
    v_total_discount_amount NUMERIC := 0;
    v_new_card_subtotal NUMERIC;
    v_new_cash_subtotal NUMERIC;
    v_new_card_tax NUMERIC;
    v_new_cash_tax NUMERIC;
    v_new_card_total NUMERIC;
    v_new_cash_total NUMERIC;
    v_new_amount_due NUMERIC;
    v_new_cash_amount_due NUMERIC;
    v_tax_rate NUMERIC;
    
    v_original_card_subtotal NUMERIC;
    v_original_cash_subtotal NUMERIC;
    
    v_voided_discount RECORD;
    v_voided_calculated_amount NUMERIC := 0;
BEGIN
    SELECT * INTO v_order
    FROM public.orders
    WHERE id = p_order_id
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids());
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Order not found or access denied');
    END IF;
    
    IF v_order.payment_status = 'paid' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot modify discounts on a paid order');
    END IF;
    
    IF v_order.voided_at IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot modify discounts on a voided order');
    END IF;
    
    SELECT 
        COALESCE(SUM(oi.quantity * oi.unit_price), 0),
        COALESCE(SUM(oi.quantity * COALESCE(oi.cash_price, oi.unit_price)), 0)
    INTO v_original_card_subtotal, v_original_cash_subtotal
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id AND oi.is_voided = false;
    
    IF v_order.card_subtotal > 0 AND v_order.card_tax_amount > 0 THEN
        v_tax_rate := ROUND((v_order.card_tax_amount / v_order.card_subtotal) * 100, 4);
    ELSE
        SELECT COALESCE(tax_rate, 0) INTO v_tax_rate
        FROM public.order_items
        WHERE order_id = p_order_id AND is_voided = false
        LIMIT 1;
    END IF;
    
    CASE p_action
    
    WHEN 'apply' THEN
        
        IF p_discount_name IS NULL OR p_discount_name = '' THEN
            RETURN jsonb_build_object('success', false, 'error', 'discount_name is required');
        END IF;
        
        IF p_discount_type IS NULL AND p_discount_id IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'Either discount_id or discount_type must be provided');
        END IF;
        
        IF p_discount_id IS NOT NULL THEN
            SELECT * INTO v_discount
            FROM public.discounts
            WHERE id = p_discount_id
              AND merchant_id = v_order.merchant_id
              AND is_active = true;
            
            IF NOT FOUND THEN
                RETURN jsonb_build_object('success', false, 'error', 'Discount not found or inactive');
            END IF;
            
            v_is_preset_discount := true;
            
            v_discount_type := v_discount.discount_type;
            v_discount_value := v_discount.discount_value;
            v_discount_name := COALESCE(p_discount_name, v_discount.name);
            v_requires_approval := COALESCE(v_discount.requires_manager_approval, false);
            v_max_discount_amount := v_discount.max_discount_amount;
            v_is_stackable := COALESCE(v_discount.stackable, false);
            
            IF v_discount.start_date IS NOT NULL AND v_discount.start_date > CURRENT_DATE THEN
                RETURN jsonb_build_object('success', false, 'error', 'Discount has not started yet');
            END IF;
            
            IF v_discount.end_date IS NOT NULL AND v_discount.end_date < CURRENT_DATE THEN
                RETURN jsonb_build_object('success', false, 'error', 'Discount has expired');
            END IF;
            
            IF v_discount.applicable_days IS NOT NULL AND 
               NOT (EXTRACT(DOW FROM CURRENT_TIMESTAMP)::integer = ANY(v_discount.applicable_days)) THEN
                RETURN jsonb_build_object('success', false, 'error', 'Discount not valid today');
            END IF;
            
            IF v_discount.applicable_hours_start IS NOT NULL AND v_discount.applicable_hours_end IS NOT NULL THEN
                DECLARE
                    v_current_time TIME := CURRENT_TIME;
                    v_in_window BOOLEAN;
                BEGIN
                    IF v_discount.applicable_hours_start > v_discount.applicable_hours_end THEN
                        v_in_window := v_current_time >= v_discount.applicable_hours_start 
                                    OR v_current_time <= v_discount.applicable_hours_end;
                    ELSE
                        v_in_window := v_current_time >= v_discount.applicable_hours_start 
                                   AND v_current_time <= v_discount.applicable_hours_end;
                    END IF;
                    
                    IF NOT v_in_window THEN
                        RETURN jsonb_build_object(
                            'success', false,
                            'error', format('Discount only valid between %s and %s', 
                                v_discount.applicable_hours_start::text, 
                                v_discount.applicable_hours_end::text)
                        );
                    END IF;
                END;
            END IF;
            
            IF v_discount.scope IS NOT NULL AND v_discount.scope::text <> 'both' THEN
                IF v_discount.scope::text = 'dine_in' AND v_order.order_type::text NOT IN ('dine_in') THEN
                    RETURN jsonb_build_object('success', false, 'error', 'Discount only valid for dine-in orders');
                END IF;
                IF v_discount.scope::text = 'takeout' AND v_order.order_type::text NOT IN ('takeout', 'delivery') THEN
                    RETURN jsonb_build_object('success', false, 'error', 'Discount only valid for takeout orders');
                END IF;
            END IF;
            
            IF v_requires_approval AND p_approved_by_staff_id IS NULL THEN
                RETURN jsonb_build_object('success', false, 'error', 'This discount requires manager approval', 'requires_approval', true);
            END IF;
            
            SELECT EXISTS(
                SELECT 1 FROM public.order_discounts od
                LEFT JOIN public.discounts d ON d.id = od.discount_id
                WHERE od.order_id = p_order_id AND od.voided_at IS NULL AND COALESCE(d.stackable, false) = false
            ) INTO v_has_non_stackable;
            
            IF v_has_non_stackable AND NOT v_is_stackable THEN
                RETURN jsonb_build_object('success', false, 'error', 'Cannot combine with existing non-stackable discount');
            END IF;
            
            IF NOT v_is_stackable THEN
                IF EXISTS (SELECT 1 FROM public.order_discounts WHERE order_id = p_order_id AND voided_at IS NULL) THEN
                    RETURN jsonb_build_object('success', false, 'error', 'This discount cannot be combined with other discounts');
                END IF;
            END IF;
            
            IF v_discount.max_uses_per_order IS NOT NULL THEN
                DECLARE v_current_uses INTEGER;
                BEGIN
                    SELECT COUNT(*) INTO v_current_uses
                    FROM public.order_discounts
                    WHERE order_id = p_order_id AND discount_id = p_discount_id AND voided_at IS NULL;
                    
                    IF v_current_uses >= v_discount.max_uses_per_order THEN
                        RETURN jsonb_build_object('success', false, 'error', format('Discount can only be used %s time(s) per order', v_discount.max_uses_per_order));
                    END IF;
                END;
            END IF;
            
        ELSE
            v_discount_type := p_discount_type;
            v_discount_value := p_discount_value;
            v_discount_name := p_discount_name;
            
            IF p_approved_by_staff_id IS NULL THEN
                RETURN jsonb_build_object('success', false, 'error', 'Custom discounts require manager approval', 'requires_approval', true);
            END IF;
        END IF;
        
        IF v_discount_value IS NULL OR v_discount_value <= 0 THEN
            RETURN jsonb_build_object('success', false, 'error', 'Discount value must be greater than 0');
        END IF;
        
        IF v_discount_type = 'percentage' AND v_discount_value > 100 THEN
            RETURN jsonb_build_object('success', false, 'error', 'Percentage discount cannot exceed 100%');
        END IF;
        
        IF p_applied_to_item_ids IS NOT NULL AND array_length(p_applied_to_item_ids, 1) > 0 THEN
            SELECT COALESCE(SUM((oi.quantity - COALESCE(oi.paid_quantity, 0)) * oi.unit_price), 0),
                   COALESCE(SUM((oi.quantity - COALESCE(oi.paid_quantity, 0)) * COALESCE(oi.cash_price, oi.unit_price)), 0)
            INTO v_applicable_subtotal, v_applicable_cash_subtotal
            FROM public.order_items oi
            WHERE oi.id = ANY(p_applied_to_item_ids)
              AND oi.order_id = p_order_id AND oi.is_voided = false
              AND oi.quantity > COALESCE(oi.paid_quantity, 0);
            
            SELECT array_agg(id) INTO v_affected_item_ids
            FROM public.order_items
            WHERE id = ANY(p_applied_to_item_ids) AND order_id = p_order_id
              AND is_voided = false AND quantity > COALESCE(paid_quantity, 0);
        ELSE
            SELECT COALESCE(SUM((oi.quantity - COALESCE(oi.paid_quantity, 0)) * oi.unit_price), 0),
                   COALESCE(SUM((oi.quantity - COALESCE(oi.paid_quantity, 0)) * COALESCE(oi.cash_price, oi.unit_price)), 0),
                   array_agg(oi.id)
            INTO v_applicable_subtotal, v_applicable_cash_subtotal, v_affected_item_ids
            FROM public.order_items oi
            WHERE oi.order_id = p_order_id AND oi.is_voided = false
              AND oi.quantity > COALESCE(oi.paid_quantity, 0);
        END IF;
        
        -- Apply exclusions for preset discounts only
        IF v_is_preset_discount THEN
            IF COALESCE(v_discount.exclude_alcohol, false) THEN
                SELECT COALESCE(SUM((oi.quantity - COALESCE(oi.paid_quantity, 0)) * oi.unit_price), 0),
                       COALESCE(SUM((oi.quantity - COALESCE(oi.paid_quantity, 0)) * COALESCE(oi.cash_price, oi.unit_price)), 0),
                       array_agg(oi.id)
                INTO v_applicable_subtotal, v_applicable_cash_subtotal, v_affected_item_ids
                FROM public.order_items oi
                LEFT JOIN public.menu_items mi ON mi.id = oi.menu_item_id
                WHERE oi.order_id = p_order_id AND oi.is_voided = false
                  AND oi.quantity > COALESCE(oi.paid_quantity, 0)
                  AND (p_applied_to_item_ids IS NULL OR oi.id = ANY(p_applied_to_item_ids))
                  AND COALESCE(mi.is_alcohol, false) = false;
            END IF;
            
            IF v_discount.exclude_categories IS NOT NULL THEN
                SELECT COALESCE(SUM((oi.quantity - COALESCE(oi.paid_quantity, 0)) * oi.unit_price), 0),
                       COALESCE(SUM((oi.quantity - COALESCE(oi.paid_quantity, 0)) * COALESCE(oi.cash_price, oi.unit_price)), 0),
                       array_agg(oi.id)
                INTO v_applicable_subtotal, v_applicable_cash_subtotal, v_affected_item_ids
                FROM public.order_items oi
                WHERE oi.order_id = p_order_id AND oi.is_voided = false
                  AND oi.quantity > COALESCE(oi.paid_quantity, 0)
                  AND (p_applied_to_item_ids IS NULL OR oi.id = ANY(p_applied_to_item_ids))
                  AND NOT EXISTS (
                      SELECT 1 FROM public.menu_items mi
                      WHERE mi.id = oi.menu_item_id
                        AND mi.category_id = ANY(v_discount.exclude_categories)
                  );
            END IF;
            
            IF v_discount.applies_to_categories IS NOT NULL THEN
                SELECT COALESCE(SUM((oi.quantity - COALESCE(oi.paid_quantity, 0)) * oi.unit_price), 0),
                       COALESCE(SUM((oi.quantity - COALESCE(oi.paid_quantity, 0)) * COALESCE(oi.cash_price, oi.unit_price)), 0),
                       array_agg(oi.id)
                INTO v_applicable_subtotal, v_applicable_cash_subtotal, v_affected_item_ids
                FROM public.order_items oi
                LEFT JOIN public.menu_items mi ON mi.id = oi.menu_item_id
                WHERE oi.order_id = p_order_id AND oi.is_voided = false
                  AND oi.quantity > COALESCE(oi.paid_quantity, 0)
                  AND (p_applied_to_item_ids IS NULL OR oi.id = ANY(p_applied_to_item_ids))
                  AND mi.category_id = ANY(v_discount.applies_to_categories);
            END IF;
        END IF;
        
        IF v_applicable_subtotal <= 0 THEN
            RETURN jsonb_build_object('success', false, 'error', 'No applicable items for this discount');
        END IF;
        
        -- FIX: Use nested IF instead of AND to avoid accessing unassigned record
        IF v_is_preset_discount THEN
            IF v_discount.min_purchase_amount IS NOT NULL THEN
                IF v_applicable_subtotal < v_discount.min_purchase_amount THEN
                    RETURN jsonb_build_object('success', false, 'error', format('Minimum purchase of $%s required', ROUND(v_discount.min_purchase_amount, 2)));
                END IF;
            END IF;
        END IF;
        
        v_pre_discount_subtotal := v_applicable_subtotal;
        v_pre_discount_cash_subtotal := v_applicable_cash_subtotal;

        IF v_discount_type = 'percentage' THEN
            v_calculated_amount := ROUND(v_applicable_subtotal * (v_discount_value / 100), 2);
            v_calculated_cash_amount := ROUND(v_applicable_cash_subtotal * (v_discount_value / 100), 2);
            IF v_max_discount_amount IS NOT NULL THEN
                v_calculated_amount := LEAST(v_calculated_amount, v_max_discount_amount);
                v_calculated_cash_amount := LEAST(v_calculated_cash_amount, v_max_discount_amount);
            END IF;
        ELSE
            v_calculated_amount := LEAST(v_discount_value, v_applicable_subtotal);
            v_calculated_cash_amount := LEAST(v_discount_value, v_applicable_cash_subtotal);
        END IF;
        
        INSERT INTO public.order_discounts (
            order_id, discount_id, discount_name, discount_type, discount_value, source,
            calculated_amount, pre_discount_subtotal, calculated_cash_amount, pre_discount_cash_subtotal,
            applied_by_staff_profiles_id, approved_by_staff_profiles_id, applied_at, applied_to_item_ids, reason
        ) VALUES (
            p_order_id, p_discount_id, v_discount_name, v_discount_type::discount_type,
            v_discount_value, p_source::discount_source, v_calculated_amount, v_pre_discount_subtotal,
            v_calculated_cash_amount, v_pre_discount_cash_subtotal,
            p_staff_id, p_approved_by_staff_id, now(), v_affected_item_ids, p_reason
        ) RETURNING id INTO v_order_discount_id;
        
        v_distributed_total := 0;
        v_last_item_id := NULL;
        
        FOR v_item IN
            SELECT oi.id, oi.quantity, oi.paid_quantity, oi.unit_price, oi.cash_price, oi.tax_rate,
                   ((oi.quantity - COALESCE(oi.paid_quantity, 0)) * oi.unit_price) as item_subtotal
            FROM public.order_items oi
            WHERE oi.id = ANY(v_affected_item_ids) AND oi.is_voided = false
            ORDER BY oi.created_at, oi.id
        LOOP
            IF v_applicable_subtotal > 0 THEN
                v_item_proportion := v_item.item_subtotal / v_applicable_subtotal;
            ELSE
                v_item_proportion := 0;
            END IF;
            
            v_item_discount_amount := ROUND(v_calculated_amount * v_item_proportion, 2);
            v_distributed_total := v_distributed_total + v_item_discount_amount;
            v_last_item_id := v_item.id;
            
            UPDATE public.order_items
            SET
                discount_id = p_discount_id,
                discount_type = v_discount_type::discount_type,
                discount_value = v_discount_value,
                discount_amount = COALESCE(discount_amount, 0) + v_item_discount_amount,
                discount_source = p_source::discount_source,
                discount_applied_by = p_staff_id,
                discount_approved_by = p_approved_by_staff_id,
                pre_discount_subtotal = CASE WHEN pre_discount_subtotal IS NULL THEN v_item.item_subtotal ELSE pre_discount_subtotal END,
                subtotal = (quantity * unit_price) - (COALESCE(discount_amount, 0) + v_item_discount_amount),
                cash_subtotal = (quantity * COALESCE(cash_price, unit_price)) - 
                    ROUND((COALESCE(discount_amount, 0) + v_item_discount_amount) * COALESCE(cash_price, unit_price) / NULLIF(unit_price, 0), 2),
                tax_amount = ROUND(((quantity * unit_price) - (COALESCE(discount_amount, 0) + v_item_discount_amount)) * COALESCE(tax_rate, 0) / 100, 2),
                cash_tax_amount = ROUND(((quantity * COALESCE(cash_price, unit_price)) - 
                    ROUND((COALESCE(discount_amount, 0) + v_item_discount_amount) * COALESCE(cash_price, unit_price) / NULLIF(unit_price, 0), 2)) * COALESCE(tax_rate, 0) / 100, 2),
                updated_at = now()
            WHERE id = v_item.id;
        END LOOP;
        
        IF v_last_item_id IS NOT NULL AND v_distributed_total <> v_calculated_amount THEN
            UPDATE public.order_items
            SET
                discount_amount = discount_amount + (v_calculated_amount - v_distributed_total),
                subtotal = subtotal - (v_calculated_amount - v_distributed_total),
                tax_amount = ROUND(subtotal * COALESCE(tax_rate, 0) / 100, 2),
                updated_at = now()
            WHERE id = v_last_item_id;
        END IF;
    
    WHEN 'void' THEN
        
        IF p_order_discount_id IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'order_discount_id is required for void action');
        END IF;
        
        SELECT * INTO v_voided_discount
        FROM public.order_discounts
        WHERE id = p_order_discount_id AND order_id = p_order_id AND voided_at IS NULL;
        
        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'error', 'Discount not found or already voided');
        END IF;
        
        v_order_discount_id := p_order_discount_id;
        v_affected_item_ids := v_voided_discount.applied_to_item_ids;
        v_calculated_amount := v_voided_discount.calculated_amount;

        UPDATE public.order_discounts
        SET voided_at = now(), voided_by = p_staff_id, void_reason = p_void_reason
        WHERE id = p_order_discount_id;
        
        IF v_affected_item_ids IS NOT NULL AND array_length(v_affected_item_ids, 1) > 0 THEN
            UPDATE public.order_items
            SET
                discount_id = NULL, discount_type = NULL, discount_value = 0, discount_amount = 0,
                discount_source = NULL, discount_applied_by = NULL, discount_approved_by = NULL,
                subtotal = quantity * unit_price,
                cash_subtotal = quantity * COALESCE(cash_price, unit_price),
                tax_amount = ROUND((quantity * unit_price) * COALESCE(tax_rate, 0) / 100, 2),
                cash_tax_amount = ROUND((quantity * COALESCE(cash_price, unit_price)) * COALESCE(tax_rate, 0) / 100, 2),
                updated_at = now()
            WHERE id = ANY(v_affected_item_ids) AND order_id = p_order_id AND is_voided = false;
        END IF;
    
    ELSE
        RETURN jsonb_build_object('success', false, 'error', format('Unknown action: %s', p_action));
    END CASE;
    
    SELECT 
        COALESCE(SUM(oi.subtotal), 0), COALESCE(SUM(oi.cash_subtotal), 0),
        COALESCE(SUM(oi.tax_amount), 0), COALESCE(SUM(oi.cash_tax_amount), 0),
        COALESCE(SUM(oi.discount_amount), 0)
    INTO v_new_card_subtotal, v_new_cash_subtotal, v_new_card_tax, v_new_cash_tax, v_total_discount_amount
    FROM public.order_items oi WHERE oi.order_id = p_order_id AND oi.is_voided = false;
    
    v_new_card_total := v_new_card_subtotal + v_new_card_tax;
    v_new_cash_total := v_new_cash_subtotal + v_new_cash_tax;
    
    SELECT
        COALESCE(SUM(
            ROUND(oi.subtotal * (oi.quantity - COALESCE(oi.paid_quantity, 0))::NUMERIC / NULLIF(oi.quantity, 0), 2) +
            ROUND(oi.tax_amount * (oi.quantity - COALESCE(oi.paid_quantity, 0))::NUMERIC / NULLIF(oi.quantity, 0), 2)
        ), 0),
        COALESCE(SUM(
            ROUND(oi.cash_subtotal * (oi.quantity - COALESCE(oi.paid_quantity, 0))::NUMERIC / NULLIF(oi.quantity, 0), 2) +
            ROUND(oi.cash_tax_amount * (oi.quantity - COALESCE(oi.paid_quantity, 0))::NUMERIC / NULLIF(oi.quantity, 0), 2)
        ), 0)
    INTO v_new_amount_due, v_new_cash_amount_due
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id AND oi.is_voided = false
      AND oi.quantity > COALESCE(oi.paid_quantity, 0);
    
    UPDATE public.orders SET
        card_subtotal = v_original_card_subtotal, cash_subtotal = v_original_cash_subtotal,
        discount_amount = v_total_discount_amount, effective_subtotal = v_new_card_subtotal,
        effective_tax_amount = v_new_card_tax, effective_total = v_new_card_total,
        card_tax_amount = v_new_card_tax, cash_tax_amount = v_new_cash_tax,
        card_total = v_new_card_total, cash_total = v_new_cash_total, total_amount = v_new_card_total,
        amount_due = v_new_amount_due, cash_amount_due = v_new_cash_amount_due, updated_at = now()
    WHERE id = p_order_id;
    
    RETURN jsonb_build_object(
        'success', true, 'action', p_action, 'order_discount_id', v_order_discount_id, 'calculated_amount', v_calculated_amount,
        'discount', CASE WHEN p_action = 'apply' THEN jsonb_build_object(
            'id', v_order_discount_id, 'discount_id', p_discount_id, 'discount_name', v_discount_name,
            'discount_type', v_discount_type, 'discount_value', v_discount_value, 'source', p_source,
            'calculated_amount', v_calculated_amount, 'calculated_cash_amount', v_calculated_cash_amount, 'applied_to_item_ids', v_affected_item_ids
        ) ELSE NULL END,
        'order', jsonb_build_object(
            'id', p_order_id, 'card_subtotal', v_original_card_subtotal, 'cash_subtotal', v_original_cash_subtotal,
            'discount_amount', v_total_discount_amount, 'effective_subtotal', v_new_card_subtotal,
            'effective_tax_amount', v_new_card_tax, 'effective_total', v_new_card_total,
            'card_tax_amount', v_new_card_tax, 'cash_tax_amount', v_new_cash_tax,
            'card_total', v_new_card_total, 'cash_total', v_new_cash_total,
            'amount_due', v_new_amount_due, 'cash_amount_due', v_new_cash_amount_due, 'amount_paid', v_order.amount_paid
        ),
        'affected_items', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'id', oi.id, 'item_name', oi.item_name, 'quantity', oi.quantity, 'unit_price', oi.unit_price,
                'cash_price', oi.cash_price, 'discount_amount', oi.discount_amount, 'subtotal', oi.subtotal,
                'cash_subtotal', oi.cash_subtotal, 'tax_amount', oi.tax_amount, 'cash_tax_amount', oi.cash_tax_amount
            ) ORDER BY oi.display_order, oi.created_at), '[]'::jsonb)
            FROM public.order_items oi WHERE oi.id = ANY(v_affected_item_ids) AND oi.is_voided = false
        ),
        'active_discounts', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'id', od.id, 'discount_id', od.discount_id, 'discount_name', od.discount_name,
                'discount_type', od.discount_type, 'discount_value', od.discount_value, 'source', od.source,
                'calculated_amount', od.calculated_amount, 'applied_to_item_ids', od.applied_to_item_ids,
                'applied_at', od.applied_at, 'applied_by', od.applied_by_staff_profiles_id,
                'approved_by', od.approved_by_staff_profiles_id, 'reason', od.reason
            ) ORDER BY od.applied_at), '[]'::jsonb)
            FROM public.order_discounts od WHERE od.order_id = p_order_id AND od.voided_at IS NULL
        )
    );
END;$_$;


ALTER FUNCTION "public"."manage_order_discount"("p_action" "text", "p_order_id" "uuid", "p_staff_id" "uuid", "p_discount_id" "uuid", "p_discount_name" "text", "p_discount_type" "text", "p_discount_value" numeric, "p_source" "text", "p_reason" "text", "p_applied_to_item_ids" "uuid"[], "p_approved_by_staff_id" "uuid", "p_order_discount_id" "uuid", "p_void_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_course_served"("p_order_id" "uuid", "p_course_number" integer, "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_course_id UUID;
  v_session_id UUID;
BEGIN
  -- Get course
  SELECT id INTO v_course_id
  FROM public.order_courses
  WHERE order_id = p_order_id AND course_number = p_course_number;

  IF v_course_id IS NULL THEN
    RAISE EXCEPTION 'Course not found';
  END IF;

  -- Update to served
  UPDATE public.order_courses
  SET status = 'served', served_at = NOW()
  WHERE id = v_course_id;

  -- Record event on session
  SELECT ts.id INTO v_session_id
  FROM public.table_sessions ts
  WHERE ts.order_id = p_order_id AND ts.is_active = TRUE;

  IF v_session_id IS NOT NULL THEN
    INSERT INTO public.table_session_events (
      session_id, event_type, event_data,
      triggered_by_staff_id, triggered_by_user_id
    ) VALUES (
      v_session_id,
      CASE p_course_number
        WHEN 1 THEN 'appetizers_served'::public.session_event_type
        WHEN 2 THEN 'mains_served'::public.session_event_type
        WHEN 3 THEN 'desserts_served'::public.session_event_type
        ELSE 'custom'::public.session_event_type
      END,
      jsonb_build_object('course_number', p_course_number),
      COALESCE(p_staff_id, user_staff_profile_id()),
      get_my_claim('sub')
    );

    -- Update food_served_at if not set
    UPDATE public.table_sessions
    SET food_served_at = COALESCE(food_served_at, NOW())
    WHERE id = v_session_id;
  END IF;

  RETURN json_build_object(
    'success', true,
    'course_number', p_course_number,
    'status', 'served'
  );
END;
$$;


ALTER FUNCTION "public"."mark_course_served"("p_order_id" "uuid", "p_course_number" integer, "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_stale_stations_offline"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  UPDATE stations
  SET is_online = FALSE
  WHERE is_online = TRUE
    AND last_heartbeat_at < NOW() - INTERVAL '3 minutes';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."mark_stale_stations_offline"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_customers"("p_primary_id" "uuid", "p_duplicate_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_merchant_id uuid;
  v_primary_name text;
  v_new_spend numeric := 0;
  v_new_visits bigint := 0;
  v_new_last_visit timestamptz;
  v_new_total_orders bigint := 0;
  v_merged_tags text[];
  v_duplicate_count int;
BEGIN

  -- =====================================
  -- 1️⃣ Basic Input Validation
  -- =====================================

  IF p_duplicate_ids IS NULL 
     OR array_length(p_duplicate_ids, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No duplicate IDs provided'
    );
  END IF;

  IF p_primary_id = ANY(p_duplicate_ids) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Primary ID cannot be included in duplicate IDs'
    );
  END IF;

  -- =====================================
  -- 2️⃣ Lock Primary Customer Row
  -- =====================================

  SELECT merchant_id, name
  INTO v_merchant_id, v_primary_name
  FROM customers
  WHERE id = p_primary_id
  FOR UPDATE;

  IF v_merchant_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Primary customer not found'
    );
  END IF;

  -- =====================================
  -- 3️⃣ Validate + Lock Duplicate Rows
  -- =====================================

  SELECT COUNT(*)
  INTO v_duplicate_count
  FROM customers
  WHERE id = ANY(p_duplicate_ids)
    AND merchant_id = v_merchant_id
  FOR UPDATE;

  IF v_duplicate_count <> array_length(p_duplicate_ids, 1) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'One or more duplicate IDs invalid or cross-merchant'
    );
  END IF;

  -- =====================================
  -- 4️⃣ Aggregate Duplicate Totals
  -- =====================================

  SELECT
    COALESCE(SUM(lifetime_spend), 0),
    COALESCE(SUM(visits), 0),
    MAX(last_visit),
    COALESCE(SUM(total_orders), 0)
  INTO
    v_new_spend,
    v_new_visits,
    v_new_last_visit,
    v_new_total_orders
  FROM customers
  WHERE id = ANY(p_duplicate_ids)
    AND merchant_id = v_merchant_id;

  -- =====================================
  -- 5️⃣ Merge Tags (Set Union)
  -- =====================================

  SELECT array_agg(DISTINCT tag)
  INTO v_merged_tags
  FROM (
    SELECT unnest(tags) AS tag
    FROM customers
    WHERE (id = p_primary_id OR id = ANY(p_duplicate_ids))
      AND merchant_id = v_merchant_id
      AND tags IS NOT NULL
  ) t
  WHERE tag IS NOT NULL;

  -- =====================================
  -- 6️⃣ Reassign Orders
  -- =====================================

  UPDATE orders
  SET customer_id = p_primary_id,
      updated_at = NOW()
  WHERE customer_id = ANY(p_duplicate_ids)
    AND merchant_id = v_merchant_id;

  -- =====================================
  -- 7️⃣ Reassign Customer Activities
  -- =====================================

  UPDATE customer_activities
  SET customer_id = p_primary_id,
      updated_at = NOW()
  WHERE customer_id = ANY(p_duplicate_ids)
    AND merchant_id = v_merchant_id;

  -- =====================================
  -- 8️⃣ Update Primary Customer
  -- =====================================

  UPDATE customers
  SET
    lifetime_spend = lifetime_spend + v_new_spend,
    visits = visits + v_new_visits,
    last_visit = CASE
      WHEN v_new_last_visit IS NOT NULL
           AND (last_visit IS NULL OR v_new_last_visit > last_visit)
      THEN v_new_last_visit
      ELSE last_visit
    END,
    tags = COALESCE(v_merged_tags, tags),
    total_orders = total_orders + v_new_total_orders,
    updated_at = NOW()
  WHERE id = p_primary_id
    AND merchant_id = v_merchant_id;

  -- =====================================
  -- 9️⃣ Delete Duplicate Customers
  -- =====================================

  DELETE FROM customers
  WHERE id = ANY(p_duplicate_ids)
    AND merchant_id = v_merchant_id;

  -- =====================================
  -- 10️⃣ Success Response
  -- =====================================

  RETURN jsonb_build_object(
    'success', true,
    'primary_id', p_primary_id,
    'primary_name', v_primary_name,
    'merged_count', v_duplicate_count,
    'merged_ids', p_duplicate_ids,
    'combined_spend', v_new_spend,
    'combined_visits', v_new_visits
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM,
    'detail', SQLSTATE
  );
END;
$$;


ALTER FUNCTION "public"."merge_customers"("p_primary_id" "uuid", "p_duplicate_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_table_to_session"("p_session_id" "uuid", "p_table_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_position INTEGER;
BEGIN
  -- Verify session
  IF NOT EXISTS (
    SELECT 1 FROM public.table_sessions
    WHERE id = p_session_id AND is_active = TRUE
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids())
  ) THEN
    RAISE EXCEPTION 'Session not found';
  END IF;

  -- Check table is available
  IF EXISTS (
    SELECT 1 FROM public.table_session_tables tst
    JOIN public.table_sessions ts ON ts.id = tst.session_id
    WHERE tst.table_id = p_table_id AND ts.is_active = TRUE
  ) THEN
    RAISE EXCEPTION 'Table is already occupied';
  END IF;

  -- Get next position
  SELECT COALESCE(MAX(seated_position), 0) + 1 INTO v_position
  FROM public.table_session_tables
  WHERE session_id = p_session_id;

  -- Add table
  INSERT INTO public.table_session_tables (session_id, table_id, is_primary, seated_position)
  VALUES (p_session_id, p_table_id, FALSE, v_position);

  RETURN json_build_object(
    'success', true,
    'session_id', p_session_id,
    'merged_table_id', p_table_id
  );
END;
$$;


ALTER FUNCTION "public"."merge_table_to_session"("p_session_id" "uuid", "p_table_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."migrate_menu_items_to_categories"() RETURNS json
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_migrated INTEGER := 0;
    v_default_category_id UUID;
    v_merchant_id UUID;
BEGIN
    -- For each unique merchant that has menu_item_menus records
    FOR v_merchant_id IN 
        SELECT DISTINCT mi.merchant_id 
        FROM menu_item_menus mim
        JOIN menu_items mi ON mi.id = mim.menu_item_id
        WHERE mim.is_migrated = false
    LOOP
        -- Create or get "Uncategorized" category for this merchant
        INSERT INTO categories (merchant_id, name, description, is_active)
        VALUES (v_merchant_id, 'Uncategorized', 'Items without a specific category', true)
        ON CONFLICT DO NOTHING;
        
        SELECT id INTO v_default_category_id 
        FROM categories 
        WHERE merchant_id = v_merchant_id AND name = 'Uncategorized'
        LIMIT 1;
        
        -- Migrate items that don't have category assignments
        INSERT INTO category_items (category_id, menu_item_id, display_order, is_available)
        SELECT DISTINCT 
            v_default_category_id,
            mim.menu_item_id,
            0,
            mim.is_available
        FROM menu_item_menus mim
        JOIN menu_items mi ON mi.id = mim.menu_item_id
        WHERE mi.merchant_id = v_merchant_id
          AND NOT EXISTS (
              SELECT 1 FROM category_items ci 
              WHERE ci.menu_item_id = mim.menu_item_id
          )
        ON CONFLICT (category_id, menu_item_id) DO NOTHING;
        
        -- Add category to menus that had these items
        INSERT INTO menu_categories (menu_id, category_id, display_order, is_active, merchant_id)
        SELECT DISTINCT 
            mim.menu_id,
            v_default_category_id,
            0,
            true,
            '2add44cb-f498-4653-aca3-a8f0ca258e70'::uuid
        FROM menu_item_menus mim
        JOIN menu_items mi ON mi.id = mim.menu_item_id
        WHERE mi.merchant_id = v_merchant_id
        ON CONFLICT (menu_id, category_id) DO NOTHING;
        
        -- Mark as migrated
        UPDATE menu_item_menus mim
        SET is_migrated = true
        FROM menu_items mi
        WHERE mi.id = mim.menu_item_id
          AND mi.merchant_id = v_merchant_id;
        
        GET DIAGNOSTICS v_migrated = ROW_COUNT;
    END LOOP;
    
    RETURN json_build_object(
        'success', true,
        'migrated_count', v_migrated
    );
END;
$$;


ALTER FUNCTION "public"."migrate_menu_items_to_categories"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."migrate_pending_to_preparing"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_affected_count INT;
  v_affected_order_ids UUID[];
BEGIN
  -- Advance all "sent" items to "preparing" for active orders at this location
  UPDATE order_items oi
  SET
    kitchen_status = 'preparing',
    started_preparing_at = COALESCE(started_preparing_at, NOW()),
    updated_at = NOW()
  FROM orders o
  WHERE oi.order_id = o.id
    AND o.location_id = p_location_id
    AND o.status IN ('sent_to_kitchen', 'preparing')
    AND oi.kitchen_status = 'sent'
    AND COALESCE(oi.is_voided, false) = false;

  GET DIAGNOSTICS v_affected_count = ROW_COUNT;

  -- Update kds_item_status: set started_at for pending display items
  UPDATE kds_item_status kis
  SET started_at = COALESCE(started_at, NOW()), updated_at = NOW()
  FROM order_items oi, orders o
  WHERE kis.order_item_id = oi.id
    AND oi.order_id = o.id
    AND o.location_id = p_location_id
    AND kis.status = 'pending'
    AND oi.kitchen_status = 'preparing';

  -- Bump sync_version on affected orders to trigger broadcasts
  SELECT ARRAY_AGG(DISTINCT o.id) INTO v_affected_order_ids
  FROM orders o
  WHERE o.location_id = p_location_id
    AND o.status IN ('sent_to_kitchen', 'preparing');

  IF v_affected_order_ids IS NOT NULL THEN
    UPDATE orders
    SET sync_version = COALESCE(sync_version, 0) + 1, updated_at = NOW()
    WHERE id = ANY(v_affected_order_ids);
  END IF;

  RETURN jsonb_build_object('success', true, 'migrated_items', v_affected_count);
END;
$$;


ALTER FUNCTION "public"."migrate_pending_to_preparing"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_waitlist_party"("p_waitlist_id" "uuid", "p_notification_type" "text" DEFAULT 'sms'::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_entry    waitlist%ROWTYPE;
  v_location locations%ROWTYPE;
BEGIN
  SELECT * INTO v_entry FROM waitlist
  WHERE id = p_waitlist_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids())
    AND status = 'waiting';

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Entry not found or not in waiting status');
  END IF;

  IF v_entry.notification_count >= 3 THEN
    RETURN json_build_object('success', false, 'error', 'max_notifications_reached');
  END IF;

  SELECT * INTO v_location FROM locations WHERE id = v_entry.location_id;

  RETURN json_build_object(
    'success', true,
    'phone', v_entry.phone,
    'party_name', v_entry.party_name,
    'store_name', COALESCE(v_location.name, 'Our Restaurant'),
    'notified_at', v_entry.notified_at,
    'notification_count', v_entry.notification_count,
    'last_notification_type', v_entry.last_notification_type,
    'notification_failures', v_entry.notification_failures,
    'action_required', 'send_sms',
    'message_template', 'Hi ' || v_entry.party_name || '! Your table at ' || COALESCE(v_location.name, 'Our Restaurant') || ' is ready. Please check in with the host within 10 minutes.'
  );
END;
$$;


ALTER FUNCTION "public"."notify_waitlist_party"("p_waitlist_id" "uuid", "p_notification_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_cash_drawer_session"("p_cash_drawer_id" "uuid", "p_merchant_id" "uuid", "p_location_id" "uuid", "p_opened_by" "uuid", "p_opening_amount" numeric, "p_opening_count_details" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_session_id UUID;
  v_business_date DATE := CURRENT_DATE;
  v_existing_session UUID;
BEGIN
  -- Verify no open session exists for this drawer
  SELECT id INTO v_existing_session
  FROM cash_drawer_sessions
  WHERE cash_drawer_id = p_cash_drawer_id
    AND status = 'open'
  LIMIT 1;

  IF v_existing_session IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Drawer already has an open session',
      'existing_session_id', v_existing_session
    );
  END IF;

  -- Create session
  INSERT INTO cash_drawer_sessions (
    cash_drawer_id, merchant_id, location_id,
    opened_by, opened_at, opening_amount,
    opening_count_details, opening_count_verified,
    expected_cash, status, business_date
  ) VALUES (
    p_cash_drawer_id, p_merchant_id, p_location_id,
    p_opened_by, NOW(), p_opening_amount,
    p_opening_count_details, (p_opening_count_details IS NOT NULL),
    p_opening_amount, 'open', v_business_date
  )
  RETURNING id INTO v_session_id;

  -- Record opening_count operation
  INSERT INTO cash_drawer_operations (
    cash_drawer_id, session_id, operation_type,
    amount, performed_by, performed_at,
    balance_after
  ) VALUES (
    p_cash_drawer_id, v_session_id, 'opening_count',
    p_opening_amount, p_opened_by, NOW(),
    p_opening_amount
  );

  -- Update drawer status
  UPDATE cash_drawers
  SET is_open = true, current_session_id = v_session_id
  WHERE id = p_cash_drawer_id;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', v_session_id,
    'business_date', v_business_date
  );
END;
$$;


ALTER FUNCTION "public"."open_cash_drawer_session"("p_cash_drawer_id" "uuid", "p_merchant_id" "uuid", "p_location_id" "uuid", "p_opened_by" "uuid", "p_opening_amount" numeric, "p_opening_count_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_staff_login"("p_location_id" "uuid", "p_pin_code" "text") RETURNS TABLE("success" boolean, "staff_profile_id" "uuid", "role_code" "text", "first_name" "text", "last_name" "text", "error_message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
  v_row RECORD;
BEGIN
  IF p_location_id IS NULL OR p_pin_code IS NULL OR p_pin_code = '' THEN
    RETURN QUERY SELECT false, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT,
      'Missing location_id or pin_code'::TEXT;
    RETURN;
  END IF;

  FOR v_row IN
    SELECT
      lm.staff_profile_id,
      lm.role_code,
      COALESCE(lm.pin_plain, lm.pin_code) AS stored_plain_pin,
      COALESCE(lm.pin_hashed, CASE WHEN lm.pin_code IS NOT NULL AND lm.pin_code !~ '^\d{4,6}$' THEN lm.pin_code END) AS stored_hashed_pin,
      sp.first_name,
      sp.last_name
    FROM location_members lm
    JOIN staff_profiles sp ON sp.id = lm.staff_profile_id
    WHERE lm.location_id = p_location_id
      AND lm.is_active = true
      AND sp.is_active = true
      AND (
        lm.pin_plain IS NOT NULL
        OR lm.pin_hashed IS NOT NULL
        OR lm.pin_code IS NOT NULL
      )
  LOOP
    IF v_row.stored_plain_pin = p_pin_code
       OR (
         v_row.stored_hashed_pin LIKE '$2%'
         AND crypt(p_pin_code, v_row.stored_hashed_pin) = v_row.stored_hashed_pin
       ) THEN
      RETURN QUERY SELECT
        true,
        v_row.staff_profile_id,
        v_row.role_code,
        v_row.first_name,
        v_row.last_name,
        NULL::TEXT;
      RETURN;
    END IF;
  END LOOP;

  RETURN QUERY SELECT false, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT,
    'Invalid PIN'::TEXT;
END;
$_$;


ALTER FUNCTION "public"."pos_staff_login"("p_location_id" "uuid", "p_pin_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_staff_login"("p_location_id" "uuid", "p_pin_code" "text", "p_station_id" "uuid", "p_device_id" "text", "p_device_name" "text" DEFAULT NULL::"text", "p_auto_clock_in" boolean DEFAULT true, "p_force_takeover" boolean DEFAULT false) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$DECLARE
  v_staff RECORD;
  v_station RECORD;
  v_existing_session RECORD;
  v_session_id UUID;
  v_shift_result JSON;
  v_was_kicked BOOLEAN := FALSE;
  v_is_reconnect BOOLEAN := FALSE;
BEGIN
  -- ========================================
  -- STEP 1: VERIFY PIN
  -- ========================================
  SELECT 
    sp.id as staff_profile_id,
    sp.first_name,
    sp.last_name,
    lm.role_code,
    lm.hourly_rate,
    lm.merchant_id
  INTO v_staff
  FROM location_members lm
  JOIN staff_profiles sp ON sp.id = lm.staff_profile_id
  WHERE lm.location_id = p_location_id 
    AND lm.is_active = true
    AND lm.pin_code IS NOT NULL
    AND (
        replace(lm.pin_code, '$2b$', '$2a$') = crypt(p_pin_code, replace(lm.pin_code, '$2b$', '$2a$'))
    );

  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Invalid PIN',
      'error_code', 'INVALID_PIN'
    );
  END IF;

  -- ========================================
  -- STEP 2: CLAIM STATION
  -- ========================================
  
  SELECT s.*, l.merchant_id 
  INTO v_station
  FROM stations s
  JOIN locations l ON l.id = s.location_id
  WHERE s.id = p_station_id AND s.is_active = TRUE;
  
  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Station not found',
      'error_code', 'STATION_NOT_FOUND'
    );
  END IF;
  
  -- End any session this device has at OTHER stations
  UPDATE station_sessions
  SET session_status = 'ended', ended_at = NOW()
  WHERE device_id = p_device_id
    AND session_status = 'active'
    AND station_id != p_station_id;
  
  -- Check for existing session at this station
  SELECT * INTO v_existing_session
  FROM station_sessions
  WHERE station_id = p_station_id
    AND session_status = 'active'
  FOR UPDATE;
  
  IF FOUND THEN
    IF v_existing_session.device_id = p_device_id THEN
      -- Same device reconnecting
      UPDATE station_sessions
      SET 
        staff_profile_id = v_staff.staff_profile_id,
        staff_name = v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.'
      WHERE id = v_existing_session.id;
      
      v_session_id := v_existing_session.id;
      v_is_reconnect := TRUE;
    ELSE
      -- Different device
      IF NOT p_force_takeover THEN
        RETURN json_build_object(
          'success', false,
          'error', 'Station in use',
          'error_code', 'STATION_IN_USE',
          'staff', json_build_object(
            'staff_profile_id', v_staff.staff_profile_id,
            'display_name', v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.'
          ),
          'current_session', json_build_object(
            'device_name', v_existing_session.device_name,
            'staff_name', v_existing_session.staff_name,
            'started_at', v_existing_session.started_at
          )
        );
      END IF;
      
      -- Kick existing session
      UPDATE station_sessions
      SET 
        session_status = 'kicked',
        ended_at = NOW(),
        kicked_by_device_id = p_device_id,
        kicked_by_staff_name = v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.',
        kick_reason = 'Taken over'
      WHERE id = v_existing_session.id;
      
      INSERT INTO session_kick_notifications (session_id, device_id, kicked_by_staff_name, kick_reason)
      VALUES (v_existing_session.id, v_existing_session.device_id, 
              v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.', 'Taken over');
      
      v_was_kicked := TRUE;
    END IF;
  END IF;
  
  -- Create new session if not reconnecting
  IF v_session_id IS NULL THEN
    INSERT INTO station_sessions (
      station_id, merchant_id, location_id,
      device_id, device_name,
      staff_profile_id, staff_name,
      session_status
    ) VALUES (
      p_station_id, v_station.merchant_id, v_station.location_id,
      p_device_id, p_device_name,
      v_staff.staff_profile_id, 
      v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.',
      'active'
    )
    RETURNING id INTO v_session_id;
    
    -- Clear device_id from other stations BEFORE setting it (fixes unique constraint error)
    UPDATE stations 
    SET device_id = NULL, device_name = NULL, is_online = FALSE
    WHERE device_id = p_device_id AND id != p_station_id;
    
    -- Now safely update the target station
    UPDATE stations SET device_id = p_device_id, device_name = p_device_name, is_online = TRUE
    WHERE id = p_station_id;
  END IF;

  -- ========================================
  -- STEP 3: AUTO CLOCK IN
  -- Using handle_time_clock with CORRECT order:
  -- handle_time_clock(p_pin_code text, p_location_id uuid, p_action_type text, p_device_id text)
  -- ========================================
  IF p_auto_clock_in THEN
    v_shift_result := handle_time_clock(
      p_pin_code,           -- 1st: pin_code (TEXT)
      p_location_id,        -- 2nd: location_id (UUID)
      'sign_in'::TEXT,      -- 3rd: action_type (TEXT)
      p_device_id           -- 4th: device_id (TEXT) - already TEXT, no cast needed
    );
  END IF;

  -- ========================================
  -- RETURN SUCCESS
  -- ========================================
  RETURN json_build_object(
    'success', true,
    'staff', json_build_object(
      'staff_profile_id', v_staff.staff_profile_id,
      'first_name', v_staff.first_name,
      'last_name', v_staff.last_name,
      'display_name', v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.',
      'role_code', v_staff.role_code
    ),
    'session', json_build_object(
      'session_id', v_session_id,
      'station_id', p_station_id,
      'station_name', v_station.station_name,
      'station_type', v_station.station_type,
      'is_reconnect', v_is_reconnect,
      'kicked_previous', v_was_kicked
    ),
    'shift', v_shift_result
  );
END;$_$;


ALTER FUNCTION "public"."pos_staff_login"("p_location_id" "uuid", "p_pin_code" "text", "p_station_id" "uuid", "p_device_id" "text", "p_device_name" "text", "p_auto_clock_in" boolean, "p_force_takeover" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_staff_login_v2"("p_location_id" "uuid", "p_pin_code" "text", "p_station_id" "uuid", "p_device_id" "text", "p_device_name" "text", "p_auto_clock_in" boolean DEFAULT false, "p_force_takeover" boolean DEFAULT false, "p_ip_address" "text" DEFAULT NULL::"text", "p_app_version" "text" DEFAULT NULL::"text", "p_os_version" "text" DEFAULT NULL::"text", "p_hardware_model" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$DECLARE
  v_staff RECORD;
  v_station RECORD;
  v_existing_session RECORD;
  v_session_id UUID;
  v_shift_result JSON;
  v_was_kicked BOOLEAN := FALSE;
  v_is_reconnect BOOLEAN := FALSE;
  v_ip_address INET;
BEGIN
  -- ========================================
  -- STEP 1: VERIFY PIN
  -- ========================================
  IF p_ip_address IS NOT NULL AND p_ip_address <> '' THEN
  v_ip_address := p_ip_address::INET;
  ELSE
    v_ip_address := NULL;
  END IF;

  SELECT
    sp.id as staff_profile_id,
    sp.first_name,
    sp.last_name,
    lm.role_code,
    lm.hourly_rate,
    lm.merchant_id,
    lm.id as location_member_id,
    lm.pin_plain
  INTO v_staff
  FROM location_members lm
  JOIN staff_profiles sp ON sp.id = lm.staff_profile_id
  WHERE lm.location_id = p_location_id
    AND lm.is_active = true
    AND (
        -- Fast path: plain-text PIN match
        (lm.pin_plain IS NOT NULL AND lm.pin_plain = p_pin_code)
        OR
        -- Bcrypt fallback: un-migrated employees only
        (lm.pin_plain IS NULL AND lm.pin_code IS NOT NULL
         AND replace(lm.pin_code, '$2b$', '$2a$') = crypt(p_pin_code, replace(lm.pin_code, '$2b$', '$2a$')))
    );

  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Invalid PIN',
      'error_code', 'INVALID_PIN'
    );
  END IF;

  -- Auto-migrate: populate pin_plain on first successful bcrypt login
  IF v_staff.pin_plain IS NULL THEN
    UPDATE location_members SET pin_plain = p_pin_code WHERE id = v_staff.location_member_id;
  END IF;
  -- ========================================
  -- STEP 2: CLAIM STATION
  -- ========================================
  
  SELECT s.*, l.merchant_id 
  INTO v_station
  FROM stations s
  JOIN locations l ON l.id = s.location_id
  WHERE s.id = p_station_id AND s.is_active = TRUE;
  
  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Station not found',
      'error_code', 'STATION_NOT_FOUND'
    );
  END IF;
  
  -- End any session this device has at OTHER stations
  UPDATE station_sessions
  SET session_status = 'ended', ended_at = NOW()
  WHERE device_id = p_device_id
    AND session_status = 'active'
    AND station_id != p_station_id;
  
  -- Check for existing session at this station
  SELECT * INTO v_existing_session
  FROM station_sessions
  WHERE station_id = p_station_id
    AND session_status = 'active'
  FOR UPDATE;
  
  IF FOUND THEN
    IF v_existing_session.device_id = p_device_id THEN
      -- Same device reconnecting
     UPDATE station_sessions
SET 
  staff_profile_id = v_staff.staff_profile_id,
  staff_name = v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.',
  ip_address = COALESCE(v_ip_address, ip_address::INET),  -- Keep existing if null
  app_version = COALESCE(NULLIF(p_app_version, ''), app_version),
  os_version = COALESCE(NULLIF(p_os_version, ''), os_version),
  hardware_model = COALESCE(NULLIF(p_hardware_model, ''), hardware_model)
WHERE id = v_existing_session.id;
      
      v_session_id := v_existing_session.id;
      v_is_reconnect := TRUE;
    ELSE
      -- Different device
      IF NOT p_force_takeover THEN
        RETURN json_build_object(
          'success', false,
          'error', 'Station in use',
          'error_code', 'STATION_IN_USE',
          'staff', json_build_object(
            'staff_profile_id', v_staff.staff_profile_id,
            'display_name', v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.'
          ),
          'current_session', json_build_object(
            'device_name', v_existing_session.device_name,
            'staff_name', v_existing_session.staff_name,
            'started_at', v_existing_session.started_at
          )
        );
      END IF;
      
      -- Kick existing session
      UPDATE station_sessions
      SET 
        session_status = 'kicked',
        ended_at = NOW(),
        kicked_by_device_id = p_device_id,
        kicked_by_staff_name = v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.',
        kick_reason = 'Taken over'
      WHERE id = v_existing_session.id;
      
      INSERT INTO session_kick_notifications (session_id, device_id, kicked_by_staff_name, kick_reason)
      VALUES (v_existing_session.id, v_existing_session.device_id, 
              v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.', 'Taken over');
      
      v_was_kicked := TRUE;
    END IF;
  END IF;
  
  -- Create new session if not reconnecting
  IF v_session_id IS NULL THEN
 INSERT INTO station_sessions (
  station_id, merchant_id, location_id,
  device_id, device_name,
  staff_profile_id, staff_name,
  session_status,
  ip_address, app_version, os_version, hardware_model
) VALUES (
  p_station_id, v_station.merchant_id, v_station.location_id,
  p_device_id, p_device_name,
  v_staff.staff_profile_id, 
  v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.',
  'active',
  v_ip_address,  -- Already converted
  NULLIF(p_app_version, ''),
  NULLIF(p_os_version, ''),
  NULLIF(p_hardware_model, '')
)
RETURNING id INTO v_session_id;
    
    -- Clear device_id from other stations BEFORE setting it
    UPDATE stations SET 
  device_id = p_device_id, 
  device_name = p_device_name, 
  is_online = TRUE,
  ip_address = v_ip_address,  -- Already converted
  app_version = NULLIF(p_app_version, ''),
  os_version = NULLIF(p_os_version, ''),
  hardware_model = NULLIF(p_hardware_model, '')
WHERE id = p_station_id;
  END IF;


  -- ========================================
  -- LOG DEVICE CONNECTION
  -- ========================================
  -- ========================================
  -- LOG DEVICE CONNECTION (UPSERT)
  -- ========================================
  INSERT INTO station_devices (
    station_id, merchant_id, location_id,
    device_type, device_name, device_model,
    connection_type, device_id, staff_id, staff_name,
    app_version, os_version, ip_address, session_id,
    is_connected, last_seen_at
  ) VALUES (
    p_station_id, v_station.merchant_id, v_station.location_id,
    'pos_device', p_device_name, NULLIF(p_hardware_model, ''),
    'integrated', p_device_id, v_staff.staff_profile_id,
    v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.',
    NULLIF(p_app_version, ''), NULLIF(p_os_version, ''),
    v_ip_address, v_session_id,
    TRUE, NOW()
  )
  ON CONFLICT (station_id, device_id) WHERE device_type = 'pos_device'
  DO UPDATE SET
    device_name = EXCLUDED.device_name,
    device_model = EXCLUDED.device_model,
    staff_id = EXCLUDED.staff_id,
    staff_name = EXCLUDED.staff_name,
    app_version = EXCLUDED.app_version,
    os_version = EXCLUDED.os_version,
    ip_address = EXCLUDED.ip_address,
    session_id = EXCLUDED.session_id,
    is_connected = TRUE,
    last_seen_at = NOW(),
    updated_at = NOW();

  -- Audit trail: record login in device_login_history
  INSERT INTO device_login_history (
    station_id, merchant_id, location_id, session_id,
    device_id, device_name, device_model,
    staff_id, staff_name,
    app_version, os_version, ip_address,
    logged_in_at
  ) VALUES (
    p_station_id, v_station.merchant_id, v_station.location_id, v_session_id,
    p_device_id, p_device_name, NULLIF(p_hardware_model, ''),
    v_staff.staff_profile_id,
    v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.',
    NULLIF(p_app_version, ''), NULLIF(p_os_version, ''),
    v_ip_address,
    NOW()
  );



  -- ========================================
  -- STEP 3: AUTO CLOCK IN
  -- ========================================
  IF p_auto_clock_in THEN
    v_shift_result := handle_time_clock(
      p_pin_code,           -- 1st: pin_code
      p_location_id,        -- 2nd: location_id
      'sign_in'::TEXT,      -- 3rd: action_type
      p_device_id           -- 4th: device_id
    );
  END IF;

  -- ========================================
  -- RETURN SUCCESS
  -- ========================================
  RETURN json_build_object(
    'success', true,
    'staff', json_build_object(
      'staff_profile_id', v_staff.staff_profile_id,
      'first_name', v_staff.first_name,
      'last_name', v_staff.last_name,
      'display_name', v_staff.first_name || ' ' || LEFT(v_staff.last_name, 1) || '.',
      'role_code', v_staff.role_code
    ),
    'session', json_build_object(
      'session_id', v_session_id,
      'station_id', p_station_id,
      'station_name', v_station.station_name,
      'station_type', v_station.station_type,
      'is_reconnect', v_is_reconnect,
      'kicked_previous', v_was_kicked
    ),
    'shift', v_shift_result
  );
END;$_$;


ALTER FUNCTION "public"."pos_staff_login_v2"("p_location_id" "uuid", "p_pin_code" "text", "p_station_id" "uuid", "p_device_id" "text", "p_device_name" "text", "p_auto_clock_in" boolean, "p_force_takeover" boolean, "p_ip_address" "text", "p_app_version" "text", "p_os_version" "text", "p_hardware_model" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_staff_logout"("p_session_id" "uuid", "p_location_id" "uuid", "p_pin_code" "text", "p_device_id" "text", "p_clock_out" boolean DEFAULT false) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_session RECORD;
  v_clock_result JSON;
BEGIN
  -- End session
  UPDATE station_sessions
  SET session_status = 'ended', ended_at = NOW(), last_activity_at = NOW()
  WHERE id = p_session_id AND session_status = 'active'
  RETURNING * INTO v_session;
  
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Session not found');
  END IF;
  
  -- Update station
  UPDATE stations SET is_online = FALSE
  WHERE id = v_session.station_id AND device_id = v_session.device_id;
  
  -- Mark device as disconnected
  UPDATE station_devices
  SET is_connected = FALSE, last_seen_at = NOW(), updated_at = NOW()
  WHERE session_id = p_session_id AND device_type = 'pos_device';

  -- Close login history entry
  UPDATE device_login_history
  SET logged_out_at = NOW(), logout_reason = 'logout'
  WHERE session_id = p_session_id AND logged_out_at IS NULL;

  -- Clock out if requested
  IF p_clock_out THEN
    v_clock_result := handle_time_clock(
      p_location_id,
      p_pin_code,
      'clock_out',
      p_device_id,
      v_session.station_id
    );
  END IF;
  
  RETURN json_build_object(
    'success', true,
    'clocked_out', p_clock_out,
    'clock_result', v_clock_result
  );
END;$$;


ALTER FUNCTION "public"."pos_staff_logout"("p_session_id" "uuid", "p_location_id" "uuid", "p_pin_code" "text", "p_device_id" "text", "p_clock_out" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_append_only_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RAISE EXCEPTION 'Table % is append-only; % is not allowed', TG_TABLE_NAME, TG_OP;
END;
$$;


ALTER FUNCTION "public"."prevent_append_only_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_payment"("p_order_id" "uuid", "p_is_cash" boolean DEFAULT false, "p_payment_type" "text" DEFAULT 'full'::"text", "p_split_count" integer DEFAULT NULL::integer, "p_item_allocations" "jsonb" DEFAULT NULL::"jsonb", "p_custom_amount" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order RECORD;
  v_charge_amount NUMERIC;
  v_subtotal_portion NUMERIC;
  v_tax_portion NUMERIC;
  v_discount_portion NUMERIC;
  v_remaining_balance NUMERIC;
  v_outstanding_total NUMERIC;
  v_outstanding_subtotal NUMERIC;
  v_outstanding_tax NUMERIC;
BEGIN
  -- Get order with current totals
  SELECT 
    o.*,
    CASE WHEN p_is_cash THEN o.cash_total ELSE o.card_total END as effective_total,
    CASE WHEN p_is_cash THEN 
      GREATEST(0, o.cash_total - o.amount_paid)
    ELSE 
      GREATEST(0, o.card_total - o.amount_paid)
    END as outstanding
  INTO v_order
  FROM orders o
  WHERE o.id = p_order_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found: %', p_order_id;
  END IF;
  
  v_outstanding_total := v_order.outstanding;
  
  -- Calculate outstanding subtotal and tax from unpaid items
  SELECT 
    COALESCE(SUM(
      CASE WHEN p_is_cash THEN 
        (oi.quantity - COALESCE(oi.paid_quantity, 0)) * oi.cash_price
      ELSE 
        (oi.quantity - COALESCE(oi.paid_quantity, 0)) * oi.unit_price
      END
    ), 0),
    COALESCE(SUM(
      CASE WHEN oi.quantity > COALESCE(oi.paid_quantity, 0) THEN
        oi.tax_amount * ((oi.quantity - COALESCE(oi.paid_quantity, 0))::NUMERIC / oi.quantity)
      ELSE 0 END
    ), 0)
  INTO v_outstanding_subtotal, v_outstanding_tax
  FROM order_items oi
  WHERE oi.order_id = p_order_id
  AND NOT oi.is_voided
  AND oi.quantity > COALESCE(oi.paid_quantity, 0);
  
  -- Calculate based on payment type
  CASE p_payment_type
    WHEN 'full' THEN
      v_charge_amount := v_outstanding_total;
      v_subtotal_portion := v_outstanding_subtotal;
      v_tax_portion := v_outstanding_tax;
      v_discount_portion := v_order.discount_amount * 
        (v_outstanding_subtotal / NULLIF(v_order.subtotal, 0));
      v_remaining_balance := 0;
      
    WHEN 'split_even' THEN
      v_charge_amount := ROUND(v_outstanding_total / COALESCE(p_split_count, 1), 2);
      v_subtotal_portion := ROUND(v_outstanding_subtotal / COALESCE(p_split_count, 1), 2);
      v_tax_portion := ROUND(v_outstanding_tax / COALESCE(p_split_count, 1), 2);
      v_discount_portion := ROUND(v_order.discount_amount / COALESCE(p_split_count, 1), 2);
      v_remaining_balance := v_outstanding_total - v_charge_amount;
      
    WHEN 'split_by_item' THEN
      -- Calculate from selected items
      SELECT 
        COALESCE(SUM(
          CASE WHEN p_is_cash THEN
            oi.cash_price * LEAST(
              (alloc->>'quantity')::INTEGER,
              oi.quantity - COALESCE(oi.paid_quantity, 0)
            )
          ELSE
            oi.unit_price * LEAST(
              (alloc->>'quantity')::INTEGER,
              oi.quantity - COALESCE(oi.paid_quantity, 0)
            )
          END
          + oi.tax_amount * (
            LEAST(
              (alloc->>'quantity')::INTEGER,
              oi.quantity - COALESCE(oi.paid_quantity, 0)
            )::NUMERIC / oi.quantity
          )
          - oi.discount_amount * (
            LEAST(
              (alloc->>'quantity')::INTEGER,
              oi.quantity - COALESCE(oi.paid_quantity, 0)
            )::NUMERIC / oi.quantity
          )
        ), 0)
      INTO v_charge_amount
      FROM order_items oi
      JOIN jsonb_array_elements(p_item_allocations) alloc 
        ON oi.id = (alloc->>'item_id')::UUID
      WHERE oi.order_id = p_order_id
      AND NOT oi.is_voided;
      
      v_remaining_balance := v_outstanding_total - v_charge_amount;
      -- Simplified portions for split by item
      v_subtotal_portion := v_charge_amount * 0.9; -- Approximate
      v_tax_portion := v_charge_amount * 0.1;
      v_discount_portion := 0;
      
    WHEN 'split_custom' THEN
      v_charge_amount := LEAST(p_custom_amount, v_outstanding_total);
      v_remaining_balance := v_outstanding_total - v_charge_amount;
      -- Estimate proportions
      v_subtotal_portion := v_charge_amount * (v_outstanding_subtotal / NULLIF(v_outstanding_total, 0));
      v_tax_portion := v_charge_amount * (v_outstanding_tax / NULLIF(v_outstanding_total, 0));
      v_discount_portion := 0;
      
    ELSE
      RAISE EXCEPTION 'Invalid payment type: %', p_payment_type;
  END CASE;
  
  RETURN jsonb_build_object(
    'charge_amount', ROUND(v_charge_amount, 2),
    'subtotal_portion', ROUND(v_subtotal_portion, 2),
    'tax_portion', ROUND(v_tax_portion, 2),
    'discount_portion', ROUND(v_discount_portion, 2),
    'remaining_balance', ROUND(v_remaining_balance, 2),
    'order_total', v_order.effective_total,
    'amount_paid', v_order.amount_paid
  );
END;
$$;


ALTER FUNCTION "public"."preview_payment"("p_order_id" "uuid", "p_is_cash" boolean, "p_payment_type" "text", "p_split_count" integer, "p_item_allocations" "jsonb", "p_custom_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_cash_payment_full_order"("p_order_id" "uuid", "p_amount_tendered" numeric, "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_order record;
    v_payment_id uuid;
    v_change_due numeric;
BEGIN
    -- Get current order with cash pricing
    SELECT * INTO v_order 
    FROM public.orders 
    WHERE id = p_order_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found: %', p_order_id;
    END IF;
    
    -- Calculate change
    v_change_due := GREATEST(p_amount_tendered - v_order.cash_total, 0);
    
    -- Update order to use cash pricing as effective
    UPDATE public.orders SET
        effective_subtotal = cash_subtotal,
        effective_tax_amount = cash_tax_amount,
        effective_total = cash_total,
        subtotal = cash_subtotal,
        tax_amount = cash_tax_amount,
        total_amount = cash_total,
        cash_discount_applied = true,
        cash_discount_amount = card_total - cash_total,
        amount_paid = cash_total,
        amount_due = 0,
        payment_status = 'paid',
        updated_at = now()
    WHERE id = p_order_id;
    
    -- Create payment record
    INSERT INTO public.order_payments (
        order_id,
        payment_method,
        amount,
        subtotal_portion,
        tax_portion,
        total_amount,
        is_cash_priced,
        cash_discount_applied,
        original_amount,
        amount_tendered,
        change_given,
        status,
        terminal_type,
        processed_by_staff_id,
        captured_at
    ) VALUES (
        p_order_id,
        'cash',
        v_order.cash_total,
        v_order.cash_subtotal,
        v_order.cash_tax_amount,
        v_order.cash_total,
        true,
        true,
        v_order.card_total,  -- What they WOULD have paid
        p_amount_tendered,
        v_change_due,
        'paid',
        'cash_drawer',
        p_staff_id,
        now()
    )
    RETURNING id INTO v_payment_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'payment_id', v_payment_id,
        'cash_total', v_order.cash_total,
        'card_total_avoided', v_order.card_total,
        'savings', v_order.card_total - v_order.cash_total,
        'amount_tendered', p_amount_tendered,
        'change_due', v_change_due
    );
END;
$$;


ALTER FUNCTION "public"."process_cash_payment_full_order"("p_order_id" "uuid", "p_amount_tendered" numeric, "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_online_order"("p_location_id" "uuid", "p_provider" "text", "p_provider_order_id" "text", "p_provider_restaurant_id" "text" DEFAULT NULL::"text", "p_external_reference" "text" DEFAULT NULL::"text", "p_delivery_company" "text" DEFAULT NULL::"text", "p_provider_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_order_type_raw" "text" DEFAULT 'DELIVERY'::"text", "p_customer_name" "text" DEFAULT NULL::"text", "p_customer_phone" "text" DEFAULT NULL::"text", "p_customer_email" "text" DEFAULT NULL::"text", "p_subtotal" numeric DEFAULT 0, "p_tax" numeric DEFAULT 0, "p_total" numeric DEFAULT 0, "p_gratuity" numeric DEFAULT 0, "p_surcharge" numeric DEFAULT 0, "p_delivery_charge" numeric DEFAULT 0, "p_discount" numeric DEFAULT 0, "p_placed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ready_by" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_estimated_delivery" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_items" "jsonb" DEFAULT '[]'::"jsonb", "p_delivery_address" "jsonb" DEFAULT NULL::"jsonb", "p_order_notes" "text" DEFAULT NULL::"text", "p_raw_payload" "jsonb" DEFAULT NULL::"jsonb", "p_auto_accept" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$DECLARE
  v_merchant_id      UUID;
  v_order_id         UUID;
  v_order_number     TEXT;
  v_display_number   TEXT;
  v_payment_id       UUID;
  v_order_type       public.order_type;
  v_status           public.order_status;
  v_kitchen_status   TEXT;
  v_provider_enum    public.online_order_provider;

  v_item             JSONB;
  v_item_index       INTEGER := 0;
  v_item_count       INTEGER := 0;
  v_order_item_id    UUID;

  v_menu_item        RECORD;
  v_menu_item_found  BOOLEAN;

  v_item_tax_raw     NUMERIC;
  v_item_tax_floor   NUMERIC;
  v_tax_distributed  NUMERIC := 0;
  v_tax_remainders   NUMERIC[];
  v_tax_item_ids     UUID[];
  v_tax_floors       NUMERIC[];

  v_modifier         JSONB;
  v_default_tax_rate NUMERIC;
  v_warnings         JSONB := '[]'::JSONB;
BEGIN
  -- ========================================================================
  -- STEP 0: IDEMPOTENCY
  -- ========================================================================
  DECLARE
    v_existing_order_id UUID;
    v_existing_online_id UUID;
  BEGIN
    SELECT oo.order_id, oo.id
    INTO v_existing_order_id, v_existing_online_id
    FROM public.online_orders oo
    WHERE oo.provider = p_provider::public.online_order_provider
      AND oo.provider_order_id = p_provider_order_id;

    IF v_existing_order_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'success', true,
        'order_id', v_existing_order_id,
        'online_order_id', v_existing_online_id,
        'duplicate', true,
        'message', 'Order already processed'
      );
    END IF;

    SELECT id INTO v_existing_order_id
    FROM public.orders
    WHERE external_id = p_provider || ':' || p_provider_order_id;

    IF v_existing_order_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'success', true,
        'order_id', v_existing_order_id,
        'duplicate', true,
        'message', 'Order already processed (external_id match)'
      );
    END IF;
  END;

  -- ========================================================================
  -- STEP 1: RESOLVE MERCHANT
  -- ========================================================================
  SELECT merchant_id INTO v_merchant_id
  FROM public.locations
  WHERE id = p_location_id;

  IF v_merchant_id IS NULL THEN
    RAISE EXCEPTION 'Location not found: %', p_location_id;
  END IF;

  -- ========================================================================
  -- STEP 2: CAST PROVIDER ENUM
  -- ========================================================================
  BEGIN
    v_provider_enum := p_provider::public.online_order_provider;
  EXCEPTION WHEN invalid_text_representation THEN
    v_provider_enum := 'other'::public.online_order_provider;
    p_provider_metadata := p_provider_metadata || jsonb_build_object('original_provider', p_provider);
  END;

  -- ========================================================================
  -- STEP 3: MAP ORDER TYPE & STATUS
  -- ========================================================================
  v_order_type := CASE UPPER(p_order_type_raw)
    WHEN 'DELIVERY' THEN 'delivery'::public.order_type
    WHEN 'PICKUP'   THEN 'takeout'::public.order_type
    WHEN 'TAKEOUT'  THEN 'takeout'::public.order_type
    ELSE 'online'::public.order_type
  END;

  IF p_auto_accept THEN
    v_status := 'sent_to_kitchen'::public.order_status;
    v_kitchen_status := 'sent';
  ELSE
    v_status := 'pending'::public.order_status;
    v_kitchen_status := NULL;
  END IF;

  -- ========================================================================
  -- STEP 4: GET DEFAULT TAX RATE
  -- FIX: removed tax_category = 'default' filter — picks the first active rate
  --      for the location regardless of category name (handles 'standard',
  --      'default', 'food', or any custom name set in the dashboard).
  -- ========================================================================
  SELECT percentage INTO v_default_tax_rate
  FROM public.tax_rates
  WHERE location_id = p_location_id
    AND is_active = true
  ORDER BY
    CASE tax_category WHEN 'standard' THEN 0 WHEN 'default' THEN 1 ELSE 2 END,
    created_at ASC
  LIMIT 1;

  -- Self-healing tax: if the caller passed p_tax = 0 but we found a rate,
  -- recalculate tax and total so the stored record is always correct.
  IF v_default_tax_rate IS NOT NULL AND p_tax = 0 AND p_subtotal > 0 THEN
    p_tax   := ROUND(p_subtotal * (v_default_tax_rate / 100), 2);
    p_total := p_subtotal + p_tax + COALESCE(p_gratuity, 0)
                           + COALESCE(p_surcharge, 0)
                           + COALESCE(p_delivery_charge, 0)
                           - COALESCE(p_discount, 0);
  END IF;

  -- Infer rate from p_tax if still unknown (e.g. third-party providers)
  IF v_default_tax_rate IS NULL AND p_subtotal > 0 AND p_tax > 0 THEN
    v_default_tax_rate := ROUND((p_tax / p_subtotal) * 100, 4);
  END IF;

  -- ========================================================================
  -- STEP 5: GENERATE ORDER NUMBER
  -- ========================================================================
  -- Generate order number (per-station when station_id provided)
  v_order_number := public.generate_order_number(p_location_id);

  -- Generate display number (handles both 3-segment and 4-segment formats)
  v_display_number := CASE
    WHEN SPLIT_PART(v_order_number, '-', 4) <> ''
    THEN '#' || SPLIT_PART(v_order_number, '-', 3) || '-' || SPLIT_PART(v_order_number, '-', 4)
    ELSE '#' || SPLIT_PART(v_order_number, '-', 3)
  END;
  
  -- ========================================================================
  -- STEP 6: INSERT ORDER
  -- ========================================================================
  INSERT INTO public.orders (
    merchant_id, location_id, order_number, display_number,
    order_type, status, payment_status,
    customer_name, customer_phone, customer_email, delivery_address,
    subtotal, tax_amount, total_amount, tip_amount, service_charge, discount_amount,
    amount_due, amount_paid,
    card_subtotal, card_tax_amount, card_total,
    cash_subtotal, cash_tax_amount, cash_total,
    effective_subtotal, effective_tax_amount, effective_total,
    external_id, estimated_delivery_time, special_instructions,
    sent_to_kitchen_at, metadata, created_at, updated_at,
    order_source
  ) VALUES (
    v_merchant_id, p_location_id, v_order_number, v_display_number,
    v_order_type, v_status, 'paid'::public.payment_status,
    p_customer_name, p_customer_phone, p_customer_email, p_delivery_address,
    p_subtotal, p_tax, p_total, COALESCE(p_gratuity, 0), COALESCE(p_surcharge, 0), COALESCE(p_discount, 0),
    0, p_total,
    p_subtotal, p_tax, p_total,
    p_subtotal, p_tax, p_total,
    p_subtotal, p_tax, p_total,
    p_provider || ':' || p_provider_order_id,
    COALESCE(p_estimated_delivery, p_ready_by),
    p_order_notes,
    CASE WHEN p_auto_accept THEN NOW() ELSE NULL END,
    jsonb_build_object(
      'source', 'online_order', 'provider', p_provider,
      'delivery_company', p_delivery_company, 'provider_order_id', p_provider_order_id,
      'external_reference', p_external_reference, 'placed_at', p_placed_at,
      'ready_by', p_ready_by, 'auto_accepted', p_auto_accept
    ),
    NOW(), NOW(),
    'online'
  )
  RETURNING id INTO v_order_id;

  -- ========================================================================
  -- STEP 7: INSERT ORDER ITEMS
  -- ========================================================================
  v_tax_remainders := ARRAY[]::NUMERIC[];
  v_tax_item_ids   := ARRAY[]::UUID[];
  v_tax_floors     := ARRAY[]::NUMERIC[];

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_item_index := v_item_index + 1;
    v_menu_item_found := FALSE;

    IF v_item->>'external_id' IS NOT NULL AND v_item->>'external_id' != '' THEN
      BEGIN
        SELECT mi.id, mi.name, mi.price, mi.is_tax_exempt,
               ci.category_id AS cat_id, c.name AS cat_name
        INTO v_menu_item
        FROM public.menu_items mi
        LEFT JOIN public.category_items ci ON ci.menu_item_id = mi.id
        LEFT JOIN public.categories c ON c.id = ci.category_id
        WHERE mi.id = (v_item->>'external_id')::UUID
          AND mi.merchant_id = v_merchant_id
        LIMIT 1;

        IF FOUND THEN v_menu_item_found := TRUE; END IF;
      EXCEPTION WHEN invalid_text_representation THEN NULL;
      END;
    END IF;

    DECLARE
      v_item_unit_price    NUMERIC;
      v_item_qty           INTEGER;
      v_item_subtotal      NUMERIC;
      v_item_name          TEXT;
      v_item_menu_id       UUID;
      v_item_cat_id        UUID;
      v_item_cat_name      TEXT;
      v_item_is_open       BOOLEAN;
      v_item_is_tax_exempt BOOLEAN;
    BEGIN
      v_item_qty        := COALESCE((v_item->>'quantity')::INTEGER, 1);
      v_item_unit_price := COALESCE((v_item->>'price')::NUMERIC, 0);
      v_item_subtotal   := COALESCE((v_item->>'total')::NUMERIC, 0);
      v_item_name       := v_item->>'name';

      IF v_menu_item_found THEN
        v_item_menu_id       := v_menu_item.id;
        v_item_cat_id        := v_menu_item.cat_id;
        v_item_cat_name      := v_menu_item.cat_name;
        v_item_is_open       := FALSE;
        v_item_is_tax_exempt := COALESCE(v_menu_item.is_tax_exempt, FALSE);
      ELSE
        v_item_menu_id       := NULL;
        v_item_cat_id        := NULL;
        v_item_cat_name      := NULL;
        v_item_is_open       := TRUE;
        v_item_is_tax_exempt := FALSE;
        v_warnings := v_warnings || jsonb_build_object(
          'type', 'menu_item_not_found',
          'external_id', v_item->>'external_id',
          'item_name', v_item_name,
          'message', 'Menu item not found in POS — inserted as open item'
        );
      END IF;

      IF p_subtotal > 0 AND NOT v_item_is_tax_exempt THEN
        v_item_tax_raw   := p_tax * (v_item_subtotal / p_subtotal);
        v_item_tax_floor := TRUNC(v_item_tax_raw, 2);
      ELSE
        v_item_tax_raw   := 0;
        v_item_tax_floor := 0;
      END IF;

      INSERT INTO public.order_items (
        order_id, menu_item_id, item_name, quantity, unit_price, subtotal,
        tax_amount, tax_rate, category_id, category_name,
        item_status, kitchen_status, sent_to_kitchen_at, display_order,
        special_instructions, is_open_item, is_tax_exempt,
        open_item_name, open_item_price,
        base_card_price, base_cash_price, cash_price, cash_unit_price,
        cash_subtotal, cash_tax_amount, metadata, created_at, updated_at
      ) VALUES (
        v_order_id, v_item_menu_id, v_item_name, v_item_qty, v_item_unit_price, v_item_subtotal,
        v_item_tax_floor, v_default_tax_rate, v_item_cat_id, v_item_cat_name,
        CASE WHEN p_auto_accept THEN 'sent' ELSE 'pending' END,
        v_kitchen_status,
        CASE WHEN p_auto_accept THEN NOW() ELSE NULL END,
        v_item_index,
        v_item->>'note', v_item_is_open, v_item_is_tax_exempt,
        CASE WHEN v_item_is_open THEN v_item_name ELSE NULL END,
        CASE WHEN v_item_is_open THEN v_item_unit_price ELSE NULL END,
        v_item_unit_price, v_item_unit_price, v_item_unit_price, v_item_unit_price,
        v_item_subtotal, v_item_tax_floor,
        jsonb_build_object(
          'source', 'online_order', 'provider', p_provider,
          'provider_item_id', v_item->>'id',
          'provider_external_id', v_item->>'external_id',
          'menu_item_matched', v_menu_item_found
        ),
        NOW(), NOW()
      )
      RETURNING id INTO v_order_item_id;

      v_tax_distributed := v_tax_distributed + v_item_tax_floor;
      v_tax_remainders  := array_append(v_tax_remainders, v_item_tax_raw - v_item_tax_floor);
      v_tax_item_ids    := array_append(v_tax_item_ids, v_order_item_id);
      v_tax_floors      := array_append(v_tax_floors, v_item_tax_floor);
      v_item_count      := v_item_count + 1;

      IF v_item->'modifiers' IS NOT NULL AND jsonb_array_length(v_item->'modifiers') > 0 THEN
        FOR v_modifier IN SELECT * FROM jsonb_array_elements(v_item->'modifiers')
        LOOP
          DECLARE
            v_mod_price NUMERIC;
            v_mod_qty   INTEGER;
          BEGIN
            v_mod_price := COALESCE((v_modifier->>'price')::NUMERIC, 0);
            v_mod_qty   := COALESCE((v_modifier->>'quantity')::INTEGER, 1);
            INSERT INTO public.order_item_modifiers (
              order_item_id, modifier_group_name, modifier_name,
              price_modifier, quantity, total_price, metadata
            ) VALUES (
              v_order_item_id,
              COALESCE(v_modifier->>'group_name', 'Modifier'),
              COALESCE(v_modifier->>'name', 'Unknown Modifier'),
              v_mod_price, v_mod_qty, v_mod_price * v_mod_qty,
              jsonb_build_object(
                'source', 'online_order', 'provider', p_provider,
                'provider_modifier_id', v_modifier->>'id'
              )
            );
          END;
        END LOOP;
      END IF;
    END;
  END LOOP;

  -- ========================================================================
  -- STEP 8: TAX REMAINDER DISTRIBUTION (Largest Remainder Method)
  -- ========================================================================
  DECLARE
    v_tax_deficit NUMERIC;
    v_penny_count INTEGER;
    v_num_items   INTEGER;
    i             INTEGER;
    j             INTEGER;
    v_max_rem     NUMERIC;
    v_max_idx     INTEGER;
    v_tmp_rem     NUMERIC;
    v_tmp_id      UUID;
    v_tmp_floor   NUMERIC;
  BEGIN
    v_tax_deficit := ROUND(p_tax - v_tax_distributed, 2);
    v_penny_count := ROUND(v_tax_deficit * 100)::INTEGER;
    v_num_items   := COALESCE(array_length(v_tax_remainders, 1), 0);

    IF v_penny_count > 0 AND v_num_items > 0 THEN
      FOR i IN 1..v_num_items LOOP
        v_max_rem := v_tax_remainders[i];
        v_max_idx := i;
        FOR j IN (i+1)..v_num_items LOOP
          IF v_tax_remainders[j] > v_max_rem THEN
            v_max_rem := v_tax_remainders[j];
            v_max_idx := j;
          END IF;
        END LOOP;
        IF v_max_idx != i THEN
          v_tmp_rem := v_tax_remainders[i];
          v_tax_remainders[i] := v_tax_remainders[v_max_idx];
          v_tax_remainders[v_max_idx] := v_tmp_rem;
          v_tmp_id := v_tax_item_ids[i];
          v_tax_item_ids[i] := v_tax_item_ids[v_max_idx];
          v_tax_item_ids[v_max_idx] := v_tmp_id;
          v_tmp_floor := v_tax_floors[i];
          v_tax_floors[i] := v_tax_floors[v_max_idx];
          v_tax_floors[v_max_idx] := v_tmp_floor;
        END IF;
      END LOOP;

      FOR i IN 1..LEAST(v_penny_count, v_num_items) LOOP
        UPDATE public.order_items
        SET tax_amount      = v_tax_floors[i] + 0.01,
            cash_tax_amount = v_tax_floors[i] + 0.01
        WHERE id = v_tax_item_ids[i];
      END LOOP;
    END IF;
  END;

  -- ========================================================================
  -- STEP 9: INSERT ORDER PAYMENT
  -- ========================================================================
  INSERT INTO public.order_payments (
    order_id, payment_method, status, amount, total_amount,
    subtotal_portion, tax_portion, tip_amount, terminal_type,
    is_cash_priced, cash_discount_applied, captured_at,
    location_id, merchant_id, metadata
  ) VALUES (
    v_order_id, 'external'::public.payment_method, 'paid'::public.payment_status,
    p_total, p_total + COALESCE(p_gratuity, 0),
    p_subtotal, p_tax, COALESCE(p_gratuity, 0),
    'none'::public.terminal_type, FALSE, FALSE, NOW(),
    p_location_id, v_merchant_id,
    jsonb_build_object(
      'source', 'online_order', 'provider', p_provider,
      'delivery_company', p_delivery_company,
      'provider_order_id', p_provider_order_id,
      'external_reference', p_external_reference,
      'payment_status_from_source', 'PAID'
    )
  )
  RETURNING id INTO v_payment_id;

  -- ========================================================================
  -- STEP 10: INSERT ORDER PAYMENT ITEMS
  -- ========================================================================
  INSERT INTO public.order_payment_items (
    order_payment_id, order_item_id, quantity_paid,
    unit_price_paid, subtotal_paid, tax_paid
  )
  SELECT v_payment_id, oi.id, oi.quantity, oi.unit_price, oi.subtotal, oi.tax_amount
  FROM public.order_items oi
  WHERE oi.order_id = v_order_id;

  -- ========================================================================
  -- STEP 11: ORDER STATUS HISTORY
  -- ========================================================================
  INSERT INTO public.order_status_history (
    order_id, from_status, to_status, notes, metadata
  ) VALUES (
    v_order_id, NULL, v_status,
    'Online order — ' || COALESCE(p_delivery_company, p_provider),
    jsonb_build_object(
      'source', 'online_order', 'provider', p_provider,
      'delivery_company', p_delivery_company,
      'auto_accepted', p_auto_accept,
      'provider_order_id', p_provider_order_id
    )
  );

  -- ========================================================================
  -- STEP 12: INSERT ONLINE_ORDERS LINK RECORD
  -- ========================================================================
  INSERT INTO public.online_orders (
    order_id, location_id, merchant_id, provider, provider_order_id,
    provider_restaurant_id, external_reference, delivery_company,
    placed_at, ready_by, estimated_delivery,
    provider_metadata, raw_payload, provider_status
  ) VALUES (
    v_order_id, p_location_id, v_merchant_id, v_provider_enum, p_provider_order_id,
    p_provider_restaurant_id, p_external_reference, p_delivery_company,
    p_placed_at, p_ready_by, p_estimated_delivery,
    p_provider_metadata, p_raw_payload,
    CASE WHEN p_auto_accept THEN 'confirmed' ELSE 'received' END
  );

  -- ========================================================================
  -- STEP 13: AUDIT LOG
  -- ========================================================================
  INSERT INTO public.audit_logs (
    actor_user_id, actor_name, organization_id,
    action, action_category, resource_type, resource_name,
    metadata, status
  ) VALUES (
    NULL, 'system',
    (SELECT clerk_org_id FROM public.merchants WHERE id = v_merchant_id),
    'online_order_created', 'order_management', 'order', v_order_number,
    jsonb_build_object(
      'order_id', v_order_id, 'order_type', v_order_type,
      'provider', p_provider, 'delivery_company', p_delivery_company,
      'provider_order_id', p_provider_order_id, 'auto_accepted', p_auto_accept,
      'item_count', v_item_count, 'total', p_total, 'tax', p_tax,
      'warnings', v_warnings
    ),
    'success'
  );

  -- ========================================================================
  -- RETURN
  -- ========================================================================
  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order_id,
    'order_number', v_order_number,
    'display_number', v_display_number,
    'status', v_status,
    'payment_status', 'paid',
    'item_count', v_item_count,
    'total', p_total,
    'tax', p_tax,
    'auto_accepted', p_auto_accept,
    'provider', p_provider,
    'warnings', v_warnings
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM,
    'error_detail', SQLSTATE,
    'provider', p_provider,
    'provider_order_id', p_provider_order_id
  );
END;$$;


ALTER FUNCTION "public"."process_online_order"("p_location_id" "uuid", "p_provider" "text", "p_provider_order_id" "text", "p_provider_restaurant_id" "text", "p_external_reference" "text", "p_delivery_company" "text", "p_provider_metadata" "jsonb", "p_order_type_raw" "text", "p_customer_name" "text", "p_customer_phone" "text", "p_customer_email" "text", "p_subtotal" numeric, "p_tax" numeric, "p_total" numeric, "p_gratuity" numeric, "p_surcharge" numeric, "p_delivery_charge" numeric, "p_discount" numeric, "p_placed_at" timestamp with time zone, "p_ready_by" timestamp with time zone, "p_estimated_delivery" timestamp with time zone, "p_items" "jsonb", "p_delivery_address" "jsonb", "p_order_notes" "text", "p_raw_payload" "jsonb", "p_auto_accept" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_online_order"("p_location_id" "uuid", "p_provider" "text", "p_provider_order_id" "text", "p_provider_restaurant_id" "text", "p_external_reference" "text", "p_delivery_company" "text", "p_provider_metadata" "jsonb", "p_order_type_raw" "text", "p_customer_name" "text", "p_customer_phone" "text", "p_customer_email" "text", "p_subtotal" numeric, "p_tax" numeric, "p_total" numeric, "p_gratuity" numeric, "p_surcharge" numeric, "p_delivery_charge" numeric, "p_discount" numeric, "p_placed_at" timestamp with time zone, "p_ready_by" timestamp with time zone, "p_estimated_delivery" timestamp with time zone, "p_items" "jsonb", "p_delivery_address" "jsonb", "p_order_notes" "text", "p_raw_payload" "jsonb", "p_auto_accept" boolean) IS 'Universal online order processor. v3: removed tax_category filter (picks any active rate), added self-healing tax recalculation when p_tax=0.';



CREATE OR REPLACE FUNCTION "public"."process_order_inventory_deduction"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_location_id UUID;
    v_order_item  RECORD;
    v_recipe_item RECORD;
    v_modifier    RECORD;
BEGIN
    SELECT location_id INTO v_location_id FROM orders WHERE id = p_order_id;
    IF v_location_id IS NULL THEN
        RETURN;
    END IF;

    -- Path 1: Direct menu_item_recipes → inventory_item_id
    FOR v_order_item IN
        SELECT
            oi.quantity,
            mir.inventory_item_id,
            mir.quantity_used,
            mir.quantity_multiplier
        FROM order_items oi
        JOIN menu_item_recipes mir ON mir.menu_item_id = oi.menu_item_id
        WHERE oi.order_id           = p_order_id
          AND oi.is_voided          = false
          AND mir.inventory_item_id IS NOT NULL
    LOOP
        PERFORM public.decrement_location_stock(
            v_order_item.inventory_item_id,
            v_location_id,
            v_order_item.quantity_used * v_order_item.quantity_multiplier * v_order_item.quantity
        );
    END LOOP;

    -- Path 2: Recipe-based — menu_item_recipes.recipe_id → recipe_items.inventory_item_id
    FOR v_order_item IN
        SELECT
            oi.quantity,
            mir.recipe_id,
            mir.quantity_multiplier
        FROM order_items oi
        JOIN menu_item_recipes mir ON mir.menu_item_id = oi.menu_item_id
        WHERE oi.order_id          = p_order_id
          AND oi.is_voided         = false
          AND mir.recipe_id        IS NOT NULL
          AND mir.inventory_item_id IS NULL
    LOOP
        FOR v_recipe_item IN
            SELECT ri.inventory_item_id, ri.quantity
            FROM recipe_items ri
            WHERE ri.recipe_id          = v_order_item.recipe_id
              AND ri.inventory_item_id  IS NOT NULL
        LOOP
            PERFORM public.decrement_location_stock(
                v_recipe_item.inventory_item_id,
                v_location_id,
                v_recipe_item.quantity * v_order_item.quantity_multiplier * v_order_item.quantity
            );
        END LOOP;
    END LOOP;

    -- Path 3: Modifier deductions
    -- order_item_modifiers.modifier_item_id = modifier_group_items.id = modifier_group_item_recipes.modifier_group_item_id
    FOR v_modifier IN
        SELECT
            oim.quantity,
            mgir.inventory_item_id,
            mgir.quantity_used
        FROM order_item_modifiers oim
        JOIN order_items oi ON oi.id = oim.order_item_id
        JOIN modifier_group_item_recipes mgir ON mgir.modifier_group_item_id = oim.modifier_item_id
        WHERE oi.order_id    = p_order_id
          AND oi.is_voided   = false
    LOOP
        PERFORM public.decrement_location_stock(
            v_modifier.inventory_item_id,
            v_location_id,
            v_modifier.quantity_used * v_modifier.quantity
        );
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."process_order_inventory_deduction"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_order_payment"("p_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric, "p_tip_amount" numeric DEFAULT 0, "p_amount_tendered" numeric DEFAULT NULL::numeric, "p_terminal_type" "text" DEFAULT 'dejavoo'::"text", "p_terminal_id" "text" DEFAULT NULL::"text", "p_device_id" "text" DEFAULT NULL::"text", "p_transaction_details" "jsonb" DEFAULT NULL::"jsonb", "p_item_allocations" "jsonb" DEFAULT NULL::"jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
    v_user_id text;
    v_staff_id uuid;
    v_order record;
    v_payment_id uuid;
    v_is_cash boolean;
    v_is_full_payment boolean;
    v_has_item_allocations boolean;
    
    -- Calculated amounts
    v_payment_total numeric;
    v_subtotal_portion numeric;
    v_tax_portion numeric;
    v_change_given numeric := 0;
    v_actual_tendered numeric;
    v_original_card_amount numeric;
    
    -- Order state after payment
    v_new_amount_paid numeric;
    v_remaining_due numeric;
    v_new_payment_status text;
    
    v_result jsonb;
BEGIN
    -- ============================================
    -- 1. AUTHENTICATION & AUTHORIZATION
    -- ============================================
    v_user_id := get_my_claim('sub');
    
    SELECT id INTO v_staff_id
    FROM public.staff_profiles
    WHERE user_id = v_user_id
    LIMIT 1;
    
    -- ============================================
    -- 2. GET ORDER WITH ACCESS CHECK
    -- ============================================
    SELECT *
    INTO v_order
    FROM public.orders
    WHERE id = p_order_id
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids());
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found or access denied';
    END IF;
    
    -- ============================================
    -- 3. VALIDATION
    -- ============================================
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Payment amount must be positive';
    END IF;
    
    IF v_order.payment_status = 'captured' THEN
        RAISE EXCEPTION 'Order is already fully paid';
    END IF;
    
    -- Determine payment characteristics
    v_is_cash := p_payment_method = 'cash';
    v_has_item_allocations := p_item_allocations IS NOT NULL AND jsonb_array_length(p_item_allocations) > 0;
    
    -- ============================================
    -- 4. CALCULATE AMOUNTS BASED ON PAYMENT TYPE
    -- ============================================
    
    IF v_is_cash THEN
        -- CASH PAYMENT: Use cash pricing
        
        -- Check if this is full payment (paying remaining balance)
        v_is_full_payment := p_amount >= v_order.amount_due 
                            OR p_amount >= v_order.cash_total - COALESCE(v_order.amount_paid, 0);
        
        IF v_is_full_payment AND NOT v_has_item_allocations THEN
            -- Full cash payment - use cash total
            v_payment_total := v_order.cash_total - COALESCE(v_order.amount_paid, 0);
            v_subtotal_portion := v_order.cash_subtotal * (v_payment_total / NULLIF(v_order.cash_total, 0));
            v_tax_portion := v_payment_total - v_subtotal_portion;
            v_original_card_amount := v_order.card_total - COALESCE(v_order.amount_paid, 0);
        ELSE
            -- Partial cash payment - prorate using cash pricing ratios
            v_payment_total := LEAST(p_amount, v_order.amount_due);
            IF v_order.cash_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.cash_subtotal / v_order.cash_total), 2);
                v_tax_portion := v_payment_total - v_subtotal_portion;
            ELSE
                v_subtotal_portion := v_payment_total;
                v_tax_portion := 0;
            END IF;
            -- Calculate what this would have been at card price
            v_original_card_amount := ROUND(v_payment_total * (v_order.card_total / NULLIF(v_order.cash_total, 0)), 2);
        END IF;
        
        -- Calculate change
        v_actual_tendered := COALESCE(p_amount_tendered, p_amount + p_tip_amount);
        v_change_given := GREATEST(v_actual_tendered - (v_payment_total + p_tip_amount), 0);
        
    ELSE
        -- CARD PAYMENT: Use card pricing
        v_payment_total := p_amount;
        v_actual_tendered := p_amount + p_tip_amount;
        v_change_given := 0;
        v_original_card_amount := p_amount;
        
        IF v_order.card_total > 0 THEN
            v_subtotal_portion := ROUND(v_payment_total * (v_order.card_subtotal / v_order.card_total), 2);
            v_tax_portion := v_payment_total - v_subtotal_portion;
        ELSE
            v_subtotal_portion := v_payment_total;
            v_tax_portion := 0;
        END IF;
    END IF;
    
    -- ============================================
    -- 5. CREATE PAYMENT RECORD
    -- ============================================
    INSERT INTO public.order_payments (
        order_id,
        payment_method,
        amount,
        tip_amount,
        total_amount,
        subtotal_portion,
        tax_portion,
        amount_tendered,
        change_given,
        is_cash_priced,
        cash_discount_applied,
        original_amount,
        status,
        terminal_type,
        processed_by_staff_id,
        processor_response,
        transaction_id,
        authorization_code,
        card_type,
        card_last_four,
        captured_at,
        metadata
    ) VALUES (
        p_order_id,
        p_payment_method::payment_method,
        v_payment_total,
        p_tip_amount,
        v_payment_total + p_tip_amount,
        v_subtotal_portion,
        v_tax_portion,
        v_actual_tendered,
        v_change_given,
        v_is_cash,
        v_is_cash AND v_original_card_amount > v_payment_total,
        v_original_card_amount,
        'captured',
        p_terminal_type::terminal_type,
        v_staff_id,
        p_transaction_details,
        p_transaction_details->>'transaction_id',
        p_transaction_details->>'authorization_code',
        p_transaction_details->>'card_type',
        p_transaction_details->>'card_last_four',
        now(),
        jsonb_build_object(
            'device_id', p_device_id,
            'terminal_id', p_terminal_id,
            'reason', p_reason
        )
    )
    RETURNING id INTO v_payment_id;
    
    -- ============================================
    -- 6. HANDLE PER-ITEM ALLOCATIONS (if provided)
    -- ============================================
    IF v_has_item_allocations THEN
        INSERT INTO public.order_payment_items (
            order_payment_id,
            order_item_id,
            quantity_paid,
            unit_price_paid,
            subtotal_paid
        )
        SELECT 
            v_payment_id,
            (item->>'order_item_id')::uuid,
            COALESCE((item->>'quantity')::integer, 1),
            COALESCE((item->>'unit_price')::numeric, (item->>'amount')::numeric),
            (item->>'amount')::numeric
        FROM jsonb_array_elements(p_item_allocations) AS item;
    END IF;
    
    -- ============================================
    -- 7. UPDATE ORDER STATE
    -- ============================================
    v_new_amount_paid := COALESCE(v_order.amount_paid, 0) + v_payment_total + p_tip_amount;
    v_remaining_due := GREATEST(v_order.total_amount - v_new_amount_paid, 0);
    
    -- For cash full payment, recalculate based on cash total
    IF v_is_cash AND v_is_full_payment AND NOT v_has_item_allocations THEN
        v_remaining_due := 0;
    END IF;
    
    v_new_payment_status := CASE
        WHEN v_remaining_due <= 0 THEN 'paid'
        WHEN v_new_amount_paid > 0 THEN 'partial'
        ELSE 'pending'
    END;
    
    UPDATE public.orders SET
        amount_paid = v_new_amount_paid,
        amount_due = v_remaining_due,
        tip_amount = COALESCE(tip_amount, 0) + p_tip_amount,
        payment_status = v_new_payment_status::payment_status,
        
        -- Update effective totals from all payments
        effective_subtotal = (
            SELECT COALESCE(SUM(subtotal_portion), 0)
            FROM public.order_payments
            WHERE order_id = p_order_id AND status = 'captured' AND is_voided = false
        ),
        effective_tax_amount = (
            SELECT COALESCE(SUM(tax_portion), 0)
            FROM public.order_payments
            WHERE order_id = p_order_id AND status = 'captured' AND is_voided = false
        ),
        effective_total = (
            SELECT COALESCE(SUM(total_amount), 0)
            FROM public.order_payments
            WHERE order_id = p_order_id AND status = 'captured' AND is_voided = false
        ),
        
        -- Track if any cash discount was applied
        cash_discount_applied = EXISTS(
            SELECT 1 FROM public.order_payments
            WHERE order_id = p_order_id 
              AND is_cash_priced = true 
              AND is_voided = false
        ),
        cash_discount_amount = (
            SELECT COALESCE(SUM(original_amount - amount), 0)
            FROM public.order_payments
            WHERE order_id = p_order_id 
              AND is_cash_priced = true 
              AND is_voided = false
        ),
        
        -- Update order status if fully paid
        status = CASE
            WHEN v_remaining_due <= 0 AND status = 'ready' THEN 'completed'::order_status
            ELSE status
        END,
        
        completed_at = CASE
            WHEN v_remaining_due <= 0 AND completed_at IS NULL THEN now()
            ELSE completed_at
        END,
        
        updated_at = now()
    WHERE id = p_order_id;
    
    -- ============================================
    -- 8. AUDIT LOG
    -- ============================================
    INSERT INTO public.audit_logs (
        actor_user_id,
        action,
        action_category,
        resource_type,
        resource_name,
        metadata,
        status
    ) VALUES (
        v_user_id,
        'payment_processed',
        'order_management',
        'payment',
        v_payment_id::text,
        jsonb_build_object(
            'order_id', p_order_id,
            'payment_method', p_payment_method,
            'amount', v_payment_total,
            'tip_amount', p_tip_amount,
            'amount_tendered', v_actual_tendered,
            'change_given', v_change_given,
            'is_cash_priced', v_is_cash,
            'original_card_amount', v_original_card_amount,
            'cash_savings', CASE WHEN v_is_cash THEN v_original_card_amount - v_payment_total ELSE 0 END,
            'has_item_allocations', v_has_item_allocations
        ),
        'success'
    );
    
    -- ============================================
    -- 9. RETURN RESULT
    -- ============================================
    v_result := jsonb_build_object(
        'success', true,
        'payment_id', v_payment_id,
        'order_id', p_order_id,
        'payment_method', p_payment_method,
        'amount_applied', v_payment_total,
        'tip_amount', p_tip_amount,
        'total_charged', v_payment_total + p_tip_amount,
        'amount_tendered', v_actual_tendered,
        'change_given', v_change_given,
        'is_cash_priced', v_is_cash,
        'original_card_amount', v_original_card_amount,
        'cash_savings', CASE WHEN v_is_cash THEN v_original_card_amount - v_payment_total ELSE 0 END,
        'order_amount_paid', v_new_amount_paid,
        'order_amount_due', v_remaining_due,
        'order_fully_paid', v_remaining_due <= 0,
        'order_payment_status', v_new_payment_status
    );
    
    RETURN v_result;
END;$$;


ALTER FUNCTION "public"."process_order_payment"("p_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric, "p_tip_amount" numeric, "p_amount_tendered" numeric, "p_terminal_type" "text", "p_terminal_id" "text", "p_device_id" "text", "p_transaction_details" "jsonb", "p_item_allocations" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_payment_v6"("p_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric DEFAULT NULL::numeric, "p_amount_tendered" numeric DEFAULT NULL::numeric, "p_tip_amount" numeric DEFAULT 0, "p_item_allocations" "jsonb" DEFAULT '[]'::"jsonb", "p_split_count" integer DEFAULT 1, "p_split_portion_index" integer DEFAULT NULL::integer, "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_terminal_response" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$DECLARE
    v_order record;
    v_payment_id uuid;
    v_is_cash boolean;
    v_is_item_payment boolean;
    v_is_split_payment boolean;
    v_payment_total numeric;
    v_new_sync_version integer;
    v_subtotal_portion numeric := 0;
    v_tax_portion numeric := 0;
    v_change_given numeric := 0;
    v_new_amount_paid numeric;
    v_new_amount_due numeric;         -- ALWAYS card price
    v_new_cash_amount_due numeric;    -- For reference
    v_current_pricing_mode text;
    v_new_pricing_mode text;
    v_items_subtotal numeric := 0;
    v_items_tax numeric := 0;
    v_covered_items uuid[] := '{}';
    v_covered_items_json jsonb := '[]'::jsonb;

    -- Unpaid tracking (ALWAYS both prices)
    v_unpaid_items_count integer := 0;
    v_unpaid_card_total numeric := 0;
    v_unpaid_cash_total numeric := 0;

    -- Pre-payment unpaid totals (for full remaining detection)
    v_pre_unpaid_card_total numeric := 0;
    v_pre_unpaid_cash_total numeric := 0;

    -- Refund balance tracking (for custom refunds not tied to items)
    v_effective_paid numeric := 0;
    v_payment_based_due numeric := 0;
    v_custom_refund_balance numeric := 0;

    -- Payment totals by type
    v_total_cash_paid numeric := 0;
    v_total_card_paid numeric := 0;

    -- Fully paid detection
    v_order_fully_paid boolean := false;

    -- Split evenly tracking
    v_split_card_portion numeric;
    v_split_cash_portion numeric;
    v_portions_paid integer := 0;
    v_portions_remaining integer := 0;
    v_paid_portion_indexes integer[];
    v_is_last_portion boolean := false;

    -- Full remaining payment detection
    v_is_full_remaining boolean := false;
    v_target_unpaid numeric := 0;

    -- Dejavoo Transaction Tracking
    v_dejavoo_reference_id text;
    v_dejavoo_transaction_number text;
    v_dejavoo_auth_code text;
    v_dejavoo_batch_number text;
    v_dejavoo_invoice_number text;
    v_dejavoo_rrn text;
    v_dejavoo_entry_mode text;
    v_dejavoo_result_code text;
    v_dejavoo_status_code text;
    v_has_dejavoo_transaction boolean := false;
    v_dejavoo_last_four text;
BEGIN
    v_is_cash := p_payment_method = 'cash';
    v_is_item_payment := p_item_allocations IS NOT NULL AND jsonb_array_length(p_item_allocations) > 0;
    v_is_split_payment := p_split_count IS NOT NULL AND p_split_count > 1;

    -- ============================================
    -- 1. Get Order with Validation
    -- ============================================
    SELECT * INTO v_order
    FROM public.orders
    WHERE id = p_order_id
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids());

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found or access denied';
    END IF;

    -- Allow payment if order has been refunded (amount_due > 0) even if payment_status is 'paid'
    IF v_order.payment_status = 'paid' AND COALESCE(v_order.amount_due, 0) <= 0 THEN
        RAISE EXCEPTION 'Order is already fully paid';
    END IF;

    v_current_pricing_mode := v_order.payment_pricing_mode::text;

     -- ============================================
    -- 2. Calculate CURRENT Unpaid Totals from Items
    --    (BEFORE this payment - source of truth)
    --    Includes prorated discounts for remaining quantities
    --    NOTE: Accounts for refunded_quantity - refunded items need to be paid again
    -- ============================================
    SELECT
        COUNT(*),
        -- Card total: (remaining_qty * unit_price) - prorated_discount + tax_on_discounted
        -- remaining_qty = quantity - paid_quantity + refunded_quantity
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price)
            - ROUND(
                COALESCE(oi.discount_amount, 0) *
                (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
            , 2)
            + ROUND(
                (
                    ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price)
                    - ROUND(
                        COALESCE(oi.discount_amount, 0) *
                        (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
                    , 2)
                ) * COALESCE(oi.tax_rate, 0) / 100
            , 2)
        ), 0),
        -- Cash total: same formula with cash_price
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price)
            - ROUND(
                COALESCE(oi.discount_amount, 0) *
                (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
            , 2)
            + ROUND(
                (
                    ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price)
                    - ROUND(
                        COALESCE(oi.discount_amount, 0) *
                        (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
                    , 2)
                ) * COALESCE(oi.tax_rate, 0) / 100
            , 2)
        ), 0)
    INTO v_unpaid_items_count, v_pre_unpaid_card_total, v_pre_unpaid_cash_total
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id
      AND oi.is_voided = false
      AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0;

    -- Account for custom refund balance (refunds not tied to specific items)
    -- Same logic as calculate_order_totals_fast
    -- Use original_amount (card-equivalent) to avoid phantom balance when cash payments
    -- are made at lower prices: original_amount stores the card-equivalent value,
    -- and refunded_amount is scaled proportionally to card-equivalent denomination
    SELECT COALESCE(SUM(
        COALESCE(original_amount, amount)
        - COALESCE(refunded_amount, 0) * COALESCE(original_amount, amount) / NULLIF(amount, 0)
    ), 0)
    INTO v_effective_paid
    FROM public.order_payments
    WHERE order_id = p_order_id
      AND status IN ('captured', 'partially_refunded', 'refunded')
      AND is_voided = false;

    v_payment_based_due := GREATEST(v_order.card_total - v_effective_paid, 0);
    v_custom_refund_balance := GREATEST(v_payment_based_due - v_pre_unpaid_card_total, 0);
    v_pre_unpaid_card_total := v_pre_unpaid_card_total + v_custom_refund_balance;
    v_pre_unpaid_cash_total := v_pre_unpaid_cash_total + v_custom_refund_balance;

    -- Fix: Clamp item-based unpaid totals to payment-based due when partial payments exist.
    -- Partial payments don't mark items as paid, so item-based totals stay at full amount.
    -- payment_based_due tracks actual remaining after prior payments.
    IF v_payment_based_due < v_pre_unpaid_card_total THEN
        IF v_pre_unpaid_card_total > 0 THEN
            v_pre_unpaid_cash_total := ROUND(
                v_pre_unpaid_cash_total * v_payment_based_due / v_pre_unpaid_card_total, 2
            );
        END IF;
        v_pre_unpaid_card_total := v_payment_based_due;
    END IF;
    -- March 13th

    -- If nothing to pay, return early
    -- Allow payment when custom refund balance exists (payment-level refund debt)
    IF v_unpaid_items_count = 0 AND v_custom_refund_balance <= 0 THEN
        RAISE EXCEPTION 'No unpaid items remaining on this order';
    END IF;

    -- ============================================
    -- 3. Get Existing Payment Totals by Type
    -- ============================================
    SELECT
        COALESCE(SUM(CASE WHEN is_cash_priced THEN total_amount ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN NOT is_cash_priced THEN total_amount ELSE 0 END), 0)
    INTO v_total_cash_paid, v_total_card_paid
    FROM public.order_payments
    WHERE order_id = p_order_id
      AND status = 'captured';


    -- ============================================
    -- 4. Split Payment Validation
    -- ============================================
    IF v_is_split_payment THEN
        IF p_split_portion_index IS NULL THEN
            RAISE EXCEPTION 'Split portion index is required for split payments';
        END IF;

        IF p_split_portion_index < 1 OR p_split_portion_index > p_split_count THEN
            RAISE EXCEPTION 'Invalid split portion index: % (must be 1-%)', p_split_portion_index, p_split_count;
        END IF;

        IF EXISTS (
            SELECT 1 FROM public.order_payments
            WHERE order_id = p_order_id
              AND split_portion_index = p_split_portion_index
              AND status = 'captured'
        ) THEN
            RAISE EXCEPTION 'Split portion % has already been paid', p_split_portion_index;
        END IF;

        SELECT
            COUNT(*),
            COALESCE(array_agg(split_portion_index ORDER BY split_portion_index), ARRAY[]::integer[])
        INTO v_portions_paid, v_paid_portion_indexes
        FROM public.order_payments
        WHERE order_id = p_order_id
          AND split_portion_index IS NOT NULL
          AND status = 'captured';

        v_portions_remaining := p_split_count - v_portions_paid - 1;
        v_is_last_portion := (v_portions_remaining = 0);
    END IF;

    -- ============================================
    -- 5. Determine Pricing Mode (for tracking only)
    -- ============================================
    IF v_current_pricing_mode IS NULL THEN
        v_new_pricing_mode := CASE WHEN v_is_cash THEN 'cash' ELSE 'card' END;
    ELSIF v_current_pricing_mode = 'card' AND v_is_cash THEN
        v_new_pricing_mode := 'mixed';
    ELSIF v_current_pricing_mode = 'cash' AND NOT v_is_cash THEN
        v_new_pricing_mode := 'mixed';
    ELSE
        v_new_pricing_mode := v_current_pricing_mode;
    END IF;

    -- ============================================
    -- 6. Calculate Payment Amount Based on Scenario
    -- ============================================
    IF v_is_item_payment THEN
        -- ========================================
        -- PER-ITEM PAYMENT (with per-item quantities)
        -- NOTE: Accounts for refunded_quantity - refunded items can be paid again
        -- effective_unpaid = quantity - paid_quantity + refunded_quantity
        -- ========================================
        WITH payment_calc AS (
            SELECT
                oi.id,
                oi.item_name,
                oi.quantity AS original_qty,
                oi.unit_price,
                oi.cash_price,
                oi.tax_rate,
                oi.discount_amount,
                COALESCE(oi.paid_quantity, 0) AS already_paid_qty,
                COALESCE(oi.refunded_quantity, 0) AS refunded_qty,
                -- Effective unpaid = quantity - paid + refunded
                (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) AS effective_unpaid,

                -- Quantity being paid (capped at effective unpaid)
                LEAST(
                    COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                    oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                ) AS qty_paying,

                -- Prorated discount: total_discount * (qty_paying / original_qty)
                ROUND(
                    COALESCE(oi.discount_amount, 0) *
                    LEAST(
                        COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                        oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                    )::numeric / NULLIF(oi.quantity, 0)
                , 2) AS prorated_discount

            FROM jsonb_array_elements(p_item_allocations) AS alloc
            JOIN public.order_items oi ON oi.id = (alloc.value->>'order_item_id')::uuid
            WHERE oi.order_id = p_order_id
              AND oi.is_voided = false
              AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0
        )
        SELECT
            -- Subtotal: (qty * price) - prorated_discount
            COALESCE(SUM(
                CASE WHEN v_is_cash
                    THEN (pc.qty_paying * pc.cash_price) - pc.prorated_discount
                    ELSE (pc.qty_paying * pc.unit_price) - pc.prorated_discount
                END
            ), 0),

            -- Tax: on discounted amount
            COALESCE(SUM(
                ROUND(
                    (
                        CASE WHEN v_is_cash
                            THEN (pc.qty_paying * pc.cash_price) - pc.prorated_discount
                            ELSE (pc.qty_paying * pc.unit_price) - pc.prorated_discount
                        END
                    ) * COALESCE(pc.tax_rate, 0) / 100
                , 2)
            ), 0),

            array_agg(pc.id)
        INTO v_items_subtotal, v_items_tax, v_covered_items
        FROM payment_calc pc;

        v_payment_total := v_items_subtotal + v_items_tax;
        v_subtotal_portion := v_items_subtotal;
        v_tax_portion := v_items_tax;

        -- Build detailed items JSON with allocated quantities
        WITH payment_calc AS (
            SELECT
                oi.id,
                oi.item_name,
                oi.quantity AS original_qty,
                oi.unit_price,
                oi.cash_price,
                LEAST(
                    COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                    oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                ) AS qty_paying,
                ROUND(
                    COALESCE(oi.discount_amount, 0) *
                    LEAST(
                        COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                        oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                    )::numeric / NULLIF(oi.quantity, 0)
                , 2) AS prorated_discount
            FROM jsonb_array_elements(p_item_allocations) AS alloc
            JOIN public.order_items oi ON oi.id = (alloc.value->>'order_item_id')::uuid
            WHERE oi.order_id = p_order_id
              AND oi.is_voided = false
              AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0
        )
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'order_item_id', pc.id,
            'item_name', pc.item_name,
            'quantity_paid', pc.qty_paying,
            'unit_price', CASE WHEN v_is_cash THEN pc.cash_price ELSE pc.unit_price END,
            'prorated_discount', pc.prorated_discount,
            'subtotal', CASE WHEN v_is_cash
                THEN (pc.qty_paying * pc.cash_price) - pc.prorated_discount
                ELSE (pc.qty_paying * pc.unit_price) - pc.prorated_discount
            END
        )), '[]'::jsonb)
        INTO v_covered_items_json
        FROM payment_calc pc;

        -- Update items with allocated quantities (INCREMENT paid_quantity)
        -- Cap at effective unpaid (quantity - paid + refunded)
        UPDATE public.order_items oi
        SET
            paid_quantity = COALESCE(oi.paid_quantity, 0) + LEAST(
                COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
            ),
            price_paid = CASE WHEN v_is_cash THEN oi.cash_price ELSE oi.unit_price END,
            updated_at = now()
        FROM jsonb_array_elements(p_item_allocations) AS alloc
        WHERE oi.id = (alloc.value->>'order_item_id')::uuid
          AND oi.order_id = p_order_id
          AND oi.is_voided = false;

    ELSIF v_is_split_payment THEN
        -- ========================================
        -- SPLIT EVENLY PAYMENT
        -- ========================================
        v_split_card_portion := ROUND(v_order.card_total / p_split_count, 2);
        v_split_cash_portion := ROUND(v_order.cash_total / p_split_count, 2);

        IF v_is_last_portion THEN
            -- Last portion: pay remainder to handle rounding
            -- Use portion-based calculation instead of tracking paid amounts,
            -- because v_total_cash/card_paid only counts payments of that type,
            -- which breaks when splits use mixed payment methods (e.g. Cash + Card).
            IF v_is_cash THEN
                v_payment_total := v_order.cash_total - (v_split_cash_portion * (p_split_count - 1));
            ELSE
                v_payment_total := v_order.card_total - (v_split_card_portion * (p_split_count - 1));
            END IF;
            -- Ensure non-negative
            v_payment_total := GREATEST(v_payment_total, 0);
        ELSE
            IF v_is_cash THEN
                v_payment_total := v_split_cash_portion;
            ELSE
                v_payment_total := v_split_card_portion;
            END IF;
        END IF;

        -- Pro-rate subtotal/tax
        IF v_is_cash AND v_order.cash_total > 0 THEN
            v_subtotal_portion := ROUND(v_payment_total * (v_order.cash_subtotal / v_order.cash_total), 2);
        ELSIF v_order.card_total > 0 THEN
            v_subtotal_portion := ROUND(v_payment_total * (v_order.card_subtotal / v_order.card_total), 2);
        END IF;
        v_tax_portion := v_payment_total - v_subtotal_portion;

    ELSE
        -- ========================================
        -- FULL/REMAINING or PARTIAL PAYMENT
        -- Supports hybrid: pay items first, then pay remaining
        -- ========================================

        -- Determine target unpaid amount (from items, source of truth)
        v_target_unpaid := CASE WHEN v_is_cash
            THEN v_pre_unpaid_cash_total
            ELSE v_pre_unpaid_card_total
        END;

        -- ============================================
        -- FIX V6: Added 0.05 tolerance for rounding differences
        -- between frontend and backend calculations
        -- ============================================
        v_is_full_remaining := (p_amount IS NULL) OR (p_amount >= (v_target_unpaid - 0.05));

        IF v_is_full_remaining THEN
            -- ========================================
            -- FULL REMAINING: Pay all unpaid items
            -- NOTE: Accounts for refunded_quantity - refunded items need to be paid again
            -- effective_unpaid = quantity - paid_quantity + refunded_quantity
            -- ========================================
            v_payment_total := v_target_unpaid;

            -- Pro-rate subtotal/tax based on order ratios
            IF v_is_cash AND v_order.cash_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.cash_subtotal / v_order.cash_total), 2);
            ELSIF v_order.card_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.card_subtotal / v_order.card_total), 2);
            END IF;
            v_tax_portion := v_payment_total - v_subtotal_portion;

            -- ============================================
            -- FIX V6: Get items BEFORE update for reliable tracking
            -- Include items with effective unpaid > 0 (accounts for refunds)
            -- ============================================
            SELECT array_agg(id)
            INTO v_covered_items
            FROM public.order_items
            WHERE order_id = p_order_id
              AND is_voided = false
              AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

            -- CRITICAL: Mark ALL remaining items as paid
            -- Set paid_quantity = quantity + refunded_quantity so effective_unpaid becomes 0
            UPDATE public.order_items
            SET
                paid_quantity = quantity + COALESCE(refunded_quantity, 0),
                price_paid = CASE WHEN v_is_cash THEN cash_price ELSE unit_price END,
                updated_at = now()
            WHERE order_id = p_order_id
              AND is_voided = false
              AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

            -- Build items JSON for response
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'order_item_id', oi.id,
                'item_name', oi.item_name,
                'quantity_paid', oi.quantity,
                'unit_price', oi.price_paid,
                'subtotal', oi.quantity * oi.price_paid
            )), '[]'::jsonb)
            INTO v_covered_items_json
            FROM public.order_items oi
            WHERE oi.id = ANY(v_covered_items);

        ELSE
            -- ========================================
            -- PARTIAL: Pay specific amount (no item marking)
            -- ========================================
            -- This is a partial amount payment - items remain unpaid
            -- Used for scenarios like "I'll pay $50 toward the bill"
            v_payment_total := LEAST(p_amount, v_target_unpaid);
            v_payment_total := GREATEST(v_payment_total, 0);

            -- Pro-rate subtotal/tax
            IF v_is_cash AND v_order.cash_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.cash_subtotal / v_order.cash_total), 2);
            ELSIF v_order.card_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.card_subtotal / v_order.card_total), 2);
            END IF;
            v_tax_portion := v_payment_total - v_subtotal_portion;

            -- No items marked as paid - this is a partial amount against the order
            -- Items will be marked when a subsequent "pay remaining" call is made
        END IF;
    END IF;

    -- ============================================
    -- 6.5 Calculate Change (Cash Only)
    -- ============================================
    IF v_is_cash THEN
        v_change_given := GREATEST(
            COALESCE(p_amount_tendered, v_payment_total) - (v_payment_total + COALESCE(p_tip_amount, 0)),
            0
        );
    END IF;


    -- ============================================
    -- 6.6 Dejavoo Terminal Response
    -- ============================================
     IF p_terminal_response ? 'dejavoo_transaction' THEN
        v_has_dejavoo_transaction := true;
        v_dejavoo_reference_id := p_terminal_response->'dejavoo_transaction'->>'referenceId';
        v_dejavoo_transaction_number := p_terminal_response ->'dejavoo_transaction'->>'transactionNumber';
        v_dejavoo_auth_code := p_terminal_response->'dejavoo_transaction'->>'authCode';
        v_dejavoo_batch_number := p_terminal_response->'dejavoo_transaction'->>'batchNumber';
        v_dejavoo_invoice_number := p_terminal_response->'dejavoo_transaction'->>'invoiceNumber';
        v_dejavoo_rrn := p_terminal_response->'dejavoo_transaction'->>'rrn';
        v_dejavoo_entry_mode := p_terminal_response->'dejavoo_transaction'->>'entryMode';
        v_dejavoo_result_code := p_terminal_response->'dejavoo_transaction'->>'resultCode';
        v_dejavoo_status_code := p_terminal_response->'dejavoo_transaction'->>'statusCode';
        v_dejavoo_last_four := p_terminal_response->'dejavoo_transaction'->>'cardLast4';
    END IF;


    -- ============================================
    -- 6.7 Castles Terminal Response
    -- Reuses v_dejavoo_* variables so the INSERT path below works unchanged.
    -- ============================================
    IF p_terminal_response ? 'castles_transaction' THEN
        v_has_dejavoo_transaction := true;
        v_dejavoo_reference_id := p_terminal_response->'castles_transaction'->>'referenceId';
        v_dejavoo_transaction_number := p_terminal_response->'castles_transaction'->>'referenceId';
        v_dejavoo_auth_code := p_terminal_response->'castles_transaction'->>'approvalCode';
        v_dejavoo_batch_number := p_terminal_response->'castles_transaction'->>'batchNumber';
        v_dejavoo_rrn := p_terminal_response->'castles_transaction'->>'rrn';
        v_dejavoo_entry_mode := p_terminal_response->'castles_transaction'->>'entryMode';
        v_dejavoo_result_code := p_terminal_response->'castles_transaction'->>'resultCode';
        v_dejavoo_status_code := p_terminal_response->'castles_transaction'->>'resultCode';
        v_dejavoo_last_four := p_terminal_response->'castles_transaction'->>'cardLast4';
    END IF;

    -- ============================================
    -- 7. Create Payment Record
    -- ============================================
  INSERT INTO public.order_payments (
        order_id,
        payment_method,
        amount,
        tip_amount,
        total_amount,
        subtotal_portion,
        tax_portion,
        amount_tendered,
        change_given,
        is_cash_priced,
        cash_discount_applied,
        original_amount,
        covers_items,
        split_portion_index,
        split_count,
        status,
        terminal_type,
        processed_by_staff_id,
        processor_response,
        reference_number,
        transaction_id,
        authorization_code,
        dejavoo_response_code,
        dejavoo_batch_number,
        dejavoo_invoice_number,
        card_type,
        card_last_four,
        captured_at,
        initiated_at,
        merchant_id,
        location_id,
        rrn,
        result_code,
        result_message
    ) VALUES (
        p_order_id,
        p_payment_method::payment_method,
        v_payment_total,
        COALESCE(p_tip_amount, 0),
        v_payment_total + COALESCE(p_tip_amount, 0),
        v_subtotal_portion,
        v_tax_portion,
        CASE WHEN v_is_cash THEN COALESCE(p_amount_tendered, v_payment_total) END,
        v_change_given,
        v_is_cash,
        v_is_cash,
        CASE WHEN v_is_cash
            THEN ROUND(v_payment_total * v_order.card_total / NULLIF(v_order.cash_total, 0), 2)
            ELSE v_payment_total
        END,
        CASE WHEN array_length(v_covered_items, 1) > 0 THEN v_covered_items ELSE NULL END,
        p_split_portion_index,
        p_split_count,
        'captured',
        CASE
            WHEN v_is_cash THEN 'cash_drawer'
            WHEN p_terminal_response ? 'castles_transaction' THEN 'castles'
            ELSE 'dejavoo'
        END::terminal_type,
        p_staff_id,
        p_terminal_response,
        COALESCE(v_dejavoo_reference_id, p_terminal_response->>'transaction_id'),
        COALESCE(v_dejavoo_transaction_number, p_terminal_response->>'transaction_id'),
        COALESCE(v_dejavoo_auth_code, p_terminal_response->>'authorization_code'),
        v_dejavoo_status_code,
        v_dejavoo_batch_number,
        v_dejavoo_invoice_number,
        COALESCE(
            p_terminal_response->'dejavoo_transaction'->>'cardType',
            p_terminal_response->'castles_transaction'->>'cardType',
            p_terminal_response->>'card_type'
        ),
        v_dejavoo_last_four,
        now(),
        now(),
        v_order.merchant_id,
        v_order.location_id,
        v_dejavoo_rrn,
        v_dejavoo_result_code,
        COALESCE(
            p_terminal_response->'dejavoo_transaction'->>'resultMessage',
            p_terminal_response->'castles_transaction'->>'statusMessage'
        )
    )
    RETURNING id INTO v_payment_id;

 PERFORM log_payment_event(
        p_payment_id := v_payment_id,
        p_order_id := p_order_id,
        p_location_id := v_order.location_id,
        p_event_type := 'captured',
        p_amount := v_payment_total,
        p_tip_amount := COALESCE(p_tip_amount, 0),
        p_previous_status := NULL,
        p_new_status := 'captured',
        p_psp_reference := COALESCE(
            v_dejavoo_reference_id,
            v_dejavoo_transaction_number,
            p_terminal_response->>'transaction_id'
        ),
        p_auth_code := v_dejavoo_auth_code,
        p_staff_id := p_staff_id,
        p_terminal_id := COALESCE(
            p_terminal_response->'castles_transaction'->>'terminalId',
            p_terminal_response->'dejavoo_transaction'->>'terminalId',
            p_terminal_response->>'terminal_id'
        ),
        p_result_code := COALESCE(v_dejavoo_result_code, '00'),
        p_response_message := CASE
            WHEN v_is_cash THEN 'Cash payment captured'
            ELSE COALESCE(
                p_terminal_response->'dejavoo_transaction'->>'resultMessage',
                p_terminal_response->'castles_transaction'->>'statusMessage',
                'Card payment captured successfully'
            )
        END,
        p_raw_response := p_terminal_response,
        p_reason := NULL
    );
    
 PERFORM log_payment_event(
        p_payment_id := v_payment_id,
        p_order_id := p_order_id,
        p_location_id := v_order.location_id,
        p_event_type := 'captured',
        p_amount := v_payment_total,
        p_tip_amount := COALESCE(p_tip_amount, 0),
        p_previous_status := NULL,
        p_new_status := 'captured',
        p_psp_reference := COALESCE(
            v_dejavoo_reference_id,
            v_dejavoo_transaction_number,
            p_terminal_response->>'transaction_id'
        ),
        p_auth_code := v_dejavoo_auth_code,
        p_staff_id := p_staff_id,
        p_terminal_id := COALESCE(
            p_terminal_response->'dejavoo_transaction'->>'terminalId',
            p_terminal_response->>'terminal_id'
        ),
        p_result_code := COALESCE(v_dejavoo_result_code, '00'),
        p_response_message := CASE
            WHEN v_is_cash THEN 'Cash payment captured'
            ELSE COALESCE(
                p_terminal_response->'dejavoo_transaction'->>'resultMessage',
                'Card payment captured successfully'
            )
        END,
        p_raw_response := p_terminal_response,
        p_reason := NULL
    );

    -- ============================================
    -- 8. Per-Item: Create order_payment_items
    --    NOTE: Accounts for refunded_quantity in effective unpaid calculation
    -- ============================================
    IF v_is_item_payment AND array_length(v_covered_items, 1) > 0 THEN
        WITH payment_calc AS (
            SELECT
                oi.id,
                oi.price_paid,
                oi.tax_rate,
                -- effective_unpaid = quantity - paid_quantity + refunded_quantity
                LEAST(
                    COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                    oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                ) AS qty_paid,
                ROUND(
                    COALESCE(oi.discount_amount, 0) *
                    LEAST(
                        COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                        oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                    )::numeric / NULLIF(oi.quantity, 0)
                , 2) AS prorated_discount
            FROM jsonb_array_elements(p_item_allocations) AS alloc
            JOIN public.order_items oi ON oi.id = (alloc.value->>'order_item_id')::uuid
            WHERE oi.order_id = p_order_id
              AND oi.is_voided = false
        )
        INSERT INTO public.order_payment_items (
            order_payment_id,
            order_item_id,
            quantity_paid,
            unit_price_paid,
            subtotal_paid,
            tax_paid
        )
        SELECT
            v_payment_id,
            pc.id,
            pc.qty_paid,
            pc.price_paid,
            (pc.qty_paid * pc.price_paid) - pc.prorated_discount,
            ROUND(((pc.qty_paid * pc.price_paid) - pc.prorated_discount) * COALESCE(pc.tax_rate, 0) / 100, 2)
        FROM payment_calc pc;

    ELSIF v_is_full_remaining AND array_length(v_covered_items, 1) > 0 THEN
        INSERT INTO public.order_payment_items (
            order_payment_id,
            order_item_id,
            quantity_paid,
            unit_price_paid,
            subtotal_paid,
            tax_paid
        )
        SELECT
            v_payment_id,
            oi.id,
            oi.quantity,
            oi.price_paid,
            oi.quantity * oi.price_paid - ROUND(COALESCE(oi.discount_amount, 0), 2),
            ROUND((oi.quantity * oi.price_paid - ROUND(COALESCE(oi.discount_amount, 0), 2)) * COALESCE(oi.tax_rate, 0) / 100, 2)
        FROM public.order_items oi
        WHERE oi.id = ANY(v_covered_items)
          AND oi.order_id = p_order_id
          AND oi.is_voided = false;
    END IF;

    -- ============================================
    -- 9. Update Payment Totals (include this payment)
    -- ============================================
    IF v_is_cash THEN
        v_total_cash_paid := v_total_cash_paid + v_payment_total + COALESCE(p_tip_amount, 0);
    ELSE
        v_total_card_paid := v_total_card_paid + v_payment_total + COALESCE(p_tip_amount, 0);
    END IF;

    v_new_amount_paid := v_total_cash_paid + v_total_card_paid;

    -- ============================================
    -- 10. Calculate NEW Unpaid Totals from Items
    --     NOTE: Accounts for refunded_quantity
    --     effective_unpaid = quantity - paid_quantity + refunded_quantity
    -- ============================================
    SELECT
        COUNT(*),
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price)
            - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)
            + ROUND((((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price) - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)) * COALESCE(oi.tax_rate, 0) / 100, 2)
        ), 0),
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price)
            - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)
            + ROUND((((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price) - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)) * COALESCE(oi.tax_rate, 0) / 100, 2)
        ), 0)
    INTO v_unpaid_items_count, v_unpaid_card_total, v_unpaid_cash_total
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id
      AND oi.is_voided = false
      AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0;

    -- Re-apply custom refund balance for post-payment state
    -- Use original_amount (card-equivalent) to avoid phantom balance from cash payments
    SELECT COALESCE(SUM(
        COALESCE(original_amount, amount)
        - COALESCE(refunded_amount, 0) * COALESCE(original_amount, amount) / NULLIF(amount, 0)
    ), 0)
    INTO v_effective_paid
    FROM public.order_payments
    WHERE order_id = p_order_id
      AND status IN ('captured', 'partially_refunded', 'refunded')
      AND is_voided = false;

    v_payment_based_due := GREATEST(v_order.card_total - v_effective_paid, 0);
    v_custom_refund_balance := GREATEST(v_payment_based_due - v_unpaid_card_total, 0);
    v_unpaid_card_total := v_unpaid_card_total + v_custom_refund_balance;
    v_unpaid_cash_total := v_unpaid_cash_total + v_custom_refund_balance;

    -- Fix: Same clamping for post-payment unpaid totals.
    -- After a partial payment, items are still "unpaid" but payment_based_due reflects actual remaining.
    IF v_payment_based_due < v_unpaid_card_total THEN
        IF v_unpaid_card_total > 0 THEN
            v_unpaid_cash_total := ROUND(
                v_unpaid_cash_total * v_payment_based_due / v_unpaid_card_total, 2
            );
        END IF;
        v_unpaid_card_total := v_payment_based_due;
    END IF;
    -- March 13th


    -- ============================================
    -- 11. Determine if Order is Fully Paid
    -- ============================================
    IF v_is_item_payment THEN
        v_order_fully_paid := (v_unpaid_items_count = 0);

    ELSIF v_is_split_payment THEN
        SELECT COUNT(*) INTO v_portions_paid
        FROM public.order_payments
        WHERE order_id = p_order_id
          AND split_portion_index IS NOT NULL
          AND split_count = p_split_count
          AND status = 'captured';

        v_portions_remaining := p_split_count - v_portions_paid;
        v_order_fully_paid := (v_portions_remaining = 0);

    ELSE
        v_order_fully_paid := (
            (v_total_cash_paid >= v_order.cash_total AND v_total_card_paid = 0) OR
            (v_total_card_paid >= v_order.card_total AND v_total_cash_paid = 0) OR
            (v_unpaid_card_total <= 0.01 AND v_unpaid_cash_total <= 0.01) OR
            (v_new_amount_paid >= v_order.card_total)
        );
    END IF;

    -- ============================================
    -- 12. Handle Split Complete
    --     NOTE: Accounts for refunded_quantity when marking items as paid
    -- ============================================
    IF v_is_split_payment THEN
        SELECT COUNT(*) INTO v_portions_paid
        FROM public.order_payments
        WHERE order_id = p_order_id
          AND split_portion_index IS NOT NULL
          AND split_count = p_split_count
          AND status = 'captured';

        v_portions_remaining := p_split_count - v_portions_paid;
        v_order_fully_paid := (v_portions_remaining = 0);

        IF v_order_fully_paid AND v_unpaid_items_count > 0 THEN
            -- Set paid_quantity = quantity + refunded_quantity so effective_unpaid becomes 0
            UPDATE public.order_items
            SET
                paid_quantity = quantity + COALESCE(refunded_quantity, 0),
                price_paid = COALESCE(price_paid, unit_price),
                updated_at = now()
            WHERE order_id = p_order_id
              AND is_voided = false
              AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

            v_unpaid_items_count := 0;
            v_unpaid_card_total := 0;
            v_unpaid_cash_total := 0;
        END IF;
    ELSE
        v_order_fully_paid := (v_unpaid_items_count = 0);
    END IF;

    -- ============================================
    -- 13. Set Final amount_due
    --     FIX: When order is fully paid, force amount_due to 0.
    --     This prevents the custom_refund_balance logic from inflating
    --     amount_due when a cash payment (at cash price) is compared
    --     against card_total, producing a false residual.
    -- ============================================
    IF v_order_fully_paid THEN
        v_new_amount_due := 0;
        v_new_cash_amount_due := 0;
        v_unpaid_card_total := 0;
        v_unpaid_cash_total := 0;
    ELSE
        v_new_amount_due := v_unpaid_card_total;
        v_new_cash_amount_due := v_unpaid_cash_total;
    END IF;

    -- ============================================
    -- 14. Update Order
    -- ============================================
    UPDATE public.orders SET
        amount_paid = v_new_amount_paid,
        amount_due = v_new_amount_due,
        cash_amount_due = v_new_cash_amount_due,
        tip_amount = COALESCE(tip_amount, 0) + COALESCE(p_tip_amount, 0),
        payment_pricing_mode = v_new_pricing_mode::pricing_mode,
        cash_discount_applied = COALESCE(cash_discount_applied, false) OR v_is_cash,
        payment_status = CASE
            WHEN v_order_fully_paid THEN 'paid'::payment_status
            WHEN v_new_amount_paid > 0 THEN 'partial'::payment_status
            ELSE 'pending'::payment_status
        END,
        updated_at = now()
    WHERE id = p_order_id;

    v_new_sync_version := increment_order_sync_version(p_order_id);

    -- ============================================
    -- 15. Return Result
    -- ============================================
    RETURN jsonb_build_object(
        'success', true,
        'payment_id', v_payment_id,
        'payment_method', p_payment_method,
        'amount_charged', v_payment_total,
        'tip_amount', COALESCE(p_tip_amount, 0),
        'total_collected', v_payment_total + COALESCE(p_tip_amount, 0),
        'change_given', v_change_given,
        'is_cash_priced', v_is_cash,
        'pricing_mode', v_new_pricing_mode,

        'is_item_payment', v_is_item_payment,
        'is_split_payment', v_is_split_payment,
        'is_full_remaining', v_is_full_remaining,

        'split_count', p_split_count,
        'split_portion_index', p_split_portion_index,
        'portions_paid', v_portions_paid,
        'portions_remaining', v_portions_remaining,
        'split_card_portion', v_split_card_portion,
        'split_cash_portion', v_split_cash_portion,

        'items_paid', v_covered_items_json,
        'items_covered', v_covered_items,

        'total_cash_paid', v_total_cash_paid,
        'total_card_paid', v_total_card_paid,

        'order_amount_paid', v_new_amount_paid,
        'order_amount_due', v_new_amount_due,
        'order_cash_amount_due', v_new_cash_amount_due,
        'order_fully_paid', v_order_fully_paid,

        'unpaid_items_count', v_unpaid_items_count,
        'unpaid_card_total', v_unpaid_card_total,
        'unpaid_cash_total', v_unpaid_cash_total,

        'sync_version', v_new_sync_version
    );
END;$_$;


ALTER FUNCTION "public"."process_payment_v6"("p_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric, "p_amount_tendered" numeric, "p_tip_amount" numeric, "p_item_allocations" "jsonb", "p_split_count" integer, "p_split_portion_index" integer, "p_staff_id" "uuid", "p_terminal_response" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_payment_v7"("p_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric DEFAULT NULL::numeric, "p_tip_amount" numeric DEFAULT 0, "p_amount_tendered" numeric DEFAULT NULL::numeric, "p_item_allocations" "jsonb" DEFAULT NULL::"jsonb", "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_terminal_response" "jsonb" DEFAULT NULL::"jsonb", "p_split_count" integer DEFAULT NULL::integer, "p_split_portion_index" integer DEFAULT NULL::integer, "p_force_card_pricing" boolean DEFAULT false, "p_terminal_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE 
    v_order record;
    v_payment_id uuid;
    v_is_cash boolean;
    v_is_item_payment boolean;
    v_is_split_payment boolean;
    v_payment_total numeric;
    v_new_sync_version integer;
    v_subtotal_portion numeric := 0;
    v_tax_portion numeric := 0;
    v_change_given numeric := 0;
    v_new_amount_paid numeric;
    v_new_amount_due numeric;         -- ALWAYS card price
    v_new_cash_amount_due numeric;    -- For reference
    v_current_pricing_mode text;
    v_new_pricing_mode text;
    v_items_subtotal numeric := 0;
    v_items_tax numeric := 0;
    v_covered_items uuid[] := '{}';
    v_covered_items_json jsonb := '[]'::jsonb;

    -- Unpaid tracking (ALWAYS both prices)
    v_unpaid_items_count integer := 0;
    v_unpaid_card_total numeric := 0;
    v_unpaid_cash_total numeric := 0;

    -- Pre-payment unpaid totals (for full remaining detection)
    v_pre_unpaid_card_total numeric := 0;
    v_pre_unpaid_cash_total numeric := 0;

    -- Refund balance tracking (for custom refunds not tied to items)
    v_effective_paid numeric := 0;
    v_payment_based_due numeric := 0;
    v_custom_refund_balance numeric := 0;

    -- Payment totals by type
    v_total_cash_paid numeric := 0;
    v_total_card_paid numeric := 0;

    -- Fully paid detection
    v_order_fully_paid boolean := false;

    -- Split evenly tracking
    v_split_card_portion numeric;
    v_split_cash_portion numeric;
    v_portions_paid integer := 0;
    v_portions_remaining integer := 0;
    v_paid_portion_indexes integer[];
    v_is_last_portion boolean := false;

    -- Full remaining payment detection
    v_is_full_remaining boolean := false;
    v_target_unpaid numeric := 0;

    -- Dejavoo Transaction Tracking
    v_dejavoo_reference_id text;
    v_dejavoo_transaction_number text;
    v_dejavoo_auth_code text;
    v_dejavoo_batch_number text;
    v_dejavoo_invoice_number text;
    v_dejavoo_rrn text;
    v_dejavoo_entry_mode text;
    v_dejavoo_result_code text;
    v_dejavoo_status_code text;
    v_has_dejavoo_transaction boolean := false;
    v_dejavoo_last_four text;
    v_use_cash_pricing boolean;

    v_terminal_id uuid;
BEGIN
    v_is_cash := p_payment_method = 'cash';
    v_use_cash_pricing := v_is_cash AND NOT COALESCE(p_force_card_pricing, false);
    v_is_item_payment := p_item_allocations IS NOT NULL AND jsonb_array_length(p_item_allocations) > 0;
    v_is_split_payment := p_split_count IS NOT NULL AND p_split_count > 1;

    -- ============================================
    -- 1. Get Order with Validation
    -- ============================================
    SELECT * INTO v_order
    FROM public.orders
    WHERE id = p_order_id
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids());

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found or access denied';
    END IF;

    -- Allow payment if order has been refunded (amount_due > 0) even if payment_status is 'paid'
    IF v_order.payment_status = 'paid' AND COALESCE(v_order.amount_due, 0) <= 0 THEN
        RAISE EXCEPTION 'Order is already fully paid';
    END IF;

    v_current_pricing_mode := v_order.payment_pricing_mode::text;

     -- ============================================
    -- 2. Calculate CURRENT Unpaid Totals from Items
    --    (BEFORE this payment - source of truth)
    --    Includes prorated discounts for remaining quantities
    --    NOTE: Accounts for refunded_quantity - refunded items need to be paid again
    -- ============================================
    SELECT
        COUNT(*),
        -- Card total: (remaining_qty * unit_price) - prorated_discount + tax_on_discounted
        -- remaining_qty = quantity - paid_quantity + refunded_quantity
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price)
            - ROUND(
                COALESCE(oi.discount_amount, 0) *
                (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
            , 2)
            + ROUND(
                (
                    ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price)
                    - ROUND(
                        COALESCE(oi.discount_amount, 0) *
                        (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
                    , 2)
                ) * COALESCE(oi.tax_rate, 0) / 100
            , 2)
        ), 0),
        -- Cash total: same formula with cash_price
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price)
            - ROUND(
                COALESCE(oi.discount_amount, 0) *
                (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
            , 2)
            + ROUND(
                (
                    ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price)
                    - ROUND(
                        COALESCE(oi.discount_amount, 0) *
                        (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
                    , 2)
                ) * COALESCE(oi.tax_rate, 0) / 100
            , 2)
        ), 0)
    INTO v_unpaid_items_count, v_pre_unpaid_card_total, v_pre_unpaid_cash_total
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id
      AND oi.is_voided = false
      AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0;

    -- Account for custom refund balance (refunds not tied to specific items)
    -- Same logic as calculate_order_totals_fast
    -- Use original_amount (card-equivalent) to avoid phantom balance when cash payments
    -- are made at lower prices: original_amount stores the card-equivalent value,
    -- and refunded_amount is scaled proportionally to card-equivalent denomination
    SELECT COALESCE(SUM(
        COALESCE(original_amount, amount)
        - COALESCE(refunded_amount, 0) * COALESCE(original_amount, amount) / NULLIF(amount, 0)
    ), 0)
    INTO v_effective_paid
    FROM public.order_payments
    WHERE order_id = p_order_id
      AND status IN ('captured', 'partially_refunded', 'refunded')
      AND is_voided = false;

    v_payment_based_due := GREATEST(v_order.card_total - v_effective_paid, 0);
    v_custom_refund_balance := GREATEST(v_payment_based_due - v_pre_unpaid_card_total, 0);
    v_pre_unpaid_card_total := v_pre_unpaid_card_total + v_custom_refund_balance;
    v_pre_unpaid_cash_total := v_pre_unpaid_cash_total + v_custom_refund_balance;

    -- Fix: Clamp item-based unpaid totals to payment-based due when partial payments exist.
    -- Partial payments don't mark items as paid, so item-based totals stay at full amount.
    -- payment_based_due tracks actual remaining after prior payments.
    IF v_payment_based_due < v_pre_unpaid_card_total THEN
        IF v_pre_unpaid_card_total > 0 THEN
            v_pre_unpaid_cash_total := ROUND(
                v_pre_unpaid_cash_total * v_payment_based_due / v_pre_unpaid_card_total, 2
            );
        END IF;
        v_pre_unpaid_card_total := v_payment_based_due;
    END IF;

    -- If nothing to pay, return early
    -- Allow payment when custom refund balance exists (payment-level refund debt)
    IF v_unpaid_items_count = 0 AND v_custom_refund_balance <= 0 AND v_payment_based_due <= 0 THEN
        RAISE EXCEPTION 'No unpaid items remaining on this order';
    END IF;

    -- ============================================
    -- 3. Get Existing Payment Totals by Type
    -- ============================================
    SELECT
        COALESCE(SUM(CASE WHEN is_cash_priced THEN total_amount ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN NOT is_cash_priced THEN total_amount ELSE 0 END), 0)
    INTO v_total_cash_paid, v_total_card_paid
    FROM public.order_payments
    WHERE order_id = p_order_id
      AND status = 'captured';


    -- ============================================
    -- 4. Split Payment Validation
    -- ============================================
    IF v_is_split_payment THEN
        IF p_split_portion_index IS NULL THEN
            RAISE EXCEPTION 'Split portion index is required for split payments';
        END IF;

        IF p_split_portion_index < 1 OR p_split_portion_index > p_split_count THEN
            RAISE EXCEPTION 'Invalid split portion index: % (must be 1-%)', p_split_portion_index, p_split_count;
        END IF;

        IF EXISTS (
            SELECT 1 FROM public.order_payments
            WHERE order_id = p_order_id
              AND split_portion_index = p_split_portion_index
              AND status = 'captured'
        ) THEN
            RAISE EXCEPTION 'Split portion % has already been paid', p_split_portion_index;
        END IF;

        SELECT
            COUNT(*),
            COALESCE(array_agg(split_portion_index ORDER BY split_portion_index), ARRAY[]::integer[])
        INTO v_portions_paid, v_paid_portion_indexes
        FROM public.order_payments
        WHERE order_id = p_order_id
          AND split_portion_index IS NOT NULL
          AND status = 'captured';

        v_portions_remaining := p_split_count - v_portions_paid - 1;
        v_is_last_portion := (v_portions_remaining = 0);
    END IF;

    -- ============================================
    -- 5. Determine Pricing Mode (for tracking only)
    -- ============================================
    IF v_current_pricing_mode IS NULL THEN
        v_new_pricing_mode := CASE WHEN v_use_cash_pricing THEN 'cash' ELSE 'card' END;
    ELSIF v_current_pricing_mode = 'card' AND v_use_cash_pricing THEN
        v_new_pricing_mode := 'mixed';
    ELSIF v_current_pricing_mode = 'cash' AND NOT v_use_cash_pricing THEN
        v_new_pricing_mode := 'mixed';
    ELSE
        v_new_pricing_mode := v_current_pricing_mode;
    END IF;

    -- ============================================
    -- 6. Calculate Payment Amount Based on Scenario
    -- ============================================
    IF v_is_item_payment THEN
        -- ========================================
        -- PER-ITEM PAYMENT (with per-item quantities)
        -- NOTE: Accounts for refunded_quantity - refunded items can be paid again
        -- effective_unpaid = quantity - paid_quantity + refunded_quantity
        -- ========================================
        WITH payment_calc AS (
            SELECT
                oi.id,
                oi.item_name,
                oi.quantity AS original_qty,
                oi.unit_price,
                oi.cash_price,
                oi.tax_rate,
                oi.discount_amount,
                COALESCE(oi.paid_quantity, 0) AS already_paid_qty,
                COALESCE(oi.refunded_quantity, 0) AS refunded_qty,
                -- Effective unpaid = quantity - paid + refunded
                (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) AS effective_unpaid,

                -- Quantity being paid (capped at effective unpaid)
                LEAST(
                    COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                    oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                ) AS qty_paying,

                -- Prorated discount: total_discount * (qty_paying / original_qty)
                ROUND(
                    COALESCE(oi.discount_amount, 0) *
                    LEAST(
                        COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                        oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                    )::numeric / NULLIF(oi.quantity, 0)
                , 2) AS prorated_discount

            FROM jsonb_array_elements(p_item_allocations) AS alloc
            JOIN public.order_items oi ON oi.id = (alloc.value->>'order_item_id')::uuid
            WHERE oi.order_id = p_order_id
              AND oi.is_voided = false
              AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0
        )
        SELECT
            -- Subtotal: (qty * price) - prorated_discount
            COALESCE(SUM(
                CASE WHEN v_is_cash
                    THEN (pc.qty_paying * pc.cash_price) - pc.prorated_discount
                    ELSE (pc.qty_paying * pc.unit_price) - pc.prorated_discount
                END
            ), 0),

            -- Tax: on discounted amount
            COALESCE(SUM(
                ROUND(
                    (
                        CASE WHEN v_is_cash
                            THEN (pc.qty_paying * pc.cash_price) - pc.prorated_discount
                            ELSE (pc.qty_paying * pc.unit_price) - pc.prorated_discount
                        END
                    ) * COALESCE(pc.tax_rate, 0) / 100
                , 2)
            ), 0),

            array_agg(pc.id)
        INTO v_items_subtotal, v_items_tax, v_covered_items
        FROM payment_calc pc;

        v_payment_total := v_items_subtotal + v_items_tax;
        v_subtotal_portion := v_items_subtotal;
        v_tax_portion := v_items_tax;

        -- Build detailed items JSON with allocated quantities
        WITH payment_calc AS (
            SELECT
                oi.id,
                oi.item_name,
                oi.quantity AS original_qty,
                oi.unit_price,
                oi.cash_price,
                LEAST(
                    COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                    oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                ) AS qty_paying,
                ROUND(
                    COALESCE(oi.discount_amount, 0) *
                    LEAST(
                        COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                        oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                    )::numeric / NULLIF(oi.quantity, 0)
                , 2) AS prorated_discount
            FROM jsonb_array_elements(p_item_allocations) AS alloc
            JOIN public.order_items oi ON oi.id = (alloc.value->>'order_item_id')::uuid
            WHERE oi.order_id = p_order_id
              AND oi.is_voided = false
              AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0
        )
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'order_item_id', pc.id,
            'item_name', pc.item_name,
            'quantity_paid', pc.qty_paying,
            'unit_price', CASE WHEN v_is_cash THEN pc.cash_price ELSE pc.unit_price END,
            'prorated_discount', pc.prorated_discount,
            'subtotal', CASE WHEN v_is_cash
                THEN (pc.qty_paying * pc.cash_price) - pc.prorated_discount
                ELSE (pc.qty_paying * pc.unit_price) - pc.prorated_discount
            END
        )), '[]'::jsonb)
        INTO v_covered_items_json
        FROM payment_calc pc;

        -- Update items with allocated quantities (INCREMENT paid_quantity)
        -- Cap at effective unpaid (quantity - paid + refunded)
        UPDATE public.order_items oi
        SET
            paid_quantity = COALESCE(oi.paid_quantity, 0) + LEAST(
                COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
            ),
            price_paid = CASE WHEN v_is_cash THEN oi.cash_price ELSE oi.unit_price END,
            updated_at = now()
        FROM jsonb_array_elements(p_item_allocations) AS alloc
        WHERE oi.id = (alloc.value->>'order_item_id')::uuid
          AND oi.order_id = p_order_id
          AND oi.is_voided = false;

    ELSIF v_is_split_payment THEN
        -- ========================================
        -- SPLIT EVENLY PAYMENT
        -- ========================================
        v_split_card_portion := ROUND(v_order.card_total / p_split_count, 2);
        v_split_cash_portion := ROUND(v_order.cash_total / p_split_count, 2);

        IF v_is_last_portion THEN
            -- Last portion: pay remainder to handle rounding
            -- Use portion-based calculation instead of tracking paid amounts,
            -- because v_total_cash/card_paid only counts payments of that type,
            -- which breaks when splits use mixed payment methods (e.g. Cash + Card).
            IF v_is_cash THEN
                v_payment_total := v_order.cash_total - (v_split_cash_portion * (p_split_count - 1));
            ELSE
                v_payment_total := v_order.card_total - (v_split_card_portion * (p_split_count - 1));
            END IF;
            -- Ensure non-negative
            v_payment_total := GREATEST(v_payment_total, 0);
        ELSE
            IF v_is_cash THEN
                v_payment_total := v_split_cash_portion;
            ELSE
                v_payment_total := v_split_card_portion;
            END IF;
        END IF;

        -- Pro-rate subtotal/tax
        IF v_is_cash AND v_order.cash_total > 0 THEN
            v_subtotal_portion := ROUND(v_payment_total * (v_order.cash_subtotal / v_order.cash_total), 2);
        ELSIF v_order.card_total > 0 THEN
            v_subtotal_portion := ROUND(v_payment_total * (v_order.card_subtotal / v_order.card_total), 2);
        END IF;
        v_tax_portion := v_payment_total - v_subtotal_portion;

    ELSE
        -- ========================================
        -- FULL/REMAINING or PARTIAL PAYMENT
        -- Supports hybrid: pay items first, then pay remaining
        -- ========================================

        -- Determine target unpaid amount (from items, source of truth)
        v_target_unpaid := CASE WHEN v_use_cash_pricing
            THEN v_pre_unpaid_cash_total
            ELSE v_pre_unpaid_card_total
        END;

        -- ============================================
        -- FIX V6: Added 0.05 tolerance for rounding differences
        -- between frontend and backend calculations
        -- ============================================
        v_is_full_remaining := (p_amount IS NULL) OR (p_amount >= (v_target_unpaid - 0.05));

        IF v_is_full_remaining THEN
            -- ========================================
            -- FULL REMAINING: Pay all unpaid items
            -- NOTE: Accounts for refunded_quantity - refunded items need to be paid again
            -- effective_unpaid = quantity - paid_quantity + refunded_quantity
            -- ========================================
            v_payment_total := v_target_unpaid;

            -- Pro-rate subtotal/tax based on order ratios
            IF v_use_cash_pricing AND v_order.cash_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.cash_subtotal / v_order.cash_total), 2);
            ELSIF v_order.card_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.card_subtotal / v_order.card_total), 2);
            END IF;
            v_tax_portion := v_payment_total - v_subtotal_portion;

            -- ============================================
            -- FIX V6: Get items BEFORE update for reliable tracking
            -- Include items with effective unpaid > 0 (accounts for refunds)
            -- ============================================
            SELECT array_agg(id)
            INTO v_covered_items
            FROM public.order_items
            WHERE order_id = p_order_id
              AND is_voided = false
              AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

            -- CRITICAL: Mark ALL remaining items as paid
            -- Set paid_quantity = quantity + refunded_quantity so effective_unpaid becomes 0
            UPDATE public.order_items
            SET
                paid_quantity = quantity + COALESCE(refunded_quantity, 0),
                price_paid = CASE WHEN v_use_cash_pricing THEN cash_price ELSE unit_price END,
                updated_at = now()
            WHERE order_id = p_order_id
              AND is_voided = false
              AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

            -- Build items JSON for response
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'order_item_id', oi.id,
                'item_name', oi.item_name,
                'quantity_paid', oi.quantity,
                'unit_price', oi.price_paid,
                'subtotal', oi.quantity * oi.price_paid
            )), '[]'::jsonb)
            INTO v_covered_items_json
            FROM public.order_items oi
            WHERE oi.id = ANY(v_covered_items);

        ELSE
            -- ========================================
            -- PARTIAL: Pay specific amount (no item marking)
            -- ========================================
            -- This is a partial amount payment - items remain unpaid
            -- Used for scenarios like "I'll pay $50 toward the bill"
            v_payment_total := LEAST(p_amount, v_target_unpaid);
            v_payment_total := GREATEST(v_payment_total, 0);

            -- Pro-rate subtotal/tax
            IF v_use_cash_pricing AND v_order.cash_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.cash_subtotal / v_order.cash_total), 2);
            ELSIF v_order.card_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.card_subtotal / v_order.card_total), 2);
            END IF;
            v_tax_portion := v_payment_total - v_subtotal_portion;

            -- No items marked as paid - this is a partial amount against the order
            -- Items will be marked when a subsequent "pay remaining" call is made
        END IF;
    END IF;

    -- ============================================
    -- 6.5 Calculate Change (Cash Only)
    -- ============================================
    IF v_is_cash THEN
        v_change_given := GREATEST(
            COALESCE(p_amount_tendered, v_payment_total) - (v_payment_total + COALESCE(p_tip_amount, 0)),
            0
        );
    END IF;


    -- ============================================
    -- 6.6 Dejavoo Terminal Response
    -- ============================================
     IF p_terminal_response ? 'dejavoo_transaction' THEN
        v_has_dejavoo_transaction := true;
        v_dejavoo_reference_id := p_terminal_response->'dejavoo_transaction'->>'referenceId';
        v_dejavoo_transaction_number := p_terminal_response ->'dejavoo_transaction'->>'transactionNumber';
        v_dejavoo_auth_code := p_terminal_response->'dejavoo_transaction'->>'authCode';
        v_dejavoo_batch_number := p_terminal_response->'dejavoo_transaction'->>'batchNumber';
        v_dejavoo_invoice_number := p_terminal_response->'dejavoo_transaction'->>'invoiceNumber';
        v_dejavoo_rrn := p_terminal_response->'dejavoo_transaction'->>'rrn';
        v_dejavoo_entry_mode := p_terminal_response->'dejavoo_transaction'->>'entryMode';
        v_dejavoo_result_code := p_terminal_response->'dejavoo_transaction'->>'resultCode';
        v_dejavoo_status_code := p_terminal_response->'dejavoo_transaction'->>'statusCode';
        v_dejavoo_last_four := p_terminal_response->'dejavoo_transaction'->>'cardLast4';
    END IF;

    -- ============================================
    -- 6.7 Castles Terminal Response
    -- Reuses v_dejavoo_* variables so the INSERT path below works unchanged.
    -- ============================================
    IF p_terminal_response ? 'castles_transaction' THEN
        v_has_dejavoo_transaction := true;
        v_dejavoo_reference_id := p_terminal_response->'castles_transaction'->>'referenceId';
        v_dejavoo_transaction_number := p_terminal_response->'castles_transaction'->>'referenceId';
        v_dejavoo_auth_code := p_terminal_response->'castles_transaction'->>'approvalCode';
        v_dejavoo_batch_number := p_terminal_response->'castles_transaction'->>'batchNumber';
        v_dejavoo_rrn := p_terminal_response->'castles_transaction'->>'rrn';
        v_dejavoo_entry_mode := p_terminal_response->'castles_transaction'->>'entryMode';
        v_dejavoo_result_code := p_terminal_response->'castles_transaction'->>'resultCode';
        v_dejavoo_status_code := p_terminal_response->'castles_transaction'->>'resultCode';
        v_dejavoo_last_four := p_terminal_response->'castles_transaction'->>'cardLast4';
    END IF;

    -- ============================================
    -- 6.8 Resolve Terminal ID
    -- ============================================
    v_terminal_id := COALESCE(
        p_terminal_id,
        (p_terminal_response->'castles_transaction'->>'terminalId')::uuid,
        (p_terminal_response->'dejavoo_transaction'->>'terminalId')::uuid,
        (p_terminal_response->>'terminal_id')::uuid
    );

    -- ============================================
    -- 7. Create Payment Record
    -- ============================================
    INSERT INTO public.order_payments (
        order_id,
        payment_method,
        amount,
        tip_amount,
        total_amount,
        subtotal_portion,
        tax_portion,
        amount_tendered,
        change_given,
        is_cash_priced,
        cash_discount_applied,
        original_amount,
        covers_items,
        split_portion_index,
        split_count,
        status,
        terminal_type,
        processed_by_staff_id,
        processor_response,
        reference_number,
        transaction_id,
        authorization_code,
        dejavoo_response_code,
        dejavoo_batch_number,
        dejavoo_invoice_number,
        card_type,
        card_last_four,
        captured_at,
        initiated_at,
        merchant_id,
        location_id,
        rrn,
        result_code,
        result_message,
        terminal_id
    ) VALUES (
        p_order_id,
        p_payment_method::payment_method,
        v_payment_total,
        COALESCE(p_tip_amount, 0),
        v_payment_total + COALESCE(p_tip_amount, 0),
        v_subtotal_portion,
        v_tax_portion,
        CASE WHEN v_is_cash THEN COALESCE(p_amount_tendered, v_payment_total) END,
        v_change_given,
        v_use_cash_pricing,
        v_use_cash_pricing,
        CASE WHEN v_use_cash_pricing
            THEN ROUND(v_payment_total * v_order.card_total / NULLIF(v_order.cash_total, 0), 2)
            ELSE v_payment_total
        END,
        CASE WHEN array_length(v_covered_items, 1) > 0 THEN v_covered_items ELSE NULL END,
        p_split_portion_index,
        p_split_count,
        'captured',
        CASE
            WHEN v_is_cash THEN 'cash_drawer'
            WHEN p_terminal_response ? 'castles_transaction' THEN 'castles'
            ELSE 'dejavoo'
        END::terminal_type,
        p_staff_id,
        p_terminal_response,
        COALESCE(v_dejavoo_reference_id, p_terminal_response->>'transaction_id'),
        COALESCE(v_dejavoo_transaction_number, p_terminal_response->>'transaction_id'),
        COALESCE(v_dejavoo_auth_code, p_terminal_response->>'authorization_code'),
        v_dejavoo_status_code,
        v_dejavoo_batch_number,
        v_dejavoo_invoice_number,
        COALESCE(
            p_terminal_response->'dejavoo_transaction'->>'cardType',
            p_terminal_response->'castles_transaction'->>'cardType',
            p_terminal_response->>'card_type'
        ),
        v_dejavoo_last_four,
        now(),
        now(),
        v_order.merchant_id,
        v_order.location_id,
        v_dejavoo_rrn,
        v_dejavoo_result_code,
        COALESCE(
            p_terminal_response->'dejavoo_transaction'->>'resultMessage',
            p_terminal_response->'castles_transaction'->>'statusMessage'
        ),
        v_terminal_id
    )
    RETURNING id INTO v_payment_id;

 PERFORM log_payment_event(
        p_payment_id := v_payment_id,
        p_order_id := p_order_id,
        p_location_id := v_order.location_id,
        p_event_type := 'captured',
        p_amount := v_payment_total,
        p_tip_amount := COALESCE(p_tip_amount, 0),
        p_previous_status := NULL,
        p_new_status := 'captured',
        p_psp_reference := COALESCE(
            v_dejavoo_reference_id,
            v_dejavoo_transaction_number,
            p_terminal_response->>'transaction_id'
        ),
        p_auth_code := v_dejavoo_auth_code,
        p_staff_id := p_staff_id,
        p_terminal_id := COALESCE(
            p_terminal_response->'castles_transaction'->>'terminalId',
            p_terminal_response->'dejavoo_transaction'->>'terminalId',
            p_terminal_response->>'terminal_id'
        ),
        p_result_code := COALESCE(v_dejavoo_result_code, '00'),
        p_response_message := CASE
            WHEN v_is_cash THEN 'Cash payment captured'
            ELSE COALESCE(
                p_terminal_response->'dejavoo_transaction'->>'resultMessage',
                p_terminal_response->'castles_transaction'->>'statusMessage',
                'Card payment captured successfully'
            )
        END,
        p_raw_response := p_terminal_response,
        p_reason := NULL
    );

    -- ============================================
    -- 8. Per-Item: Create order_payment_items
    --    NOTE: Accounts for refunded_quantity in effective unpaid calculation
    -- ============================================
    IF v_is_item_payment AND array_length(v_covered_items, 1) > 0 THEN
        WITH payment_calc AS (
            SELECT
                oi.id,
                oi.price_paid,
                oi.tax_rate,
                -- effective_unpaid = quantity - paid_quantity + refunded_quantity
                LEAST(
                    COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                    oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                ) AS qty_paid,
                ROUND(
                    COALESCE(oi.discount_amount, 0) *
                    LEAST(
                        COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                        oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                    )::numeric / NULLIF(oi.quantity, 0)
                , 2) AS prorated_discount
            FROM jsonb_array_elements(p_item_allocations) AS alloc
            JOIN public.order_items oi ON oi.id = (alloc.value->>'order_item_id')::uuid
            WHERE oi.order_id = p_order_id
              AND oi.is_voided = false
        )
        INSERT INTO public.order_payment_items (
            order_payment_id,
            order_item_id,
            quantity_paid,
            unit_price_paid,
            subtotal_paid,
            tax_paid
        )
        SELECT
            v_payment_id,
            pc.id,
            pc.qty_paid,
            pc.price_paid,
            (pc.qty_paid * pc.price_paid) - pc.prorated_discount,
            ROUND(((pc.qty_paid * pc.price_paid) - pc.prorated_discount) * COALESCE(pc.tax_rate, 0) / 100, 2)
        FROM payment_calc pc;

    ELSIF v_is_full_remaining AND array_length(v_covered_items, 1) > 0 THEN
        INSERT INTO public.order_payment_items (
            order_payment_id,
            order_item_id,
            quantity_paid,
            unit_price_paid,
            subtotal_paid,
            tax_paid
        )
        SELECT
            v_payment_id,
            oi.id,
            oi.quantity,
            oi.price_paid,
            oi.quantity * oi.price_paid - ROUND(COALESCE(oi.discount_amount, 0), 2),
            ROUND((oi.quantity * oi.price_paid - ROUND(COALESCE(oi.discount_amount, 0), 2)) * COALESCE(oi.tax_rate, 0) / 100, 2)
        FROM public.order_items oi
        WHERE oi.id = ANY(v_covered_items)
          AND oi.order_id = p_order_id
          AND oi.is_voided = false;
    END IF;

    -- ============================================
    -- 9. Update Payment Totals (include this payment)
    -- ============================================
    IF v_use_cash_pricing THEN
        v_total_cash_paid := v_total_cash_paid + v_payment_total + COALESCE(p_tip_amount, 0);
    ELSE
        v_total_card_paid := v_total_card_paid + v_payment_total + COALESCE(p_tip_amount, 0);
    END IF;

    v_new_amount_paid := v_total_cash_paid + v_total_card_paid;

    -- ============================================
    -- 10. Calculate NEW Unpaid Totals from Items
    --     NOTE: Accounts for refunded_quantity
    --     effective_unpaid = quantity - paid_quantity + refunded_quantity
    -- ============================================
    SELECT
        COUNT(*),
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price)
            - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)
            + ROUND((((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price) - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)) * COALESCE(oi.tax_rate, 0) / 100, 2)
        ), 0),
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price)
            - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)
            + ROUND((((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price) - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)) * COALESCE(oi.tax_rate, 0) / 100, 2)
        ), 0)
    INTO v_unpaid_items_count, v_unpaid_card_total, v_unpaid_cash_total
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id
      AND oi.is_voided = false
      AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0;

    -- Re-apply custom refund balance for post-payment state
    -- Use original_amount (card-equivalent) to avoid phantom balance from cash payments
    SELECT COALESCE(SUM(
        COALESCE(original_amount, amount)
        - COALESCE(refunded_amount, 0) * COALESCE(original_amount, amount) / NULLIF(amount, 0)
    ), 0)
    INTO v_effective_paid
    FROM public.order_payments
    WHERE order_id = p_order_id
      AND status IN ('captured', 'partially_refunded', 'refunded')
      AND is_voided = false;

    v_payment_based_due := GREATEST(v_order.card_total - v_effective_paid, 0);
    v_custom_refund_balance := GREATEST(v_payment_based_due - v_unpaid_card_total, 0);
    v_unpaid_card_total := v_unpaid_card_total + v_custom_refund_balance;
    v_unpaid_cash_total := v_unpaid_cash_total + v_custom_refund_balance;

    -- Fix: Same clamping for post-payment unpaid totals.
    -- After a partial payment, items are still "unpaid" but payment_based_due reflects actual remaining.
    IF v_payment_based_due < v_unpaid_card_total THEN
        IF v_unpaid_card_total > 0 THEN
            v_unpaid_cash_total := ROUND(
                v_unpaid_cash_total * v_payment_based_due / v_unpaid_card_total, 2
            );
        END IF;
        v_unpaid_card_total := v_payment_based_due;
    END IF;

    -- ============================================
    -- 11. Determine if Order is Fully Paid
    -- ============================================
    IF v_is_item_payment THEN
        v_order_fully_paid := (v_unpaid_items_count = 0);

    ELSIF v_is_split_payment THEN
        SELECT COUNT(*) INTO v_portions_paid
        FROM public.order_payments
        WHERE order_id = p_order_id
          AND split_portion_index IS NOT NULL
          AND split_count = p_split_count
          AND status = 'captured';

        v_portions_remaining := p_split_count - v_portions_paid;
        v_order_fully_paid := (v_portions_remaining = 0);

    ELSE
        v_order_fully_paid := (
            (v_total_cash_paid >= v_order.cash_total AND v_total_card_paid = 0) OR
            (v_total_card_paid >= v_order.card_total AND v_total_cash_paid = 0) OR
            (v_unpaid_card_total <= 0.01 AND v_unpaid_cash_total <= 0.01) OR
            (v_new_amount_paid >= v_order.card_total)
        );
    END IF;

    -- ============================================
    -- 12. Handle Split Complete
    --     NOTE: Accounts for refunded_quantity when marking items as paid
    -- ============================================
        -- ============================================
    -- 12. Handle Split Complete
    --     NOTE: Accounts for refunded_quantity when marking items as paid
    -- ============================================
    IF v_is_split_payment THEN
        SELECT COUNT(*) INTO v_portions_paid
        FROM public.order_payments
        WHERE order_id = p_order_id
          AND split_portion_index IS NOT NULL
          AND split_count = p_split_count
          AND status = 'captured';

        v_portions_remaining := p_split_count - v_portions_paid;
        v_order_fully_paid := (v_portions_remaining = 0);

        IF v_order_fully_paid AND v_unpaid_items_count > 0 THEN
            -- Set paid_quantity = quantity + refunded_quantity so effective_unpaid becomes 0
            UPDATE public.order_items
            SET
                paid_quantity = quantity + COALESCE(refunded_quantity, 0),
                price_paid = COALESCE(price_paid, unit_price),
                updated_at = now()
            WHERE order_id = p_order_id
              AND is_voided = false
              AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

            v_unpaid_items_count := 0;
            v_unpaid_card_total := 0;
            v_unpaid_cash_total := 0;
        END IF;
    ELSE
        -- Preserve section 11's amount-based result if it already determined fully paid.
        -- Only fall back to item-count check if amounts don't confirm paid.
        IF NOT v_order_fully_paid THEN
            v_order_fully_paid := (v_unpaid_items_count = 0);
        END IF;

        -- If fully paid by amounts but items weren't marked (custom amount that
        -- covered the full order, or rounding caused v_is_full_remaining=false),
        -- mark all remaining items as paid for data consistency.
        -- This mirrors the split-completion pattern at lines 846-859.
        IF v_order_fully_paid AND v_unpaid_items_count > 0 THEN
            UPDATE public.order_items
            SET
                paid_quantity = quantity + COALESCE(refunded_quantity, 0),
                price_paid = COALESCE(price_paid, CASE WHEN v_use_cash_pricing THEN cash_price ELSE unit_price END),
                updated_at = now()
            WHERE order_id = p_order_id
              AND is_voided = false
              AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

            v_unpaid_items_count := 0;
            v_unpaid_card_total := 0;
            v_unpaid_cash_total := 0;
        END IF;
    END IF;

    -- ============================================
    -- 13. Set Final amount_due
    --     FIX: When order is fully paid, force amount_due to 0.
    --     This prevents the custom_refund_balance logic from inflating
    --     amount_due when a cash payment (at cash price) is compared
    --     against card_total, producing a false residual.
    -- ============================================
    IF v_order_fully_paid THEN
        v_new_amount_due := 0;
        v_new_cash_amount_due := 0;
        v_unpaid_card_total := 0;
        v_unpaid_cash_total := 0;
    ELSE
        v_new_amount_due := v_unpaid_card_total;
        v_new_cash_amount_due := v_unpaid_cash_total;
    END IF;

    -- ============================================
    -- 14. Update Order
    -- ============================================
    UPDATE public.orders SET
        amount_paid = v_new_amount_paid,
        amount_due = v_new_amount_due,
        cash_amount_due = v_new_cash_amount_due,
        tip_amount = COALESCE(tip_amount, 0) + COALESCE(p_tip_amount, 0),
        payment_pricing_mode = v_new_pricing_mode::pricing_mode,
        cash_discount_applied = COALESCE(cash_discount_applied, false) OR v_use_cash_pricing,
        payment_status = CASE
            WHEN v_order_fully_paid THEN 'paid'::payment_status
            WHEN v_new_amount_paid > 0 THEN 'partial'::payment_status
            ELSE 'pending'::payment_status
        END,
        updated_at = now()
    WHERE id = p_order_id;

    v_new_sync_version := increment_order_sync_version(p_order_id);

    -- ============================================
    -- 15. Return Result
    -- ============================================
    RETURN jsonb_build_object(
        'success', true,
        'payment_id', v_payment_id,
        'payment_method', p_payment_method,
        'amount_charged', v_payment_total,
        'tip_amount', COALESCE(p_tip_amount, 0),
        'total_collected', v_payment_total + COALESCE(p_tip_amount, 0),
        'change_given', v_change_given,
        'is_cash_priced', v_use_cash_pricing,
        'pricing_mode', v_new_pricing_mode,

        'is_item_payment', v_is_item_payment,
        'is_split_payment', v_is_split_payment,
        'is_full_remaining', v_is_full_remaining,

        'split_count', p_split_count,
        'split_portion_index', p_split_portion_index,
        'portions_paid', v_portions_paid,
        'portions_remaining', v_portions_remaining,
        'split_card_portion', v_split_card_portion,
        'split_cash_portion', v_split_cash_portion,

        'items_paid', v_covered_items_json,
        'items_covered', v_covered_items,

        'total_cash_paid', v_total_cash_paid,
        'total_card_paid', v_total_card_paid,

        'order_amount_paid', v_new_amount_paid,
        'order_amount_due', v_new_amount_due,
        'order_cash_amount_due', v_new_cash_amount_due,
        'order_fully_paid', v_order_fully_paid,

        'unpaid_items_count', v_unpaid_items_count,
        'unpaid_card_total', v_unpaid_card_total,
        'unpaid_cash_total', v_unpaid_cash_total,

        'sync_version', v_new_sync_version
    );
END;
$_$;


ALTER FUNCTION "public"."process_payment_v7"("p_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric, "p_tip_amount" numeric, "p_amount_tendered" numeric, "p_item_allocations" "jsonb", "p_staff_id" "uuid", "p_terminal_response" "jsonb", "p_split_count" integer, "p_split_portion_index" integer, "p_force_card_pricing" boolean, "p_terminal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_payment_v8"("p_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric DEFAULT NULL::numeric, "p_tip_amount" numeric DEFAULT 0, "p_amount_tendered" numeric DEFAULT NULL::numeric, "p_item_allocations" "jsonb" DEFAULT NULL::"jsonb", "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_terminal_response" "jsonb" DEFAULT NULL::"jsonb", "p_split_count" integer DEFAULT NULL::integer, "p_split_portion_index" integer DEFAULT NULL::integer, "p_force_card_pricing" boolean DEFAULT false, "p_terminal_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE 
    v_order record;
    v_payment_id uuid;
    v_is_cash boolean;
    v_is_item_payment boolean;
    v_is_split_payment boolean;
    v_payment_total numeric;
    v_new_sync_version integer;
    v_subtotal_portion numeric := 0;
    v_tax_portion numeric := 0;
    v_change_given numeric := 0;
    v_new_amount_paid numeric;
    v_new_amount_due numeric;         -- ALWAYS card price
    v_new_cash_amount_due numeric;    -- For reference
    v_current_pricing_mode text;
    v_new_pricing_mode text;
    v_items_subtotal numeric := 0;
    v_items_tax numeric := 0;
    v_covered_items uuid[] := '{}';
    v_covered_items_json jsonb := '[]'::jsonb;

    -- Unpaid tracking (ALWAYS both prices)
    v_unpaid_items_count integer := 0;
    v_unpaid_card_total numeric := 0;
    v_unpaid_cash_total numeric := 0;

    -- Pre-payment unpaid totals (for full remaining detection)
    v_pre_unpaid_card_total numeric := 0;
    v_pre_unpaid_cash_total numeric := 0;

    -- Refund balance tracking (for custom refunds not tied to items)
    v_effective_paid numeric := 0;
    v_payment_based_due numeric := 0;
    v_custom_refund_balance numeric := 0;

    -- Payment totals by type
    v_total_cash_paid numeric := 0;
    v_total_card_paid numeric := 0;

    -- Fully paid detection
    v_order_fully_paid boolean := false;

    -- Split evenly tracking
    v_split_card_portion numeric;
    v_split_cash_portion numeric;
    v_portions_paid integer := 0;
    v_portions_remaining integer := 0;
    v_paid_portion_indexes integer[];
    v_is_last_portion boolean := false;

    -- Full remaining payment detection
    v_is_full_remaining boolean := false;
    v_target_unpaid numeric := 0;

    -- Dejavoo Transaction Tracking
    v_dejavoo_reference_id text;
    v_dejavoo_transaction_number text;
    v_dejavoo_auth_code text;
    v_dejavoo_batch_number text;
    v_dejavoo_invoice_number text;
    v_dejavoo_rrn text;
    v_dejavoo_entry_mode text;
    v_dejavoo_result_code text;
    v_dejavoo_status_code text;
    v_has_dejavoo_transaction boolean := false;
    v_dejavoo_last_four text;
    v_use_cash_pricing boolean;

    v_terminal_id uuid;
BEGIN
    v_is_cash := p_payment_method = 'cash';
    v_use_cash_pricing := v_is_cash AND NOT COALESCE(p_force_card_pricing, false);
    v_is_item_payment := p_item_allocations IS NOT NULL AND jsonb_array_length(p_item_allocations) > 0;
    v_is_split_payment := p_split_count IS NOT NULL AND p_split_count > 1;

    -- ============================================
    -- 1. Get Order with Validation
    -- ============================================
    SELECT * INTO v_order
    FROM public.orders
    WHERE id = p_order_id
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids());

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found or access denied';
    END IF;

    -- Allow payment if order has been refunded (amount_due > 0) even if payment_status is 'paid'
    IF v_order.payment_status = 'paid' AND COALESCE(v_order.amount_due, 0) <= 0 THEN
        RAISE EXCEPTION 'Order is already fully paid';
    END IF;

    v_current_pricing_mode := v_order.payment_pricing_mode::text;

     -- ============================================
    -- 2. Calculate CURRENT Unpaid Totals from Items
    --    (BEFORE this payment - source of truth)
    --    Includes prorated discounts for remaining quantities
    --    NOTE: Accounts for refunded_quantity - refunded items need to be paid again
    -- ============================================
    SELECT
        COUNT(*),
        -- Card total: (remaining_qty * unit_price) - prorated_discount + tax_on_discounted
        -- remaining_qty = quantity - paid_quantity + refunded_quantity
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price)
            - ROUND(
                COALESCE(oi.discount_amount, 0) *
                (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
            , 2)
            + ROUND(
                (
                    ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price)
                    - ROUND(
                        COALESCE(oi.discount_amount, 0) *
                        (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
                    , 2)
                ) * COALESCE(oi.tax_rate, 0) / 100
            , 2)
        ), 0),
        -- Cash total: same formula with cash_price
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price)
            - ROUND(
                COALESCE(oi.discount_amount, 0) *
                (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
            , 2)
            + ROUND(
                (
                    ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price)
                    - ROUND(
                        COALESCE(oi.discount_amount, 0) *
                        (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0)
                    , 2)
                ) * COALESCE(oi.tax_rate, 0) / 100
            , 2)
        ), 0)
    INTO v_unpaid_items_count, v_pre_unpaid_card_total, v_pre_unpaid_cash_total
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id
      AND oi.is_voided = false
      AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0;

    -- Account for custom refund balance (refunds not tied to specific items)
    -- Same logic as calculate_order_totals_fast
    -- Use original_amount (card-equivalent) to avoid phantom balance when cash payments
    -- are made at lower prices: original_amount stores the card-equivalent value,
    -- and refunded_amount is scaled proportionally to card-equivalent denomination
    SELECT COALESCE(SUM(
        COALESCE(original_amount, amount)
        - COALESCE(refunded_amount, 0) * COALESCE(original_amount, amount) / NULLIF(amount, 0)
    ), 0)
    INTO v_effective_paid
    FROM public.order_payments
    WHERE order_id = p_order_id
      AND status IN ('captured', 'partially_refunded', 'refunded')
      AND is_voided = false;

    v_payment_based_due := GREATEST(v_order.card_total - v_effective_paid, 0);
    v_custom_refund_balance := GREATEST(v_payment_based_due - v_pre_unpaid_card_total, 0);
    v_pre_unpaid_card_total := v_pre_unpaid_card_total + v_custom_refund_balance;
    v_pre_unpaid_cash_total := v_pre_unpaid_cash_total + v_custom_refund_balance;

    -- Fix: Clamp item-based unpaid totals to payment-based due when partial payments exist.
    -- Partial payments don't mark items as paid, so item-based totals stay at full amount.
    -- payment_based_due tracks actual remaining after prior payments.
    IF v_payment_based_due < v_pre_unpaid_card_total THEN
        IF v_pre_unpaid_card_total > 0 THEN
            v_pre_unpaid_cash_total := ROUND(
                v_pre_unpaid_cash_total * v_payment_based_due / v_pre_unpaid_card_total, 2
            );
        END IF;
        v_pre_unpaid_card_total := v_payment_based_due;
    END IF;

    -- If nothing to pay, return early
    -- Allow payment when custom refund balance exists (payment-level refund debt)
    IF v_unpaid_items_count = 0 AND v_custom_refund_balance <= 0 AND v_payment_based_due <= 0 THEN
        RAISE EXCEPTION 'No unpaid items remaining on this order';
    END IF;

    -- ============================================
    -- 3. Get Existing Payment Totals by Type
    -- ============================================
    SELECT
        COALESCE(SUM(CASE WHEN is_cash_priced THEN total_amount ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN NOT is_cash_priced THEN total_amount ELSE 0 END), 0)
    INTO v_total_cash_paid, v_total_card_paid
    FROM public.order_payments
    WHERE order_id = p_order_id
      AND status = 'captured';


    -- ============================================
    -- 4. Split Payment Validation
    -- ============================================
    IF v_is_split_payment THEN
        IF p_split_portion_index IS NULL THEN
            RAISE EXCEPTION 'Split portion index is required for split payments';
        END IF;

        IF p_split_portion_index < 1 OR p_split_portion_index > p_split_count THEN
            RAISE EXCEPTION 'Invalid split portion index: % (must be 1-%)', p_split_portion_index, p_split_count;
        END IF;

        IF EXISTS (
            SELECT 1 FROM public.order_payments
            WHERE order_id = p_order_id
              AND split_portion_index = p_split_portion_index
              AND status = 'captured'
        ) THEN
            RAISE EXCEPTION 'Split portion % has already been paid', p_split_portion_index;
        END IF;

        SELECT
            COUNT(*),
            COALESCE(array_agg(split_portion_index ORDER BY split_portion_index), ARRAY[]::integer[])
        INTO v_portions_paid, v_paid_portion_indexes
        FROM public.order_payments
        WHERE order_id = p_order_id
          AND split_portion_index IS NOT NULL
          AND status = 'captured';

        v_portions_remaining := p_split_count - v_portions_paid - 1;
        v_is_last_portion := (v_portions_remaining = 0);
    END IF;

    -- ============================================
    -- 5. Determine Pricing Mode (for tracking only)
    -- ============================================
    IF v_current_pricing_mode IS NULL THEN
        v_new_pricing_mode := CASE WHEN v_use_cash_pricing THEN 'cash' ELSE 'card' END;
    ELSIF v_current_pricing_mode = 'card' AND v_use_cash_pricing THEN
        v_new_pricing_mode := 'mixed';
    ELSIF v_current_pricing_mode = 'cash' AND NOT v_use_cash_pricing THEN
        v_new_pricing_mode := 'mixed';
    ELSE
        v_new_pricing_mode := v_current_pricing_mode;
    END IF;

    -- ============================================
    -- 6. Calculate Payment Amount Based on Scenario
    -- ============================================
    IF v_is_item_payment THEN
        -- ========================================
        -- PER-ITEM PAYMENT (with per-item quantities)
        -- NOTE: Accounts for refunded_quantity - refunded items can be paid again
        -- effective_unpaid = quantity - paid_quantity + refunded_quantity
        -- ========================================
        WITH payment_calc AS (
            SELECT
                oi.id,
                oi.item_name,
                oi.quantity AS original_qty,
                oi.unit_price,
                oi.cash_price,
                oi.tax_rate,
                oi.discount_amount,
                COALESCE(oi.paid_quantity, 0) AS already_paid_qty,
                COALESCE(oi.refunded_quantity, 0) AS refunded_qty,
                -- Effective unpaid = quantity - paid + refunded
                (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) AS effective_unpaid,

                -- Quantity being paid (capped at effective unpaid)
                LEAST(
                    COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                    oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                ) AS qty_paying,

                -- Prorated discount: total_discount * (qty_paying / original_qty)
                ROUND(
                    COALESCE(oi.discount_amount, 0) *
                    LEAST(
                        COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                        oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                    )::numeric / NULLIF(oi.quantity, 0)
                , 2) AS prorated_discount

            FROM jsonb_array_elements(p_item_allocations) AS alloc
            JOIN public.order_items oi ON oi.id = (alloc.value->>'order_item_id')::uuid
            WHERE oi.order_id = p_order_id
              AND oi.is_voided = false
              AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0
        )
        SELECT
            -- Subtotal: (qty * price) - prorated_discount
            COALESCE(SUM(
                CASE WHEN v_is_cash
                    THEN (pc.qty_paying * pc.cash_price) - pc.prorated_discount
                    ELSE (pc.qty_paying * pc.unit_price) - pc.prorated_discount
                END
            ), 0),

            -- Tax: on discounted amount
            COALESCE(SUM(
                ROUND(
                    (
                        CASE WHEN v_is_cash
                            THEN (pc.qty_paying * pc.cash_price) - pc.prorated_discount
                            ELSE (pc.qty_paying * pc.unit_price) - pc.prorated_discount
                        END
                    ) * COALESCE(pc.tax_rate, 0) / 100
                , 2)
            ), 0),

            array_agg(pc.id)
        INTO v_items_subtotal, v_items_tax, v_covered_items
        FROM payment_calc pc;

        v_payment_total := v_items_subtotal + v_items_tax;
        v_subtotal_portion := v_items_subtotal;
        v_tax_portion := v_items_tax;

        -- Build detailed items JSON with allocated quantities
        -- NOTE: This runs BEFORE the UPDATE below so quantities are pre-update (correct)
        WITH payment_calc AS (
            SELECT
                oi.id,
                oi.item_name,
                oi.quantity AS original_qty,
                oi.unit_price,
                oi.cash_price,
                oi.tax_rate,
                LEAST(
                    COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                    oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                ) AS qty_paying,
                ROUND(
                    COALESCE(oi.discount_amount, 0) *
                    LEAST(
                        COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                        oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
                    )::numeric / NULLIF(oi.quantity, 0)
                , 2) AS prorated_discount
            FROM jsonb_array_elements(p_item_allocations) AS alloc
            JOIN public.order_items oi ON oi.id = (alloc.value->>'order_item_id')::uuid
            WHERE oi.order_id = p_order_id
              AND oi.is_voided = false
              AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0
        )
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'order_item_id', pc.id,
            'item_name', pc.item_name,
            'quantity_paid', pc.qty_paying,
            'original_quantity', pc.original_qty,
            'unit_price', CASE WHEN v_is_cash THEN pc.cash_price ELSE pc.unit_price END,
            'tax_rate', COALESCE(pc.tax_rate, 0),
            'prorated_discount', pc.prorated_discount,
            'subtotal', CASE WHEN v_is_cash
                THEN (pc.qty_paying * pc.cash_price) - pc.prorated_discount
                ELSE (pc.qty_paying * pc.unit_price) - pc.prorated_discount
            END
        )), '[]'::jsonb)
        INTO v_covered_items_json
        FROM payment_calc pc;

        -- Update items with allocated quantities (INCREMENT paid_quantity)
        -- Cap at effective unpaid (quantity - paid + refunded)
        UPDATE public.order_items oi
        SET
            paid_quantity = COALESCE(oi.paid_quantity, 0) + LEAST(
                COALESCE((alloc.value->>'quantity')::integer, oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)
            ),
            price_paid = CASE WHEN v_is_cash THEN oi.cash_price ELSE oi.unit_price END,
            updated_at = now()
        FROM jsonb_array_elements(p_item_allocations) AS alloc
        WHERE oi.id = (alloc.value->>'order_item_id')::uuid
          AND oi.order_id = p_order_id
          AND oi.is_voided = false;

    ELSIF v_is_split_payment THEN
        -- ========================================
        -- SPLIT EVENLY PAYMENT
        -- ========================================
        v_split_card_portion := ROUND(v_order.card_total / p_split_count, 2);
        v_split_cash_portion := ROUND(v_order.cash_total / p_split_count, 2);

        IF v_is_last_portion THEN
            -- Last portion: pay remainder to handle rounding
            -- Use portion-based calculation instead of tracking paid amounts,
            -- because v_total_cash/card_paid only counts payments of that type,
            -- which breaks when splits use mixed payment methods (e.g. Cash + Card).
            IF v_is_cash THEN
                v_payment_total := v_order.cash_total - (v_split_cash_portion * (p_split_count - 1));
            ELSE
                v_payment_total := v_order.card_total - (v_split_card_portion * (p_split_count - 1));
            END IF;
            -- Ensure non-negative
            v_payment_total := GREATEST(v_payment_total, 0);
        ELSE
            IF v_is_cash THEN
                v_payment_total := v_split_cash_portion;
            ELSE
                v_payment_total := v_split_card_portion;
            END IF;
        END IF;

        -- Pro-rate subtotal/tax
        IF v_is_cash AND v_order.cash_total > 0 THEN
            v_subtotal_portion := ROUND(v_payment_total * (v_order.cash_subtotal / v_order.cash_total), 2);
        ELSIF v_order.card_total > 0 THEN
            v_subtotal_portion := ROUND(v_payment_total * (v_order.card_subtotal / v_order.card_total), 2);
        END IF;
        v_tax_portion := v_payment_total - v_subtotal_portion;

    ELSE
        -- ========================================
        -- FULL/REMAINING or PARTIAL PAYMENT
        -- Supports hybrid: pay items first, then pay remaining
        -- ========================================

        -- Determine target unpaid amount (from items, source of truth)
        v_target_unpaid := CASE WHEN v_use_cash_pricing
            THEN v_pre_unpaid_cash_total
            ELSE v_pre_unpaid_card_total
        END;

        -- ============================================
        -- FIX V6: Added 0.05 tolerance for rounding differences
        -- between frontend and backend calculations
        -- ============================================
        v_is_full_remaining := (p_amount IS NULL) OR (p_amount >= (v_target_unpaid - 0.05));

        IF v_is_full_remaining THEN
            -- ========================================
            -- FULL REMAINING: Pay all unpaid items
            -- NOTE: Accounts for refunded_quantity - refunded items need to be paid again
            -- effective_unpaid = quantity - paid_quantity + refunded_quantity
            -- ========================================
            v_payment_total := v_target_unpaid;

            -- Pro-rate subtotal/tax based on order ratios
            IF v_use_cash_pricing AND v_order.cash_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.cash_subtotal / v_order.cash_total), 2);
            ELSIF v_order.card_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.card_subtotal / v_order.card_total), 2);
            END IF;
            v_tax_portion := v_payment_total - v_subtotal_portion;

            -- ============================================
            -- FIX V6: Get items BEFORE update for reliable tracking
            -- Include items with effective unpaid > 0 (accounts for refunds)
            -- ============================================
            SELECT array_agg(id)
            INTO v_covered_items
            FROM public.order_items
            WHERE order_id = p_order_id
              AND is_voided = false
              AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

            -- Build items JSON for response BEFORE the update (captures correct remaining qty)
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'order_item_id', oi.id,
                'item_name', oi.item_name,
                'quantity_paid', (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)),
                'original_quantity', oi.quantity,
                'unit_price', CASE WHEN v_use_cash_pricing THEN oi.cash_price ELSE oi.unit_price END,
                'discount_amount', COALESCE(oi.discount_amount, 0),
                'tax_rate', COALESCE(oi.tax_rate, 0),
                'subtotal', (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))
                            * CASE WHEN v_use_cash_pricing THEN oi.cash_price ELSE oi.unit_price END
            )), '[]'::jsonb)
            INTO v_covered_items_json
            FROM public.order_items oi
            WHERE oi.id = ANY(v_covered_items);

            -- CRITICAL: Mark ALL remaining items as paid
            -- Set paid_quantity = quantity + refunded_quantity so effective_unpaid becomes 0
            UPDATE public.order_items
            SET
                paid_quantity = quantity + COALESCE(refunded_quantity, 0),
                price_paid = CASE WHEN v_use_cash_pricing THEN cash_price ELSE unit_price END,
                updated_at = now()
            WHERE order_id = p_order_id
              AND is_voided = false
              AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

        ELSE
            -- ========================================
            -- PARTIAL: Pay specific amount (no item marking)
            -- ========================================
            -- This is a partial amount payment - items remain unpaid
            -- Used for scenarios like "I'll pay $50 toward the bill"
            v_payment_total := LEAST(p_amount, v_target_unpaid);
            v_payment_total := GREATEST(v_payment_total, 0);

            -- Pro-rate subtotal/tax
            IF v_use_cash_pricing AND v_order.cash_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.cash_subtotal / v_order.cash_total), 2);
            ELSIF v_order.card_total > 0 THEN
                v_subtotal_portion := ROUND(v_payment_total * (v_order.card_subtotal / v_order.card_total), 2);
            END IF;
            v_tax_portion := v_payment_total - v_subtotal_portion;

            -- No items marked as paid - this is a partial amount against the order
            -- Items will be marked when a subsequent "pay remaining" call is made
        END IF;
    END IF;

    -- ============================================
    -- 6.5 Calculate Change (Cash Only)
    -- ============================================
    IF v_is_cash THEN
        v_change_given := GREATEST(
            COALESCE(p_amount_tendered, v_payment_total) - (v_payment_total + COALESCE(p_tip_amount, 0)),
            0
        );
    END IF;


    -- ============================================
    -- 6.6 Dejavoo Terminal Response
    -- ============================================
     IF p_terminal_response ? 'dejavoo_transaction' THEN
        v_has_dejavoo_transaction := true;
        v_dejavoo_reference_id := p_terminal_response->'dejavoo_transaction'->>'referenceId';
        v_dejavoo_transaction_number := p_terminal_response ->'dejavoo_transaction'->>'transactionNumber';
        v_dejavoo_auth_code := p_terminal_response->'dejavoo_transaction'->>'authCode';
        v_dejavoo_batch_number := p_terminal_response->'dejavoo_transaction'->>'batchNumber';
        v_dejavoo_invoice_number := p_terminal_response->'dejavoo_transaction'->>'invoiceNumber';
        v_dejavoo_rrn := p_terminal_response->'dejavoo_transaction'->>'rrn';
        v_dejavoo_entry_mode := p_terminal_response->'dejavoo_transaction'->>'entryMode';
        v_dejavoo_result_code := p_terminal_response->'dejavoo_transaction'->>'resultCode';
        v_dejavoo_status_code := p_terminal_response->'dejavoo_transaction'->>'statusCode';
        v_dejavoo_last_four := p_terminal_response->'dejavoo_transaction'->>'cardLast4';
    END IF;

    -- ============================================
    -- 6.7 Castles Terminal Response
    -- Reuses v_dejavoo_* variables so the INSERT path below works unchanged.
    -- ============================================
    IF p_terminal_response ? 'castles_transaction' THEN
        v_has_dejavoo_transaction := true;
        v_dejavoo_reference_id := p_terminal_response->'castles_transaction'->>'referenceId';
        v_dejavoo_transaction_number := p_terminal_response->'castles_transaction'->>'referenceId';
        v_dejavoo_auth_code := p_terminal_response->'castles_transaction'->>'approvalCode';
        v_dejavoo_batch_number := p_terminal_response->'castles_transaction'->>'batchNumber';
        v_dejavoo_rrn := p_terminal_response->'castles_transaction'->>'rrn';
        v_dejavoo_entry_mode := p_terminal_response->'castles_transaction'->>'entryMode';
        v_dejavoo_result_code := p_terminal_response->'castles_transaction'->>'resultCode';
        v_dejavoo_status_code := p_terminal_response->'castles_transaction'->>'resultCode';
        v_dejavoo_last_four := p_terminal_response->'castles_transaction'->>'cardLast4';
    END IF;

    -- ============================================
    -- 6.8 Resolve Terminal ID
    -- ============================================
    v_terminal_id := COALESCE(
        p_terminal_id,
        (p_terminal_response->'castles_transaction'->>'terminalId')::uuid,
        (p_terminal_response->'dejavoo_transaction'->>'terminalId')::uuid,
        (p_terminal_response->>'terminal_id')::uuid
    );

    -- ============================================
    -- 7. Create Payment Record
    -- ============================================
    INSERT INTO public.order_payments (
        order_id,
        payment_method,
        amount,
        tip_amount,
        total_amount,
        subtotal_portion,
        tax_portion,
        amount_tendered,
        change_given,
        is_cash_priced,
        cash_discount_applied,
        original_amount,
        covers_items,
        split_portion_index,
        split_count,
        status,
        terminal_type,
        processed_by_staff_id,
        processor_response,
        reference_number,
        transaction_id,
        authorization_code,
        dejavoo_response_code,
        dejavoo_batch_number,
        dejavoo_invoice_number,
        card_type,
        card_last_four,
        captured_at,
        initiated_at,
        merchant_id,
        location_id,
        rrn,
        result_code,
        result_message,
        terminal_id
    ) VALUES (
        p_order_id,
        p_payment_method::payment_method,
        v_payment_total,
        COALESCE(p_tip_amount, 0),
        v_payment_total + COALESCE(p_tip_amount, 0),
        v_subtotal_portion,
        v_tax_portion,
        CASE WHEN v_is_cash THEN COALESCE(p_amount_tendered, v_payment_total) END,
        v_change_given,
        v_use_cash_pricing,
        v_use_cash_pricing,
        CASE WHEN v_use_cash_pricing
            THEN ROUND(v_payment_total * v_order.card_total / NULLIF(v_order.cash_total, 0), 2)
            ELSE v_payment_total
        END,
        CASE WHEN array_length(v_covered_items, 1) > 0 THEN v_covered_items ELSE NULL END,
        p_split_portion_index,
        p_split_count,
        'captured',
        CASE
            WHEN v_is_cash THEN 'cash_drawer'
            WHEN p_terminal_response ? 'castles_transaction' THEN 'castles'
            ELSE 'dejavoo'
        END::terminal_type,
        p_staff_id,
        p_terminal_response,
        COALESCE(v_dejavoo_reference_id, p_terminal_response->>'transaction_id'),
        COALESCE(v_dejavoo_transaction_number, p_terminal_response->>'transaction_id'),
        COALESCE(v_dejavoo_auth_code, p_terminal_response->>'authorization_code'),
        v_dejavoo_status_code,
        v_dejavoo_batch_number,
        v_dejavoo_invoice_number,
        COALESCE(
            p_terminal_response->'dejavoo_transaction'->>'cardType',
            p_terminal_response->'castles_transaction'->>'cardType',
            p_terminal_response->>'card_type'
        ),
        v_dejavoo_last_four,
        now(),
        now(),
        v_order.merchant_id,
        v_order.location_id,
        v_dejavoo_rrn,
        v_dejavoo_result_code,
        COALESCE(
            p_terminal_response->'dejavoo_transaction'->>'resultMessage',
            p_terminal_response->'castles_transaction'->>'statusMessage'
        ),
        v_terminal_id
    )
    RETURNING id INTO v_payment_id;

 PERFORM log_payment_event(
        p_payment_id := v_payment_id,
        p_order_id := p_order_id,
        p_location_id := v_order.location_id,
        p_event_type := 'captured',
        p_amount := v_payment_total,
        p_tip_amount := COALESCE(p_tip_amount, 0),
        p_previous_status := NULL,
        p_new_status := 'captured',
        p_psp_reference := COALESCE(
            v_dejavoo_reference_id,
            v_dejavoo_transaction_number,
            p_terminal_response->>'transaction_id'
        ),
        p_auth_code := v_dejavoo_auth_code,
        p_staff_id := p_staff_id,
        p_terminal_id := COALESCE(
            p_terminal_response->'castles_transaction'->>'terminalId',
            p_terminal_response->'dejavoo_transaction'->>'terminalId',
            p_terminal_response->>'terminal_id'
        ),
        p_result_code := COALESCE(v_dejavoo_result_code, '00'),
        p_response_message := CASE
            WHEN v_is_cash THEN 'Cash payment captured'
            ELSE COALESCE(
                p_terminal_response->'dejavoo_transaction'->>'resultMessage',
                p_terminal_response->'castles_transaction'->>'statusMessage',
                'Card payment captured successfully'
            )
        END,
        p_raw_response := p_terminal_response,
        p_reason := NULL
    );

    -- ============================================
    -- 8. Per-Item: Create order_payment_items
    --    NOTE: Accounts for refunded_quantity in effective unpaid calculation
    -- ============================================
    -- Derive order_payment_items from v_covered_items_json (built BEFORE paid_quantity UPDATE)
    IF v_is_item_payment AND array_length(v_covered_items, 1) > 0 THEN
        INSERT INTO public.order_payment_items (
            order_payment_id,
            order_item_id,
            quantity_paid,
            unit_price_paid,
            subtotal_paid,
            tax_paid
        )
        SELECT
            v_payment_id,
            (ci->>'order_item_id')::uuid,
            (ci->>'quantity_paid')::integer,
            (ci->>'unit_price')::numeric,
            (ci->>'subtotal')::numeric,
            ROUND((ci->>'subtotal')::numeric * COALESCE((ci->>'tax_rate')::numeric, 0) / 100, 2)
        FROM jsonb_array_elements(v_covered_items_json) AS ci;

    ELSIF v_is_full_remaining AND array_length(v_covered_items, 1) > 0 THEN
        INSERT INTO public.order_payment_items (
            order_payment_id,
            order_item_id,
            quantity_paid,
            unit_price_paid,
            subtotal_paid,
            tax_paid
        )
        SELECT
            v_payment_id,
            (ci->>'order_item_id')::uuid,
            (ci->>'quantity_paid')::integer,
            (ci->>'unit_price')::numeric,
            (ci->>'quantity_paid')::integer * (ci->>'unit_price')::numeric
                - ROUND(COALESCE((ci->>'discount_amount')::numeric, 0)
                        * (ci->>'quantity_paid')::integer
                        / NULLIF((ci->>'original_quantity')::integer, 0)
                  , 2),
            ROUND(
                ((ci->>'quantity_paid')::integer * (ci->>'unit_price')::numeric
                  - ROUND(COALESCE((ci->>'discount_amount')::numeric, 0)
                          * (ci->>'quantity_paid')::integer
                          / NULLIF((ci->>'original_quantity')::integer, 0)
                    , 2))
                * COALESCE((ci->>'tax_rate')::numeric, 0) / 100
            , 2)
        FROM jsonb_array_elements(v_covered_items_json) AS ci;
        -- NOTE: Split-even and partial-amount payments intentionally have no
        -- order_payment_items records. They cover a proportional share of the
        -- whole order, not specific items.
    END IF;

    -- ============================================
    -- 9. Update Payment Totals (include this payment)
    -- ============================================
    IF v_use_cash_pricing THEN
        v_total_cash_paid := v_total_cash_paid + v_payment_total + COALESCE(p_tip_amount, 0);
    ELSE
        v_total_card_paid := v_total_card_paid + v_payment_total + COALESCE(p_tip_amount, 0);
    END IF;

    v_new_amount_paid := v_total_cash_paid + v_total_card_paid;

    -- ============================================
    -- 10. Calculate NEW Unpaid Totals from Items
    --     NOTE: Accounts for refunded_quantity
    --     effective_unpaid = quantity - paid_quantity + refunded_quantity
    -- ============================================
    SELECT
        COUNT(*),
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price)
            - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)
            + ROUND((((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.unit_price) - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)) * COALESCE(oi.tax_rate, 0) / 100, 2)
        ), 0),
        COALESCE(SUM(
            ((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price)
            - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)
            + ROUND((((oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) * oi.cash_price) - ROUND(COALESCE(oi.discount_amount, 0) * (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0))::numeric / NULLIF(oi.quantity, 0), 2)) * COALESCE(oi.tax_rate, 0) / 100, 2)
        ), 0)
    INTO v_unpaid_items_count, v_unpaid_card_total, v_unpaid_cash_total
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id
      AND oi.is_voided = false
      AND (oi.quantity - COALESCE(oi.paid_quantity, 0) + COALESCE(oi.refunded_quantity, 0)) > 0;

    -- Re-apply custom refund balance for post-payment state
    -- Use original_amount (card-equivalent) to avoid phantom balance from cash payments
    SELECT COALESCE(SUM(
        COALESCE(original_amount, amount)
        - COALESCE(refunded_amount, 0) * COALESCE(original_amount, amount) / NULLIF(amount, 0)
    ), 0)
    INTO v_effective_paid
    FROM public.order_payments
    WHERE order_id = p_order_id
      AND status IN ('captured', 'partially_refunded', 'refunded')
      AND is_voided = false;

    v_payment_based_due := GREATEST(v_order.card_total - v_effective_paid, 0);
    v_custom_refund_balance := GREATEST(v_payment_based_due - v_unpaid_card_total, 0);
    v_unpaid_card_total := v_unpaid_card_total + v_custom_refund_balance;
    v_unpaid_cash_total := v_unpaid_cash_total + v_custom_refund_balance;

    -- Fix: Same clamping for post-payment unpaid totals.
    -- After a partial payment, items are still "unpaid" but payment_based_due reflects actual remaining.
    IF v_payment_based_due < v_unpaid_card_total THEN
        IF v_unpaid_card_total > 0 THEN
            v_unpaid_cash_total := ROUND(
                v_unpaid_cash_total * v_payment_based_due / v_unpaid_card_total, 2
            );
        END IF;
        v_unpaid_card_total := v_payment_based_due;
    END IF;

    -- ============================================
    -- 11. Determine if Order is Fully Paid
    -- ============================================
    IF v_is_item_payment THEN
        v_order_fully_paid := (v_unpaid_items_count = 0);

    ELSIF v_is_split_payment THEN
        SELECT COUNT(*) INTO v_portions_paid
        FROM public.order_payments
        WHERE order_id = p_order_id
          AND split_portion_index IS NOT NULL
          AND split_count = p_split_count
          AND status = 'captured';

        v_portions_remaining := p_split_count - v_portions_paid;
        v_order_fully_paid := (v_portions_remaining = 0);

    ELSE
        v_order_fully_paid := (
            (v_total_cash_paid >= v_order.cash_total AND v_total_card_paid = 0) OR
            (v_total_card_paid >= v_order.card_total AND v_total_cash_paid = 0) OR
            (v_unpaid_card_total <= 0.01 AND v_unpaid_cash_total <= 0.01) OR
            (v_new_amount_paid >= v_order.card_total)
        );
    END IF;

    -- ============================================
    -- 12. Handle Split Complete
    --     NOTE: Accounts for refunded_quantity when marking items as paid
    -- ============================================
        -- ============================================
    -- 12. Handle Split Complete
    --     NOTE: Accounts for refunded_quantity when marking items as paid
    -- ============================================
    IF v_is_split_payment THEN
        SELECT COUNT(*) INTO v_portions_paid
        FROM public.order_payments
        WHERE order_id = p_order_id
          AND split_portion_index IS NOT NULL
          AND split_count = p_split_count
          AND status = 'captured';

        v_portions_remaining := p_split_count - v_portions_paid;
        v_order_fully_paid := (v_portions_remaining = 0);

        IF v_order_fully_paid AND v_unpaid_items_count > 0 THEN
            -- Set paid_quantity = quantity + refunded_quantity so effective_unpaid becomes 0
            UPDATE public.order_items
            SET
                paid_quantity = quantity + COALESCE(refunded_quantity, 0),
                price_paid = COALESCE(price_paid, unit_price),
                updated_at = now()
            WHERE order_id = p_order_id
              AND is_voided = false
              AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

            v_unpaid_items_count := 0;
            v_unpaid_card_total := 0;
            v_unpaid_cash_total := 0;
        END IF;
    ELSE
        -- Preserve section 11's amount-based result if it already determined fully paid.
        -- Only fall back to item-count check if amounts don't confirm paid.
        IF NOT v_order_fully_paid THEN
            v_order_fully_paid := (v_unpaid_items_count = 0);
        END IF;

        -- If fully paid by amounts but items weren't marked (custom amount that
        -- covered the full order, or rounding caused v_is_full_remaining=false),
        -- mark all remaining items as paid for data consistency.
        -- This mirrors the split-completion pattern at lines 846-859.
        IF v_order_fully_paid AND v_unpaid_items_count > 0 THEN
            UPDATE public.order_items
            SET
                paid_quantity = quantity + COALESCE(refunded_quantity, 0),
                price_paid = COALESCE(price_paid, CASE WHEN v_use_cash_pricing THEN cash_price ELSE unit_price END),
                updated_at = now()
            WHERE order_id = p_order_id
              AND is_voided = false
              AND (quantity - COALESCE(paid_quantity, 0) + COALESCE(refunded_quantity, 0)) > 0;

            v_unpaid_items_count := 0;
            v_unpaid_card_total := 0;
            v_unpaid_cash_total := 0;
        END IF;
    END IF;

    -- ============================================
    -- 13. Set Final amount_due
    --     FIX: When order is fully paid, force amount_due to 0.
    --     This prevents the custom_refund_balance logic from inflating
    --     amount_due when a cash payment (at cash price) is compared
    --     against card_total, producing a false residual.
    -- ============================================
    IF v_order_fully_paid THEN
        v_new_amount_due := 0;
        v_new_cash_amount_due := 0;
        v_unpaid_card_total := 0;
        v_unpaid_cash_total := 0;
    ELSE
        v_new_amount_due := v_unpaid_card_total;
        v_new_cash_amount_due := v_unpaid_cash_total;
    END IF;

    -- ============================================
    -- 14. Update Order
    -- ============================================
    UPDATE public.orders SET
        amount_paid = v_new_amount_paid,
        amount_due = v_new_amount_due,
        cash_amount_due = v_new_cash_amount_due,
        tip_amount = COALESCE(tip_amount, 0) + COALESCE(p_tip_amount, 0),
        payment_pricing_mode = v_new_pricing_mode::pricing_mode,
        cash_discount_applied = COALESCE(cash_discount_applied, false) OR v_use_cash_pricing,
        payment_status = CASE
            WHEN v_order_fully_paid THEN 'paid'::payment_status
            WHEN v_new_amount_paid > 0 THEN 'partial'::payment_status
            ELSE 'pending'::payment_status
        END,
        updated_at = now()
    WHERE id = p_order_id;

    v_new_sync_version := increment_order_sync_version(p_order_id);

    -- ============================================
    -- 15. Return Result
    -- ============================================
    RETURN jsonb_build_object(
        'success', true,
        'payment_id', v_payment_id,
        'payment_method', p_payment_method,
        'amount_charged', v_payment_total,
        'tip_amount', COALESCE(p_tip_amount, 0),
        'total_collected', v_payment_total + COALESCE(p_tip_amount, 0),
        'change_given', v_change_given,
        'is_cash_priced', v_use_cash_pricing,
        'pricing_mode', v_new_pricing_mode,

        'is_item_payment', v_is_item_payment,
        'is_split_payment', v_is_split_payment,
        'is_full_remaining', v_is_full_remaining,

        'split_count', p_split_count,
        'split_portion_index', p_split_portion_index,
        'portions_paid', v_portions_paid,
        'portions_remaining', v_portions_remaining,
        'split_card_portion', v_split_card_portion,
        'split_cash_portion', v_split_cash_portion,

        'items_paid', v_covered_items_json,
        'items_covered', v_covered_items,

        'total_cash_paid', v_total_cash_paid,
        'total_card_paid', v_total_card_paid,

        'order_amount_paid', v_new_amount_paid,
        'order_amount_due', v_new_amount_due,
        'order_cash_amount_due', v_new_cash_amount_due,
        'order_fully_paid', v_order_fully_paid,

        'unpaid_items_count', v_unpaid_items_count,
        'unpaid_card_total', v_unpaid_card_total,
        'unpaid_cash_total', v_unpaid_cash_total,

        'sync_version', v_new_sync_version
    );
END;
$_$;


ALTER FUNCTION "public"."process_payment_v8"("p_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric, "p_tip_amount" numeric, "p_amount_tendered" numeric, "p_item_allocations" "jsonb", "p_staff_id" "uuid", "p_terminal_response" "jsonb", "p_split_count" integer, "p_split_portion_index" integer, "p_force_card_pricing" boolean, "p_terminal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_preauth_v1"("p_order_id" "uuid", "p_amount" numeric, "p_terminal_response" "jsonb" DEFAULT NULL::"jsonb", "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_terminal_type" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order RECORD;
  v_existing_auth_count INT;
  v_payment_id UUID;
  v_rrn TEXT;
  v_auth_code TEXT;
  v_ref_id TEXT;
  v_card_type TEXT;
  v_card_last_four TEXT;
BEGIN
  -- Validate order exists and is active
  SELECT id, status, location_id, merchant_id
  INTO v_order
  FROM orders
  WHERE id = p_order_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.status IN ('completed', 'cancelled', 'refunded', 'void') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order is not active');
  END IF;

  -- Guard: reject if order already has an active pre-auth
  SELECT COUNT(*)
  INTO v_existing_auth_count
  FROM order_payments
  WHERE order_id = p_order_id
    AND status = 'authorized'
    AND (is_voided IS NULL OR is_voided = false);

  IF v_existing_auth_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order already has an active pre-authorization');
  END IF;

  -- Extract terminal reference fields
  v_rrn := COALESCE(
    p_terminal_response->'castles_transaction'->>'rrn',
    p_terminal_response->>'rrn',
    ''
  );
  v_auth_code := COALESCE(
    p_terminal_response->'castles_transaction'->>'approvalCode',
    p_terminal_response->>'AuthCode',
    ''
  );
  v_ref_id := COALESCE(
    p_terminal_response->'castles_transaction'->>'referenceId',
    p_terminal_response->>'ReferenceId',
    ''
  );

  -- Extract card details from terminal response
  v_card_type := COALESCE(
    p_terminal_response->'castles_transaction'->>'cardType',
    p_terminal_response->'raw_castles_response'->>'txnCardBrand',
    p_terminal_response->'dejavoo_transaction'->>'CardType',
    NULL
  );
  v_card_last_four := COALESCE(
    p_terminal_response->'castles_transaction'->>'cardLast4',
    p_terminal_response->'dejavoo_transaction'->>'Last4',
    NULL
  );

  -- Insert authorized payment
  INSERT INTO order_payments (
    order_id,
    payment_method,
    amount,
    tip_amount,
    total_amount,
    status,
    authorized_at,
    captured_at,
    rrn,
    authorization_code,
    reference_number,
    terminal_response,
    processed_by_staff_id,
    terminal_type,
    card_type,
    card_last_four,
    merchant_id,
    location_id,
    initiated_at
  ) VALUES (
    p_order_id,
    'card',
    p_amount,
    0,
    p_amount,
    'authorized',
    NOW(),
    NULL,
    v_rrn,
    v_auth_code,
    v_ref_id,
    p_terminal_response,
    p_staff_id,
    COALESCE(p_terminal_type, CASE
      WHEN p_terminal_response ? 'castles_transaction' THEN 'castles'
      ELSE 'dejavoo'
    END)::terminal_type,
    v_card_type,
    v_card_last_four,
    v_order.merchant_id,
    v_order.location_id,
    NOW()
  )
  RETURNING id INTO v_payment_id;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'authorized_amount', p_amount,
    'rrn', v_rrn,
    'auth_code', v_auth_code
  );
END;
$$;


ALTER FUNCTION "public"."process_preauth_v1"("p_order_id" "uuid", "p_amount" numeric, "p_terminal_response" "jsonb", "p_staff_id" "uuid", "p_terminal_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_shift_pto_accrual"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_policy_id uuid;
    v_accrual_rate numeric;
    v_method text;
    v_hours_worked numeric;
    v_earned numeric;
BEGIN
    -- Only run when shift becomes 'completed'
    IF NEW.status = 'completed' AND (OLD.status != 'completed' OR OLD.status IS NULL) THEN
        
        -- 1. Get Employee's Policy
        SELECT p.id, p.accrual_rate, p.accrual_method
        INTO v_policy_id, v_accrual_rate, v_method
        FROM staff_profiles sp
        JOIN pto_policies p ON p.id = sp.pto_policy_id
        WHERE sp.id = NEW.employee_id;
        
        -- If no policy or not hourly, skip
        IF v_policy_id IS NULL OR v_method != 'hourly' THEN RETURN NEW; END IF;

        -- 2. Calculate Hours Worked (using actual clock times if available, else scheduled)
        v_hours_worked := EXTRACT(EPOCH FROM (NEW.end_time - NEW.start_time))/3600;
        
        -- 3. Calculate Earned Amount
        v_earned := v_hours_worked * v_accrual_rate;
        
        -- 4. Credit the Ledger
        INSERT INTO pto_ledger (
            merchant_id, 
            employee_id, 
            transaction_type, 
            amount, 
            source_shift_id, 
            description
        ) VALUES (
            NEW.merchant_id,
            NEW.employee_id,
            'accrual',
            v_earned,
            NEW.id,
            'Accrued from ' || round(v_hours_worked, 2) || 'h shift'
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."process_shift_pto_accrual"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_split_payment"("p_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric, "p_amount_tendered" numeric DEFAULT NULL::numeric, "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_terminal_response" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_order record;
    v_payment_id uuid;
    v_is_cash boolean;
    v_subtotal_portion numeric;
    v_tax_portion numeric;
    v_total_for_tender numeric;
    v_remaining_after numeric;
    v_change_due numeric := 0;
    v_new_payment_status text;
BEGIN
    v_is_cash := p_payment_method = 'cash';

    -- Get current order state
    SELECT * INTO v_order
    FROM public.orders
    WHERE id = p_order_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found: %', p_order_id;
    END IF;

    -- Calculate what portion of the order this payment covers
    -- Use the appropriate pricing based on tender type
    IF v_is_cash THEN
        -- Cash payment uses cash pricing for its portion
        v_total_for_tender := LEAST(p_amount, v_order.amount_due);

        -- Pro-rate subtotal and tax at cash rates
        IF v_order.cash_total > 0 THEN
            v_subtotal_portion := ROUND(v_total_for_tender * (v_order.cash_subtotal / v_order.cash_total), 2);
            v_tax_portion := v_total_for_tender - v_subtotal_portion;
        ELSE
            v_subtotal_portion := v_total_for_tender;
            v_tax_portion := 0;
        END IF;

        v_change_due := GREATEST(COALESCE(p_amount_tendered, p_amount) - v_total_for_tender, 0);
    ELSE
        -- Card payment uses card pricing
        v_total_for_tender := p_amount;

        IF v_order.card_total > 0 THEN
            v_subtotal_portion := ROUND(v_total_for_tender * (v_order.card_subtotal / v_order.card_total), 2);
            v_tax_portion := v_total_for_tender - v_subtotal_portion;
        ELSE
            v_subtotal_portion := v_total_for_tender;
            v_tax_portion := 0;
        END IF;
    END IF;

    -- Create payment record
    INSERT INTO public.order_payments (
        order_id,
        payment_method,
        amount,
        subtotal_portion,
        tax_portion,
        total_amount,
        is_cash_priced,
        cash_discount_applied,
        original_amount,
        amount_tendered,
        change_given,
        status,
        terminal_type,
        processed_by_staff_id,
        processor_response,
        captured_at
    ) VALUES (
        p_order_id,
        p_payment_method::payment_method,
        v_total_for_tender,
        v_subtotal_portion,
        v_tax_portion,
        v_total_for_tender,
        v_is_cash,
        v_is_cash,
        CASE WHEN v_is_cash THEN
            ROUND(v_total_for_tender * (v_order.card_total / NULLIF(v_order.cash_total, 0)), 2)
        ELSE v_total_for_tender END,
        p_amount_tendered,
        v_change_due,
        'paid',
        CASE WHEN v_is_cash THEN 'cash_drawer' ELSE 'dejavoo' END::terminal_type,
        p_staff_id,
        p_terminal_response,
        now()
    )
    RETURNING id INTO v_payment_id;

    -- Calculate new order totals
    v_remaining_after := GREATEST(v_order.amount_due - v_total_for_tender, 0);
    v_new_payment_status := CASE
        WHEN v_remaining_after <= 0 THEN 'paid'
        WHEN v_order.amount_paid + v_total_for_tender > 0 THEN 'partial'
        ELSE 'pending'
    END;

    -- Update order
    UPDATE public.orders SET
        amount_paid = amount_paid + v_total_for_tender,
        amount_due = v_remaining_after,
        payment_status = v_new_payment_status::payment_status,
        -- Recalculate effective totals based on actual payments
        effective_subtotal = (
            SELECT COALESCE(SUM(subtotal_portion), 0)
            FROM public.order_payments
            WHERE order_id = p_order_id AND status = 'paid' AND is_voided = false
        ),
        effective_tax_amount = (
            SELECT COALESCE(SUM(tax_portion), 0)
            FROM public.order_payments
            WHERE order_id = p_order_id AND status = 'paid' AND is_voided = false
        ),
        effective_total = (
            SELECT COALESCE(SUM(total_amount), 0)
            FROM public.order_payments
            WHERE order_id = p_order_id AND status = 'paid' AND is_voided = false
        ),
        cash_discount_applied = EXISTS(
            SELECT 1 FROM public.order_payments
            WHERE order_id = p_order_id AND is_cash_priced = true AND is_voided = false
        ),
        updated_at = now()
    WHERE id = p_order_id;

    RETURN jsonb_build_object(
        'success', true,
        'payment_id', v_payment_id,
        'payment_method', p_payment_method,
        'amount_applied', v_total_for_tender,
        'subtotal_portion', v_subtotal_portion,
        'tax_portion', v_tax_portion,
        'change_due', v_change_due,
        'remaining_balance', v_remaining_after,
        'order_payment_status', v_new_payment_status
    );
END;
$$;


ALTER FUNCTION "public"."process_split_payment"("p_order_id" "uuid", "p_payment_method" "text", "p_amount" numeric, "p_amount_tendered" numeric, "p_staff_id" "uuid", "p_terminal_response" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."propagate_rush_to_kds"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Touch the parent order to trigger a broadcast
  UPDATE orders
  SET updated_at = NOW()
  WHERE id = NEW.order_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."propagate_rush_to_kds"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."propagate_rush_to_kds"() IS 'Touches parent order updated_at when an item is marked rush, triggering broadcast to KDS.';



CREATE OR REPLACE FUNCTION "public"."publish_schedule"("p_schedule_id" "uuid", "p_merchant_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_schedule_name text;
    v_start_date date;
    v_end_date date;
BEGIN
    -- 1. Get Schedule Details & Validate
    SELECT name, start_date, end_date 
    INTO v_schedule_name, v_start_date, v_end_date
    FROM schedules 
    WHERE id = p_schedule_id AND merchant_id = p_merchant_id;

    IF NOT FOUND THEN RAISE EXCEPTION 'Schedule not found'; END IF;

    -- 2. Update Schedule Status
    UPDATE schedules 
    SET status = 'active', updated_at = now() 
    WHERE id = p_schedule_id;

    -- 3. Update Shifts Status
    UPDATE shifts 
    SET status = 'published', updated_at = now()
    WHERE schedule_id = p_schedule_id;

    -- 4. BATCH NOTIFY: Insert one notification per unique employee
    INSERT INTO notifications (
        merchant_id, 
        recipient_id, 
        type, 
        title, 
        body, 
        data
    )
    SELECT DISTINCT
        p_merchant_id,
        s.employee_id,
        'schedule_published',
        'New Schedule Published',
        -- Dynamic Message: "Week 42 (Oct 21 - Oct 27) is now live."
        v_schedule_name || ' (' || to_char(v_start_date, 'Mon DD') || ' - ' || to_char(v_end_date, 'Mon DD') || ') is now live.',
        jsonb_build_object('schedule_id', p_schedule_id)
    FROM shifts s
    WHERE s.schedule_id = p_schedule_id
      AND s.employee_id IS NOT NULL; -- Don't notify open shifts yet

    RETURN true;
END;
$$;


ALTER FUNCTION "public"."publish_schedule"("p_schedule_id" "uuid", "p_merchant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_order_discount"("p_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_discount RECORD;
    v_preset_discount RECORD;
    v_applicable_subtotal NUMERIC := 0;
    v_new_calculated_amount NUMERIC := 0;
    v_affected_item_ids UUID[] := '{}';
    
    -- For item distribution
    v_item RECORD;
    v_item_proportion NUMERIC;
    v_item_discount_amount NUMERIC;
    v_distributed_total NUMERIC := 0;
    v_last_item_id UUID;
    v_item_calcs JSONB;
    
    -- Order totals
    v_gross_card_subtotal NUMERIC;
    v_gross_cash_subtotal NUMERIC;
    v_total_discount NUMERIC;
    v_net_card_subtotal NUMERIC;
    v_net_cash_subtotal NUMERIC;
    v_card_tax NUMERIC;
    v_cash_tax NUMERIC;
    v_card_total NUMERIC;
    v_cash_total NUMERIC;
    v_amount_paid NUMERIC;
BEGIN
    -- ============================================
    -- 1. Get Active Order-Level Discount
    -- ============================================
    SELECT 
        od.id,
        od.discount_id,
        od.discount_name,
        od.discount_type::text as discount_type,
        od.discount_value,
        od.source::text as source,
        od.applied_by_staff_profiles_id,
        od.approved_by_staff_profiles_id,
        d.max_discount_amount,
        d.exclude_alcohol,
        d.exclude_categories,
        d.applies_to_categories
    INTO v_discount
    FROM public.order_discounts od
    LEFT JOIN public.discounts d ON d.id = od.discount_id
    WHERE od.order_id = p_order_id
      AND od.voided_at IS NULL
    ORDER BY od.applied_at DESC
    LIMIT 1;
    
    -- If no active discount, just recalculate totals and return
    IF v_discount.id IS NULL THEN
        -- Clear any stale discount data from items
        UPDATE public.order_items
        SET
            discount_id = NULL,
            discount_type = NULL,
            discount_value = 0,
            discount_amount = 0,
            discount_source = NULL,
            discount_applied_by = NULL,
            discount_approved_by = NULL,
            pre_discount_subtotal = NULL,
            -- Recalculate without discount
            subtotal = quantity * unit_price,
            cash_subtotal = quantity * COALESCE(cash_price, unit_price),
            tax_amount = ROUND((quantity * unit_price) * COALESCE(tax_rate, 0) / 100, 2),
            cash_tax_amount = ROUND((quantity * COALESCE(cash_price, unit_price)) * COALESCE(tax_rate, 0) / 100, 2),
            updated_at = now()
        WHERE order_id = p_order_id
          AND is_voided = false
          AND discount_amount > 0;
        
        PERFORM calculate_order_totals_fast(p_order_id);
        
        RETURN jsonb_build_object(
            'success', true,
            'has_discount', false,
            'message', 'No active discount'
        );
    END IF;
    
    -- ============================================
    -- 2. Get All Applicable Items
    -- ============================================
    -- Start with all unpaid, non-voided items
    SELECT 
        COALESCE(SUM(oi.quantity * oi.unit_price), 0),
        COALESCE(array_agg(oi.id), '{}')
    INTO v_applicable_subtotal, v_affected_item_ids
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id
      AND oi.is_voided = false
      AND oi.quantity > COALESCE(oi.paid_quantity, 0);
    
    -- Apply exclusions if preset discount
    IF v_discount.discount_id IS NOT NULL THEN
        -- Exclude alcohol
        IF COALESCE(v_discount.exclude_alcohol, false) THEN
            SELECT 
                COALESCE(SUM(oi.quantity * oi.unit_price), 0),
                COALESCE(array_agg(oi.id), '{}')
            INTO v_applicable_subtotal, v_affected_item_ids
            FROM public.order_items oi
            LEFT JOIN public.menu_items mi ON mi.id = oi.menu_item_id
            WHERE oi.order_id = p_order_id
              AND oi.is_voided = false
              AND oi.quantity > COALESCE(oi.paid_quantity, 0)
              AND COALESCE(mi.is_alcohol, false) = false;
        END IF;
        
        -- Exclude categories
        IF v_discount.exclude_categories IS NOT NULL THEN
            SELECT 
                COALESCE(SUM(oi.quantity * oi.unit_price), 0),
                COALESCE(array_agg(oi.id), '{}')
            INTO v_applicable_subtotal, v_affected_item_ids
            FROM public.order_items oi
            LEFT JOIN public.menu_items mi ON mi.id = oi.menu_item_id
            WHERE oi.order_id = p_order_id
              AND oi.is_voided = false
              AND oi.quantity > COALESCE(oi.paid_quantity, 0)
              AND (mi.category_id IS NULL OR NOT (mi.category_id = ANY(v_discount.exclude_categories)));
        END IF;
        
        -- Apply to specific categories only
        IF v_discount.applies_to_categories IS NOT NULL THEN
            SELECT 
                COALESCE(SUM(oi.quantity * oi.unit_price), 0),
                COALESCE(array_agg(oi.id), '{}')
            INTO v_applicable_subtotal, v_affected_item_ids
            FROM public.order_items oi
            LEFT JOIN public.menu_items mi ON mi.id = oi.menu_item_id
            WHERE oi.order_id = p_order_id
              AND oi.is_voided = false
              AND oi.quantity > COALESCE(oi.paid_quantity, 0)
              AND mi.category_id = ANY(v_discount.applies_to_categories);
        END IF;
    END IF;
    
    -- ============================================
    -- 3. Calculate New Discount Amount
    -- ============================================
    IF v_applicable_subtotal > 0 THEN
        IF v_discount.discount_type = 'percentage' THEN
            v_new_calculated_amount := ROUND(v_applicable_subtotal * (v_discount.discount_value / 100), 2);
            -- Apply cap if exists
            IF v_discount.max_discount_amount IS NOT NULL THEN
                v_new_calculated_amount := LEAST(v_new_calculated_amount, v_discount.max_discount_amount);
            END IF;
        ELSE
            -- Fixed amount
            v_new_calculated_amount := LEAST(v_discount.discount_value, v_applicable_subtotal);
        END IF;
    ELSE
        v_new_calculated_amount := 0;
    END IF;
    
    -- ============================================
    -- 4. Update order_discounts Record
    -- ============================================
    UPDATE public.order_discounts
    SET
        calculated_amount = v_new_calculated_amount,
        pre_discount_subtotal = v_applicable_subtotal,
        applied_to_item_ids = v_affected_item_ids
    WHERE id = v_discount.id;
    
    -- ============================================
    -- 5. Clear Discounts from Non-Applicable Items
    -- ============================================
    UPDATE public.order_items
    SET
        discount_id = NULL,
        discount_type = NULL,
        discount_value = 0,
        discount_amount = 0,
        discount_source = NULL,
        discount_applied_by = NULL,
        discount_approved_by = NULL,
        pre_discount_subtotal = NULL,
        subtotal = quantity * unit_price,
        cash_subtotal = quantity * COALESCE(cash_price, unit_price),
        tax_amount = ROUND((quantity * unit_price) * COALESCE(tax_rate, 0) / 100, 2),
        cash_tax_amount = ROUND((quantity * COALESCE(cash_price, unit_price)) * COALESCE(tax_rate, 0) / 100, 2),
        updated_at = now()
    WHERE order_id = p_order_id
      AND is_voided = false
      AND id <> ALL(v_affected_item_ids);
    
    -- ============================================
    -- 6. Distribute Discount to Applicable Items
    -- ============================================
    v_distributed_total := 0;
    v_last_item_id := NULL;
    
    FOR v_item IN
        SELECT 
            oi.id,
            oi.quantity,
            oi.paid_quantity,
            oi.unit_price,
            oi.cash_price,
            oi.tax_rate,
            (oi.quantity * oi.unit_price) as item_gross_subtotal
        FROM public.order_items oi
        WHERE oi.id = ANY(v_affected_item_ids)
          AND oi.is_voided = false
        ORDER BY oi.created_at, oi.id
    LOOP
        -- Calculate proportion
        IF v_applicable_subtotal > 0 THEN
            v_item_proportion := v_item.item_gross_subtotal / v_applicable_subtotal;
        ELSE
            v_item_proportion := 0;
        END IF;
        
        -- This item's discount
        v_item_discount_amount := ROUND(v_new_calculated_amount * v_item_proportion, 2);
        v_distributed_total := v_distributed_total + v_item_discount_amount;
        v_last_item_id := v_item.id;
        
        -- Calculate item totals with discount
        v_item_calcs := calculate_item_totals(
            v_item.quantity,
            v_item.unit_price,
            v_item.cash_price,
            v_item.tax_rate,
            v_item_discount_amount
        );
        
        -- Update item
        UPDATE public.order_items
        SET
            discount_id = v_discount.discount_id,
            discount_type = v_discount.discount_type::discount_type,
            discount_value = v_discount.discount_value,
            discount_amount = v_item_discount_amount,
            discount_source = v_discount.source::discount_source,
            discount_applied_by = v_discount.applied_by_staff_profiles_id,
            discount_approved_by = v_discount.approved_by_staff_profiles_id,
            pre_discount_subtotal = v_item.item_gross_subtotal,
            subtotal = (v_item_calcs->>'subtotal')::numeric,
            cash_subtotal = (v_item_calcs->>'cash_subtotal')::numeric,
            tax_amount = (v_item_calcs->>'tax_amount')::numeric,
            cash_tax_amount = (v_item_calcs->>'cash_tax_amount')::numeric,
            updated_at = now()
        WHERE id = v_item.id;
    END LOOP;
    
    -- Handle rounding remainder
    IF v_last_item_id IS NOT NULL AND v_distributed_total <> v_new_calculated_amount THEN
        DECLARE
            v_rounding_adj NUMERIC := v_new_calculated_amount - v_distributed_total;
            v_last_row RECORD;
        BEGIN
            SELECT * INTO v_last_row FROM public.order_items WHERE id = v_last_item_id;
            
            v_item_calcs := calculate_item_totals(
                v_last_row.quantity,
                v_last_row.unit_price,
                v_last_row.cash_price,
                v_last_row.tax_rate,
                v_last_row.discount_amount + v_rounding_adj
            );
            
            UPDATE public.order_items
            SET
                discount_amount = discount_amount + v_rounding_adj,
                subtotal = (v_item_calcs->>'subtotal')::numeric,
                cash_subtotal = (v_item_calcs->>'cash_subtotal')::numeric,
                tax_amount = (v_item_calcs->>'tax_amount')::numeric,
                cash_tax_amount = (v_item_calcs->>'cash_tax_amount')::numeric,
                updated_at = now()
            WHERE id = v_last_item_id;
        END;
    END IF;
    
    -- ============================================
    -- 7. Recalculate Order Totals
    -- ============================================
    SELECT COALESCE(amount_paid, 0) INTO v_amount_paid
    FROM public.orders WHERE id = p_order_id;
    
    SELECT 
        COALESCE(SUM(quantity * unit_price), 0),
        COALESCE(SUM(quantity * COALESCE(cash_price, unit_price)), 0),
        COALESCE(SUM(discount_amount), 0),
        COALESCE(SUM(subtotal), 0),
        COALESCE(SUM(cash_subtotal), 0),
        COALESCE(SUM(tax_amount), 0),
        COALESCE(SUM(cash_tax_amount), 0)
    INTO 
        v_gross_card_subtotal,
        v_gross_cash_subtotal,
        v_total_discount,
        v_net_card_subtotal,
        v_net_cash_subtotal,
        v_card_tax,
        v_cash_tax
    FROM public.order_items
    WHERE order_id = p_order_id AND is_voided = false;
    
    v_card_total := v_net_card_subtotal + v_card_tax;
    v_cash_total := v_net_cash_subtotal + v_cash_tax;
    
    UPDATE public.orders SET
        card_subtotal = v_gross_card_subtotal,
        cash_subtotal = v_gross_cash_subtotal,
        subtotal = v_gross_card_subtotal,
        discount_amount = v_total_discount,
        effective_subtotal = v_net_card_subtotal,
        card_tax_amount = v_card_tax,
        cash_tax_amount = v_cash_tax,
        tax_amount = v_card_tax,
        effective_tax_amount = v_card_tax,
        card_total = v_card_total,
        cash_total = v_cash_total,
        total_amount = v_card_total,
        effective_total = v_card_total,
        amount_due = GREATEST(v_card_total - v_amount_paid, 0),
        cash_amount_due = GREATEST(v_cash_total - v_amount_paid, 0),
        updated_at = now()
    WHERE id = p_order_id;
    
    -- ============================================
    -- 8. Return Result
    -- ============================================
    RETURN jsonb_build_object(
        'success', true,
        'has_discount', true,
        'order_discount_id', v_discount.id,
        'discount_name', v_discount.discount_name,
        'pre_discount_subtotal', v_applicable_subtotal,
        'calculated_amount', v_new_calculated_amount,
        'affected_items_count', array_length(v_affected_item_ids, 1),
        'order_totals', jsonb_build_object(
            'card_subtotal', v_gross_card_subtotal,
            'discount_amount', v_total_discount,
            'effective_subtotal', v_net_card_subtotal,
            'card_tax', v_card_tax,
            'card_total', v_card_total,
            'cash_total', v_cash_total
        )
    );
END;
$$;


ALTER FUNCTION "public"."recalculate_order_discount"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_order_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_order_id UUID;
  v_subtotal NUMERIC(10, 2);
BEGIN
  -- Determine order_id based on trigger context
  IF TG_OP = 'DELETE' THEN
    v_order_id = OLD.order_id;
  ELSE
    v_order_id = NEW.order_id;
  END IF;
  
  -- Recalculate order subtotal
  SELECT COALESCE(SUM(subtotal), 0)
  INTO v_subtotal
  FROM public.order_items
  WHERE order_id = v_order_id
    AND is_voided = FALSE;
  
  -- Update order
  UPDATE public.orders
  SET 
    subtotal = v_subtotal,
    total_amount = v_subtotal + tax_amount + service_charge - discount_amount,
    amount_due = v_subtotal + tax_amount + service_charge - discount_amount - amount_paid,
    updated_at = NOW()
  WHERE id = v_order_id;
  
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."recalculate_order_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recall_kds_items"("p_order_item_ids" "uuid"[], "p_target_status" "text" DEFAULT 'sent'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_id UUID;
BEGIN
  -- Reset order_items kitchen_status to target status
  UPDATE order_items
  SET
    kitchen_status = p_target_status,
    completed_at = NULL,
    started_preparing_at = CASE
      WHEN p_target_status = 'sent' THEN NULL
      ELSE COALESCE(started_preparing_at, NOW())
    END,
    updated_at = NOW()
  WHERE id = ANY(p_order_item_ids);

  -- Reset kds_item_status records
  UPDATE kds_item_status
  SET
    status = CASE WHEN p_target_status = 'preparing' THEN 'pending' ELSE 'pending' END,
    started_at = CASE WHEN p_target_status = 'preparing' THEN COALESCE(started_at, NOW()) ELSE NULL END,
    completed_at = NULL,
    bumped_at = NULL,
    bumped_by = NULL,
    updated_at = NOW()
  WHERE order_item_id = ANY(p_order_item_ids);

  -- Touch parent order(s) to trigger broadcast
  FOR v_order_id IN
    SELECT DISTINCT order_id FROM order_items WHERE id = ANY(p_order_item_ids)
  LOOP
    UPDATE orders
    SET
      updated_at = NOW(),
      sync_version = COALESCE(sync_version, 0) + 1
    WHERE id = v_order_id;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."recall_kds_items"("p_order_item_ids" "uuid"[], "p_target_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recall_kds_items_dep"("p_order_item_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_order_id UUID;
BEGIN
  -- Reset order_items kitchen_status back to 'sent'
  UPDATE order_items
  SET
    kitchen_status = 'sent',
    completed_at = NULL,
    started_preparing_at = NULL,
    updated_at = NOW()
  WHERE id = ANY(p_order_item_ids);

  -- Reset kds_item_status records back to 'pending'
  UPDATE kds_item_status
  SET
    status = 'pending',
    started_at = NULL,
    completed_at = NULL,
    bumped_at = NULL,
    bumped_by = NULL,
    updated_at = NOW()
  WHERE order_item_id = ANY(p_order_item_ids);

  -- Touch parent order(s) to trigger broadcast
  FOR v_order_id IN
    SELECT DISTINCT order_id FROM order_items WHERE id = ANY(p_order_item_ids)
  LOOP
    UPDATE orders
    SET
      updated_at = NOW(),
      sync_version = COALESCE(sync_version, 0) + 1
    WHERE id = v_order_id;
  END LOOP;
END;$$;


ALTER FUNCTION "public"."recall_kds_items_dep"("p_order_item_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_cash_operation"("p_cash_drawer_id" "uuid", "p_session_id" "uuid", "p_operation_type" "text", "p_amount" numeric, "p_performed_by" "uuid", "p_order_id" "uuid" DEFAULT NULL::"uuid", "p_payment_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text", "p_approved_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_session RECORD;
  v_current_balance NUMERIC;
  v_balance_after NUMERIC;
  v_should_kick_drawer BOOLEAN := false;
  v_op_id UUID;
BEGIN
  -- Verify session is open
  SELECT * INTO v_session
  FROM cash_drawer_sessions
  WHERE id = p_session_id AND status = 'open';

  IF v_session IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No open session found'
    );
  END IF;

  -- Calculate current balance from operations
  SELECT v_session.opening_amount + COALESCE(SUM(
    CASE
      WHEN operation_type IN ('cash_sale', 'pay_in') THEN amount
      WHEN operation_type IN ('cash_refund', 'pay_out', 'cash_drop', 'tip_out') THEN -amount
      ELSE 0
    END
  ), 0)
  INTO v_current_balance
  FROM cash_drawer_operations
  WHERE session_id = p_session_id;

  -- Calculate new balance
  v_balance_after := CASE
    WHEN p_operation_type IN ('cash_sale', 'pay_in') THEN v_current_balance + p_amount
    WHEN p_operation_type IN ('cash_refund', 'pay_out', 'cash_drop', 'tip_out') THEN v_current_balance - p_amount
    ELSE v_current_balance -- no_sale, opening_count, closing_count
  END;

  -- Determine if drawer should be kicked open
  v_should_kick_drawer := p_operation_type IN ('no_sale', 'pay_in', 'pay_out', 'cash_drop');

  -- Insert operation
  INSERT INTO cash_drawer_operations (
    cash_drawer_id, session_id, operation_type,
    amount, performed_by, performed_at,
    order_id, payment_id, balance_after,
    reason, approved_by
  ) VALUES (
    p_cash_drawer_id, p_session_id, p_operation_type,
    p_amount, p_performed_by, NOW(),
    p_order_id, p_payment_id, v_balance_after,
    p_reason, p_approved_by
  )
  RETURNING id INTO v_op_id;

  -- Update session expected_cash for balance-affecting operations
  IF p_operation_type NOT IN ('no_sale', 'opening_count', 'closing_count') THEN
    UPDATE cash_drawer_sessions
    SET expected_cash = v_balance_after
    WHERE id = p_session_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'operation_id', v_op_id,
    'balance_after', v_balance_after,
    'should_kick_drawer', v_should_kick_drawer
  );
END;
$$;


ALTER FUNCTION "public"."record_cash_operation"("p_cash_drawer_id" "uuid", "p_session_id" "uuid", "p_operation_type" "text", "p_amount" numeric, "p_performed_by" "uuid", "p_order_id" "uuid", "p_payment_id" "uuid", "p_reason" "text", "p_approved_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_order_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO public.order_status_history (
      order_id,
      from_status,
      to_status,
      changed_by_staff_id,
      changed_by_user_id,
      changed_at
    ) VALUES (
      NEW.id,
      OLD.status,
      NEW.status,
      NEW.created_by_staff_id,
      NEW.created_by_user_id,
      NOW()
    );
    
    -- Update timing fields based on status
    IF NEW.status = 'pending' AND NEW.sent_to_kitchen_at IS NULL THEN
      NEW.sent_to_kitchen_at = NOW();
    ELSIF NEW.status = 'preparing' AND NEW.started_preparing_at IS NULL THEN
      NEW.started_preparing_at = NOW();
    ELSIF NEW.status = 'ready' AND NEW.ready_at IS NULL THEN
      NEW.ready_at = NOW();
    ELSIF NEW.status = 'completed' AND NEW.completed_at IS NULL THEN
      NEW.completed_at = NOW();
    ELSIF NEW.status IN ('cancelled', 'void') AND NEW.cancelled_at IS NULL THEN
      NEW.cancelled_at = NOW();
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."record_order_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_refund_items"("p_reversal_id" "uuid", "p_items" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_item jsonb;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO order_refund_items (
      reversal_id,
      order_item_id,
      order_payment_item_id,
      quantity_refunded,
      unit_price_refunded,
      subtotal_refunded,
      tax_refunded,
      total_refunded,
      refund_reason,
      refund_reason_detail,
      return_to_inventory,
      inventory_updated
    )
    VALUES (
      p_reversal_id,
      (v_item->>'order_item_id')::uuid,
      NULLIF(v_item->>'order_payment_item_id', '')::uuid,
      COALESCE((v_item->>'quantity_refunded')::integer, 1),
      COALESCE((v_item->>'unit_price_refunded')::numeric, 0),
      COALESCE((v_item->>'subtotal_refunded')::numeric, 0),
      COALESCE((v_item->>'tax_refunded')::numeric, 0),
      COALESCE((v_item->>'total_refunded')::numeric, 0),
      (v_item->>'refund_reason')::refund_reason_type,
      v_item->>'refund_reason_detail',
      COALESCE((v_item->>'return_to_inventory')::boolean, false),
      COALESCE((v_item->>'inventory_updated')::boolean, false)
    );

    UPDATE order_items
    SET refunded_quantity = COALESCE(refunded_quantity, 0)
          + COALESCE((v_item->>'quantity_refunded')::integer, 0),
        refunded_amount = COALESCE(refunded_amount, 0)
          + COALESCE((v_item->>'total_refunded')::numeric, 0)
    WHERE id = (v_item->>'order_item_id')::uuid;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."record_refund_items"("p_reversal_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


