CREATE OR REPLACE FUNCTION "public"."record_waitlist_sms_result"("p_waitlist_id" "uuid", "p_success" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF NOT p_success THEN
    UPDATE waitlist
    SET notification_failures = notification_failures + 1
    WHERE id = p_waitlist_id;
  END IF;
END;
$$;


