CREATE OR REPLACE FUNCTION "public"."record_waitlist_sms_result"("p_waitlist_id" "uuid", "p_success" boolean, "p_notification_type" "text" DEFAULT 'sms'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF p_success THEN
    UPDATE waitlist
    SET
      status = 'notified',
      notified_at = NOW(),
      notification_count = notification_count + 1,
      last_notification_type = p_notification_type
    WHERE id = p_waitlist_id;
  ELSE
    UPDATE waitlist
    SET
      notification_count = notification_count + 1,
      notification_failures = notification_failures + 1,
      last_notification_type = p_notification_type
    WHERE id = p_waitlist_id;
  END IF;
END;
$$;


