CREATE OR REPLACE FUNCTION "public"."remove_category_from_menu"("p_menu_id" "uuid", "p_category_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    DELETE FROM menu_categories
    WHERE menu_id = p_menu_id AND category_id = p_category_id;
    
    -- Also clean up location overrides
    DELETE FROM location_menu_category_overrides
    WHERE menu_id = p_menu_id AND category_id = p_category_id;
    
    RETURN json_build_object(
        'success', true,
        'menu_id', p_menu_id,
        'category_id', p_category_id
    );
END;
