CREATE OR REPLACE FUNCTION "public"."remove_order_item"("p_order_item_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_order_id UUID;
  v_order_status TEXT;
  v_item_kitchen_status TEXT;
  v_item_subtotal NUMERIC(10, 2);
  v_result JSON;
BEGIN
  -- Get order and item info and verify access
  SELECT 
    o.id,
    o.status,
    oi.subtotal,
    oi.kitchen_status
  INTO v_order_id, v_order_status, v_item_subtotal, v_item_kitchen_status
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
    AND oi.is_voided = FALSE
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found or access denied';
  END IF;

  -- Check item's kitchen_status instead of order status
  -- Items that have been sent to kitchen must be voided, not removed
  -- Allow hard delete for items with kitchen_status = 'new', NULL, or empty
  IF v_item_kitchen_status IS NOT NULL 
     AND v_item_kitchen_status NOT IN ('new', '') THEN
    RAISE EXCEPTION 'Cannot remove item with kitchen_status=%. Use void_order_item() instead.', v_item_kitchen_status;
  END IF;

  -- Delete modifiers first (cascade would handle this, but being explicit)
  DELETE FROM public.order_item_modifiers
  WHERE order_item_id = p_order_item_id;

  -- Delete the item
  DELETE FROM public.order_items
  WHERE id = p_order_item_id;
  
  PERFORM recalculate_order_discount(v_order_id);

  -- Return result
  SELECT json_build_object(
    'success', true,
    'removed_item_id', p_order_item_id,
    'order_id', v_order_id,
    'removed_subtotal', v_item_subtotal
  ) INTO v_result;

  RETURN v_result;
END;$$;


ALTER FUNCTION "public"."remove_order_item"("p_order_item_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_order_item"("p_order_item_id" "uuid") IS 'Hard deletes an order item (for draft/pending orders only). Use void_order_item for confirmed orders.';



CREATE OR REPLACE FUNCTION "public"."remove_order_item_modifier"("p_modifier_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_item_id UUID;
  v_order_id UUID;
  v_item_quantity INTEGER;
  v_price_paid NUMERIC(10, 2);
  v_new_modifier_total NUMERIC(10, 2);
  v_new_subtotal NUMERIC(10, 2);
  v_result JSON;
BEGIN
  -- Get modifier and item details
  SELECT 
    oim.order_item_id,
    oi.order_id,
    oi.quantity,
    oi.price_paid
  INTO v_order_item_id, v_order_id, v_item_quantity, v_price_paid
  FROM public.order_item_modifiers oim
  JOIN public.order_items oi ON oi.id = oim.order_item_id
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oim.id = p_modifier_id
    AND oi.is_voided = FALSE
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids())
    AND o.status NOT IN ('completed', 'cancelled', 'void');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Modifier not found or cannot be removed';
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Delete modifier
  DELETE FROM public.order_item_modifiers
  WHERE id = p_modifier_id;

  -- Calculate new totals
  SELECT COALESCE(SUM(total_price), 0)
  INTO v_new_modifier_total
  FROM public.order_item_modifiers
  WHERE order_item_id = v_order_item_id;

  v_new_subtotal := (v_item_quantity * v_price_paid) + (v_item_quantity * v_new_modifier_total);

  -- Update item subtotal
  UPDATE public.order_items
  SET 
    subtotal = v_new_subtotal,
    updated_at = NOW()
  WHERE id = v_order_item_id;

  SELECT json_build_object(
    'success', true,
    'removed_modifier_id', p_modifier_id,
    'order_item_id', v_order_item_id,
    'modifier_total', v_new_modifier_total,
    'new_subtotal', v_new_subtotal
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."remove_order_item_modifier"("p_modifier_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_order_items_batch"("p_order_item_ids" "uuid"[]) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_id UUID;
  v_order_status TEXT;
  v_removed_count INTEGER := 0;
  v_item_id UUID;
  v_result JSON;
BEGIN
  -- Verify all items belong to same order and order is draft/pending
  SELECT DISTINCT o.id, o.status
  INTO v_order_id, v_order_status
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = ANY(p_order_item_ids)
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order items not found or access denied';
  END IF;

  IF v_order_status NOT IN ('draft', 'pending') THEN
    RAISE EXCEPTION 'Cannot remove items from % orders', v_order_status;
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Delete modifiers for all items
  DELETE FROM public.order_item_modifiers
  WHERE order_item_id = ANY(p_order_item_ids);

  -- Delete items
  DELETE FROM public.order_items
  WHERE id = ANY(p_order_item_ids)
    AND is_voided = FALSE;

  GET DIAGNOSTICS v_removed_count = ROW_COUNT;

  SELECT json_build_object(
    'success', true,
    'order_id', v_order_id,
    'removed_count', v_removed_count,
    'removed_item_ids', p_order_item_ids
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."remove_order_items_batch"("p_order_item_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reopen_check"("p_order_id" "uuid", "p_staff_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_order RECORD;
  v_result JSONB;
BEGIN
  -- Lock and fetch order
  SELECT * INTO v_order
  FROM orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Order not found'
    );
  END IF;

  -- Validate check is closed (can't reopen an open check)
  IF v_order.check_status != 'Closed' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Check is not closed'
    );
  END IF;

  -- Reopen the check
  UPDATE orders
  SET check_status = 'Opened',
      updated_at = NOW(),
      sync_version = sync_version + 1
  WHERE id = p_order_id;

  -- Recalculate amount_due so re-payment is possible
  PERFORM calculate_order_totals_fast(p_order_id);
  
  -- Log the action with reason (audit_logs table expected to exist)
  INSERT INTO audit_logs (
    action,
    resource_type,
    resource_id,
    staff_profile_id,
    changes,
    created_at
  ) VALUES (
    'reopen_check',
    'orders',
    p_order_id,
    p_staff_id,
    jsonb_build_object(
      'check_status', 'Opened',
      'reason', COALESCE(p_reason, 'No reason provided')
    ),
    NOW()
  );

  -- Return success
  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'check_status', 'Opened'
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM
  );
END;$$;


ALTER FUNCTION "public"."reopen_check"("p_order_id" "uuid", "p_staff_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_category_items"("p_location_id" "uuid", "p_category_id" "uuid", "p_item_orders" "jsonb") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_item RECORD;
BEGIN
    FOR v_item IN SELECT * FROM jsonb_to_recordset(p_item_orders) AS x(menu_item_id UUID, display_order INTEGER)
    LOOP
        IF p_location_id IS NULL THEN
            -- Global update
            UPDATE category_items
            SET display_order = v_item.display_order,
                updated_at = NOW()
            WHERE category_id = p_category_id AND menu_item_id = v_item.menu_item_id;
        ELSE
            -- Location override update
            INSERT INTO location_category_item_overrides (location_id, category_id, menu_item_id, display_order, updated_at)
            VALUES (p_location_id, p_category_id, v_item.menu_item_id, v_item.display_order, NOW())
            ON CONFLICT (location_id, category_id, menu_item_id)
            DO UPDATE SET display_order = EXCLUDED.display_order, updated_at = NOW();
        END IF;
    END LOOP;
    
    RETURN json_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."reorder_category_items"("p_location_id" "uuid", "p_category_id" "uuid", "p_item_orders" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_menu_categories"("p_location_id" "uuid", "p_menu_id" "uuid", "p_category_orders" "jsonb") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_item RECORD;
BEGIN
    FOR v_item IN SELECT * FROM jsonb_to_recordset(p_category_orders) AS x(category_id UUID, display_order INTEGER)
    LOOP
        IF p_location_id IS NULL THEN
            -- Global update
            UPDATE menu_categories
            SET display_order = v_item.display_order,
                updated_at = NOW()
            WHERE menu_id = p_menu_id AND category_id = v_item.category_id;
        ELSE
            -- Location override update
            INSERT INTO location_menu_category_overrides (location_id, menu_id, category_id, display_order, updated_at)
            VALUES (p_location_id, p_menu_id, v_item.category_id, v_item.display_order, NOW())
            ON CONFLICT (location_id, menu_id, category_id)
            DO UPDATE SET display_order = EXCLUDED.display_order, updated_at = NOW();
        END IF;
    END LOOP;
    
    RETURN json_build_object('success', true);
END;
$$;


