CREATE OR REPLACE FUNCTION "public"."resend_waitlist_notification"("p_waitlist_id" "uuid", "p_notification_type" "text" DEFAULT 'sms'::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_entry    waitlist%ROWTYPE;
  v_location locations%ROWTYPE;
BEGIN
  SELECT * INTO v_entry FROM waitlist
  WHERE id = p_waitlist_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids())
    AND status IN ('waiting', 'notified', 'arrived');

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Entry not found');
  END IF;

  IF v_entry.notification_count >= 3 THEN
    RETURN json_build_object('success', false, 'error', 'max_notifications_reached');
  END IF;

  SELECT * INTO v_location FROM locations WHERE id = v_entry.location_id;

  RETURN json_build_object(
    'success', true,
    'phone', v_entry.phone,
    'party_name', v_entry.party_name,
    'store_name', COALESCE(v_location.name, 'Our Restaurant'),
    'notified_at', v_entry.notified_at,
    'notification_count', v_entry.notification_count,
    'last_notification_type', v_entry.last_notification_type,
    'notification_failures', v_entry.notification_failures,
    'action_required', 'send_sms',
    'message_template', 'Hi ' || v_entry.party_name || '! Your table at ' || COALESCE(v_location.name, 'Our Restaurant') || ' is ready. Please check in with the host within 10 minutes.'
  );
END;
$$;


ALTER FUNCTION "public"."resend_waitlist_notification"("p_waitlist_id" "uuid", "p_notification_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_castles_txn_counter"("p_terminal_id" "uuid", "p_batch_number" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE payment_terminals
  SET
    castles_txn_counter = 0,
    castles_batch_number = COALESCE(p_batch_number, castles_batch_number),
    castles_counter_updated_at = now()
  WHERE id = p_terminal_id;
END;
$$;


ALTER FUNCTION "public"."reset_castles_txn_counter"("p_terminal_id" "uuid", "p_batch_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_category_item_to_level"("p_menu_item_id" "uuid", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_menu_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_target_level" integer DEFAULT 1) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_deleted_levels TEXT[] := '{}';
BEGIN
    -- Reset Level 5 (location + menu + category)
    IF p_target_level < 5 AND p_location_id IS NOT NULL AND p_menu_id IS NOT NULL THEN
        DELETE FROM location_menu_item_overrides
        WHERE location_id = p_location_id 
          AND menu_id = p_menu_id 
          AND menu_item_id = p_menu_item_id
          AND (p_category_id IS NULL OR category_id = p_category_id);
        
        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_5_location_menu');
        END IF;
    END IF;
    
    -- Reset Level 4 (location + category)
    IF p_target_level < 4 AND p_location_id IS NOT NULL AND p_category_id IS NOT NULL THEN
        DELETE FROM location_category_item_overrides
        WHERE location_id = p_location_id 
          AND category_id = p_category_id 
          AND menu_item_id = p_menu_item_id;
        
        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_4_location_category');
        END IF;
    END IF;
    
    -- Reset Level 3 (category price) - only if merchant admin
    IF p_target_level < 3 AND p_location_id IS NULL AND p_category_id IS NOT NULL THEN
        UPDATE category_items
        SET custom_price = NULL, custom_cash_price = NULL, updated_at = NOW()
        WHERE category_id = p_category_id AND menu_item_id = p_menu_item_id;
        
        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_3_category');
        END IF;
    END IF;
    
    -- Reset Level 2 (location item)
    IF p_target_level < 2 AND p_location_id IS NOT NULL THEN
        DELETE FROM location_item_overrides
        WHERE location_id = p_location_id AND menu_item_id = p_menu_item_id;
        
        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_2_location_item');
        END IF;
    END IF;
    
    RETURN json_build_object(
        'success', true,
        'target_level', p_target_level,
        'deleted_overrides', v_deleted_levels
    );
END;
$$;


ALTER FUNCTION "public"."reset_category_item_to_level"("p_menu_item_id" "uuid", "p_category_id" "uuid", "p_menu_id" "uuid", "p_location_id" "uuid", "p_target_level" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_item_to_level"("p_menu_item_id" "uuid", "p_menu_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_target_level" integer DEFAULT 1) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_deleted_levels TEXT[] := '{}';
BEGIN
    -- Reset Level 4 (location + menu override)
    IF p_target_level < 4 AND p_location_id IS NOT NULL AND p_menu_id IS NOT NULL THEN
        DELETE FROM location_menu_item_overrides
        WHERE location_id = p_location_id 
          AND menu_id = p_menu_id 
          AND menu_item_id = p_menu_item_id;
        
        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_4_location_menu');
        END IF;
    END IF;
    
    -- Reset Level 3 (menu override) - only if merchant admin
    IF p_target_level < 3 AND p_location_id IS NULL AND p_menu_id IS NOT NULL THEN
        UPDATE menu_item_menus
        SET custom_price = NULL, custom_cash_price = NULL, updated_at = NOW()
        WHERE menu_id = p_menu_id AND menu_item_id = p_menu_item_id;
        
        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_3_menu');
        END IF;
    END IF;
    
    -- Reset Level 2 (location item override)
    IF p_target_level < 2 AND p_location_id IS NOT NULL THEN
        DELETE FROM location_item_overrides
        WHERE location_id = p_location_id AND menu_item_id = p_menu_item_id;
        
        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_2_location_item');
        END IF;
    END IF;
    
    RETURN json_build_object(
        'success', true,
        'target_level', p_target_level,
        'deleted_overrides', v_deleted_levels
    );
END;
$$;


ALTER FUNCTION "public"."reset_item_to_level"("p_menu_item_id" "uuid", "p_menu_id" "uuid", "p_location_id" "uuid", "p_target_level" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_item_prep_station"("p_item_id" "uuid", "p_location_id" "uuid", "p_category_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_station_name TEXT;
BEGIN
    -- 1. Check item-level override (location_item_overrides.prep_station_id)
    SELECT ps.name INTO v_station_name
    FROM location_item_overrides lio
    JOIN prep_stations ps ON ps.id = lio.prep_station_id
    WHERE lio.menu_item_id = p_item_id
      AND lio.location_id = p_location_id
      AND ps.is_active = true;

    IF v_station_name IS NOT NULL THEN
        RETURN v_station_name;
    END IF;

    -- 2. Check category-level default (if category provided)
    IF p_category_id IS NOT NULL THEN
        SELECT ps.name INTO v_station_name
        FROM location_category_prep_defaults lcpd
        JOIN prep_stations ps ON ps.id = lcpd.prep_station_id
        WHERE lcpd.category_id = p_category_id
          AND lcpd.location_id = p_location_id
          AND ps.is_active = true;

        IF v_station_name IS NOT NULL THEN
            RETURN v_station_name;
        END IF;
    END IF;

    -- 3. No assignment → return NULL (routes to Expo via catch-all)
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."resolve_item_prep_station"("p_item_id" "uuid", "p_location_id" "uuid", "p_category_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_item_prep_station"("p_item_id" "uuid", "p_location_id" "uuid", "p_category_id" "uuid") IS 'Resolves the effective prep station name for a menu item at a location. Resolution chain: Item override > Category default > NULL (Expo catch-all). Called by POS at order creation to populate order_items.prep_station.';



CREATE OR REPLACE FUNCTION "public"."route_items_to_kds"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_location_id UUID;
  v_order_type TEXT;
  v_display RECORD;
  v_matched BOOLEAN;
  v_any_routed BOOLEAN := false;
  v_rule RECORD;
  v_resolved_prep_station TEXT;
BEGIN
  -- Only process when sent_to_kitchen_at transitions from NULL to a value
  IF NEW.sent_to_kitchen_at IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.sent_to_kitchen_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Get the location_id and order_type from the parent order
  SELECT o.location_id, o.order_type
  INTO v_location_id, v_order_type
  FROM orders o
  WHERE o.id = NEW.order_id;

  IF v_location_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Resolve effective prep station via location overrides cascade
  v_resolved_prep_station := resolve_item_prep_station(NEW.menu_item_id, v_location_id, NEW.category_id);
  IF v_resolved_prep_station IS NULL THEN
    v_resolved_prep_station := NEW.prep_station;
  END IF;

  -- Iterate over all active KDS displays for this location
  FOR v_display IN
    SELECT d.id, d.routing_mode, d.show_all_items
    FROM kds_displays d
    WHERE d.location_id = v_location_id
      AND d.is_active = true
  LOOP
    v_matched := false;

    -- routing_mode = 'all' (expo/catch-all): always route
    IF v_display.routing_mode = 'all' THEN
      v_matched := true;
    ELSE
      -- Check routing rules for this display
      FOR v_rule IN
        SELECT r.rule_type, r.rule_value
        FROM kds_routing_rules r
        WHERE r.kds_display_id = v_display.id
      LOOP
        -- Match by prep_station (resolved from location overrides)
        IF v_rule.rule_type = 'prep_station' AND v_resolved_prep_station = v_rule.rule_value THEN
          v_matched := true;
          EXIT; -- One match is enough
        END IF;

        -- Match by category (name or ID)
        IF v_rule.rule_type = 'category' AND (
          NEW.category_name = v_rule.rule_value
          OR (NEW.category_id IS NOT NULL AND NEW.category_id::text = v_rule.rule_value)
        ) THEN
          v_matched := true;
          EXIT;
        END IF;

        -- Match by order_type
        IF v_rule.rule_type = 'order_type' AND v_order_type = v_rule.rule_value THEN
          v_matched := true;
          EXIT;
        END IF;
      END LOOP;
    END IF;

    -- Also match if display has show_all_items = true (expo display that gets copies of everything)
    IF NOT v_matched AND COALESCE(v_display.show_all_items, false) THEN
      v_matched := true;
    END IF;

    -- Insert into kds_item_status if matched (idempotent via ON CONFLICT)
    IF v_matched THEN
      INSERT INTO kds_item_status (kds_display_id, order_id, order_item_id, status)
      VALUES (v_display.id, NEW.order_id, NEW.id, 'pending')
      ON CONFLICT (kds_display_id, order_item_id) DO NOTHING;

      v_any_routed := true;
    END IF;
  END LOOP;

  -- Fallback: route unmatched items so nothing is lost
  -- Prefer show_all_items displays first; only blast to ALL if none exist
  IF NOT v_any_routed THEN
    FOR v_display IN
      SELECT d.id FROM kds_displays d
      WHERE d.location_id = v_location_id
        AND d.is_active = true
        AND COALESCE(d.show_all_items, false) = true
    LOOP
      INSERT INTO kds_item_status (kds_display_id, order_id, order_item_id, status)
      VALUES (v_display.id, NEW.order_id, NEW.id, 'pending')
      ON CONFLICT (kds_display_id, order_item_id) DO NOTHING;
      v_any_routed := true;
    END LOOP;

    -- Last resort: no show_all_items displays, send to every active display
    IF NOT v_any_routed THEN
      FOR v_display IN
        SELECT d.id FROM kds_displays d
        WHERE d.location_id = v_location_id AND d.is_active = true
      LOOP
        INSERT INTO kds_item_status (kds_display_id, order_id, order_item_id, status)
        VALUES (v_display.id, NEW.order_id, NEW.id, 'pending')
        ON CONFLICT (kds_display_id, order_item_id) DO NOTHING;
      END LOOP;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."route_items_to_kds"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."route_items_to_kds"() IS 'Routes order items to KDS displays based on routing rules when sent_to_kitchen_at is set. Supports prep_station, category, and order_type matching.';



CREATE OR REPLACE FUNCTION "public"."safe_jsonb_int"("p_value" "jsonb", "p_default" integer DEFAULT 1) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_text TEXT;
  v_int  INTEGER;
BEGIN
  IF p_value IS NULL OR p_value = 'null'::JSONB THEN
    RETURN p_default;
  END IF;

  v_text := p_value #>> '{}';   -- extract scalar as text (handles both string and number JSON types)

  IF v_text IS NULL OR v_text = '' THEN
    RETURN p_default;
  END IF;

  -- Only allow digits (optionally negative)
  IF v_text !~ '^-?[0-9]+$' THEN
    RETURN p_default;
  END IF;

  BEGIN
    v_int := v_text::INTEGER;
  EXCEPTION WHEN OTHERS THEN
    RETURN p_default;
  END;

  RETURN COALESCE(v_int, p_default);
END;
$_$;


ALTER FUNCTION "public"."safe_jsonb_int"("p_value" "jsonb", "p_default" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."safe_jsonb_int"("p_value" "jsonb", "p_default" integer) IS 'Safely extract an integer from a JSONB value. Returns p_default for any non-integer input (null, strings, floats, etc.).';



CREATE OR REPLACE FUNCTION "public"."seat_from_waitlist"("p_waitlist_id" "uuid", "p_table_ids" "uuid"[]) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_waitlist RECORD;
  v_result JSON;
BEGIN
  -- Get waitlist info
  SELECT * INTO v_waitlist
  FROM public.waitlist
  WHERE id = p_waitlist_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids())
    AND status IN ('waiting', 'notified', 'arrived');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Waitlist entry not found or not ready to seat';
  END IF;

  -- Seat the guests (reuse seat_guests function)
  SELECT public.seat_guests(
    p_table_ids := p_table_ids,
    p_party_size := v_waitlist.party_size,
    p_guest_name := v_waitlist.party_name,
    p_guest_phone := v_waitlist.phone,
    p_guest_notes := v_waitlist.notes,
    p_waitlist_id := p_waitlist_id,
    p_create_order := TRUE
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."seat_from_waitlist"("p_waitlist_id" "uuid", "p_table_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seat_guests"("p_table_ids" "uuid"[], "p_party_size" integer, "p_guest_name" "text" DEFAULT NULL::"text", "p_guest_phone" "text" DEFAULT NULL::"text", "p_guest_notes" "text" DEFAULT NULL::"text", "p_reservation_id" "uuid" DEFAULT NULL::"uuid", "p_waitlist_id" "uuid" DEFAULT NULL::"uuid", "p_create_order" boolean DEFAULT false, "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_merchant_id UUID;
  v_location_id UUID;
  v_session_id UUID;
  v_order_id UUID;
  v_table_id UUID;
  v_is_first BOOLEAN := TRUE;
  v_server_staff_id UUID;
BEGIN
  -- Get merchant and location from first table
  SELECT fpo.merchant_id, fpo.location_id
  INTO v_merchant_id, v_location_id
  FROM public.floor_plan_objects fpo
  WHERE fpo.id = p_table_ids[1]
    AND fpo.merchant_id = user_merchant_id()
    AND fpo.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Table not found or access denied';
  END IF;

  -- Check if any table is already occupied
  IF EXISTS (
    SELECT 1 FROM public.table_session_tables tst
    JOIN public.table_sessions ts ON ts.id = tst.session_id
    WHERE tst.table_id = ANY(p_table_ids) AND ts.is_active = TRUE
  ) THEN
    RAISE EXCEPTION 'One or more tables are already occupied';
  END IF;

  -- Use provided staff_id OR fall back to JWT-based lookup
  v_server_staff_id := COALESCE(p_staff_id, user_staff_profile_id());

  -- Create session
  INSERT INTO public.table_sessions (
    merchant_id, location_id,
    party_size, guest_name, guest_phone, guest_notes,
    reservation_id, waitlist_id,
    server_staff_id, server_user_id,
    status, seated_at
  ) VALUES (
    v_merchant_id, v_location_id,
    p_party_size, p_guest_name, p_guest_phone, p_guest_notes,
    p_reservation_id, p_waitlist_id,
    v_server_staff_id, get_my_claim('sub'),
    'seated', NOW()
  )
  RETURNING id INTO v_session_id;

  -- Link tables to session
  FOREACH v_table_id IN ARRAY p_table_ids
  LOOP
    INSERT INTO public.table_session_tables (session_id, table_id, is_primary, seated_position)
    VALUES (v_session_id, v_table_id, v_is_first, 
            ARRAY_POSITION(p_table_ids, v_table_id) - 1);
    v_is_first := FALSE;
  END LOOP;

  -- Create initial event
  INSERT INTO public.table_session_events (session_id, event_type, triggered_by_staff_id, triggered_by_user_id)
  VALUES (v_session_id, 'seated', v_server_staff_id, get_my_claim('sub'));

  -- Update reservation if provided
  IF p_reservation_id IS NOT NULL THEN
    UPDATE public.reservations
    SET status = 'seated', seated_at = NOW(), seated_session_id = v_session_id
    WHERE id = p_reservation_id;
  END IF;

  -- Update waitlist if provided
  IF p_waitlist_id IS NOT NULL THEN
    UPDATE public.waitlist
    SET status = 'seated', seated_at = NOW(), seated_session_id = v_session_id,
        actual_wait_minutes = EXTRACT(EPOCH FROM (NOW() - created_at)) / 60
    WHERE id = p_waitlist_id;
  END IF;

  -- Create order if requested
  IF p_create_order THEN
    SELECT (public.create_order(
      p_merchant_id := v_merchant_id,
      p_location_id := v_location_id,
      p_order_type := 'dine_in',
      p_table_number := (SELECT name FROM public.floor_plan_objects WHERE id = p_table_ids[1]),
      p_customer_name := p_guest_name,
      p_created_by_staff_id := v_server_staff_id
    ))->>'order_id' INTO v_order_id;

    -- Link order to session
    UPDATE public.table_sessions
    SET order_id = v_order_id::UUID
    WHERE id = v_session_id;
  END IF;

  RETURN json_build_object(
    'success', true,
    'session_id', v_session_id,
    'order_id', v_order_id,
    'table_ids', p_table_ids,
    'party_size', p_party_size,
    'guest_name', p_guest_name
  );
END;
$$;


ALTER FUNCTION "public"."seat_guests"("p_table_ids" "uuid"[], "p_party_size" integer, "p_guest_name" "text", "p_guest_phone" "text", "p_guest_notes" "text", "p_reservation_id" "uuid", "p_waitlist_id" "uuid", "p_create_order" boolean, "p_staff_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."seat_guests"("p_table_ids" "uuid"[], "p_party_size" integer, "p_guest_name" "text", "p_guest_phone" "text", "p_guest_notes" "text", "p_reservation_id" "uuid", "p_waitlist_id" "uuid", "p_create_order" boolean, "p_staff_id" "uuid") IS 'Seats guests at specified tables, creates session with event logging, and optionally creates an order with bidirectional session_id link. Includes security checks and supports reservations/waitlist.';



CREATE OR REPLACE FUNCTION "public"."seat_guests_v2"("p_table_ids" "uuid"[], "p_party_size" integer, "p_guest_name" "text" DEFAULT NULL::"text", "p_guest_phone" "text" DEFAULT NULL::"text", "p_guest_notes" "text" DEFAULT NULL::"text", "p_reservation_id" "uuid" DEFAULT NULL::"uuid", "p_waitlist_id" "uuid" DEFAULT NULL::"uuid", "p_create_order" boolean DEFAULT false, "p_station_id" "uuid" DEFAULT NULL::"uuid", "p_device_id" "text" DEFAULT NULL::"text", "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_merchant_id UUID;
  v_location_id UUID;
  v_session_id UUID;
  v_order_id UUID;
  v_table_id UUID;
  v_is_first BOOLEAN := TRUE;
  v_server_staff_id UUID;
BEGIN
  -- Get merchant and location from first table
  SELECT fpo.merchant_id, fpo.location_id
  INTO v_merchant_id, v_location_id
  FROM public.floor_plan_objects fpo
  WHERE fpo.id = p_table_ids[1]
    AND fpo.merchant_id = user_merchant_id()
    AND fpo.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Table not found or access denied';
  END IF;

  -- Check if any table is already occupied
  IF EXISTS (
    SELECT 1 FROM public.table_session_tables tst
    JOIN public.table_sessions ts ON ts.id = tst.session_id
    WHERE tst.table_id = ANY(p_table_ids) AND ts.is_active = TRUE
  ) THEN
    RAISE EXCEPTION 'One or more tables are already occupied';
  END IF;

  -- Use provided staff_id OR fall back to JWT-based lookup
  v_server_staff_id := COALESCE(p_staff_id, user_staff_profile_id());

  -- Create session
  INSERT INTO public.table_sessions (
    merchant_id, location_id,
    party_size, guest_name, guest_phone, guest_notes,
    reservation_id, waitlist_id,
    server_staff_id, server_user_id,
    status, seated_at
  ) VALUES (
    v_merchant_id, v_location_id,
    p_party_size, p_guest_name, p_guest_phone, p_guest_notes,
    p_reservation_id, p_waitlist_id,
    v_server_staff_id, get_my_claim('sub'),
    'seated', NOW()
  )
  RETURNING id INTO v_session_id;

  -- Link tables to session
  FOREACH v_table_id IN ARRAY p_table_ids
  LOOP
    INSERT INTO public.table_session_tables (session_id, table_id, is_primary, seated_position)
    VALUES (v_session_id, v_table_id, v_is_first,
            ARRAY_POSITION(p_table_ids, v_table_id) - 1);
    v_is_first := FALSE;
  END LOOP;

  -- Create initial event
  INSERT INTO public.table_session_events (session_id, event_type, triggered_by_staff_id, triggered_by_user_id)
  VALUES (v_session_id, 'seated', v_server_staff_id, get_my_claim('sub'));

  -- Update reservation if provided
  IF p_reservation_id IS NOT NULL THEN
    UPDATE public.reservations
    SET status = 'seated', seated_at = NOW(), seated_session_id = v_session_id
    WHERE id = p_reservation_id;
  END IF;

  -- Update waitlist if provided
  IF p_waitlist_id IS NOT NULL THEN
    UPDATE public.waitlist
    SET status = 'seated', seated_at = NOW(), seated_session_id = v_session_id,
        actual_wait_minutes = EXTRACT(EPOCH FROM (NOW() - created_at)) / 60
    WHERE id = p_waitlist_id;
  END IF;

  -- Create order if requested
  IF p_create_order THEN
    SELECT (public.create_order_v2(
      p_merchant_id := v_merchant_id,
      p_location_id := v_location_id,
      p_order_type := 'dine_in',
      p_table_number := (SELECT name FROM public.floor_plan_objects WHERE id = p_table_ids[1]),
      p_customer_name := p_guest_name,
      p_customer_phone := p_guest_phone,
      p_special_instructions := p_guest_notes,
      p_created_by_staff_id := v_server_staff_id,
      p_station_id := p_station_id,
      p_device_id := p_device_id
    ))->>'order_id' INTO v_order_id;

    -- ===================================================================
    -- NEW: Set bidirectional link between order and session (ATOMIC)
    -- ===================================================================
    IF v_order_id IS NOT NULL THEN
      -- Update order to point to session
      UPDATE public.orders
      SET session_id = v_session_id,
          updated_at = NOW()
      WHERE id = v_order_id::UUID;

      -- Update session to point to order (existing logic kept)
      UPDATE public.table_sessions
      SET order_id = v_order_id::UUID,
          updated_at = NOW()
      WHERE id = v_session_id;
    END IF;
  END IF;

  -- Return response (matching original format)
  RETURN json_build_object(
    'success', true,
    'session_id', v_session_id,
    'order_id', v_order_id,
    'table_ids', p_table_ids,
    'party_size', p_party_size,
    'guest_name', p_guest_name
  );
END;
$$;


ALTER FUNCTION "public"."seat_guests_v2"("p_table_ids" "uuid"[], "p_party_size" integer, "p_guest_name" "text", "p_guest_phone" "text", "p_guest_notes" "text", "p_reservation_id" "uuid", "p_waitlist_id" "uuid", "p_create_order" boolean, "p_station_id" "uuid", "p_device_id" "text", "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seat_guests_v3"("p_table_id" "uuid", "p_merchant_id" "uuid", "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_server_staff_id" "uuid" DEFAULT NULL::"uuid", "p_party_size" integer DEFAULT 1, "p_create_order" boolean DEFAULT true, "p_guest_name" "text" DEFAULT NULL::"text", "p_guest_phone" "text" DEFAULT NULL::"text", "p_reservation_id" "uuid" DEFAULT NULL::"uuid", "p_waitlist_id" "uuid" DEFAULT NULL::"uuid", "p_device_id" "text" DEFAULT NULL::"text", "p_station_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_table              RECORD;
  v_session_id         UUID;
  v_order_id           UUID;
  v_order_number       TEXT;
  v_display_number     TEXT;
  v_session_number     TEXT;
  v_location_id        UUID;
  v_merchant_id        UUID;
  v_daily_count        INT;
  v_user_id            TEXT;
  v_verified_staff_id  UUID;   -- Validated POS staff (created_by)
  v_verified_server_id UUID;   -- Validated assigned server
BEGIN
  -- ──────────────────────────────────────────────────────────────
  -- 1. AUTH
  -- ──────────────────────────────────────────────────────────────

  v_user_id := get_my_claim('sub');

  IF p_merchant_id != user_merchant_id() THEN
    RAISE EXCEPTION 'Access denied: Invalid merchant_id';
  END IF;

  -- ──────────────────────────────────────────────────────────────
  -- 2. Lock table + extract location
  -- ──────────────────────────────────────────────────────────────

  SELECT fpo.id, fpo.name, fpo.location_id, fpo.merchant_id, fpo.capacity
  INTO v_table
  FROM floor_plan_objects fpo
  WHERE fpo.id = p_table_id
    AND fpo.is_active = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Table not found or inactive'
    );
  END IF;

  v_location_id := v_table.location_id;
  v_merchant_id := v_table.merchant_id;

  IF NOT (v_location_id = ANY(user_location_ids())) THEN
    RAISE EXCEPTION 'Access denied: User does not have access to location';
  END IF;

  -- ──────────────────────────────────────────────────────────────
  -- 3. Check no active session exists
  -- ──────────────────────────────────────────────────────────────

  IF EXISTS (
    SELECT 1
    FROM table_session_tables tst
    JOIN table_sessions ts ON ts.id = tst.session_id
    WHERE tst.table_id = p_table_id
      AND tst.is_active = true
      AND ts.is_active = true
      AND ts.status NOT IN ('cleaning')
  ) THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Table already has an active session'
    );
  END IF;

  -- ──────────────────────────────────────────────────────────────
  -- 4. Validate BOTH staff IDs independently
  -- ──────────────────────────────────────────────────────────────

  -- POS logged-in staff (who performed the action)
  v_verified_staff_id := p_staff_id;
  IF v_verified_staff_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.staff_profiles WHERE id = v_verified_staff_id) THEN
      v_verified_staff_id := NULL;
    END IF;
  END IF;

  -- Assigned server (who is responsible for the table)
  v_verified_server_id := p_server_staff_id;
  IF v_verified_server_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.staff_profiles WHERE id = v_verified_server_id) THEN
      v_verified_server_id := NULL;
    END IF;
  END IF;

  -- ──────────────────────────────────────────────────────────────
  -- 5. Generate session number
  -- ──────────────────────────────────────────────────────────────

  SELECT COUNT(*) + 1
  INTO v_daily_count
  FROM table_sessions
  WHERE location_id = v_location_id
    AND created_at::date = CURRENT_DATE;

  v_session_number := v_table.name || '-' || LPAD(v_daily_count::TEXT, 3, '0');

  -- ──────────────────────────────────────────────────────────────
  -- 6. Create session
  --    server_staff_id = the assigned server (responsible for table)
  -- ──────────────────────────────────────────────────────────────

  INSERT INTO table_sessions (
    location_id,
    merchant_id,
    party_size,
    status,
    server_staff_id,
    guest_name,
    guest_phone,
    reservation_id,
    waitlist_id,
    session_number,
    seated_at,
    is_active,
    current_course,
    working_course,
    course_pacing
  ) VALUES (
    v_location_id,
    v_merchant_id,
    p_party_size,
    'seated',
    v_verified_server_id,       -- Assigned server owns the table
    p_guest_name,
    p_guest_phone,
    p_reservation_id,
    p_waitlist_id,
    v_session_number,
    NOW(),
    true,
    0,
    1,
    'normal'
  )
  RETURNING id INTO v_session_id;

  -- ──────────────────────────────────────────────────────────────
  -- 7. Link table to session
  -- ──────────────────────────────────────────────────────────────

  INSERT INTO table_session_tables (session_id, table_id, is_primary, is_active)
  VALUES (v_session_id, p_table_id, true, true);

  -- ──────────────────────────────────────────────────────────────
  -- 8. Create order
  --    created_by_staff_id  = POS staff who tapped "seat" (the actor)
  --    assigned_server_id   = server responsible for the table
  -- ──────────────────────────────────────────────────────────────

  IF p_create_order THEN
    v_order_number := public.generate_order_number(v_location_id, p_station_id);
    v_display_number := CASE
      WHEN SPLIT_PART(v_order_number, '-', 4) <> ''
      THEN '#' || SPLIT_PART(v_order_number, '-', 3) || '-' || SPLIT_PART(v_order_number, '-', 4)
      ELSE '#' || SPLIT_PART(v_order_number, '-', 3)
    END;
    INSERT INTO public.orders (
      merchant_id,
      location_id,
      order_number,
      display_number,
      order_type,
      status,
      table_number,
      session_id,
      device_id,
      created_by_staff_id,
      created_by_user_id,
      assigned_server_id,
      station_id,
      created_at,
      updated_at
    ) VALUES (
      v_merchant_id,
      v_location_id,
      v_order_number,
      v_display_number,
      'dine_in',
      'draft',
      v_table.name,
      v_session_id,
      p_device_id,
      v_verified_staff_id,        -- POS staff who performed the action
      v_user_id,                  -- Clerk user from JWT
      v_verified_server_id,       -- Server assigned to the table
      p_station_id,
      NOW(),
      NOW()
    )
    RETURNING id INTO v_order_id;

    UPDATE table_sessions
    SET order_id = v_order_id
    WHERE id = v_session_id;

    -- Audit log
    INSERT INTO public.audit_logs (
      actor_user_id,
      organization_id,
      action,
      action_category,
      resource_type,
      resource_name,
      metadata,
      status
    ) VALUES (
      v_user_id,
      (SELECT clerk_org_id FROM public.merchants WHERE id = v_merchant_id),
      'order_created',
      'order_management',
      'order',
      v_order_number,
      jsonb_build_object(
        'order_id', v_order_id,
        'order_type', 'dine_in',
        'table_number', v_table.name,
        'location_id', v_location_id,
        'station_id', p_station_id,
        'session_id', v_session_id,
        'created_by_staff_id', v_verified_staff_id,
        'assigned_server_id', v_verified_server_id,
        'source', 'seat_guests_v5'
      ),
      'success'
    );
  END IF;

  -- ──────────────────────────────────────────────────────────────
  -- 9. Log seated event
  --    triggered_by = POS staff who performed the action
  -- ──────────────────────────────────────────────────────────────

  INSERT INTO table_session_events (
    session_id,
    event_type,
    triggered_by_staff_id,
    triggered_by_user_id,
    event_data
  ) VALUES (
    v_session_id,
    'seated',
    v_verified_staff_id,          -- Who actually did it
    v_user_id,
    jsonb_build_object(
      'party_size', p_party_size,
      'table_name', v_table.name,
      'guest_name', p_guest_name,
      'order_number', v_order_number,
      'assigned_server_id', v_verified_server_id
    )
  );

  -- ──────────────────────────────────────────────────────────────
  -- 10. Update waitlist if linked
  -- ──────────────────────────────────────────────────────────────

  IF p_waitlist_id IS NOT NULL THEN
    UPDATE waitlist
    SET status = 'seated',
        seated_at = NOW(),
        seated_session_id = v_session_id,
        actual_wait_minutes = EXTRACT(EPOCH FROM (NOW() - created_at))::INT / 60
    WHERE id = p_waitlist_id
      AND status IN ('waiting', 'notified', 'arrived');
  END IF;

  -- ──────────────────────────────────────────────────────────────
  -- 11. Update reservation if linked
  -- ──────────────────────────────────────────────────────────────

  IF p_reservation_id IS NOT NULL THEN
    UPDATE reservations
    SET status = 'seated',
        seated_at = NOW(),
        seated_session_id = v_session_id
    WHERE id = p_reservation_id
      AND status IN ('confirmed', 'reminded', 'arrived');
  END IF;

  -- ──────────────────────────────────────────────────────────────
  -- 12. Return
  -- ──────────────────────────────────────────────────────────────

  RETURN json_build_object(
    'success',        true,
    'session_id',     v_session_id,
    'order_id',       v_order_id,
    'order_number',   v_order_number,
    'display_number', v_display_number,
    'session_number', v_session_number,
    'table_name',     v_table.name,
    'status',         'draft'
  );
END;$$;


ALTER FUNCTION "public"."seat_guests_v3"("p_table_id" "uuid", "p_merchant_id" "uuid", "p_staff_id" "uuid", "p_server_staff_id" "uuid", "p_party_size" integer, "p_create_order" boolean, "p_guest_name" "text", "p_guest_phone" "text", "p_reservation_id" "uuid", "p_waitlist_id" "uuid", "p_device_id" "text", "p_station_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seat_reservation"("p_reservation_id" "uuid", "p_table_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_reservation RECORD;
  v_table_ids UUID[];
  v_result JSON;
BEGIN
  -- Get reservation info
  SELECT * INTO v_reservation
  FROM public.reservations
  WHERE id = p_reservation_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids())
    AND status IN ('pending', 'confirmed', 'reminded', 'arrived');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Reservation not found or not ready to seat';
  END IF;

  -- Use provided tables or assigned tables
  v_table_ids := COALESCE(p_table_ids, v_reservation.assigned_table_ids);

  IF v_table_ids IS NULL OR array_length(v_table_ids, 1) = 0 THEN
    RAISE EXCEPTION 'No tables specified for seating';
  END IF;

  -- Seat the guests
  SELECT public.seat_guests(
    p_table_ids := v_table_ids,
    p_party_size := v_reservation.party_size,
    p_guest_name := v_reservation.party_name,
    p_guest_phone := v_reservation.phone,
    p_guest_notes := v_reservation.notes || COALESCE(' | ' || v_reservation.special_requests, ''),
    p_reservation_id := p_reservation_id,
    p_create_order := TRUE
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."seat_reservation"("p_reservation_id" "uuid", "p_table_ids" "uuid"[]) OWNER TO "postgres";


