CREATE OR REPLACE FUNCTION "public"."set_location_ein_last_four"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_digits text;
BEGIN
  -- If app provides a plain EIN pattern, derive last-4 automatically.
  -- If app stores encrypted/tokenized value in ein, this will not overwrite
  -- an explicit ein_last_four set by the app.
  IF NEW.ein IS NOT NULL THEN
    v_digits := regexp_replace(NEW.ein, '[^0-9]', '', 'g');
    IF length(v_digits) = 9 THEN
      NEW.ein_last_four := right(v_digits, 4);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_location_ein_last_four"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_location_stock"("p_inventory_item_id" "uuid", "p_location_id" "uuid", "p_quantity" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    INSERT INTO location_inventory_stock (location_id, inventory_item_id, stock_quantity, updated_at)
    VALUES (p_location_id, p_inventory_item_id, GREATEST(0, p_quantity), now())
    ON CONFLICT (location_id, inventory_item_id)
    DO UPDATE SET
        stock_quantity = GREATEST(0, p_quantity),
        updated_at     = now();

    -- Sync legacy aggregate on inventory_items
    UPDATE inventory_items
    SET
        current_stock = (
            SELECT COALESCE(SUM(stock_quantity), 0)
            FROM location_inventory_stock
            WHERE inventory_item_id = p_inventory_item_id
        ),
        updated_at = now()
    WHERE id = p_inventory_item_id;
END;
$$;


ALTER FUNCTION "public"."set_location_stock"("p_inventory_item_id" "uuid", "p_location_id" "uuid", "p_quantity" numeric) OWNER TO "postgres";


