CREATE OR REPLACE FUNCTION "public"."table_session_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
begin
  perform realtime.broadcast_changes(
    'floor-plan-' || coalesce(NEW.location_id, OLD.location_id) ::text,       -- topic - the topic to which you're broadcasting where you can use the topic id to build the topic name
    TG_OP,                                             -- event - the event that triggered the function
    TG_OP,                                             -- operation - the operation that triggered the function
    TG_TABLE_NAME,                                     -- table - the table that caused the trigger
    TG_TABLE_SCHEMA,                                   -- schema - the schema of the table that caused the trigger
    NEW,                                               -- new record - the record after the change
    OLD                                                -- old record - the record before the change
  );
  return null;
end;
$$;


ALTER FUNCTION "public"."table_session_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_priority_order_items"("p_order_item_ids" "uuid"[], "p_is_prioritized" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_id UUID;
BEGIN
  -- Update the priority flag on specified items
  UPDATE order_items
  SET is_prioritized = p_is_prioritized,
      updated_at = NOW()
  WHERE id = ANY(p_order_item_ids);

  -- Touch parent orders to trigger broadcast (bumps sync_version)
  FOR v_order_id IN
    SELECT DISTINCT order_id
    FROM order_items
    WHERE id = ANY(p_order_item_ids)
  LOOP
    UPDATE orders
    SET updated_at = NOW(),
        sync_version = COALESCE(sync_version, 0) + 1
    WHERE id = v_order_id;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."toggle_priority_order_items"("p_order_item_ids" "uuid"[], "p_is_prioritized" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_rush_order_items"("p_order_item_ids" "uuid"[], "p_rush" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_id UUID;
BEGIN
  -- Set rush flag on all specified items
  UPDATE order_items
  SET
    rush = p_rush,
    updated_at = NOW()
  WHERE id = ANY(p_order_item_ids);

  -- Touch parent order(s) to trigger broadcast
  FOR v_order_id IN
    SELECT DISTINCT order_id FROM order_items WHERE id = ANY(p_order_item_ids)
  LOOP
    UPDATE orders
    SET
      updated_at = NOW(),
      sync_version = COALESCE(sync_version, 0) + 1
    WHERE id = v_order_id;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."toggle_rush_order_items"("p_order_item_ids" "uuid"[], "p_rush" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_table_session"("p_session_id" "uuid", "p_new_table_ids" "uuid"[], "p_reason" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_old_table_ids UUID[];
  v_table_id UUID;
  v_is_first BOOLEAN := TRUE;
BEGIN
  -- Verify permission
  -- IF NOT has_any_permission(ARRAY['location.tables.manage', 'merchant.orders.manage']) THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Verify session exists and is active
  IF NOT EXISTS (
    SELECT 1 FROM public.table_sessions
    WHERE id = p_session_id
      AND is_active = TRUE
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids())
  ) THEN
    RAISE EXCEPTION 'Session not found or not active';
  END IF;

  -- Check new tables are available
  IF EXISTS (
    SELECT 1 FROM public.table_session_tables tst
    JOIN public.table_sessions ts ON ts.id = tst.session_id
    WHERE tst.table_id = ANY(p_new_table_ids) 
      AND ts.is_active = TRUE
      AND ts.id != p_session_id
  ) THEN
    RAISE EXCEPTION 'One or more target tables are occupied';
  END IF;

  -- Get old table IDs for reference
  SELECT ARRAY_AGG(table_id) INTO v_old_table_ids
  FROM public.table_session_tables
  WHERE session_id = p_session_id;

  -- Remove old table links
  DELETE FROM public.table_session_tables
  WHERE session_id = p_session_id;

  -- Add new table links
  FOREACH v_table_id IN ARRAY p_new_table_ids
  LOOP
    INSERT INTO public.table_session_tables (session_id, table_id, is_primary, seated_position)
    VALUES (p_session_id, v_table_id, v_is_first, 
            ARRAY_POSITION(p_new_table_ids, v_table_id) - 1);
    v_is_first := FALSE;
  END LOOP;

  -- Update order table number if linked
  UPDATE public.orders o
  SET table_number = (SELECT name FROM public.floor_plan_objects WHERE id = p_new_table_ids[1])
  FROM public.table_sessions ts
  WHERE ts.id = p_session_id AND o.id = ts.order_id;

  -- Record transfer event
  INSERT INTO public.table_session_events (
    session_id, event_type, notes, event_data,
    triggered_by_staff_id, triggered_by_user_id
  ) VALUES (
    p_session_id, 'custom', p_reason,
    jsonb_build_object(
      'action', 'table_transfer',
      'from_tables', v_old_table_ids,
      'to_tables', p_new_table_ids
    ),
    user_staff_profile_id(), get_my_claim('sub')
  );

  RETURN json_build_object(
    'success', true,
    'session_id', p_session_id,
    'from_table_ids', v_old_table_ids,
    'to_table_ids', p_new_table_ids
  );
END;
$$;


ALTER FUNCTION "public"."transfer_table_session"("p_session_id" "uuid", "p_new_table_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


