CREATE OR REPLACE FUNCTION "public"."unmerge_table_from_session"("p_session_id" "uuid", "p_table_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_remaining_count INTEGER;
BEGIN
  -- Verify session
  IF NOT EXISTS (
    SELECT 1 FROM public.table_sessions
    WHERE id = p_session_id AND is_active = TRUE
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids())
  ) THEN
    RAISE EXCEPTION 'Session not found';
  END IF;

  -- Can't remove the only table
  SELECT COUNT(*) INTO v_remaining_count
  FROM public.table_session_tables
  WHERE session_id = p_session_id;

  IF v_remaining_count <= 1 THEN
    RAISE EXCEPTION 'Cannot unmerge the only table in a session';
  END IF;

  -- Remove table
  DELETE FROM public.table_session_tables
  WHERE session_id = p_session_id AND table_id = p_table_id;

  -- If primary was removed, set new primary
  IF NOT EXISTS (
    SELECT 1 FROM public.table_session_tables
    WHERE session_id = p_session_id AND is_primary = TRUE
  ) THEN
    -- Choose the row with the lowest seated_position and set it as primary.
    -- Use an UPDATE ... FROM (subselect ORDER BY ... LIMIT 1) to avoid ORDER BY/LIMIT inside UPDATE.
    UPDATE public.table_session_tables t
    SET is_primary = TRUE
    FROM (
      SELECT id
      FROM public.table_session_tables
      WHERE session_id = p_session_id
      ORDER BY seated_position
      LIMIT 1
    ) s
    WHERE t.id = s.id;
  END IF;

  RETURN json_build_object(
    'success', true,
    'session_id', p_session_id,
    'unmerged_table_id', p_table_id
  );
END;
$$;


ALTER FUNCTION "public"."unmerge_table_from_session"("p_session_id" "uuid", "p_table_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_admin_merchant_access_updated_at"() RETURNS "trigger"
