CREATE OR REPLACE FUNCTION "public"."update_customer_metrics_on_order"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_customer_id UUID;
  v_order_total NUMERIC;
  v_order_tip NUMERIC;
  v_order_subtotal NUMERIC;
BEGIN
  -- Only update when order is completed or ready
  IF NEW.status IN ('completed', 'ready') AND (OLD.status IS NULL OR OLD.status NOT IN ('completed', 'ready')) THEN
    
    v_customer_id := NEW.customer_id;
    
    -- Skip if no customer assigned
    IF v_customer_id IS NULL THEN
      RETURN NEW;
    END IF;
    
    v_order_total := COALESCE(NEW.total_amount, 0);
    v_order_tip := COALESCE(NEW.tip_amount, 0);
    v_order_subtotal := COALESCE(NEW.subtotal, 0);
    
    -- Update customer metrics
    UPDATE public.customers
    SET
      last_order_date = NEW.completed_at,
      last_visit = NEW.completed_at,
      total_orders = total_orders + 1,
      visits = visits + 1,
      lifetime_spend = lifetime_spend + v_order_total,
      avg_spend = (lifetime_spend + v_order_total) / (total_orders + 1),
      avg_tip_percent = CASE 
        WHEN v_order_subtotal > 0 THEN
          ((COALESCE(avg_tip_percent, 0) * total_orders) + (v_order_tip / v_order_subtotal * 100)) / (total_orders + 1)
        ELSE 
          avg_tip_percent
      END,
      updated_at = NOW()
    WHERE id = v_customer_id;
    
    -- Log activity
    INSERT INTO public.customer_activities (
      customer_id,
      merchant_id,
      activity_type,
      related_order_id,
      metadata
    ) VALUES (
      v_customer_id,
      NEW.merchant_id,
      'order',
      NEW.id,
      jsonb_build_object(
        'total', v_order_total,
        'tip', v_order_tip,
        'channel', NEW.order_type,
        'items_count', (SELECT COUNT(*) FROM public.order_items WHERE order_id = NEW.id)
      )
    );
    
  END IF;
  
  -- Handle refunds
  IF NEW.status = 'refunded' AND (OLD.status IS NULL OR OLD.status != 'refunded') THEN
    v_customer_id := NEW.customer_id;
    
    IF v_customer_id IS NOT NULL THEN
      v_order_total := COALESCE(NEW.total_amount, 0);
      
      -- Subtract from lifetime spend
      UPDATE public.customers
      SET
        lifetime_spend = GREATEST(lifetime_spend - v_order_total, 0),
        total_orders = GREATEST(total_orders - 1, 0),
        avg_spend = CASE 
          WHEN (total_orders - 1) > 0 THEN (lifetime_spend - v_order_total) / (total_orders - 1)
          ELSE 0
        END,
        updated_at = NOW()
      WHERE id = v_customer_id;
      
      -- Log refund activity
      INSERT INTO public.customer_activities (
        customer_id,
        merchant_id,
        activity_type,
        related_order_id,
        metadata
      ) VALUES (
        v_customer_id,
        NEW.merchant_id,
        'refund',
        NEW.id,
        jsonb_build_object('amount', v_order_total)
      );
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_customer_metrics_on_order"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_floor_plan_object_position"("p_object_id" "uuid", "p_x" numeric, "p_y" numeric, "p_rotation" numeric DEFAULT NULL::numeric) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$BEGIN
  UPDATE public.floor_plan_objects
  SET 
    x = p_x,
    y = p_y,
    rotation = COALESCE(p_rotation, rotation),
    updated_at = NOW()
  WHERE id = p_object_id
    AND merchant_id = user_merchant_id();
    -- AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Object not found or access denied';
  END IF;

  RETURN json_build_object(
    'success', true,
    'object_id', p_object_id,
    'x', p_x,
    'y', p_y,
    'rotation', p_rotation
  );
END;$$;


ALTER FUNCTION "public"."update_floor_plan_object_position"("p_object_id" "uuid", "p_x" numeric, "p_y" numeric, "p_rotation" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_floor_plan_objects_batch"("p_updates" "jsonb") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_update JSONB;
  v_updated_count INTEGER := 0;
BEGIN
  FOR v_update IN SELECT * FROM jsonb_array_elements(p_updates)
  LOOP
    UPDATE public.floor_plan_objects
    SET 
      x = (v_update->>'x')::NUMERIC,
      y = (v_update->>'y')::NUMERIC,
      rotation = COALESCE((v_update->>'rotation')::NUMERIC, rotation),
      updated_at = NOW()
    WHERE id = (v_update->>'id')::UUID
      AND merchant_id = user_merchant_id();
      -- AND location_id = ANY(user_location_ids());
    RAISE LOG 'v_update %', v_update;

    IF FOUND THEN
      v_updated_count := v_updated_count + 1;
    END IF;
  END LOOP;

  RETURN json_build_object(
    'success', true,
    'updated_count', v_updated_count
  );
END;$$;


ALTER FUNCTION "public"."update_floor_plan_objects_batch"("p_updates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_inventory_on_po_received"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- When PO status changes to 'received', update inventory stock
  IF NEW.status = 'received' AND OLD.status != 'received' THEN
    UPDATE public.inventory_items ii
    SET
      current_stock = ii.current_stock + poi.quantity_received,
      updated_at = NOW()
    FROM public.purchase_order_items poi
    WHERE poi.purchase_order_id = NEW.id
      AND ii.id = poi.inventory_item_id
      AND ii.stock_mode = 'stock_tracking';

    -- Set received_at timestamp
    NEW.received_at := NOW();
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_inventory_on_po_received"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_location_pos_config"("p_location_id" "uuid", "p_namespace" "text", "p_config" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_existing JSONB;
  v_merged JSONB;
  v_result JSONB;
BEGIN
  -- Get existing config for this namespace (or empty object)
  SELECT COALESCE(pos_config->p_namespace, '{}'::jsonb)
  INTO v_existing
  FROM locations
  WHERE id = p_location_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Location not found: %', p_location_id;
  END IF;

  -- Deep merge: existing namespace values || new values (new wins on conflict)
  v_merged := v_existing || p_config;

  -- Atomic update with metadata
  UPDATE locations
  SET pos_config = jsonb_set(
    jsonb_set(
      jsonb_set(pos_config, ARRAY[p_namespace], v_merged),
      '{_updated_at}',
      to_jsonb(now()::text)
    ),
    '{_version}',
    to_jsonb(COALESCE((pos_config->>'_version')::int, 0) + 1)
  ),
  updated_at = now()
  WHERE id = p_location_id
  RETURNING pos_config INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."update_location_pos_config"("p_location_id" "uuid", "p_namespace" "text", "p_config" "jsonb") OWNER TO "postgres";


