CREATE OR REPLACE FUNCTION "public"."update_order_item"("p_order_item_id" "uuid", "p_quantity" integer DEFAULT NULL::integer, "p_special_instructions" "text" DEFAULT NULL::"text", "p_prep_station" "text" DEFAULT NULL::"text", "p_course_number" integer DEFAULT NULL::integer, "p_price_override" numeric DEFAULT NULL::numeric) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_id UUID;
  v_current_quantity INTEGER;
  v_price_paid NUMERIC(10, 2);
  v_modifier_total NUMERIC(10, 2);
  v_new_subtotal NUMERIC(10, 2);
  v_result JSON;
BEGIN
  -- Get item details and verify access
  SELECT 
    oi.order_id,
    oi.quantity,
    oi.price_paid,
    COALESCE((
      SELECT SUM(oim.total_price)
      FROM public.order_item_modifiers oim
      WHERE oim.order_item_id = oi.id
    ), 0)
  INTO v_order_id, v_current_quantity, v_price_paid, v_modifier_total
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
    AND oi.is_voided = FALSE
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids())
    AND o.status NOT IN ('completed', 'cancelled', 'void');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found or cannot be modified';
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied: location.orders.manage required';
  -- END IF;

  -- Handle price override (requires additional permission)
  IF p_price_override IS NOT NULL THEN
    IF NOT has_any_permission(ARRAY['location.orders.override_price', 'merchant.orders.manage']) THEN
      RAISE EXCEPTION 'Permission denied: price override requires manager permission';
    END IF;
    v_price_paid := p_price_override;
  END IF;

  -- Use provided quantity or keep current
  v_current_quantity := COALESCE(p_quantity, v_current_quantity);
  
  -- Validate quantity
  IF v_current_quantity < 1 THEN
    RAISE EXCEPTION 'Quantity must be at least 1';
  END IF;

  -- Calculate new subtotal
  v_new_subtotal := (v_current_quantity * v_price_paid) + (v_current_quantity * v_modifier_total);

  -- Update the item (only non-null fields)
  UPDATE public.order_items
  SET 
    quantity = v_current_quantity,
    price_paid = v_price_paid,
    subtotal = v_new_subtotal,
    special_instructions = COALESCE(p_special_instructions, special_instructions),
    prep_station = COALESCE(p_prep_station, prep_station),
    course_number = COALESCE(p_course_number, course_number),
    updated_at = NOW()
  WHERE id = p_order_item_id;

  -- Return result
  SELECT json_build_object(
    'success', true,
    'order_item_id', p_order_item_id,
    'order_id', v_order_id,
    'quantity', v_current_quantity,
    'price_paid', v_price_paid,
    'modifier_total', v_modifier_total,
    'new_subtotal', v_new_subtotal,
    'special_instructions', p_special_instructions,
    'prep_station', p_prep_station,
    'course_number', p_course_number
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."update_order_item"("p_order_item_id" "uuid", "p_quantity" integer, "p_special_instructions" "text", "p_prep_station" "text", "p_course_number" integer, "p_price_override" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_order_item"("p_order_item_id" "uuid", "p_quantity" integer, "p_special_instructions" "text", "p_prep_station" "text", "p_course_number" integer, "p_price_override" numeric) IS 'Updates order item details including quantity, instructions, and optional price override';



CREATE OR REPLACE FUNCTION "public"."update_order_item_quantity"("p_order_item_id" "uuid", "p_quantity" integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
    v_order_id UUID;
    v_merchant_id UUID;
    v_location_id UUID;
    
    -- Item details
    v_unit_price NUMERIC;
    v_cash_price NUMERIC;
    v_tax_rate NUMERIC;
    v_paid_quantity INTEGER;
    v_current_quantity INTEGER;
    
    -- New Totals
    v_new_subtotal NUMERIC;
    v_new_cash_subtotal NUMERIC;
    v_new_tax_amount NUMERIC;
    v_new_cash_tax_amount NUMERIC;
    
    v_result JSON;
    v_new_sync_version integer;
BEGIN
    -- ==========================================
    -- 1. Validate Input
    -- ==========================================
    IF p_quantity < 1 THEN
        RAISE EXCEPTION 'Quantity must be at least 1. Use void_order_item() to remove items.';
    END IF;

    -- ==========================================
    -- 2. Get Item Details & Verify Access
    -- ==========================================
    SELECT 
        oi.order_id,
        oi.unit_price,       -- The full Card Price (Base + Size + Mods)
        oi.cash_price,       -- The full Cash Price
        oi.tax_rate,
        oi.quantity,
        COALESCE(oi.paid_quantity, 0),
        o.merchant_id,
        o.location_id
    INTO 
        v_order_id, 
        v_unit_price, 
        v_cash_price, 
        v_tax_rate,
        v_current_quantity,
        v_paid_quantity,
        v_merchant_id,
        v_location_id
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    WHERE oi.id = p_order_item_id
      AND oi.is_voided = FALSE
      AND o.merchant_id = user_merchant_id()
      AND o.location_id = ANY(user_location_ids())
      AND o.status NOT IN ('completed', 'cancelled', 'void')
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order item not found or cannot be modified';
    END IF;

    -- ==========================================
    -- 3. Safety Check: Paid Quantity
    -- ==========================================
    IF p_quantity < v_paid_quantity THEN
        RAISE EXCEPTION 'Cannot reduce quantity below paid amount (%)', v_paid_quantity;
    END IF;

    -- ==========================================
    -- 4. Calculate New Totals (Gross)
    -- ==========================================
    -- We calculate "Gross" totals first. 
    -- If there is a discount, recalculate_order_discount will adjust these to "Net" later.
    v_new_subtotal := p_quantity * v_unit_price;
    v_new_cash_subtotal := p_quantity * v_cash_price;
    
    -- Calculate Tax
    v_new_tax_amount := ROUND(v_new_subtotal * (v_tax_rate / 100), 2);
    v_new_cash_tax_amount := ROUND(v_new_cash_subtotal * (v_tax_rate / 100), 2);

    -- ==========================================
    -- 5. Update Order Item
    -- ==========================================
    UPDATE public.order_items
    SET 
        quantity = p_quantity,
        
        -- Set Totals
        subtotal = v_new_subtotal,
        cash_subtotal = v_new_cash_subtotal,
        tax_amount = v_new_tax_amount,
        cash_tax_amount = v_new_cash_tax_amount,
        
        -- Reset Discount columns (Let the recalculate function fill them fresh)
        -- This ensures we don't have "stale" discount amounts from the old quantity
        discount_amount = 0,
        discount_cash_amount = 0,
        pre_discount_subtotal = NULL,
        
        updated_at = NOW()
    WHERE id = p_order_item_id;

    -- ==========================================
    -- 6. Recalculate Order-Level Math
    -- ==========================================
    -- 1. Redistribute any active discounts across the new quantity
    PERFORM recalculate_order_discount(v_order_id);
    
    -- 2. Update the main Order Header (Total, Tax, Amount Due)
    -- PERFORM calculate_order_totals_fast(v_order_id);
    -- PERFORM calculate_order_totals_fast(p_order_id);
    v_new_sync_version := increment_order_sync_version(v_order_id);
    -- ==========================================
    -- 7. Return Result
    -- ==========================================
    -- Fetch final values (in case discount changed them)
    SELECT subtotal INTO v_new_subtotal FROM public.order_items WHERE id = p_order_item_id;

    SELECT json_build_object(
        'success', true,
        'order_item_id', p_order_item_id,
        'order_id', v_order_id,
        'quantity', p_quantity,
        'unit_price', v_unit_price,
        'new_subtotal', v_new_subtotal,
        'sync_version', v_new_sync_version
    ) INTO v_result;

    RETURN v_result;
END;$$;


ALTER FUNCTION "public"."update_order_item_quantity"("p_order_item_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_order_item_quantity"("p_order_item_id" "uuid", "p_quantity" integer) IS 'Updates item quantity and recalculates subtotal including modifiers';



CREATE OR REPLACE FUNCTION "public"."update_order_item_quantity_v2"("p_order_item_id" "uuid", "p_quantity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_order_id uuid;
    v_location_id uuid;
    v_unit_price numeric;
    v_cash_unit_price numeric;
    v_tax_rate numeric;
    v_is_tax_exempt boolean;

    v_modifier_total numeric;
    v_new_subtotal numeric;
    v_new_cash_subtotal numeric;
    v_new_tax_amount numeric;
    v_new_cash_tax_amount numeric;

    v_discount_amount numeric := 0;
    v_discount_cash_amount numeric := 0;
    v_has_active_discount boolean := false;

    v_new_sync_version integer;
    v_price_paid numeric;

    v_result jsonb;
BEGIN
    -- Validate quantity
    IF p_quantity IS NULL OR p_quantity < 1 THEN
        RAISE EXCEPTION 'Invalid quantity: must be at least 1';
    END IF;

    -- ============================================
    -- 1. Get current item details
    -- ============================================
    SELECT
        oi.order_id,
        oi.unit_price,
        oi.cash_price,
        oi.tax_rate,
        COALESCE(oi.is_tax_exempt, false),
        o.location_id,
        o.sync_version + 1  -- Increment sync version
    INTO
        v_order_id,
        v_unit_price,
        v_cash_unit_price,
        v_tax_rate,
        v_is_tax_exempt,
        v_location_id,
        v_new_sync_version
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    WHERE oi.id = p_order_item_id
      AND o.merchant_id = user_merchant_id()
      AND o.location_id = ANY(user_location_ids())
    FOR UPDATE;  -- Lock row to prevent race conditions

    IF v_order_id IS NULL THEN
        RAISE EXCEPTION 'Order item not found or access denied';
    END IF;

    -- ============================================
    -- 2. Calculate modifier total (for reference)
    -- ============================================
    SELECT COALESCE(SUM(total_price), 0)
    INTO v_modifier_total
    FROM public.order_item_modifiers
    WHERE order_item_id = p_order_item_id;

    -- ============================================
    -- 3. Calculate new pricing based on quantity
    -- ============================================
    -- Subtotals = unit price × new quantity
    v_new_subtotal := v_unit_price * p_quantity;
    v_new_cash_subtotal := v_cash_unit_price * p_quantity;

    -- Calculate tax
    IF v_is_tax_exempt THEN
        v_new_tax_amount := 0;
        v_new_cash_tax_amount := 0;
    ELSE
        v_new_tax_amount := ROUND(v_new_subtotal * v_tax_rate / 100, 2);
        v_new_cash_tax_amount := ROUND(v_new_cash_subtotal * v_tax_rate / 100, 2);
    END IF;

    -- Calculate price paid (for backward compatibility)
    v_price_paid := v_unit_price * p_quantity;

    -- ============================================
    -- 4. Update order item with new pricing
    -- ============================================
    UPDATE public.order_items SET
        quantity = p_quantity,
        subtotal = v_new_subtotal,
        cash_subtotal = v_new_cash_subtotal,
        tax_amount = v_new_tax_amount,
        cash_tax_amount = v_new_cash_tax_amount,
        discount_amount = 0,  -- Reset, will be recalculated if discount exists
        discount_cash_amount = 0,
        updated_at = now()
    WHERE id = p_order_item_id;

    -- ============================================
    -- 5. Handle active order discounts
    -- ============================================
    SELECT EXISTS(
        SELECT 1 FROM public.order_discounts
        WHERE order_id = v_order_id
          AND voided_at IS NULL
          AND calculated_amount > 0
    ) INTO v_has_active_discount;

    IF v_has_active_discount THEN
        -- Redistribute discount across all items (including this updated one)
        PERFORM redistribute_order_discount(v_order_id);

        -- Get updated values after discount redistribution
        SELECT
            subtotal,
            cash_subtotal,
            tax_amount,
            cash_tax_amount,
            COALESCE(discount_amount, 0),
            COALESCE(discount_cash_amount, 0)
        INTO
            v_new_subtotal,
            v_new_cash_subtotal,
            v_new_tax_amount,
            v_new_cash_tax_amount,
            v_discount_amount,
            v_discount_cash_amount
        FROM public.order_items
        WHERE id = p_order_item_id;

        -- Recalculate price_paid after discount
        v_price_paid := v_new_subtotal;
    END IF;

    -- ============================================
    -- 6. Update order sync version
    -- ============================================
    -- UPDATE public.orders
    v_new_sync_version := increment_order_sync_version(v_order_id);

    -- ============================================
    -- 7. Recalculate order totals
    -- ============================================
    PERFORM recalculate_order_discount(v_order_id);

    -- ============================================
    -- 8. Return enhanced result with complete item data
    -- ============================================
    SELECT json_build_object(
        'success', true,
        'order_item_id', p_order_item_id,

        -- Backward compatibility (existing fields that might be expected)
        'quantity', p_quantity,
        'price_paid', v_price_paid,
        'modifier_total', v_modifier_total,
        'new_subtotal', v_new_subtotal,  -- For backward compatibility

        -- NEW: Complete item data with explicit naming
        -- Card pricing (explicit)
        'unit_price', v_unit_price,
        'card_subtotal', v_new_subtotal,
        'card_tax_amount', v_new_tax_amount,

        -- Cash pricing
        'cash_unit_price', v_cash_unit_price,
        'cash_subtotal', v_new_cash_subtotal,
        'cash_tax_amount', v_new_cash_tax_amount,

        -- Discounts
        'discount_amount', v_discount_amount,
        'discount_cash_amount', v_discount_cash_amount,

        -- Sync version for conflict detection
        'sync_version', v_new_sync_version
    ) INTO v_result;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."update_order_item_quantity_v2"("p_order_item_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_order_item_quantity_v2"("p_order_item_id" "uuid", "p_quantity" integer) IS 'Updates the quantity of an order item and recalculates pricing. Returns complete item data including card/cash pricing, tax amounts, and discounts.';



CREATE OR REPLACE FUNCTION "public"."update_order_item_v2"("p_order_item_id" "uuid", "p_quantity" integer DEFAULT NULL::integer, "p_unit_price" numeric DEFAULT NULL::numeric, "p_special_instructions" "text" DEFAULT NULL::"text", "p_seat_number" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_order_id uuid;
    v_is_open_item boolean;
    v_location_id uuid;
    v_tax_rate numeric;
    
    v_new_quantity integer;
    v_new_price numeric;
    v_cash_price numeric;
    v_subtotal numeric;
    v_cash_subtotal numeric;
    v_tax_amount numeric;
    v_cash_tax_amount numeric;
    
    v_cash_discount_rate numeric := 0.04;
BEGIN
    -- Get current item details
    SELECT 
        oi.order_id,
        oi.is_open_item,
        oi.quantity,
        oi.unit_price,
        oi.tax_rate,
        o.location_id
    INTO v_order_id, v_is_open_item, v_new_quantity, v_new_price, v_tax_rate, v_location_id
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    WHERE oi.id = p_order_item_id
      AND o.merchant_id = user_merchant_id()
      AND o.location_id = ANY(user_location_ids());
    
    IF v_order_id IS NULL THEN
        RAISE EXCEPTION 'Order item not found or access denied';
    END IF;
    
    -- Update quantity if provided
    IF p_quantity IS NOT NULL THEN
        v_new_quantity := p_quantity;
    END IF;
    
    -- Update price if provided AND it's an open item
    IF p_unit_price IS NOT NULL THEN
        IF NOT v_is_open_item THEN
            RAISE EXCEPTION 'Cannot change price of regular menu items';
        END IF;
        v_new_price := p_unit_price;
    END IF;
    
    -- Recalculate pricing
    v_cash_price := v_new_price * (1 - v_cash_discount_rate);
    v_subtotal := v_new_price * v_new_quantity;
    v_cash_subtotal := v_cash_price * v_new_quantity;
    v_tax_amount := ROUND(v_subtotal * v_tax_rate / 100, 2);
    v_cash_tax_amount := ROUND(v_cash_subtotal * v_tax_rate / 100, 2);
    
    -- Update the item
    UPDATE public.order_items SET
        quantity = v_new_quantity,
        unit_price = v_new_price,
        cash_price = v_cash_price,
        subtotal = v_subtotal,
        cash_subtotal = v_cash_subtotal,
        tax_amount = v_tax_amount,
        cash_tax_amount = v_cash_tax_amount,
        open_item_price = CASE WHEN v_is_open_item THEN v_new_price ELSE open_item_price END,
        special_instructions = COALESCE(p_special_instructions, special_instructions),
        seat_number = COALESCE(p_seat_number, seat_number),
        updated_at = now()
    WHERE id = p_order_item_id;
    
    -- Recalculate order totals
    PERFORM calculate_order_totals_fast(v_order_id);
    
    RETURN jsonb_build_object(
        'success', true,
        'order_item_id', p_order_item_id,
        'quantity', v_new_quantity,
        'unit_price', v_new_price,
        'subtotal', v_subtotal
    );
END;
$$;


ALTER FUNCTION "public"."update_order_item_v2"("p_order_item_id" "uuid", "p_quantity" integer, "p_unit_price" numeric, "p_special_instructions" "text", "p_seat_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_order_item_v2_dep"("p_order_item_id" "uuid", "p_quantity" integer DEFAULT NULL::integer, "p_unit_price" numeric DEFAULT NULL::numeric, "p_special_instructions" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$DECLARE
    v_order_id uuid;
    v_is_open_item boolean;
    v_location_id uuid;
    v_tax_rate numeric;
    
    v_new_quantity integer;
    v_new_price numeric;
    v_cash_price numeric;
    v_subtotal numeric;
    v_cash_subtotal numeric;
    v_tax_amount numeric;
    v_cash_tax_amount numeric;
    
    v_new_sync_version integer;

    v_cash_discount_rate numeric := 0.04;
    v_has_active_discount boolean := false;
BEGIN
    -- Get current item details
    SELECT 
        oi.order_id,
        oi.is_open_item,
        oi.quantity,
        oi.unit_price,
        oi.tax_rate,
        o.location_id
    INTO v_order_id, v_is_open_item, v_new_quantity, v_new_price, v_tax_rate, v_location_id
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    WHERE oi.id = p_order_item_id
      AND o.merchant_id = user_merchant_id()
      AND o.location_id = ANY(user_location_ids());
    
    IF v_order_id IS NULL THEN
        RAISE EXCEPTION 'Order item not found or access denied';
    END IF;
    
    -- Update quantity if provided
    IF p_quantity IS NOT NULL THEN
        v_new_quantity := p_quantity;
    END IF;
    
    -- Update price if provided AND it's an open item
    IF p_unit_price IS NOT NULL THEN
        IF NOT v_is_open_item THEN
            RAISE EXCEPTION 'Cannot change price of regular menu items';
        END IF;
        v_new_price := p_unit_price;
    END IF;
    
    -- Recalculate base pricing (pre-discount)
    v_cash_price := v_new_price * (1 - v_cash_discount_rate);
    v_subtotal := v_new_price * v_new_quantity;
    v_cash_subtotal := v_cash_price * v_new_quantity;
    v_tax_amount := ROUND(v_subtotal * v_tax_rate / 100, 2);
    v_cash_tax_amount := ROUND(v_cash_subtotal * v_tax_rate / 100, 2);
    
    -- Update the item with base values (discount will be applied after)
    UPDATE public.order_items SET
        quantity = v_new_quantity,
        unit_price = v_new_price,
        cash_price = v_cash_price,
        subtotal = v_subtotal,
        cash_subtotal = v_cash_subtotal,
        tax_amount = v_tax_amount,
        cash_tax_amount = v_cash_tax_amount,
        discount_amount = 0,  -- Reset, will be recalculated
        open_item_price = CASE WHEN v_is_open_item THEN v_new_price ELSE open_item_price END,
        special_instructions = COALESCE(p_special_instructions, special_instructions),
        updated_at = now()
    WHERE id = p_order_item_id;
    
    -- Check if there's an active order discount
    SELECT EXISTS(
        SELECT 1 FROM public.order_discounts
        WHERE order_id = v_order_id
          AND voided_at IS NULL
          AND calculated_amount > 0
    ) INTO v_has_active_discount;
    
    -- If discount exists, redistribute across all items
    IF v_has_active_discount THEN
        PERFORM redistribute_order_discount(v_order_id);
        
        -- Get updated values
        SELECT subtotal, tax_amount, cash_subtotal, cash_tax_amount
        INTO v_subtotal, v_tax_amount, v_cash_subtotal, v_cash_tax_amount
        FROM public.order_items
        WHERE id = p_order_item_id;
    END IF;
    
    -- Recalculate order totals
    -- PERFORM calculate_order_totals_fast(v_order_id);
    PERFORM recalculate_order_discount(v_order_id);
    
    v_new_sync_version := increment_order_sync_version(v_order_id);

    RETURN jsonb_build_object(
        'success', true,
        'order_item_id', p_order_item_id,
        'quantity', v_new_quantity,
        'unit_price', v_new_price,
        'subtotal', v_subtotal,
        'discount_applied', v_has_active_discount
    );
END;$$;


ALTER FUNCTION "public"."update_order_item_v2_dep"("p_order_item_id" "uuid", "p_quantity" integer, "p_unit_price" numeric, "p_special_instructions" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_order_payment_status_after_refund"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_order record;
  v_payment_status payment_status;
BEGIN
  -- Verify order access
  SELECT * INTO v_order
  FROM orders
  WHERE id = p_order_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found or access denied';
  END IF;

  -- Use calculate_order_totals_fast for comprehensive calculation
  -- This includes both item-level refunds (refunded_quantity) and
  -- payment-level refunds (refunded_amount) using MAX logic
  PERFORM calculate_order_totals_fast(p_order_id);
  
  -- Refresh order data after recalculation
  SELECT * INTO v_order FROM orders WHERE id = p_order_id;

  -- Determine payment status based on recalculated amounts
  IF COALESCE(v_order.amount_due, 0) <= 0 THEN
    v_payment_status := 'paid'::payment_status;
  ELSIF COALESCE(v_order.amount_paid, 0) > 0 THEN
    v_payment_status := 'partial'::payment_status;
  ELSE
    v_payment_status := 'refunded'::payment_status;
  END IF;

  -- Update only the payment_status (totals already updated by calculate_order_totals_fast)
  UPDATE orders
  SET payment_status = v_payment_status
  WHERE id = p_order_id;
END;$$;


ALTER FUNCTION "public"."update_order_payment_status_after_refund"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_order_status"("p_order_id" "uuid", "p_new_status" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_current_status TEXT;
  v_result JSONB;
BEGIN
  -- Get current status
  SELECT status::text INTO v_current_status
  FROM orders
  WHERE id = p_order_id;

  IF v_current_status IS NULL THEN
    RAISE EXCEPTION 'Order not found: %', p_order_id;
  END IF;

  -- Prevent redundant status updates
  IF v_current_status = p_new_status THEN
    RAISE EXCEPTION 'Order is already in % status', p_new_status
      USING ERRCODE = 'P0001';
  END IF;

  -- Update the order with appropriate timestamps based on new status
  UPDATE orders
  SET
    status = p_new_status::order_status,
    updated_at = NOW(),
    -- Set sent_to_kitchen_at when transitioning to sent_to_kitchen or preparing
    sent_to_kitchen_at = CASE
      WHEN p_new_status IN ('sent_to_kitchen', 'preparing')
        THEN COALESCE(sent_to_kitchen_at, NOW())
      ELSE sent_to_kitchen_at
    END,
    -- Set started_preparing_at when transitioning to preparing
    started_preparing_at = CASE
      WHEN p_new_status = 'preparing'
        THEN COALESCE(started_preparing_at, NOW())
      ELSE started_preparing_at
    END,
    -- Set ready_at when transitioning to ready
    ready_at = CASE
      WHEN p_new_status = 'ready'
        THEN COALESCE(ready_at, NOW())
      ELSE ready_at
    END,
    -- Set completed_at when transitioning to completed
    completed_at = CASE
      WHEN p_new_status = 'completed'
        THEN COALESCE(completed_at, NOW())
      ELSE completed_at
    END,
    -- Set cancelled_at when transitioning to cancelled
    cancelled_at = CASE
      WHEN p_new_status = 'cancelled'
        THEN COALESCE(cancelled_at, NOW())
      ELSE cancelled_at
    END,
    cancellation_reason = CASE
      WHEN p_new_status = 'cancelled' AND p_reason IS NOT NULL
        THEN p_reason
      ELSE cancellation_reason
    END
  WHERE id = p_order_id;

  -- Return the updated order
  SELECT jsonb_build_object(
    'id', id,
    'status', status,
    'sent_to_kitchen_at', sent_to_kitchen_at,
    'started_preparing_at', started_preparing_at,
    'ready_at', ready_at,
    'completed_at', completed_at
  ) INTO v_result
  FROM orders
  WHERE id = p_order_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."update_order_status"("p_order_id" "uuid", "p_new_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_order_status_dep"("p_order_id" "uuid", "p_new_status" "public"."order_status", "p_reason" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_current_status order_status;
  v_result JSON;
BEGIN
  -- Verify user has access and get current status
  SELECT status INTO v_current_status
  FROM public.orders
  WHERE id = p_order_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found or access denied';
  END IF;
  
  -- Verify user has permission
  -- IF NOT auth.has_any_permission(ARRAY['location.orders.manage', 'merchant.orders.manage']) THEN
  --   RAISE EXCEPTION 'Permission denied: location.orders.manage or merchant.orders.manage required';
  -- END IF;
  
  -- Validate status transition
  IF v_current_status = p_new_status THEN
    RAISE WARNING 'Order is already in % status', p_new_status;
  END IF;
  
  -- Update order status (trigger will record history)
  UPDATE public.orders
  SET 
    status = p_new_status,
    updated_at = NOW()
  WHERE id = p_order_id;
  
  -- Add notes to history if provided
  IF p_reason IS NOT NULL OR p_notes IS NOT NULL THEN
    UPDATE public.order_status_history
    SET 
      reason = p_reason,
      notes = p_notes
    WHERE order_id = p_order_id
      AND to_status = p_new_status
      AND changed_at = (
        SELECT MAX(changed_at)
        FROM public.order_status_history
        WHERE order_id = p_order_id
      );
  END IF;
  
  -- Return result
  SELECT json_build_object(
    'success', true,
    'order_id', p_order_id,
    'previous_status', v_current_status,
    'new_status', p_new_status,
    'updated_at', NOW()
  ) INTO v_result;
  
  RETURN v_result;
END;$$;


ALTER FUNCTION "public"."update_order_status_dep"("p_order_id" "uuid", "p_new_status" "public"."order_status", "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_order_status_dep"("p_order_id" "uuid", "p_new_status" "public"."order_status", "p_reason" "text", "p_notes" "text") IS 'Updates order status with validation - requires location.orders.manage or merchant.orders.manage permission';



CREATE OR REPLACE FUNCTION "public"."update_preauth_amount_v1"("p_payment_id" "uuid", "p_new_amount" numeric, "p_terminal_response" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_payment RECORD;
BEGIN
  -- Validate payment exists and is authorized
  SELECT id, status, amount
  INTO v_payment
  FROM order_payments
  WHERE id = p_payment_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment not found');
  END IF;

  IF v_payment.status <> 'authorized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment is not in authorized status');
  END IF;

  -- Update authorized amount
  UPDATE order_payments
  SET
    amount = p_new_amount,
    total_amount = p_new_amount,
    terminal_response = CASE
      WHEN p_terminal_response IS NOT NULL THEN p_terminal_response
      ELSE terminal_response
    END
  WHERE id = p_payment_id;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', p_payment_id,
    'new_authorized_amount', p_new_amount
  );
END;
$$;


ALTER FUNCTION "public"."update_preauth_amount_v1"("p_payment_id" "uuid", "p_new_amount" numeric, "p_terminal_response" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_reservation_status"("p_reservation_id" "uuid", "p_status" "public"."reservation_status", "p_cancellation_reason" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_old_status reservation_status;
BEGIN
  -- Get current status
  SELECT status INTO v_old_status
  FROM public.reservations
  WHERE id = p_reservation_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Reservation not found';
  END IF;

  -- Update status
  UPDATE public.reservations
  SET 
    status = p_status,
    arrived_at = CASE WHEN p_status = 'arrived' THEN NOW() ELSE arrived_at END,
    no_show_marked_at = CASE WHEN p_status = 'no_show' THEN NOW() ELSE no_show_marked_at END,
    cancelled_at = CASE WHEN p_status = 'cancelled' THEN NOW() ELSE cancelled_at END,
    cancellation_reason = COALESCE(p_cancellation_reason, cancellation_reason),
    updated_at = NOW()
  WHERE id = p_reservation_id;

  RETURN json_build_object(
    'success', true,
    'reservation_id', p_reservation_id,
    'previous_status', v_old_status,
    'new_status', p_status
  );
END;
$$;


