CREATE OR REPLACE FUNCTION "public"."update_table_session_status"("p_session_id" "uuid", "p_status" "public"."table_status", "p_notes" "text" DEFAULT NULL::"text", "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_old_status public.table_status;
  v_event_type public.session_event_type;
BEGIN
  -- Get current status
  SELECT status INTO v_old_status
  FROM public.table_sessions
  WHERE id = p_session_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found';
  END IF;

  -- Map status to event type
  v_event_type := CASE p_status
    WHEN 'ordered' THEN 'order_placed'::public.session_event_type
    WHEN 'served' THEN 'mains_served'::public.session_event_type
    WHEN 'check_presented' THEN 'check_presented'::public.session_event_type
    WHEN 'paid' THEN 'payment_complete'::public.session_event_type
    WHEN 'cleaning' THEN 'table_cleared'::public.session_event_type
    WHEN 'available' THEN 'table_cleaned'::public.session_event_type
    ELSE 'custom'::public.session_event_type
  END;

  -- Record event (this triggers status update via trigger)
  INSERT INTO public.table_session_events (
    session_id, event_type, notes,
    triggered_by_staff_id, triggered_by_user_id
  ) VALUES (
    p_session_id, v_event_type, p_notes,
    COALESCE(p_staff_id, user_staff_profile_id()), get_my_claim('sub')
  );

  -- If closing session
  IF p_status IN ('available') THEN
    UPDATE public.table_sessions
    SET 
      is_active = FALSE,
      actual_duration = EXTRACT(EPOCH FROM (NOW() - seated_at)) / 60,
      closed_by = COALESCE(p_staff_id, user_staff_profile_id()),
      closed_at = NOW()
    WHERE id = p_session_id;
  END IF;

  RETURN json_build_object(
    'success', true,
    'session_id', p_session_id,
    'previous_status', v_old_status,
    'new_status', p_status
  );
END;
$$;


ALTER FUNCTION "public"."update_table_session_status"("p_session_id" "uuid", "p_status" "public"."table_status", "p_notes" "text", "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_terminal_health"("p_terminal_id" "uuid", "p_is_connected" boolean, "p_status" "text" DEFAULT NULL::"text", "p_firmware_version" "text" DEFAULT NULL::"text", "p_battery_level" integer DEFAULT NULL::integer, "p_consecutive_failures" integer DEFAULT NULL::integer, "p_last_error_message" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_result JSON;
BEGIN
  UPDATE payment_terminals
  SET
    is_connected = p_is_connected,
    last_connection_test_at = NOW(),
    last_connection_status = COALESCE(p_status, last_connection_status),
    firmware_version = COALESCE(p_firmware_version, firmware_version),
    battery_level = COALESCE(p_battery_level, battery_level),
    consecutive_failures = COALESCE(p_consecutive_failures, consecutive_failures),
    last_error_message = CASE
      WHEN p_is_connected = TRUE THEN NULL
      ELSE COALESCE(p_last_error_message, last_error_message)
    END,
    updated_at = NOW()
  WHERE id = p_terminal_id;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', FALSE,
      'error', 'Terminal not found'
    );
  END IF;

  SELECT json_build_object(
    'success', TRUE,
    'terminal_id', id,
    'is_connected', is_connected,
    'consecutive_failures', consecutive_failures,
    'last_connection_status', last_connection_status
  ) INTO v_result
  FROM payment_terminals
  WHERE id = p_terminal_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."update_terminal_health"("p_terminal_id" "uuid", "p_is_connected" boolean, "p_status" "text", "p_firmware_version" "text", "p_battery_level" integer, "p_consecutive_failures" integer, "p_last_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_terminal_status"("p_terminal_id" "uuid", "p_status" "text", "p_is_connected" boolean) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$BEGIN
  UPDATE payment_terminals
  SET 
    is_connected = p_is_connected,
    last_connection_test_at = NOW(),
    last_connection_status = p_status,
    updated_at = NOW()
  WHERE id = p_terminal_id
    AND merchant_id IN (
      SELECT merchant_id FROM staff_profiles WHERE user_id = get_my_claim('sub')
    );
  
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Terminal not found');
  END IF;
  
  RETURN json_build_object('success', true);
END;$$;


ALTER FUNCTION "public"."update_terminal_status"("p_terminal_id" "uuid", "p_status" "text", "p_is_connected" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_ticket_status"("p_ticket_id" "uuid", "p_status" "text", "p_resolution_notes" "text" DEFAULT NULL::"text", "p_resolved_by" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE public.support_tickets
  SET
    status = p_status,
    updated_at = now(),
    resolved_at = CASE WHEN p_status = 'resolved' THEN now() ELSE resolved_at END,
    resolved_by = CASE WHEN p_status = 'resolved' AND p_resolved_by IS NOT NULL THEN p_resolved_by ELSE resolved_by END,
    resolution_notes = CASE WHEN p_resolution_notes IS NOT NULL THEN p_resolution_notes ELSE resolution_notes END
  WHERE id = p_ticket_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ticket not found');
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


