CREATE OR REPLACE FUNCTION "public"."upsert_menu_item_with_recipe"("p_menu_item_id" "uuid", "p_ingredients" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    item jsonb;
    v_merchant_id UUID;
BEGIN
    -- 1. Validate inputs (basic)
    IF p_menu_item_id IS NULL THEN
        RAISE EXCEPTION 'Menu Item ID is required';
    END IF;

    -- Get merchant_id from menu_item
    SELECT merchant_id INTO v_merchant_id
    FROM menu_items
    WHERE id = p_menu_item_id;

    -- 2. Update Recipe (Full replacement strategy)
    IF p_ingredients IS NOT NULL THEN
        -- Delete existing recipe lines
        DELETE FROM menu_item_recipes 
        WHERE menu_item_id = p_menu_item_id;

        -- Insert new lines
        FOR item IN SELECT * FROM jsonb_array_elements(p_ingredients)
        LOOP
            INSERT INTO menu_item_recipes (
                menu_item_id,
                inventory_item_id,
                quantity_used,
                merchant_id
            ) VALUES (
                p_menu_item_id,
                (item->>'inventoryItemId')::UUID,
                COALESCE((item->>'quantity')::NUMERIC, (item->>'quantityUsed')::NUMERIC, 1),
                v_merchant_id
            );
        END LOOP;
    END IF;
END;
$$;


ALTER FUNCTION "public"."upsert_menu_item_with_recipe"("p_menu_item_id" "uuid", "p_ingredients" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_menu_item_with_recipe"("p_menu_item_id" "uuid", "p_location_id" "uuid", "p_recipe_items" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    item jsonb;
BEGIN
    -- 1. Validate inputs (basic)
    IF p_menu_item_id IS NULL THEN
        RAISE EXCEPTION 'Menu Item ID is required';
    END IF;

    -- 2. Update Recipe (Full replacement strategy)
    IF p_recipe_items IS NOT NULL THEN
        -- Delete existing recipe lines
        DELETE FROM menu_item_recipes 
        WHERE menu_item_id = p_menu_item_id;

        -- Insert new lines
        FOR item IN SELECT * FROM jsonb_array_elements(p_recipe_items)
        LOOP
            INSERT INTO menu_item_recipes (
                menu_item_id,
                inventory_item_id,
                quantity,
                unit_type -- Optional, can fetch triggers or default
            ) VALUES (
                p_menu_item_id,
                (item->>'inventoryItemId')::UUID,
                (item->>'quantity')::NUMERIC,
                'unit' -- Placeholder, ideally fetch from inventory_items
            );
        END LOOP;
    END IF;
END;
$$;


ALTER FUNCTION "public"."upsert_menu_item_with_recipe"("p_menu_item_id" "uuid", "p_location_id" "uuid", "p_recipe_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_menu_item_with_recipe"("p_menu_item_id" "uuid", "p_ingredients" "jsonb" DEFAULT NULL::"jsonb", "p_recipe_items" "jsonb" DEFAULT NULL::"jsonb", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    item jsonb;
    v_merchant_id UUID;
    v_items JSONB;
    v_inventory_id UUID;
BEGIN
    -- 1. Validate inputs (basic)
    IF p_menu_item_id IS NULL THEN
        RAISE EXCEPTION 'Menu Item ID is required';
    END IF;

    -- Resolve items array (support both param names)
    v_items := COALESCE(p_ingredients, p_recipe_items);

    -- Get merchant_id from menu_item
    SELECT merchant_id INTO v_merchant_id
    FROM menu_items
    WHERE id = p_menu_item_id;

    -- 2. Update Recipe (Full replacement strategy)
    IF v_items IS NOT NULL THEN
        -- Delete existing recipe lines
        DELETE FROM menu_item_recipes 
        WHERE menu_item_id = p_menu_item_id;

        -- Insert new lines
        FOR item IN SELECT * FROM jsonb_array_elements(v_items)
        LOOP
            -- Check for valid inventory ID
            v_inventory_id := (item->>'inventoryItemId')::UUID;
            
            IF v_inventory_id IS NOT NULL THEN
                INSERT INTO menu_item_recipes (
                    menu_item_id,
                    inventory_item_id,
                    quantity_used,
                    merchant_id
                ) VALUES (
                    p_menu_item_id,
                    v_inventory_id,
                    COALESCE(
                        (item->>'quantity')::NUMERIC, 
                        (item->>'quantityUsed')::NUMERIC,
                        (item->>'quantity_used')::NUMERIC, 
                        1
                    ),
                    v_merchant_id
                );
            END IF;
        END LOOP;
    END IF;
END;
$$;


