CREATE OR REPLACE FUNCTION "public"."upsert_modifier_item_with_recipe"("p_modifier_item_id" "uuid", "p_recipe_items" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_merchant_id UUID;
    item jsonb;
BEGIN
    IF p_modifier_item_id IS NULL THEN
        RAISE EXCEPTION 'Modifier Item ID is required';
    END IF;

    -- Get merchant_id from the modifier item (via group)
    SELECT mg.merchant_id INTO v_merchant_id
    FROM modifier_group_items mgi
    JOIN modifier_groups mg ON mgi.modifier_group_id = mg.id
    WHERE mgi.id = p_modifier_item_id;

    -- Delete existing recipe lines
    DELETE FROM modifier_group_item_recipes 
    WHERE modifier_group_item_id = p_modifier_item_id;

    -- Insert new lines
    IF p_recipe_items IS NOT NULL THEN
        FOR item IN SELECT * FROM jsonb_array_elements(p_recipe_items)
        LOOP
            INSERT INTO modifier_group_item_recipes (
                modifier_group_item_id,
                inventory_item_id,
                quantity_used,
                merchant_id
            ) VALUES (
                p_modifier_item_id,
                (item->>'inventoryItemId')::UUID,
                (item->>'quantity')::NUMERIC,
                v_merchant_id
            );
        END LOOP;
    END IF;
END;
$$;


ALTER FUNCTION "public"."upsert_modifier_item_with_recipe"("p_modifier_item_id" "uuid", "p_recipe_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_modifier_override"("p_location_id" "uuid", "p_modifier_item_id" "uuid", "p_price_modifier" numeric DEFAULT NULL::numeric, "p_is_active" boolean DEFAULT NULL::boolean, "p_stock_tracking_mode" "text" DEFAULT NULL::"text", "p_current_stock" integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_merchant_id UUID;
BEGIN
    -- 1. Get Merchant ID from the modifier item to ensure safety
    SELECT merchant_id INTO v_merchant_id
    FROM modifier_group_items WHERE id = p_modifier_item_id;

    -- 2. Upsert
    INSERT INTO location_modifier_item_overrides (
        location_id, modifier_group_item_id, merchant_id,
        price_modifier, is_active, 
        stock_tracking_mode, current_stock,
        updated_at
    ) VALUES (
        p_location_id, p_modifier_item_id, v_merchant_id,
        p_price_modifier, p_is_active,
        p_stock_tracking_mode, p_current_stock,
        NOW()
    )
    ON CONFLICT (location_id, modifier_group_item_id)
    DO UPDATE SET
        price_modifier = COALESCE(EXCLUDED.price_modifier, location_modifier_item_overrides.price_modifier),
        is_active = COALESCE(EXCLUDED.is_active, location_modifier_item_overrides.is_active),
        stock_tracking_mode = COALESCE(EXCLUDED.stock_tracking_mode, location_modifier_item_overrides.stock_tracking_mode),
        current_stock = COALESCE(EXCLUDED.current_stock, location_modifier_item_overrides.current_stock),
        updated_at = NOW();

    RETURN json_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."upsert_modifier_override"("p_location_id" "uuid", "p_modifier_item_id" "uuid", "p_price_modifier" numeric, "p_is_active" boolean, "p_stock_tracking_mode" "text", "p_current_stock" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_has_location_permission"("p_location_id" "uuid", "p_permission_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_user_id TEXT;
    v_merchant_id UUID;
    v_role_code TEXT;
BEGIN
    v_user_id := current_user_id();
    
    -- Fast path: check location membership first (most common case)
    SELECT lm.role_code, l.merchant_id 
    INTO v_role_code, v_merchant_id
    FROM location_members lm
    JOIN locations l ON l.id = lm.location_id
    WHERE lm.user_id = v_user_id
      AND lm.location_id = p_location_id
      AND lm.is_active = true;
    
    -- If user is a location member, check their role's permissions
    IF v_role_code IS NOT NULL THEN
        RETURN EXISTS (
            SELECT 1 FROM role_permissions
            WHERE role_code = v_role_code
              AND permission_code = p_permission_code
        );
    END IF;
    
    -- Fallback: get merchant_id and check if user is merchant admin
    IF v_merchant_id IS NULL THEN
        SELECT merchant_id INTO v_merchant_id 
        FROM locations WHERE id = p_location_id;
    END IF;
    
    -- Check if merchant admin (they have all location permissions)
    IF is_merchant_admin(v_merchant_id) THEN
        RETURN true;
    END IF;
    
    RETURN false;
END;
$$;


ALTER FUNCTION "public"."user_has_location_permission"("p_location_id" "uuid", "p_permission_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_location_ids"() RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT COALESCE(
    ARRAY_AGG(DISTINCT location_id),
    ARRAY[]::UUID[]
  )
  FROM (
    -- Get locations from location_members where user is assigned
    -- Handles both Clerk users (user_id match) and POS-only users (staff_profile_id match)
    SELECT lm.location_id
    FROM public.location_members lm
    WHERE lm.is_active = true
      AND lm.merchant_id = user_merchant_id()
      AND (
        lm.user_id = get_my_claim('sub')  -- For Clerk users
        OR lm.staff_profile_id = user_staff_profile_id()  -- For POS-only users
      )
    
    UNION
    
    -- If user has merchant-level role, include all merchant locations
    SELECT l.id as location_id
    FROM public.locations l
    WHERE l.merchant_id = user_merchant_id()
      AND EXISTS (
        SELECT 1 
        FROM public.user_roles ur
        INNER JOIN public.roles r ON r.code = ur.role_code
        WHERE ur.user_id = get_my_claim('sub')
          AND r.organization_type = 'merchant'
          AND r.level_type IN ('merchant', 'organization')
      )
  ) all_locations
  WHERE location_id IS NOT NULL;
$$;


ALTER FUNCTION "public"."user_location_ids"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."user_location_ids"() IS 'Returns array of location IDs the user can access from location_members table or merchant-level roles';



