CREATE OR REPLACE FUNCTION "public"."validate_payment_amount"("p_order_id" "uuid", "p_expected_amount" numeric, "p_is_cash" boolean DEFAULT false, "p_item_allocations" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_correct_amount NUMERIC;
  v_order RECORD;
  v_tolerance NUMERIC := 0.02; -- 2 cents tolerance for rounding
BEGIN
  -- Get fresh order totals
  SELECT 
    o.*,
    CASE WHEN p_is_cash THEN 
      GREATEST(0, o.cash_total - o.amount_paid)
    ELSE 
      GREATEST(0, o.card_total - o.amount_paid)
    END as outstanding
  INTO v_order
  FROM orders o
  WHERE o.id = p_order_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'valid', false,
      'error', 'Order not found',
      'correct_amount', 0
    );
  END IF;
  
  -- Calculate correct amount
  IF p_item_allocations IS NOT NULL THEN
    -- Split by item - calculate from allocations
    SELECT COALESCE(SUM(
      CASE WHEN p_is_cash THEN
        oi.cash_price * LEAST(
          (alloc->>'quantity')::INTEGER,
          oi.quantity - COALESCE(oi.paid_quantity, 0)
        )
      ELSE
        oi.unit_price * LEAST(
          (alloc->>'quantity')::INTEGER,
          oi.quantity - COALESCE(oi.paid_quantity, 0)
        )
      END
      + oi.tax_amount * (
        LEAST((alloc->>'quantity')::INTEGER, oi.quantity - COALESCE(oi.paid_quantity, 0))::NUMERIC / oi.quantity
      )
      - oi.discount_amount * (
        LEAST((alloc->>'quantity')::INTEGER, oi.quantity - COALESCE(oi.paid_quantity, 0))::NUMERIC / oi.quantity
      )
    ), 0)
    INTO v_correct_amount
    FROM order_items oi
    JOIN jsonb_array_elements(p_item_allocations) alloc 
      ON oi.id = (alloc->>'item_id')::UUID
    WHERE oi.order_id = p_order_id
    AND NOT oi.is_voided;
  ELSE
    -- Full or split even - use outstanding
    v_correct_amount := v_order.outstanding;
  END IF;
  
  v_correct_amount := ROUND(v_correct_amount, 2);
  
  -- Check if amounts match within tolerance
  IF ABS(p_expected_amount - v_correct_amount) <= v_tolerance THEN
    RETURN jsonb_build_object(
      'valid', true,
      'correct_amount', v_correct_amount
    );
  ELSE
    RETURN jsonb_build_object(
      'valid', false,
      'correct_amount', v_correct_amount,
      'expected_amount', p_expected_amount,
      'discrepancy', ROUND(p_expected_amount - v_correct_amount, 2),
      'error', 'Amount mismatch - order may have been modified'
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."validate_payment_amount"("p_order_id" "uuid", "p_expected_amount" numeric, "p_is_cash" boolean, "p_item_allocations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_order"("p_order_id" "uuid", "p_void_reason" "text" DEFAULT 'Order cancelled'::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$DECLARE
  v_order RECORD;
  v_voided_items_count INTEGER;
  v_voided_payments_count INTEGER;
  v_refund_amount NUMERIC(10, 2) := 0;
  v_result JSON;
  v_new_sync_version integer;
BEGIN
  -- 1. Get order details
  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  -- 2. Business Logic Checks
  -- We allow voiding 'pending', 'preparing', 'ready', 'served'.
  -- We only block if it's already 'void'.
  IF v_order.status = 'void' THEN
    RAISE EXCEPTION 'Order is already voided';
  END IF;

  -- Optional: Prevent voiding 'completed' (historical) orders if you prefer strict accounting
  -- IF v_order.status = 'completed' AND v_order.closed_at < (NOW() - INTERVAL '1 day') THEN
  --   RAISE EXCEPTION 'Cannot void orders closed more than 24 hours ago.';
  -- END IF;

  -- 3. Void all items
  -- This is critical for KDS: The kitchen needs to see 'is_voided' flip to TRUE
  UPDATE public.order_items
  SET 
    is_voided = TRUE,
    voided_at = NOW(),
    voided_by = user_staff_profile_id(),
    void_reason = p_void_reason,
    updated_at = NOW()
  WHERE order_id = p_order_id AND is_voided = FALSE;

  GET DIAGNOSTICS v_voided_items_count = ROW_COUNT;

  -- 4. Handle Payments (Paid vs Unpaid Logic)
  -- If the order was "Preparing" and "Paid", this calculates the refund due.
  -- If "Preparing" and "Unpaid", this returns 0.
  SELECT COALESCE(SUM(amount), 0) INTO v_refund_amount
  FROM public.order_payments
  WHERE order_id = p_order_id 
    AND status = 'captured'
    AND is_voided = FALSE;

  -- Void the payment records so they don't count towards daily sales
  UPDATE public.order_payments
  SET 
    is_voided = TRUE,
    voided_by = user_staff_profile_id(),
    void_reason = p_void_reason,
    voided_at = NOW()
  WHERE order_id = p_order_id AND is_voided = FALSE;

  GET DIAGNOSTICS v_voided_payments_count = ROW_COUNT;

  -- 5. Update Order Status
  -- Whether it was 'preparing' or 'pending', it is now 'void'.
  UPDATE public.orders
  SET 
    status = 'void',
    amount_paid = 0,
    voided_at = NOW(),
    voided_by = user_staff_profile_id(),
    void_reason = p_void_reason,
    updated_at = NOW(),
    check_status = 'Closed',
    payment_status = 'void'
  WHERE id = p_order_id;

  -- 6. Release the Table
  -- If the order was 'preparing', the table was likely 'seated'. We must free it.
  UPDATE public.table_sessions
  SET 
    is_active = FALSE,
    status = 'available',
    closed_at = NOW(),
    closed_by = user_staff_profile_id()
  WHERE order_id = p_order_id AND is_active = TRUE;

  -- 7. Record History
  INSERT INTO public.order_status_history (
    order_id, 
    from_status, 
    to_status, 
    changed_by_staff_id,
    notes
  ) VALUES (
    p_order_id,
    v_order.status,
    'void',
    user_staff_profile_id(),
    p_void_reason
  );

   v_new_sync_version := increment_order_sync_version(p_order_id);

  -- 8. Return Result
  SELECT json_build_object(
    'success', true,
    'order_id', p_order_id,
    'previous_status', v_order.status, -- Helps frontend know if it was 'preparing'
    'refund_amount', v_refund_amount,  -- Frontend can prompt "Refund $X to customer?"
    'void_reason', p_void_reason,
    'sync_version', v_new_sync_version
  ) INTO v_result;

  RETURN v_result;
END;$_$;


ALTER FUNCTION "public"."void_order"("p_order_id" "uuid", "p_void_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."void_order"("p_order_id" "uuid", "p_void_reason" "text") IS 'Voids an entire order, all items, all payments, and closes linked table session';



CREATE OR REPLACE FUNCTION "public"."void_order_item"("p_order_item_id" "uuid", "p_void_reason" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  v_staff_id UUID;
  v_user_id TEXT;
  v_result JSON;
  v_order_id UUID;
  v_new_sync_version integer;
BEGIN
  -- Get current user
  v_user_id := get_my_claim('sub');
  
  -- Get staff_id if exists
  SELECT id INTO v_staff_id
  FROM public.staff_profiles
  WHERE user_id = v_user_id
  LIMIT 1;
  
  -- -- Verify user has permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied: location.orders.manage required';
  -- END IF;


  UPDATE public.order_items
  SET 
    is_voided = TRUE,
    void_reason = p_void_reason,
    voided_at = NOW(),
    voided_by = v_staff_id,
    updated_at = NOW()
  WHERE id = p_order_item_id
    AND is_voided = FALSE
    AND EXISTS (
      SELECT 1 FROM public.orders o
      WHERE o.id = order_items.order_id
        AND o.merchant_id = user_merchant_id()
        AND o.location_id = ANY(user_location_ids())
        AND o.status NOT IN ('completed', 'cancelled')
    )
  RETURNING order_id INTO v_order_id; -- <--- ADD THIS LINE
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found or cannot be voided';
  END IF;

  -- PERFORM calculate_order_totals_fast(v_order_id);
    PERFORM recalculate_order_discount(v_order_id);
   
    v_new_sync_version := increment_order_sync_version(v_order_id);
  
  SELECT json_build_object(
    'success', true,
    'order_item_id', p_order_item_id,
    'voided_at', NOW(),
    'sync_version', v_new_sync_version
  ) INTO v_result;
  
  RETURN v_result;
END;$$;


ALTER FUNCTION "public"."void_order_item"("p_order_item_id" "uuid", "p_void_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."void_order_item"("p_order_item_id" "uuid", "p_void_reason" "text") IS 'Voids an order item - requires location.orders.manage permission';



CREATE OR REPLACE FUNCTION "public"."void_preauth_v1"("p_payment_id" "uuid", "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_payment RECORD;
BEGIN
  -- Validate payment exists and is authorized
  SELECT id, status, order_id
  INTO v_payment
  FROM order_payments
  WHERE id = p_payment_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment not found');
  END IF;

  IF v_payment.status <> 'authorized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment is not in authorized status');
  END IF;

  -- Void the payment
  UPDATE order_payments
  SET
    status = 'void',
    is_voided = true,
    voided_at = NOW(),
    void_reason = p_reason,
    voided_by = p_staff_id
  WHERE id = p_payment_id;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', p_payment_id
  );
END;
$$;


ALTER FUNCTION "public"."void_preauth_v1"("p_payment_id" "uuid", "p_staff_id" "uuid", "p_reason" "text") OWNER TO "postgres";


