CREATE OR REPLACE VIEW "analytics"."v_location_performance_30d" AS
 SELECT "l"."id" AS "location_id",
    "l"."name" AS "location_name",
    "l"."merchant_id",
    "sum"("lds"."gross_sales") AS "total_gross_sales",
    "sum"("lds"."net_sales") AS "total_net_sales",
    "sum"("lds"."order_count") AS "total_orders",
    "avg"("lds"."avg_ticket") AS "avg_ticket",
    "sum"("lds"."tips_total") AS "total_tips",
    "avg"("lds"."labor_cost_percentage") AS "avg_labor_cost_pct"
   FROM ("public"."locations" "l"
     LEFT JOIN "analytics"."location_daily_stats" "lds" ON ((("lds"."location_id" = "l"."id") AND ("lds"."business_date" >= (CURRENT_DATE - '30 days'::interval)))))
  WHERE ("l"."is_active" = true)
  GROUP BY "l"."id", "l"."name", "l"."merchant_id";


