CREATE OR REPLACE VIEW "public"."admin_device_inventory" WITH ("security_invoker"='true') AS
 SELECT "di"."id",
    "di"."catalog_id",
    "di"."serial_number",
    "di"."mac_address",
    "di"."status",
    "di"."condition",
    "di"."firmware_version",
    "di"."app_version",
    "di"."purchased_at",
    "di"."warranty_expires_at",
    "di"."purchase_order_number",
    "di"."last_config_at",
    "di"."created_at",
    "di"."updated_at",
    "dc"."device_category",
    "dc"."manufacturer",
    "dc"."model_name",
    "dc"."model_sku",
    "dc"."monthly_fee_cents",
    "di"."merchant_id",
    "m"."name" AS "merchant_name",
    "di"."location_id",
    "l"."name" AS "location_name",
    "di"."linked_station_id",
    "di"."linked_payment_terminal_id",
