   FROM ((("public"."device_inventory" "di"
     JOIN "public"."device_catalog" "dc" ON (("dc"."id" = "di"."catalog_id")))
     LEFT JOIN "public"."merchants" "m" ON (("m"."id" = "di"."merchant_id")))
     LEFT JOIN "public"."locations" "l" ON (("l"."id" = "di"."location_id")));


