    CONSTRAINT "orders_cancelled_by_check" CHECK (("cancelled_by" = ANY (ARRAY['customer'::"text", 'merchant'::"text", 'system'::"text"]))),
    CONSTRAINT "positive_amounts" CHECK ((("subtotal" >= (0)::numeric) AND ("tax_amount" >= (0)::numeric) AND ("tip_amount" >= (0)::numeric) AND ("discount_amount" >= (0)::numeric) AND ("service_charge" >= (0)::numeric) AND ("total_amount" >= (0)::numeric) AND ("amount_paid" >= (0)::numeric))),
    CONSTRAINT "valid_status_transitions" CHECK (((("status" = 'draft'::"public"."order_status") AND ("sent_to_kitchen_at" IS NULL)) OR ("status" <> 'draft'::"public"."order_status")))
);


ALTER TABLE "public"."orders" OWNER TO "postgres";


COMMENT ON TABLE "public"."orders" IS 'Main orders table storing all order information with support for multiple payment methods and real-time syncing';



COMMENT ON COLUMN "public"."orders"."order_number" IS 'Unique order number for the entire system (e.g., "ORD-20240101-0042")';



COMMENT ON COLUMN "public"."orders"."display_number" IS 'Customer-facing display number (e.g., "#42")';



COMMENT ON COLUMN "public"."orders"."sync_version" IS 'Version number for optimistic locking and conflict resolution';



COMMENT ON COLUMN "public"."orders"."card_subtotal" IS 'Subtotal if entire order paid by card';



COMMENT ON COLUMN "public"."orders"."cash_subtotal" IS 'Subtotal if entire order paid by cash (with discount)';



COMMENT ON COLUMN "public"."orders"."effective_total" IS 'Actual final total after all payments applied';



COMMENT ON COLUMN "public"."orders"."session_id" IS 'Bidirectional link to table session for dine-in orders. Allows O(1) lookup of which table/session an order belongs to. NULL for takeout/delivery orders.';



COMMENT ON COLUMN "public"."orders"."order_source" IS 'Origin of the order. pos = in-house POS, orderout = delivery platform via OrderOut, online_store = branded online ordering, phone = phone-in order.';



COMMENT ON COLUMN "public"."orders"."delivery_platform" IS 'Delivery platform name: UberEats, DoorDash, Grubhub, etc. NULL for non-delivery orders.';



COMMENT ON COLUMN "public"."orders"."platform_order_number" IS 'External platform order number for display on receipts and KDS. Different from our internal order_number.';



COMMENT ON COLUMN "public"."orders"."estimated_ready_at" IS 'When the delivery platform expects the order ready. Drives KDS countdown timers and urgency colors.';



COMMENT ON COLUMN "public"."orders"."is_prepaid" IS 'When true, customer already paid through the delivery platform. No payment processing needed on POS.';



COMMENT ON COLUMN "public"."orders"."split_payment_path" IS 'Locks split method after first partial split payment';



