CREATE OR REPLACE VIEW "public"."admin_merchant_summary" AS
 SELECT "m"."id",
    "m"."name",
    "m"."clerk_org_id",
    "m"."type",
    "m"."created_at",
    "m"."updated_at",
    "m"."public_metadata",
    "org"."imageURL" AS "logo_url",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."locations" "l"
          WHERE ("l"."merchant_id" = "m"."id")) AS "total_locations",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."locations" "l"
          WHERE (("l"."merchant_id" = "m"."id") AND ("l"."is_active" = true))) AS "active_locations",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."staff_profiles" "sp"
          WHERE (("sp"."merchant_id" = "m"."id") AND ("sp"."is_active" = true))) AS "active_staff_count",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."orders" "o"
          WHERE (("o"."merchant_id" = "m"."id") AND ("o"."created_at" >= CURRENT_DATE) AND ("o"."status" <> ALL (ARRAY['cancelled'::"public"."order_status", 'draft'::"public"."order_status"])))) AS "orders_today",
    ( SELECT COALESCE("sum"("o"."total_amount"), (0)::numeric) AS "coalesce"
           FROM "public"."orders" "o"
          WHERE (("o"."merchant_id" = "m"."id") AND ("o"."created_at" >= CURRENT_DATE) AND ("o"."status" = 'completed'::"public"."order_status"))) AS "revenue_today",
    ( SELECT "max"("o"."created_at") AS "max"
           FROM "public"."orders" "o"
          WHERE ("o"."merchant_id" = "m"."id")) AS "last_order_at",
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM "public"."locations" "l"
              WHERE (("l"."merchant_id" = "m"."id") AND ("l"."is_active" = true))))) THEN 'onboarding'::"text"
            WHEN (( SELECT "max"("o"."created_at") AS "max"
               FROM "public"."orders" "o"
              WHERE ("o"."merchant_id" = "m"."id")) IS NULL) THEN 'onboarding'::"text"
            WHEN (( SELECT "max"("o"."created_at") AS "max"
               FROM "public"."orders" "o"
              WHERE ("o"."merchant_id" = "m"."id")) < ("now"() - '7 days'::interval)) THEN 'inactive'::"text"
            ELSE 'active'::"text"
        END AS "derived_status"
   FROM ("public"."merchants" "m"
     LEFT JOIN "public"."organizations" "org" ON (("m"."clerk_org_id" = "org"."id")));


ALTER VIEW "public"."admin_merchant_summary" OWNER TO "postgres";


