CREATE OR REPLACE VIEW "public"."customer_profile_summary" AS
 SELECT "c"."id",
    "c"."merchant_id",
    "c"."name",
    "c"."phone",
    "c"."email",
    "c"."address",
    "c"."birthday",
    "c"."anniversary",
    "c"."dietary_preferences",
    "c"."allergy_notes",
    "c"."preferred_server_id",
    "c"."preferred_table",
    "c"."preferred_seating",
    "c"."company_name",
    "c"."vip_level",
    "c"."tags",
    "c"."sms_opt_in",
    "c"."email_opt_in",
    "c"."receipt_via_sms",
    "c"."receipt_via_email",
    "c"."preferred_language",
    "c"."created_at",
    "c"."updated_at",
    ("count"("cn"."id"))::integer AS "notes_count"
   FROM ("public"."customers" "c"
     LEFT JOIN "public"."customer_notes" "cn" ON (("c"."id" = "cn"."customer_id")))
  GROUP BY "c"."id", "c"."merchant_id", "c"."name", "c"."phone", "c"."email", "c"."address", "c"."birthday", "c"."anniversary", "c"."dietary_preferences", "c"."allergy_notes", "c"."preferred_server_id", "c"."preferred_table", "c"."preferred_seating", "c"."company_name", "c"."vip_level", "c"."tags", "c"."sms_opt_in", "c"."email_opt_in", "c"."receipt_via_sms", "c"."receipt_via_email", "c"."preferred_language", "c"."created_at", "c"."updated_at";


