    "order_id" "uuid" NOT NULL,
    "menu_item_id" "uuid",
    "location_exclusive_item_id" "uuid",
    "item_name" "text" NOT NULL,
    "item_description" "text",
    "category_name" "text",
    "quantity" integer DEFAULT 1 NOT NULL,
    "unit_price" numeric(10,2) NOT NULL,
    "cash_price" numeric(10,2),
    "subtotal" numeric(10,2) NOT NULL,
    "selected_size_id" "uuid",
    "selected_size_name" "text",
    "size_price_modifier" numeric(10,2) DEFAULT 0.00,
    "item_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "is_voided" boolean DEFAULT false,
    "void_reason" "text",
    "voided_at" timestamp with time zone,
    "voided_by" "uuid",
    "course_number" integer,
    "fire_time" timestamp with time zone,
    "rush" boolean DEFAULT false,
    "special_instructions" "text",
    "kitchen_notes" "text",
    "prep_station" "text",
    "assigned_to_staff_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sent_to_kitchen_at" timestamp with time zone,
    "started_preparing_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "display_order" integer DEFAULT 0,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "is_tax_exempt" boolean DEFAULT false,
    "discount_id" "uuid",
    "discount_name" "text",
    "discount_type" "public"."discount_type",
    "discount_value" numeric DEFAULT 0,
    "discount_amount" numeric DEFAULT 0,
    "discount_source" "public"."discount_source",
    "discount_reason" "text",
    "discount_applied_by" "uuid",
    "discount_approved_by" "uuid",
    "pre_discount_subtotal" numeric,
    "is_open_item" boolean DEFAULT false,
    "open_item_name" "text",
    "open_item_description" "text",
    "tax_rate" numeric DEFAULT 0,
    "tax_amount" numeric DEFAULT 0,
    "cash_unit_price" numeric,
    "cash_subtotal" numeric DEFAULT 0,
    "cash_tax_amount" numeric DEFAULT 0,
    "paid_quantity" integer DEFAULT 0,
    "payment_id" "uuid",
    "price_paid" numeric DEFAULT '0'::numeric,
    "open_item_price" numeric(10,2),
    "discount_cash_amount" numeric,
    "kitchen_status" "text" DEFAULT 'new'::"text",
    "base_card_price" numeric,
    "base_cash_price" numeric,
    "refunded_quantity" integer DEFAULT 0,
    "refunded_amount" numeric DEFAULT 0,
    "menu_id" "uuid",
    "menu_name" "text",
    "category_id" "uuid",
    "is_prioritized" boolean DEFAULT false,
    "seat_number" integer,
    CONSTRAINT "check_open_item_fields" CHECK (((("is_open_item" = false) AND ("open_item_name" IS NULL) AND ("open_item_price" IS NULL)) OR (("is_open_item" = true) AND ("open_item_name" IS NOT NULL) AND ("open_item_price" IS NOT NULL)))),
    CONSTRAINT "order_items_kitchen_status_check" CHECK (("kitchen_status" = ANY (ARRAY['new'::"text", 'sent'::"text", 'preparing'::"text", 'ready'::"text", 'served'::"text"]))),
    CONSTRAINT "positive_quantity" CHECK (("quantity" > 0))
);


ALTER TABLE "public"."order_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."order_items" IS 'Individual items within an order with support for sizing, modifiers, and coursing';



COMMENT ON COLUMN "public"."order_items"."discount_amount" IS 'Calculated discount in dollars';



COMMENT ON COLUMN "public"."order_items"."is_open_item" IS 'True if this is a custom-priced item';



