);


ALTER TABLE "public"."order_payment_items" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."order_payments" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "order_id" "uuid" NOT NULL,
    "payment_method" "public"."payment_method" NOT NULL,
    "amount" numeric(10,2) NOT NULL,
    "tip_amount" numeric(10,2) DEFAULT 0.00 NOT NULL,
    "total_amount" numeric(10,2) NOT NULL,
    "status" "public"."payment_status" DEFAULT 'pending'::"public"."payment_status" NOT NULL,
    "terminal_type" "public"."terminal_type" NOT NULL,
    "terminal_id" "text",
    "device_id" "text",
    "transaction_id" "text",
    "authorization_code" "text",
    "reference_number" "text",
    "card_type" "text",
    "card_last_four" "text",
    "card_exp_month" integer,
    "card_exp_year" integer,
    "card_token" "text",
    "dejavoo_transaction_type" "text",
    "dejavoo_response_code" "text",
    "dejavoo_response_message" "text",
    "dejavoo_batch_number" "text",
    "dejavoo_invoice_number" "text",
    "dvpaylite_request_id" "text",
    "dvpaylite_application_type" "text",
    "processor_name" "text",
    "processor_response" "jsonb",
    "gateway_fee" numeric(10,2),
    "cash_discount_applied" boolean DEFAULT false,
    "original_amount" numeric(10,2),
    "refunded_amount" numeric(10,2) DEFAULT 0.00,
    "refund_reason" "text",
    "refunded_at" timestamp with time zone,
    "refunded_by" "uuid",
    "parent_payment_id" "uuid",
    "initiated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "authorized_at" timestamp with time zone,
    "captured_at" timestamp with time zone,
    "failed_at" timestamp with time zone,
    "voided_at" timestamp with time zone,
    "processed_by_staff_id" "uuid",
    "processed_by_user_id" "text",
    "error_code" "text",
    "error_message" "text",
    "retry_count" integer DEFAULT 0,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "amount_tendered" numeric(10,2),
    "change_given" numeric(10,2) DEFAULT 0,
    "is_voided" boolean DEFAULT false,
    "voided_by" "uuid",
    "void_reason" "text",
    "subtotal_portion" numeric DEFAULT 0.00,
    "tax_portion" numeric DEFAULT 0.00,
    "discount_portion" numeric DEFAULT 0.00,
    "is_cash_priced" boolean DEFAULT false,
    "covers_items" "uuid"[] DEFAULT '{}'::"uuid"[],
    "split_portion_index" integer,
    "split_count" integer,
    "auth_code" character varying(10),
    "rrn" character varying(50),
    "result_code" character varying(10),
    "result_message" "text",
    "batch_number" "text",
    "is_settled" boolean DEFAULT false,
    "settled_at" timestamp with time zone,
    "is_returned" boolean DEFAULT false,
    "returned_at" timestamp with time zone,
    "returned_by" "uuid",
    "return_reason" character varying(100),
    "return_number" character varying(20),
    "return_reference_id" character varying(50),
    "return_amount" numeric(10,2),
    "return_auth_code" character varying(10),
    "return_rrn" character varying(50),
    "tip_adjusted_at" timestamp with time zone,
    "tip_adjusted_by" "uuid",
    "original_tip_amount" numeric(10,2),
    "split_index" integer,
    "split_total" integer,
    "terminal_request" "jsonb",
    "terminal_response" "jsonb",
    "emv_data" "jsonb",
    "approved_at" timestamp with time zone,
    "merchant_id" "uuid",
    "location_id" "uuid",
    "initiated_by" "uuid",
    CONSTRAINT "positive_payment_amounts" CHECK ((("amount" >= (0)::numeric) AND ("tip_amount" >= (0)::numeric) AND ("total_amount" >= (0)::numeric) AND ("refunded_amount" >= (0)::numeric))),
    CONSTRAINT "valid_card_exp" CHECK (((("card_exp_month" IS NULL) AND ("card_exp_year" IS NULL)) OR ((("card_exp_month" >= 1) AND ("card_exp_month" <= 12)) AND (("card_exp_year")::numeric >= EXTRACT(year FROM CURRENT_DATE))))),
    CONSTRAINT "valid_change_given" CHECK ((("change_given" >= (0)::numeric) AND ((("payment_method" <> 'cash'::"public"."payment_method") AND ("change_given" = (0)::numeric)) OR ("payment_method" = 'cash'::"public"."payment_method"))))
);


ALTER TABLE "public"."order_payments" OWNER TO "postgres";


COMMENT ON TABLE "public"."order_payments" IS 'Payment records supporting cash, SPINAPI, DVPaylite, and other payment methods';



COMMENT ON COLUMN "public"."order_payments"."terminal_type" IS 'Type of terminal used: dejavoo_spinapi (external), dejavoo_p18 (native DVPaylite), manual, or none';



COMMENT ON COLUMN "public"."order_payments"."transaction_id" IS 'Unique transaction ID from payment processor/gateway';



COMMENT ON COLUMN "public"."order_payments"."amount_tendered" IS 'For cash payments: the amount customer physically handed over (e.g., $25 for a $21 order)';



COMMENT ON COLUMN "public"."order_payments"."change_given" IS 'For cash payments: the change returned to customer (e.g., $4 if they gave $25 for $21)';



COMMENT ON COLUMN "public"."order_payments"."subtotal_portion" IS 'Portion of order subtotal covered by this payment';



COMMENT ON COLUMN "public"."order_payments"."tax_portion" IS 'Tax amount allocated to this payment';



COMMENT ON COLUMN "public"."order_payments"."is_cash_priced" IS 'Whether this payment used cash pricing';



