    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "chk_oo_orders_accept_status" CHECK (("accept_status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'rejected'::"text"]))),
