CREATE OR REPLACE VIEW "public"."v_cash_drawer_summary" AS
 SELECT "date"("op"."initiated_at") AS "business_date",
    "o"."location_id",
    "count"(*) AS "cash_transactions",
    "sum"(("op"."amount" + "op"."tip_amount")) AS "total_cash_received",
    "sum"("op"."amount_tendered") AS "total_tendered",
    "sum"("op"."change_given") AS "total_change_given",
    "sum"("op"."tip_amount") AS "total_cash_tips",
    "sum"(("op"."amount_tendered" - "op"."change_given")) AS "net_cash_in_drawer"
   FROM ("public"."order_payments" "op"
     JOIN "public"."orders" "o" ON (("o"."id" = "op"."order_id")))
  WHERE (("op"."payment_method" = 'cash'::"public"."payment_method") AND ("op"."status" = 'captured'::"public"."payment_status"))
  GROUP BY ("date"("op"."initiated_at")), "o"."location_id";


ALTER VIEW "public"."v_cash_drawer_summary" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_cash_drawer_summary" IS 'Daily cash drawer summary by location for reconciliation';



CREATE OR REPLACE VIEW "public"."v_eod_cash_summary" AS
 SELECT "s"."cash_drawer_id",
    "d"."name" AS "drawer_name",
    "d"."location_id",
    "s"."opened_by",
    "s"."closed_by",
    "s"."opening_amount",
    "s"."closing_amount",
    "s"."expected_cash",
    "s"."variance",
        CASE
            WHEN ("s"."variance" IS NULL) THEN 'pending'::"text"
            WHEN ("s"."variance" = (0)::numeric) THEN 'balanced'::"text"
            WHEN ("abs"("s"."variance") <= 1.00) THEN 'acceptable'::"text"
            ELSE 'discrepancy'::"text"
        END AS "variance_status",
    (("s"."opened_at" AT TIME ZONE 'UTC'::"text"))::"date" AS "business_date",
    COALESCE("sum"(
        CASE
            WHEN (("o"."operation_type")::"text" = 'cash_sale'::"text") THEN "o"."amount"
            ELSE (0)::numeric
        END), (0)::numeric) AS "total_cash_sales",
    COALESCE("sum"(
        CASE
            WHEN (("o"."operation_type")::"text" = 'cash_refund'::"text") THEN "o"."amount"
            ELSE (0)::numeric
        END), (0)::numeric) AS "total_cash_refunds",
    COALESCE("sum"(
        CASE
            WHEN (("o"."operation_type")::"text" = 'pay_in'::"text") THEN "o"."amount"
            ELSE (0)::numeric
        END), (0)::numeric) AS "total_pay_ins",
    COALESCE("sum"(
        CASE
            WHEN (("o"."operation_type")::"text" = 'pay_out'::"text") THEN "o"."amount"
            ELSE (0)::numeric
        END), (0)::numeric) AS "total_pay_outs",
    COALESCE("sum"(
        CASE
            WHEN (("o"."operation_type")::"text" = 'cash_drop'::"text") THEN "o"."amount"
            ELSE (0)::numeric
        END), (0)::numeric) AS "total_cash_drops",
    COALESCE("count"(
        CASE
            WHEN (("o"."operation_type")::"text" = 'no_sale'::"text") THEN 1
            ELSE NULL::integer
        END), (0)::bigint) AS "no_sale_count"
   FROM (("public"."cash_drawer_sessions" "s"
     JOIN "public"."cash_drawers" "d" ON (("d"."id" = "s"."cash_drawer_id")))
     LEFT JOIN "public"."cash_drawer_operations" "o" ON (("o"."session_id" = "s"."id")))
  GROUP BY "s"."id", "s"."cash_drawer_id", "d"."name", "d"."location_id", "s"."opened_by", "s"."closed_by", "s"."opening_amount", "s"."closing_amount", "s"."expected_cash", "s"."variance", "s"."opened_at";


ALTER VIEW "public"."v_eod_cash_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_location_menu_items" AS
 SELECT "m"."id" AS "menu_id",
    "m"."merchant_id",
    "m"."name" AS "menu_name",
    "mim"."id" AS "menu_item_menu_id",
    "mim"."display_order",
    "mi"."id" AS "menu_item_id",
    "mi"."name" AS "item_name",
    "mi"."description",
    "mi"."image",
    "mi"."meal_types",
    "mi"."allergens",
    "mi"."card_bg_color",
    "mi"."price" AS "base_price",
    "mi"."cash_price" AS "base_cash_price",
    "mim"."custom_price" AS "menu_price",
    "mim"."custom_cash_price" AS "menu_cash_price",
    "mim"."is_available" AS "menu_available",
    "l"."id" AS "location_id",
    "l"."name" AS "location_name",
    "lmio"."custom_price" AS "location_price",
    "lmio"."custom_cash_price" AS "location_cash_price",
    "lmio"."is_available" AS "location_available",
    "lmio"."stock_tracking_mode" AS "location_stock_mode",
    COALESCE("lmio"."custom_price", "mim"."custom_price", "mi"."price") AS "effective_price",
    COALESCE("lmio"."custom_cash_price", "mim"."custom_cash_price", "mi"."cash_price") AS "effective_cash_price",
    COALESCE("lmio"."is_available", "mim"."is_available", "mi"."availability") AS "effective_available",
    COALESCE("lmio"."stock_tracking_mode", "mi"."stock_tracking_mode") AS "effective_stock_mode",
    ("lmio"."id" IS NOT NULL) AS "has_location_override"
   FROM (((("public"."menus" "m"
     JOIN "public"."menu_item_menus" "mim" ON (("mim"."menu_id" = "m"."id")))
     JOIN "public"."menu_items" "mi" ON (("mi"."id" = "mim"."menu_item_id")))
     CROSS JOIN "public"."locations" "l")
     LEFT JOIN "public"."location_menu_item_overrides" "lmio" ON ((("lmio"."menu_item_id" = "mi"."id") AND ("lmio"."location_id" = "l"."id"))))
  WHERE ("l"."merchant_id" = "m"."merchant_id");


ALTER VIEW "public"."v_location_menu_items" OWNER TO "postgres";


