CREATE TABLE IF NOT EXISTS "public"."waste_logs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "merchant_id" "uuid" NOT NULL,
    "location_id" "uuid" NOT NULL,
    "inventory_item_id" "uuid" NOT NULL,
    "quantity" numeric NOT NULL,
    "reason" "text" NOT NULL,
    "notes" "text",
    "waste_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "estimated_cost" numeric DEFAULT 0,
    "logged_by_user_id" "text",
    "logged_by_name" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "waste_logs_quantity_check" CHECK (("quantity" > (0)::numeric)),
    CONSTRAINT "waste_logs_reason_check" CHECK (("reason" = ANY (ARRAY['spoilage'::"text", 'overproduction'::"text", 'spill'::"text", 'theft'::"text", 'damaged'::"text", 'expired'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."waste_logs" OWNER TO "postgres";


COMMENT ON TABLE "public"."waste_logs" IS 'Records inventory waste events (spoilage, spill, theft, etc.). Drives Actual vs Theoretical food cost and shrinkage reports.';



CREATE TABLE IF NOT EXISTS "public"."webhook_dead_letter_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source" "text" DEFAULT 'orderout'::"text" NOT NULL,
    "event_type" "text",
    "raw_payload" "jsonb" NOT NULL,
    "error_message" "text",
    "retry_count" integer DEFAULT 0 NOT NULL,
    "max_retries" integer DEFAULT 5 NOT NULL,
    "next_retry_at" timestamp with time zone,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "resolved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "chk_dlq_status" CHECK (("status" = ANY (ARRAY['pending'::"text", 'retrying'::"text", 'resolved'::"text", 'abandoned'::"text"])))
);


ALTER TABLE "public"."webhook_dead_letter_queue" OWNER TO "postgres";


COMMENT ON TABLE "public"."webhook_dead_letter_queue" IS 'Stores failed webhook payloads for retry. Ensures no delivery orders are lost.';



