CREATE OR REPLACE VIEW "public"."location_summary" AS
 SELECT "l"."id",
    "l"."merchant_id",
    "l"."name",
    "l"."code",
    "l"."city",
    "l"."state",
    "l"."is_active",
    "l"."is_accepting_orders",
    "l"."timezone",
    "l"."created_at",
    "count"(DISTINCT "lm"."user_id") FILTER (WHERE ("lm"."is_active" = true)) AS "active_staff_count",
    "count"(DISTINCT "lm"."user_id") FILTER (WHERE (("lm"."is_active" = true) AND ("r"."level_type" = 'manager'::"text"))) AS "manager_count"
   FROM (("public"."locations" "l"
     LEFT JOIN "public"."location_members" "lm" ON (("lm"."location_id" = "l"."id")))
     LEFT JOIN "public"."roles" "r" ON (("r"."code" = "lm"."role_code")))
  GROUP BY "l"."id";



