CREATE POLICY "Merchants can view own daily stats" ON "analytics"."location_daily_stats" FOR SELECT USING (("merchant_id" IN ( SELECT DISTINCT "l"."merchant_id"
   FROM ("public"."locations" "l"
     JOIN "public"."location_members" "lm" ON (("lm"."location_id" = "l"."id")))
  WHERE (("lm"."user_id" = ("auth"."uid"())::"text") AND ("lm"."is_active" = true)))));



CREATE POLICY "Merchants can view own hourly stats" ON "analytics"."location_hourly_stats" FOR SELECT USING (("merchant_id" IN ( SELECT DISTINCT "l"."merchant_id"
   FROM ("public"."locations" "l"
     JOIN "public"."location_members" "lm" ON (("lm"."location_id" = "l"."id")))
  WHERE (("lm"."user_id" = ("auth"."uid"())::"text") AND ("lm"."is_active" = true)))));



CREATE POLICY "Users can create own saved views" ON "analytics"."saved_comparison_views" FOR INSERT WITH CHECK ((("created_by_user_id" = ("auth"."uid"())::"text") AND ("merchant_id" IN ( SELECT DISTINCT "l"."merchant_id"
   FROM ("public"."locations" "l"
     JOIN "public"."location_members" "lm" ON (("lm"."location_id" = "l"."id")))
  WHERE (("lm"."user_id" = ("auth"."uid"())::"text") AND ("lm"."is_active" = true))))));



CREATE POLICY "Users can delete own saved views" ON "analytics"."saved_comparison_views" FOR DELETE USING (("created_by_user_id" = ("auth"."uid"())::"text"));



CREATE POLICY "Users can update own saved views" ON "analytics"."saved_comparison_views" FOR UPDATE USING (("created_by_user_id" = ("auth"."uid"())::"text"));



CREATE POLICY "Users can view own saved views" ON "analytics"."saved_comparison_views" FOR SELECT USING ((("created_by_user_id" = ("auth"."uid"())::"text") OR (("is_shared" = true) AND ("merchant_id" IN ( SELECT DISTINCT "l"."merchant_id"
   FROM ("public"."locations" "l"
     JOIN "public"."location_members" "lm" ON (("lm"."location_id" = "l"."id")))
  WHERE (("lm"."user_id" = ("auth"."uid"())::"text") AND ("lm"."is_active" = true)))))));



ALTER TABLE "analytics"."location_daily_stats" ENABLE ROW LEVEL SECURITY;


ALTER TABLE "analytics"."location_hourly_stats" ENABLE ROW LEVEL SECURITY;


ALTER TABLE "analytics"."saved_comparison_views" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "Admin Can manage categories" ON "public"."menu_categories" USING ("public"."is_merchant_admin"("merchant_id")) WITH CHECK ("public"."is_merchant_admin"("merchant_id"));



CREATE POLICY "Allow auth user to update menu_schedules" ON "public"."menu_schedules" FOR UPDATE USING ("public"."is_merchant_admin"("merchant_id"));



CREATE POLICY "Allow authenticated users to delete CFD ordering panel images" ON "public"."cfd_ordering_panel_images" FOR DELETE TO "authenticated" USING (true);



CREATE POLICY "Allow authenticated users to insert CFD ordering panel images" ON "public"."cfd_ordering_panel_images" FOR INSERT TO "authenticated" WITH CHECK (true);



CREATE POLICY "Allow authenticated users to read CFD ordering panel images" ON "public"."cfd_ordering_panel_images" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "Allow authenticated users to update CFD ordering panel images" ON "public"."cfd_ordering_panel_images" FOR UPDATE TO "authenticated" USING (true) WITH CHECK (true);



CREATE POLICY "Allow insert for auth merchants" ON "public"."menu_categories" FOR INSERT TO "authenticated" WITH CHECK ("public"."is_merchant_admin"("merchant_id"));



CREATE POLICY "Allow insert kick notifications" ON "public"."session_kick_notifications" FOR INSERT WITH CHECK (true);



CREATE POLICY "Anyone can create order sessions" ON "public"."online_order_sessions" FOR INSERT WITH CHECK (true);



CREATE POLICY "Anyone can view kick notifications" ON "public"."session_kick_notifications" FOR SELECT USING (true);



CREATE POLICY "Auth Merchants can interact" ON "public"."modifier_group_items" USING ("public"."is_merchant_admin"("merchant_id")) WITH CHECK ("public"."is_merchant_admin"("merchant_id"));



CREATE POLICY "Can update status" ON "public"."orderout_menu_syncs" FOR UPDATE USING ((EXISTS ( SELECT 1
   FROM "public"."orderout_restaurants" "orr"
  WHERE (("orr"."id" = "orderout_menu_syncs"."orderout_restaurant_id") AND "public"."is_merchant_admin"("orr"."merchant_id"))))) WITH CHECK ((EXISTS ( SELECT 1
