CREATE POLICY "vendors_insert" ON "public"."vendors" FOR INSERT WITH CHECK ("public"."is_merchant_admin"("merchant_id"));



CREATE POLICY "vendors_select" ON "public"."vendors" FOR SELECT USING (("public"."is_merchant_admin"("merchant_id") OR (EXISTS ( SELECT 1
   FROM ("public"."location_members" "lm"
     JOIN "public"."locations" "l" ON (("l"."id" = "lm"."location_id")))
  WHERE (("lm"."user_id" = "public"."current_user_id"()) AND ("lm"."is_active" = true) AND ("l"."merchant_id" = "vendors"."merchant_id"))))));



CREATE POLICY "vendors_update" ON "public"."vendors" FOR UPDATE USING ("public"."is_merchant_admin"("merchant_id"));



