CREATE POLICY "waste_logs_insert" ON "public"."waste_logs" FOR INSERT WITH CHECK ("public"."is_merchant_admin"("merchant_id"));



CREATE POLICY "waste_logs_select" ON "public"."waste_logs" FOR SELECT USING (("public"."is_merchant_admin"("merchant_id") OR "public"."is_location_member"("location_id")));



